	private static final java.util.regex.Pattern KILL_COUNT_RE = java.util.regex.Pattern.compile(
		"(?:kill|completion|chest|success|harvest) count is:? ?([\\d,]+)", java.util.regex.Pattern.CASE_INSENSITIVE);
	/**
	 * Structured source of a count line: "Your [completion count for |subdued |completed ]<source>
	 * [kill|harvest|completion|success|Total Ticket ][count ]is: N". The shape follows the parser in the
	 * BSD-2-Clause plugin "Collection Log Popup Enhanced" (Copyright (c) 2026, SnakeSteak), written
	 * independently here; only the line shape is shared. The colour markup is stripped first, both forms.
	 */
	static final java.util.regex.Pattern KC_SOURCE_RE = java.util.regex.Pattern.compile(
		"Your (completion count for |subdued |completed )?(.+?) ((?:kill|harvest|completion|success|Total Ticket) )?(?:count )?is: ?([0-9,]+)",
		java.util.regex.Pattern.CASE_INSENSITIVE);
	static final java.util.regex.Pattern CHAT_MARKUP_RE = java.util.regex.Pattern.compile("<[^<>]*>|@[a-zA-Z0-9_]+@");

	/** {source, kind, count} for a count line, or null. kind is the verb ("kill", "completion", ...) or "count". */
	static Map<String, Object> parseKillCount(String text)
	{
		if (text == null)
		{
			return null;
		}
		String clean = CHAT_MARKUP_RE.matcher(text).replaceAll("");
		java.util.regex.Matcher m = KC_SOURCE_RE.matcher(clean);
		if (!m.find())
		{
			return null;
		}
		long count;
		try
		{
			count = Long.parseLong(m.group(4).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
		String source = m.group(2).trim();
		if (source.toLowerCase(java.util.Locale.ROOT).startsWith("the "))
		{
			source = source.substring(4);
		}
		String kind = m.group(3) != null ? m.group(3).trim().toLowerCase(java.util.Locale.ROOT)
			: m.group(1) != null ? m.group(1).trim().toLowerCase(java.util.Locale.ROOT) : "count";
		Map<String, Object> out = new LinkedHashMap<>();
		out.put("source", source);
		out.put("kind", kind);
		out.put("count", count);
		return out;
	}

	/**
	 * Emit the two structured milestones parsed from a system chat line: kill_count and pet.
	 *
	 * Own-account only. A system line names no other player, so nothing here captures a bystander.
	 * The raw line rides along as `text` because the count alone does not say WHAT was killed.
	 */
	void emitParsedMilestones(String text)
	{
		if (text == null || text.isEmpty() || !activityLogActive())
		{
			return;
		}
		java.util.regex.Matcher m = KILL_COUNT_RE.matcher(text);
		if (m.find())
		{
			Map<String, Object> f = new LinkedHashMap<>();
			f.put("text", text);
			try
			{
				f.put("count", Long.parseLong(m.group(1).replace(",", "")));
			}
			catch (NumberFormatException ignored)
			{
				// leave count off when it does not parse; the text still carries the milestone
			}
			Map<String, Object> parsed = parseKillCount(text);
			if (parsed != null)
			{
				f.put("source", parsed.get("source"));	// structured boss / activity name; text kept as the raw line
				f.put("kind", parsed.get("kind"));
			}
			emitEvent("kill_count", f);
		}
		String low = text.toLowerCase(java.util.Locale.ROOT);
		if (low.contains("funny feeling like you") && low.contains("followed"))
		{
			Map<String, Object> f = new LinkedHashMap<>();
			f.put("text", text);
			emitEvent("pet", f);
		}
	}

	/**
	 * On "Accepted trade.", emit a structured "trade" event from what was captured at the confirm screen:
	 * the items WE gave and received. PublicTransport removes legacy partner/context/text fields
	 * before either memory or disk enqueue, and again before transmission of old queued rows.
	 */
	void putWorldContext(Map<String, Object> fields)
	{
		if (fields == null || client == null)
		{
			return;
		}
		int world = client.getWorld();
		if (world > 0)
		{
			fields.put("world", world);
		}
		java.util.Set<WorldType> types = client.getWorldType();
		if (types != null)
		{
			fields.put("world_members", types.contains(WorldType.MEMBERS));
		}
	}

	void emitTradeEvent()
	{
		List<Map<String, Object>> given = pendingTradeGiven;
		String counterparty = pendingCounterparty;
		Integer counterpartyCombatLevel = pendingCounterpartyCombatLevel;
		List<Map<String, Object>> received = pendingTradeReceived;
		String receivedText = pendingReceivedText;
		pendingTradeGiven = null;
		pendingCounterparty = null;
		pendingCounterpartyCombatLevel = null;
		pendingTradeReceived = null;
		pendingReceivedText = null;
		if (given == null)
		{
			return;
		}
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("given", given);
		// Legacy operational context. PublicTransport excludes it from both queues and the wire.
		if (counterparty != null)
		{
			fields.put("counterparty", counterparty);
		}
		if (counterpartyCombatLevel != null)
		{
			fields.put("counterparty_combat_level", counterpartyCombatLevel);
		}
		putWorldContext(fields);
		// WAVE 1b: the received side. Always carry received[] (may be empty if the widget was text-only or not
		// yet populated); attach received_text only when the structured read came back empty and text was found.
		fields.put("received", received == null ? new ArrayList<>() : received);
		if (receivedText != null && !receivedText.isEmpty())
		{
			fields.put("received_text", receivedText);
		}
		// Staff Wilderness trades only: who the client had loaded at "Accepted trade.". Sampled here, not at
		// the confirm screen: players stay loaded at acceptance, and moving would have closed the trade.
		// Presence only: `counterparty` above is the trade partner, these rows never change it.
		attachSurroundingSnapshot(fields, "surrounding_at_trade");
		emitEvent("trade", fields);
	}

	/** General-store buy/sell: a Buy/Sell menu click while the shop (SHOPMAIN 300) is open. Own-account. */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (gameplayReady()) ownGameplay.consumption.menu(client, event);
		if (progressReady()) accountProgress.storageRecovery.menu(client, event, System.currentTimeMillis());
		if (maxCapture() && event != null)
		{
			Map<String, Object> d = new LinkedHashMap<>();
			d.put("opt", event.getMenuOption());
			d.put("target", Text.removeTags(event.getMenuTarget() == null ? "" : event.getMenuTarget()));
			firehose("menu", d);
		}
		// Delivery-proof tx flag — hoisted ABOVE the activity-log gate (grill F5): a clip's buy/sell must
		// not be dropped just because activity logging is off. Only relevant while a clip is capturing.
		if (clipCapturing && shopOpen && isStoreBuyOrSell(event))
		{
			storeTxThisVisit = true;
			markStoreClipMoment();
		}
		// Off-book value events (drop / pickup / alch): own gate (not shop-scoped) — arm an inventory-delta
		// pending resolved on the next INVENTORY change. BEFORE the store gate so the shop-open early-return
		// below never swallows it.
		maybeArmInvDeltaPending(event);
		if (!shopOpen || !activityLogActive())
		{
			return;
		}
		String type = storeTxType(event);
		if (type == null)
		{
			return;
		}
		lastOwnStoreClickMs = nowMs();	// the shop changes that follow our own click never support the cycle phase
		if ("store_buy".equals(type))
		{
			// OUR OWN BUY-BACK. The seller's own procedure has an explicit emergency step — if the
			// buyer cannot take the item in time, buy it back — so our own buy of an item we just
			// sold is a NORMAL part of the method, not a customer taking it. Without this the fall
			// that our own purchase causes is reported as a counterparty: measured on live events
			// 3914798/3914799, where a buy-back and a store_taken landed in the SAME SECOND and the
			// plugin still named a candidate. Record the item so handleShopStockChanged can suppress
			// the inference.
			lastSelfBuyItem = event.getItemId();
			lastSelfBuyAtMs = System.currentTimeMillis();
		}
		int item = event.getItemId();
		if (item <= 0)
		{
			return;	// no resolvable item id — same guard the off-book path uses; skip rather than emit -1
		}
		String opt = event.getMenuOption();	// non-null here: storeTxType only matches a "Buy"/"Sell" prefix
		// WAVE 6 (store price): don't emit here — arm a pending and let the next INVENTORY change resolve the
		// exact transacted gp from the coin-count delta (store-price-feasibility.md option B). Snapshot coins
		// BEFORE the transaction. Last-click-wins: a second click on the same tick marks the pending ambiguous
		// (its delta would merge two txns), so the resolver omits gp_total rather than misattribute it.
		ItemContainer invNow = client == null ? null : client.getItemContainer(InventoryID.INVENTORY);
		long coinsBefore = countItem(invNow, COINS_ID);
		long itemBefore = invNow == null ? UNKNOWN_ITEM_COUNT : countItem(invNow, item);
		int tick = client == null ? 0 : client.getTickCount();
		int qty = parseTrailingQty(opt);
		// Snapshot who is standing here AT THE CLICK. The visit-wide accumulator answers a weaker
		// question ("who was around at some point"); a dispute is about the moment value moved.
		nearbyAtTx = nearbyPlayersSnapshot(NEARBY_FIELD_CAP);
		if ("store_sell".equals(type))
		{
			// Default stock is judged ONCE, at our FIRST sell of this item this visit: after that the shop
			// stock includes units we put in ourselves, which must never make our delivery look native.
			if (soldThisVisit.add(item) && shopStock.getOrDefault(item, 0) > 0)
			{
				defaultStockSoldThisVisit.add(item);	// the shop already stocked it before we sold: default stock
			}
			lastSellTickThisVisit.put(item, tick);
			if (storeProbeItem == 0)
			{
				// FIRST sell of the visit = the junk probe. Only its disappearance moves the reset
				// clock; everything after it is merchandise whose disappearance means a customer.
				storeProbeItem = item;
			}
		}
		storePendings.values().removeIf(p -> tick - p.tick > STORE_PENDING_MAX_TICKS);	// failed clicks
		// Removed and put back so a repeat click moves the item to the end: click order is emit order.
		StorePending prev = storePendings.remove(item);
		storePendings.put(item, mergeStorePending(prev, type, item, qty, coinsBefore, itemBefore, tick));
	}

	/**
	 * Fold a new store click into any pending one still inside the resolution window.
	 *
	 * <p>Production evidence (2026-08-15 audit): on the newest clients, {@code gp_total} was missing from
	 * <b>37.1% of multi-quantity store buys</b> (140 of 377 on 2026-08-15) against 8.0% at qty=1. Cause:
	 * a player spam-clicking "Buy 10" lands two clicks in quick succession, which the previous code
	 * flagged {@code ambiguous} and then dropped the gold for — deliberately, "rather than misattribute
	 * it". General-store selling is how gold is delivered, so that was the delivery path going dark.
	 *
	 * <p>The flag was over-cautious for the common case. If {@code prev} is still armed then it was never
	 * resolved, and a pending is only consumed by an inventory change — so no inventory change has
	 * happened yet, so {@code prev.coinsBefore} still predates BOTH transactions. When the two clicks are
	 * the same type on the same item, the eventual coin delta therefore covers exactly their combined
	 * quantity: keep the ORIGINAL {@code coinsBefore} and SUM the quantities, and {@code gp_total} comes
	 * out exact rather than absent.
	 *
	 * <p><b>The window is UNRESOLVED-ness, not same-tick.</b> Field-observed 2026-08-17: two "Buy 10"
	 * clicks a single tick apart produced {@code qty:10, gp_total:11325, unit_price_gp:1132} — one
	 * click's quantity against both clicks' gold, with no {@code qty_merged} label, so a fabricated unit
	 * price (true ~755) was indistinguishable downstream from a correct single-click row. That is the
	 * exact half-price failure the conservative rule exists to prevent, arriving through the door the
	 * {@code prev.tick == tick} equality left open. What makes {@code prev.coinsBefore} usable is that
	 * nothing has consumed the pending, so the merge now spans the same {@link #STORE_PENDING_MAX_TICKS}
	 * window the resolver already uses to decide a pending is still live. Beyond it the resolver would
	 * discard the pending anyway, so the two agree by construction.
	 *
	 * <p>Genuine ambiguity is still respected. Clicks on a DIFFERENT item, or in a different direction,
	 * cannot be split out of one delta, so those stay {@code ambiguous} and still degrade to
	 * {item, qty} — the audit's rule that we never emit a guessed number is unchanged.
	 */
	static StorePending mergeStorePending(StorePending prev, String type, int item, int qty, long coinsBefore, int tick)
	{
		return mergeStorePending(prev, type, item, qty, coinsBefore, UNKNOWN_ITEM_COUNT, tick);
	}

	static StorePending mergeStorePending(StorePending prev, String type, int item, int qty, long coinsBefore,
		long itemBefore, int tick)
	{
		if (prev != null && tick - prev.tick >= 0 && tick - prev.tick <= STORE_PENDING_MAX_TICKS)
		{
			if (prev.item == item && prev.type.equals(type) && !prev.ambiguous)
			{
				// Same item, same direction, prev never resolved → one delta covers both. Both baselines
				// stay the ORIGINAL pre-transaction readings, for the same reason: nothing has consumed
				// this pending, so no inventory change has been applied to either count yet.
				return new StorePending(type, item, prev.qty + qty, prev.coinsBefore, prev.itemBefore,
					tick, false, true);
			}
			// Different item or direction inside one window — the delta merges unrelated transactions.
			return new StorePending(type, item, qty, coinsBefore, itemBefore, tick, true, false);
		}
		return new StorePending(type, item, qty, coinsBefore, itemBefore, tick, false, false);
	}

	/**
	 * Resolve an armed store pending against the post-transaction coin count. Consumes the pending (one
	 * inventory change resolves at most one click) and emits the store event, with the exact-gp price when it
	 * can be cleanly attributed. Stale pendings (a failed click that never moved the inventory, then some
	 * unrelated later change) are dropped rather than paired. Package-private seam so the async path is unit
	 * testable without a live client.
	 */
	void resolveStorePendingOnInventoryChange(long coinsAfter, int currentTick)
	{
		resolveStorePendingOnInventoryChange(coinsAfter, UNKNOWN_ITEM_COUNT, currentTick);
	}

	/**
	 * @param itemAfter post-transaction count of the transacted item, or {@link #UNKNOWN_ITEM_COUNT} when it
	 *                  could not be read. Its distance from the pending's baseline is the quantity the
	 *                  server ACTUALLY moved, which is what makes a unit price safe to derive — see
	 *                  {@link #buildStoreTxFields}.
	 */
	void resolveStorePendingOnInventoryChange(long coinsAfter, long itemAfter, int currentTick)
	{
		resolveStorePendingsOnInventoryChange(coinsAfter, id -> itemAfter, currentTick);
	}

	/**
	 * Resolve the armed store pendings against one INVENTORY change. {@code countAfter} gives an item's count
	 * after the change, or is null when the inventory could not be read.
	 *
	 * <p>Stale pendings are dropped. When the item counts are known they decide whose change this is, also for
	 * a single click: a click resolves only on a change that moved its item its way. A failed sell (0 gp sale
	 * refused, item still held) used to resolve on any inventory change inside the window and send a store_sell
	 * for a sale that never happened (live run 2026-10-19, beside the real retry). One item moved: the whole
	 * coin delta is that item's, so its gp_total is exact, and the others stay armed with this change's coin
	 * count as their new baseline. Several items moved in this one change: each still gets its own event, but
	 * one coin delta cannot be split, so none carries gp_total.
	 */
	void resolveStorePendingsOnInventoryChange(long coinsAfter, java.util.function.IntToLongFunction countAfter,
		int currentTick)
	{
		storePendings.values().removeIf(p -> currentTick - p.tick > STORE_PENDING_MAX_TICKS);
		if (storePendings.isEmpty())
		{
			return;
		}
		List<StorePending> resolved = new ArrayList<>();
		if (countAfter == null || storePendings.values().stream().anyMatch(p -> p.itemBefore == UNKNOWN_ITEM_COUNT
			|| countAfter.applyAsLong(p.item) == UNKNOWN_ITEM_COUNT))
		{
			// Nothing to tell the clicks apart: this change resolves them all. Several get no price.
			resolved.addAll(storePendings.values());
		}
		else
		{
			for (StorePending p : storePendings.values())
			{
				long executed = executedQty(p, countAfter.applyAsLong(p.item));
				if (executed > 0)
				{
					resolved.add(p);
				}
			}
		}
		boolean shared = resolved.size() > 1;
		for (StorePending p : resolved)
		{
			storePendings.remove(p.item);
		}
		// The coins of this change belong to the resolved clicks. What stays armed counts from here.
		for (Map.Entry<Integer, StorePending> e : storePendings.entrySet())
		{
			StorePending p = e.getValue();
			e.setValue(new StorePending(p.type, p.item, p.qty, coinsAfter, p.itemBefore, p.tick, p.ambiguous, p.qtyMerged));
		}
		if (!activityLogActive())
		{
			return;
		}
		for (StorePending p : resolved)
		{
			long executed = executedQty(p, countAfter == null ? UNKNOWN_ITEM_COUNT : countAfter.applyAsLong(p.item));
			Map<String, Object> fields = buildStoreTxFields(p.type, p.item, p.qty, p.coinsBefore, coinsAfter,
				p.ambiguous || shared, p.qtyMerged, executed);
			addStoreContextFields(fields);	// nearby[] + world + loc — the candidate receivers of a store transfer
			emitEvent(p.type, fields);
		}
	}

	/**
	 * The quantity the server actually moved, from the item-count delta, or {@link #UNKNOWN_ITEM_COUNT} when
	 * either baseline is missing. Sign is normalised: a buy adds items, a sell removes them, so the
	 * magnitude is what matters and a delta pointing the wrong way is not this transaction's.
	 */
	static long executedQty(StorePending p, long itemAfter)
	{
		if (p.itemBefore == UNKNOWN_ITEM_COUNT || itemAfter == UNKNOWN_ITEM_COUNT)
		{
			return UNKNOWN_ITEM_COUNT;
		}
		long delta = "store_buy".equals(p.type) ? itemAfter - p.itemBefore : p.itemBefore - itemAfter;
		return delta < 0 ? UNKNOWN_ITEM_COUNT : delta;
	}

	/**
	 * Attach store-transfer context to a store event: `nearby` (players seen over the shop visit — the
	 * candidate receivers of the general-store method: staff sells cheap, an untracked player buys it out),
	 * `world`, `loc`. Instance method (needs the live client). nearby[] comes from the visit accumulator; a
	 * live snapshot backfills if the accumulator is empty (event fired before a tick ran).
	 */
	void addStoreContextFields(Map<String, Object> fields)
	{
		if (client == null)
		{
			return;
		}
		List<Map<String, Object>> nearby = nearbyFromVisit();
		if (nearby.isEmpty())
		{
			nearby = nearbyPlayersSnapshot(NEARBY_FIELD_CAP);
		}
		if (!nearby.isEmpty())
		{
			fields.put("nearby", nearby);		// everyone seen across the whole shop visit
		}
		// AND, separately, who was standing there at the CLICK. The two answer different questions and
		// a dispute is about the second: "nobody was around at some point in the visit" is far weaker
		// than "nobody was within N tiles when the item moved". Captured at the click rather than here
		// because this runs on the inventory change, which is one or more ticks later.
		List<Map<String, Object>> atTx = nearbyAtTx;
		if (atTx != null && !atTx.isEmpty())
		{
			fields.put("nearby_at_tx", atTx);
		}
		nearbyAtTx = null;
		fields.put("world", client.getWorld());
		Player self = client.getLocalPlayer();
		WorldPoint me = self == null ? null : self.getWorldLocation();
		if (me != null)
		{
			fields.put("loc", java.util.Arrays.asList(me.getX(), me.getY(), me.getPlane()));
		}
	}

	/**
	 * Ephemeral rows for the staff store overlay only. The upload readers below stay empty;
	 * rendering a visible player must not populate event context, journals or snapshots.
	 */
	List<Map<String, Object>> nearbyPlayersForOverlay(int cap)
	{
		List<Map<String, Object>> rows = new ArrayList<>();
		if (cap <= 0 || client == null || !isShopOpen() || !storeToolsEnabled() || !staffCaptureEnabled())
		{
			return rows;
		}
		Player self = client.getLocalPlayer();
		WorldPoint me = self == null ? null : self.getWorldLocation();
		if (me == null)
		{
			return rows;
		}
		List<Player> players = client.getPlayers();
		if (players == null)
		{
			return rows;
		}
		for (Player player : players)
		{
			if (player == null || player == self)
			{
				continue;
			}
			String name = player.getName();
			WorldPoint location = player.getWorldLocation();
			if (name == null || location == null)
			{
				continue;
			}
			name = Text.removeTags(name);
			int distance = location.distanceTo(me);
			if (name.isEmpty() || distance > StoreNearbyOverlay.DISPLAY_RANGE_TILES)
			{
				continue;
			}
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("rsn", name);
			row.put("dist", distance);
			row.put("cb", player.getCombatLevel());
			rows.add(row);
		}
		rows.sort(java.util.Comparator
			.comparingInt((Map<String, Object> row) -> (Integer) row.get("dist"))
			.thenComparing(row -> (String) row.get("rsn")));
		int limit = Math.min(cap, StoreNearbyOverlay.DISPLAY_CAP);
		return new ArrayList<>(rows.subList(0, Math.min(limit, rows.size())));
	}

	/** Snapshot up to {@code cap} nearest OTHER players right now: {rsn, dx, dy, dist, cb}, nearest first. */
	List<Map<String, Object>> nearbyPlayersSnapshot(int cap)
	{
		return nearbyPlayersSnapshot(cap, false);
	}

	// ---- WILDERNESS SURROUNDING PLAYERS (staff only) ----
	//
	// WHAT THIS CAN SEE, from the RuneLite 1.13.1 API itself. client.getPlayers() is the top-level world
	// view's player set: every player the SERVER sent to this client, and nobody else. The minimap draws
	// a zoom-dependent subset of it. So the honest label is "client_loaded": it is not a claim that nobody
	// else was nearby. FLOOR IS UNKNOWN: Player.getWorldLocation() is built from the world view's plane
	// (the viewer's), so another player's floor cannot be told apart; rows say plane_known:false and no
	// row is ever dropped for its floor.
	//
	// PRESENCE IS EVIDENCE, NEVER ATTRIBUTION: nothing here names who took a pile or who received a trade.
	// NAMES are the exact displayed names at that moment. No alias, history or identity link is made.
	// ONLY CURRENT-AT-EVENT SNAPSHOTS are emitted. Nothing is accumulated across ticks.

	/** Evidence label for {@link #surroundingPlayersNow}. Changing it changes what the rows claim. */
	static final String SURROUNDING_OBSERVATION = "client_loaded";
	/** Most rows one snapshot carries before the size budget is even considered. */
	static final int SURROUNDING_ROW_CAP = 64;
	/**
	 * Largest encoded event the snapshot may grow to. The live /event-ingest skips an event whose fields
	 * blob exceeds 8192 chars and still answers 200, so nothing would ever report the loss. 512 chars of
	 * headroom under that.
	 */
	static final int SURROUNDING_EVENT_BUDGET = 7680;
	/** Stand-in for the event_id that emitEventBound adds later: same length (32 hex), so it is measured. */
	private static final String EVENT_ID_PLACEHOLDER = "00000000000000000000000000000000";

	/** Is our character in the Wilderness right now? The same varbit drop.wilderness and death_kind use. */
	boolean inWilderness()
	{
		return client != null && client.getVarbitValue(Varbits.IN_WILDERNESS) > 0;
	}

	/**
	 * Every other loaded player right now: {rsn, dx, dy, dist, cb}, nearest first, ties by name so the
	 * order is deterministic. Uncapped; callers cap and say so. dist is 2D Chebyshev (floor unknown).
	 */
	List<Map<String, Object>> surroundingPlayersNow()
	{
		if (!staffCaptureEnabled()) return java.util.Collections.emptyList();

		List<Map<String, Object>> out = new ArrayList<>();
		if (client == null)
		{
			return out;
		}
		Player self = client.getLocalPlayer();
		List<Player> players = client.getPlayers();
		WorldPoint me = self == null ? null : self.getWorldLocation();
		if (me == null || players == null)
		{
			return out;
		}
		for (Player p : players)
		{
			WorldPoint loc = p == null ? null : p.getWorldLocation();
			if (p == null || p == self || p.getName() == null || p.getName().isEmpty() || loc == null)
			{
				continue;
			}
			int dx = loc.getX() - me.getX();
			int dy = loc.getY() - me.getY();
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("rsn", Text.removeTags(p.getName()));
			m.put("dx", dx);
			m.put("dy", dy);
			m.put("dist", Math.max(Math.abs(dx), Math.abs(dy)));
			m.put("cb", p.getCombatLevel());
			out.add(m);
		}
		out.sort((a, b) ->
		{
			int c = Integer.compare((Integer) a.get("dist"), (Integer) b.get("dist"));
			return c != 0 ? c : ((String) a.get("rsn")).compareTo((String) b.get("rsn"));
		});
		return out;
	}

	/**
	 * Attach a current-at-event snapshot to {@code fields} under {@code key}, if the staff drop-proof grant
	 * holds and we are in the Wilderness. Rows are the nearest first; the first {@link #SURROUNDING_ROW_CAP}
	 * are kept, then rows drop from the far end until the whole event fits {@link #SURROUNDING_EVENT_BUDGET}.
	 * The own-account row is never shrunk: with no room at all the block says so with zero rows.
	 */
	void attachSurroundingSnapshot(Map<String, Object> fields, String key)
	{
		if (!dropProofEnabled() || !inWilderness())
		{
			return;
		}
		Player self = client.getLocalPlayer();
		WorldPoint me = self == null ? null : self.getWorldLocation();
		if (me == null)
		{
			return;
		}
		List<Map<String, Object>> all = surroundingPlayersNow();
		Map<String, Object> block = new LinkedHashMap<>();
		block.put("observation", SURROUNDING_OBSERVATION);
		block.put("plane_known", false);
		block.put("wilderness", true);
		block.put("anchor", java.util.Arrays.asList(me.getX(), me.getY(), me.getPlane()));
		block.put("observed_count", all.size());
		fields.put(key, fitSurrounding(fields, key, block, all));
	}

	/**
	 * Fill {@code block} with as many of {@code rows} as fit. Deterministic: the same rows always give the
	 * same output. Measures the event as the server will see it, event_id and context included.
	 */
	Map<String, Object> fitSurrounding(Map<String, Object> fields, String key, Map<String, Object> block,
		List<Map<String, Object>> rows)
	{
		int n = Math.min(rows.size(), SURROUNDING_ROW_CAP);
		String reason = n < rows.size() ? "row_cap" : null;
		while (true)
		{
			List<Map<String, Object>> kept = new ArrayList<>(rows.subList(0, n));
			block.put("emitted_count", n);
			block.put("truncated", n < rows.size());
			if (n < rows.size())
			{
				block.put("truncation_reason", reason);
			}
			else
			{
				block.remove("truncation_reason");
			}
			block.put("players", kept);
			if (n == 0 || encodedEventLength(fields, key, block) <= SURROUNDING_EVENT_BUDGET)
			{
				return block;
			}
			// One row at a time from the far end, so the cut lands on the exact largest count that fits.
			n--;
			reason = "size_budget";
		}
	}

	/** Length of the event as the server's fields blob will see it, with this block attached. */
	private int encodedEventLength(Map<String, Object> fields, String key, Map<String, Object> block)
	{
		Map<String, Object> wire = new LinkedHashMap<>(fields);
		wire.put(key, block);	// under its REAL key: the key's own length counts too
		wire.put("event_id", EVENT_ID_PLACEHOLDER);
		return gson.toJson(wire).length();
	}

	/**
	 * The name of the NPC our own character is interacting with, or null. Read when the shop opens: the
	 * Trade click faces the shopkeeper, so this names the shop's owner for the buyer check.
	 */
	String currentShopkeeperName()
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return null;
		}
		Actor t = client.getLocalPlayer().getInteracting();
		return t instanceof net.runelite.api.NPC && t.getName() != null ? Text.removeTags(t.getName()) : null;
	}

	/** Index of the NPC our character faces when the shop opens, or -1. */
	int currentShopkeeperIndex()
	{
		if (client == null || client.getLocalPlayer() == null)
		{
			return -1;
		}
		Actor t = client.getLocalPlayer().getInteracting();
		return t instanceof net.runelite.api.NPC ? ((net.runelite.api.NPC) t).getIndex() : -1;
	}

	/**
	 * Same snapshot, and with {@code activity} each row also says what the player was doing: {@code anim}
	 * (animation id, -1 idle) and {@code interacting_npc} when they face an NPC, plus {@code with_shopkeeper}
	 * when that NPC is the shopkeeper we are trading with. Another player's shop screen is never visible,
	 * so this is the closest mechanical sign that they are trading with the same shop. Player targets are
	 * not named.
	 */
	List<Map<String, Object>> nearbyPlayersSnapshot(int cap, boolean activity)
	{
		if (!staffCaptureEnabled()) return java.util.Collections.emptyList();

		List<Map<String, Object>> out = new ArrayList<>();
		if (client == null)
		{
			return out;
		}
		Player self = client.getLocalPlayer();
		List<Player> players = client.getPlayers();
		WorldPoint me = self == null ? null : self.getWorldLocation();
		if (me == null || players == null)
		{
			return out;
		}
		List<Player> others = new ArrayList<>();
		for (Player p : players)
		{
			if (p == null || p == self || p.getName() == null || p.getName().isEmpty() || p.getWorldLocation() == null)
			{
				continue;
			}
			others.add(p);
		}
		others.sort((a, b) -> Integer.compare(a.getWorldLocation().distanceTo(me), b.getWorldLocation().distanceTo(me)));
		for (Player p : others)
		{
			if (out.size() >= cap)
			{
				break;
			}
			WorldPoint loc = p.getWorldLocation();
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("rsn", Text.removeTags(p.getName()));
			m.put("dx", loc.getX() - me.getX());
			m.put("dy", loc.getY() - me.getY());
			m.put("dist", loc.distanceTo(me));
			m.put("cb", p.getCombatLevel());
			if (activity)
			{
				m.put("anim", p.getAnimation());
				Actor t = p.getInteracting();
				if (t instanceof net.runelite.api.NPC && t.getName() != null)
				{
					String npc = Text.removeTags(t.getName());
					m.put("interacting_npc", npc);
					// The SAME NPC, by index. A second trader of the same shop (a shop assistant) reads false here
					// but still shows its name in interacting_npc; a same-named NPC elsewhere never reads true.
					m.put("with_shopkeeper", shopkeeperIndex >= 0
						&& ((net.runelite.api.NPC) t).getIndex() == shopkeeperIndex);
				}
			}
			out.add(m);
		}
		return out;
	}

	/**
	 * Milliseconds until the next store reset, given an observed anchor and the current time.
	 *
	 * Returns 0 when the phase is unknown (no reset observed yet this visit) — the caller shows nothing
	 * rather than a guess. Pure and static so the phase arithmetic is testable without a game client.
	 */
	static long msUntilNextReset(long anchorMs, long nowMs)
	{
		if (anchorMs <= 0 || nowMs < anchorMs)
		{
			return 0;			// no anchor, or a clock that went backwards — refuse to guess
		}
		long since = nowMs - anchorMs;
		long remainder = since % STORE_RESET_PERIOD_MS;
		// Land exactly ON a tick => a full period remains, never 0 (0 is reserved for "unknown").
		return STORE_RESET_PERIOD_MS - remainder;
	}

	/** True when the phase is known and a countdown may be shown. */
	static boolean resetPhaseKnown(long anchorMs)
	{
		return anchorMs > 0;
	}

	/** The live countdown infobox, or null when none is shown. Client thread only. */
	private Timer resetTimer;

	/**
	 * Show (or re-point) the countdown for the next reset.
	 *
	 * Called once per observed reset, so the box is replaced rather than accumulated — a leaked infobox
	 * is the obvious failure of this feature and the tests assert against it explicitly.
	 */
	private void showResetTimer()
	{
		if (infoBoxManager == null || !storeToolsEnabled() || !resetPhaseKnown(storeResetAnchorMs))
		{
			return;
		}
		removeResetTimer();
		long remainMs = msUntilNextReset(storeResetAnchorMs, System.currentTimeMillis());
		if (remainMs <= 0)
		{
			return;
		}
		java.awt.image.BufferedImage icon = itemManager != null ? itemManager.getImage(COINS_ITEM_ID) : null;
		Timer t = new Timer(remainMs, java.time.temporal.ChronoUnit.MILLIS, icon, this);
		t.setTooltip("General store resets");
		resetTimer = t;
		infoBoxManager.addInfoBox(t);
	}

	/** Counts tick-driven re-arms. Test seam: the re-arm decision is otherwise invisible. */
	private int reArmAttempts;

	int reArmAttemptsForTest()
	{
		return reArmAttempts;
	}

	boolean resetPhaseKnownForTest()
	{
		return resetPhaseKnown(storeResetAnchorMs);
	}

	/** Milliseconds until the next reset, or 0 when the phase has not been observed yet. */
	long msUntilNextResetForDisplay()
	{
		return msUntilNextReset(storeResetAnchorMs, System.currentTimeMillis());
	}

	/**
	 * DIAGNOSTIC ONLY — writes what the shop container actually does, to a LOCAL file.
	 *
	 * The reset model is not yet confirmed against a real client: a full store session produced no
	 * anchor on 2026-09-03 while the operator saw several resets happen. Rather than guess at a
	 * second model, record the ground truth. Nothing here is uploaded and nothing about another
	 * player is written — only item ids and quantities from the shop's own container.
	 *
	 * Enabled only by the system property, so an ordinary build writes nothing at all.
	 */
	private void traceLine(String text)
	{
		String path = System.getProperty("osrsbis.shoptrace");
		if (path == null || path.isEmpty())
		{
			return;
		}
		try
		{
			java.nio.file.Files.write(java.nio.file.Paths.get(path),
				(System.currentTimeMillis() + " " + text + "\n")
					.getBytes(java.nio.charset.StandardCharsets.UTF_8),
				java.nio.file.StandardOpenOption.CREATE,
				java.nio.file.StandardOpenOption.APPEND);
		}
		catch (Exception ignored)
		{
			// a diagnostic must never affect the plugin
		}
	}

	private void traceShopStock(Map<Integer, Integer> now)
	{
		String path = System.getProperty("osrsbis.shoptrace");
		if (path == null || path.isEmpty())
		{
			return;
		}
		try
		{
			StringBuilder sb = new StringBuilder();
			sb.append(System.currentTimeMillis()).append(' ');
			sb.append("gate=").append(storeToolsEnabled()).append(' ');
			sb.append("probe=").append(storeProbeItem).append(' ');
			sb.append("anchor=").append(storeResetAnchorMs).append(' ');
			sb.append("delta=");
			boolean any = false;
			java.util.Set<Integer> keys = new java.util.TreeSet<>();
			keys.addAll(shopStock.keySet());
			keys.addAll(now.keySet());
			for (Integer k : keys)
			{
				int a = shopStock.getOrDefault(k, 0);
				int b = now.getOrDefault(k, 0);
				if (a != b)
				{
					sb.append(k).append(':').append(a).append("->").append(b).append(' ');
					any = true;
				}
			}
			if (!any)
			{
				sb.append("(none)");
			}
			sb.append('\n');
			java.nio.file.Files.write(java.nio.file.Paths.get(path),
				sb.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),
				java.nio.file.StandardOpenOption.CREATE,
				java.nio.file.StandardOpenOption.APPEND);
		}
		catch (Exception ignored)
		{
			// a diagnostic must never affect the plugin
		}
	}

	/**
	 * Milliseconds from {@code nowMs} to the NEAREST shop cycle tick of an observed anchor, or null when no
	 * phase is known (or the clock went backwards). Pure and static so it is testable without a client.
	 */
	static Long msFromResetCycle(long anchorMs, long nowMs)
	{
		if (anchorMs <= 0 || nowMs < anchorMs)
		{
			return null;
		}
		long r = (nowMs - anchorMs) % STORE_RESET_PERIOD_MS;
		return Math.min(r, STORE_RESET_PERIOD_MS - r);
	}

	/**
	 * Do two change times sit a WHOLE number of periods apart (k >= 1), within tolMs? Two changes in the same
	 * cycle (k = 0) never align: they are one observation of the cycle, not two. Pure and static.
	 */
	static boolean phaseAligned(long a, long b, long tolMs)
	{
		long gap = Math.abs(b - a);
		long k = (gap + STORE_RESET_PERIOD_MS / 2) / STORE_RESET_PERIOD_MS;
		return k >= 1 && Math.abs(gap - k * STORE_RESET_PERIOD_MS) <= tolMs;
	}

	/**
	 * The largest set of change times in which EVERY pair is phaseAligned, found greedily from each start.
	 * Returns {latest member, set size}, or null for no times. Greedy can miss a larger set, which only
	 * makes confirmation rarer: it never invents one. Pure and static so the rule is testable.
	 */
	static long[] alignedPhase(long[] obs, long tolMs)
	{
		if (obs == null || obs.length == 0)
		{
			return null;
		}
		long[] best = null;
		for (int i = 0; i < obs.length; i++)
		{
			List<Long> set = new ArrayList<>();
			set.add(obs[i]);
			for (int j = 0; j < obs.length; j++)
			{
				if (j == i)
				{
					continue;
				}
				boolean all = true;
				for (long m : set)
				{
					if (!phaseAligned(m, obs[j], tolMs))
					{
						all = false;
						break;
					}
				}
				if (all)
				{
					set.add(obs[j]);
				}
			}
			long latest = Long.MIN_VALUE;
			for (long m : set)
			{
				latest = Math.max(latest, m);
			}
			if (best == null || set.size() > best[1])
			{
				best = new long[]{latest, set.size()};
			}
		}
		return best;
	}

	/**
	 * Aligned changes needed before a history of n changes is evidence. Each other change lands inside the
	 * tolerance of a given phase with chance q = 2 * tol / period, and there are 1 / q distinct phases, so the
	 * chance that SOME phase gathers s of n by luck is at most (1 / q) * P(Binomial(n, q) >= s). Returns the
	 * smallest s >= RESET_PHASE_MIN_OBS that keeps this at or below RESET_PHASE_FALSE_RATE, or n + 1 (never).
	 * Pure and static so it is testable.
	 */
	static int requiredPhaseSupport(int n)
	{
		if (n >= 0 && n < PHASE_SUPPORT_NEEDED.length)
		{
			return PHASE_SUPPORT_NEEDED[n];
		}
		return computePhaseSupport(n);
	}

	private static int[] phaseSupportTable()
	{
		int[] t = new int[RESET_PHASE_HISTORY + 1];
		for (int n = 0; n < t.length; n++)
		{
			t[n] = computePhaseSupport(n);
		}
		return t;
	}

	private static int computePhaseSupport(int n)
	{
		double q = 2.0 * PHASE_ALIGN_TOL_MS / STORE_RESET_PERIOD_MS;
		for (int s = RESET_PHASE_MIN_OBS; s <= n; s++)
		{
			double tail = 0;
			for (int k = s; k <= n; k++)
			{
				double c = 1;
				for (int i = 0; i < k; i++)
				{
					c = c * (n - i) / (i + 1);
				}
				tail += c * Math.pow(q, k) * Math.pow(1 - q, n - k);
			}
			if (tail / q <= RESET_PHASE_FALSE_RATE)
			{
				return s;
			}
		}
		return Math.max(n, RESET_PHASE_MIN_OBS - 1) + 1;
	}

	/**
	 * Record one shop container change for the evidence phase. Before confirmation the bounded history is
	 * searched for requiredPhaseSupport(history size) aligned changes (at least 3). After it, a change that lands on the confirmed phase
	 * in a cycle not yet counted raises the support. Nothing here touches the countdown.
	 */
	private void registerResetPhaseObservation(long nowMs)
	{
		if (evidencePhaseMs > 0)
		{
			Long off = msFromResetCycle(evidencePhaseMs, nowMs);
			long k = (nowMs - evidencePhaseMs + STORE_RESET_PERIOD_MS / 2) / STORE_RESET_PERIOD_MS;
			if (off != null && off <= PHASE_ALIGN_TOL_MS && k > evidencePhaseLastCycle)
			{
				evidencePhaseSupport++;
				evidencePhaseLastCycle = k;
			}
			return;
		}
		long oldest = nowMs - RESET_PHASE_WINDOW_PERIODS * STORE_RESET_PERIOD_MS;
		while (!resetPhaseObs.isEmpty() && (resetPhaseObs.peekFirst() < oldest || resetPhaseObs.peekFirst() > nowMs))
		{
			resetPhaseObs.pollFirst();	// aged out, or a clock that went backwards
		}
		resetPhaseObs.addLast(nowMs);
		while (resetPhaseObs.size() > RESET_PHASE_HISTORY)
		{
			resetPhaseObs.pollFirst();
		}
		long[] obs = new long[resetPhaseObs.size()];
		int i = 0;
		for (long t : resetPhaseObs)
		{
			obs[i++] = t;
		}
		long[] best = alignedPhase(obs, PHASE_ALIGN_TOL_MS);
		if (best != null && best[1] >= requiredPhaseSupport(obs.length))
		{
			evidencePhaseMs = best[0];
			evidencePhaseSupport = (int) best[1];
			evidencePhaseLastCycle = 0;
			resetPhaseObs.clear();
		}
	}

	/**
	 * May this container change support the evidence phase? Only a change the shop made by itself on its
	 * cycle may: player-added stock decaying by one. So ALL of these must hold, read against the stock as it
	 * was before the change:
	 * (1) an item we sold this visit that is not the shop's own default stock fell by exactly one unit;
	 * (2) no item rose (a rise is our own sell, another seller, or a restock landing);
	 * (3) it is more than OWN_ACTION_QUIET_MS (one period plus tolerance) after our own last store click this
	 *     visit (our sells, our buy-backs and a buyer reacting to our sell all sit at a fixed offset from it).
	 * Everything else (buys by others, normalisation of native stock, our own actions) never counts.
	 */
	private boolean isShopMadeDecay(Map<Integer, Integer> now, long nowMs)
	{
		if (lastOwnStoreClickMs > 0 && nowMs - lastOwnStoreClickMs <= OWN_ACTION_QUIET_MS)
		{
			return false;
		}
		for (Map.Entry<Integer, Integer> e : now.entrySet())
		{
			if (e.getValue() > shopStock.getOrDefault(e.getKey(), 0))
			{
				return false;
			}
		}
		for (Integer item : soldThisVisit)
		{
			if (item == null || defaultStockSoldThisVisit.contains(item))
			{
				continue;
			}
			int before = shopStock.getOrDefault(item, 0);
			if (before > 0 && before - now.getOrDefault(item, 0) == 1)
			{
				return true;
			}
		}
		return false;
	}

	/** Forget the evidence phase. Called wherever the countdown anchor is dropped. */
	private void clearResetPhaseEvidence()
	{
		evidencePhaseMs = 0;
		evidencePhaseSupport = 0;
		evidencePhaseLastCycle = 0;
		resetPhaseObs.clear();
	}

	/** How far a gap may sit from one full period and still count as the cycle. */
	static final long PERIOD_TOLERANCE_MS = 3_000L;

	/**
	 * Do two consecutive container changes sit exactly one store period apart?
	 *
	 * This is the whole anchor rule. It is deliberately conservative: a shop where nothing else
	 * happens produces a clean 60s chain, while a busy shop full of customers produces changes at
	 * arbitrary times that mostly will NOT be 60s apart, so the clock simply stays unknown rather
	 * than locking onto a coincidence. Showing nothing beats showing a wrong countdown.
	 *
	 * Pure and static so the rule is testable without a client.
	 */
	static boolean isPeriodAgreement(long previousChangeMs, long nowMs)
	{
		if (previousChangeMs <= 0 || nowMs <= previousChangeMs)
		{
			return false;		// nothing to compare against, or a clock that went backwards
		}
		long gap = nowMs - previousChangeMs;
		return Math.abs(gap - STORE_RESET_PERIOD_MS) <= PERIOD_TOLERANCE_MS;
	}

	/** Remove the countdown. Idempotent — every teardown path calls it. */
	private void removeResetTimer()
	{
		Timer t = resetTimer;
		resetTimer = null;
		if (t != null && infoBoxManager != null)
		{
			infoBoxManager.removeInfoBox(t);
		}
	}

	/**
	 * Watch the SHOP's stock for someone taking an item we just sold into it — the general-store
	 * counterparty, which no other signal can see.
	 *
	 * The method works because the shop is a dead drop: staff sells low, an untracked player buys it
	 * out. The staff account's own inventory shows only the first half. The shop container shows the
	 * second: stock of a sold item DROPS when a player takes it. So a drop, paired with who is standing
	 * there at that moment, names the likely receiver.
	 *
	 * ⚠ This is an INFERENCE and is emitted as one (`taken_by_candidates`, never `counterparty`). Stock
	 * also falls when the shop's own restock timer runs, and any player in the shop could be the taker,
	 * so the candidate list is the players present — evidence to weigh, not an accusation. Only items
	 * this visit actually SOLD are watched, so a staff buy that lowers stock is never mistaken for it.
	 */
	void handleShopStockChanged(ItemContainer shop)
	{
		if (shop == null)
		{
			return;
		}
		Map<Integer, Integer> now = new java.util.HashMap<>();
		Item[] items = shop.getItems();
		if (items != null)
		{
			for (Item it : items)
			{
				if (it != null && it.getId() > 0)
				{
					now.merge(it.getId(), it.getQuantity(), Integer::sum);
				}
			}
		}
		traceShopStock(now);
		long nowMs = nowMs();
		// The evidence phase as it was BEFORE this change. Player-added stock decays on the cycle tick, so a
		// store_taken that lands on it may be the shop, not a buyer. The change being judged must never count
		// toward its own phase, so read it before this change is registered below.
		long evidencePhaseBefore = evidencePhaseMs;
		int evidenceSupportBefore = evidencePhaseSupport;

		// ANCHOR 1 — THE ITEM WE SOLD VANISHING. This is the event the user actually watches, and it
		// is the strongest signal available: a junk item the shop does NOT natively stock is sold in,
		// and it is removed on the next tick.
		//
		// The discriminator is ZERO, measured live 2026-09-03. Player-added stock decays 1 per tick
		// until it reaches 0 and leaves the shop entirely (item 1191: 5->4->3->…->0, each step exactly
		// 60.0s apart; item 1159: 1->0). Shop DEFAULT stock behaves completely differently — selling a
		// Pot into Varrock GS raised it 5->6 and the shop normalised it back to 5 in 1.2-5.4 SECONDS,
		// never touching the cycle. So a sold item falling to a NON-ZERO number is the shop
		// normalising its own goods and means nothing; falling to ZERO is the tick.
		// ONLY THE PROBE, never the merchandise. Reported from the field by Snaauz on 2026-09-19:
		// delivering more than one item made the timer reset as soon as the first item was bought.
		// A delivery visit sells the junk probe and then the goods, so soldThisVisit holds both. A
		// customer buying the GOODS out takes their stock to zero at an arbitrary moment in the cycle,
		// which is a purchase and not a tick. Anchoring there threw the phase away and every number
		// after it was wrong. storeProbeItem already records the first item sold, which is the junk
		// whose decay IS the cycle, so read that one item and no other.
		if (storeProbeItem != 0)
		{
			int had = shopStock.getOrDefault(storeProbeItem, 0);
			int has = now.getOrDefault(storeProbeItem, 0);
			if (had > 0 && has == 0)
			{
				storeResetAnchorMs = nowMs;
				traceLine("ANCHOR probe-vanished item=" + storeProbeItem + " " + had + "->0");
				showResetTimer();
			}
		}

		// ANCHOR 2 — PERIODICITY, for a visit where nothing of ours has vanished yet. Two consecutive
		// container changes exactly one period apart can only be the cycle. Confirmed live: two
		// restock ticks 60.015s apart anchored, while two buys 15.0s apart were correctly refused.
		//
		// Two earlier models were refuted by measurement, both by watching a real shop. "the junk item
		// we sold vanishing IS the reset" gave 72s cycles drifting 36s/24s/12s, because a shop's
		// DEFAULT stock normalises on its own schedule. "a tick is a rise and a fall together" refused
		// all five ticks of a five-minute observation, because a full shop has nothing to restock. What
		// survived every observation is the PERIOD: ticks landed at 60.0s with no deviation, twice.
		if (!now.equals(shopStock) && !shopStock.isEmpty())
		{
			if (storeResetAnchorMs == 0 && isPeriodAgreement(lastStockChangeMs, nowMs))
			{
				storeResetAnchorMs = nowMs;
				traceLine("ANCHOR period gap=" + (nowMs - lastStockChangeMs));
				showResetTimer();
			}
			lastStockChangeMs = nowMs;
			if (isShopMadeDecay(now, nowMs))
			{
				registerResetPhaseObservation(nowMs);
			}
		}
		for (Integer item : soldThisVisit)
		{
			int before = shopStock.getOrDefault(item, -1);
			int after = now.getOrDefault(item, 0);
			if (before < 0 || after >= before)
			{
				continue;		// no baseline yet, or stock did not fall
			}
			if (item != null && item == lastSelfBuyItem
				&& System.currentTimeMillis() - lastSelfBuyAtMs <= SELF_BUY_SUPPRESS_MS)
			{
				continue;	// WE bought it back — not a customer. See onMenuOptionClicked.
			}
			if (after > 0 && before - after == 1 && defaultStockSoldThisVisit.contains(item))
			{
				continue;	// F-A1: the shop normalising its own default stock, not a customer
			}
			if (after == 0)
			{
				defaultStockSoldThisVisit.remove(item);	// native stock is gone: anything sold in later is ours
			}
			Map<String, Object> f = new LinkedHashMap<>();
			f.put("item", item);
			f.put("qty", before - after);
			f.put("stock_before", before);
			f.put("stock_after", after);
			// Every other player in the shop area, each with what they were doing, so the reader can keep
			// only the mechanically plausible buyers (facing the same shopkeeper) and name one if one remains.
			List<Map<String, Object>> present = nearbyPlayersSnapshot(NEARBY_FIELD_CAP, true);
			if (!present.isEmpty())
			{
				f.put("taken_by_candidates", present);
			}
			if (shopkeeperName != null)
			{
				f.put("shopkeeper", shopkeeperName);
			}
			// Distance in ms to the nearest shop cycle tick, when the EVIDENCE phase was confirmed before this
			// change. Near 0 = the fall landed on the cycle, where player-added stock decays by itself (measured
			// live 2026-09-27: a sold log fell to 0 exactly 60.0 s after the previous one with no buyer).
			// reset_cycle_obs = how many changes support that phase. Both absent = phase not confirmed, so the
			// reader cannot tell a decay from a buy by timing. The countdown anchor is never used here.
			Long msFromCycle = msFromResetCycle(evidencePhaseBefore, nowMs);
			if (msFromCycle != null)
			{
				f.put("ms_from_reset_cycle", msFromCycle);
				f.put("reset_cycle_obs", evidenceSupportBefore);
			}
			if (client != null)
			{
				f.put("world", client.getWorld());
				Integer soldAt = lastSellTickThisVisit.get(item);
				if (soldAt != null && client.getTickCount() >= soldAt)
				{
					f.put("ticks_since_sell", client.getTickCount() - soldAt);
				}
			}
			emitEvent("store_taken", f);
			markStoreClipMoment();
		}
		shopStock.clear();
		shopStock.putAll(now);
	}

	/** Merge the current nearby players into the shop-visit accumulator (called each tick while shop open). */
	void accumulateShopNearby()
	{
		if (!staffCaptureEnabled())
		{
			shopVisitNearby.clear();
			return;
		}
		if (client == null)
		{
			return;
		}
		Player self = client.getLocalPlayer();
		List<Player> players = client.getPlayers();
		WorldPoint me = self == null ? null : self.getWorldLocation();
		if (me == null || players == null)
		{
			return;
		}
		int tick = client.getTickCount();
		for (Player p : players)
		{
			if (p == null || p == self || p.getName() == null || p.getName().isEmpty() || p.getWorldLocation() == null)
			{
				continue;
			}
			int dist = p.getWorldLocation().distanceTo(me);
			String rsn = Text.removeTags(p.getName());
			int[] rec = shopVisitNearby.get(rsn);
			if (rec == null)
			{
				if (shopVisitNearby.size() >= MAX_NEARBY_TRACKED)
				{
					continue;	// map full — don't grow unbounded on a crowded world
				}
				shopVisitNearby.put(rsn, new int[]{dist, tick, tick, p.getCombatLevel()});
			}
			else
			{
				if (dist < rec[0])
				{
					rec[0] = dist;	// closest approach this visit
				}
				rec[2] = tick;		// last seen
			}
		}
	}

	/** Emit nearby[] from the visit accumulator, nearest-first: {rsn, dist, first_tick, last_tick, cb}. */
	private List<Map<String, Object>> nearbyFromVisit()
	{
		List<Map<String, Object>> out = new ArrayList<>();
		List<Map.Entry<String, int[]>> entries = new ArrayList<>(shopVisitNearby.entrySet());
		entries.sort((a, b) -> Integer.compare(a.getValue()[0], b.getValue()[0]));
		for (Map.Entry<String, int[]> e : entries)
		{
			if (out.size() >= NEARBY_FIELD_CAP)
			{
				break;
			}
			int[] r = e.getValue();
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("rsn", e.getKey());
			m.put("dist", r[0]);
			m.put("first_tick", r[1]);
			m.put("last_tick", r[2]);
			m.put("cb", r[3]);
			out.add(m);
		}
		return out;
	}

	/**
	 * Build the store event fields. {item, qty} always; gp_total = the exact coins that moved, added ONLY
	 * when the delta is cleanly attributable — right sign for the direction (buy → coins fell, sell → rose)
	 * and not a same-tick batch. unit_price_gp is a LABELLED average (gp_total/qty), only meaningful for
	 * qty>1; per-item price scales mid-batch as stock moves, so it is never a flat rate. When the delta can't
	 * be trusted, degrade to {item, qty} only (option D) rather than emit a guess. Pure/static: no client.
	 */
	static Map<String, Object> buildStoreTxFields(String type, int item, int qty, long coinsBefore, long coinsAfter, boolean ambiguous)
	{
		return buildStoreTxFields(type, item, qty, coinsBefore, coinsAfter, ambiguous, false);
	}

	/**
	 * @param qtyMerged qty is the SUM of same-tick clicks (intent), not a confirmed executed quantity —
	 *                  gp_total stays exact (it is the measured coin delta) but unit_price_gp is OMITTED,
	 *                  because dividing an exact total by an unconfirmed denominator yields a wrong unit
	 *                  price (half price when one of two merged clicks failed). An absent field is
	 *                  recoverable; a plausible wrong number is not.
	 */
	static Map<String, Object> buildStoreTxFields(String type, int item, int qty, long coinsBefore, long coinsAfter,
		boolean ambiguous, boolean qtyMerged)
	{
		return buildStoreTxFields(type, item, qty, coinsBefore, coinsAfter, ambiguous, qtyMerged,
			UNKNOWN_ITEM_COUNT);
	}

	/**
	 * @param executedQty the quantity the server ACTUALLY moved, measured from the item-count delta, or
	 *                    {@link #UNKNOWN_ITEM_COUNT} when it could not be measured.
	 *
	 *                    <p>Field-observed 2026-08-17: a SINGLE "Buy 50" click on a shop holding 5 emitted
	 *                    {@code qty:50, gp_total:3925, unit_price_gp:78} against a true unit of ~785, and a
	 *                    single "Sell 50" of 27 items emitted {@code unit_price_gp:43} against ~80. A
	 *                    single click's quantity is click INTENT too — the shop's stock, the inventory's
	 *                    free space and the player's coins all cap what actually executes — so "one click
	 *                    means a confirmed denominator" was simply false, and both rows were 10x wrong
	 *                    while looking exact.
	 *
	 *                    <p>So a unit price is derived only when the measured executed quantity CONFIRMS
	 *                    the click: it is then a real per-item rate over a real denominator. When the two
	 *                    disagree the row carries {@code qty_partial: true} and the executed quantity in
	 *                    {@code qty_executed}, and no unit price — the same "label it, never guess it"
	 *                    rule the merged case already follows. When nothing could be measured, there is no
	 *                    evidence either way, so no unit price either.
	 */
	static Map<String, Object> buildStoreTxFields(String type, int item, int qty, long coinsBefore, long coinsAfter,
		boolean ambiguous, boolean qtyMerged, long executedQty)
	{
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("item", item);
		fields.put("qty", qty);
		long delta = coinsAfter - coinsBefore;
		boolean signOk = "store_buy".equals(type) ? delta < 0 : delta > 0;
		if (!ambiguous && signOk)
		{
			long gp = Math.abs(delta);
			fields.put("gp_total", gp);
			if (qtyMerged)
			{
				// Label the residual uncertainty rather than let a bare exact-looking number imply a
				// pairing we cannot guarantee. gp_total is always the coins that really moved in this
				// resolution window. qty is the SUM of same-tick click intents, and two things can make
				// it overstate what those coins bought: a click that failed (out of stock, full
				// inventory, insufficient coins), or the server settling the two clicks on DIFFERENT
				// ticks, in which case the first ItemContainerChanged carries only the first
				// transaction's delta while qty already counts both.
				//
				// Neither is detectable client-side — the plugin sees one inventory update and cannot
				// ask what the server did — so this is honest labelling, not a guess. A consumer must
				// treat qty as an UPPER BOUND on a merged row and must never divide gp_total by it.
				// unit_price_gp is omitted for exactly that reason.
				fields.put("qty_merged", true);
				if (executedQty != UNKNOWN_ITEM_COUNT)
				{
					// The measured quantity is not uncertain even when the click intent was — publish it
					// so a consumer has a real denominator instead of only an upper bound.
					fields.put("qty_executed", executedQty);
				}
			}
			else if (executedQty != UNKNOWN_ITEM_COUNT && executedQty != qty)
			{
				// The server moved a different quantity than the click asked for — partial fill (stock ran
				// out, inventory filled, coins ran short) or nothing at all. qty stays the click's own
				// number for continuity with every historical row; the truth sits beside it, labelled.
				fields.put("qty_partial", true);
				fields.put("qty_executed", executedQty);
			}
			else if (executedQty == qty && qty > 1)
			{
				// The measured executed quantity CONFIRMS the click, so gp_total/qty is a real per-item
				// rate over a real denominator. An unmeasurable quantity does not reach here: no evidence
				// is not the same as confirmation, and this release exists to stop plausible wrong numbers.
				fields.put("unit_price_gp", gp / qty);	// average — see note above
			}
		}
		else if (executedQty != UNKNOWN_ITEM_COUNT)
		{
			// A SALE THE SHOP PAID 0 GP FOR. The item count measured the sell and the coins were read before
			// and after (a measured quantity needs the inventory read at the click, which is where the coins
			// come from) and did not move, on a row of its own. Without this the row looked exactly like a sale
			// whose coins were never read (live 0.7.55 audit 2026-10-27: 181 such rows, 7 of 1M+ items).
			// coins_unchanged tells a reader this 0 was measured; it is never sent without gp_total 0.
			if ("store_sell".equals(type) && !ambiguous && !qtyMerged && delta == 0 && executedQty > 0)
			{
				fields.put("gp_total", 0L);
				fields.put("coins_unchanged", true);
			}
			// The coins cannot be split (two buys settled in one inventory change), but each item's own count
			// still measured what the server moved. Live 0.7.55 (2026-10-24): a player buying two runes per
			// world sent half of all rows as a bare {item, qty:50} while about 30 had really moved.
			if (qtyMerged)
			{
				fields.put("qty_merged", true);
			}
			else if (executedQty != qty)
			{
				fields.put("qty_partial", true);
			}
			fields.put("qty_executed", executedQty);
		}
		return fields;
	}

	/**
	 * The general-store transaction type for a menu click — "store_buy", "store_sell", or null if it is
	 * neither. SINGLE source of truth for what counts as a store buy/sell: the emit path derives its event
	 * type from this and isStoreBuyOrSell delegates to it, so the two can never drift (grill F5).
	 */
	static String storeTxType(MenuOptionClicked event)
	{
		String opt = event.getMenuOption() == null ? "" : event.getMenuOption();
		if (opt.startsWith("Buy"))
		{
			return "store_buy";
		}
		if (opt.startsWith("Sell"))
		{
			return "store_sell";
		}
		return null;
	}

	/** True when a menu click is a general-store buy/sell (delegates to storeTxType — never a second match). */
	static boolean isStoreBuyOrSell(MenuOptionClicked event)
	{
		return storeTxType(event) != null;
	}

	/**
	 * "Buy 10" -&gt; 10, "Sell 10&lt;col=ff9040&gt;" -&gt; 10, "Buy" -&gt; 1 (default).
	 *
	 * <p>Colour tags are stripped first, then the trailing digits are read. Field-observed 2026-08-17: the
	 * client's SELL options carry a trailing colour tag that BUY options do not ("Sell 10&lt;col=ff9040&gt;"),
	 * so token-parsing threw and silently defaulted every sell to qty 1 while gp_total stayed correct — a
	 * 10x-wrong implied unit price on the gold-delivery path. Stripping matters rather than just scanning
	 * for digits: "ff9040" inside the tag would otherwise read as the quantity.
	 */
	static int parseTrailingQty(String option)
	{
		Matcher m = TRAILING_QTY.matcher(MENU_TAG.matcher(option).replaceAll(""));
		if (!m.find())
		{
			return 1;
		}
		try
		{
			return Integer.parseInt(m.group(1));
		}
		catch (NumberFormatException e)
		{
			return 1;	// absurdly long digit run — treat as unparseable rather than overflow
		}
	}

	/**
	 * Off-book value events. A "Drop", ground-item "Take", or High/Low-Alchemy cast arms an inventory-delta
	 * pending, resolved on the next INVENTORY change from the item-count delta (alch also confirms the gp gained
	 * from the coin delta). Own gate on the activity log; not shop-scoped. Last-click-wins like the store pending
	 * (a fresh click supersedes an unresolved one — rapid drop-all logs the last drop; the wealth snapshot nets
	 * the rest). getItemId() carries the item for Drop/Take (same accessor the store path uses); for alch it is
	 * [verify in-client] (a spell-on-item click may report -1), so an unresolvable item id is skipped, not guessed.
	 */
	void maybeArmInvDeltaPending(MenuOptionClicked event)
	{
		if (!activityLogActive())
		{
			return;
		}
		String action = offBookMenuAction(event);
		if (action == null)
		{
			return;
		}
		int item = offBookItemId(event, action);
		if (item <= 0)
		{
			return;	// no resolvable item id (e.g. alch spell-on-item may report -1) — skip rather than guess
		}
		String base = action.startsWith("alch") ? "alch" : action;
		if ("drop".equals(base))
		{
			// START THE CLIP AT THE CLICK, not at the drop EVENT. The event only exists once the
			// inventory loss and the ground spawn agree, which is ticks later, so starting there
			// would cut the drop itself off the front of the evidence.
			onDropActionForProof();
		}
		String spell = "alch_high".equals(action) ? "high" : ("alch_low".equals(action) ? "low" : null);
		ItemContainer inv = client == null ? null : client.getItemContainer(InventoryID.INVENTORY);
		long beforeCount = countItem(inv, item);
		long beforeCoins = countItem(inv, COINS_ID);
		int tick = client == null ? 0 : client.getTickCount();
		Map<String, Object> location = "alch".equals(base) ? null : currentLocation();
		Boolean wilderness = "drop".equals(base)
			? (client != null && client.getVarbitValue(Varbits.IN_WILDERNESS) > 0)
			: null;
		// A ground Take carries the pile's tile; anything else has none, which reads as (-1,-1,-1).
		int[] tile = "pickup".equals(base) ? groundTakeTile(event) : new int[]{-1, -1, -1};
		InvDeltaPending armed = new InvDeltaPending(base, item, spell, beforeCount, beforeCoins,
			location, wilderness, tick, tile[0], tile[1], tile[2]);
		synchronized (invDeltaPendings)
		{
			// A second Drop before the first lands is the NORMAL shape of a drop trade, never a mistake.
			// Append; never overwrite.
			while (invDeltaPendings.size() >= INV_PENDING_MAX)
			{
				invDeltaPendings.pollFirst();	// evict the oldest — also the most likely to be stale
			}
			invDeltaPendings.addLast(armed);
		}
		if ("pickup".equals(base))
		{
			// Flag every pile this Take could have been aimed at, NOW, while they are all still
			// tracked. From here on none of them may be published as `removed_early` (somebody else
			// took it) or `despawn_timer` (nobody took it): we clicked Take on one of them, so both
			// are claims the client cannot support. Only a proven, unambiguous recovery upgrades a
			// flagged pile back to `self_pickup`.
			flagTakeArmedPiles(armed);
		}
	}

	/**
	 * WORLD tile of the ground pile a Take was clicked on, or null when it cannot be established.
	 *
	 * A ground-item menu entry carries the pile's SCENE coordinates in param0/param1 (live capture
	 * 2026-09-12: `option=Take id=1931 itemId=-1 param0=49 param1=54`). Scene coordinates are
	 * relative to the loaded region, so they are converted to world coordinates here, which is the
	 * space `DroppedGroundItem` stores and what makes the two comparable.
	 *
	 * Returns null rather than a guess whenever the opcode is not a ground-item option, the client
	 * is unavailable, or the conversion fails.
	 */
	int[] groundTakeTile(MenuOptionClicked event)
	{
		int[] none = {-1, -1, -1};
		if (client == null || event == null || !isGroundItemOpcode(event.getMenuAction()))
		{
			return none;
		}
		try
		{
			net.runelite.api.coords.WorldPoint w = net.runelite.api.coords.WorldPoint.fromScene(
				client, event.getParam0(), event.getParam1(), client.getPlane());
			return w == null ? none : new int[]{w.getX(), w.getY(), w.getPlane()};
		}
		catch (RuntimeException e)
		{
			return none;	// no scene loaded / coordinates out of range — degrade, never guess
		}
	}

	/** True for the ground-item menu opcodes, the only ones whose identifier is an item id. */
	static boolean isGroundItemOpcode(net.runelite.api.MenuAction a)
	{
		return a == net.runelite.api.MenuAction.GROUND_ITEM_FIRST_OPTION
			|| a == net.runelite.api.MenuAction.GROUND_ITEM_SECOND_OPTION
			|| a == net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION
			|| a == net.runelite.api.MenuAction.GROUND_ITEM_FOURTH_OPTION
			|| a == net.runelite.api.MenuAction.GROUND_ITEM_FIFTH_OPTION;
	}

	/**
	 * The item id for an off-book action, from whichever field the client actually populates.
	 *
	 * `getItemId()` is the right source for an INVENTORY action (Drop, alch): the entry is a widget
	 * op on a slot that holds the item. A GROUND-item Take is a different opcode entirely, and the
	 * client leaves `getItemId()` at -1 while putting the item id in the entry IDENTIFIER.
	 *
	 * Measured on the live client 2026-09-12, dropping and re-taking a Pot on world 308 - the real
	 * MenuOptionClicked the plugin received:
	 *
	 *     option=Take target=&lt;col=ff9040&gt;Pot id=1931 itemId=-1 param0=49 param1=54
	 *     type=GROUND_ITEM_THIRD_OPTION
	 *
	 * against the inventory Drop of the same item moments earlier:
	 *
	 *     option=Drop target=&lt;col=ff9040&gt;Pot id=7 itemId=1931 param0=1 param1=9764864
	 *     type=CC_OP_LOW_PRIORITY
	 *
	 * So a self-pickup could never arm a pending, no `pickup` was ever emitted for this opcode, and
	 * the item's later removal fell through to the despawn comparison and was labelled as if a
	 * stranger or the timer had taken it. Both symptoms, one cause.
	 *
	 * The fallback is deliberately narrow: pickup only, only when `getItemId()` is unusable, AND
	 * only on a GROUND_ITEM_* opcode. `identifier` on an inventory entry is the OPTION index (7 for
	 * Drop above), never an item, so it must not be consulted anywhere else. Matching the option
	 * word "Take" alone would adopt the identifier of any future non-ground entry labelled Take; the
	 * opcode is what makes that identifier an item id.
	 */
	static int offBookItemId(MenuOptionClicked event, String action)
	{
		int item = event.getItemId();
		if (item > 0 || !"pickup".equals(action) || !isGroundItemOpcode(event.getMenuAction()))
		{
			return item;
		}
		return event.getId();	// ground Take: the item id lives in the entry identifier
	}

	/**
	 * Ground-spawn confirmation for drops (the M3 redesign). A "drop" pending resolves ONLY when BOTH signals
	 * co-occur: the armed item APPEARS ON THE GROUND on/adjacent to the player's tile, AND the player's
	 * inventory holds fewer of it than at click time. An inventory removal alone (equip / eat / bank deposit /
	 * destroy — including via widget buttons that carry no item id) spawns no ground item, so it can never
	 * fabricate a drop; a ground item alone (another player's drop becoming visible) shows no inventory loss,
	 * so it never resolves either. Package-private + primitives so it is unit-testable without a client.
	 */
	/** Backwards-compatible overload — a plain ItemSpawned is always a fresh (grown) ground item. */
	void resolveDropPendingOnGroundSpawn(int spawnedItemId, int dist, long invCountAfter, int currentTick)
	{
		resolveDropPendingOnGroundSpawn(spawnedItemId, dist, invCountAfter, currentTick, true);
	}

	void resolveDropPendingOnGroundSpawn(int spawnedItemId, int dist, long invCountAfter, int currentTick, boolean stackGrew)
	{
		resolveDropPendingOnGroundSpawn(spawnedItemId, dist, invCountAfter, currentTick, stackGrew, -1, -1, -1);
	}

	/** @param tileX tileY tilePlane the spawn's world tile, recorded on the drop row; -1 when unknown. */
	void resolveDropPendingOnGroundSpawn(int spawnedItemId, int dist, long invCountAfter, int currentTick, boolean stackGrew,
		int tileX, int tileY, int tilePlane)
	{
		if (dist > DROP_SPAWN_MAX_DIST || !stackGrew)
		{
			return;	// !stackGrew: a SHRINKING nearby stack is another player looting it — never our drop landing
		}
		if (deathPending != null)
		{
			// Death belt (backs the onActorDeath disarm): mid-death ground spawns + inventory wipe are the
			// death's items, never a player-initiated drop — refuse all corroboration while a death settles.
			clearInvDeltaPendings();
			return;
		}
		// Match by ITEM ID against the oldest matching armed drop. Packet order is the server's choice, so a
		// spawn may arrive for the second click before the first; matching on the item rather than on "the
		// one pending" is what lets each drop find its own.
		InvDeltaPending p;
		synchronized (invDeltaPendings)
		{
			p = null;
			java.util.Iterator<InvDeltaPending> it = invDeltaPendings.iterator();
			while (it.hasNext())
			{
				InvDeltaPending c = it.next();
				if (!"drop".equals(c.base) || c.item != spawnedItemId)
				{
					continue;
				}
				if (currentTick - c.tick > DROP_PENDING_MAX_TICKS)
				{
					// Stale — the click this pending belonged to is long over. Discard it and keep looking:
					// returning here left a NEWER armed drop of the same item without its spawn, while the
					// pile was already tracked, so a ground_removed row appeared with no drop row (theft
					// investigation M5, event 40325).
					it.remove();
					continue;
				}
				p = c;
				break;
			}
			if (p == null)
			{
				return;
			}
			// The tile follows the spawn that corroborates (overwritten with spawnCorroboratedTick) or completes
			// the drop, so the row names the pile that actually confirmed it, never an earlier stray spawn.
			if (tileX >= 0 && tileY >= 0 && tilePlane >= 0)
			{
				p.spawnX = tileX;
				p.spawnY = tileY;
				p.spawnPlane = tilePlane;
			}
			long staleDelta = p.beforeCount - invCountAfter;
			if (staleDelta <= 0)
			{
				// The spawn was processed BEFORE the inventory decrement was visible (intra-tick order is a
				// server packet detail we don't control). Record the corroboration; the inventory-change path
				// completes the emit when the loss lands. Without this, spawn-first ordering misses EVERY drop.
				p.spawnCorroboratedTick = currentTick;
				return;
			}
			invDeltaPendings.remove(p);	// consume — both signals confirmed
		}
		// The loss came first: the row reports that earlier change, not this spawn.
		long outer = triggerChangeBuildSeq;
		triggerChangeBuildSeq = p.lossBuildSeq;
		try
		{
			emitDropEvent(p, p.beforeCount - invCountAfter);
		}
		finally
		{
			triggerChangeBuildSeq = outer;
		}
	}

	/** Drop every armed pending — used by the logout / hop / disconnect / death disarms. */
	private void clearInvDeltaPendings()
	{
		synchronized (invDeltaPendings)
		{
			invDeltaPendings.clear();
		}
	}

	/** Remove exactly one resolved/expired pending. */
	private void removeInvDeltaPending(InvDeltaPending p)
	{
		synchronized (invDeltaPendings)
		{
			invDeltaPendings.remove(p);
		}
	}

	/** The oldest armed pending, or null. Kept so the single-pending call sites read unchanged. */
	private InvDeltaPending peekInvDeltaPending()
	{
		synchronized (invDeltaPendings)
		{
			return invDeltaPendings.peekFirst();
		}
	}

	/** Shared drop emit — reached from either signal order. */
	private void emitDropEvent(InvDeltaPending p, long qty)
	{
		if (!activityLogActive())
		{
			return;
		}
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("item", p.item);
		fields.put("qty", qty);
		if (p.location != null)
		{
			fields.put("location", p.location);
		}
		fields.put("wilderness", p.wilderness != null && p.wilderness);
		// The pile's exact tile and the world, on the drop row itself, in the same {x,y,plane} shape the
		// ground_removed row uses. Before this only the removal row carried the tile, so a drop whose
		// removal was never seen (out of scene, logout) could not be located at all.
		if (p.spawnX >= 0)
		{
			Map<String, Object> tile = new LinkedHashMap<>();
			tile.put("x", p.spawnX);
			tile.put("y", p.spawnY);
			tile.put("plane", p.spawnPlane);
			fields.put("tile", tile);
		}
		putWorldContext(fields);
		// SESSION LINKAGE on the drop row itself. drop_seq is what lets the manifest join one drop
		// to one removal when a session drops the same item, same quantity, onto the same tile twice
		// — which is the ordinary shape of a drop trade, not an edge case.
		String auditSessionId = null;
		if (dropSession.active() && pendingDropSessionId != null)
		{
			auditSessionId = pendingDropSessionId;
			fields.put("drop_session_id", auditSessionId);
			fields.put("drop_seq", pendingDropSeq);
		}
		// Staff Wilderness drops only: who the client had loaded around us at this drop. The Wilderness
		// flag is the one sampled at the Drop click, so the gate and the row agree.
		if (p.wilderness != null && p.wilderness)
		{
			attachSurroundingSnapshot(fields, "surrounding_at_drop");
		}
		emitEvent("drop", fields);
		noteDropAuditEvent(auditSessionId);
	}

	/** Live wrapper for the ground-spawn resolvers: distance from the local player + current inventory count. */
	private void handleGroundItemForDropPending(net.runelite.api.TileItem it, net.runelite.api.Tile tile,
		boolean stackGrew, boolean quantityMerge)
	{
		InvDeltaPending p = peekInvDeltaPending();
		if (p == null || client == null || it == null || tile == null)
		{
			return;	// cheap early-out — ItemSpawned fires constantly for scenery/other players' items
		}
		// Ownership discriminator (review 2026-07-18): the client tags ground items with ownership,
		// and a fresh OWN drop is always OWNERSHIP_SELF. Anything else (another player's pile, an NPC drop,
		// an ownerless world spawn, a GIM partner's item) can never corroborate OUR drop — this closes the
		// whole coincidental-foreign-source fabrication class in one check. [verify in-client]
		if (it.getOwnership() != net.runelite.api.TileItem.OWNERSHIP_SELF)
		{
			return;
		}
		net.runelite.api.Player me = client.getLocalPlayer();
		net.runelite.api.coords.WorldPoint pw = me == null ? null : me.getWorldLocation();
		net.runelite.api.coords.WorldPoint tw = tile.getWorldLocation();
		if (pw == null || tw == null || pw.getPlane() != tw.getPlane())
		{
			return;
		}
		int dist = Math.abs(pw.getX() - tw.getX()) + Math.abs(pw.getY() - tw.getY());
		long invCount = countItem(client.getItemContainer(InventoryID.INVENTORY), it.getId());
		int tick = client.getTickCount();
		// Track the pile BEFORE resolving: resolution may consume the pending, and the pile is ours either
		// way (OWNERSHIP_SELF, our own tile). Only track when an armed drop of this item is waiting, so a
		// pile we did not drop this session is never adopted.
		if (dist <= DROP_SPAWN_MAX_DIST && stackGrew && hasArmedDropFor(it.getId()))
		{
			trackGroundDrop(it.getId(), it.getQuantity(), tw.getX(), tw.getY(), tw.getPlane(),
				currentLocation(), tick, it.getDespawnTime(), quantityMerge);
		}
		resolveDropPendingOnGroundSpawn(it.getId(), dist, invCount, tick, stackGrew,
			tw.getX(), tw.getY(), tw.getPlane());
	}

	/** A fresh ground item at our tile — the primary own-drop confirmation signal. */
	@Subscribe
	public void onItemSpawned(net.runelite.api.events.ItemSpawned event)
	{
		if (event != null && gameplayReady()) ownGameplay.groundClues.spawned(client, event.getItem(), System.currentTimeMillis());
		// A genuine NEW ground item, never a merge into an existing stack.
		handleGroundItemForDropPending(event.getItem(), event.getTile(), true, false);
	}

	/**
	 * Dropping a stackable onto an existing ground stack merges instead of spawning — same confirmation, but
	 * ONLY when the stack GREW (a shrinking stack is another player looting it, never our drop landing).
	 */
	@Subscribe
	public void onItemQuantityChanged(net.runelite.api.events.ItemQuantityChanged event)
	{
		// A GROWN stack is a merge: the game holds ONE pile and will fire ONE ItemDespawned for it.
		handleGroundItemForDropPending(event.getItem(), event.getTile(),
			event.getNewQuantity() > event.getOldQuantity(), true);
	}

	/** True when a "drop" pending for this item is armed — i.e. this ground pile is one we just dropped. */
	boolean hasArmedDropFor(int item)
	{
		synchronized (invDeltaPendings)
		{
			for (InvDeltaPending p : invDeltaPendings)
			{
				if ("drop".equals(p.base) && p.item == item)
				{
					return true;
				}
			}
		}
		return false;
	}

	// ---- ground-item lifecycle: our own dropped piles, tracked from spawn to removal ----

	/**
	 * Record a pile WE dropped, so a later ItemDespawned on the same tile can be attributed to it.
	 * Called only from the own-tile OWNERSHIP_SELF spawn path, so a foreign pile is never tracked.
	 */
	void trackGroundDrop(int item, long qty, int x, int y, int plane, Map<String, Object> location,
		int dropTick, int despawnTick)
	{
		trackGroundDrop(item, qty, x, y, plane, location, dropTick, despawnTick, false);
	}

	/**
	 * @param quantityMerge true when this arrived as an ItemQuantityChanged growth, meaning the game
	 *                      merged the drop into an existing stack instead of spawning a new pile.
	 */
	void trackGroundDrop(int item, long qty, int x, int y, int plane, Map<String, Object> location,
		int dropTick, int despawnTick, boolean quantityMerge)
	{
		synchronized (groundDrops)
		{
			// A MERGED STACK IS ONE PILE. Dropping a stackable onto a live pile of the same item on
			// the same tile merges it in the game, and the client will fire exactly one
			// ItemDespawned for the result. Tracking a second DroppedGroundItem here made a second
			// session key that no despawn could release (finding F1 path A).
			//
			// FINDING B2: the lookup is ownership-AGNOSTIC on purpose, and it is findGroundDrop —
			// the SAME resolver onItemDespawned uses. So the entry adopted here is exactly the entry
			// that despawn will resolve to. Requiring session membership here is what let one
			// physical pile become two tracked entries whenever the pile predated the session.
			//
			// STILL SCOPED TO A RUNNING SESSION. With no session there are no keys to strand, and
			// two tracked records for one stack is the pre-existing behaviour the ground-removal
			// arms pin: it makes the removal report cause `unknown` rather than fabricate an
			// attribution. Widening the merge branch to the no-session case would change that, and
			// it has nothing to do with this defect.
			DroppedGroundItem merged =
				quantityMerge && dropSession.active() ? findGroundDrop(item, x, y, plane) : null;
			if (merged != null)
			{
				adoptMergedPileIntoDropSession(merged);
				return;
			}
			while (groundDrops.size() >= GROUND_TRACK_MAX)
			{
				// An evicted pile is one we will never see leave the ground. Tell the session, or
				// its key is stranded and the recorder waits on it forever (finding F1 path C).
				abandonPileFromDropSession(groundDrops.pollFirst());
			}
			DroppedGroundItem g =
				new DroppedGroundItem(item, qty, x, y, plane, location, dropTick, despawnTick);
			// The game called this drop a MERGE and the merge branch above did not take it, so this
			// record shadows a pile already on the tile rather than standing for one of its own.
			// FINDING R2 needs that distinction; see DroppedGroundItem.mergeShadow.
			g.mergeShadow = quantityMerge;
			groundDrops.addLast(g);
			attachPileToDropSession(g);
		}
	}

	/**
	 * Resolve a removal or a merge at this item and tile: the RUNNING SESSION'S OWN record first,
	 * then the oldest match.
	 *
	 * ROUND 6, FINDING R1 — WHY OWNERSHIP IS PART OF THE RESOLUTION ORDER. The merge branch above is
	 * scoped to a running session, so with no session a stackable dropped twice onto one tile is
	 * still TWO records for ONE physical pile. The single despawn consumed the OLDEST of them and
	 * left the other on a tile that is now physically empty: a PHANTOM. It is unowned, so no
	 * teardown removes it, and no despawn will ever come for it.
	 *
	 * A later session then dropped on that same tile and the ONE despawn it gets resolved to the
	 * phantom again, because the phantom is older. The session's own key was never released, the
	 * tail never armed, and only MAX_SESSION_MILLIS ended the recording — 30 minutes rather than the
	 * five seconds after the final pile both user-facing strings promise. The invariant backstop
	 * cannot see it either: dropSessionHoldsOwnedPile asks whether the session owns ANY tracked
	 * record, and it still owns the record whose physical pile is gone. The disagreement is between
	 * the tracked RECORD and the PHYSICAL pile, which neither half of that invariant can observe.
	 *
	 * So when a session is running its own record wins. A despawn on a tile the session dropped on
	 * is the session's pile far more often than it is a stale record, and the session's record is
	 * the only one whose resolution can release a recorder key.
	 *
	 * NO-SESSION BEHAVIOUR IS UNCHANGED, deliberately. With no session there is no owner, the loop
	 * falls straight through to the oldest match, and the two-records-for-one-stack attribution the
	 * ground-removal arms pin is exactly as it was. That behaviour makes a removal report `unknown`
	 * rather than fabricate an attribution, and this change must not touch it.
	 *
	 * ONE RESOLVER, BOTH CALLERS. trackGroundDrop's merge lookup and onItemDespawned use this same
	 * method, so the record a merge ADOPTS is exactly the record the despawn will later resolve to.
	 * Finding B2 was caused by those two asking different questions.
	 */
	private DroppedGroundItem findGroundDrop(int item, int x, int y, int plane)
	{
		String sid = dropSession.sessionId();
		synchronized (groundDrops)
		{
			if (sid != null)
			{
				for (DroppedGroundItem g : groundDrops)
				{
					if (g.item == item && g.x == x && g.y == y && g.plane == plane
						&& sid.equals(dropPileSession.get(g)))
					{
						return g;
					}
				}
			}
			for (DroppedGroundItem g : groundDrops)
			{
				if (g.item == item && g.x == x && g.y == y && g.plane == plane)
				{
					return g;
				}
			}
		}
		return null;
	}

	/**
	 * Resolve the ONE ItemDespawned the game fires at this item and tile, and say whether the
	 * choice was a GUESS.
	 *
	 * ROUND 7, FINDING R2 — WHY THE DESPAWN PATH NEEDS ITS OWN RESOLVER. Round 6 made
	 * findGroundDrop prefer the running session's own record, which closed R1. On a tile holding
	 * TWO REAL PILES of the same UNSTACKABLE, only one of them the session's, that preference took
	 * the despawn of the OTHER pile: the session's key was released while its pile was still on the
	 * ground, the recording stopped early, and the manifest claimed COMPLETE on a clip missing the
	 * collection. The row published for the other pile carried our session id, our sequence, our
	 * quantity and our time on ground.
	 *
	 * WHICH PILE WENT IS UNKNOWABLE. The game tells us an item of that id left that tile. It does
	 * not tell us which of two identical piles it was. Round 6 guessed "ours" and round 5 guessed
	 * "the oldest", and both guesses are wrong half the time. So this method REFUSES: it reports the
	 * choice as ambiguous and the callers then decline to claim anything.
	 *
	 *   ATTRIBUTION goes back to the pre-round-6 answer — the oldest UNOWNED record. That is the
	 *   other pile's own record, so the published row is the honest one it always was, with no
	 *   session linkage on it (see attributionAmbiguous).
	 *
	 *   THE RECORDER keeps its key. Our pile may still be lying there, so releasing the key would be
	 *   the early stop all over again. The session is marked unprovable instead, which puts COMPLETE
	 *   permanently out of reach, and it still ends: by the later despawn that is no longer
	 *   ambiguous, by the orphaned-state invariant, or by the 30-minute cap.
	 *
	 * A MERGE SHADOW IS NOT A SECOND PILE, and that is what keeps R1 closed. The R1 phantom is one
	 * physical pile tracked twice, because the merge branch is scoped to a running session: the
	 * second record was minted from a quantityMerge and stands for nothing of its own. Treating it
	 * as a rival pile here would make every R1 route ambiguous again and strand the recorder exactly
	 * as round 3 measured. So only a NON-shadow unowned record can make a despawn ambiguous.
	 */
	static final class GroundDespawnMatch
	{
		final DroppedGroundItem record;
		final boolean ambiguous;

		GroundDespawnMatch(DroppedGroundItem record, boolean ambiguous)
		{
			this.record = record;
			this.ambiguous = ambiguous;
		}
	}

	/** Pure: picks the record and classifies the choice. Changes no state. */
	GroundDespawnMatch matchDespawnedGroundDrop(int item, int x, int y, int plane)
	{
		String sid = dropSession.sessionId();
		if (sid != null)
		{
			DroppedGroundItem owned = null;
			DroppedGroundItem unownedReal = null;
			synchronized (groundDrops)
			{
				// groundDrops is append-ordered, so the first match in each class is the oldest.
				for (DroppedGroundItem g : groundDrops)
				{
					if (g.item != item || g.x != x || g.y != y || g.plane != plane)
					{
						continue;
					}
					if (sid.equals(dropPileSession.get(g)))
					{
						if (owned == null)
						{
							owned = g;
						}
					}
					else if (!g.mergeShadow && unownedReal == null)
					{
						unownedReal = g;
					}
				}
			}
			if (owned != null && unownedReal != null)
			{
				return new GroundDespawnMatch(unownedReal, true);
			}
			if (owned != null)
			{
				return new GroundDespawnMatch(owned, false);
			}
		}
		return new GroundDespawnMatch(findGroundDrop(item, x, y, plane), false);
	}

	/**
	 * Resolve a despawn and APPLY the refusal when the choice was a guess. The one entry point the
	 * despawn path uses, so nothing can resolve a despawn and forget to record the ambiguity.
	 */
	DroppedGroundItem resolveDespawnedGroundDrop(int item, int x, int y, int plane)
	{
		return resolveDespawnedGroundDrop(item, x, y, plane, null);
	}

	/**
	 * Every record THIS SESSION owns for that item on that tile, oldest first.
	 *
	 * ROUND 9. The count of these is |S| in the despawn rule below. groundDrops is append-ordered,
	 * so the returned order is the order the piles were dropped.
	 */
	List<DroppedGroundItem> sessionOwnedPilesAt(int item, int x, int y, int plane)
	{
		List<DroppedGroundItem> out = new ArrayList<>();
		String sid = dropSession.sessionId();
		if (sid == null)
		{
			return out;
		}
		synchronized (groundDrops)
		{
			for (DroppedGroundItem g : groundDrops)
			{
				if (g.item == item && g.x == x && g.y == y && g.plane == plane
					&& sid.equals(dropPileSession.get(g)))
				{
					out.add(g);
				}
			}
		}
		return out;
	}

	/**
	 * A despawning pile that can state its own quantity.
	 *
	 * The live path passes a {@code net.runelite.api.TileItem}, whose {@code getQuantity()} was read
	 * from the resolved runelite-api-1.12.39 jar with javap. The test harness models a physical pile
	 * with its own type, so this interface is the seam that lets both answer the same question
	 * without the harness having to implement the whole TileItem surface.
	 */
	interface DespawnQuantity
	{
		long despawnedQuantity();
	}

	/** The quantity of the pile that is going, or null when nothing can say. */
	static Long despawningQuantity(Object despawnedItem)
	{
		if (despawnedItem instanceof net.runelite.api.TileItem)
		{
			return (long) ((net.runelite.api.TileItem) despawnedItem).getQuantity();
		}
		if (despawnedItem instanceof DespawnQuantity)
		{
			return ((DespawnQuantity) despawnedItem).despawnedQuantity();
		}
		return null;
	}

	/**
	 * ROUND 8, FINDING R4 — THE SCENE DECIDES WHETHER A DESPAWN IS AMBIGUOUS, NOT OUR BOOKKEEPING.
	 *
	 * Round 7 asked "do I hold TWO matching RECORDS?". That question can only see a rival the plugin
	 * TRACKED, and groundDrops only ever holds OWNERSHIP_SELF piles that had an armed drop pending.
	 * Three real piles are invisible to it: another player's pile, our own pile from a session that
	 * ended while the pile was still down (every end path runs endDropSessionTracking, which removes
	 * the records and leaves the PILES), and a pile dropped before the token was linked. When one of
	 * those despawns, round 7 saw exactly one matching record — OURS — called it unambiguous,
	 * released the key, stopped recording five seconds later with our pile still on the ground, and
	 * published COMPLETE with our session id on a row describing somebody else's pile.
	 *
	 * SO THE QUESTION CHANGES to one the game can answer: after this despawn, is there still an item
	 * of this id on this tile? If there is, the despawn is AMBIGUOUS whatever we tracked, because
	 * our pile may be the one still lying there. If there is not, it is unambiguous: nothing of that
	 * kind is left, so our pile went.
	 *
	 * THE SCENE CAN ONLY MAKE A DESPAWN MORE AMBIGUOUS, NEVER LESS. A round-7 ambiguity stands
	 * whatever the scene says. UNKNOWN changes nothing, because a tile out of scene is not an empty
	 * tile and this must not invent certainty from a failed read.
	 *
	 * @param despawnedItem the TileItem that is going, excluded from the scene count by identity, or
	 *                      null. See {@link #scenePileState}.
	 */
	DroppedGroundItem resolveDespawnedGroundDrop(int item, int x, int y, int plane,
		Object despawnedItem)
	{
		GroundDespawnMatch m = matchDespawnedGroundDrop(item, x, y, plane);
		if (m.record != null && m.ambiguous)
		{
			// ROUND 7. Two records matched and one of them is a real rival pile, so the OTHER pile's
			// own record answers the despawn and the flag rides on it. Carried on the RECORD, because
			// a parked removal publishes its row ticks later and must publish the same refusal this
			// despawn decided. Our own record stays tracked and our key stays held.
			m.record.attributionAmbiguous = true;
			dropSession.resolutionAmbiguous(System.currentTimeMillis());
			return m.record;
		}
		// ROUND 9, FINDING R7 — COUNT THE TILE, AND USE THE QUANTITY. DO NOT ASK PRESENCE.
		//
		// Round 8 asked "is an item of this id still on this tile?". That question cannot tell our
		// OWN second pile from a stranger's, so a session that dropped ten piles of one item on one
		// tile had the first nine despawns refused, published one of its ten evidence rows, and that
		// row described the WRONG pile. An ordinary store delivery is exactly that shape.
		//
		// The counting question CAN tell them apart. |S| is how many records this session still owns
		// for that item on that tile, INCLUDING the one this despawn is about to credit. C is how
		// many piles of that id the scene still shows, with the despawning TileItem excluded by
		// identity. After this removal the scene holds C piles while we still claim |S|, so:
		//
		//   C >= |S|  AMBIGUOUS. At least as many piles are left as we own, so at least one of them
		//             is not ours, and the one that left may equally have been that stranger's.
		//   C <  |S|  UNAMBIGUOUS. There are fewer piles left than we own, so one of OURS went.
		//
		// ONLY a despawn about to be credited to our own pile is tested. A record that is not ours
		// releases no key and claims no session linkage, so there is nothing here for the scene to
		// protect. UNKNOWN keeps round-8 behaviour: no refusal is ever inferred from a failed read,
		// and the invariant and the hard cap remain the backstops.
		if (m.record != null
			&& dropSession.sessionId() != null
			&& dropSession.sessionId().equals(dropSessionForPile(m.record)))
		{
			SceneTileItems scene = sceneTileItems(item, x, y, plane, despawnedItem);
			if (scene.state != ScenePileState.UNKNOWN)
			{
				List<DroppedGroundItem> own = sessionOwnedPilesAt(item, x, y, plane);
				if (scene.count >= own.size())
				{
					// THE DESPAWN IS REFUSED WHOLE, which is the round-7 handling with no rival
					// record to hand it to. Returning null leaves our record TRACKED and our key
					// HELD, so the tail cannot arm while our pile may still be down, and publishes
					// NO row: a row built from our record would describe a pile that did not
					// necessarily go, which is the fabricated attribution round 7 exists to refuse.
					//
					// attributionAmbiguous is deliberately NOT set on our record. Our pile is still
					// down and its own later removal may be perfectly attributable; the flag never
					// clears, so setting it here would refuse an honest linkage we have not yet
					// lost. COMPLETE is already out of reach through the recorder, which is the
					// property that matters.
					dropSession.resolutionAmbiguous(System.currentTimeMillis());
					return null;
				}
				if (own.size() > 1)
				{
					return chooseOwnPileByQuantity(own, despawnedItem);
				}
			}
		}
		return m.record;
	}

	/**
	 * ROUND 9 — WHICH of our own piles just left, when several of ours are on that tile.
	 *
	 * The count already proved one of OURS went. The QUANTITY says which one.
	 * {@code TileItem.getQuantity()} was read from runelite-api-1.12.39 with javap.
	 *
	 * <ul>
	 * <li>EXACTLY ONE of our records carries that quantity: that is the pile, with its own
	 *     drop_seq, its own ticks_on_ground and its own qty. This is the ordinary delivery.</li>
	 * <li>SEVERAL of our records carry it: they are indistinguishable BY QUANTITY, and nothing else
	 *     on the tile can separate them. The oldest is released so its row is published, and ONLY
	 *     that row's attribution is marked uncertain. The session is NOT marked unprovable: every
	 *     candidate is ours, every quantity is the same, and the row's own qty is right. Refusing
	 *     the whole session over two of our own equal piles would be FINDING R7 again.</li>
	 * <li>NONE of our records carries it, or nothing could state the despawning quantity: a pile of
	 *     a size we never dropped left that tile, so it was a stranger's. Refuse.</li>
	 * </ul>
	 */
	private DroppedGroundItem chooseOwnPileByQuantity(List<DroppedGroundItem> own,
		Object despawnedItem)
	{
		Long q = despawningQuantity(despawnedItem);
		List<DroppedGroundItem> matches = new ArrayList<>();
		if (q != null)
		{
			for (DroppedGroundItem g : own)
			{
				if (g.qty == q)
				{
					matches.add(g);
				}
			}
		}
		if (matches.isEmpty())
		{
			dropSession.resolutionAmbiguous(System.currentTimeMillis());
			return null;
		}
		DroppedGroundItem chosen = matches.get(0);	// oldest, groundDrops is append-ordered
		if (matches.size() > 1)
		{
			chosen.qtyTieUncertain = true;
		}
		return chosen;
	}

	void clearGroundDrops()
	{
		synchronized (groundDrops)
		{
			groundDrops.clear();
		}
		synchronized (telegrabSightings)
		{
			telegrabSightings.clear();
		}
	}

	/** True when a pile we track (live or parked for a Take) lies on this tile. */
	boolean isTrackedPileTile(int x, int y, int plane)
	{
		synchronized (groundDrops)
		{
			for (DroppedGroundItem g : groundDrops)
			{
				if (g.x == x && g.y == y && g.plane == plane)
				{
					return true;
				}
			}
		}
		synchronized (pendingRemovals)
		{
			for (DroppedGroundItem g : pendingRemovals.keySet())
			{
				if (g.x == x && g.y == y && g.plane == plane)
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Record one Telekinetic Grab sighting when it targets a tracked pile's tile. Prunes rows older than
	 * the attribution window and keeps at most TELEGRAB_SIGHTING_CAP (oldest dropped).
	 */
	void recordTelegrabSighting(DropCandidates.TelegrabSighting s)
	{
		if (s == null || !isTrackedPileTile(s.x, s.y, s.plane))
		{
			return;
		}
		synchronized (telegrabSightings)
		{
			telegrabSightings.removeIf(o -> s.tick - o.tick > DropCandidates.TELEGRAB_WINDOW_TICKS || o.tick > s.tick);
			telegrabSightings.add(s);
			while (telegrabSightings.size() > TELEGRAB_SIGHTING_CAP)
			{
				telegrabSightings.remove(0);
			}
		}
	}

	/**
	 * A Telekinetic Grab projectile in flight. Recorded once per projectile, with its caster, when it
	 * targets the tile of a pile we track. Other projectiles return on the first id compare.
	 */
	@Subscribe
	public void onProjectileMoved(net.runelite.api.events.ProjectileMoved event)
	{
		if (!staffCaptureEnabled() || client == null || event == null || event.getProjectile() == null
			|| event.getProjectile().getId() != DropCandidates.TELEGRAB_PROJECTILE)
		{
			return;
		}
		net.runelite.api.Projectile pr = event.getProjectile();
		if (!telegrabProjectilesSeen.add(pr))
		{
			return;
		}
		WorldPoint target = pr.getTargetPoint();
		if (target == null && event.getPosition() != null)
		{
			target = WorldPoint.fromLocal(client, event.getPosition());
		}
		if (target == null)
		{
			return;
		}
		Actor src = pr.getSourceActor();
		boolean self = src != null && src == client.getLocalPlayer();
		String caster = src == null || src.getName() == null ? null : Text.removeTags(src.getName());
		WorldPoint from = src != null && src.getWorldLocation() != null ? src.getWorldLocation() : pr.getSourcePoint();
		recordTelegrabSighting(new DropCandidates.TelegrabSighting(target.getX(), target.getY(), target.getPlane(),
			client.getTickCount(), "projectile", self ? null : caster, self,
			from == null ? target.getX() : from.getX(), from == null ? target.getY() : from.getY()));
	}

	/** A Telekinetic Grab impact graphic. It carries no caster, only the tile. */
	@Subscribe
	public void onGraphicsObjectCreated(net.runelite.api.events.GraphicsObjectCreated event)
	{
		if (client == null || event == null || event.getGraphicsObject() == null
			|| event.getGraphicsObject().getId() != DropCandidates.TELEGRAB_IMPACT
			|| event.getGraphicsObject().getLocation() == null)
		{
			return;
		}
		net.runelite.api.GraphicsObject go = event.getGraphicsObject();
		WorldPoint wp = WorldPoint.fromLocal(client, go.getLocation());
		if (wp == null)
		{
			return;
		}
		recordTelegrabSighting(new DropCandidates.TelegrabSighting(wp.getX(), wp.getY(), go.getLevel(),
			client.getTickCount(), "impact", null, false, wp.getX(), wp.getY()));
	}

	int groundDropCount()
	{
		synchronized (groundDrops)
		{
			return groundDrops.size();
		}
	}

	/**
	 * Could this Take have been aimed at this pile?
	 *
	 * Item, and the tile whenever the client gave us one. A Take the client gave NO tile for could
	 * have been aimed at any pile of its item, so it matches all of them here.
	 *
	 * This is the ONLY match rule in the narrow candidate, and it is used in both directions. To
	 * WEAKEN a verdict, one match is enough: the pile may have been ours. To CLAIM a pile, the
	 * caller additionally requires that it be the ONLY match, so a no-tile Take against two piles
	 * claims neither, and a tiled Take against two piles on that tile claims neither. Identity comes
	 * from the uniqueness, not from the tile alone, and the two directions can never disagree
	 * because there is only one predicate.
	 */
	static boolean takeCouldName(InvDeltaPending take, DroppedGroundItem g)
	{
		return g.item == take.item && (take.takeX < 0
			|| (g.x == take.takeX && g.y == take.takeY && g.plane == take.takePlane));
	}

	/**
	 * Every pile we still hold state for: on the ground, and parked awaiting a verdict.
	 *
	 * One snapshot, because a pile the Take named may already have despawned - which is the ORDINARY
	 * case for a completed pickup, since the despawn callback runs before the inventory change.
	 * Taken under both locks, then released, so callers iterate a copy and never hold two at once.
	 */
	private List<DroppedGroundItem> trackedPiles()
	{
		List<DroppedGroundItem> all = new ArrayList<>();
		synchronized (pendingRemovals)
		{
			all.addAll(pendingRemovals.keySet());
		}
		synchronized (groundDrops)
		{
			all.addAll(groundDrops);
		}
		return all;
	}

	/**
	 * Mark every tracked pile a Take on this item and tile could have been aimed at.
	 *
	 * Run at CLICK time, not at resolution time. A Take is pruned by any unrelated inventory change,
	 * and a store account's inventory changes constantly, so waiting until the arrival lands loses
	 * the flag exactly when the walk was long enough to matter - and the pile then published
	 * `removed_early` over our own recovery.
	 */
	private void flagTakeArmedPiles(InvDeltaPending take)
	{
		for (DroppedGroundItem g : trackedPiles())
		{
			g.takeArmed = g.takeArmed || takeCouldName(take, g);
		}
	}

	/**
	 * True when a local Take that could explain THIS pile is still in flight.
	 *
	 * Used only to DEFER a removal, never to attribute one. Matching on item id alone made a Take on
	 * a stranger's pile ten tiles away defer our pile's removal, which delayed a verdict that was
	 * already knowable.
	 */
	boolean hasArmedPickupFor(DroppedGroundItem g)
	{
		synchronized (invDeltaPendings)
		{
			for (InvDeltaPending p : invDeltaPendings)
			{
				if ("pickup".equals(p.base) && takeCouldName(p, g))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * The ONE tracked pile this Take could have been aimed at, or null when there is not exactly one.
	 *
	 * Two candidates are indistinguishable to the client, so nothing is claimed and both report
	 * `unknown`. That covers two piles on one tile and a no-tile Take against two piles of its item
	 * with the same rule. Looks in both collections because the pile may already have despawned and
	 * be parked awaiting its verdict, which is the ordinary case for a completed pickup.
	 */
	private DroppedGroundItem soleClaimablePile(InvDeltaPending take)
	{
		DroppedGroundItem found = null;
		for (DroppedGroundItem g : trackedPiles())
		{
			if (!g.selfPickedUp && takeCouldName(take, g))
			{
				if (found != null)
				{
					return null;	// two candidates: indistinguishable, so claim neither
				}
				found = g;
			}
		}
		return found;
	}

	/**
	 * Attribute a recovered pile to a Take, but ONLY when the evidence is unambiguous.
	 *
	 * Every condition below is necessary and none is negotiable, because the failure this guards
	 * against is naming a staff member as the taker of a pile a CUSTOMER collected:
	 *
	 *   * exactly ONE armed Take of the item in this pass - two Takes and the client cannot say
	 *     which one the server actually ran, and OSRS runs the LAST click of a burst while the
	 *     queue hands the arrival to the FIRST pending;
	 *   * exactly ONE tracked pile that Take could have been aimed at - two piles on the tile, or a
	 *     no-tile Take against two piles of the item, name nothing;
	 *   * the measured gain equals that pile EXACTLY - a ground pile is recovered whole, so a
	 *     1,500-coin store sale is not a 1,200-coin pile.
	 *
	 * The Take's own freshness is enforced earlier, in `resolveOnePending`: a Take past its window
	 * is discarded before it can produce a `pickup` row at all, so it cannot reach this method.
	 *
	 * Anything else marks nothing. The pile keeps its `takeArmed` flag and reports `unknown`, which
	 * is the truthful answer: we may well have taken it, so `removed_early` would be as wrong as
	 * claiming the pickup.
	 *
	 * @return true when a pile was marked, so the caller can publish it at once.
	 */
	private boolean markGroundDropSelfPickedUp(InvDeltaPending take, long rawGain,
		List<InvDeltaPending> snapshot, int currentTick)
	{
		if (take == null)
		{
			return false;
		}
		for (InvDeltaPending other : snapshot)
		{
			if (other != take && "pickup".equals(other.base) && other.item == take.item)
			{
				return false;	// a second armed Take: nothing says which click the server ran
			}
		}
		DroppedGroundItem g = soleClaimablePile(take);
		if (g == null || rawGain != g.qty)
		{
			return false;
		}
		g.selfPickedUp = true;
		// A pile still lying on the ground has NOT been recovered yet, whatever the inventory did.
		// Record the tick, so the removal can check the pile really left. See `provisionalMarkTick`.
		if (stillOnGround(g))
		{
			g.provisionalMarkTick = currentTick;
		}
		return true;
	}

	/** True while the pile is still lying on the ground, so its removal has not been observed yet. */
	private boolean stillOnGround(DroppedGroundItem g)
	{
		synchronized (groundDrops)
		{
			return groundDrops.contains(g);
		}
	}

	/**
	 * Finalize removals whose resolution window has closed, or whose pickup has landed.
	 *
	 * A pile marked `selfPickedUp` finalizes at once - the evidence is in. One that ran out of
	 * window finalizes on what can actually be proven, which is never `self_pickup`. Called from the
	 * tick hook and again whenever a pickup resolves, so the common case publishes immediately
	 * rather than waiting out the window.
	 */
	/**
	 * @param tickPass true only for the once-per-tick call. The budget counts TICKS, not calls: a
	 * pickup resolving re-enters this method, so counting every call let ten pickups landing in one
	 * tick spend the whole budget of every other parked pile. The re-entrant call exists to PUBLISH
	 * a pile whose answer just arrived, never to age one.
	 */
	/**
	 * @param unreliable true for the lifecycle disarms, which take EVERY parked entry and publish it
	 * as `unknown`. Observation is genuinely unreliable across a hop, a logout or a region boundary,
	 * so no stronger cause is supportable there.
	 * @param tickPass true only for the once-per-tick call. The attempt budget counts TICKS, not
	 * calls: a pickup resolving re-enters this method, so counting every call let ten pickups landing
	 * in one tick spend the whole budget of every other parked pile. The re-entrant call exists to
	 * PUBLISH a pile whose answer just arrived, never to age one.
	 */
	void settlePendingRemovals(int currentTick, boolean tickPass, boolean unreliable)
	{
		Map<DroppedGroundItem, Integer> due = new LinkedHashMap<>();
		synchronized (pendingRemovals)
		{
			java.util.Iterator<java.util.Map.Entry<DroppedGroundItem, Integer>> it =
				pendingRemovals.entrySet().iterator();
			while (it.hasNext())
			{
				java.util.Map.Entry<DroppedGroundItem, Integer> e = it.next();
				int waited = currentTick - e.getValue();
				// `waited < 0` means the tick counter moved BACKWARDS under us; `settleAttempts`
				// counts attempts instead of trusting the clock, because a counter that is FROZEN
				// never lets the difference reach the window either. Without both, the entry strands
				// in the map forever and its event is lost. Finalize: a late verdict beats none.
				if (tickPass)
				{
					e.getKey().settleAttempts++;
				}
				if (unreliable || e.getKey().selfPickedUp || waited >= REMOVAL_RESOLVE_MAX_TICKS
					|| waited < 0 || e.getKey().settleAttempts > REMOVAL_RESOLVE_MAX_TICKS)
				{
					due.put(e.getKey(), e.getValue());
					it.remove();		// removed as it fires - never two finals for one lifecycle
				}
			}
		}
		for (Map.Entry<DroppedGroundItem, Integer> e : due.entrySet())
		{
			// The tick the pile ACTUALLY left the ground, not the tick we got around to concluding.
			// Passing `currentTick` here let up to REMOVAL_RESOLVE_MAX_TICKS of drift cross the
			// despawn deadline, silently turning a genuine `removed_early` into `despawn_timer` -
			// a STRONGER claim than the evidence supports, and the opposite of failing closed.
			emitGroundRemoval(e.getKey(), e.getValue(), unreliable || groundObservationUnreliable);
		}
	}

	/**
	 * Discard the parked removals - but PUBLISH them first, as `unknown`.
	 *
	 * A region boundary, a hop or a logout can land inside the resolution window. Clearing the map
	 * silently made the pile's removal vanish from the record entirely, which is worse than the
	 * weaker verdict the same event got before it was ever deferred: a delivery simply disappeared.
	 * Observation is genuinely unreliable across these transitions, so the honest cause is `unknown`
	 * and never `despawn_timer` or `removed_early`. Each entry is emitted at the tick it was
	 * actually removed, and removed from the map as it fires, so this cannot double-emit.
	 */
	void clearPendingRemovals()
	{
		settlePendingRemovals(client == null ? 0 : client.getTickCount(), false, true);
	}

	/**
	 * Our dropped pile left the ground. Emit what we can HONESTLY say, and nothing more.
	 *
	 * `cause` is the whole point of this event and has exactly three values:
	 *   "self_pickup"   — our own account took it back; we saw the inventory rise, so this is certain.
	 *   "despawn_timer" — removal happened at or after the client's own reported despawn deadline.
	 *                     Nobody took it; it timed out.
	 *   "removed_early" — the pile went BEFORE its deadline while we were watching normally.
	 *
	 * "removed_early" means SOMETHING removed it early. It does NOT mean a customer collected it,
	 * and it names nobody. A different player picking it up and an unobserved client-side quirk are
	 * indistinguishable here, which is why the field says removed, not delivered. Any consumer that
	 * renders this as a delivery is reading it wrong.
	 *
	 * When observation was unreliable (scene reload, hop, logout, render-distance loss) the cause is
	 * "unknown" — the ambiguity is preserved explicitly rather than resolved by guessing.
	 */
	/**
	 * May a pile a Take once named still report `despawn_timer`? Only at its OWN deadline.
	 *
	 * `takeArmed` is set at click time and never clears, so a Take the client gave no tile for costs
	 * every same-item pile its timer evidence for the whole pile lifetime. This buys that evidence
	 * back in the one case where the Take cannot explain anything, and every condition is required:
	 *
	 *   * observation was reliable, and the client did report a deadline for this pile;
	 *   * the pile left AT that deadline, inside the margin on BOTH sides - so this can only ever
	 *     produce `despawn_timer`, never `removed_early`, which is the label the old
	 *     withholding-expiry rule got wrong (round 8). The upper bound matters as much as the lower
	 *     one: a removal a hundred ticks PAST a deadline means the record does not describe the pile
	 *     that just left, which is the merged-stack double-tracking residual, and a stale record
	 *     must never be read as a timer expiry;
	 *   * NO Take of this item is still live, so nothing in flight could still explain the removal,
	 *     and no Take was live when the pile actually LEFT the ground either - a Take that expired
	 *     while the removal sat parked still explains that removal, so the pile stays ambiguous;
	 *   * no gain was ever claimed for this pile, provisionally or otherwise - a claim that was made
	 *     and then withdrawn leaves the pile ambiguous, and ambiguous stays `unknown`.
	 *
	 * This method does NOT repeat the GROUND_TIMER_MIN_TICKS floor. Passing here only clears the way
	 * to the deadline branch below, which applies that floor itself, so a pile removed too fast for a
	 * real timer still reads `unknown`. `theTimerFloorStillRefusesAnImplausiblyFastExpiry` proves it.
	 *
	 * The reset is bound to the pile's own deadline and to nothing else. Resetting on TAKE EXPIRY
	 * instead is round 8 again: a walk longer than the Take window would publish our own recovery as
	 * `removed_early`. `aTakeThatExpiredWithThePileStillOnTheGroundStaysUnknown` holds that line.
	 */
	private boolean timerExpiryIsStillProvable(DroppedGroundItem g, int currentTick,
		boolean observationUnreliable)
	{
		return !observationUnreliable
			&& g.despawnTick >= 0
			&& currentTick >= g.despawnTick - GROUND_EARLY_MARGIN_TICKS
			&& currentTick <= g.despawnTick + GROUND_EARLY_MARGIN_TICKS
			&& g.provisionalMarkTick < 0
			&& !g.parkedForLiveTake
			&& !hasArmedPickupFor(g);
	}

	void emitGroundRemoval(DroppedGroundItem g, int currentTick, boolean observationUnreliable)
	{
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("item", g.item);
		fields.put("qty", g.qty);
		if (g.location != null)
		{
			fields.put("location", g.location);
		}
		fields.put("ticks_on_ground", Math.max(0, currentTick - g.dropTick));
		// Reconcile a PROVISIONAL mark against what the pile actually did. A pile we truly recovered
		// leaves the ground in the same tick, or in the next tick or two. One still lying there long
		// after the gain was never the source of that gain, so the mark is withdrawn and `takeArmed`
		// carries the row to `unknown`. This branch only WEAKENS: it never sets `selfPickedUp`.
		//
		// A NEGATIVE wait means the tick counter moved BACKWARDS under us, so the removal cannot be
		// timed against the mark at all. A bare `> margin` test reads every negative difference as
		// "inside the margin" and keeps the claim, which is the strongest reading of the weakest
		// evidence. `settlePendingRemovals` already treats `waited < 0` as a reason to stop trusting
		// the clock; the provisional path does the same and withdraws.
		int sinceMark = currentTick - g.provisionalMarkTick;
		if (g.selfPickedUp && g.provisionalMarkTick >= 0
			&& (sinceMark < 0 || sinceMark > GROUND_EARLY_MARGIN_TICKS))
		{
			g.selfPickedUp = false;
		}
		String cause;
		if (g.selfPickedUp)
		{
			cause = "self_pickup";
		}
		else if (g.takeArmed && !timerExpiryIsStillProvable(g, currentTick, observationUnreliable))
		{
			// A local Take named this pile and the recovery was not proven exactly. `removed_early`
			// would read as somebody else taking it and `despawn_timer` as nobody taking it, and we
			// can support neither. Refusing to attribute must not become a different wrong answer.
			cause = "unknown";
		}
		else if (observationUnreliable)
		{
			cause = "unknown";
		}
		else if (g.despawnTick < 0)
		{
			cause = "unknown";	// the client never reported a deadline — we cannot call early vs timer
		}
		else if (currentTick >= g.despawnTick - GROUND_EARLY_MARGIN_TICKS)
		{
			// FAIL CLOSED. `despawnTick` is an ABSOLUTE future tick (measured live 2026-09-12:
			// tick=244 while despawn_time=530 on a freshly dropped pile), so a pile that genuinely
			// reaches its deadline has been on the ground for the full timer. A removal that
			// satisfies the comparison after only a handful of ticks means the deadline we stored
			// does not describe this pile - a stale baseline, a re-tracked tile, a client whose tick
			// counter moved under us. Saying "nobody took it" there is an assertion we cannot
			// support. Unknown is the honest answer; a wrong cause is worse than no cause.
			cause = (currentTick - g.dropTick) < GROUND_TIMER_MIN_TICKS ? "unknown" : "despawn_timer";
		}
		else
		{
			cause = "removed_early";
		}
		fields.put("cause", cause);
		// Stated on every row so no downstream reader has to know this rule: the taker is never observable.
		fields.put("recipient", "UNKNOWN");
		// DROP-SESSION LINKAGE. Written on every removal of a session pile, whatever the cause, so a
		// self-pickup and a despawn join the manifest exactly like an early removal does. A removal
		// that carries no session id simply predates the feature or happened outside a session.
		// FINDING R2. An AMBIGUOUS despawn resolved between two real piles of one item on one tile
		// and could not know which went. Naming our session on that row would be a fabricated
		// attribution, so the row carries no linkage at all. `cause` is left to the ordinary rules,
		// which already answer `unknown` when the evidence does not support a claim.
		String dropSid = g.attributionAmbiguous ? null : dropSessionForPile(g);
		int dropSeq = dropSeqForPile(g);
		boolean resolvedForAudit = false;
		if (dropSid != null)
		{
			fields.put("drop_session_id", dropSid);
			fields.put("drop_seq", dropSeq);
			// ROUND 9. Two or more of OUR OWN piles of this item on this tile carried the same
			// quantity, so which of them left cannot be told apart. The linkage and the qty are
			// still ours and still right; only drop_seq and ticks_on_ground name one of several
			// equal candidates. Said on the row rather than hidden, so a reader is never misled.
			if (g.qtyTieUncertain)
			{
				fields.put("attribution_uncertain", "equal_quantity_own_piles");
			}
		}
		// The pile's own tile, on every row. A reader must be able to locate the pile without
		// knowing where our character stood, and the candidate offsets below are relative to THIS.
		Map<String, Object> tile = new LinkedHashMap<>();
		tile.put("x", g.x);
		tile.put("y", g.y);
		tile.put("plane", g.plane);
		fields.put("tile", tile);
		// A Telekinetic Grab aimed at THIS tile just before it went. A grab takes the pile from range, so
		// a player standing on the tile may be a bystander; the reader must know. Absent when none seen.
		// Not on a self-pickup: our own Take already explains the removal.
		if (!"self_pickup".equals(cause))
		{
			Map<String, Object> grab;
			synchronized (telegrabSightings)
			{
				grab = DropCandidates.telegrabAt(telegrabSightings, g.x, g.y, g.plane, currentTick);
			}
			if (grab != null)
			{
				fields.put("telegrab", grab);
			}
		}
		// Who was standing here when an early removal happened. The pickup itself runs in another
		// player's client, so this is EVIDENCE, never an answer: it goes out under the same
		// `taken_by_candidates` inference field the store handoff uses, for the server-side resolver
		// (one candidate at dist 0 -> counterparty, anything else stays UNKNOWN). Only `removed_early`
		// carries it: presence at a timer expiry or a self-pickup says nothing about a taker.
		// The key is absent when nobody is around, matching the store path, so readers keep one rule.
		if ("removed_early".equals(cause))
		{
			// PILE-CENTRED, not player-centred. The old snapshot measured from OUR character, which
			// answers the wrong question: in a drop trade the staff member walks off before the
			// customer arrives, so a player at distance 0 from us is not on the pile and a player on
			// the pile can be many tiles away. Measured from the pile's own tile instead.
			List<Map<String, Object>> present =
				DropCandidates.candidatesAt(observedPlayers(), g.x, g.y, g.plane);
			if (!present.isEmpty())
			{
				fields.put("taken_by_candidates", present);
			}
			// Resolve ONLY on exactly one player standing on the pile's tile. Two on it is
			// AMBIGUOUS, an empty tile is UNKNOWN, and neither ever names anybody. The Take itself
			// happens in the other client and nothing in our stream proves it.
			String resolved = fields.containsKey("telegrab") ? null : DropCandidates.resolveCounterparty(present);
			String status = DropCandidates.statusFor(present, resolved);
			fields.put("counterparty_status", status);
			if (resolved != null)
			{
				resolvedForAudit = true;
				// `counterparty_inferred`, never `counterparty`. The trade path's `counterparty` is
				// read from the trade window and IS the other party; this one is an inference from
				// where somebody stood, and the field name has to keep those apart.
				fields.put("counterparty_inferred", resolved);
			}
		}
		else
		{
			// Self-pickup, despawn timer and unknown all carry the status too, so a reader never has
			// to infer "no status means nobody asked" from an absent key.
			fields.put("counterparty_status", DropCandidates.STATUS_UNKNOWN);
		}
		emitEvent("ground_removed", fields);
		noteDropAuditRemoval(dropSid, resolvedForAudit);
		// Tell the session this pile is gone. When it is the last one, the 5-second tail arms.
		releasePileFromDropSession(g);
	}

	/**
	 * RuneLite fires ItemDespawned for a pile leaving the ground — taken, timed out, or simply
	 * out of scene. Only piles WE dropped and are still tracking reach an emit.
	 */
	@Subscribe
	public void onItemDespawned(net.runelite.api.events.ItemDespawned event)
	{
		if (event != null && gameplayReady()) ownGameplay.groundClues.despawned(client, event.getItem(), System.currentTimeMillis());
		if (client == null || event == null || event.getItem() == null || event.getTile() == null)
		{
			return;
		}
		net.runelite.api.coords.WorldPoint tw = event.getTile().getWorldLocation();
		if (tw == null)
		{
			return;
		}
		DroppedGroundItem g = resolveDespawnedGroundDrop(
			event.getItem().getId(), tw.getX(), tw.getY(), tw.getPlane(), event.getItem());
		if (g == null)
		{
			// Not one of ours — every other pile on the map despawns constantly — OR the scene
			// refused this despawn because an item of that id is still on the tile (round 8).
			return;
		}
		synchronized (groundDrops)
		{
			groundDrops.remove(g);
		}
		int now = client.getTickCount();
		// Do NOT conclude yet if a local Take for this item is still in flight: the inventory gain
		// that proves it arrives AFTER this callback. Hold the removal for a bounded window and let
		// whatever actually resolves decide the cause. Piles with no pending Take finalize
		// immediately, so ordinary despawns are not delayed at all.
		if (!g.selfPickedUp && hasArmedPickupFor(g))
		{
			g.takeArmed = true;
			// Recorded HERE, at removal time, and never re-derived at settlement: the Take that
			// justified parking this pile can expire or be pruned before the row is published.
			g.parkedForLiveTake = true;
			synchronized (pendingRemovals)
			{
				pendingRemovals.put(g, now);
			}
			return;
		}
		emitGroundRemoval(g, now, groundObservationUnreliable);
	}

	/**
	 * Classify a menu click as an off-book value action: "drop" (inventory Drop), "pickup" (ground Take), or
	 * "alch_high"/"alch_low" (High/Low Level Alchemy cast). Alch menu shape varies — option "Cast High Level
	 * Alchemy", or option "Cast" with the spell name in the target — so it matches the spell name across the
	 * combined option+target text. Returns null for anything else. Static + pure (no client) so it is unit-testable.
	 */
	static String offBookMenuAction(MenuOptionClicked event)
	{
		String opt = event.getMenuOption() == null ? "" : event.getMenuOption();
		if (opt.equals("Drop"))
		{
			return "drop";
		}
		if (opt.equals("Take"))
		{
			return "pickup";
		}
		if (opt.startsWith("Cast"))
		{
			String combined = opt + " " + (event.getMenuTarget() == null ? "" : event.getMenuTarget());
			if (combined.contains("High Level Alchemy"))
			{
				return "alch_high";
			}
			if (combined.contains("Low Level Alchemy"))
			{
				return "alch_low";
			}
		}
		return null;
	}

	/**
	 * Resolve an armed pickup/alch pending against the post-change inventory. pickup fires when the item count
	 * ROSE (an inventory removal can't fake a rise); alch fires only when the item fell AND coins rose in the
	 * same change (an alch always yields coins — an item removal without a coin gain is an equip/bank/destroy,
	 * never an alch). "drop" pendings NEVER resolve here: an inventory removal alone could be a bank deposit /
	 * destroy / equip, so drops resolve exclusively via ground-spawn confirmation
	 * (resolveDropPendingOnGroundSpawn) — this path only expires a stale drop pending. Unrelated inventory
	 * changes are ignored and the pending kept until it lands or its tick window expires (so a "Take" that
	 * completes after a short walk still logs). Package-private + primitive args so it is unit-testable.
	 */
	void resolveInvDeltaPending(long itemCountAfter, long coinsAfter, int currentTick)
	{
		// Head-only entry point, kept for the single-pending call shape. The live client path uses
		// resolveInvDeltaPendings(ItemContainer, ...) instead, which walks EVERY armed pending: with a queue,
		// an unconfirmed drop sits at the head and would otherwise hide a later pickup behind it forever.
		InvDeltaPending p = peekInvDeltaPending();
		if (p == null)
		{
			return;
		}
		resolveOnePending(p, itemCountAfter, coinsAfter, currentTick,
			java.util.Collections.singletonList(p));
	}

	/**
	 * Resolve EVERY armed pending against one inventory change, each against ITS OWN item count.
	 *
	 * A single pending slot could rely on the head being the only candidate. A queue cannot: a Drop whose
	 * ground spawn never arrives stays armed for DROP_PENDING_MAX_TICKS, and while it sits at the head a
	 * real "Take" armed behind it resolves against nothing and is lost. The pre-queue build hid this because
	 * a fresh click overwrote the stale pending. Walking the queue is what keeps a self-pickup observable.
	 */
	void resolveInvDeltaPendings(ItemContainer inv, long coinsAfter, int currentTick)
	{
		List<InvDeltaPending> snapshot;
		synchronized (invDeltaPendings)
		{
			if (invDeltaPendings.isEmpty())
			{
				return;
			}
			snapshot = new ArrayList<>(invDeltaPendings);
		}
		// ONE unit of evidence resolves ONE pending. Every pending is measured against the same
		// container, so two Takes of the same item armed on the same tick share a `beforeCount` and a
		// SINGLE arriving item satisfied both: two `pickup` rows and doubled quantities for one real
		// recovery. A resolved pickup therefore raises every other still-armed pickup's baseline by
		// what it consumed.
		for (InvDeltaPending p : snapshot)
		{
			long used = resolveOnePending(p, countItem(inv, p.item), coinsAfter, currentTick, snapshot);
			if (used > 0 && "pickup".equals(p.base))
			{
				for (InvDeltaPending other : snapshot)
				{
					if (other != p && "pickup".equals(other.base) && other.item == p.item)
					{
						other.beforeCount += used;
					}
				}
			}
		}
	}

	/**
	 * Resolve exactly ONE armed pending. Removes it only when its own signals landed or its window
	 * expired. Returns the quantity it CONSUMED, so the caller can withhold that evidence from the
	 * remaining pendings; 0 when nothing landed.
	 */
	private long resolveOnePending(InvDeltaPending p, long itemCountAfter, long coinsAfter,
		int currentTick, List<InvDeltaPending> snapshot)
	{
		// Resolution removes ONE pending — the one whose signals landed. The lifecycle disarms (logout, hop,
		// disconnect, death) are the only places that clear them all; a single item's loss must never discard
		// another item's armed drop, which is the whole point of the queue.
		if ("drop".equals(p.base))
		{
			// Order-independence: if a matching ground spawn already corroborated (spawn processed before the
			// inventory decrement) and the loss now lands within the corroboration window, complete the emit.
			long dropDelta = p.beforeCount - itemCountAfter;
			int spawnTick = p.spawnCorroboratedTick;
			if (dropDelta > 0 && spawnTick >= 0 && currentTick - spawnTick <= DROP_CORROBORATION_MAX_TICKS)
			{
				removeInvDeltaPending(p);
				emitDropEvent(p, dropDelta);
				return dropDelta;
			}
			if (dropDelta > 0 && spawnTick < 0 && p.lossBuildSeq < 0)
			{
				p.lossBuildSeq = triggerChangeBuildSeq;	// the loss is this change; its spawn completes the row
			}
			if (currentTick - p.tick > DROP_PENDING_MAX_TICKS)
			{
				removeInvDeltaPending(p);	// no ground spawn confirmed it — expire silently, emit nothing
			}
			return 0;
		}
		if ("pickup".equals(p.base) && currentTick - p.tick > INV_DELTA_PENDING_MAX_TICKS)
		{
			// A Take past its OWN window is no longer evidence about anything, whether or not an
			// item arrived. The window used to be checked only when nothing landed, so a Take
			// clicked but never served stayed armed forever and the next same-item gain revived it:
			// a customer's collection published as ours, and a `pickup` row for a recovery that
			// never happened. Expire it silently and emit nothing.
			removeInvDeltaPending(p);
			return 0;
		}
		long delta = "pickup".equals(p.base) ? (itemCountAfter - p.beforeCount) : (p.beforeCount - itemCountAfter);
		long gp = coinsAfter - p.beforeCoins;
		boolean landed = delta > 0 && (!"alch".equals(p.base) || gp > 0);
		if (!landed)
		{
			int window = "pickup".equals(p.base) ? INV_DELTA_PENDING_MAX_TICKS : ALCH_PENDING_MAX_TICKS;
			if (currentTick - p.tick > window)
			{
				removeInvDeltaPending(p);
			}
			return 0;
		}
		removeInvDeltaPending(p);	// consume — the expected delta landed
		if (!activityLogActive())
		{
			return delta;
		}
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("item", p.item);
		fields.put("qty", delta);
		if ("alch".equals(p.base))
		{
			fields.put("spell", p.spell);
			fields.put("gp", gp);	// always present now — the coin gain is the alch confirmation itself
			emitEvent("alch", fields);
			return delta;
		}
		if (p.location != null)
		{
			fields.put("location", p.location);
		}
		// If this recovers a pile WE dropped, say so on the pile: its later removal is then explained
		// as self_pickup rather than counted as an ambiguous early removal. The rule is deliberately
		// strict — see markGroundDropSelfPickedUp. Anything it refuses leaves the pile `unknown`.
		if (markGroundDropSelfPickedUp(p, delta, snapshot, currentTick))
		{
			// The pile may already be waiting on this answer; publish now rather than idle out the
			// window. settlePendingRemovals removes the entry as it fires, so this cannot double-emit.
			settlePendingRemovals(currentTick, false, false);
		}
		emitEvent("pickup", fields);	// only pickup reaches here — drop is spawn-confirmed, alch returned above
		return delta;
	}

	/** Own-account death (item-loss context). ActorDeath fires for any nearby actor, so filter to self. */
	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (gameplayReady()) ownGameplay.activities.death(client, event.getActor(), System.currentTimeMillis());
		if (gameplayReady()) ownGameplay.ownDeath(client, event.getActor(), System.currentTimeMillis());
		if (gameplayReady() && event.getActor() instanceof NPC)
			ownGameplay.endNpc(client, (NPC) event.getActor(), true, System.currentTimeMillis());
		if (event.getActor() != null && event.getActor() == client.getLocalPlayer())
		{
			// A death spawns the player's items on the ground at their tile WITH an inventory loss — exactly the
			// drop pending's dual confirmation signal. Kill any armed drop/pickup/alch pending: the loss belongs
			// to the death event's items_lost, never to a fabricated player-initiated drop.
			clearInvDeltaPendings();
			// Capture the pre-death inventory + equipment LIVE now: OSRS removes items a few ticks AFTER the death
			// animation, so the containers are still intact at ActorDeath ([verify in-client] — the standard
			// RuneLite death-tracking timing assumption). Defer the emit; items_lost is the pre/post diff resolved
			// once the containers settle (at syncTask, DEATH_SETTLE_TICKS later) or on logout — whichever first.
			deathPending = new DeathPending(currentLocation(), deathKind(),
				mergedInvEquipCounts(), client == null ? 0 : client.getTickCount());
		}
	}

	/**
	 * death_kind: "wilderness" (inside the Wilderness — items drop to the killer), "pvp" (a PvP / DMM / high-risk
	 * world), or "safe" (PvM / minigame — a gp-sink item-retrieval reclaim, NOT a transfer). Only wilderness/pvp is
	 * an inter-account transfer. IN_WILDERNESS is the standard client wilderness signal.
	 */
	private String deathKind()
	{
		if (client == null)
		{
			return "safe";
		}
		if (client.getVarbitValue(Varbits.IN_WILDERNESS) > 0)
		{
			return "wilderness";
		}
		java.util.Set<WorldType> wt = client.getWorldType();
		if (wt != null && (wt.contains(WorldType.PVP) || wt.contains(WorldType.DEADMAN) || wt.contains(WorldType.HIGH_RISK)))
		{
			return "pvp";
		}
		return "safe";
	}

	/** Merged inventory + equipment item -> total qty, read live. Null-safe (empty when a container is absent). */
	private Map<Integer, Long> mergedInvEquipCounts()
	{
		Map<Integer, Long> counts = new LinkedHashMap<>();
		if (client == null)
		{
			return counts;
		}
		addContainerCounts(counts, client.getItemContainer(InventoryID.INVENTORY));
		addContainerCounts(counts, client.getItemContainer(InventoryID.EQUIPMENT));
		return counts;
	}

	private void addContainerCounts(Map<Integer, Long> counts, ItemContainer c)
	{
		if (c == null)
		{
			return;
		}
		addItemCounts(counts, c.getItems());
	}

	private void addItemCounts(Map<Integer, Long> counts, Item[] items)
	{
		if (items == null)
		{
			return;
		}
		for (Item item : items)
		{
			if (realItem(item))
			{
				counts.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
	}

	private Map<Integer, Long> itemCounts(Item[] items)
	{
		Map<Integer, Long> counts = new LinkedHashMap<>();
		addItemCounts(counts, items);
		return counts;
	}

	/** Resolve a deferred death from the settle-window path: containers are live AND settled, so the loss diff
	 * is trustworthy (computeLoss=true). The logout/disconnect path calls resolveDeathPending(null, false). */
	private void resolveDeathPendingViaLiveContainers()
	{
		if (deathPending != null)
		{
			resolveDeathPending(mergedInvEquipCounts(), true);
		}
	}

	/**
	 * Emit the deferred death event: {location?, death_kind, items_lost[]?}. death + kind + location are always
	 * recorded. items_lost is emitted ONLY when it can be trusted: (a) computeLoss — the settle-window path where
	 * the containers are live AND settled (the logout/disconnect path passes false, where the containers are null
	 * or not-yet-settled and a diff would over- or under-report), AND (b) the death is a real inter-account
	 * transfer (wilderness/pvp). A safe death is a gp-sink reclaim, not a transfer, and its settle-window diff is
	 * polluted by post-death eating/drinking — so it never carries items_lost. A wrong items_lost on a monitoring
	 * feed is worse than an absent one; the server wealth-reconciliation still catches the delta either way.
	 * Package-private + map arg so it is unit-testable without a client.
	 */
	void resolveDeathPending(Map<Integer, Long> postCounts, boolean computeLoss)
	{
		DeathPending p = deathPending;
		if (p == null)
		{
			return;
		}
		deathPending = null;
		Map<String, Object> fields = new LinkedHashMap<>();
		if (p.location != null)
		{
			fields.put("location", p.location);
		}
		fields.put("death_kind", p.kind);
		if (computeLoss && ("wilderness".equals(p.kind) || "pvp".equals(p.kind)))
		{
			List<Map<String, Object>> lost = new ArrayList<>();
			for (Map.Entry<Integer, Long> e : p.preCounts.entrySet())
			{
				long before = e.getValue();
				long after = postCounts == null ? 0L : postCounts.getOrDefault(e.getKey(), 0L);
				long d = before - after;
				if (d > 0)
				{
					Map<String, Object> m = new LinkedHashMap<>();
					m.put("id", e.getKey());
					m.put("qty", d);
					lost.add(m);
				}
			}
			fields.put("items_lost", lost);
		}
		emitEvent("death", fields);
	}

	/** Level-ups: StatChanged fires on every xp drop, so emit only when the real level increases. */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == null)
		{
			return;
		}
		String skill = event.getSkill().getName();
		int level = event.getLevel();
		Integer prev = lastSkillLevel.put(skill, level);
		if (prev != null && level > prev && activityLogActive())
		{
			Map<String, Object> fields = new LinkedHashMap<>();
			fields.put("skill", skill);
			fields.put("level", level);
			if (client != null)
			{
				fields.put("xp", client.getSkillExperience(event.getSkill()));	// WAVE 3: total xp at level-up
			}
			emitEvent("level_up", fields);
		}
		// XP gain (coalesced): accumulate the per-skill delta from the event's total xp. The tick timer
		// flushes it as one xp_gain event. First observation per skill only baselines (prevXp null).
		int nowXp = event.getXp();
		Integer prevXp = lastSkillXp.put(skill, nowXp);
		if (prevXp != null && nowXp > prevXp)
		{
			xpAccum.merge(skill, (long) (nowXp - prevXp), Long::sum);
		}
	}

	/** Emit one coalesced xp_gain event for all per-skill xp accumulated since the last flush. */
	void flushXpGain()
	{
		if (xpAccum.isEmpty() || !activityLogActive())
		{
			return;
		}
		List<Map<String, Object>> gains = new ArrayList<>();
		long total = 0;
		for (Map.Entry<String, Long> e : xpAccum.entrySet())
		{
			Map<String, Object> g = new LinkedHashMap<>();
			g.put("skill", e.getKey());
			g.put("xp", e.getValue());
			gains.add(g);
			total += e.getValue();
		}
		xpAccum.clear();
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("gains", gains);
		fields.put("total", total);
		emitEvent("xp_gain", fields);
	}

	/** Emit region {from,to,x,y} when the map region changes. The first observation only baselines. */
	void checkRegionChange()
	{
		if (client == null)
		{
			return;
		}
		Player self = client.getLocalPlayer();
		WorldPoint wp = self == null ? null : self.getWorldLocation();
		if (wp == null)
		{
			return;
		}
		int region = wp.getRegionID();
		Integer prev = lastRegion;
		lastRegion = region;
		if (prev != null && prev != region)
		{
			Map<String, Object> fields = new LinkedHashMap<>();
			fields.put("from", prev);
			fields.put("to", region);
			fields.put("x", wp.getX());
			fields.put("y", wp.getY());
			emitEvent("region", fields);
		}
	}

	/**
	 * GE offer lifecycle observations, own account only:
	 * ge_offer (a new offer placed), ge_progress (a partial fill, at most one per slot per minute),
	 * ge_buy / ge_sell / ge_cancel (terminal, as before) and ge_collect (the slot emptied, with what it held).
	 * The client replays slots at login. First sight only baselines; matching retained slots can
	 * report counter differences across the gap, with inferred identity and unknown fill time.
	 */
	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		GrandExchangeOffer offer = event.getOffer();
		if (offer == null)
		{
			return;
		}
		int slot = event.getSlot();
		if (slot < 0 || slot >= GE_SLOT_COUNT || offer.getState() == null)
		{
			return;
		}
		GrandExchangeOfferState state = offer.getState();
		// The client clears every slot to EMPTY while hopping, logging in and at the login screen. That
		// clear is not a collect and must not overwrite what the slot held (the RuneLite GE plugin skips
		// it the same way). Only an EMPTY seen while logged in is a real collect.
		if (state == GrandExchangeOfferState.EMPTY && client != null
			&& client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int tick = client == null ? 0 : client.getTickCount();
		long acct = client == null ? -1L : client.getAccountHash();
		long[] nowOffer = {offer.getItemId(), offer.getQuantitySold(), offer.getTotalQuantity(),
			offer.getPrice(), offer.getSpent()};
		if (client != null && acct == -1L)
		{
			// The account is not known yet (before login the hash is -1). The event cannot be judged now, and it
			// must not re-key or clear the slots. It may still be the only replay of an offer that finished while
			// away, so hold it (latest per slot, no state change) until the account is known.
			if (geUnkeyed.containsKey(slot) || geUnkeyed.size() < GE_SLOT_COUNT)
			{
				geUnkeyed.put(slot, new Object[]{state, nowOffer, System.currentTimeMillis()});
			}
			return;
		}
		prepareGeContext();
		resolveUnkeyedGe(acct);
		if (acct != geAccountHash)
		{
			// GE slots belong to one account. Another account's remembered slot must never make this one's
			// replay look like an offer that finished while away. Events with hash -1 never reach here, so a
			// stored -1 can only be the empty start or an unkeyed seed.
			geObservations.clear();
			geAccountHash = acct;
		}
		restoreGeSlots();
		// An identical re-send of a slot (same state, same offer) emits nothing through the rules below: an
		// unchanged terminal state, an active offer with no new fill and a repeated EMPTY all yield no row.
		// A replay is every slot event from leaving the world until LOGGED_IN (the RuneLite GE plugin opens its
		// window at LOGGING_IN / HOPPING / CONNECTION_LOST), plus GE_LOGIN_BURST_TICKS after LOGGED_IN.
		// geAwaitingLogin is set on leaving the world and cleared by the LOGGED_IN handler. It is read only while
		// the client is not LOGGED_IN, so a flag left stale can never swallow live activity in the world.
		boolean loginReplay = client != null
			&& ((geAwaitingLogin && client.getGameState() != GameState.LOGGED_IN)
				|| tick - geLoginTick <= GE_LOGIN_BURST_TICKS);
		judgeGeOffer(slot, state, nowOffer, loginReplay, tick, System.currentTimeMillis());
	}

	private final GeObservationTracker geObservations = new GeObservationTracker();
	private String geProfileType;
	private String geTokenFingerprint;

	// ---- GE SLOTS ACROSS A RESTART ----
	//
	// The tracker lived in memory, so a client restart forgot every open offer. The login replay then only took
	// a baseline: a fill that happened while away, and the terminal row of an offer that finished while away,
	// were never reported, and the collect came under a new offer_key. Now the slots are written after every
	// GE change and read back at the first GE event of the same token, account and profile. The next
	// observation reports the counter difference since the last row sent, as for a hop: identity
	// inferred_across_gap, the interval from that row to now, no fill time. A slot found EMPTY at login was
	// collected elsewhere and is dropped without a row, so a collect is never counted twice.
	//
	// IDENTITY. One entry per token fingerprint (never the token), account hash and profile. Another
	// account, profile or token never reads it. At most GE_SLOTS_MAX_ENTRIES entries, newest kept.

	static final String GE_SLOTS_FILE = "ge-slots.json";
	static final int GE_SLOTS_MAX_ENTRIES = 8;
	/** The key whose saved slots were last restored or superseded; client-thread only. */
	private String geRestoredFor;

	private String geSlotsKey()
	{
		String fp = currentEventTokenFingerprint();
		if (fp == null || geAccountHash == -1L || geProfileType == null)
		{
			return null;
		}
		return fp + "|" + geAccountHash + "|" + geProfileType;
	}

	private java.nio.file.Path geSlotsPath()
	{
		return spoolDataRoot().resolve("osrsbis").resolve(GE_SLOTS_FILE);
	}

	/** Once per token, account and profile: take back the saved slots. Runs right after the tracker was cleared. */
	void restoreGeSlots()
	{
		String key = geSlotsKey();
		if (key == null || key.equals(geRestoredFor))
		{
			return;
		}
		geRestoredFor = key;
		try
		{
			for (Map<String, Object> entry : readGeSlots())
			{
				if (key.equals(entry.get("key")) && entry.get("slots") instanceof List)
				{
					geObservations.restore((List<?>) entry.get("slots"));
					return;
				}
			}
		}
		catch (Throwable t)
		{
			log.debug("OSRS BiS GE slots could not be restored", t);
		}
	}

	/** Write the current slots under the current key. A failed write only costs the restart reconciliation. */
	void saveGeSlots()
	{
		String key = geSlotsKey();
		if (key == null || !key.equals(geRestoredFor) || gson == null)
		{
			return;	// not restored yet for this key: writing now would overwrite the saved slots with nothing
		}
		try
		{
			List<Map<String, Object>> all = readGeSlots();
			all.removeIf(e -> key.equals(e.get("key")));
			Map<String, Object> entry = new LinkedHashMap<>();
			entry.put("key", key);
			entry.put("saved_at", System.currentTimeMillis());
			entry.put("slots", geObservations.export());
			all.add(entry);
			all.sort(java.util.Comparator.comparingLong(e -> e.get("saved_at") instanceof Number ? ((Number) e.get("saved_at")).longValue() : 0L));
			while (all.size() > GE_SLOTS_MAX_ENTRIES)
			{
				all.remove(0);
			}
			java.nio.file.Path file = geSlotsPath();
			java.nio.file.Files.createDirectories(file.getParent());
			java.nio.file.Path tmp = file.resolveSibling(GE_SLOTS_FILE + ".tmp");
			java.nio.file.Files.write(tmp, gson.toJson(all).getBytes(java.nio.charset.StandardCharsets.UTF_8));
			java.nio.file.Files.move(tmp, file, java.nio.file.StandardCopyOption.REPLACE_EXISTING,
				java.nio.file.StandardCopyOption.ATOMIC_MOVE);
		}
		catch (Throwable t)
		{
			log.debug("OSRS BiS GE slots could not be written", t);
		}
	}

	@SuppressWarnings("unchecked")
	private List<Map<String, Object>> readGeSlots() throws IOException
	{
		java.nio.file.Path file = geSlotsPath();
		List<Map<String, Object>> rows = new ArrayList<>();
		if (gson == null || !java.nio.file.Files.exists(file))
		{
			return rows;
		}
		try
		{
			Object parsed = gson.fromJson(new String(java.nio.file.Files.readAllBytes(file),
				java.nio.charset.StandardCharsets.UTF_8), Object.class);
			if (parsed instanceof List)
			{
				for (Object row : (List<?>) parsed)
				{
					if (row instanceof Map)
					{
						rows.add(new LinkedHashMap<>((Map<String, Object>) row));
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("OSRS BiS GE slots file unreadable; starting fresh", e);
		}
		return rows;
	}

	private void prepareGeContext()
	{
		String profile = client == null || client.getWorldType() == null ? "UNKNOWN" : RuneScapeProfileType.getCurrent(client).name();
		String token = currentEventTokenFingerprint();
		if (!java.util.Objects.equals(profile, geProfileType)
			|| !java.util.Objects.equals(token, geTokenFingerprint))
		{
			if (geProfileType != null && client != null)
			{
				geLoginTick = client.getTickCount();
			}
			geObservations.clear();
			geProfileType = profile;
			geTokenFingerprint = token;
		}
	}

	/** GE slots held while the account hash was -1: slot -> {state, offer tuple, callback time}. Client-thread only. */
	private final java.util.TreeMap<Integer, Object[]> geUnkeyed = new java.util.TreeMap<>();
	/** The client has 8 GE slots; the unkeyed buffer never holds more. */
	static final int GE_SLOT_COUNT = 8;

	/**
	 * Settle the GE events held while the account hash was -1, now that the hash is known. Same account as
	 * the stored slots (a hop or relog): judge them in slot order as a login replay, so an offer that
	 * finished while away is reported once. Another account (or none stored): drop the old slots and take
	 * the held events as the new baseline, emitting nothing.
	 */
	void resolveUnkeyedGe(long acct)
	{
		if (geUnkeyed.isEmpty() || acct == -1L)
		{
			return;
		}
		prepareGeContext();
		java.util.List<Map.Entry<Integer, Object[]>> held = new ArrayList<>(geUnkeyed.entrySet());
		geUnkeyed.clear();
		int tick = client == null ? 0 : client.getTickCount();
		if (acct == geAccountHash)
		{
			restoreGeSlots();
			for (Map.Entry<Integer, Object[]> e : held)
			{
				judgeGeOffer(e.getKey(), (GrandExchangeOfferState) e.getValue()[0], (long[]) e.getValue()[1], true, tick, (Long) e.getValue()[2]);
			}
			return;
		}
		geObservations.clear();
		geAccountHash = acct;
		restoreGeSlots();
		for (Map.Entry<Integer, Object[]> e : held)
		{
			judgeGeOffer(e.getKey(), (GrandExchangeOfferState) e.getValue()[0],
				(long[]) e.getValue()[1], true, tick, (Long) e.getValue()[2]);
		}
	}

	/** Emit legacy cumulative fields plus explicitly qualified observation deltas. */
	private void judgeGeOffer(int slot, GrandExchangeOfferState state, long[] value, boolean replay, int tick, long observedAt)
	{
		Map<String, Object> fields = geObservations.observe(slot, state, value, replay, tick, observedAt);
		saveGeSlots();
		if (fields != null)
		{
			String type = (String) fields.remove("type");
			fields.put("profile_type", geProfileType);
			// The session upload loop may still name the previous account during login.
			Player self = client == null ? null : client.getLocalPlayer();
			fields.put("rsn", self == null ? null : self.getName());
			if (geAccountHash != -1L)
			{
				fields.put("account_hash", Long.toString(geAccountHash));
			}
			emitEvent(type, fields);
		}
	}

	/** "buy" or "sell" for an offer state; null for EMPTY. */
	static String geSide(GrandExchangeOfferState s)
	{
		if (s == null)
		{
			return null;
		}
		switch (s)
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return "buy";
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				return "sell";
			default:
				return null;
		}
	}

	/**
	 * WAVE 4 — structured NPC loot. The whole drop for one kill arrives as a single Collection&lt;ItemStack&gt;,
	 * so one kill = one "loot" event (already coalesced by the API — no time window needed). Fired by
	 * LootManager, a core RuneLite service that is ALWAYS running (NOT the optional loot-tracker plugin), for
	 * the local player's kills — so this is own-account by construction.
	 *
	 * We subscribe to ServerNpcLoot ONLY. LootManager fires BOTH ServerNpcLoot and NpcLootReceived for the same
	 * server-authoritative kill (verified in its bytecode), so taking both would double-count; this mirrors
	 * RuneLite's own maintained LootTrackerPlugin (onServerNpcLoot + onPlayerLootReceived). Trade-off: kills
	 * that ONLY fire via LootManager's older ground-detection path (NpcLootReceived alone) are not captured —
	 * a rare edge case in modern OSRS; adding it would require subscribing to both with dedup state.
	 * javap-verified vs client 1.12.32 (ServerNpcLoot.getComposition/getItems, NPCComposition.getName).
	 */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		NPCComposition comp = event.getComposition();
		emitLoot(comp == null ? null : comp.getName(), "npc", event.getItems());
		// Derived local encounter input; existing loot transport stays unchanged.
		if (gameplayReady())
		{
			ownGameplay.loot(client, comp == null ? -1 : comp.getId(), event.getItems(), System.currentTimeMillis());
			if (log.isDebugEnabled() && gson != null)
				log.debug("OSRS BiS encounter summary {}", gson.toJson(ownGameplay.encounterSummary(client.getTickCount())));
		}
	}

	/**
	 * WAVE 4 — PvP player loot (e.g. a Wilderness kill). Capture the ITEMS only. The victim's name is available
	 * (event.getPlayer().getName()) but is deliberately NOT sent: forwarding a killed player's name on the
	 * public path is a compliance decision for the product owner, not an auto-send.
	 * TODO: decide whether to attach the victim RSN as loot source_name — left OUT until then.
	 * javap-verified vs client 1.12.32 (PlayerLootReceived.getItems).
	 */
	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		emitLoot(null, "player", event.getItems());
	}

	/**
	 * Build + buffer a structured "loot" event: {source_name?, source_type, items:[{id,qty}], value}. value is
	 * the summed GE price via ItemManager when reachable (0 when itemManager is absent, e.g. buffer-only tests).
	 * No-op on an empty/blank drop. Gated inside emitEvent exactly like every other event (token set + account
	 * not excluded). Deliberately NOT a SNAPSHOT_TRIGGER_EVENT: loot fires many times a minute at a boss/slayer
	 * task — forcing a snapshot per kill would be a firehose; the wealth/inventory change lands on the next
	 * syncTask through the normal change-gate, while the loot event itself still ships in real time (WAVE 2).
	 */
	void emitLoot(String sourceName, String sourceType, Collection<ItemStack> stacks)
	{
		if (stacks == null || stacks.isEmpty())
		{
			return;
		}
		List<Map<String, Object>> items = new ArrayList<>();
		long value = 0L;
		for (ItemStack st : stacks)
		{
			if (st == null || st.getId() <= 0 || st.getQuantity() <= 0)
			{
				continue;
			}
			items.add(itemMap(st.getId(), st.getQuantity()));
			if (itemManager != null)
			{
				value += (long) itemManager.getItemPrice(st.getId()) * st.getQuantity();
			}
		}
		if (items.isEmpty())
		{
			return;
		}
		Map<String, Object> fields = new LinkedHashMap<>();
		if (sourceName != null && !sourceName.isEmpty())
		{
			fields.put("source_name", sourceName);
		}
		fields.put("source_type", sourceType);
		fields.put("items", items);
		fields.put("value", value);
		emitEvent("loot", fields);
	}

	void handleTradeChat(String message)
	{
		if (tradeScreenshotsDisabled())
		{
			return;
		}
		String text = Text.removeTags(message == null ? "" : message).trim();
		if (TRADE_ACCEPTED_MESSAGE.equalsIgnoreCase(text))
		{
			BufferedImage frame = pendingTradeFrame.getAndSet(null);
			resetTradeState();
			if (frame != null)
			{
				submitTradeScreenshotUpload(frame, "confirm");
			}
			// Second proof frame: the trade just completed and the window closed, so the NEXT rendered
			// frame shows the "Accepted trade." chat confirmation. Delivery proof needs BOTH — the
			// confirm screen (items + partner) and the completion frame (proof it actually went through).
			// Only capture when a valid token is configured: nothing to upload otherwise, and this also
			// keeps the no-token path from touching drawManager.
			String completedToken = config.linkToken() == null ? "" : config.linkToken().trim();
			if (completedToken.matches("^[a-f0-9]{32}$"))
			{
				drawManager.requestNextFrameListener(image ->
				{
					if (screenshotsEnabled())	// re-check: the gate may close before the frame lands
					{
						submitTradeScreenshotUpload(toBufferedImage(image), "completed");
					}
				});
			}
		}
		else if (TRADE_DECLINED_MESSAGE.equalsIgnoreCase(text))
		{
			resetTradeState();
		}
	}

	/**
	 * The whole feature is gated on screenshotsEnabled(): no link token (or a server force-disable)
	 * means no arming, no frame request, no buffer, no upload. Also drops any frame buffered before the
	 * token was cleared or the server disabled it mid-trade.
	 */
	private boolean tradeScreenshotsDisabled()
	{
		if (screenshotsEnabled())
		{
			return false;
		}
		if (tradeActive || tradeArmed || pendingTradeFrame.get() != null)
		{
			resetTradeState();
		}
		return true;
	}

	private void resetTradeState()
	{
		tradeActive = false;
		tradeArmed = false;
		tradeMainOpen = false;
		pendingTradeFrame.set(null);
		pendingTradeGiven = null;	// activity-log trade capture — drop on decline/abandon/hop so it never leaks
		pendingCounterparty = null;
		pendingCounterpartyCombatLevel = null;
		pendingTradeReceived = null;	// WAVE 1b: received side — drop with the rest so it never leaks across trades
		pendingReceivedText = null;
	}

	// ---- trade screenshot: capture + upload ----

	/** Safe Image -> BufferedImage copy (the frame-listener contract only guarantees Image). */
	static BufferedImage toBufferedImage(java.awt.Image img)
	{
		if (img instanceof BufferedImage)
		{
			return (BufferedImage) img;
		}
		BufferedImage bi = new BufferedImage(
			img.getWidth(null), img.getHeight(null), BufferedImage.TYPE_INT_ARGB);
		java.awt.Graphics2D g = bi.createGraphics();
		g.drawImage(img, 0, 0, null);
		g.dispose();
		return bi;
	}

	/** In-memory encode via JDK ImageIO (same encoder core ImageCapture uses). fmt e.g. "png". Null on failure. */
	static byte[] encodeImage(BufferedImage image, String fmt)
	{
		java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
		try
		{
			javax.imageio.ImageIO.write(image, fmt, buf);
		}
		catch (IOException e)
		{
			log.debug("OSRS BiS image encode ({}) failed", fmt, e);
			return null;
		}
		return buf.toByteArray();
	}

	/** In-memory PNG encode (trade path). Delegates to the generalized encoder. */
	static byte[] encodePng(BufferedImage image)
	{
		return encodeImage(image, "png");
	}

	/**
	 * In-memory JPEG encode at an explicit quality (store delivery-proof frames). The default ImageIO.write
	 * path can't set quality, so drive the writer directly with ImageWriteParam. Input must be TYPE_INT_RGB
	 * (the JDK JPEG writer corrupts ARGB rasters). Null on failure.
	 */
	static byte[] encodeJpeg(BufferedImage image)
	{
		javax.imageio.ImageWriter writer = null;
		try (java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
			javax.imageio.stream.ImageOutputStream ios = javax.imageio.ImageIO.createImageOutputStream(buf))
		{
			writer = javax.imageio.ImageIO.getImageWritersByFormatName("jpg").next();
			writer.setOutput(ios);
			javax.imageio.ImageWriteParam param = writer.getDefaultWriteParam();
			param.setCompressionMode(javax.imageio.ImageWriteParam.MODE_EXPLICIT);
			// 0.55, lowered from 0.70 on 2026-09-02 to fit 360 frames (30fps x 12s) in the then 12MB burst
			// cap: 30KB/frame at 704px vs 45KB at 768px/0.70. Legibility was re-checked at this setting,
			// not assumed — a clip nobody can read is not evidence however smooth it is.
			param.setCompressionQuality(0.55f);
			writer.write(null, new javax.imageio.IIOImage(image, null, null), param);
			ios.flush();
			return buf.toByteArray();
		}
		catch (Exception e)
		{
			log.debug("OSRS BiS store-clip JPEG encode failed", e);
			return null;
		}
		finally
		{
			if (writer != null)
			{
				writer.dispose();
			}
		}
	}

	/**
	 * PNG-encoding a full frame can hitch the render loop, so encode + upload run on the injected
	 * background executor; the OkHttp call itself is async (enqueue), same as postSnapshot.
	 */
	private void submitTradeScreenshotUpload(BufferedImage frame, String phase)
	{
		if (!uploadAllowed())
		{
			return;		// upload switch off — send nothing
		}
		String token = config.linkToken() == null ? "" : config.linkToken().trim();
		if (!token.matches("^[a-f0-9]{32}$"))
		{
			return;	// same guard as syncTask: no / malformed token configured yet — never POST
		}
		executor.submit(() ->
		{
			byte[] bytes = encodePng(frame);
			if (bytes == null || bytes.length == 0)
			{
				return;
			}
			if (bytes.length > MAX_SCREENSHOT_UPLOAD_BYTES)
			{
				log.debug("OSRS BiS trade screenshot dropped: {} bytes exceeds {} byte cap",
					bytes.length, MAX_SCREENSHOT_UPLOAD_BYTES);
				return;
			}
			uploadTradeScreenshot(token, bytes, phase);
		});
	}

	private void uploadTradeScreenshot(String token, byte[] pngBytes, String phase)
	{
		if (!staffCaptureEnabled() || !uploadAllowed())
		{
			return;		// upload switch off — send nothing
		}
		long capturedAt = System.currentTimeMillis() / 1000L;
		RequestBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("token", token)
			.addFormDataPart("kind", "trade")
			.addFormDataPart("phase", phase)	// "confirm" = trade window; "completed" = post-accept chat frame
			.addFormDataPart("captured_at", Long.toString(capturedAt))
			.addFormDataPart("file", "trade-" + phase + "-" + capturedAt + ".png", RequestBody.create(PNG, pngBytes))
			.build();

		String base = config.apiBaseUrl() == null ? "" : config.apiBaseUrl().replaceAll("/+$", "");
		Request request = new Request.Builder()
			.url(base + "/screenshot-ingest")
			.post(body)
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("OSRS BiS trade screenshot upload failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					if (response.isSuccessful())
					{
						healthLastMediaUploadMs.set(System.currentTimeMillis());
					}
					log.debug("OSRS BiS trade screenshot upload response: {}", response.code());
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	Map<String, Object> captureHealthSnapshot()
	{
		Map<String, Object> h = new LinkedHashMap<>();
		h.put("process_started_at", healthProcessStartedAtMs / 1000L);
		h.put("events_queued_total", healthEventsQueued.get());
		h.put("events_sent_total", healthEventsSent.get());
		h.put("events_lost_total", healthEventsLost.get());
		h.put("events_sent_semantics", "legacy_success_or_queue_ownership_not_archive_total");
		h.put("queue_delivery", queueDeliveryHealth.snapshot());
		h.put("events_overflow_p0_total", healthOverflowByClass.get(EventPriority.P0));
		h.put("events_overflow_p1_total", healthOverflowByClass.get(EventPriority.P1));
		h.put("events_overflow_p2_total", healthOverflowByClass.get(EventPriority.P2));
		synchronized (pendingEvents)
		{
			h.put("events_pending", pendingEvents.size());
		}
		h.put("event_post_in_flight", eventPostInFlight);
		h.put("drop_segments_uploaded_total", healthDropSegmentsSent.get());
		h.put("drop_segments_refused_total", healthDropSegmentsRefused.get());
		h.put("drop_segments_lost_total", healthDropSegmentsLost.get());
		h.put("drop_frames_rejected_total", healthDropFramesRejected.get());
		h.put("store_clip_chunks_uploaded_total", clipChunksSent.get());
		h.put("store_clip_chunks_lost_total", clipChunksLost.get());
		long eventAt = healthLastEventUploadMs.get();
		long mediaAt = healthLastMediaUploadMs.get();
		long snapshotAt = healthLastSnapshotUploadMs.get();
		if (eventAt > 0) h.put("last_event_upload_at", eventAt / 1000L);
		if (mediaAt > 0) h.put("last_media_upload_at", mediaAt / 1000L);
		if (snapshotAt > 0) h.put("last_snapshot_upload_at", snapshotAt / 1000L);
		h.put("public_outbox_pending", publicOutboxPending);
		h.put("public_outbox_bytes", publicOutboxBytes);
		h.put("public_outbox_dropped_total", publicOutboxDropped);
		h.put("public_outbox_retired_identities_total", publicOutboxPurged);
		h.put("public_outbox_not_durable_total", publicOutboxUndurable.get());
		h.put("public_outbox_append_pending", publicOutboxWrites.get());
		addSpoolHealth(h);
		return h;
	}

	/** The account-type varbit (gameval VarbitID.IRONMAN, legacy Varbits.ACCOUNT_TYPE). */
	static final int ACCOUNT_TYPE_VARBIT = net.runelite.api.gameval.VarbitID.IRONMAN;	// 1777

	/**
	 * Explicit map from the ACCOUNT_TYPE varbit to a stable name. Values 0-5 match the names of RuneLite's
	 * net.runelite.api.vars.AccountType (deprecated, so it is not referenced at runtime; AccountTypeTest pins
	 * the parity). 6 is unranked group ironman, which that enum lacks, so it gets its own name rather than
	 * being folded into GROUP_IRONMAN. Any other value is UNKNOWN_<n>: never guessed, never NORMAL.
	 */
	static String accountTypeName(int varbit)
	{
		switch (varbit)
		{
			case 0:
				return "NORMAL";
			case 1:
				return "IRONMAN";
			case 2:
				return "ULTIMATE_IRONMAN";
			case 3:
				return "HARDCORE_IRONMAN";
			case 4:
				return "GROUP_IRONMAN";
			case 5:
				return "HARDCORE_GROUP_IRONMAN";
			case 6:
				return "UNRANKED_GROUP_IRONMAN";
			default:
				return "UNKNOWN_" + varbit;
		}
	}

	private boolean broadCaptureEnabled()
	{
		return serverGameVarsEnabled && broadCaptureToken != null
			&& broadCaptureToken.equals(currentLinkToken());
	}

	private static void stripBroadCapture(Map<String, Object> snapshot)
	{
		snapshot.remove("game_vars");
		for (String key : OWN_STORAGE_CONTAINERS.keySet()) snapshot.remove(key);
	}

	private void setBroadCaptureGrant(String token, boolean enabled)
	{
		broadCaptureToken = enabled ? token : null;
		serverGameVarsEnabled = enabled;
		if (!enabled)
		{
			lastGameVarsSentMs = 0;
			Map<String, Object> cached = lastBuiltSnapshot;
			if (cached != null)
			{
				Map<String, Object> clean = new LinkedHashMap<>(cached);
				stripBroadCapture(clean);
				lastBuiltSnapshot = clean;
				lastBuiltHash = canonicalHash(clean);
			}
		}
	}

	/**
	 * account.members: TRUE on a members world. Elsewhere the membership-days varp decides, but only once the
	 * player's variables have settled after login: TRUE with days left, FALSE with none, null before that.
	 * An early read can be a zero still on its way, or a value left from the account logged in before.
	 */
	static Boolean accountMembers(boolean onMembersWorld, boolean varsSettled, int membershipDays)
	{
		if (onMembersWorld)
		{
			return Boolean.TRUE;
		}
		if (!varsSettled || membershipDays < 0)
		{
			return null;
		}
		return membershipDays > 0;
	}

	/**
	 * The game_vars block for this snapshot, or null. Null when not granted, before the player's skills have
	 * loaded (a login snapshot can read all zeros: 6 of 3,003 production snapshots on 2026-10-15 had every skill
	 * at level 0), or inside GAME_VARS_MIN_INTERVAL_MS of the last accepted block. The cadence applies
	 * to changed and unchanged arrays alike; failed requests obey snapshot retry backoff.
	 */
	Map<String, Object> gameVarsBlock(long nowMs)
	{
		if (!broadCaptureEnabled() || client == null || client.getRealSkillLevel(Skill.HITPOINTS) <= 0)
		{
			return null;
		}
		if (lastGameVarsSentMs > 0 && nowMs - lastGameVarsSentMs < GAME_VARS_MIN_INTERVAL_MS)
		{
			return null;	// the interval runs from the last ACCEPTED snapshot that carried the block
		}
		Map<String, Object> gv = GameVarsCapture.encode(client.getVarps());
		if (gv == null)
		{
			return null;
		}
		gv.put("observed_at", nowMs / 1000L);
		gv.put("api", "runelite-varps");
		return gv;
	}

	private Map<String, Object> buildSnapshot()
	{
		snapshotBuildSeq++;
		Map<String, Object> snap = new LinkedHashMap<>();
		snap.put("schema_v", SCHEMA_V);
		// One clock read for both: captured_at_ms orders a snapshot against a same-second event, and
		// captured_at stays its whole second.
		long capturedAtMs = System.currentTimeMillis();
		snap.put("captured_at", capturedAtMs / 1000L);
		snap.put("captured_at_ms", capturedAtMs);

		Map<String, Object> source = new LinkedHashMap<>();
		source.put("plugin", "osrsbis-export");
		source.put("plugin_version", PLUGIN_VERSION);
		source.put("client", "runelite");
		source.put("capture_health", captureHealthSnapshot());
		snap.put("source", source);

		ItemContainer eqp = client.getItemContainer(InventoryID.EQUIPMENT);
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		ItemContainer liveBank = client.getItemContainer(InventoryID.BANK);
		// After a close the client has no bank container: report the last read of this login, timestamped by
		// the bank's last change, instead of nothing (which let the server carry an older bank forward).
		Item[] bank = liveBank != null ? liveBank.getItems() : lastBankItems;
		boolean bankSynced = bank != null;

		// ---- account meta ----
		Map<String, Object> account = new LinkedHashMap<>();
		account.put("rsn", client.getLocalPlayer().getName());
		account.put("account_hash", Long.toString(client.getAccountHash()));
		// account_type is the IRON MODE (0.7.17). It used to be RuneScapeProfileType, which has no ironman
		// variants, so every main-game account shipped STANDARD and the site's ironman arm never fired.
		// profile_type keeps that old value (STANDARD/BETA/LEAGUE/...) under its own name.
		account.put("account_type", accountTypeName(client.getVarbitValue(ACCOUNT_TYPE_VARBIT)));
		account.put("profile_type", RuneScapeProfileType.getCurrent(client).name());
		// A members world proves an active sub. An f2p world proves nothing (members play there too), so the
		// account's own membership-days varp decides there, the same varp the RuneLite friends list uses for
		// its 400/200 limit. current_world_members stays the plain world-type signal.
		boolean onMembersWorld = client.getWorldType().contains(WorldType.MEMBERS);
		account.put("current_world_members", onMembersWorld);
		boolean varsSettled = client.getRealSkillLevel(Skill.HITPOINTS) > 0
			&& client.getTickCount() - worldLoginTick >= MEMBERS_SETTLE_TICKS;
		account.put("members", accountMembers(onMembersWorld, varsSettled, client.getVarpValue(VarPlayer.MEMBERSHIP_DAYS)));
		snap.put("account", account);

		// ---- capture completeness ----
		Map<String, Object> flags = new LinkedHashMap<>();
		flags.put("equipment_synced", eqp != null);
		flags.put("inventory_synced", inv != null);
		flags.put("bank_synced", bankSynced);   // bank container is null until the bank is opened in-session
		flags.put("collog_synced", clogSeen);     // true once the player has opened the clog UI this session
		flags.put("boss_kc_source", "none");      // deferred (no clean client field)
		snap.put("capture_flags", flags);

		// ---- game variables (server-granted, off by default) ----
		Map<String, Object> gv = gameVarsBlock(System.currentTimeMillis());
		if (gv != null)
		{
			snap.put("game_vars", gv);
		}

		Map<String,Object> gameplay = gameplayBlock();
		if (gameplay != null) snap.put("own_gameplay", gameplay);
		Map<String, Object> progress = progressBlock();
		if (progress != null)
		{
			snap.put("account_progress", progress);
		}

		// ---- skills (real skills only; OVERALL excluded) ----
		Map<String, Object> skills = new LinkedHashMap<>();
		for (Skill s : Skill.values())
		{
			if ("Overall".equalsIgnoreCase(s.getName()))
			{
				continue;
			}
			Map<String, Object> sk = new LinkedHashMap<>();
			sk.put("xp", client.getSkillExperience(s));
			sk.put("level", client.getRealSkillLevel(s));
			sk.put("boosted", client.getBoostedSkillLevel(s));
			skills.put(s.getName().toLowerCase(), sk);
		}
		snap.put("skills", skills);
		snap.put("total_level", client.getTotalLevel());
		snap.put("combat_level", client.getLocalPlayer().getCombatLevel());

		// ---- quests: per-quest state ----
		Map<String, Object> states = new LinkedHashMap<>();
		for (Quest q : Quest.values())
		{
			try
			{
				states.put(q.name(), q.getState(client).name());
			}
			catch (Exception e)
			{
				log.debug("Unable to read quest state {}: {}", q.name(), e.toString());
			}
		}
		Map<String, Object> quests = new LinkedHashMap<>();
		quests.put("states", states);
		// How many quests the client could read, so a quest missing from states is known to be unread, not absent.
		quests.put("read_count", states.size());
		quests.put("known_count", Quest.values().length);
		quests.put("quest_points", client.getVarpValue(VARP_QUEST_POINTS));
		snap.put("quests", quests);

		// ---- achievement diaries: raw completion varbit per region/tier ----
		Map<String, Object> diaries = new LinkedHashMap<>();
		for (Object[] d : DIARIES)
		{
			Map<String, Object> tiers = new LinkedHashMap<>();
			tiers.put("easy", client.getVarbitValue((int) d[1]));
			tiers.put("medium", client.getVarbitValue((int) d[2]));
			tiers.put("hard", client.getVarbitValue((int) d[3]));
			tiers.put("elite", client.getVarbitValue((int) d[4]));
			diaries.put((String) d[0], tiers);
		}
		snap.put("diaries_raw", diaries);

		// ---- combat achievements: raw per-tier varbit ----
		Map<String, Object> ca = new LinkedHashMap<>();
		ca.put("easy", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_EASY));
		ca.put("medium", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_MEDIUM));
		ca.put("hard", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_HARD));
		ca.put("elite", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_ELITE));
		ca.put("master", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_MASTER));
		ca.put("grandmaster", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_GRANDMASTER));
		// Every task's completion bit (one bit per task id), so a task-gated item is known, not only the tier.
		List<Integer> caWords = new ArrayList<>();
		for (int varp : AccountReadiness.CA_TASK_VARPS)
		{
			caWords.add(client.getVarpValue(varp));
		}
		ca.put("task_words", caWords);
		ca.put("points", client.getVarbitValue(VARBIT_CA_POINTS));
		snap.put("combat_achievements_raw", ca);

		// ---- slayer ----
		Map<String, Object> slayer = new LinkedHashMap<>();
		slayer.put("points", client.getVarbitValue(Varbits.SLAYER_POINTS));
		slayer.put("streak", client.getVarbitValue(Varbits.SLAYER_TASK_STREAK));
		slayer.put("task_target_id", client.getVarpValue(VARP_SLAYER_TARGET));
		slayer.put("task_remaining", client.getVarpValue(VARP_SLAYER_COUNT));
		slayer.put("unlocks_raw", client.getVarpValue(VARP_SLAYER_UNLOCKS));
		slayer.put("blocked_raw", client.getVarpValue(VARP_SLAYER_BLOCKED));
		// The later reward words: unlocks1/unlocks2 hold the rewards bought after the first varp filled.
		slayer.put("unlocks1_raw", client.getVarpValue(VARP_SLAYER_UNLOCKS1));
		slayer.put("unlocks2_raw", client.getVarpValue(VARP_SLAYER_UNLOCKS2));
		snap.put("slayer", slayer);

		// ---- rune pouch: raw type-index + amount per slot (server maps type-index -> rune item) ----
		int[][] rpSlots = {
			{Varbits.RUNE_POUCH_RUNE1, Varbits.RUNE_POUCH_AMOUNT1},
			{Varbits.RUNE_POUCH_RUNE2, Varbits.RUNE_POUCH_AMOUNT2},
			{Varbits.RUNE_POUCH_RUNE3, Varbits.RUNE_POUCH_AMOUNT3},
			{Varbits.RUNE_POUCH_RUNE4, Varbits.RUNE_POUCH_AMOUNT4},
			{Varbits.RUNE_POUCH_RUNE5, Varbits.RUNE_POUCH_AMOUNT5},
			{Varbits.RUNE_POUCH_RUNE6, Varbits.RUNE_POUCH_AMOUNT6},
		};
		List<Map<String, Object>> runePouch = new ArrayList<>();
		for (int[] s : rpSlots)
		{
			int type = client.getVarbitValue(s[0]);
			int amt = client.getVarbitValue(s[1]);
			if (type > 0 && amt > 0)
			{
				Map<String, Object> m = new LinkedHashMap<>();
				m.put("type_raw", type);
				m.put("amount", amt);
				runePouch.add(m);
			}
		}
		snap.put("rune_pouch_raw", runePouch);

		// ---- grand exchange: active buy/sell offers ----
		List<Map<String, Object>> geOffers = new ArrayList<>();
		long geEscrowGp = 0L;	// wealth locked in GE offers (see the per-offer accumulation below)
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers != null)
		{
			for (int i = 0; i < offers.length; i++)
			{
				GrandExchangeOffer o = offers[i];
				if (o == null || o.getState() == GrandExchangeOfferState.EMPTY)
				{
					continue;
				}
				Map<String, Object> m = new LinkedHashMap<>();
				m.put("slot", i);
				m.put("item_id", o.getItemId());
				m.put("state", o.getState().name());
				m.put("total_qty", o.getTotalQuantity());
				m.put("transferred_qty", o.getQuantitySold());
				m.put("price_per_item", o.getPrice());
				m.put("spent", o.getSpent());
				geOffers.add(m);
				// GE escrow (gap audit 2026-07-18): wealth locked in the GE that bank+inv can't see — a placed
				// buy removes gp, an in-flight sell removes items, and either reads as a FALSE leak without this.
				// Buy-side: the full committed gp (bought-but-uncollected items stand in for the spent part).
				// Sell-side: remaining items at GE value + uncollected proceeds. Approximation is deliberate —
				// partial mid-offer collection can briefly double-count, and the reconcile engine already
				// downgrades confidence on GE-active windows.
				GrandExchangeOfferState st = o.getState();
				boolean buySide = st == GrandExchangeOfferState.BUYING || st == GrandExchangeOfferState.BOUGHT
					|| st == GrandExchangeOfferState.CANCELLED_BUY;
				if (buySide)
				{
					geEscrowGp += (long) o.getTotalQuantity() * o.getPrice();
				}
				else
				{
					long remaining = (long) o.getTotalQuantity() - o.getQuantitySold();
					if (remaining > 0 && itemManager != null)
					{
						geEscrowGp += remaining * itemManager.getItemPrice(o.getItemId());
					}
					geEscrowGp += o.getSpent();	// proceeds not yet collected
				}
			}
		}
		snap.put("ge_offers", geOffers);

		// ---- worn equipment: slot -> {id, qty} ----
		Map<String, Object> equipment = new LinkedHashMap<>();
		if (eqp != null)
		{
			for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
			{
				Item item = eqp.getItem(slot.getSlotIdx());
				if (item != null && item.getId() > 0)
				{
					equipment.put(slot.name().toLowerCase(), itemMap(item.getId(), item.getQuantity()));
				}
			}
		}
		snap.put("equipment", equipment);

		// ---- inventory + bank ----
		snap.put("inventory", itemList(inv));
		Map<String, Object> bankBlock = new LinkedHashMap<>();
		bankBlock.put("items", bankSynced ? itemList(bank) : new ArrayList<>());
		bankBlock.put("value_gp", bankSynced ? containerValue(bank) : 0L);
		List<long[]> manifest = bankSynced ? BankVisitManifest.canonical(itemCounts(bank)) : null;
		if (manifest != null && manifest.size() == ((List<?>) bankBlock.get("items")).size())
		{
			// The same canonical list and hash as a bank visit, so the server can match this bank to a visit and
			// check the list is whole. A bank with one item in two slots would not match its items, so it has neither.
			bankBlock.put("manifest_sha256", BankVisitManifest.sha256(manifest));
			bankBlock.put("item_stacks", manifest.size());
		}
		// An open bank's live read that no change of this open has confirmed yet has no known time: the last
		// change's time predates the open, and the bank may have changed while it was closed.
		bankBlock.put("observed_at", bankSynced && !bankReadUnconfirmed(liveBank) ? observedAtSeconds(BANK_CONTAINER_ID) : null);
		if (bankOpenAtCapture(liveBank))
		{
			bankBlock.put("open_at_capture", true);
		}
		snap.put("bank", bankBlock);

		// ---- off-book / niche containers (verified gameval ids; legacy enum for GIM shared storage). Included
		// only when non-null = opened at least once this session, so a normal snapshot never carries empty blocks.
		// Shared Group Ironman storage is deliberately excluded from this public artifact. ----
		addContainerSnapshot(snap, "looting_bag", client.getItemContainer(LOOTING_BAG_CONTAINER_ID));
		addContainerSnapshot(snap, "seed_vault", client.getItemContainer(SEED_VAULT_CONTAINER_ID));
		// Shared group storage is outside the public own-player transport contract.
		// Storage-visibility (gap audit 2026-07-18): real wealth a bank+inv+equip snapshot can't see — a bond
		// is ~30M+ parked invisibly; quiver ammo can be a large stacked value. False-residual sources closed.
		addContainerSnapshot(snap, "bonds_pouch", client.getItemContainer(BONDS_POUCH_CONTAINER_ID));
		addContainerSnapshot(snap, "bonds_escrow", client.getItemContainer(BONDS_ESCROW_CONTAINER_ID));
		addContainerSnapshot(snap, "quiver_ammo", client.getItemContainer(QUIVER_AMMO_CONTAINER_ID));
		// Broad capture batch 1: the player's OWN storage containers that the game sends once opened or
		// checked (ids from gameval, matched against runelite-api 1.13.1). Each block is present only once the
		// game has sent that container this session, and carries observed_at. Group, trade, duel, Deadman loot
		// and reward-chest containers are deliberately absent: they hold other players' items or are loot,
		// which the loot events already cover.
		if (broadCaptureEnabled())
		{
			for (Map.Entry<String, Integer> c : OWN_STORAGE_CONTAINERS.entrySet())
			{
				addContainerSnapshot(snap, c.getKey(), client.getItemContainer(c.getValue()));
			}
		}

		// ---- collection log: obtained item ids (partial until the player opens the clog tabs) ----
		Map<String, Object> collog = new LinkedHashMap<>();
		List<Integer> obtained = new ArrayList<>(clogObtained);
		java.util.Collections.sort(obtained);
		AccountProgressCapture collection = activeCollection();
		Map<String, Object> verified = collection == null ? null : collection.verifiedCollection(client);
		if (verified != null)
		{
			// A verified scan saw every obtained slot: send that whole list, so the server can keep only this one.
			obtained = new ArrayList<>();
			for (Object id : (List<?>) verified.get("obtained_item_ids"))
			{
				obtained.add((Integer) id);
			}
		}
		collog.put("synced", clogSeen || verified != null);
		if (collection != null)
		{
			collog.put("scan_status", collection.collectionScanStatus());
		}
		collog.put("obtained_count", obtained.size());
		collog.put("obtained_item_ids", obtained);
		if (verified != null)
		{
			collog.put("complete", true);
			collog.put("game_obtained_count", verified.get("game_obtained_count"));
			collog.put("game_total_count", verified.get("game_total_count"));
			collog.put("verified_at_ms", verified.get("verified_at_ms"));
		}
		snap.put("collection_log", collog);

		// ---- wealth (broken out: carried coins, inventory, worn gear, bank, total) ----
		long invValue = containerValue(inv);
		long eqpValue = containerValue(eqp);
		long bankValue = bankSynced ? containerValue(bank) : 0L;
		long coins = countItem(inv, COINS_ID) + countItem(eqp, COINS_ID);
		Map<String, Object> wealth = new LinkedHashMap<>();
		wealth.put("coins_carried", coins);          // coins (id 995) on hand
		wealth.put("inventory_gp", invValue);         // total GE value of carried inventory (incl. coins)
		wealth.put("equipment_gp", eqpValue);         // GE value of worn / on-character gear
		wealth.put("bank_gp", bankSynced ? bankValue : null);
		wealth.put("ge_escrow_gp", geEscrowGp);       // wealth locked in GE offers — invisible to bank+inv+equip
		wealth.put("net_worth_gp", bankSynced ? (invValue + eqpValue + bankValue + geEscrowGp) : null); // null until bank opened
		snap.put("wealth", wealth);

		// ---- WAVE 5: live state (all ids javap-verified vs runelite-api 1.12.32; raw values, decoded server-side) ----
		snap.put("spellbook", client.getVarbitValue(Varbits.SPELLBOOK));          // 0 standard / 1 ancient / 2 lunar / 3 arceuus
		snap.put("attack_style", client.getVarpValue(VarPlayer.ATTACK_STYLE));    // 0..3 = the selected style slot
		snap.put("world", client.getWorld());
		snap.put("location", currentLocation());                                  // {region_id, plane} or null if unreadable

		List<String> activePrayers = new ArrayList<>();
		for (Prayer prayer : Prayer.values())
		{
			if (client.isPrayerActive(prayer))
			{
				activePrayers.add(prayer.name());
			}
		}
		snap.put("prayer_active", activePrayers);

		// Kourend house favour — 5 raw varbits (server divides by 10 for the %). Spelled FAVOR in the api enum.
		Map<String, Object> favour = new LinkedHashMap<>();
		favour.put("arceuus", client.getVarbitValue(Varbits.KOUREND_FAVOR_ARCEUUS));
		favour.put("hosidius", client.getVarbitValue(Varbits.KOUREND_FAVOR_HOSIDIUS));
		favour.put("lovakengj", client.getVarbitValue(Varbits.KOUREND_FAVOR_LOVAKENGJ));
		favour.put("piscarilius", client.getVarbitValue(Varbits.KOUREND_FAVOR_PISCARILIUS));
		favour.put("shayzien", client.getVarbitValue(Varbits.KOUREND_FAVOR_SHAYZIEN));
		snap.put("kourend_favour", favour);

		// Minigame points. NMZ + Tithe have clean point varbits; LMS has none in this jar (only IN_LMS state) so
		// LMS points are omitted rather than invented.
		Map<String, Object> minigames = new LinkedHashMap<>();
		minigames.put("nmz", client.getVarbitValue(Varbits.NMZ_POINTS));
		minigames.put("tithe", client.getVarbitValue(Varbits.TITHE_FARM_POINTS));
		// Own milestones the game keeps in vars (gameval ids, runelite-api 1.13.4), raw. Boss kill counts and
		// minigame scores are not in vars: the server reads those from the official hiscores.
		for (Object[] m : MINIGAME_VARBITS)
		{
			minigames.put((String) m[0], client.getVarbitValue((int) m[1]));
		}
		for (Object[] m : MINIGAME_VARPS)
		{
			minigames.put((String) m[0], client.getVarpValue((int) m[1]));
		}
		snap.put("minigame_points", minigames);

		return snap;
	}

	/**
	 * bank.open_at_capture: the bank items in this snapshot are the live container of an open bank. True only
	 * with the open seen and no close since, a populated live read, no first read still pending, and a bank
	 * change delivered since the open; absent otherwise (closed, closing, unloaded, a retained read from earlier
	 * in this login, or an open whose contents no change has confirmed yet). Uses the bank-session state, which
	 * runs for every linked token, not the staff-only visit id.
	 *
	 * Live 0.7.57 QA (2026-10-24): the snapshot sent at the open read a populated container before this open's
	 * ItemContainerChanged (bank.observed_at still the previous change). The contents were right there, but
	 * nothing proves a container read at the open is not an earlier copy, so the open snapshot carries the key
	 * only when the change arrived in the open's own tick, and the next snapshot carries it after the change.
	 */
	private boolean bankOpenAtCapture(ItemContainer liveBank)
	{
		if (liveBank == null || bankClosePending || client == null)
		{
			return false;
		}
		boolean confirmed = bankOpeningNow
			? bankChangeTick == client.getTickCount()
			: bankAtOpen != null && !bankBaselinePending && bankChangeTick >= bankOpenTick;
		if (!confirmed)
		{
			return false;
		}
		Item[] items = liveBank.getItems();
		return items != null && java.util.Arrays.stream(items).anyMatch(this::realItem);
	}

	/**
	 * The snapshot reads the live container of a bank open now (the open itself, or a visit with no close since)
	 * and no bank change of this open has arrived yet. Live 0.7.58 QA (2026-10-24, G4): after a deposit at a
	 * deposit box while the bank was closed, the open upload held the deposited item with the observed_at of the
	 * read before the deposit. A retained read after a close is not this case and keeps its own time.
	 */
	private boolean bankReadUnconfirmed(ItemContainer liveBank)
	{
		if (liveBank == null || client == null || bankClosePending)
		{
			return false;
		}
		if (bankOpeningNow)
		{
			return bankChangeTick != client.getTickCount();
		}
		return (bankAtOpen != null || bankBaselinePending) && bankChangeTick < bankOpenTick;
	}

	/** {region_id, plane} of the local player's world location, or null if it isn't currently readable. */
	private Map<String, Object> currentLocation()
	{
		net.runelite.api.Player p = client.getLocalPlayer();
		if (p == null)
		{
			return null;
		}
		net.runelite.api.coords.WorldPoint wp = p.getWorldLocation();
		if (wp == null)
		{
			return null;
		}
		Map<String, Object> loc = new LinkedHashMap<>();
		loc.put("region_id", wp.getRegionID());
		loc.put("plane", wp.getPlane());
		return loc;
	}

	// ---- container helpers ----

	private Map<String, Object> itemMap(int id, int qty)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("id", id);
		m.put("qty", qty);
		return m;
	}

	/** itemMap variant for quantities that can exceed int range (bank diffs, large coin/token stacks). */
	private Map<String, Object> itemMapLong(int id, long qty)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("id", id);
		m.put("qty", qty);
		return m;
	}

	/**
	 * A stack that is really held. A bank placeholder is its own item id with quantity 1 in the container (live run
	 * 2026-10-22: Bat bones 530 left placeholder 19269 x1), so it was sent as an item and moved in and out of the
	 * bank as a phantom deposit and withdrawal. Its composition names a placeholder template; nothing else does.
	 * Must run on the client thread (ItemManager composition). Without an ItemManager (tests) nothing is skipped.
	 */
	boolean realItem(Item item)
	{
		if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
		{
			return false;
		}
		net.runelite.api.ItemComposition c = itemManager == null ? null : itemManager.getItemComposition(item.getId());
		return c == null || c.getPlaceholderTemplateId() == -1;
	}

	private List<Map<String, Object>> itemList(ItemContainer c)
	{
		return itemList(c == null ? null : c.getItems());
	}

	private List<Map<String, Object>> itemList(Item[] items)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		if (items == null)
		{
			return out;
		}
		for (Item item : items)
		{
			if (realItem(item))
			{
				out.add(itemMap(item.getId(), item.getQuantity()));
			}
		}
		return out;
	}

	private long countItem(ItemContainer c, int id)
	{
		if (c == null)
		{
			return 0L;
		}
		long n = 0L;
		for (Item item : c.getItems())
		{
			if (item != null && item.getId() == id)
			{
				n += item.getQuantity();
			}
		}
		return n;
	}

	private long containerValue(ItemContainer c)
	{
		return containerValue(c == null ? null : c.getItems());
	}

	private long containerValue(Item[] items)
	{
		if (items == null)
		{
			return 0L;
		}
		long v = 0L;
		for (Item item : items)
		{
			if (realItem(item))
			{
				v += (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
			}
		}
		return v;
	}

	/** Seconds of the last ItemContainerChanged for this container id, or null when none was seen. */
	Long observedAtSeconds(int containerId)
	{
		Long ms = containerObservedAtMs.get(containerId);
		return ms == null ? null : ms / 1000L;
	}

	/** Add a {items, value_gp} block for a container, but only when it is present (opened this session). */
	void addContainerSnapshot(Map<String, Object> snap, String key, ItemContainer c)
	{
		if (c == null)
		{
			return;
		}
		if (observedAtSeconds(c.getId()) == null)
		{
			// Present but no change seen since this login's start (observation times clear on every hop and
			// relog), so this is not a reading of this login: live 0.7.55 sent 3 of 6 looting bags and 4 of 12
			// seed vaults with observed_at null. If the client kept it from before, it may even be another
			// account's. No block: the server keeps this account's last dated reading as carried.
			return;
		}
		if ("seed_box".equals(key))
		{
			Map<String,Object> seed = seedBoxSnapshot(c);
			if (seed != null) snap.put(key, seed);
			return;
		}
		Map<String, Object> block = new LinkedHashMap<>();
		block.put("items", itemList(c));
		block.put("value_gp", containerValue(c));
		block.put("observed_at", observedAtSeconds(c.getId()));
		snap.put(key, block);
	}

	/** Own fixed container only. Unknown or malformed cache never becomes an empty box. */
	private Map<String,Object> seedBoxSnapshot(ItemContainer c)
	{
		if (c.getId() != net.runelite.api.gameval.InventoryID.SEED_BOX) return null;
		Item[] raw = c.getItems();
		if (raw == null || raw.length > 4096) return null;
		Map<Integer,Long> totals = new java.util.TreeMap<>();
		for (Item item : raw)
		{
			if (item == null || item.getId() < -1 || item.getQuantity() < 0
				|| item.getId() <= 0 && item.getQuantity() > 0) return null;
			if (item.getId() > 0 && item.getQuantity() > 0)
				totals.merge(item.getId(), (long)item.getQuantity(), Long::sum);
		}
		List<Map<String,Object>> items = new ArrayList<>();
		Long estimate = 0L;
		for (Map.Entry<Integer,Long> entry : totals.entrySet())
		{
			items.add(itemMapLong(entry.getKey(), entry.getValue()));
			if (estimate != null)
			{
				long price = itemManager == null ? -1 : itemManager.getItemPrice(entry.getKey());
				if (price <= 0) estimate = null;
				else try { estimate = Math.addExact(estimate, Math.multiplyExact(price, entry.getValue())); }
				catch (ArithmeticException overflow) { estimate = null; }
				if (estimate != null && estimate > 9007199254740991L) estimate = null; // exact JSON integer range
			}
		}
		Map<String,Object> block = new LinkedHashMap<>(); block.put("items", items); block.put("value_gp", estimate);
		block.put("observed_at", observedAtSeconds(net.runelite.api.gameval.InventoryID.SEED_BOX));
		block.put("basis", "client_cached_seed_box"); block.put("complete", false);
		block.put("status", items.isEmpty() ? "observed_empty_cache" : "cached_items");
		block.put("valuation_basis", "client_item_price_estimate"); return block;
	}

	/**
	 * Async snapshot POST. The response drives the upload gate's memory: a 2xx accept records the
	 * uploaded hash (so unchanged ticks stop re-sending) and clears any backoff; a 429 arms the
	 * backoff window from Retry-After (or exponential). hash is the CANONICAL hash of this snapshot
	 * — recorded on accept, never the raw JSON hash.
	 */
	private void postSnapshot(String token, Map<String, Object> snapshot, String hash)
	{
		if (!uploadAllowed() || !token.equals(currentLinkToken()))
		{
			return;		// upload switch off — send nothing
		}
		final Map<String, Object> sentSnapshot = new LinkedHashMap<>(snapshot);
		sentSnapshot.remove("group_storage"); // also covers cached snapshots from before this boundary
		if (!broadCaptureEnabled()) stripBroadCapture(sentSnapshot);
		// Recheck separate grants at serialization, including cached logout snapshots.
		if (!progressGranted() || !token.equals(progressGrantToken)) sentSnapshot.remove("account_progress");
		if (!gameplayGranted() || !token.equals(gameplayGrantToken)) sentSnapshot.remove("own_gameplay");
		final String sentHash = canonicalHash(sentSnapshot);
		Object sentBank = sentSnapshot.get("bank");
		Object sentBankSha = sentBank instanceof Map ? ((Map<?, ?>) sentBank).get("manifest_sha256") : null;
		Object sentAccount = sentSnapshot.get("account");
		Object sentHashValue = sentAccount instanceof Map ? ((Map<?, ?>) sentAccount).get("account_hash") : null;
		final String bankAccount = sentHashValue instanceof String ? (String) sentHashValue : null;
		final String bankSha = sentBankSha instanceof String ? (String) sentBankSha : null;
		final boolean bankTimed = sentBank instanceof Map && ((Map<?, ?>) sentBank).get("observed_at") != null;
		queuedBankToken = token;
		queuedBankAccount = bankAccount;
		queuedBankSha = bankSha;
		queuedBankTimed = bankTimed;
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("token", token);
		body.put("snapshot", sentSnapshot);

		String base = config.apiBaseUrl() == null ? "" : config.apiBaseUrl().replaceAll("/+$", "");
		Request request = new Request.Builder()
			.url(base + "/account-ingest")
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				if (token.equals(currentLinkToken()))
				{
					snapshotRetryPending = true;
					applyRateLimitBackoff(null);
				}
				forgetQueuedBank(bankSha);
				log.debug("OSRS BiS sync failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					if (!token.equals(currentLinkToken())) return; // stale identity cannot grant or ACK this cache
					int code = response.code();
					applyServerPolicy(response, token);	// server dictates cadence / screenshot-disable per token
					if (code == 403)
					{
						spoolOnRevoked(token);	// a revoked link: its durable spool is purged
					}
					if (response.isSuccessful())
					{
						acceptedBankToken = token;
						acceptedBankAccount = bankAccount;
						acceptedBankSha = bankSha;
						acceptedBankTimed = bankTimed;
						onUploadAccepted(sentHash);
						Object gv = sentSnapshot.get("game_vars");
						if (gv instanceof Map)
						{
							lastGameVarsSentMs = System.currentTimeMillis();
						}
					}
					else
					{
						snapshotRetryPending = true;
						applyRateLimitBackoff(response.header("Retry-After"));
						forgetQueuedBank(bankSha);
					}
					// All failed snapshot requests remain pending behind bounded retry backoff.
					log.debug("OSRS BiS sync response: {}", code);
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	/** A failed upload: a newer one may have replaced the queued record, so only the same bank is forgotten. */
	private void forgetQueuedBank(String sha)
	{
		if (sha != null && sha.equals(queuedBankSha))
		{
			queuedBankSha = null;
		}
	}

	/** A 2xx accept: this canonical hash is now the server's known state, and any 429 backoff clears. */
	private void onUploadAccepted(String hash)
	{
		snapshotRetryPending = false;
		lastUploadedHash = hash;
		healthLastSnapshotUploadMs.set(System.currentTimeMillis());
		backoffUntilMillis = 0L;
		nextBackoffMillis = BACKOFF_START_MILLIS;
	}

	/**
	 * Apply the per-token policy osrsbestinslot.com returns on the ingest response. All directives are
	 * "narrow/control" only (Hub-safe): the server can set the sync cadence, force trade screenshots
	 * OFF, and soft-pause a token — it can never force screenshots ON or expand what's collected.
	 *   X-Sync-Interval    seconds, clamped [5, 600] — the minimum gap between sends.
	 *   X-Screenshots      "off"/"disabled"/"false" force-disables trade-screenshot capture.
	 *   X-Clips            "off"/"disabled"/"false" force-disables store delivery-clip capture.
	 *   X-Store-Tools      "on"/"enabled"/"true"/"1" grants the shop overlays for this token. The
	 *                      overlays draw only and send nothing, so the grant expands no collection.
	 *                      It does NOT grant drop-trade recording; that is X-Drop-Proof below, and
	 *                      keeping them apart is the whole reason that header exists.
	 *   X-Drop-Proof       "on"/"enabled"/"true"/"1" ROLLS OUT drop-trade screen recording to this
	 *                      token. Absent, false or unparseable = OFF, and a response that never
	 *                      arrives leaves it OFF, so an unknown state never records. It is a
	 *                      rollout control, not an authorization: the server still decides on its
	 *                      own staff check whether to keep a drop_frames upload.
	 *   X-Uploads-Enabled  "false"/"0" soft-pauses the token: cadence drops to the 600s max so the
	 *                      policy channel stays open (the hard data-stop is enforced server-side by
	 *                      dropping the token's snapshots — the client never goes dark, so it can be
	 *                      re-enabled on the next poll). Any header absent = that directive unchanged.
	 */
	void applyServerPolicy(Response response)
	{
		applyServerPolicy(response, currentLinkToken());
	}

	/**
	 * sentToken is the token the request carried. The spool grant is applied only when it is still the
	 * configured token, so a late response for an old token can never switch the new identity on.
	 *   X-Event-Spool      "on"/"enabled"/"true"/"1" turns the durable event spool on for this token;
	 *                      "off"/"disabled"/"false"/"0" turns it off and purges this identity's spool.
	 *                      Absent or unparseable = unchanged; the default is off.
	 */
	void applyServerPolicy(Response response, String sentToken)
	{
		if (sentToken == null || !sentToken.equals(currentLinkToken())) return;
		String queueScope = response.header("X-Event-Queue");
		if (response.isSuccessful() && ("ge-v1".equals(queueScope) || "own-history-v1".equals(queueScope)
			|| "own-combat-v1".equals(queueScope) || "own-state-v1".equals(queueScope) || "own-vars-v1".equals(queueScope) || "own-signals-v1".equals(queueScope)))
		{
			eventQueueScope = queueScope;
			eventQueueGrantToken = sentToken;
		}
		else { eventQueueGrantToken = null; eventQueueScope = null; }

		// No existing broad/progress grant widens the capture scope. Missing/failed response revokes.
		String gameplay = response.header("X-Own-Gameplay");
		String gameplayGrant = response.isSuccessful() && "on".equalsIgnoreCase(gameplay == null ? "" : gameplay.trim()) ? sentToken : null;
		if (!java.util.Objects.equals(gameplayGrant, gameplayGrantToken)) gameplayGrantEpoch++;
		gameplayGrantToken = gameplayGrant;

		// Separate batch2 disclosure gate: batch1's X-Broad-Capture does not grant these fields.
		String progress = response.header("X-Account-Progress");
		if (progress != null && sentToken != null && sentToken.equals(currentLinkToken()))
		{
			String grant = "on".equalsIgnoreCase(progress.trim()) && response.isSuccessful() ? sentToken : null;
			if (!java.util.Objects.equals(grant, progressGrantToken))
			{
				progressGrantEpoch++;
			}
			progressGrantToken = grant;
		}
		if (response.code() == 403 && sentToken != null && sentToken.equals(progressGrantToken))
		{
			progressGrantToken = null;
			progressGrantEpoch++;
			gameplayGrantToken = null;
			gameplayGrantEpoch++;
		}
		String eventSpool = response.header("X-Event-Spool");
		if (eventSpool != null && sentToken != null && sentToken.equals(currentLinkToken()))
		{
			String v = eventSpool.trim().toLowerCase(java.util.Locale.ROOT);
			if ("on".equals(v) || "enabled".equals(v) || "true".equals(v) || "1".equals(v))
			{
				setSpoolGrant(sentToken, true);
			}
			else if ("off".equals(v) || "disabled".equals(v) || "false".equals(v) || "0".equals(v))
			{
				setSpoolGrant(sentToken, false);
			}
		}

		// X-Bank-Evidence: on grants bank-visit evidence to THIS token. Missing or anything else = off, so a
		// grant lasts only while the newest snapshot response keeps sending it.
		if (sentToken != null && sentToken.equals(currentLinkToken()))
		{
			String bank = response.header("X-Bank-Evidence");
			String v = bank == null ? "" : bank.trim().toLowerCase(java.util.Locale.ROOT);
			bankEvidenceToken = ("on".equals(v) || "enabled".equals(v) || "true".equals(v) || "1".equals(v))
				? sentToken : null;
		}
		// Distinct public capability: old servers and staff grants never enable this journal.
		bankJournalGrantToken = response.isSuccessful() && sentToken.equals(bankEvidenceToken)
			&& !sentToken.equals(spoolGrantToken) && "event-id-v1".equals(response.header("X-Bank-Receipt"))
			? sentToken : null;


		// The server grant binds this exact account and link token to staff media/evidence.
		// A late response for a previous account never opens a new account's recorder.
		// An accepted upload without the grant ends it, and so does any refusal (4xx). Only a 429 or a 5xx
		// says nothing about staff, so only those keep it and leave a running store clip alone.
		boolean previouslyGranted = staffCaptureEnabled();
		if (!configuredForStaffApi() || !onStaffApi(response.request().url().toString()))
		{
			clearStaffCaptureGrant();
		}
		else if (response.isSuccessful())
		{
			String staffCapture = response.header("X-Staff-Capture");
			String staffAccount = response.header("X-Staff-Account");
			if ("on".equalsIgnoreCase(staffCapture == null ? "" : staffCapture.trim())
				&& staffAccount != null && staffAccount.trim().matches("-?[0-9]{1,19}"))
			{
				setStaffCaptureForTest(sentToken, staffAccount.trim());
			}
			else
			{
				clearStaffCaptureGrant();
			}
		}
		else if (response.code() >= 400 && response.code() < 500 && response.code() != 429)
		{
			clearStaffCaptureGrant();
		}
		String screenshots = response.header("X-Screenshots");
		if (screenshots != null)
		{
			String v = screenshots.trim().toLowerCase(java.util.Locale.ROOT);
			serverScreenshotsDisabled = "off".equals(v) || "disabled".equals(v) || "false".equals(v);
		}

		String storeTools = response.header("X-Store-Tools");
		if (storeTools != null)
		{
			String v = storeTools.trim().toLowerCase(java.util.Locale.ROOT);
			boolean on = "on".equals(v) || "enabled".equals(v) || "true".equals(v) || "1".equals(v);
			serverStoreToolsEnabled = on;
			if (!on)
			{
				removeResetTimer();	// a revoked grant must clear what is already on screen
			}
		}
		// Either header can end staff capture. A store clip recording when it ends is dropped, not sent.
		if (previouslyGranted && !staffCaptureEnabled())
		{
			stopStoreClipCapture(false);
			removeResetTimer();
		}

		String maxCap = response.header("X-Max-Capture");
		if (maxCap != null)
		{
			String v = maxCap.trim().toLowerCase(java.util.Locale.ROOT);
			boolean on = "on".equals(v) || "enabled".equals(v) || "true".equals(v) || "1".equals(v);
			serverMaxCaptureEnabled = on;
			if (!on)
			{
				clearFirehose();	// a revoked grant drops whatever is still buffered
			}
		}

		String gameVars = response.header("X-Broad-Capture");
		String broad = gameVars == null ? "" : gameVars.trim().toLowerCase(java.util.Locale.ROOT);
		setBroadCaptureGrant(sentToken, response.isSuccessful()
			&& ("on".equals(broad) || "enabled".equals(broad) || "true".equals(broad) || "1".equals(broad)));

		String clips = response.header("X-Clips");
		if (clips != null)
		{
			String v = clips.trim().toLowerCase(java.util.Locale.ROOT);
			serverClipsDisabled = "off".equals(v) || "disabled".equals(v) || "false".equals(v);
		}

		// THE ROLLOUT FLAG. Absent header leaves it unchanged, exactly like every other directive,
		// because a single malformed response must not silently revoke a live rollout. It starts
		// false and only an explicit on-value ever sets it, so the fail-closed default holds.
		String dropProof = response.header("X-Drop-Proof");
		if (dropProof != null)
		{
			String v = dropProof.trim().toLowerCase(java.util.Locale.ROOT);
			serverDropProofEnabled = "on".equals(v) || "enabled".equals(v)
				|| "true".equals(v) || "1".equals(v);
		}
		// A capability that has just become reachable owes the user the notice, and a capability
		// that has just gone away must not leave a recorder running.
		onDropProofCapabilityChanged();

		boolean paused = false;
		String uploadsEnabled = response.header("X-Uploads-Enabled");
		if (uploadsEnabled != null)
		{
			String v = uploadsEnabled.trim().toLowerCase(java.util.Locale.ROOT);
			paused = "false".equals(v) || "0".equals(v) || "off".equals(v);
			// An operator pause holds spool REPLAY only. Writes continue within bounds; nothing is purged.
			spoolReplayPaused = paused;
		}

		String interval = response.header("X-Sync-Interval");
		if (paused)
		{
			minUploadIntervalMillis = 600_000L;	// soft-pause: max cadence, still polls for re-enable
		}
		else if (interval != null)
		{
			try
			{
				long s = Long.parseLong(interval.trim());
				minUploadIntervalMillis = Math.max(5L, Math.min(s, 600L)) * 1000L;
			}
			catch (NumberFormatException ignored)
			{
				// malformed directive — keep the current cadence
			}
		}
		pumpPublicOutbox();
	}

	/**
	 * 429 rate-limited: honor Retry-After (seconds) when present, capped at 1h; otherwise exponential
	 * backoff from 60s, doubling to a 15m cap. While backed off, ticks build + track the snapshot but
	 * never send (see syncTask); the next accepted upload resets the schedule.
	 */
	private void applyRateLimitBackoff(String retryAfterHeader)
	{
		long now = System.currentTimeMillis();
		Long retryAfterSeconds = parseRetryAfterSeconds(retryAfterHeader);
		if (retryAfterSeconds != null)
		{
			long capped = Math.min(retryAfterSeconds, RETRY_AFTER_CAP_SECONDS);
			backoffUntilMillis = now + capped * 1000L;
			return;
		}
		long wait = Math.min(nextBackoffMillis, BACKOFF_CAP_MILLIS);
		backoffUntilMillis = now + wait;
		nextBackoffMillis = Math.min(nextBackoffMillis * 2, BACKOFF_CAP_MILLIS);
	}

	/** Retry-After as integer seconds; null if absent/blank/negative/non-integer (HTTP-date unsupported). */
	static Long parseRetryAfterSeconds(String header)
	{
		if (header == null)
		{
			return null;
		}
		String trimmed = header.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}
		try
		{
			long seconds = Long.parseLong(trimmed);
			return seconds < 0 ? null : seconds;
		}
		catch (NumberFormatException e)
		{
			return null; // HTTP-date form not handled — fall back to exponential
		}
	}
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.StructComposition;
import net.runelite.api.Skill;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.VarbitComposition;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.util.Text;

/** Own-account observations only. No persistence or third-party plugin dependencies. Only the permitted collection Search action. */
final class AccountProgressCapture
{
    // Cache-generated gameval 1.13.1 IDs; numeric IDs avoid linking newer enum fields on older clients.
    private static final Pattern CLUE = Pattern.compile("^You have completed ([0-9,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.$");
    private static final Pattern COLLECTION = Pattern.compile("^New item added to your collection log: (.{1,160})$");
    private static final Pattern CA = Pattern.compile("^(?:CA_ID:([0-9]+)\\|)?Congratulations, you've completed an? (easy|medium|hard|elite|master|grandmaster) combat task: (.{1,160})\\.$", Pattern.CASE_INSENSITIVE);
    private static final Pattern SALVAGE = Pattern.compile("^You sort through the (Small|Fishy|Barracuda|Large|Plundered|Martial|Fremennik|Opulent) salvage and find: ([0-9,]+) x (.{1,160})\\.$", Pattern.CASE_INSENSITIVE);
    private String identity;
    private int settleTick;
    private final Map<Integer, Integer> collectionItems = new TreeMap<>();
    private Long collectionObservedAt;
    private final Map<String, Map<String, Object>> signals = new LinkedHashMap<>();
    private int evicted;
    private final GeHistoryCapture geHistory = new GeHistoryCapture();
    final StorageRecoveryCapture storageRecovery = new StorageRecoveryCapture();
    private boolean scanActive, scanComplete, scanAttempted;
    private int scanStartTick, lastSlotTick, nextScanTick;
    private Integer scanObtained, scanTotal;
    private Long scanStartedAt, scanVerifiedAt;
    private String scanStatus = "not_scanned";
    // Static game-cache CA catalogue (task id -> tier), loaded on the client thread. Not account data.
    private Map<Integer, String> caCatalog;
    private int caCatalogNextTick;

    void reset()
    {
        identity = null;
        collectionItems.clear();
        collectionObservedAt = null;
        signals.clear();
        evicted = 0;
        geHistory.reset();
        storageRecovery.reset();
        scanActive = scanComplete = scanAttempted = false;
        nextScanTick = 0;
        scanObtained = scanTotal = null;
        scanStartedAt = scanVerifiedAt = null;
        scanStatus = "not_scanned";
    }

    boolean ready(Client client, String token)
    {
        // Region loads are not account transitions. Retain last-seen observations, but do not read.
        if (client != null && client.getGameState() == GameState.LOADING)
        {
            storageRecovery.gap();
            return false;
        }
        if (client == null || client.getGameState() != GameState.LOGGED_IN
            || client.getLocalPlayer() == null || (client.getAccountHash() == -1L || client.getAccountHash() == 0L)
            || client.getRealSkillLevel(Skill.HITPOINTS) <= 0)
        {
            reset();
            return false;
        }
        String key = token + ":" + client.getAccountHash() + ":" + RuneScapeProfileType.getCurrent(client).name();
        if (!Objects.equals(identity, key))
        {
            reset();
            identity = key;
            settleTick = client.getTickCount();
            return false;
        }
        return client.getTickCount() - settleTick >= 2;
    }

    void collectionSlot(Client client, Object[] args, long now)
    {
        // Missing discriminator is unknown, never permission to read a house host's log.
        Integer host = bit(client, client.getVarps(), 12061);
        if (!Integer.valueOf(0).equals(host) || args == null || args.length < 3
            || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
        {
            return;
        }
        int id = (Integer) args[1];
        int quantity = (Integer) args[2];
        if (id <= 0 || (quantity < 0 || (quantity == 0 && !scanActive)) || (collectionItems.size() >= 4096 && !collectionItems.containsKey(id)))
        {
            return;
        }
        lastSlotTick = client.getTickCount();
        if (!Objects.equals(collectionItems.get(id), quantity))
        {
            scanComplete = false;
            if (!scanActive && scanVerifiedAt != null) scanStatus = "slots_changed";
        }
        collectionItems.put(id, quantity); // absolute count, repeated draws never increment
        collectionObservedAt = now;
    }

    /** Called only after the existing grant and account-settlement gate, on the client thread. */
    void collectionSetup(Client client, long now)
    {
        if (scanAttempted || client.getTickCount() < nextScanTick || !ownLog(client) || verifiedForCurrentCounts(client)) return;
        Widget search = client.getWidget(InterfaceID.Collection.SEARCH_TOGGLE);
        if (search == null || search.isHidden()) return;
        scanAttempted = true; // set before synchronous scripts can re-enter
        nextScanTick = client.getTickCount() + 100;
        scanActive = true;
        scanComplete = false;
        scanStatus = "scanning";
        scanStartTick = lastSlotTick = client.getTickCount();
        scanStartedAt = now;
        scanVerifiedAt = null;
        scanObtained = varp(client.getVarps(), 2943);
        scanTotal = varp(client.getVarps(), 2944);
        collectionItems.clear();
        collectionObservedAt = null;
        try
        {
            // RuneLite's sole documented menuAction exception. Never enable packet-sending scripts.
            client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
            client.runScript(2240);
        }
        catch (RuntimeException | LinkageError ex)
        {
            scanActive = false;
            scanStatus = "unsupported_client"; // passive script observations remain usable
        }
    }

    void collectionClosed()
    {
        scanAttempted = false;
        if (scanActive)
        {
            scanActive = false;
            scanStatus = "closed_before_verification";
        }
    }

    private boolean ownLog(Client client)
    {
        return Integer.valueOf(0).equals(bit(client, client.getVarps(), 12061));
    }

    void poll(Client client, long now)
    {
        if (caCatalog == null && client.getTickCount() >= caCatalogNextTick)
        {
            caCatalog = loadCaCatalog(client);
            if (caCatalog == null) caCatalogNextTick = client.getTickCount() + 100;
        }
        geHistory.poll(client, now);
        storageRecovery.poll(client, now);
        pollCollection(client, now);
    }

    /** The collection part of {@link #poll}: ends a running search scan when its slots match the game's count. */
    void pollCollection(Client client, long now)
    {
        if (!ownLog(client))
        {
            scanActive = scanComplete = false;
            scanStatus = "own_log_unverified";
            return;
        }
        if ((scanComplete || scanActive) && (!Objects.equals(scanObtained, varp(client.getVarps(), 2943))
            || !Objects.equals(scanTotal, varp(client.getVarps(), 2944))))
        {
            scanActive = scanComplete = false;
            scanStatus = "counts_changed";
        }
        if (!scanActive) return;
        int tick = client.getTickCount();
        if (tick - scanStartTick > 20)
        {
            scanActive = false;
            scanStatus = "timeout";
            return;
        }
        if (tick - lastSlotTick < 3) return;
        Integer obtained = varp(client.getVarps(), 2943), total = varp(client.getVarps(), 2944);
        if (total != null && total > 0 && obtained != null && obtained >= 0 && obtained <= total
            && Objects.equals(scanTotal, total) && Objects.equals(scanObtained, obtained)
            && positiveCollectionCount() == obtained)
        {
            scanActive = false;
            scanComplete = true;
            scanStatus = "count_verified";
            scanVerifiedAt = now;
            if (collectionObservedAt == null) collectionObservedAt = now / 1000L;
        }
        // Mismatch is not completion; leave time for delayed transmissions until the timeout.
    }

    /** Where the search scan stands: not_scanned, scanning, count_verified, timeout, unsupported_client, ... */
    String collectionScanStatus()
    {
        return scanStatus;
    }

    /** A verified scan whose counts the game still shows: a new open does not scan again. */
    private boolean verifiedForCurrentCounts(Client client)
    {
        return scanComplete && Objects.equals(scanObtained, varp(client.getVarps(), 2943))
            && Objects.equals(scanTotal, varp(client.getVarps(), 2944));
    }

    /** The scan saw every obtained slot: own log, distinct positive items equal to the game's unchanged counts. */
    private boolean collectionVerified(Client client, int[] vars)
    {
        boolean own = Integer.valueOf(0).equals(bit(client, vars, 12061));
        Integer total = own ? varp(vars, 2944) : null;
        Integer obtained = own ? varp(vars, 2943) : null;
        boolean countsKnown = total != null && total > 0 && obtained != null && obtained >= 0 && obtained <= total;
        return scanComplete && own && countsKnown
            && Objects.equals(scanObtained, obtained) && Objects.equals(scanTotal, total)
            && positiveCollectionCount() == obtained;
    }

    /**
     * The whole collection log from a verified scan: every obtained item id, the game's counts and the scan time.
     * Null when no scan of this login is verified for the counts the game shows now.
     */
    Map<String, Object> verifiedCollection(Client client)
    {
        int[] live = client.getVarps();
        int[] vars = live == null ? null : live.clone();
        if (!collectionVerified(client, vars))
        {
            return null;
        }
        java.util.List<Integer> ids = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : collectionItems.entrySet())
        {
            if (e.getValue() > 0)
            {
                ids.add(e.getKey());
            }
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("obtained_item_ids", ids);
        out.put("game_obtained_count", varp(vars, 2943));
        out.put("game_total_count", varp(vars, 2944));
        out.put("verified_at_ms", scanVerifiedAt);
        return out;
    }

    private long positiveCollectionCount()
    {
        return collectionItems.values().stream().filter(quantity -> quantity > 0).count();
    }

    void chat(String message, long now)
    {
        Map<String, Object> signal = parseMessage(message);
        if (signal == null)
        {
            return;
        }
        String key = signal.get("kind") + ":" + signal.get("subject");
        Map<String, Object> old = signals.get(key);
        // Identical chat/SPAM callbacks must not churn timestamps or create duplicate observations.
        if (old != null)
        {
            Map<String, Object> value = new LinkedHashMap<>(old);
            value.remove("observed_at");
            if (value.equals(signal))
            {
                return;
            }
        }
        signal.put("observed_at", now);
        signals.remove(key);
        signals.put(key, signal);
        if (signals.size() > 128)
        {
            signals.remove(signals.keySet().iterator().next());
            evicted++;
        }
    }

    static Map<String, Object> parseMessage(String message)
    {
        if (message == null || message.length() > 512)
        {
            return null;
        }
        String text = Text.removeTags(message).replaceAll("@\\w+@", "").replace('\u00a0', ' ').trim();
        Map<String, Object> out = new LinkedHashMap<>();
        Matcher m = CLUE.matcher(text);
        try
        {
            if (m.matches())
            {
                out.put("kind", "clue_complete");
                out.put("subject", m.group(2));
                out.put("count", positiveCount(m.group(1)));
            }
            else if ((m = COLLECTION.matcher(text)).matches())
            {
                out.put("kind", "collection_log_add");
                out.put("subject", m.group(1)); // name only: never invent an item id
            }
            else if ((m = CA.matcher(text)).matches())
            {
                out.put("kind", "combat_achievement");
                out.put("subject", m.group(3));
                out.put("tier", m.group(2).toLowerCase(java.util.Locale.ROOT));
                out.put("task_id", m.group(1) == null ? null : Long.parseLong(m.group(1)));
            }
            else if ((m = SALVAGE.matcher(text)).matches())
            {
                out.put("kind", "salvage_sort");
                out.put("subject", m.group(3));
                out.put("shipwreck_type", m.group(1).toLowerCase(java.util.Locale.ROOT));
                out.put("quantity", positiveCount(m.group(2)));
            }
            else
            {
                return null;
            }
        }
        catch (NumberFormatException ex)
        {
            return null;
        }
        out.put("source", "game_message");
        return out;
    }

    private static long positiveCount(String value)
    {
        if (!value.matches("(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)"))
        {
            throw new NumberFormatException();
        }
        long count = Long.parseLong(value.replace(",", ""));
        if (count <= 0)
        {
            throw new NumberFormatException();
        }
        return count;
    }

    Map<String, Object> snapshot(Client client)
    {
        int[] live = client.getVarps();
        int[] vars = live == null ? null : live.clone();
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("source", "runelite_account_progress");
        Map<String, Object> slayer = new LinkedHashMap<>();
        Integer target = varp(vars, 395);
        Integer remaining = varp(vars, 394);
        boolean active = remaining != null && remaining > 0;
        slayer.put("task_target_id", target);
        slayer.put("task_remaining", remaining);
        slayer.put("boss_id", active && Integer.valueOf(98).equals(target) ? bit(client, vars, 4723) : null);
        slayer.put("area_id", active ? varp(vars, 2096) : null);
        slayer.put("task_original", active ? varp(vars, 4258) : null);
        out.put("slayer", slayer);
        Map<String, Object> prayers = new LinkedHashMap<>();
        String[] names = {"rigour", "augury", "preserve", "deadeye", "mystic_vigour"};
        int[] ids = {5451, 5452, 5453, 16097, 16098};
        for (int i = 0; i < ids.length; i++)
        {
            Integer value = bit(client, vars, ids[i]);
            prayers.put(names[i], value == null ? null : value == 1);
        }
        // Keep raw quest state: the threshold for chivalry/piety is not runtime-verified here.
        prayers.put("knight_waves_state", bit(client, vars, 3909));
        out.put("prayer_unlocks", prayers);
        Map<String, Object> watson = new LinkedHashMap<>();
        String[] tiers = {"easy", "medium", "hard", "elite"};
        for (int i = 0; i < tiers.length; i++)
        {
            Integer value = bit(client, vars, 5186 + i);
            watson.put(tiers[i], value == null ? null : value == 1);
        }
        out.put("watson_clues", watson);
        out.put("combat_achievement_points", bit(client, vars, 14815));
        out.put("combat_achievement_tasks", caTasks(vars, caCatalog));
        Map<String, Object> log = new LinkedHashMap<>();
        boolean own = Integer.valueOf(0).equals(bit(client, vars, 12061));
        Integer total = own ? varp(vars, 2944) : null;
        Integer obtained = own ? varp(vars, 2943) : null;
        boolean countsKnown = total != null && total > 0 && obtained != null && obtained >= 0 && obtained <= total;
        log.put("game_obtained_count", countsKnown ? obtained : null);
        log.put("game_total_count", countsKnown ? total : null);
        log.put("notification_setting", bit(client, vars, 11959));
        log.put("observed_at", collectionObservedAt);
        log.put("observed_item_count", collectionObservedAt == null ? null : collectionItems.size());
        log.put("items", new TreeMap<>(collectionItems));
        boolean verified = collectionVerified(client, vars);
        log.put("complete", verified);
        log.put("completeness_basis", verified ? "own_search_scan_unique_count_matches_game" : "unverified");
        log.put("scan_status", scanComplete && !verified ? "counts_changed" : scanStatus);
        log.put("scan_expected_obtained_count", scanObtained);
        log.put("scan_expected_total_count", scanTotal);
        log.put("observed_positive_item_count", collectionObservedAt == null ? null : positiveCollectionCount());
        log.put("scan_started_at_ms", scanStartedAt);
        log.put("scan_verified_at_ms", scanVerifiedAt);
        log.put("source", "script_4100_observed_slots");
        out.put("collection_log", log);
        out.put("ge_history", geHistory.snapshot());
        out.put("storage_recovery", storageRecovery.snapshot(client));
        out.put("recent_signals", new ArrayList<>(signals.values()));
        out.put("signals_evicted", evicted);
        return out;
    }

    /**
     * Raw CA completion words plus game-cache catalogue metadata. completed_by_tier lists only completed ids whose
     * tier the cache catalogue states; the bit position alone is the task id. Unknown word = whole list null.
     */
    static Map<String, Object> caTasks(int[] vars, Map<Integer, String> catalog)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        java.util.List<Integer> words = new ArrayList<>();
        boolean known = vars != null;
        for (int id : AccountReadiness.CA_TASK_VARPS)
        {
            Integer w = varp(vars, id);
            known &= w != null;
            words.add(w);
        }
        out.put("words", known ? words : null);
        out.put("source", "varp:CA_TASK_COMPLETED_0..20");
        out.put("catalog_status", catalog == null ? "unavailable" : "loaded");
        if (catalog == null || !known)
        {
            out.put("completed_by_tier", null);
            out.put("catalog_task_totals", null);
            return out;
        }
        Map<String, Object> byTier = new LinkedHashMap<>();
        Map<String, Integer> totals = new LinkedHashMap<>();
        StringBuilder canon = new StringBuilder();
        for (String tier : AccountReadiness.CA_TIERS)
        {
            byTier.put(tier, new ArrayList<Integer>());
            totals.put(tier, 0);
        }
        for (Map.Entry<Integer, String> e : catalog.entrySet())
        {
            totals.put(e.getValue(), totals.get(e.getValue()) + 1);
            canon.append(e.getKey()).append('=').append(e.getValue()).append(';');
            int w = e.getKey() / 32, b = e.getKey() % 32;
            if ((words.get(w) & (1 << b)) != 0) ((java.util.List<Integer>) byTier.get(e.getValue())).add(e.getKey());
        }
        out.put("catalog_source", "enum:3981..3986,param:1306");
        out.put("catalog_sha256", AccountConnectPlugin.sha256Hex(canon.toString()));
        out.put("completed_by_tier", byTier);
        out.put("catalog_task_totals", totals);
        return out;
    }

    /** Client thread only. Enums 3981..3986 list CA task structs by tier; struct param 1306 is the task id. */
    static Map<Integer, String> loadCaCatalog(Client client)
    {
        try
        {
            Map<Integer, String> catalog = new TreeMap<>();
            for (int t = 0; t < AccountReadiness.CA_TIERS.size(); t++)
            {
                EnumComposition tier = client.getEnum(3981 + t);
                int[] structs = tier == null ? null : tier.getIntVals();
                if (structs == null || structs.length == 0 || structs.length > 4096) return null;
                for (int structId : structs)
                {
                    StructComposition struct = client.getStructComposition(structId);
                    if (struct == null) return null;
                    int task = struct.getIntValue(1306);
                    // A duplicate or out-of-range id means the cache layout changed: refuse the whole catalogue.
                    if (task < 0 || task >= 32 * AccountReadiness.CA_TASK_VARPS.length || catalog.containsKey(task)) return null;
                    catalog.put(task, AccountReadiness.CA_TIERS.get(t));
                }
            }
            return catalog;
        }
        catch (RuntimeException | LinkageError ex)
        {
            return null;
        }
    }

    static Integer varp(int[] vars, int id)
    {
        return vars == null || id < 0 || id >= vars.length ? null : vars[id];
    }

    static Integer bit(Client client, int[] vars, int id)
    {
        try
        {
            VarbitComposition def = client.getVarbit(id);
            // All listed sources use a positive varp index. A missing cache file can return
            // a default 0/0/0 composition instead of null on mixed client versions.
            if (def == null || def.getIndex() <= 0 || varp(vars, def.getIndex()) == null
                || def.getLeastSignificantBit() < 0 || def.getMostSignificantBit() > 31
                || def.getMostSignificantBit() < def.getLeastSignificantBit())
            {
                return null;
            }
            return GameVarsCapture.varbit(vars[def.getIndex()], def.getLeastSignificantBit(), def.getMostSignificantBit());
        }
        catch (RuntimeException ex)
        {
            return null; // missing cache definition on an older client is unknown, never locked/zero
        }
    }
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * progress.readiness.v1: named, versioned unlock/task state derived ONLY from the raw account_progress block.
 * Pure and deterministic: the same raw block gives the same result, so it is safe inside the change hash.
 * A missing raw value is "unknown", never "locked". No wall-clock time is added here; the caller owns as-of.
 */
final class AccountReadiness
{
    static final String SCHEMA = "progress.readiness.v1";
    // Cache-generated gameval 1.13.1 names next to their IDs, the same numbers AccountProgressCapture reads.
    private static final String[][] PRAYERS = {
        {"prayer.rigour", "varbit:5451"},          // PRAYER_RIGOUR_UNLOCKED
        {"prayer.augury", "varbit:5452"},          // PRAYER_AUGURY_UNLOCKED
        {"prayer.preserve", "varbit:5453"},        // PRAYER_PRESERVE_UNLOCKED
        {"prayer.deadeye", "varbit:16097"},        // PRAYER_DEADEYE_UNLOCKED
        {"prayer.mystic_vigour", "varbit:16098"},  // PRAYER_MYSTIC_VIGOUR_UNLOCKED
    };
    private static final String[] PRAYER_RAW = {"rigour", "augury", "preserve", "deadeye", "mystic_vigour"};
    private static final String[] WATSON = {"easy", "medium", "hard", "elite"}; // TRAIL_WATSON_* 5186..5189
    /** CA_TASK_COMPLETED_0..20. Task id = 32 * word + bit (cs2 proc script4834, pinned exporter sources). */
    static final int[] CA_TASK_VARPS = {3116, 3117, 3118, 3119, 3120, 3121, 3122, 3123, 3124, 3125, 3126, 3127, 3128,
        3387, 3718, 3773, 3774, 4204, 4496, 4721, 5673};
    static final List<String> CA_TIERS = Collections.unmodifiableList(Arrays.asList(
        "easy", "medium", "hard", "elite", "master", "grandmaster"));

    private AccountReadiness()
    {
    }

    /** Derives readiness from a raw account_progress map, or returns null when there is no raw block. */
    static Map<String, Object> derive(Map<?, ?> raw)
    {
        if (raw == null)
        {
            return null;
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("schema", SCHEMA);
        out.put("derived_from", "account_progress");
        Map<String, Object> unlocks = new TreeMap<>();
        Map<?, ?> prayers = map(raw.get("prayer_unlocks"));
        for (int i = 0; i < PRAYERS.length; i++)
        {
            Object value = prayers == null ? null : prayers.get(PRAYER_RAW[i]);
            String state = Boolean.TRUE.equals(value) ? "unlocked" : Boolean.FALSE.equals(value) ? "locked" : "unknown";
            unlocks.put(PRAYERS[i][0], entry(state, PRAYERS[i][1], value == null ? "var_unavailable" : "observed_var"));
        }
        // Knight Waves state 8 is widely used as "finished", but no runtime check proves the exact
        // threshold here. Keep chivalry/piety unknown with the raw value rather than guess either way.
        Object waves = prayers == null ? null : prayers.get("knight_waves_state");
        for (String name : new String[]{"prayer.chivalry", "prayer.piety"})
        {
            Map<String, Object> e = entry("unknown", "varbit:3909", "threshold_unverified");
            e.put("raw", waves instanceof Number ? waves : null);
            unlocks.put(name, e);
        }
        out.put("unlocks", unlocks);

        Map<String, Object> tasks = new TreeMap<>();
        Map<?, ?> watson = map(raw.get("watson_clues"));
        for (int i = 0; i < WATSON.length; i++)
        {
            Object value = watson == null ? null : watson.get(WATSON[i]);
            String state = Boolean.TRUE.equals(value) ? "done" : Boolean.FALSE.equals(value) ? "not_done" : "unknown";
            // The game clears these after the master clue is handed out, so not_done is current state, not history.
            tasks.put("clue.watson_" + WATSON[i] + "_handed_in", entry(state, "varbit:" + (5186 + i),
                value == null ? "var_unavailable" : "observed_var_current"));
        }
        out.put("tasks", tasks);
        out.put("slayer_task", slayer(map(raw.get("slayer"))));
        out.put("combat_achievements", combatAchievements(raw));

        // Inventory Setups stores setups in GLOBAL RuneLite config (getConfiguration, not the RS profile).
        // Nothing binds a saved setup to this account, so it is never offered as owned or account gear.
        Map<String, Object> setups = new LinkedHashMap<>();
        setups.put("state", "unsupported_ownership");
        setups.put("reason", "inventory_setups_global_config_no_account_binding");
        out.put("saved_setups", setups);
        return out;
    }

    /**
     * Read-model helper for advice/calculators: are the named unlocks all unlocked? "unknown" when any required
     * unlock is unknown and none is locked. A locked requirement wins, because it is observed.
     */
    static Map<String, Object> requirement(Map<?, ?> readiness, String goal, List<String> required)
    {
        Map<?, ?> unlocks = readiness == null ? null : map(readiness.get("unlocks"));
        List<String> missing = new ArrayList<>(), unknown = new ArrayList<>();
        for (String name : required)
        {
            Map<?, ?> e = unlocks == null ? null : map(unlocks.get(name));
            Object state = e == null ? null : e.get("state");
            if ("locked".equals(state)) missing.add(name);
            else if (!"unlocked".equals(state)) unknown.add(name);
        }
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("goal", goal);
        out.put("state", !missing.isEmpty() ? "not_ready" : !unknown.isEmpty() ? "unknown" : "ready");
        out.put("missing", missing);
        out.put("unknown", unknown);
        out.put("schema", readiness == null ? null : readiness.get("schema"));
        return out;
    }

    private static Map<String, Object> slayer(Map<?, ?> s)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        Integer remaining = s == null ? null : wholeInt(s.get("task_remaining"));
        String state = remaining == null ? "unknown" : remaining > 0 ? "active" : "none";
        out.put("state", state);
        out.put("source", "varp:394,395");
        boolean active = "active".equals(state);
        out.put("target_id", active ? s.get("task_target_id") : null); // raw game id; no name decode in v1
        out.put("remaining", active ? remaining : null);
        out.put("original", active ? s.get("task_original") : null);
        out.put("boss_id", active ? s.get("boss_id") : null);
        out.put("area_id", active ? s.get("area_id") : null);
        return out;
    }

    /**
     * Individual tasks come from the completion bitfield, never from tier totals or chat words. A tier label
     * is attached only from the game's own task catalogue (enums 3981..3986, struct param 1306 = task id).
     */
    static Map<String, Object> combatAchievements(Map<?, ?> raw)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        Object points = raw.get("combat_achievement_points");
        out.put("points", points instanceof Number ? points : null);
        out.put("points_source", "varbit:14815");
        out.put("task_source", "varp CA_TASK_COMPLETED_0..20, task_id = 32*word + bit");
        Map<?, ?> ca = map(raw.get("combat_achievement_tasks"));
        List<?> words = ca == null || !(ca.get("words") instanceof List) ? null : (List<?>) ca.get("words");
        if (words == null || words.size() != CA_TASK_VARPS.length || !words.stream().allMatch(w -> wholeInt(w) != null))
        {
            // Unknown words make every task unknown, including "not completed".
            out.put("state", "unknown");
            out.put("completed_task_ids", null);
            out.put("catalog", "unavailable");
            out.put("completed_by_tier", null);
            return out;
        }
        List<Integer> completed = new ArrayList<>();
        for (int w = 0; w < words.size(); w++)
        {
            int value = wholeInt(words.get(w));
            for (int b = 0; b < 32; b++)
            {
                if ((value & (1 << b)) != 0) completed.add(32 * w + b);
            }
        }
        out.put("state", "observed");
        out.put("completed_task_ids", completed);
        Map<?, ?> tiers = map(ca.get("completed_by_tier"));
        if (tiers == null || !"loaded".equals(ca.get("catalog_status")))
        {
            out.put("catalog", "unavailable");
            out.put("completed_by_tier", null);
            return out;
        }
        Map<String, Object> byTier = new LinkedHashMap<>();
        java.util.Set<Integer> catalogued = new java.util.HashSet<>();
        for (String tier : CA_TIERS)
        {
            List<Integer> ids = new ArrayList<>();
            Object listed = tiers.get(tier);
            if (listed instanceof List)
            {
                for (Object id : (List<?>) listed)
                {
                    // Only a completed bit can carry a tier: a catalogue id without its bit is not a completion.
                    Integer task = wholeInt(id);
                    if (task != null && completed.contains(task) && catalogued.add(task)) ids.add(task);
                }
            }
            byTier.put(tier, ids);
        }
        List<Integer> uncatalogued = new ArrayList<>();
        for (Integer id : completed) if (!catalogued.contains(id)) uncatalogued.add(id); // reported, never guessed
        byTier.put("uncatalogued", uncatalogued);
        Map<String, Object> totals = new LinkedHashMap<>();
        Map<?, ?> rawTotals = map(ca.get("catalog_task_totals"));
        for (String tier : CA_TIERS)
        {
            Object n = rawTotals == null ? null : rawTotals.get(tier);
            totals.put(tier, wholeInt(n));
        }
        out.put("catalog", "game_cache_enums_3981_3986");
        out.put("catalog_sha256", ca.get("catalog_sha256"));
        out.put("completed_by_tier", byTier);
        out.put("catalog_task_totals", totals);
        return out;
    }

    /**
     * A JSON number is an int only when finite, whole and inside the int range. Lenient JSON parsing accepts NaN
     * and huge values; they must stay unknown instead of becoming 0 or Integer.MAX_VALUE.
     */
    static Integer wholeInt(Object o)
    {
        if (!(o instanceof Number)) return null;
        double d = ((Number) o).doubleValue();
        if (Double.isNaN(d) || d != Math.rint(d) || d < Integer.MIN_VALUE || d > Integer.MAX_VALUE) return null;
        return (int) d;
    }

    private static Map<String, Object> entry(String state, String source, String basis)
    {
        Map<String, Object> e = new LinkedHashMap<>();
        e.put("state", state);
        e.put("source", source);
        e.put("basis", basis);
        return e;
    }

    private static Map<?, ?> map(Object o)
    {
        return o instanceof Map ? (Map<?, ?>) o : null;
    }
}

package com.osrsbestinslot.export;

import java.util.*;

/**
 * Classifies one already-projected event into own item flows (contract c3-activity-flows-v1).
 * Only a classified flow is a cost or a result. An inventory decrease alone is never consumption:
 * bank, trade, drop and pickup are transfers, and a death without a trusted diff is an unknown loss.
 */
final class ActivityFlows
{
    private ActivityFlows() {}
    static final String VERSION = "c3-activity-flows-v1";
    static final List<String> CLASSES = List.of("consumed_observed", "consumed_inferred", "transformed",
        "output_reward", "transferred", "lost_death", "unknown");

    /** Event time in ms: own gameplay projections carry observed_at_ms, the public emitter carries ts. */
    static Long at(Map<String,Object> event)
    {
        Object x = event.get("observed_at_ms") != null ? event.get("observed_at_ms") : event.get("ts");
        return x instanceof Number && ((Number)x).longValue() > 0 ? ((Number)x).longValue() : null;
    }

    static List<Map<String,Object>> classify(Map<String,Object> event)
    {
        List<Map<String,Object>> out = new ArrayList<>();
        String type = String.valueOf(event.get("type")), id = String.valueOf(event.get("event_id"));
        Long at = at(event);
        switch (type)
        {
            case "own_signal":
            {
                Map<?,?> v = event.get("signal_value") instanceof Map ? (Map<?,?>)event.get("signal_value") : Map.of();
                String kind = String.valueOf(event.get("signal_kind"));
                if (kind.equals("effects.consumption"))
                {
                    int before = num(v.get("item_id_before")), after = num(v.get("item_id_after"));
                    long qb = lnum(v.get("quantity_before")), qa = lnum(v.get("quantity_after"));
                    if (before <= 0 || qb <= 0) break;
                    if (after == before) out.add(flow(id, 0, at, before, qa - qb, "consumed_inferred", "inferred", "own_click_slot_change", null));
                    else if (after <= 0) out.add(flow(id, 0, at, before, -qb, "consumed_inferred", "inferred", "own_click_slot_change", null));
                    else
                    {
                        // A dose step or a food stage: the input becomes a cheaper product in the same slot.
                        out.add(flow(id, 0, at, before, -qb, "transformed", "inferred", "own_click_slot_change", id));
                        out.add(flow(id, 1, at, after, qa, "transformed", "inferred", "own_click_slot_change", id));
                    }
                }
                else if (kind.equals("skills.item_transformation"))
                {
                    int in = num(v.get("input_item_id")), product = num(v.get("output_item_id"));
                    long q = lnum(v.get("matched_quantity"));
                    if (in <= 0 || product <= 0 || q <= 0) break;
                    out.add(flow(id, 0, at, in, -q, "transformed", "inferred", "inventory_xp_coincidence", id));
                    out.add(flow(id, 1, at, product, q, "transformed", "inferred", "inventory_xp_coincidence", id));
                }
                break;
            }
            case "loot":
                items(out, id, at, event.get("items"), 1, "output_reward", "observed", "server_loot_" + event.get("source_type"));
                break;
            case "alch":
            {
                int item = num(event.get("item")); long q = lnum(event.get("qty")), gp = lnum(event.get("gp"));
                if (item <= 0 || q <= 0 || gp <= 0) break;
                // Runes spent on the cast are not observed here; the record lists them as an unobserved cost.
                out.add(flow(id, 0, at, item, -q, "transformed", "observed", "alch_coin_gain", id));
                out.add(flow(id, 1, at, ActivityPrices.COINS, gp, "transformed", "observed", "alch_coin_gain", id));
                break;
            }
            case "drop":
                single(out, id, at, event, -1, "own_drop_spawn_confirmed");
                break;
            case "pickup":
                single(out, id, at, event, 1, "own_pickup");
                break;
            case "bank_session":
            {
                int n = items(out, id, at, event.get("deposited"), -1, "transferred", "observed", "bank_deposit");
                items(out, id, at, event.get("withdrawn"), 1, "transferred", "observed", "bank_withdraw", n);
                break;
            }
            case "trade":
            {
                int n = items(out, id, at, event.get("given"), -1, "transferred", "observed", "trade_given");
                items(out, id, at, event.get("received"), 1, "transferred", "observed", "trade_received", n);
                break;
            }
            case "death":
                if (event.get("items_lost") instanceof List)
                    items(out, id, at, event.get("items_lost"), -1, "lost_death", "observed", "death_settled_diff");
                else out.add(flow(id, 0, at, null, null, "lost_death", "unknown", "death_without_trusted_diff", null));
                break;
            default:
                break;
        }
        return out;
    }

    private static void single(List<Map<String,Object>> out, String id, Long at, Map<String,Object> e, int sign, String origin)
    {
        int item = num(e.get("item")); long q = lnum(e.get("qty"));
        if (item > 0 && q > 0) out.add(flow(id, 0, at, item, sign * q, "transferred", "observed", origin, null));
    }

    private static int items(List<Map<String,Object>> out, String id, Long at, Object list, int sign, String cls, String prov, String origin)
    {
        return items(out, id, at, list, sign, cls, prov, origin, 0);
    }

    private static int items(List<Map<String,Object>> out, String id, Long at, Object list, int sign, String cls, String prov, String origin, int first)
    {
        int index = first;
        if (!(list instanceof List)) return index;
        for (Object x : (List<?>)list)
        {
            if (!(x instanceof Map)) continue;
            int item = num(((Map<?,?>)x).get("id")); long q = lnum(((Map<?,?>)x).get("qty"));
            if (item > 0 && q > 0) out.add(flow(id, index++, at, item, sign * q, cls, prov, origin, null));
        }
        return index;
    }

    static Map<String,Object> flow(String eventId, int index, Long at, Integer item, Long delta, String cls, String provenance, String origin, String group)
    {
        Map<String,Object> f = new LinkedHashMap<>();
        f.put("flow_id", eventId + ":" + index); f.put("event_id", eventId);
        f.put("item_id", item); f.put("qty_delta", delta); f.put("observed_at_ms", at);
        f.put("flow_class", cls); f.put("provenance", provenance); f.put("origin", origin);
        f.put("transform_group_id", group);
        return f;
    }

    private static int num(Object x)
    {
        return x instanceof Number && ((Number)x).doubleValue() == ((Number)x).intValue() ? ((Number)x).intValue() : -1;
    }

    private static long lnum(Object x)
    {
        return x instanceof Number && ((Number)x).doubleValue() == ((Number)x).longValue() ? ((Number)x).longValue() : -1;
    }
}

package com.osrsbestinslot.export;

import java.util.*;

/**
 * One dated public price snapshot. A quote is usable only at or after the snapshot was available,
 * and carries its own trade time and age; a missing item or side stays unknown, never zero.
 */
final class ActivityPrices
{
    static final int COINS = 995, PLATINUM = 13204;
    static final long FRESH_SECONDS = 3600, STALE_SECONDS = 86400;
    final String source, sourceSha256;
    final long availableAt; // seconds; when this response was received, not its nominal trade times
    private final Map<Integer,long[]> rows; // high, highTime, low, lowTime; -1 means absent

    ActivityPrices(String source, String sourceSha256, long availableAt, Map<Integer,long[]> rows)
    {
        this.source = source; this.sourceSha256 = sourceSha256; this.availableAt = availableAt;
        this.rows = Collections.unmodifiableMap(new HashMap<>(rows));
    }

    /** prices.runescape.wiki /latest body: {data:{id:{high,highTime,low,lowTime}}}. Malformed rows are absent. */
    static ActivityPrices wikiLatest(Map<?,?> body, String sourceSha256, long availableAt)
    {
        Map<Integer,long[]> rows = new HashMap<>();
        Object data = body == null ? null : body.get("data");
        if (data instanceof Map) for (Map.Entry<?,?> e : ((Map<?,?>)data).entrySet())
        {
            if (!(e.getValue() instanceof Map) || !String.valueOf(e.getKey()).matches("[1-9][0-9]{0,6}")) continue;
            Map<?,?> p = (Map<?,?>)e.getValue();
            rows.put(Integer.parseInt(String.valueOf(e.getKey())), new long[]{
                whole(p.get("high")), whole(p.get("highTime")), whole(p.get("low")), whole(p.get("lowTime"))});
        }
        return new ActivityPrices("prices.runescape.wiki/api/v1/osrs/latest", sourceSha256, availableAt, rows);
    }

    private static long whole(Object x)
    {
        if (!(x instanceof Number)) return -1;
        double d = ((Number)x).doubleValue();
        return Double.isFinite(d) && d > 0 && d == Math.floor(d) && d < 9007199254740991D ? (long)d : -1;
    }

    /** side "instant_buy" (Wiki high) or "instant_sell" (Wiki low), quoted at asOf seconds. */
    Map<String,Object> quote(int item, String side, long asOf)
    {
        Map<String,Object> q = new LinkedHashMap<>();
        q.put("item_id", item); q.put("side", side);
        if (item == COINS || item == PLATINUM)
        {
            q.put("unit_gp", item == COINS ? 1L : 1000L); q.put("observed_trade_at", null); q.put("age_seconds", null);
            q.put("freshness", "fixed_face_value"); return q;
        }
        long[] row = rows.get(item);
        int at = "instant_buy".equals(side) ? 0 : 2;
        long price = row == null ? -1 : row[at], time = row == null ? -1 : row[at+1];
        String freshness;
        if (asOf < availableAt) freshness = "snapshot_not_yet_available";
        else if (price <= 0 || time <= 0) freshness = "missing";
        else if (time > asOf) freshness = "future_trade_time";
        else freshness = asOf - time <= FRESH_SECONDS ? "fresh" : asOf - time <= STALE_SECONDS ? "stale" : "too_old";
        boolean usable = freshness.equals("fresh") || freshness.equals("stale");
        q.put("unit_gp", usable ? price : null);
        q.put("observed_trade_at", usable ? time : null);
        q.put("age_seconds", usable ? asOf - time : null);
        q.put("freshness", freshness);
        return q;
    }

    static boolean usable(Map<String,Object> quote) { return quote.get("unit_gp") != null; }
}

package com.osrsbestinslot.export;

import java.util.*;

/**
 * Deterministic derived activity record (schema osrsbis.activity-record.v1). Pure: the caller supplies
 * the already-projected events, the scope (identity, window, optional C2 encounter) and one dated price
 * snapshot. Raw events are never changed. A rate is published only when every value-bearing flow is
 * priced and no loss is unknown; otherwise it is null with the reasons. Costs this capture cannot see
 * (runes, ammunition, charges) are named, so a published net is an upper bound when that list is not empty.
 */
final class ActivityRecord
{
    private ActivityRecord() {}
    static final String SCHEMA = "osrsbis.activity-record.v1", INTERPRETATION = "c3-activity-v1";
    static final long IDLE_GAP_MS = 60_000;
    static final int MAX_CONTRIBUTING = 512;
    static final Map<String,List<String>> UNOBSERVED_COSTS = Map.of(
        "combat_encounter", List.of("ammunition", "runes", "weapon_charges", "cannonballs", "prayer_points_without_potions"),
        "bolt_enchanting", List.of("runes"),
        "alching", List.of("runes"),
        "generic", List.of("supplies_used_without_eat_drink_chew_click"));
    private static final Set<String> SESSION_BOUNDARIES = Set.of("login", "logout", "world_hop");

    /**
     * scope: activity_type, account_hash, profile_type, start_ms, end_ms (null = open), optional gameplay_session
     * (32 hex, filters own_* events) and optional encounter (C2 record, copied verbatim).
     */
    static Map<String,Object> derive(Map<String,Object> scope, List<Map<String,Object>> events, ActivityPrices prices)
    {
        Object requested = scope.get("activity_type");
        String type = requested instanceof String && UNOBSERVED_COSTS.containsKey(requested) ? (String)requested : "generic";
        Long start = asLong(scope.get("start_ms")), end = asLong(scope.get("end_ms"));
        Map<?,?> encounter = scope.get("encounter") instanceof Map ? (Map<?,?>)scope.get("encounter") : null;
        if (encounter != null)
        {
            start = asLong(encounter.get("start_observed_at_ms")); end = asLong(encounter.get("end_observed_at_ms"));
        }
        Object rawSession = scope.get("gameplay_session");
        String session = rawSession instanceof String && ((String)rawSession).matches("[a-f0-9]{32}") ? (String)rawSession : null;
        List<String> gaps = new ArrayList<>();
        int duplicates = 0, identityMismatch = 0, unbound = 0, outside = 0, adapterBound = 0, ownWithoutSession = 0;
        if (rawSession != null && session == null) gaps.add("gameplay_session_invalid");
        String account = scope.get("account_hash") instanceof String ? (String)scope.get("account_hash") : null;
        String profile = scope.get("profile_type") instanceof String ? (String)scope.get("profile_type") : null;
        if (account == null || account.isEmpty() || profile == null || profile.isEmpty()) gaps.add("scope_identity_missing");

        // One event_id must name one observation. Identical copies are duplicates; different copies are
        // quarantined, because keeping either one would make the result depend on delivery order.
        Map<String,String> firstForm = new HashMap<>();
        Set<String> conflicting = new TreeSet<>();
        for (Map<String,Object> e : events)
            if (e.get("event_id") instanceof String)
            {
                String form = canonical(e), seen = firstForm.putIfAbsent((String)e.get("event_id"), form);
                if (seen != null && !seen.equals(form)) conflicting.add((String)e.get("event_id"));
            }
        int conflictsInWindow = 0;
        Set<String> conflictCounted = new HashSet<>();

        // Queue delivery can duplicate and reorder; dedupe on event_id, then order by observed time.
        Map<String,Map<String,Object>> unique = new LinkedHashMap<>();
        for (Map<String,Object> e : events)
        {
            Object id = e.get("event_id"); Long at = ActivityFlows.at(e);
            if (!(id instanceof String) || at == null) { gaps.add("event_without_id_or_time"); continue; }
            String identity = identity(account, profile, e, session);
            if (identity.equals("unbound")) { unbound++; continue; }
            if (identity.equals("mismatch"))
            {
                identityMismatch++;
                // An own row of the right account dropped only for a missing or wrong session hides real costs.
                if (inWindow(at, start, end) && account != null && account.equals(e.get("account_hash")) && Objects.equals(profile, e.get("profile_type"))) ownWithoutSession++;
                continue;
            }
            if (!inWindow(at, start, end)) { outside++; continue; }
            if (conflicting.contains(id)) { if (conflictCounted.add((String)id)) conflictsInWindow++; continue; }
            if (unique.putIfAbsent((String)id, e) != null) duplicates++;
            else if (identity.equals("adapter_bound")) adapterBound++;
        }
        List<Map<String,Object>> ordered = new ArrayList<>(unique.values());
        ordered.sort(Comparator.comparingLong((Map<String,Object> e) -> ActivityFlows.at(e))
            .thenComparingLong(e -> asLong(e.get("source_sequence")) == null ? 0 : asLong(e.get("source_sequence")))
            .thenComparing(e -> (String)e.get("event_id")));

        List<Map<String,Object>> flows = new ArrayList<>();
        Map<String,Long> xp = new TreeMap<>();
        long transformationXp = 0; boolean xpFromFlush = false, boundary = false;
        List<Long> activityTimes = new ArrayList<>();
        List<String> contributing = new ArrayList<>(); int usedCount = 0;
        for (Map<String,Object> e : ordered)
        {
            String t = String.valueOf(e.get("type")); long at = ActivityFlows.at(e);
            List<Map<String,Object>> f = ActivityFlows.classify(e);
            boolean used = !f.isEmpty();
            flows.addAll(f);
            if (t.equals("xp_gain") && e.get("gains") instanceof List)
            {
                for (Object g : (List<?>)e.get("gains")) if (g instanceof Map)
                {
                    Long amount = asLong(((Map<?,?>)g).get("xp")); Object skill = ((Map<?,?>)g).get("skill");
                    if (amount != null && amount > 0 && skill instanceof String) xp.merge((String)skill, amount, Long::sum);
                }
                xpFromFlush = used = true;
            }
            if (t.equals("own_signal") && "skills.item_transformation".equals(e.get("signal_kind")) && e.get("signal_value") instanceof Map)
            {
                Long m = asLong(((Map<?,?>)e.get("signal_value")).get("magic_xp_change")); if (m != null) transformationXp += m;
            }
            if (SESSION_BOUNDARIES.contains(t)) { boundary = true; used = true; }
            if (t.equals("combat_hit")) used = true;
            if (used && !t.equals("xp_gain") && !SESSION_BOUNDARIES.contains(t)) activityTimes.add(at);
            if (used) { usedCount++; if (contributing.size() < MAX_CONTRIBUTING) contributing.add((String)e.get("event_id")); }
        }
        if (usedCount > MAX_CONTRIBUTING) gaps.add("contributing_ids_truncated");

        // Valuation: inputs at the Wiki instant-buy (replacement) price, outputs at instant-sell, before GE tax.
        long asOf = end == null ? 0 : Math.floorDiv(end, 1000L); // never later than the window end
        long inputs = 0, outputs = 0, transfersOut = 0, transfersIn = 0;
        int unpriced = 0, unpricedTransfers = 0, stale = 0, unknownLoss = 0;
        Map<Integer,Map<String,Object>> quotes = new TreeMap<>();
        for (Map<String,Object> f : flows)
        {
            String cls = (String)f.get("flow_class");
            Integer item = (Integer)f.get("item_id"); Long delta = (Long)f.get("qty_delta");
            if (item == null || delta == null) { unknownLoss++; f.put("unit_gp", null); continue; }
            String side = delta < 0 ? "instant_buy" : "instant_sell";
            Map<String,Object> q = end == null ? null : prices.quote(item, side, asOf);
            Long unit = q == null ? null : (Long)q.get("unit_gp");
            if (q != null) quotes.putIfAbsent(item * 2 + (delta < 0 ? 0 : 1), q);
            f.put("unit_gp", unit); f.put("price_side", side);
            if (cls.equals("transferred"))
            {
                if (unit == null) unpricedTransfers++;
                else if (delta < 0) transfersOut += -delta * unit; else transfersIn += delta * unit;
                continue;
            }
            if (unit == null) { unpriced++; continue; }
            if ("stale".equals(q.get("freshness"))) stale++;
            if (delta < 0) inputs += -delta * unit; else outputs += delta * unit;
        }

        Map<String,Object> r = new LinkedHashMap<>();
        r.put("schema", SCHEMA); r.put("interpretation_version", INTERPRETATION); r.put("flows_version", ActivityFlows.VERSION);
        r.put("activity_type", type);
        r.put("activity_key", session == null || start == null ? null : session + ":" + start + ":" + type);
        r.put("encounter_key", encounter == null ? null : encounter.get("encounter_key"));
        r.put("encounter_outcome", encounter == null ? null : encounter.get("outcome"));
        r.put("join_basis", session == null ? "account_profile_time_window" : "account_profile_time_window+gameplay_session_for_own_events");

        Map<String,Object> time = new LinkedHashMap<>();
        time.put("start_ms", start); time.put("end_ms", end);
        boolean invalidWindow = start != null && end != null && end < start;
        time.put("elapsed_ms", start == null || end == null || invalidWindow ? null : end - start);
        long active = 0; for (int i = 1; i < activityTimes.size(); i++)
        {
            long gap = activityTimes.get(i) - activityTimes.get(i-1); if (gap <= IDLE_GAP_MS) active += gap;
        }
        time.put("active_ms", end == null || activityTimes.size() < 2 ? null : active);
        time.put("active_basis", "sum_of_gaps_le_60s_between_classified_events_not_input_activity");
        time.put("session_boundary_inside", boundary);
        r.put("time", time);

        r.put("flows", flows);
        r.put("inputs", summary(flows, true)); r.put("outputs", summary(flows, false));
        Map<String,Object> xpOut = new LinkedHashMap<>();
        long totalXp = 0; for (long v : xp.values()) totalXp += v;
        xpOut.put("by_skill", xp); xpOut.put("total", xpFromFlush ? totalXp : null);
        xpOut.put("source", xpFromFlush ? "xp_gain_5min_flush" : "not_observed");
        xpOut.put("alignment", xpFromFlush ? "flush_may_include_xp_from_before_window" : null);
        xpOut.put("magic_xp_from_transformations", transformationXp);
        r.put("xp", xpOut);

        Map<String,Object> v = new LinkedHashMap<>();
        v.put("source", prices.source); v.put("source_sha256", prices.sourceSha256);
        v.put("snapshot_available_at", prices.availableAt); v.put("as_of", end == null ? null : asOf);
        v.put("basis", "inputs_instant_buy_outputs_instant_sell_before_ge_tax");
        v.put("quotes", new ArrayList<>(quotes.values()));
        v.put("input_cost_gp", inputs); v.put("output_value_gp", outputs);
        // A missing transfer price leaves the transfer totals unknown; transfers never enter the net.
        v.put("transfers_out_gp", unpricedTransfers > 0 ? null : transfersOut); v.put("transfers_in_gp", unpricedTransfers > 0 ? null : transfersIn);
        v.put("unpriced_transfers", unpricedTransfers);
        v.put("transfers_in_net", false);
        r.put("valuation", v);

        List<String> reasons = new ArrayList<>();
        if (gaps.contains("scope_identity_missing")) reasons.add("scope_identity_missing");
        if (invalidWindow) reasons.add("invalid_window");
        if (ownWithoutSession > 0) reasons.add("own_events_excluded_without_session:" + ownWithoutSession);
        if (conflictsInWindow > 0) reasons.add("conflicting_event_ids:" + conflictsInWindow);
        // C2 sets end_observed_at_ms null for inferred ends (scene_gap, tick_reversal, inactivity): the end time is unknown.
        Object outcome = encounter == null ? null : encounter.get("outcome");
        if (end == null) reasons.add(encounter == null || "open".equals(outcome) ? "window_open" : "encounter_end_time_unobserved:" + outcome);
        if (unpriced > 0 && end != null) reasons.add("unpriced_flows:" + unpriced); // no as_of means nothing was priced
        if (unknownLoss > 0) reasons.add("unknown_loss:" + unknownLoss);
        if (flows.isEmpty()) reasons.add("no_classified_flows");
        Map<String,Object> result = new LinkedHashMap<>();
        boolean ok = reasons.isEmpty();
        Long net = ok ? outputs - inputs : null;
        Long elapsed = (Long)time.get("elapsed_ms"), activeMs = (Long)time.get("active_ms");
        result.put("net_gp", net);
        result.put("net_gp_per_elapsed_hour", ok && elapsed != null && elapsed > 0 ? Math.round(net * 3_600_000D / elapsed) : null);
        result.put("net_gp_per_active_hour", ok && activeMs != null && activeMs > 0 ? Math.round(net * 3_600_000D / activeMs) : null);
        Long gpXpBase = xpFromFlush ? Long.valueOf(totalXp) : transformationXp > 0 ? Long.valueOf(transformationXp) : null;
        result.put("gp_per_xp", ok && gpXpBase != null && gpXpBase > 0 ? Math.round(net * 100D / gpXpBase) / 100D : null);
        result.put("gp_per_xp_basis", gpXpBase == null ? null : xpFromFlush ? "xp_gain_total" : "magic_xp_from_transformations");
        result.put("unobserved_cost_classes", UNOBSERVED_COSTS.get(type));
        result.put("net_bound", !ok ? null : UNOBSERVED_COSTS.get(type).isEmpty() ? "point" : "upper_bound_excludes_unobserved_costs");
        result.put("confidence", !ok ? "unavailable" : stale > 0 || boundary || xpFromFlush || adapterBound > 0 ? "low" : "medium");
        result.put("unavailable_reasons", reasons);
        r.put("result", result);

        Map<String,Object> quality = new LinkedHashMap<>();
        quality.put("events_received", events.size()); quality.put("events_used", usedCount);
        quality.put("duplicates_dropped", duplicates); quality.put("identity_mismatch_excluded", identityMismatch);
        quality.put("identity_unbound_excluded", unbound); quality.put("adapter_bound_events", adapterBound);
        quality.put("conflicting_event_ids", new ArrayList<>(conflicting));
        quality.put("outside_window_excluded", outside); quality.put("stale_prices_used", stale);
        quality.put("gaps", gaps);
        r.put("quality", quality);
        r.put("contributing_event_ids", contributing);
        return r;
    }

    private static Map<String,Object> summary(List<Map<String,Object>> flows, boolean inputs)
    {
        Map<String,Map<Integer,Long>> byClass = new TreeMap<>();
        for (Map<String,Object> f : flows)
        {
            Long d = (Long)f.get("qty_delta"); Integer item = (Integer)f.get("item_id");
            if (d == null || item == null || (inputs ? d >= 0 : d <= 0)) continue;
            byClass.computeIfAbsent((String)f.get("flow_class"), k -> new TreeMap<>()).merge(item, Math.abs(d), Long::sum);
        }
        return new LinkedHashMap<>(byClass);
    }

    /**
     * Every used event must name the scope's account and profile. own_* events must also carry the scope's
     * gameplay_session. A row without account/profile is accepted only when a trusted adapter bound it
     * explicitly (identity_binding=adapter, which the caller sets, never the capture); absence never matches.
     */
    private static boolean inWindow(long at, Long start, Long end)
    {
        return start != null && at >= start && (end == null || at <= end);
    }

    static String identity(String account, String profile, Map<String,Object> e, String session)
    {
        if (account == null || profile == null) return "unbound";
        boolean ownType = String.valueOf(e.get("type")).startsWith("own_"), own = ownType || e.get("gameplay_session") != null;
        if (own && (session == null || !session.equals(e.get("gameplay_session")))) return "mismatch";
        Object a = e.get("account_hash"), p = e.get("profile_type");
        if (a == null && p == null) return ownType && "adapter".equals(e.get("identity_binding")) ? "adapter_bound" : "unbound";
        return account.equals(a) && profile.equals(p) ? "bound" : "mismatch";
    }

    /**
     * Order-independent, unambiguous form: every value is type-tagged and every string, key and container
     * is length-framed, so no string content can imitate structure. JSON replay turns integers into
     * doubles, so whole numbers compare as longs.
     */
    static String canonical(Object x)
    {
        StringBuilder out = new StringBuilder(); canonical(x, out); return out.toString();
    }

    private static void canonical(Object x, StringBuilder out)
    {
        if (x instanceof Map)
        {
            TreeMap<String,Object> sorted = new TreeMap<>();
            for (Map.Entry<?,?> e : ((Map<?,?>)x).entrySet()) sorted.put(String.valueOf(e.getKey()), e.getValue());
            out.append('M').append(sorted.size()).append('{');
            for (Map.Entry<String,Object> e : sorted.entrySet()) { framed(e.getKey(), out); canonical(e.getValue(), out); }
            out.append('}');
        }
        else if (x instanceof List)
        {
            out.append('L').append(((List<?>)x).size()).append('[');
            for (Object v : (List<?>)x) canonical(v, out);
            out.append(']');
        }
        else if (x instanceof Number)
        {
            double d = ((Number)x).doubleValue();
            if (d == Math.rint(d) && Math.abs(d) < 9.007199254740991E15) out.append('n').append((long)d).append(';');
            else out.append('d').append(Double.doubleToLongBits(d)).append(';');
        }
        else if (x == null) out.append('z');
        else if (x instanceof Boolean) out.append((Boolean)x ? 't' : 'f');
        else if (x instanceof String) { out.append('s'); framed((String)x, out); }
        else { out.append('o'); framed(x.getClass().getName() + ":" + x, out); }
    }

    private static void framed(String s, StringBuilder out) { out.append(s.length()).append(':').append(s); }

    private static Long asLong(Object x)
    {
        return x instanceof Number && ((Number)x).doubleValue() == ((Number)x).longValue() ? ((Number)x).longValue() : null;
    }
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Bank-visit evidence (0.7.18, staff only): the canonical item list, its hash, and its chunks.
 *
 * Server ingest contract:
 *   canonical list = drop id &lt;= 0 or qty &lt;= 0, sum by id, sort by id ascending, written as the compact
 *   JSON [[id,qty],...] with no spaces, UTF-8; the hash is its lowercase hex SHA-256. Chunks carry
 *   consecutive slices of that same list, each at most MAX_STACKS stacks AND at most FIELDS_BUDGET chars
 *   of encoded fields, whichever is hit first. The server drops (ACKs "filtered") any event whose fields
 *   are longer than 8192 chars, so the budget keeps 512 chars of headroom, like the surrounding snapshot.
 */
final class BankVisitManifest
{
	static final int MAX_STACKS = 150;
	static final int FIELDS_BUDGET = 7680;

	private BankVisitManifest()
	{
	}

	/** The canonical list: positive ids and quantities only, summed by id, sorted by id. */
	static List<long[]> canonical(Map<Integer, Long> counts)
	{
		TreeMap<Integer, Long> sorted = new TreeMap<>();
		if (counts != null)
		{
			for (Map.Entry<Integer, Long> e : counts.entrySet())
			{
				if (e.getKey() != null && e.getKey() > 0 && e.getValue() != null && e.getValue() > 0)
				{
					sorted.merge(e.getKey(), e.getValue(), Long::sum);
				}
			}
		}
		List<long[]> out = new ArrayList<>(sorted.size());
		for (Map.Entry<Integer, Long> e : sorted.entrySet())
		{
			out.add(new long[]{e.getKey(), e.getValue()});
		}
		return out;
	}

	/** Compact JSON [[id,qty],...]: integers only, no spaces. */
	static String json(List<long[]> list)
	{
		StringBuilder b = new StringBuilder("[");
		for (int i = 0; i < list.size(); i++)
		{
			if (i > 0)
			{
				b.append(',');
			}
			b.append('[').append(list.get(i)[0]).append(',').append(list.get(i)[1]).append(']');
		}
		return b.append(']').toString();
	}

	static String sha256(List<long[]> list)
	{
		return EventSpool.sha256Hex(json(list));
	}

	/** Encoded length of one stack inside the list, without its separating comma. */
	static int stackLength(long[] s)
	{
		return 3 + Long.toString(s[0]).length() + Long.toString(s[1]).length();
	}

	/**
	 * Split the list into consecutive chunks. {@code emptyChunkLength} is the encoded length of a chunk's
	 * fields with an EMPTY items list (event_id and the largest chunk numbers included), so every chunk's
	 * real length is that plus the items it holds. An empty list gives no chunks.
	 */
	static List<List<long[]>> chunk(List<long[]> list, int emptyChunkLength)
	{
		List<List<long[]>> out = new ArrayList<>();
		List<long[]> cur = new ArrayList<>();
		int len = emptyChunkLength;
		for (long[] s : list)
		{
			int add = stackLength(s) + (cur.isEmpty() ? 0 : 1);
			if (!cur.isEmpty() && (cur.size() >= MAX_STACKS || len + add > FIELDS_BUDGET))
			{
				out.add(cur);
				cur = new ArrayList<>();
				len = emptyChunkLength;
				add = stackLength(s);
			}
			cur.add(s);
			len += add;
		}
		if (!cur.isEmpty())
		{
			out.add(cur);
		}
		return out;
	}
}

/*
 * Buffers the last N rendered frames for the store delivery-proof burst (frames uploaded raw; the server stitches — no encoder in the plugin).
 *
 * A bounded ring buffer of ALREADY-ENCODED JPEG frames. The recorder pushes the last few
 * seconds of frames in; when the shop closes, the buffer is snapshotted and uploaded off the
 * client thread. Oldest frames are evicted once the capacity is reached, so memory stays
 * bounded regardless of how long a shop stays open.
 *
 * ⚠ The ring holds byte[], NOT BufferedImage, and that is load-bearing (fixed 2026-09-02).
 * It used to hold raw BufferedImages, which at 30fps x 12s x 704px is ~1.1MB per frame and
 * ~400MB retained for the length of a shop visit — past RuneLite's 512MB default max heap, so
 * the client froze in continuous GC and the burst never uploaded. Encoded, the same 360 frames
 * are ~30KB each, about 11MB. Never store decoded images here.
 *
 * Standalone + unit-testable: it depends only on the JDK (no RuneLite, no AWT), so the
 * frame -> buffer path can be driven with synthetic byte arrays under test.
 */
package com.osrsbestinslot.export;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/** Fixed-capacity FIFO of the most recent ENCODED frames. Thread-safe (encode thread adds, upload thread snapshots). */
public class ClipRingBuffer
{
	private final int capacity;
	private final Deque<byte[]> frames;

	/**
	 * @param capacity max frames retained (= fps * seconds). Must be &gt;= 1.
	 */
	public ClipRingBuffer(int capacity)
	{
		if (capacity < 1)
		{
			throw new IllegalArgumentException("capacity must be >= 1");
		}
		this.capacity = capacity;
		this.frames = new ArrayDeque<>(capacity);
	}

	/** Append an encoded frame, evicting the oldest if at capacity. Null / empty frames are ignored. */
	public synchronized void add(byte[] frame)
	{
		if (frame == null || frame.length == 0)
		{
			return;
		}
		if (frames.size() >= capacity)
		{
			frames.pollFirst();
		}
		frames.addLast(frame);
	}

	/** Ordered copy (oldest -&gt; newest) for the uploader. */
	public synchronized List<byte[]> snapshot()
	{
		return new ArrayList<>(frames);
	}

	/** Total retained bytes — the number this class exists to bound. */
	public synchronized long byteSize()
	{
		long total = 0;
		for (byte[] f : frames)
		{
			total += f.length;
		}
		return total;
	}

	public synchronized int size()
	{
		return frames.size();
	}

	public int capacity()
	{
		return capacity;
	}

	public synchronized void clear()
	{
		frames.clear();
	}
}

package com.osrsbestinslot.export;

import java.util.*;

/**
 * Derived own-combat encounter summaries from the raw own-gameplay rows of ONE gameplay session.
 * Pure and replayable: the same ordered rows give the same result. Raw rows stay unchanged.
 * An encounter is one observed NPC target. Its start is the first OBSERVED own hit, not the true
 * start. NPC death is not kill credit, despawn is not death and received damage is not a mistake.
 * Only the local player's hits are visible, so party damage and own damage share stay unknown.
 */
final class CombatEncounterTracker
{
    static final String MODEL = "combat-encounter-v1";
    // 100 ticks (60 s) without an own hit closes the target as an unobserved end. Inferred, not observed.
    static final int INACTIVE_TICKS = 100;
    // ServerNpcLoot follows the death animation. Loot later than this is never linked.
    static final int LOOT_WINDOW_TICKS = 16;
    static final int MAX_OPEN = 16, MAX_CLOSED = 32, MAX_PHASES = 8, MAX_REVISIONS = 8, MAX_LOOT = 8, MAX_SEQUENCES = 256;
    // RuneLite HitsplatID: own attack splats versus own damage over time.
    private static final Set<Integer> ATTACK = new HashSet<>(Arrays.asList(12, 16, 18, 20, 22, 24, 43, 44, 45, 46, 47, 53, 55));
    private static final Set<Integer> OVER_TIME = new HashSet<>(Arrays.asList(5, 65, 67, 74));

    private final String session;
    private final Map<String,Encounter> open = new LinkedHashMap<>();
    private final Deque<Encounter> closed = new ArrayDeque<>();
    private final List<Map<String,Object>> unlinkedLoot = new ArrayList<>();
    private Map<String,Object> worn; // latest observed worn revision in this session, or null = unknown
    private long receivedNoOpenHits, receivedNoOpenDamage, receivedOverlapHits, receivedOverlapDamage, droppedClosed, droppedLoot;
    private int lastTick = -1;
    // Deaths of targets with no open encounter, kept for their tick: a first own splat can arrive after ActorDeath.
    private final Map<String,long[]> pendingDeaths = new LinkedHashMap<>();
    private int pendingDeathTick = -1;

    CombatEncounterTracker(String gameplaySession) { session = gameplaySession == null ? null : gameplaySession.replace("-", ""); }
    String session() { return session; }

    private final class Encounter
    {
        final String key, targetKey;
        final int startTick; final long startAt;
        int lastHitTick, endTick = -1; long lastHitAt, endAt; String outcome, endSource;
        long attackSplats, landed, zero, attackDamage, overTimeSplats, overTimeDamage, otherSplats, otherDamage, maxHit;
        long receivedHits, receivedDamage;
        final List<Map<String,Object>> phases = new ArrayList<>();
        final List<Map<String,Object>> revisions = new ArrayList<>();
        final List<Map<String,Object>> loot = new ArrayList<>();
        final Set<String> gaps = new LinkedHashSet<>();
        final List<Long> sequences = new ArrayList<>(); boolean sequencesTruncated;
        final Map<String,Object> wornAtStart;

        Encounter(String target, int tick, long at)
        {
            targetKey = target; key = session + ":" + target + ":" + tick; startTick = lastHitTick = tick; startAt = lastHitAt = at;
            wornAtStart = worn;
        }
        void contributes(long sequence)
        {
            if (sequence < 0) return; // local input, no shared source sequence
            if (sequences.size() < MAX_SEQUENCES) sequences.add(sequence); else sequencesTruncated = true;
        }
        void phase(int npcId, int tick)
        {
            Map<String,Object> last = phases.isEmpty() ? null : phases.get(phases.size() - 1);
            if (last != null && Objects.equals(last.get("npc_id"), npcId)) { last.put("last_hit_tick", tick); return; }
            if (phases.size() >= MAX_PHASES) { gaps.add("phase_capacity"); return; }
            Map<String,Object> p = new LinkedHashMap<>();
            p.put("npc_id", npcId); p.put("first_hit_tick", tick); p.put("last_hit_tick", tick);
            phases.add(p);
        }
        boolean hasNpc(int npcId)
        {
            for (Map<String,Object> p : phases) if (Objects.equals(p.get("npc_id"), npcId)) return true;
            return false;
        }
    }

    /** Feed one raw own-gameplay row in sequence order. Unknown kinds are ignored. */
    void accept(Map<String,Object> row)
    {
        if (row == null || !(row.get("value") instanceof Map) || !(row.get("tick") instanceof Number)
            || !(row.get("observed_at_ms") instanceof Number)) return;
        // Shared rows carry source sequence. Local encounter inputs carry local_input_id instead.
        if (!(row.get("sequence") instanceof Number) && !(row.get("local_input_id") instanceof String)) return;
        String kind = String.valueOf(row.get("kind"));
        Map<?,?> v = (Map<?,?>) row.get("value");
        int tick = ((Number) row.get("tick")).intValue();
        long at = ((Number) row.get("observed_at_ms")).longValue();
        long seq = row.get("sequence") instanceof Number ? ((Number) row.get("sequence")).longValue() : -1;
        if (lastTick >= 0 && tick < lastTick) { interrupt("tick_reversal", lastTick); lastTick = -1; }
        expire(tick);
        lastTick = Math.max(lastTick, tick);
        switch (kind)
        {
            case "combat.worn_revision": worn(v, tick, seq); break;
            case "combat.worn_unknown":
                worn = null; // later encounters start with unknown gear
                for (Encounter e : open.values()) e.gaps.add("equipment_unreadable");
                break;
            case "combat.own_hits": hit(v, tick, at, seq); break;
            case "combat.npc_lifecycle": npcEnd(v, tick, at, seq); break;
            case "combat.own_death":
                for (Encounter e : new ArrayList<>(open.values())) { e.contributes(seq); close(e, "own_death", "ActorDeath:self", tick, at); }
                break;
            case "combat.loot_observed": loot(v, tick, at, "loot_input_id", String.valueOf(row.get("local_input_id")), false); break;
            default: break;
        }
    }

    private void worn(Map<?,?> v, int tick, long seq)
    {
        if (!(v.get("slots") instanceof Map) || !(v.get("content_id") instanceof String)) return;
        Map<String,Object> r = new LinkedHashMap<>();
        r.put("content_id", v.get("content_id")); r.put("slots", new LinkedHashMap<>((Map<?,?>) v.get("slots")));
        r.put("observed_tick", tick); r.put("provenance", "worn_container_at_own_hit");
        worn = r;
        for (Encounter e : open.values())
        {
            if (e.revisions.size() < MAX_REVISIONS) e.revisions.add(r); else e.gaps.add("revision_capacity");
            e.contributes(seq);
        }
    }

    private void hit(Map<?,?> v, int tick, long at, long seq)
    {
        if (!(v.get("amount") instanceof Number) || !(v.get("hitsplat_type") instanceof Number)) return;
        long amount = ((Number) v.get("amount")).longValue(); int type = ((Number) v.get("hitsplat_type")).intValue();
        if ("received".equals(v.get("direction")))
        {
            // Without a visible attacker, received damage belongs to an encounter only when exactly one is open.
            if (open.size() == 1)
            {
                Encounter e = open.values().iterator().next();
                e.receivedHits++; e.receivedDamage += amount; e.contributes(seq);
            }
            else if (open.isEmpty()) { receivedNoOpenHits++; receivedNoOpenDamage += amount; }
            else { receivedOverlapHits++; receivedOverlapDamage += amount; }
            return;
        }
        if (!"dealt_to_npc".equals(v.get("direction")) || !(v.get("target_observation_id") instanceof String)
            || !(v.get("npc_id") instanceof Number)) return;
        String target = ((String) v.get("target_observation_id")).replace("-", "");
        Encounter e = open.get(target);
        if (e == null)
        {
            // A killing splat that the client delivers after ActorDeath in the same tick belongs to that death.
            Encounter dead = null;
            for (Encounter c : closed)
                if (c.targetKey.equals(target) && "observed_death".equals(c.outcome) && c.endTick == tick) dead = c;
            if (dead != null)
            {
                // The worn read for this splat came after the death closed the encounter. Keep it when it is new.
                if (worn != null && Integer.valueOf(tick).equals(worn.get("observed_tick")) && !dead.revisions.contains(worn))
                {
                    if (dead.revisions.size() < MAX_REVISIONS) dead.revisions.add(worn); else dead.gaps.add("revision_capacity");
                }
                count(dead, v, tick, at, seq); return;
            }
        }
        if (e == null)
        {
            if (open.size() >= MAX_OPEN)
            {
                Encounter oldest = open.values().iterator().next();
                oldest.gaps.add("open_capacity"); close(oldest, "unknown", "tracker_capacity", tick, at);
            }
            e = new Encounter(target, tick, at); open.put(target, e);
            if (open.size() > 1) for (Encounter o : open.values()) o.gaps.add("overlapping_targets");
            if (e.wornAtStart != null) e.revisions.add(e.wornAtStart);
        }
        count(e, v, tick, at, seq);
        long[] death = tick == pendingDeathTick ? pendingDeaths.remove(target) : null;
        if (death != null) { e.contributes(death[1]); close(e, "observed_death", "ActorDeath", tick, death[0]); }
    }

    private void count(Encounter e, Map<?,?> v, int tick, long at, long seq)
    {
        long amount = ((Number) v.get("amount")).longValue(); int type = ((Number) v.get("hitsplat_type")).intValue();
        e.lastHitTick = tick; e.lastHitAt = at; e.contributes(seq); e.phase(((Number) v.get("npc_id")).intValue(), tick);
        if (ATTACK.contains(type))
        {
            e.attackSplats++; e.attackDamage += amount; e.maxHit = Math.max(e.maxHit, amount);
            if (amount > 0) e.landed++; else e.zero++;
        }
        else if (OVER_TIME.contains(type)) { e.overTimeSplats++; e.overTimeDamage += amount; }
        else { e.otherSplats++; e.otherDamage += amount; }
    }

    private void npcEnd(Map<?,?> v, int tick, long at, long seq)
    {
        if (!(v.get("target_observation_id") instanceof String)) return;
        Encounter e = open.get(((String) v.get("target_observation_id")).replace("-", ""));
        String end = String.valueOf(v.get("end"));
        if (e == null)
        {
            // Not open in this tracker (for example closed by inactivity). A same-tick own splat may still follow.
            if ("observed_death".equals(end))
            {
                if (tick != pendingDeathTick) { pendingDeaths.clear(); pendingDeathTick = tick; }
                if (pendingDeaths.size() < MAX_OPEN)
                    pendingDeaths.put(((String) v.get("target_observation_id")).replace("-", ""), new long[] {at, seq});
            }
            return;
        }
        e.contributes(seq);
        close(e, "observed_death".equals(end) ? "observed_death" : "despawn_not_death",
            "observed_death".equals(end) ? "ActorDeath" : "NpcDespawned", tick, at);
    }

    private void loot(Map<?,?> v, int tick, long at, String idField, String id, boolean wallClock)
    {
        Integer npcId = v.get("npc_id") instanceof Number && ((Number) v.get("npc_id")).intValue() >= 0
            ? ((Number) v.get("npc_id")).intValue() : null;
        List<Encounter> candidates = new ArrayList<>();
        for (Encounter e : closed)
            // One ServerNpcLoot per death: an encounter that already holds loot is not a candidate again.
            if ("observed_death".equals(e.outcome) && e.loot.isEmpty() && (npcId == null || e.hasNpc(npcId))
                && (wallClock ? e.endAt >= 0 && at >= e.endAt && at - e.endAt <= LOOT_WINDOW_TICKS * 600L
                    : tick >= e.endTick && tick - e.endTick <= LOOT_WINDOW_TICKS)) candidates.add(e);
        Map<String,Object> link = new LinkedHashMap<>();
        // Client side: local input ID only, the uploaded event_id is generated later by the shared emitter.
        // Event replay: the existing loot event's own event_id.
        link.put(idField, id); link.put("observed_tick", wallClock ? null : tick);
        link.put("observed_at_ms", at); link.put("npc_id", npcId); link.put("items", v.get("items"));
        link.put("link_basis", (npcId == null ? "time_window_only" : "npc_id_and_time_window") + (wallClock ? ";wall_clock_ms" : ";game_ticks"));
        if (candidates.size() == 1)
        {
            Encounter e = candidates.get(0);
            link.put("encounter_key", e.key); link.put("link_provenance", "matched");
            if (e.loot.size() < MAX_LOOT) e.loot.add(link); else e.gaps.add("loot_capacity");
            return;
        }
        link.put("encounter_key", null);
        link.put("link_provenance", candidates.isEmpty() ? "unlinked" : "ambiguous");
        if (!candidates.isEmpty())
        {
            List<String> keys = new ArrayList<>(); for (Encounter e : candidates) keys.add(e.key);
            link.put("candidate_encounter_keys", keys);
        }
        if (unlinkedLoot.size() < MAX_LOOT) unlinkedLoot.add(link); else droppedLoot++;
    }

    private void expire(int tick)
    {
        for (Encounter e : new ArrayList<>(open.values()))
            if (tick - e.lastHitTick > INACTIVE_TICKS) close(e, "unobserved_end_inactivity", "inferred_inactivity", e.lastHitTick, -1);
    }

    private void close(Encounter e, String outcome, String source, int tick, long at)
    {
        open.remove(e.targetKey);
        e.outcome = outcome; e.endSource = source; e.endTick = tick; e.endAt = at;
        closed.addLast(e);
        while (closed.size() > MAX_CLOSED) { closed.removeFirst(); droppedClosed++; }
    }

    /** Scene reload, tick reversal or session end: open targets cannot be followed further. */
    void interrupt(String reason, int tick)
    {
        worn = null; // gear across a gap is not known until it is read again
        pendingDeaths.clear();
        // The caller's tick can be older than the last hit (poll tick, or -1 after a gap). Never end before it.
        for (Encounter e : new ArrayList<>(open.values())) { e.gaps.add(reason); close(e, reason, reason, Math.max(tick, e.lastHitTick), -1); }
    }

    /** Read-only: the same accepted rows give the same result however often this is called. */
    Map<String,Object> summary(int asOfTick)
    {
        Map<String,Object> out = new LinkedHashMap<>();
        out.put("model", MODEL); out.put("gameplay_session", session); out.put("as_of_tick", asOfTick < 0 ? null : asOfTick);
        out.put("derived", true); out.put("complete", false);
        out.put("scope", "own_hits_on_npcs_only;party_damage_not_observed;kill_credit_unknown");
        List<Map<String,Object>> list = new ArrayList<>();
        for (Encounter e : closed) list.add(describe(e, e.outcome, e.endSource, e.endTick, e.endAt));
        for (Encounter e : open.values())
        {
            // As-of view only. The tracker itself expires targets when a later row is accepted.
            boolean inactive = asOfTick >= 0 && asOfTick - e.lastHitTick > INACTIVE_TICKS;
            list.add(inactive ? describe(e, "unobserved_end_inactivity", "inferred_inactivity", e.lastHitTick, -1) : describe(e, null, null, -1, -1));
        }
        out.put("encounters", list); out.put("closed_dropped", droppedClosed);
        Map<String,Object> received = new LinkedHashMap<>();
        received.put("no_open_encounter_hits", receivedNoOpenHits); received.put("no_open_encounter_damage", receivedNoOpenDamage);
        received.put("overlapping_encounters_hits", receivedOverlapHits); received.put("overlapping_encounters_damage", receivedOverlapDamage);
        out.put("received_unattributed", received);
        out.put("loot_not_matched", new ArrayList<>(unlinkedLoot)); out.put("loot_not_matched_dropped", droppedLoot);
        return out;
    }

    private Map<String,Object> describe(Encounter e, String outcome, String endSource, int endTick, long endAt)
    {
        Map<String,Object> m = new LinkedHashMap<>();
        m.put("encounter_key", e.key); m.put("target_key", e.targetKey);
        m.put("status", outcome == null ? "open" : "closed");
        m.put("start_tick", e.startTick); m.put("start_observed_at_ms", e.startAt);
        m.put("start_provenance", "first_observed_own_hit"); m.put("true_start", "unknown");
        m.put("last_own_hit_tick", e.lastHitTick); m.put("last_own_hit_observed_at_ms", e.lastHitAt);
        m.put("end_tick", outcome == null ? null : endTick);
        m.put("end_observed_at_ms", outcome == null || endAt < 0 ? null : endAt);
        m.put("outcome", outcome == null ? "open" : outcome); m.put("end_source", endSource);
        m.put("kill_credit", "unknown");
        Integer elapsed = outcome == null ? null : endTick - e.startTick;
        m.put("elapsed_ticks", elapsed);
        m.put("elapsed_seconds_game", elapsed == null ? null : elapsed * 0.6);
        m.put("elapsed_basis", "first_observed_own_hit_to_end_tick");
        m.put("phases", new ArrayList<>(e.phases));
        Map<String,Object> own = new LinkedHashMap<>();
        own.put("attack_splats", e.attackSplats); own.put("landed_splats", e.landed); own.put("zero_splats", e.zero);
        own.put("attack_damage", e.attackDamage); own.put("max_attack_splat", e.attackSplats == 0 ? null : e.maxHit);
        own.put("over_time_splats", e.overTimeSplats); own.put("over_time_damage", e.overTimeDamage);
        own.put("other_type_splats", e.otherSplats); own.put("other_type_damage", e.otherDamage);
        long total = e.attackDamage + e.overTimeDamage + e.otherDamage;
        own.put("total_own_damage", total);
        own.put("damage_per_tick", elapsed == null || elapsed <= 0 ? null : Math.round(total * 1000.0 / elapsed) / 1000.0);
        own.put("party_damage", "not_observed");
        m.put("own_attacks", own);
        Map<String,Object> recv = new LinkedHashMap<>();
        recv.put("hits", e.receivedHits); recv.put("damage", e.receivedDamage);
        recv.put("attribution", e.gaps.contains("overlapping_targets") ? "single_open_window_partial" : "single_open_window");
        recv.put("interpretation", "received_damage_not_classified_as_mistake");
        m.put("received", recv);
        Map<String,Object> gear = new LinkedHashMap<>();
        gear.put("at_start", e.wornAtStart == null ? "unknown" : e.wornAtStart);
        gear.put("revisions_observed", new ArrayList<>(e.revisions));
        // A change needs two adjacent revisions with different content. Unknown then known, or the same gear
        // re-read as a fresh baseline after an unreadable read, is not a change.
        boolean changed = false;
        for (int i = 1; i < e.revisions.size(); i++)
            changed |= !Objects.equals(e.revisions.get(i - 1).get("content_id"), e.revisions.get(i).get("content_id"));
        gear.put("changed_during", changed);
        gear.put("timing", "observed_at_own_hits_not_exact_change_time");
        m.put("equipment", gear);
        m.put("loot", new ArrayList<>(e.loot));
        m.put("loot_status", !e.loot.isEmpty() ? "matched" : "observed_death".equals(outcome) ? "none_matched" : "not_applicable");
        m.put("gaps", new ArrayList<>(e.gaps));
        m.put("contributing_sequences", new ArrayList<>(e.sequences)); m.put("contributing_truncated", e.sequencesTruncated);
        return m;
    }

    // Same canonical form as LoadoutRevision.contentId (loadout.revision.v1), so one gear set has one ID.
    // Slot indexes 6, 8 and 11 are not worn item slots and are excluded.
    static final String[] SLOT_NAMES = {"head", "cape", "amulet", "weapon", "body", "shield", null, "legs",
        null, "gloves", "boots", null, "ring", "ammo"};

    /** sha256 of "loadout.v1;" plus "name=item_id;" for each named slot in index order. */
    static String contentId(Map<String,Object> slots)
    {
        StringBuilder canonical = new StringBuilder("loadout.v1;");
        for (int i = 0; i < SLOT_NAMES.length; i++)
        {
            Object item = slots.get(SLOT_NAMES[i]);
            if (SLOT_NAMES[i] != null && item != null) canonical.append(SLOT_NAMES[i]).append('=').append(item).append(';');
        }
        return AccountConnectPlugin.sha256Hex(canonical.toString());
    }

    /**
     * Server/offline read model from the EXISTING own-combat-v1 wire events (combat_hit, combat_npc_end) of one
     * gameplay_session. No new wire field is needed. Gear, own death and loot are not in those events, so the
     * result marks them unknown. Delivery can duplicate or reorder: rows are deduplicated by source_sequence
     * and replayed in source order.
     */
    static Map<String,Object> deriveFromEvents(String gameplaySession, List<Map<String,Object>> events, int asOfTick)
    {
        TreeMap<Long,Map<String,Object>> rows = new TreeMap<>();
        for (Map<String,Object> ev : events)
        {
            if (ev == null || !Objects.equals(gameplaySession, ev.get("gameplay_session"))
                || !(ev.get("source_sequence") instanceof Number) || !(ev.get("source_tick") instanceof Number)
                || !(ev.get("observed_at_ms") instanceof Number)) continue;
            Map<String,Object> value = new LinkedHashMap<>();
            Map<String,Object> row = new LinkedHashMap<>();
            if ("combat_hit".equals(ev.get("type")))
            {
                row.put("kind", "combat.own_hits");
                for (String k : Arrays.asList("direction", "amount", "hitsplat_type", "npc_id")) if (ev.containsKey(k)) value.put(k, ev.get(k));
                if (ev.get("target_key") != null) value.put("target_observation_id", ev.get("target_key"));
            }
            else if ("combat_npc_end".equals(ev.get("type")))
            {
                row.put("kind", "combat.npc_lifecycle");
                value.put("target_observation_id", ev.get("target_key")); value.put("end", ev.get("end"));
            }
            else continue;
            row.put("sequence", ((Number) ev.get("source_sequence")).longValue());
            row.put("tick", ((Number) ev.get("source_tick")).intValue());
            row.put("observed_at_ms", ev.get("observed_at_ms")); row.put("value", value);
            rows.putIfAbsent(((Number) ev.get("source_sequence")).longValue(), row);
        }
        // Existing loot events carry an NPC name, not an ID, and wall-clock ts, not a tick. Same account only:
        // the caller supplies events of one account/profile. Linking is a time-window inference. Loot is merged
        // in time order with the combat rows, so it links before older encounters leave the bounded closed list.
        Set<Object> seenLoot = new HashSet<>();
        List<Map<String,Object>> loot = new ArrayList<>();
        for (Map<String,Object> ev : events)
            if (ev != null && "loot".equals(ev.get("type")) && "npc".equals(ev.get("source_type")) && ev.get("ts") instanceof Number
                && ev.get("event_id") instanceof String && seenLoot.add(ev.get("event_id"))) loot.add(ev);
        loot.sort(Comparator.comparingLong(ev -> ((Number) ev.get("ts")).longValue()));
        CombatEncounterTracker t = new CombatEncounterTracker(gameplaySession);
        int next = 0;
        for (Map<String,Object> row : rows.values())
        {
            long at = ((Number) row.get("observed_at_ms")).longValue();
            for (; next < loot.size() && ((Number) loot.get(next).get("ts")).longValue() < at; next++) t.replayLoot(loot.get(next));
            t.accept(row);
        }
        for (; next < loot.size(); next++) t.replayLoot(loot.get(next));
        Map<String,Object> out = t.summary(asOfTick);
        List<Long> gearChanges = new ArrayList<>();
        for (Map<String,Object> ev : events)
            if (ev != null && "equip_change".equals(ev.get("type")) && ev.get("ts") instanceof Number) gearChanges.add(((Number) ev.get("ts")).longValue());
        for (Object o : (List<?>) out.get("encounters"))
        {
            Map<String,Object> e = (Map<String,Object>) o, gear = (Map<String,Object>) e.get("equipment");
            long from = ((Number) e.get("start_observed_at_ms")).longValue();
            // Open: any later change counts. Closed without an end time: bounded by the last own hit only.
            Object to = "open".equals(e.get("status")) ? null
                : e.get("end_observed_at_ms") != null ? e.get("end_observed_at_ms") : e.get("last_own_hit_observed_at_ms");
            boolean changed = false;
            for (long at : gearChanges) changed |= at >= from && (to == null || at <= ((Number) to).longValue());
            gear.put("changed_during", changed ? Boolean.TRUE : "not_observed");
            gear.put("timing", "equip_change_event_wall_clock");
        }
        long expected = rows.isEmpty() ? 0 : rows.firstKey(), missing = 0;
        for (Long s : rows.keySet()) { missing += s - expected; expected = s + 1; }
        out.put("input_scope", "own_combat_v1_events;gear_death_loot_not_in_events");
        out.put("input_sequence_first", rows.isEmpty() ? null : rows.firstKey());
        out.put("input_sequence_missing_between", missing); // other own families share the sequence, so not all are combat
        return out;
    }

    private void replayLoot(Map<String,Object> ev)
    {
        Map<String,Object> v = new LinkedHashMap<>(); v.put("items", ev.get("items"));
        loot(v, -1, ((Number) ev.get("ts")).longValue(), "loot_event_id", (String) ev.get("event_id"), true);
    }

    /** Offline replay of one session's ordered rows, e.g. from a captured own_gameplay snapshot or fixture. */
    static Map<String,Object> derive(String gameplaySession, List<Map<String,Object>> rows, int asOfTick)
    {
        CombatEncounterTracker t = new CombatEncounterTracker(gameplaySession);
        for (Map<String,Object> row : rows) t.accept(row);
        return t.summary(asOfTick);
    }
}

/*
 * Pile-centred counterparty candidates, and the one rule that turns them into a name.
 *
 * ⚠ THE HONESTY CONSTRAINT, AND IT IS THE WHOLE POINT OF THIS FILE.
 * The Take happens in the OTHER player's client. Nothing in our packet stream names the taker, so
 * no amount of geometry can prove who picked a pile up. What this class produces is EVIDENCE with a
 * stated strength, never a fact. The one case worth naming is the case a human would accept on
 * sight: exactly one other player standing ON the pile's own tile at the moment it vanished.
 * Everything else — two people on the tile, nobody on it, somebody one step away — resolves to
 * AMBIGUOUS or UNKNOWN and names nobody.
 *
 * WHY PILE-CENTRED AND NOT PLAYER-CENTRED. The existing nearby snapshot measures from OUR
 * character. In a drop trade the staff member routinely walks off before the customer arrives, so a
 * player at distance 0 from US is not on the pile, and a player on the pile can be many tiles from
 * us. Measuring from the pile's own tile is the difference between an answer and a coincidence.
 *
 * Pure: JDK only, no RuneLite types, so every branch is testable without a client.
 */
package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class DropCandidates
{
	private DropCandidates()
	{
	}

	/** How the counterparty question was answered for one pile. Written onto every removal row. */
	public static final String STATUS_RESOLVED = "RESOLVED";
	/** More than one player stood on the pile's tile. Somebody took it; we cannot say which. */
	public static final String STATUS_AMBIGUOUS = "AMBIGUOUS";
	/** Nobody was on the tile, or the cause was not an early removal. Nothing to say. */
	public static final String STATUS_UNKNOWN = "UNKNOWN";

	/**
	 * How far from the pile a player is still recorded as a candidate.
	 *
	 * Wider than the resolve rule on purpose. Only distance 0 ever RESOLVES, but a reviewer looking
	 * at an ambiguous pile wants to see who else was around, and the server-side resolver may later
	 * weigh persistence across ticks. Recording more than we resolve on costs a few bytes and keeps
	 * the evidence; resolving on more than distance 0 would be a guess.
	 */
	public static final int CANDIDATE_RANGE_TILES = 3;

	/**
	 * Cap on recorded candidates for one pile. A crowded tile cannot make the row unbounded. Nearest
	 * first, so the players that matter are never the ones cut.
	 */
	public static final int CANDIDATE_CAP = 8;

	/** Animation id when the client reports none (the game's own idle value). */
	public static final int NO_ANIMATION = -1;

	/** One observed player, in world tiles. Deliberately a plain value type, not a RuneLite Player. */
	public static final class Observed
	{
		public final String rsn;
		public final int x;
		public final int y;
		public final int plane;
		public final int combatLevel;
		/** The animation the player was playing at the moment of observation, or NO_ANIMATION. */
		public final int animation;

		public Observed(String rsn, int x, int y, int plane, int combatLevel)
		{
			this(rsn, x, y, plane, combatLevel, NO_ANIMATION);
		}

		public Observed(String rsn, int x, int y, int plane, int combatLevel, int animation)
		{
			this.rsn = rsn;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.combatLevel = combatLevel;
			this.animation = animation;
		}
	}

	/**
	 * One sighting of a Telekinetic Grab aimed at a tile: the travelling projectile (which names its
	 * caster) or the impact graphic on the tile (which does not). A grab takes a pile from up to ten
	 * tiles away, so a player standing on the tile when it vanished may be an innocent bystander.
	 */
	public static final class TelegrabSighting
	{
		public final int x;
		public final int y;
		public final int plane;
		public final int tick;
		/** "projectile" or "impact". */
		public final String via;
		/** Caster name, only known from a projectile. Null otherwise. */
		public final String caster;
		/** True when the caster is our own character. */
		public final boolean casterSelf;
		public final int casterX;
		public final int casterY;

		public TelegrabSighting(int x, int y, int plane, int tick, String via,
			String caster, boolean casterSelf, int casterX, int casterY)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.tick = tick;
			this.via = via;
			this.caster = caster;
			this.casterSelf = casterSelf;
			this.casterX = casterX;
			this.casterY = casterY;
		}
	}

	/**
	 * How many ticks before a pile vanished a grab aimed at its tile still counts. The projectile flies
	 * for a few ticks before the item leaves the ground; ten covers the longest cast range with margin
	 * and keeps an old, unrelated grab on the same tile out.
	 */
	public static final int TELEGRAB_WINDOW_TICKS = 10;

	/** Telekinetic Grab reaches about ten tiles; a caster further out cannot have taken the pile. */
	public static final int TELEGRAB_RANGE_TILES = 10;

	/** The player animation of a Telekinetic Grab cast (gameval AnimationID.HUMAN_CASTTELEGRAB). */
	public static final int TELEGRAB_CAST_ANIMATION = 723;

	/** The travelling grab projectile (gameval SpotanimID.TELEGRAB_TRAVEL). */
	public static final int TELEGRAB_PROJECTILE = 143;

	/** The grab's impact graphic on the item's tile (gameval SpotanimID.TELEGRAB_IMPACT). */
	public static final int TELEGRAB_IMPACT = 144;

	/**
	 * The Telekinetic Grab evidence for one pile, or null when no grab aimed at this exact tile was seen
	 * in the window before the removal. A named caster comes from the most recent projectile.
	 */
	public static Map<String, Object> telegrabAt(List<TelegrabSighting> sightings,
		int pileX, int pileY, int pilePlane, int removalTick)
	{
		if (sightings == null)
		{
			return null;
		}
		TelegrabSighting latest = null;
		TelegrabSighting named = null;
		java.util.Set<String> via = new java.util.TreeSet<>();
		for (TelegrabSighting s : sightings)
		{
			if (s == null || s.x != pileX || s.y != pileY || s.plane != pilePlane)
			{
				continue;
			}
			int age = removalTick - s.tick;
			if (age < 0 || age > TELEGRAB_WINDOW_TICKS)
			{
				continue;
			}
			via.add(s.via);
			if (latest == null || s.tick >= latest.tick)
			{
				latest = s;
			}
			if ((s.caster != null || s.casterSelf) && (named == null || s.tick >= named.tick))
			{
				named = s;
			}
		}
		if (latest == null)
		{
			return null;
		}
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("via", new ArrayList<>(via));
		m.put("ticks_before", removalTick - latest.tick);
		if (named != null)
		{
			if (named.casterSelf)
			{
				m.put("caster_self", true);
			}
			else
			{
				m.put("caster", named.caster);
				m.put("caster_dx", named.casterX - pileX);
				m.put("caster_dy", named.casterY - pileY);
				m.put("caster_dist", tileDistance(named.casterX, named.casterY, pileX, pileY));
			}
		}
		return m;
	}

	/**
	 * Chebyshev distance, which is how OSRS measures tiles: one diagonal step is distance 1, not
	 * 1.41. A Euclidean measure here would make a diagonal neighbour look further away than an
	 * orthogonal one when the game treats them identically.
	 */
	public static int tileDistance(int ax, int ay, int bx, int by)
	{
		return Math.max(Math.abs(ax - bx), Math.abs(ay - by));
	}

	/**
	 * Candidates for one pile, nearest first, each carrying its offset FROM THE PILE.
	 *
	 * A player on another plane is never a candidate whatever its x/y: planes are separate floors and
	 * a player directly above the pile cannot have taken it.
	 */
	public static List<Map<String, Object>> candidatesAt(List<Observed> players,
		int pileX, int pileY, int pilePlane)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		if (players == null)
		{
			return out;
		}
		List<Observed> inRange = new ArrayList<>();
		for (Observed p : players)
		{
			if (p == null || p.rsn == null || p.rsn.isEmpty() || p.plane != pilePlane)
			{
				continue;
			}
			int d = tileDistance(p.x, p.y, pileX, pileY);
			// The mechanically relevant area is not one fixed ring: a player further out who is casting
			// Telekinetic Grab can take the pile from range, so that player is a candidate too.
			if (d <= CANDIDATE_RANGE_TILES
				|| (d <= TELEGRAB_RANGE_TILES && p.animation == TELEGRAB_CAST_ANIMATION))
			{
				inRange.add(p);
			}
		}
		// Order for the cap: players ON the pile first, then grab casters (they can take it from range),
		// then everyone else by distance; name breaks ties so the order is stable.
		Collections.sort(inRange, (a, b) ->
		{
			int c = Integer.compare(capRank(a, pileX, pileY), capRank(b, pileX, pileY));
			if (c == 0)
			{
				c = Integer.compare(tileDistance(a.x, a.y, pileX, pileY), tileDistance(b.x, b.y, pileX, pileY));
			}
			return c != 0 ? c : a.rsn.compareTo(b.rsn);
		});
		for (Observed p : inRange)
		{
			if (out.size() >= CANDIDATE_CAP)
			{
				break;
			}
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("rsn", p.rsn);
			// Offsets FROM THE PILE, not from us. A reader must never have to know where we stood.
			m.put("dx", p.x - pileX);
			m.put("dy", p.y - pileY);
			m.put("dist", tileDistance(p.x, p.y, pileX, pileY));
			m.put("cb", p.combatLevel);
			// What the player was DOING when the pile vanished. A floor pickup plays one animation and a
			// grab cast another, so a reader can rule out a bystander who was doing something else.
			m.put("anim", p.animation);
			out.add(m);
		}
		return out;
	}

	private static int capRank(Observed p, int pileX, int pileY)
	{
		if (tileDistance(p.x, p.y, pileX, pileY) == 0)
		{
			return 0;
		}
		return p.animation == TELEGRAB_CAST_ANIMATION ? 1 : 2;
	}

	/**
	 * The resolve rule: exactly ONE candidate standing on the pile's own tile.
	 *
	 * @return the RSN when that holds, otherwise null. The caller pairs this with
	 *         {@link #statusFor} so the row always states which of the three answers it got.
	 */
	public static String resolveCounterparty(List<Map<String, Object>> candidates)
	{
		if (candidates == null || candidates.isEmpty())
		{
			return null;
		}
		String only = null;
		for (Map<String, Object> c : candidates)
		{
			Object d = c.get("dist");
			if (!(d instanceof Number) || ((Number) d).intValue() != 0)
			{
				continue;
			}
			if (only != null)
			{
				return null;		// two on the tile — ambiguous, and never a coin toss
			}
			Object rsn = c.get("rsn");
			if (!(rsn instanceof String) || ((String) rsn).isEmpty())
			{
				return null;
			}
			only = (String) rsn;
		}
		return only;
	}

	/**
	 * The status that goes on the row.
	 *
	 * AMBIGUOUS is reserved for the case where somebody WAS on the tile and we still cannot name
	 * them. An empty tile is UNKNOWN, not ambiguous: there is no competing explanation to choose
	 * between, only an absence of evidence, and conflating the two would make "we saw two people"
	 * indistinguishable from "we saw nobody".
	 */
	public static String statusFor(List<Map<String, Object>> candidates, String resolved)
	{
		if (resolved != null)
		{
			return STATUS_RESOLVED;
		}
		if (candidates != null)
		{
			for (Map<String, Object> c : candidates)
			{
				Object d = c.get("dist");
				if (d instanceof Number && ((Number) d).intValue() == 0)
				{
					return STATUS_AMBIGUOUS;
				}
			}
		}
		return STATUS_UNKNOWN;
	}
}

/*
 * Adaptive capture rate for a drop-trade session: 8fps baseline, 30fps around the moments that matter.
 *
 * WHY, measured. A 197-second session captured at a flat 30fps produced 1,814 frames and DROPPED
 * 4,058 at the 72MB budget (live, 2026-09-20). Flat 30fps for that session would have needed
 * roughly 200MB. The same session at an 8fps baseline still needed 73.8MB and truncated its tail
 * (live, same day), which is why the baseline below is 6. Truncation is not acceptable — the missing middle and end are exactly the part a
 * dispute is about — and raising the budget pays full price for footage of a tile nobody is
 * standing on. So the rate follows the evidence: a continuous baseline that proves the pile sat
 * there untouched, and short 30fps bursts around the Drop, the spawn, the removal and a new drop
 * inside the tail, which are the instants somebody actually has to SEE.
 *
 * THE LOOKBEHIND IS WHY THIS CLASS EXISTS. "2 seconds BEFORE the removal" cannot be decided when
 * the removal happens, because those frames are already in the past. So the sampler runs at 30fps
 * the whole time and this class decides what to KEEP:
 *
 *   * baseline: keep 1 frame in every (30/8), drop the rest immediately;
 *   * a held PRE-ROLL of the most recent PRE_ROLL_MILLIS of 30fps frames, which the dropped ones go
 *     into rather than being discarded;
 *   * on an event: flush that pre-roll into the clip and keep every frame for POST_ROLL_MILLIS.
 *
 * Memory for the pre-roll is 2s x 30fps x ~40KB, about 2.4MB, on top of one 40-frame segment. That
 * is bounded and small, and it is the whole cost of being able to show the two seconds before a
 * pile vanished.
 *
 * Pure: JDK only, no RuneLite, no AWT, and the clock is a parameter, so every branch is testable.
 */
package com.osrsbestinslot.export;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/** Decides, per sampled frame, whether it is kept now, held as pre-roll, or dropped. */
public class DropCaptureRate
{
	/** The sampler's own rate. Every frame passes through here; this class decides what survives. */
	public static final int SAMPLE_FPS = 30;

	/**
	 * Continuous baseline, and it is 6 because 8 was MEASURED not to fit.
	 *
	 * The live 197-second rerun at 8fps needed 73.8MB against the 72MB budget and truncated the last
	 * 6 seconds, which is the 5-second tail — the worst possible thing to lose. The overshoot was not
	 * the baseline alone: the real session fired FOUR bursts totalling 13 seconds at 30fps, while the
	 * first sizing modelled two totalling about 7. 6 divides 30 exactly, so the cadence is a perfectly
	 * even one frame every 5 sampled frames, and the same session costs 58.3MB — 19% under budget,
	 * with the truncation point pushed from about 195 seconds of session out to about 245.
	 */
	public static final int BASELINE_FPS = 6;

	/** Kept at full rate BEFORE an event. Held in the pre-roll ring until an event claims it. */
	public static final long PRE_ROLL_MILLIS = 2_000L;

	/** Kept at full rate AFTER an event. */
	public static final long POST_ROLL_MILLIS = 2_000L;

	/** What the caller must do with the frame it just sampled. */
	public enum Decision
	{
		/** Keep it. Either the baseline cadence chose it, or a burst is running. */
		KEEP,
		/** Not kept, but held as pre-roll so a burst starting within 2s can still claim it. */
		HOLD,
	}

	/** Why a burst was triggered. Recorded so the manifest can report what the clip covers. */
	public enum Event
	{
		DROP_ACTION,
		PILE_SPAWN,
		PILE_REMOVED,
		/** A new drop inside the 5-second tail. It cancels the stop, so it is a moment too. */
		TAIL_DROP
	}

	private final int baselineFps;
	private final long preRollMillis;
	private final long postRollMillis;

	/** Frames held for the lookbehind, oldest first, each with the wall time it was sampled. */
	private final Deque<long[]> preRollTimes = new ArrayDeque<>();
	private final Deque<byte[]> preRollFrames = new ArrayDeque<>();

	/** Wall time the running burst ends, or 0 when no burst is running. */
	private long burstUntilMillis;
	/** Baseline cadence counter, in sampled frames. */
	private int sampleCounter;
	private int keptBaseline;
	private int keptBurst;
	private int dropped;
	private int bursts;

	public DropCaptureRate()
	{
		this(BASELINE_FPS, PRE_ROLL_MILLIS, POST_ROLL_MILLIS);
	}

	public DropCaptureRate(int baselineFps, long preRollMillis, long postRollMillis)
	{
		if (baselineFps < 1 || baselineFps > SAMPLE_FPS)
		{
			throw new IllegalArgumentException("baselineFps must be 1.." + SAMPLE_FPS);
		}
		this.baselineFps = baselineFps;
		this.preRollMillis = preRollMillis;
		this.postRollMillis = postRollMillis;
	}

	/**
	 * A moment worth full detail happened. Starts or EXTENDS a burst.
	 *
	 * Extending rather than restarting matters for a rapid multi-drop: four drops a second apart
	 * must produce one continuous high-rate stretch, not four overlapping ones whose ends cut into
	 * each other.
	 */
	public void onEvent(Event event, long nowMillis)
	{
		long until = nowMillis + postRollMillis;
		if (until > burstUntilMillis)
		{
			if (burstUntilMillis <= nowMillis)
			{
				bursts++;		// a genuinely new burst, not an extension of a running one
			}
			burstUntilMillis = until;
		}
	}

	/** True while a burst is running, so the caller can report the current rate. */
	public boolean bursting(long nowMillis)
	{
		return nowMillis < burstUntilMillis;
	}

	/**
	 * Decide what happens to one sampled frame.
	 *
	 * @return KEEP to hand it to the segmenter now, HOLD to leave it in the pre-roll.
	 */
	public Decision offer(byte[] frame, long nowMillis)
	{
		expirePreRoll(nowMillis);
		if (bursting(nowMillis))
		{
			keptBurst++;
			return Decision.KEEP;
		}
		// Baseline cadence. Integer arithmetic on the sample index, so 8fps out of 30 is a steady
		// 3-4-4 pattern rather than a drifting float comparison.
		boolean keep = (sampleCounter * baselineFps) / SAMPLE_FPS
			!= ((sampleCounter + 1) * baselineFps) / SAMPLE_FPS;
		sampleCounter++;
		if (sampleCounter >= SAMPLE_FPS)
		{
			sampleCounter = 0;
		}
		if (keep)
		{
			keptBaseline++;
			return Decision.KEEP;
		}
		// NOT kept, but NOT discarded either: held so a burst starting within the next preRoll
		// window can still show the moment leading up to it.
		if (frame != null && frame.length > 0)
		{
			preRollFrames.addLast(frame);
			preRollTimes.addLast(new long[]{nowMillis});
		}
		dropped++;
		return Decision.HOLD;
	}

	/**
	 * Take the held pre-roll, oldest first, for a burst that has just started.
	 *
	 * Called right after onEvent. Returns the frames in chronological order so the caller can hand
	 * them to the segmenter before the frame that triggered the burst.
	 */
	public List<byte[]> claimPreRoll(long nowMillis)
	{
		expirePreRoll(nowMillis);
		List<byte[]> out = new ArrayList<>(preRollFrames);
		preRollFrames.clear();
		preRollTimes.clear();
		keptBurst += out.size();
		dropped -= out.size();		// they were counted as dropped when held; they are kept after all
		return out;
	}

	/** Discard pre-roll frames older than the lookbehind window. */
	private void expirePreRoll(long nowMillis)
	{
		while (!preRollTimes.isEmpty() && nowMillis - preRollTimes.peekFirst()[0] > preRollMillis)
		{
			preRollTimes.pollFirst();
			preRollFrames.pollFirst();
		}
	}

	/** Frames held in the lookbehind right now. The memory this class adds, and it is bounded. */
	public int preRollSize()
	{
		return preRollFrames.size();
	}

	public int keptBaseline()
	{
		return keptBaseline;
	}

	public int keptBurst()
	{
		return keptBurst;
	}

	/** Frames genuinely discarded: sampled, not kept, and never claimed by a burst. */
	public int discarded()
	{
		return dropped;
	}

	/** How many separate high-rate stretches ran. Reported on the manifest. */
	public int bursts()
	{
		return bursts;
	}

	public int baselineFps()
	{
		return baselineFps;
	}

	/** Drop everything held. Used when a session ends. */
	public void clear()
	{
		preRollFrames.clear();
		preRollTimes.clear();
		burstUntilMillis = 0L;
	}

	/**
	 * Bytes one second of baseline footage costs, at a measured per-frame size.
	 *
	 * Used by the budget arithmetic in the tests, so the sizing claim is checked rather than
	 * asserted in a comment.
	 */
	public static long baselineBytesPerSecond(int baselineFps, int bytesPerFrame)
	{
		return (long) baselineFps * bytesPerFrame;
	}
}

/*
 * Segmented frame buffering for a drop-trade session — the replacement for the store clip's ring.
 *
 * WHY NOT THE RING. The store path keeps the last 12 seconds in a ClipRingBuffer and uploads it at
 * the end. That is right for a shop visit, whose evidence is the transaction and the seconds around
 * it, and wrong for a drop trade: the DROP is at the START and the customer may arrive minutes
 * later, so a ring loses the very thing the clip exists to show. Requirement: keep the start.
 *
 * WHY MEMORY IS STILL BOUNDED. Nothing accumulates for the length of the session. Frames fill one
 * SEGMENT_FRAMES-sized segment, the segment is handed to the uploader, and the buffer starts empty
 * again. The uploader holds each segment only until the server acknowledges it, and the segmenter
 * frees those bytes when it does. Retained bytes are therefore one segment plus whatever is still
 * unacknowledged, not the whole session — a 20-minute trade costs the same heap as a 10-second one
 * while uploads keep up.
 *
 * WHY SEGMENTS CARRY AN INDEX. The store path reassembles chunks by comparing `captured_at`
 * timestamps, which works but infers the order. A drop clip must join deterministically to its
 * session, so each segment carries its own 0-based index and the session id. Two segments uploaded
 * out of order, or one retried after a failure, still reassemble into exactly one ordering.
 *
 * Standalone and unit-testable: JDK only, no RuneLite and no AWT, so the whole path can be driven
 * with synthetic byte arrays.
 */
package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Accumulates encoded frames and yields bounded, ordered segments ready for upload. */
public class DropFrameSegmenter
{
	/**
	 * Frames per segment. MUST stay at or below the store path's CLIP_CHUNK_FRAMES, because one
	 * segment is one POST and the server writes one R2 object per frame inside ONE Worker
	 * invocation. A Worker has a hard subrequest ceiling, and a 100-frame chunk was measured dying
	 * at 45-49 frames written, leaving orphaned frames and no manifest. 40 keeps it inside budget.
	 */
	public static final int SEGMENT_FRAMES = 40;

	/** A frame larger than this failed to encode sanely. Mirrors the store path's per-frame cap. */
	public static final int MAX_FRAME_BYTES = 1_000_000;

	/**
	 * Maximum bytes held LOCALLY at once: the segment being filled, plus every segment handed to the
	 * uploader that the server has not acknowledged yet.
	 *
	 * THIS IS NOT A SESSION CAP, and the difference is the whole point. It used to be a lifetime
	 * total, which made a long session truncate however well the network was working — measured
	 * live, a 196-second session at an 8fps baseline hit 72MB and lost its own tail. Segments upload
	 * continuously while the session runs, and an acknowledged segment's bytes are freed, so a
	 * session of any length costs the same memory as a short one as long as uploads keep up.
	 *
	 * What it still bounds is the RETRY BUFFER. If the server stops acknowledging, unacknowledged
	 * segments accumulate here and nothing else frees them. At that point the client refuses new
	 * frames and records the session as truncated, which is the visible failure: a clip that is
	 * short because the network died says so, rather than quietly pretending to be complete.
	 */
	public static final long UNACKED_BYTE_BUDGET = 72_000_000L;

	private final int segmentFrames;
	private final int maxFrameBytes;
	private final long unackedByteBudget;

	private final List<byte[]> current = new ArrayList<>();
	private int currentBytes;
	private int nextSegmentIndex;
	private long sessionBytes;
	private int acceptedFrames;
	private int rejectedFrames;
	private boolean truncated;
	/** Bytes of each segment handed out and not yet settled, keyed by segment index. */
	private final java.util.Map<Integer, Integer> outstanding = new java.util.LinkedHashMap<>();
	/** Sum of the map above, kept alongside it so the hot path does not walk the map. */
	private long outstandingBytes;
	/** The highest heldBytes() ever reached. Reported, so "bounded memory" is measured not claimed. */
	private long peakHeldBytes;
	/** Wall time of the first frame in the segment being filled. 0 when the segment is empty. */
	private long currentFirstFrameMillis;
	/**
	 * Set by {@link #discardAll()} and never cleared. A discarded segmenter accepts nothing and
	 * yields nothing, so a reference held by an in-flight callback cannot produce a late upload.
	 */
	private boolean discarded;

	public DropFrameSegmenter()
	{
		this(SEGMENT_FRAMES, MAX_FRAME_BYTES, UNACKED_BYTE_BUDGET);
	}

	public DropFrameSegmenter(int segmentFrames, int maxFrameBytes, long unackedByteBudget)
	{
		if (segmentFrames < 1)
		{
			throw new IllegalArgumentException("segmentFrames must be >= 1");
		}
		this.segmentFrames = segmentFrames;
		this.maxFrameBytes = maxFrameBytes;
		this.unackedByteBudget = unackedByteBudget;
	}

	/** One flushable unit of a session's footage. Immutable once handed out. */
	public static final class Segment
	{
		/** 0-based position in the session. THE ordering key — never inferred from a timestamp. */
		public final int index;
		/** Wall time of this segment's FIRST frame, for playback timing and for the stitcher. */
		public final long firstFrameMillis;
		public final List<byte[]> frames;
		public final int bytes;

		Segment(int index, long firstFrameMillis, List<byte[]> frames, int bytes)
		{
			this.index = index;
			this.firstFrameMillis = firstFrameMillis;
			this.frames = Collections.unmodifiableList(frames);
			this.bytes = bytes;
		}

		public int frameCount()
		{
			return frames.size();
		}
	}

	/**
	 * Add one already-encoded frame.
	 *
	 * @return a full segment ready to upload, or null when the current segment still has room.
	 */
	public synchronized Segment add(byte[] frame, long nowMillis)
	{
		if (discarded)
		{
			// The identity this footage belonged to is gone. Refusing here, rather than only at the
			// caller, is what makes a stale reference to this object harmless.
			rejectedFrames++;
			return null;
		}
		if (frame == null || frame.length == 0 || frame.length > maxFrameBytes)
		{
			rejectedFrames++;
			return null;
		}
		if (heldBytes() + frame.length > unackedByteBudget)
		{
			// The RETRY BUFFER is full, which means the server has stopped acknowledging. A working
			// upload path frees these bytes continuously, so reaching this at all is a network
			// failure, not a long session. Keep what is captured and stop taking more. Recording the
			// fact is the point: a truncated clip that says so is evidence, and a truncated clip
			// that does not is a lie about what happened after the cut.
			truncated = true;
			rejectedFrames++;
			return null;
		}
		if (current.isEmpty())
		{
			currentFirstFrameMillis = nowMillis;
		}
		current.add(frame);
		currentBytes += frame.length;
		sessionBytes += frame.length;
		acceptedFrames++;
		peakHeldBytes = Math.max(peakHeldBytes, heldBytes());
		if (current.size() >= segmentFrames)
		{
			return takeSegment();
		}
		return null;
	}

	/**
	 * Hand over the partially-filled segment at the end of a session, or null when it is empty.
	 *
	 * Called once, at stop. A session whose frame count divides exactly by segmentFrames ends with
	 * nothing here, which is correct and not an error.
	 */
	public synchronized Segment flushRemainder()
	{
		if (discarded || current.isEmpty())
		{
			return null;
		}
		return takeSegment();
	}

	private Segment takeSegment()
	{
		Segment seg = new Segment(nextSegmentIndex++, currentFirstFrameMillis,
			new ArrayList<>(current), currentBytes);
		// The bytes move from the segment being filled to the uploader. They are still HELD, because
		// the uploader keeps the frames alive until the server answers, so the total is unchanged
		// here by design.
		outstanding.put(seg.index, seg.bytes);
		outstandingBytes += seg.bytes;
		current.clear();
		currentBytes = 0;
		currentFirstFrameMillis = 0L;
		return seg;
	}

	/**
	 * The server stored this segment. Free its bytes.
	 *
	 * This is what turns the budget into a retry buffer rather than a session cap. Idempotent: a
	 * duplicate acknowledgement frees nothing twice, because the index is removed on the first one.
	 */
	public synchronized void segmentAcknowledged(int index)
	{
		settle(index);
	}

	/**
	 * This segment will never be sent: retries are exhausted, or the upload could not start.
	 *
	 * Its bytes are freed too. Holding them would let one dead segment shrink the buffer for the
	 * rest of the session, so a single failure would slowly strangle capture. The segment is LOST
	 * and the caller counts it as failed, which is what the manifest reports. Freeing the memory
	 * does not hide that.
	 */
	public synchronized void segmentAbandoned(int index)
	{
		settle(index);
	}

	private void settle(int index)
	{
		Integer bytes = outstanding.remove(index);
		if (bytes != null)
		{
			outstandingBytes -= bytes;
		}
	}

	/** Bytes held right now: the segment being filled plus every unacknowledged segment. */
	public synchronized long heldBytes()
	{
		return outstandingBytes + currentBytes;
	}

	/** Segments handed out and not yet acknowledged or abandoned. */
	public synchronized int unsettledSegments()
	{
		return outstanding.size();
	}

	/** The highest heldBytes() this session ever reached. The memory claim, measured. */
	public synchronized long peakHeldBytes()
	{
		return peakHeldBytes;
	}

	/** Segments handed out so far. After flushRemainder this is the session's total segment count. */
	public synchronized int segmentCount()
	{
		return nextSegmentIndex;
	}

	public synchronized int acceptedFrames()
	{
		return acceptedFrames;
	}

	/** Frames refused: failed encode, oversized, or past the retry buffer. Reported, never hidden. */
	public synchronized int rejectedFrames()
	{
		return rejectedFrames;
	}

	public synchronized long sessionBytes()
	{
		return sessionBytes;
	}

	/** True when the retry buffer filled, so the clip does not cover the whole session. */
	public synchronized boolean truncated()
	{
		return truncated;
	}

	/** Frames held in memory right now. The memory bound this class exists to enforce. */
	public synchronized int bufferedFrames()
	{
		return current.size();
	}

	/** Drop everything held. Used when a session ends with nothing worth uploading. */
	public synchronized void clear()
	{
		current.clear();
		currentBytes = 0;
		currentFirstFrameMillis = 0L;
	}

	/**
	 * THE IDENTITY WITHDRAWAL PATH. Drop the filling segment AND the retry buffer, then refuse
	 * everything afterwards.
	 *
	 * {@link #clear()} only empties the segment being filled. That is enough when a session ends
	 * tidily, because every segment already handed to the uploader belongs to the same account and
	 * is still allowed to finish. It is NOT enough when the account identity behind the footage is
	 * withdrawn or swapped: the segments counted in the outstanding map were captured under the old
	 * token and must never reach the network, so their accounting is dropped here and the caller
	 * strands the in-flight attempts themselves.
	 *
	 * The discarded flag is the part that makes the bytes UNREACHABLE rather than merely
	 * unaccounted. After this call add() refuses every frame and flushRemainder() yields nothing,
	 * so a caller still holding this object cannot produce a segment from it.
	 */
	public synchronized void discardAll()
	{
		discarded = true;
		current.clear();
		currentBytes = 0;
		currentFirstFrameMillis = 0L;
		outstanding.clear();
		outstandingBytes = 0L;
	}

	/** True once discardAll() has run. Nothing can come out of this segmenter again. */
	public synchronized boolean discarded()
	{
		return discarded;
	}
}

/*
 * Drop-trade session lifecycle — the state machine behind one continuous proof clip.
 *
 * A staff drop trade is several Drop actions, several piles on the ground, and several removals,
 * spread over as long as the customer takes to arrive. The evidence that proves it is ONE clip
 * covering all of that, not one clip per drop.
 *
 * This class owns WHEN that clip starts, when it may stop, and which drops belong to it. It is
 * deliberately pure: no RuneLite, no AWT, no clock of its own — every method takes the caller's
 * millisecond clock. That is what lets the whole lifecycle be driven under test, including the
 * races that only appear at real timing (a second drop landing inside the stop tail).
 *
 * THE CONTRACT, restated after the 0.7.14 privacy review found it unmet:
 *
 *   FIRST Drop action -> one continuous session
 *     -> every live pile AND every pending drop that has not yet produced a pile is represented
 *     -> no stop while ANY of those remain
 *     -> the final pile disappears, or the final pending drop definitively expires
 *     -> exactly TAIL_MILLIS more -> stop.
 *
 * WHAT WAS WRONG BEFORE. The stop was armed from pileRemoved ALONE. Three ordinary cases never
 * reached it, and each left a recorder that ran until the player logged out:
 *
 *   A. A stackable dropped twice onto one tile merges into ONE physical pile, and the client fires
 *      ONE ItemDespawned for it. The old code made two session keys, so the second was orphaned.
 *      Fixed at the caller: a merged drop resolves its pending against the pile already live and
 *      never mints a second key.
 *   B. A Drop click that never produces a tracked pile (the destroy dialog answered No, a pile
 *      landing out of range, a region boundary) left activePiles empty with nothing to remove.
 *      Fixed here: every Drop action registers a PENDING drop with a deadline, and an expired
 *      pending releases the session exactly as a removed pile does.
 *   C. Eviction past the caller's tracking cap orphaned a key nobody could ever release.
 *      Fixed here: pileAbandoned releases the key and marks the session unprovable.
 *
 * AND THE RULE THAT FOLLOWS FROM ALL THREE. A session whose coverage cannot be PROVEN complete
 * never reports COMPLETE. An expired pending drop, an abandoned pile and a live pile at finish
 * time are all INTERRUPTED, because in each case something the clip was supposed to show was not
 * observed end to end.
 *
 * THE RULES IT ENFORCES, each of which was asked for explicitly:
 *   1. Recording starts at the FIRST Drop ACTION, not at the drop event, so the drop itself is on
 *      screen. The action fires on the click; the event only exists once the inventory and the
 *      ground spawn agree, which is ticks later.
 *   2. Recording continues while ANY pile or pending drop from this session is outstanding.
 *   3. When the last of those goes, recording runs on for exactly TAIL_MILLIS more.
 *   4. A new drop inside that tail CANCELS the stop and continues the SAME session. It never
 *      starts a second one.
 *   5. Two overlapping sessions can never exist: there is one session field, and a drop either
 *      starts it or joins it.
 */
package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * One drop-trade recording session. Not thread-safe by itself: every caller in the plugin is the
 * client thread, and the one background reader (the flusher) takes the plugin's own lock.
 */
public class DropSessionRecorder
{
	/**
	 * How long recording continues after the LAST pile leaves the ground.
	 *
	 * Five seconds, as specified. It is long enough to show the tile empty and whoever is standing
	 * on it walking away, and short enough that an idle staff client is not recording for free.
	 */
	public static final long TAIL_MILLIS = 5_000L;

	/**
	 * How long a Drop ACTION may wait for its ground pile before the session gives up on it.
	 *
	 * This is the bound that makes rule 3 reachable at all. The click arms a pending; the pile
	 * normally spawns within a tick or two. Ten seconds covers the slowest real path — the
	 * untradeable destroy dialog, which the caller already sizes at DROP_PENDING_MAX_TICKS (16
	 * ticks, about 9.6 seconds) — and then declares the drop unobserved rather than waiting
	 * forever. A pending that expires is NOT evidence of a pile, so the session it belongs to can
	 * never call itself COMPLETE.
	 */
	public static final long PENDING_DROP_EXPIRY_MILLIS = 10_000L;

	/**
	 * THE HARD CEILING on one recording, however the state machine is feeling. Thirty minutes.
	 *
	 * ROUND 5, THE STRUCTURAL BACKSTOP. "The recording always ends" has now been claimed and
	 * measured false three times, by three different routes, and every time the END paths were
	 * enumerated correctly. The defect was always in how STALE STATE ENTERS, which is an open set:
	 * the next unknown entry route produces the same immortal recorder. So the last line of defence
	 * is not another end path, it is a bound that does not care how the state got wrong.
	 *
	 * WHY THIRTY MINUTES. The design supports a 20-minute drop trade: the customer takes as long as
	 * the customer takes, and nothing stops a staff member waiting that long with piles on the
	 * ground. Thirty is comfortably above that, so no real trade is cut short, and it is still a
	 * hard bound rather than "until logout". A session ended by this cap is INTERRUPTED, never
	 * COMPLETE: the cap is the admission that coverage could not be proven whole.
	 *
	 * IT DOES NOT FALSIFY THE DISCLOSURE. Both strings promise recording continues UNTIL five
	 * seconds after the final dropped pile disappears. A cap can only ever end a recording EARLIER
	 * than that, never later, so it removes recording the user was told about and adds none.
	 */
	public static final long MAX_SESSION_MILLIS = 30L * 60L * 1_000L;

	/**
	 * How long the caller's bookkeeping may disagree with this recorder before the session is ended.
	 *
	 * ROUND 5, THE INVARIANT BACKSTOP. The recorder waits on pile KEYS. The caller owns the piles
	 * those keys stand for. When the recorder holds a key and the caller tracks no pile for this
	 * session to match it, that key can never be released and the tail can never arm: that is the
	 * exact shape of every immortal recorder found so far, arrived at by three different routes.
	 *
	 * WHY THIRTY SECONDS. It must be longer than any legitimate disagreement. The longest one the
	 * code can produce is a pending drop that runs its full PENDING_DROP_EXPIRY_MILLIS (10s) and
	 * then the TAIL_MILLIS tail (5s), which is 15 seconds, and the caller's own bookkeeping updates
	 * within a single 0.6-second game tick. Thirty seconds is twice that worst case, so a healthy
	 * session can never trip it. It is also short enough that a leaked key costs at most half a
	 * minute of extra recording instead of running until logout.
	 */
	public static final long ORPHANED_STATE_GRACE_MILLIS = 30_000L;

	/** No stop is pending. Deliberately not 0, which is a legal clock value under test. */
	private static final long NO_STOP = -1L;

	/** How a session ended. The clip is uploaded either way — INTERRUPTED is evidence, not litter. */
	public enum Outcome
	{
		/** Every drop produced a pile, every pile resolved, and the tail elapsed. */
		COMPLETE,
		/**
		 * Coverage could not be proven whole. A hop, a logout, a disconnect, a scene reload, a
		 * withdrawn grant, a drop that never produced an observable pile, or a pile the client
		 * stopped tracking. What was captured still uploads, labelled so nobody reads a partial
		 * clip as a whole one.
		 */
		INTERRUPTED
	}

	/** Why a session could not report COMPLETE. Reporting only; never used to decide the outcome. */
	public static final String REASON_NONE = "none";
	public static final String REASON_EXTERNAL = "external_interrupt";
	public static final String REASON_LIVE_PILES = "piles_still_live";
	public static final String REASON_PENDING_DROPS = "pending_drops_outstanding";
	public static final String REASON_PENDING_EXPIRED = "pending_drop_expired";
	public static final String REASON_PILE_ABANDONED = "pile_abandoned";
	/**
	 * A despawn at an item and tile where an OWNED and an UNOWNED real pile both matched. Which
	 * physical pile went is unknowable, so the clip cannot be proven to cover the whole trade.
	 */
	public static final String REASON_AMBIGUOUS_DESPAWN = "ambiguous_despawn";
	/**
	 * ROUND 8. The SCENE says no item of this pile's kind is lying on its tile any more, so the pile
	 * is physically gone even though no despawn we could attribute to it ever arrived.
	 */
	public static final String REASON_PILE_SCENE_GONE = "pile_gone_from_scene";
	/** ROUND 5 backstop: the recorder held a key no tracked pile of this session could ever release. */
	public static final String REASON_ORPHANED_STATE = "orphaned_session_state";
	/** ROUND 5 backstop: the session hit MAX_SESSION_MILLIS. */
	public static final String REASON_MAX_DURATION = "max_session_duration";

	private String sessionId;
	private int nextSeq;
	private long startedAtMillis;
	private long stopAtMillis = NO_STOP;
	private boolean interrupted;
	/** Pile keys still on the ground for THIS session. A LinkedHashSet so ordering is reproducible. */
	private final Set<String> activePiles = new LinkedHashSet<>();
	/**
	 * Drop actions that have not yet produced an observable pile, mapped to the instant they give up.
	 *
	 * This is the half the old code was missing. Without it a Drop click that never spawns a pile
	 * leaves NOTHING outstanding, the tail arms off a pile removal that can never come, and the
	 * recorder runs until an external interrupt. A LinkedHashMap so expiry order is reproducible.
	 */
	private final Map<Integer, Long> pendingDrops = new LinkedHashMap<>();
	/** Drops recorded this session. Kept so a session that never spawned a pile still reports its size. */
	private int dropCount;
	/** Set the moment anything happens that makes full coverage unprovable. Never cleared mid-session. */
	private boolean unprovable;
	private String reason = REASON_NONE;
	/**
	 * The reason a ROUND 5 backstop ended this session, or null.
	 *
	 * A separate field, and it outranks every other reason including REASON_EXTERNAL. A backstop
	 * firing is the single most important thing to be able to read off a manifest: it says the
	 * ordinary lifecycle failed and a bound had to end the recording. Folding it into {@code reason}
	 * would let the interrupt flag mask it, because an interrupt is exactly how a backstop ends a
	 * session.
	 */
	private String backstopReason;
	/** When the caller was first seen holding nothing this session could ever resolve. NO_STOP when healthy. */
	private long orphanedSinceMillis = NO_STOP;

	/** The current session id, or null when idle. */
	public String sessionId()
	{
		return sessionId;
	}

	public boolean active()
	{
		return sessionId != null;
	}

	public long startedAtMillis()
	{
		return startedAtMillis;
	}

	public int dropCount()
	{
		return dropCount;
	}

	public int activePileCount()
	{
		return activePiles.size();
	}

	/** Drop actions still waiting for a pile. Zero live piles AND zero of these means the tail may arm. */
	public int pendingDropCount()
	{
		return pendingDrops.size();
	}

	/** True when this session can no longer prove it covered every drop end to end. */
	public boolean unprovable()
	{
		return unprovable;
	}

	/** Why the session cannot report COMPLETE, or REASON_NONE. Reporting only. */
	public String reason()
	{
		if (backstopReason != null)
		{
			return backstopReason;		// a bound had to end this; that outranks every other reason
		}
		if (interrupted)
		{
			return REASON_EXTERNAL;
		}
		if (!reason.equals(REASON_NONE))
		{
			return reason;
		}
		if (!activePiles.isEmpty())
		{
			return REASON_LIVE_PILES;
		}
		if (!pendingDrops.isEmpty())
		{
			return REASON_PENDING_DROPS;
		}
		return REASON_NONE;
	}

	/** True while a stop is armed and has not yet fired. */
	public boolean stopPending()
	{
		return stopAtMillis != NO_STOP;
	}

	/**
	 * A Drop action happened. Starts a session when idle, and otherwise JOINS the running one —
	 * cancelling any armed stop, which is rule 4.
	 *
	 * The returned sequence number is ALSO registered as a pending drop. The caller must later
	 * resolve it, with pileActive when a pile spawns for it or with pendingDropResolved when the
	 * drop merged into a pile that is already live. An unresolved pending expires on its own.
	 *
	 * @param sessionIdIfNew id to adopt when this starts a new session. The caller mints it so the id
	 *                       generator stays out of this class and the tests can pin it.
	 * @return the sequence number for this drop, starting at 1 within a session.
	 */
	public int onDropAction(String sessionIdIfNew, long nowMillis)
	{
		if (sessionId == null)
		{
			sessionId = sessionIdIfNew;
			startedAtMillis = nowMillis;
			nextSeq = 0;
			interrupted = false;
			unprovable = false;
			reason = REASON_NONE;
			backstopReason = null;
			orphanedSinceMillis = NO_STOP;
			activePiles.clear();
			pendingDrops.clear();
			dropCount = 0;
		}
		// Rule 4: a drop inside the tail cancels the stop. Unconditional on purpose — cancelling a
		// stop that is not armed is a no-op, and making it conditional invites a caller to forget.
		stopAtMillis = NO_STOP;
		dropCount++;
		int seq = ++nextSeq;
		pendingDrops.put(seq, nowMillis + PENDING_DROP_EXPIRY_MILLIS);
		return seq;
	}

	/**
	 * A pile from this session is now on the ground, produced by the drop numbered {@code seq}.
	 *
	 * Resolves that drop's pending, so the pair (action, pile) is now represented by the pile alone.
	 * Also cancels a pending stop: a pile can spawn a tick or two AFTER the drop action, so a fast
	 * session could otherwise arm its stop between the action and the spawn.
	 */
	public void pileActive(String pileKey, int seq)
	{
		if (sessionId == null || pileKey == null)
		{
			return;
		}
		pendingDrops.remove(seq);
		activePiles.add(pileKey);
		stopAtMillis = NO_STOP;
	}

	/**
	 * The drop numbered {@code seq} merged into a pile that is ALREADY live in this session.
	 *
	 * This is finding F1 path A. Dropping a stackable onto an existing ground stack of the same item
	 * merges it: the game has ONE pile and fires ONE ItemDespawned, so minting a second key here
	 * would orphan it forever. The pending is resolved against the existing pile instead, and no new
	 * key is created.
	 *
	 * Does NOT cancel an armed stop on its own, because the pile it merged into is live and a live
	 * pile means no stop can be armed in the first place.
	 */
	public void pendingDropResolved(int seq)
	{
		if (sessionId == null)
		{
			return;
		}
		pendingDrops.remove(seq);
	}

	/**
	 * A pile from this session left the ground. When nothing is outstanding, arm the TAIL_MILLIS tail.
	 *
	 * Arming only when the LAST outstanding thing goes is rule 2: a session with three piles keeps
	 * recording while any of the three is still there, however long the customer takes.
	 */
	public void pileRemoved(String pileKey, long nowMillis)
	{
		if (sessionId == null || pileKey == null)
		{
			return;
		}
		if (!activePiles.remove(pileKey))
		{
			return;		// not ours, or already counted — never arm a stop off an unknown pile
		}
		maybeArmStop(nowMillis);
	}

	/**
	 * The client stopped tracking a pile without ever observing it leave the ground.
	 *
	 * Finding F1 path C: the caller's ground-item tracker is bounded, and an eviction past that
	 * bound used to strand the key here with nothing able to release it. Releasing it is what stops
	 * the recorder; marking the session unprovable is what stops that release from being mistaken
	 * for the pile actually going.
	 */
	public void pileAbandoned(String pileKey, long nowMillis)
	{
		if (sessionId == null || pileKey == null)
		{
			return;
		}
		if (!activePiles.remove(pileKey))
		{
			return;
		}
		unprovable = true;
		if (reason.equals(REASON_NONE))
		{
			reason = REASON_PILE_ABANDONED;
		}
		maybeArmStop(nowMillis);
	}

	/**
	 * A despawn could not be attributed to a pile: an owned and an unowned real pile both matched.
	 *
	 * ROUND 7, FINDING R2. This is pileAbandoned's sibling, and the difference is the KEY. An
	 * abandoned pile is one the caller has stopped tracking, so its key can never be released and
	 * holding it would run the recorder forever. An ambiguous despawn is the opposite: our pile may
	 * still be lying on the ground and its own despawn may still be coming, so releasing the key
	 * here would stop the recording while the pile the clip exists to show is still there.
	 *
	 * The key is therefore KEPT and only the proof is given up. COMPLETE is out of reach from here,
	 * and the session still ends by the later unambiguous despawn, by the orphaned-state invariant,
	 * or by the hard cap.
	 */
	public void resolutionAmbiguous(long nowMillis)
	{
		if (sessionId == null)
		{
			return;
		}
		unprovable = true;
		if (reason.equals(REASON_NONE))
		{
			reason = REASON_AMBIGUOUS_DESPAWN;
		}
		maybeArmStop(nowMillis);
	}

	/**
	 * The SCENE says this pile is no longer on its tile, so it is physically gone.
	 *
	 * ROUND 8. This is the third sibling of pileRemoved and pileAbandoned, and the difference is
	 * WHAT KNOWS. pileRemoved is driven by an ItemDespawned we could attribute to this pile.
	 * pileAbandoned is driven by the caller giving up on tracking it. This one is driven by the
	 * game's own world state: the tile is in the scene and it holds no item of this kind, so the
	 * pile really left, whatever our own event bookkeeping did or did not see.
	 *
	 * THE KEY IS RELEASED, so the tail arms and the recording ends five seconds later. That is the
	 * whole point: it is what keeps the disclosed stop honest in the LATE direction on the ambiguous
	 * route, where the despawn we did see could not be attributed to any one pile.
	 *
	 * THE SESSION IS ALSO MARKED UNPROVABLE, unconditionally. Nothing here observed the pile leave;
	 * it observed that the pile is no longer there. That is enough to stop recording and it is not
	 * enough to claim the clip covers the whole handover, so COMPLETE must stay out of reach. This
	 * also makes a WRONG scene read safe in the only direction that matters: a spurious release can
	 * shorten a recording, and it can never manufacture a COMPLETE.
	 */
	public void pileGoneFromScene(String pileKey, long nowMillis)
	{
		if (sessionId == null || pileKey == null)
		{
			return;
		}
		if (!activePiles.remove(pileKey))
		{
			return;
		}
		unprovable = true;
		if (reason.equals(REASON_NONE))
		{
			reason = REASON_PILE_SCENE_GONE;
		}
		maybeArmStop(nowMillis);
	}

	/**
	 * Advance the clock: expire any pending drop past its deadline, then arm the tail if nothing is
	 * left outstanding.
	 *
	 * THE CALLER MUST RUN THIS ON A TIMER, once per tick. It is the only thing that can end a
	 * session whose drops never produced a pile, and without it case 13 — recording with zero piles
	 * and zero pendings — is reachable again.
	 *
	 * @return the sequence numbers that expired on this call, so the caller can drop their bookkeeping.
	 */
	public List<Integer> settle(long nowMillis)
	{
		List<Integer> expired = new ArrayList<>();
		if (sessionId == null)
		{
			return expired;
		}
		Iterator<Map.Entry<Integer, Long>> it = pendingDrops.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<Integer, Long> e = it.next();
			if (nowMillis >= e.getValue())
			{
				expired.add(e.getKey());
				it.remove();
			}
		}
		if (!expired.isEmpty())
		{
			// An expired pending is a drop nobody ever saw land. The clip may still show it, but the
			// session cannot PROVE it did, so COMPLETE is off the table from here.
			unprovable = true;
			if (reason.equals(REASON_NONE))
			{
				reason = REASON_PENDING_EXPIRED;
			}
		}
		maybeArmStop(nowMillis);
		return expired;
	}

	/**
	 * THE STRUCTURAL BACKSTOP. Two bounds that do not care HOW the state went wrong.
	 *
	 * ROUND 5. Every immortal recorder found so far had the same shape and a different cause: the
	 * recorder was waiting on something the caller could no longer produce. The end paths were
	 * enumerated correctly each time, and each time a new ENTRY route for stale state was found.
	 * Entry routes are an open set, so this check does not try to name them. It asks one question
	 * every poll: is this session still waiting on anything that can actually arrive?
	 *
	 *   BOUND 1, the invariant. The caller holds no live pile for this session and nothing is
	 *   pending. Nothing can ever release a key the recorder still holds, and no removal can arrive.
	 *   A healthy session in that state arms its tail and ends within TAIL_MILLIS, so being in it
	 *   for ORPHANED_STATE_GRACE_MILLIS means the ordinary lifecycle has failed.
	 *
	 *   BOUND 2, the hard cap. MAX_SESSION_MILLIS since the session started, whatever its state.
	 *
	 * Both end the session as INTERRUPTED. A bound firing is the opposite of proven coverage, and
	 * the manifest names which bound in outcome_reason.
	 *
	 * @param callerHoldsOwnedPile whether the CALLER still tracks a ground pile owned by this
	 *                             session. The recorder cannot know this: it holds keys, the caller
	 *                             holds the piles those keys stand for, and the whole defect class
	 *                             is the two disagreeing.
	 * @return true when a bound fired and the session is now due to stop.
	 */
	public boolean enforceBackstops(long nowMillis, boolean callerHoldsOwnedPile)
	{
		if (sessionId == null)
		{
			return false;
		}
		if (nowMillis - startedAtMillis >= MAX_SESSION_MILLIS)
		{
			backstopReason = REASON_MAX_DURATION;
			interrupt();
			return true;
		}
		if (callerHoldsOwnedPile || !pendingDrops.isEmpty())
		{
			orphanedSinceMillis = NO_STOP;		// healthy again: the grace never accumulates
			return false;
		}
		if (orphanedSinceMillis == NO_STOP)
		{
			orphanedSinceMillis = nowMillis;
			return false;
		}
		if (nowMillis - orphanedSinceMillis >= ORPHANED_STATE_GRACE_MILLIS)
		{
			backstopReason = REASON_ORPHANED_STATE;
			interrupt();
			return true;
		}
		return false;
	}

	/**
	 * Arm the tail when, and only when, nothing is outstanding and no stop is armed already.
	 *
	 * Guarding on {@code stopAtMillis == NO_STOP} keeps an already-armed deadline from sliding
	 * forward every tick, which would be a second way to record forever.
	 */
	private void maybeArmStop(long nowMillis)
	{
		if (sessionId == null || stopAtMillis != NO_STOP)
		{
			return;
		}
		if (activePiles.isEmpty() && pendingDrops.isEmpty())
		{
			stopAtMillis = nowMillis + TAIL_MILLIS;
		}
	}

	/**
	 * Has the armed tail elapsed?
	 *
	 * Note the {@code >=}: a caller polling on a tick boundary can land exactly on the deadline, and
	 * a strict {@code >} there would wait a whole extra tick for no reason.
	 */
	public boolean shouldStop(long nowMillis)
	{
		return stopAtMillis != NO_STOP && nowMillis >= stopAtMillis;
	}

	/**
	 * Milliseconds left on the tail, or -1 when no stop is armed. Reporting only.
	 *
	 * Clamped at 0 so an overdue stop reads as "due now" rather than as a negative duration.
	 */
	public long tailRemainingMillis(long nowMillis)
	{
		if (stopAtMillis == NO_STOP)
		{
			return -1L;
		}
		return Math.max(0L, stopAtMillis - nowMillis);
	}

	/**
	 * A hop, logout, disconnect, scene reload or withdrawn grant happened. The session ends as
	 * INTERRUPTED.
	 *
	 * The captured frames are NOT discarded by this call: an interrupted drop trade is exactly the
	 * case somebody will need to look at, and throwing the footage away because the session did not
	 * end tidily is how evidence disappears. The flag only changes the LABEL the clip carries.
	 * Whether the frames are uploaded is the caller's decision, and a withdrawn upload consent is
	 * the one case where the caller discards them.
	 */
	public void interrupt()
	{
		if (sessionId == null)
		{
			return;
		}
		interrupted = true;
		unprovable = true;
		stopAtMillis = 0L;	// due immediately — the caller's next poll stops it
	}

	/**
	 * End the session and return how it ended. Idempotent: a second call on an idle recorder
	 * returns COMPLETE and changes nothing.
	 *
	 * COMPLETE REQUIRES PROOF, and there are four ways to lose it: an explicit interrupt, a pile
	 * still live, a drop still pending, and the unprovable flag an expired pending or an abandoned
	 * pile sets. Any of them means the clip is not known to cover the whole trade, and a manifest
	 * that said COMPLETE anyway would be a false statement about evidence.
	 */
	public Outcome finish()
	{
		boolean proven = !interrupted
			&& !unprovable
			&& activePiles.isEmpty()
			&& pendingDrops.isEmpty();
		Outcome outcome = proven ? Outcome.COMPLETE : Outcome.INTERRUPTED;
		sessionId = null;
		stopAtMillis = NO_STOP;
		interrupted = false;
		unprovable = false;
		reason = REASON_NONE;
		backstopReason = null;
		orphanedSinceMillis = NO_STOP;
		activePiles.clear();
		pendingDrops.clear();
		nextSeq = 0;
		dropCount = 0;
		startedAtMillis = 0L;
		return outcome;
	}

	/**
	 * The stable key for one pile: item, tile and the sequence number of the drop that made it.
	 *
	 * The sequence number is what makes two piles of the SAME item on the SAME tile distinguishable
	 * when the game really does hold two piles. When the game MERGES them into one — dropping a
	 * stackable onto an existing stack — the caller must not mint a second key at all; see
	 * {@link #pendingDropResolved(int)}.
	 */
	public static String pileKey(int item, int x, int y, int plane, int seq)
	{
		return item + ":" + x + ":" + y + ":" + plane + ":" + seq;
	}
}

package com.osrsbestinslot.export;

import java.util.*;

/** Per-client observation context, not a stable game session/order identifier. */
final class EventObservationContext
{
    static final Set<String> MODES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        "NORMAL", "IRONMAN", "ULTIMATE_IRONMAN", "HARDCORE_IRONMAN", "GROUP_IRONMAN",
        "HARDCORE_GROUP_IRONMAN", "UNRANKED_GROUP_IRONMAN")));
    private String owner, session, mode;
    private long sequence, observedAt;
    private Integer tick;

    synchronized void clear() { owner = session = mode = null; sequence = observedAt = 0; tick = null; }
    private void bind(String identity)
    {
        if (!Objects.equals(owner, identity))
        {
            clear(); owner = identity; session = EventSpool.newEventId();
        }
    }
    synchronized void observe(String identity, String accountMode, int gameTick, long now)
    {
        if (identity == null) { clear(); return; }
        bind(identity);
        mode = MODES.contains(accountMode) ? accountMode : null;
        tick = gameTick >= 0 ? gameTick : null;
        observedAt = now;
    }
    synchronized Map<String,Object> event(String identity, String version, long now)
    {
        if (identity == null) return null;
        bind(identity);
        Map<String,Object> out = new LinkedHashMap<>();
        out.put("schema_v", 1); out.put("collector_session", session); out.put("sequence", ++sequence);
        out.put("plugin_version", version); out.put("source", "public_event_emitter");
        boolean fresh = observedAt > 0 && now >= observedAt && now - observedAt <= 10_000;
        out.put("context_status", fresh ? "observed_client_tick" : "unknown_or_stale");
        out.put("context_observed_at_ms", fresh ? observedAt : null);
        out.put("context_tick", fresh ? tick : null);
        out.put("account_mode", fresh ? mode : null);
        out.put("account_mode_source", fresh && mode != null ? "varbit_1777" : null);
        return out;
    }

    /** Strict nested replay projection: no raw profile ID, token, account name or free text. */
    static Map<String,Object> project(Object input)
    {
        Map<String,Object> out = new LinkedHashMap<>();
        if (!(input instanceof Map)) return out;
        Map<?,?> m = (Map<?,?>)input;
        for (String key : Arrays.asList("schema_v", "sequence", "context_observed_at_ms", "context_tick"))
        {
            Object v = m.get(key);
            if (v == null || v instanceof Number && Double.isFinite(((Number)v).doubleValue())
                && ((Number)v).doubleValue() >= 0 && ((Number)v).doubleValue() <= 9007199254740991D
                && ((Number)v).doubleValue() == ((Number)v).longValue()) out.put(key,v);
        }
        Object s = m.get("collector_session"), v = m.get("plugin_version"), mode = m.get("account_mode");
        if (s instanceof String && ((String)s).matches("[a-f0-9]{32}")) out.put("collector_session",s);
        if (v instanceof String && ((String)v).matches("[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}")) out.put("plugin_version",v);
        if (mode == null || MODES.contains(mode)) out.put("account_mode",mode);
        if ("public_event_emitter".equals(m.get("source"))) out.put("source",m.get("source"));
        if ("observed_client_tick".equals(m.get("context_status")) || "unknown_or_stale".equals(m.get("context_status")))
            out.put("context_status",m.get("context_status"));
        if (m.get("account_mode_source") == null || "varbit_1777".equals(m.get("account_mode_source")))
            out.put("account_mode_source",m.get("account_mode_source"));
        return out;
    }
}

/*
 * OSRS Best in Slot — event priority classes for the in-memory queue.
 *
 * A pure helper: no RuneLite types, no network. The pending buffer holds at most MAX_PENDING_EVENTS rows.
 * When it overflows, the plugin used to drop the OLDEST row whatever its type, so a long 429 run could
 * throw away a Grand Exchange completion to keep a region crossing. Overflow now drops the oldest row of
 * the LOWEST class present, so money and session rows survive as long as any lower row can go instead.
 *
 *   P0  ge_*, trade, store_*, death, login, logout   money movements and session edges
 *   P1  loot, drop, pickup, alch, ground_removed, level_up, kill_count, pet, bank_session, bank_visit_*
 *   P2  everything else (region, equip_change, xp_gain, world_hop, fh_batch, ...)
 *
 * Order inside the buffer is never changed: a row is removed, the others keep their positions.
 */
package com.osrsbestinslot.export;

import java.util.List;
import java.util.Map;

final class EventPriority
{
	static final int P0 = 0;
	static final int P1 = 1;
	static final int P2 = 2;

	private EventPriority()
	{
	}

	static int classOf(String type)
	{
		if (type == null)
		{
			return P2;
		}
		if (type.startsWith("ge_") || type.startsWith("store_") || type.equals("trade") || type.equals("death")
			|| type.equals("login") || type.equals("logout"))
		{
			return P0;
		}
		if (type.equals("loot") || type.equals("drop") || type.equals("pickup") || type.equals("alch")
			|| type.equals("ground_removed") || type.equals("level_up") || type.equals("kill_count")
			|| type.equals("pet") || type.equals("bank_session") || type.startsWith("bank_visit_")
			|| type.startsWith("drop_trade_clip"))
		{
			return P1;
		}
		return P2;
	}

	/** Index of the row overflow should drop: the oldest row of the lowest class present. -1 when empty. */
	static int evictIndex(List<Map<String, Object>> pending)
	{
		int best = -1;
		int bestClass = -1;
		for (int i = 0; i < pending.size(); i++)
		{
			Object t = pending.get(i).get("type");
			int c = classOf(t == null ? null : String.valueOf(t));
			if (c > bestClass)
			{
				bestClass = c;
				best = i;
				if (c == P2)
				{
					break;	// the first P2 row is the oldest of the lowest possible class
				}
			}
		}
		return best;
	}
}

package com.osrsbestinslot.export;

import com.google.gson.*;
import java.util.*;

/** Public queue-v1 receipts. A receipt proves durable ownership, not a market fill. */
final class EventQueueProtocol
{
    private EventQueueProtocol() {}
    private static final Set<String> GE = new HashSet<>(Arrays.asList(
        "ge_offer", "ge_progress", "ge_buy", "ge_sell", "ge_cancel", "ge_collect"));
    private static final Set<String> HISTORY = new HashSet<>(Arrays.asList(
        "bank_session",
        "equip_change", "loot", "kill_count", "level_up", "xp_gain", "alch", "pickup"));
    static boolean allows(String scope, Map<String,Object> event)
    {
        Object id = event.get("event_id");
        boolean signals = "own-signals-v1".equals(scope), vars = signals || "own-vars-v1".equals(scope), states = vars || "own-state-v1".equals(scope), combat = states || "own-combat-v1".equals(scope);
        return id instanceof String && ((String) id).matches("[a-f0-9]{32}")
            && ((combat || "ge-v1".equals(scope) || "own-history-v1".equals(scope)) && GE.contains(event.get("type"))
                || (combat || "own-history-v1".equals(scope)) && HISTORY.contains(event.get("type"))
                || combat && ("combat_hit".equals(event.get("type")) || "combat_npc_end".equals(event.get("type")))
                || states && "own_state".equals(event.get("type"))
                || vars && "own_vars".equals(event.get("type"))
                || signals && "own_signal".equals(event.get("type")));
    }
    enum Outcome { RETRY, DURABLE, ERASED, REJECTED }
    enum Stage { NONE, BROKER, ARCHIVE }
    static final class ReceiptSet
    {
        final List<Outcome> outcomes;
        final List<Stage> stages;
        ReceiptSet(int size)
        {
            outcomes = new ArrayList<>(Collections.nCopies(size, Outcome.RETRY));
            stages = new ArrayList<>(Collections.nCopies(size, Stage.NONE));
        }
        static ReceiptSet rejected(int size)
        {
            ReceiptSet r = new ReceiptSet(size); Collections.fill(r.outcomes, Outcome.REJECTED); return r;
        }
    }

    static boolean terminalError(int status, String body)
    {
        // Provider404/timeout/rate-limit and HTML answers stay retryable. A parsed
        // application4xx rejection is a loss, never a durable acknowledgement.
        if (status < 400 || status >= 500 || status == 404 || status == 408 || status == 429) return false;
        try {
            String error = string(new JsonParser().parse(body).getAsJsonObject(), "error");
            return error != null && !error.isEmpty();
        } catch (RuntimeException ignored) { return false; }
    }

    static List<Outcome> receipts(String body, List<Map<String,Object>> batch)
    {
        return parseReceipts(body, batch).outcomes;
    }

    static ReceiptSet parseReceipts(String body, List<Map<String,Object>> batch)
    {
        ReceiptSet parsed = new ReceiptSet(batch.size()); List<Outcome> out = parsed.outcomes;
        try
        {
            JsonObject root = new JsonParser().parse(body).getAsJsonObject();
            if (!root.has("receipt_version") || !"1".equals(root.get("receipt_version").toString())) return parsed;
            JsonArray rows = root.getAsJsonArray("results");
            Set<Integer> seen = new HashSet<>();
            for (JsonElement element : rows)
            {
                JsonObject row = element.getAsJsonObject();
                JsonElement rawIndex = row.get("index");
                if (rawIndex == null || !rawIndex.isJsonPrimitive() || !rawIndex.getAsJsonPrimitive().isNumber()) continue;
                int i = rawIndex.getAsInt();
                if (i < 0 || i >= batch.size() || !Integer.toString(i).equals(rawIndex.toString())) continue;
                // Duplicate/contradictory rows invalidate the response; no ambiguous event is settled.
                if (!seen.add(i)) return new ReceiptSet(batch.size());
                if (!Objects.equals(batch.get(i).get("event_id"), string(row, "event_id"))) continue;
                String status = string(row, "status");
                if ("queued".equals(status) && flag(row, "broker_ack")
                    || "stored".equals(status) && flag(row, "archive_receipt") && flag(row, "d1_receipt"))
                {
                    out.set(i, Outcome.DURABLE);
                    parsed.stages.set(i, "queued".equals(status) ? Stage.BROKER : Stage.ARCHIVE);
                }
                else if ("rejected".equals(status) && string(row, "reason") != null && !string(row, "reason").isEmpty())
                    out.set(i, "erased".equals(string(row, "reason")) ? Outcome.ERASED : Outcome.REJECTED);
            }
        }
        catch (RuntimeException ignored)
        {
            // A malformed/HTML/truncated answer is not permission to discard any memory event.
            return new ReceiptSet(batch.size());
        }
        return parsed;
    }
    private static String string(JsonObject row, String key)
    {
        JsonElement v = row.get(key);
        return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isString() ? v.getAsString() : null;
    }
    private static boolean flag(JsonObject row, String key)
    {
        JsonElement v = row.get(key);
        return v != null && v.isJsonPrimitive() && v.getAsJsonPrimitive().isBoolean() && v.getAsBoolean();
    }
}

/*
 * OSRS Best in Slot — durable structured-event spool (staff only, server-granted).
 *
 * A pure file library: no RuneLite types, no network. The plugin drives it from ONE dedicated
 * single-thread writer, so an instance is confined to that thread and needs no locking of its own.
 * File locks are for OTHER processes (two RuneLite clients on one OS user), not for threads.
 *
 * LAYOUT. <plugin-data>/osrsbis/spool/<identity>/ where identity = first 32 hex of
 * sha256("spool-identity:" + token + ":" + accountHash). The token itself is never written anywhere:
 * not in a file, not in a file name, not in a directory name. Per process instance:
 *   shard-<16 hex>.spl       the shard: [magic "OBSP"][format u16] then records [len u32][crc32 u32][UTF-8 JSON]
 *   shard-<16 hex>.spl.next  compaction output, ATOMIC_MOVEd over the shard, never merged with it
 *   shard-<16 hex>.lock      held with an exclusive FileLock while the writer lives
 *   recovery.lock            taken while a process reads or deletes shards it does not own
 *   purge-requested          {"v":1,"requested_ms":N}: the identity was purged while a shard was still live
 *   quarantine.jsonl         terminal metadata only (event_id, type, created_ms, status), never event content
 * and one non-secret pointer <plugin-data>/osrsbis/spool/active.json naming the last granted identity.
 *
 * RECORD KINDS (payload JSON, fixed layout written and read here only):
 *   {"v":1,"k":"ev","id":"<32 hex>","c":<created ms>,"t":"<type>","e":<wire event JSON, byte-exact>}
 *   {"v":1,"k":"ack","ids":["<32 hex>",...]}   tombstone: the ids are no longer pending (acked, dropped
 *                                                by a bound, or quarantined). Acks are tombstones in the
 *                                                same file; compaction later removes both rows.
 *   {"v":1,"k":"end","n":<count>}               last record of a compaction output; a .next without a
 *                                                matching end record is not a complete generation.
 *
 * RECOVERY RULES. A torn or CRC-bad TAIL is cut off (the valid prefix is kept). A bad record that is
 * followed by ANY valid record is middle corruption: the whole file is renamed .corrupt, counted, and
 * never replayed. With both .spl and .next present the .next wins only if it is a complete, clean
 * generation; otherwise it is discarded. The two are never merged, so an acked row cannot come back.
 */
package com.osrsbestinslot.export;

import java.io.IOException;
import java.io.StringReader;
import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.channels.OverlappingFileLockException;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.FileAlreadyExistsException;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.OpenOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.FileAttribute;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.zip.CRC32;

final class EventSpool
{
	static final byte[] MAGIC = {'O', 'B', 'S', 'P'};
	static final int FORMAT = 1;
	static final int HEADER = 6;
	static final long MAX_AGE_MS = 48L * 3600_000L;
	/** A frame longer than this is not one of ours: the length field itself is damaged. */
	static final int MAX_FRAME_PAYLOAD = 4 * 1024 * 1024;
	static final long COMPACT_DEAD_BYTES = 1024L * 1024L;
	static final long COMPACT_RETRY_MS = 60_000L;
	static final String MARKER = "purge-requested";
	static final String POINTER = "active.json";
	static final String RECOVERY_LOCK = "recovery.lock";
	static final String QUARANTINE = "quarantine.jsonl";
	/**
	 * Owner-only permissions apply only where the file system has a POSIX view. On Windows this is
	 * false and the files inherit the user profile's ACL: plaintext, readable by that OS user.
	 */
	static final boolean POSIX = FileSystems.getDefault().supportedFileAttributeViews().contains("posix");

	private static final SecureRandom RANDOM = new SecureRandom();
	private static final Pattern HEX32 = Pattern.compile("^[0-9a-f]{32}$");
	private static final Pattern TYPE = Pattern.compile("^[a-z0-9_]{1,32}$");
	private static final Pattern EV_HEAD = Pattern.compile(
		"^\\{\"v\":1,\"k\":\"ev\",\"id\":\"([0-9a-f]{32})\",\"c\":(\\d{1,19}),\"t\":\"([a-z0-9_]{1,32})\",\"e\":");
	private static final Pattern ACK = Pattern.compile(
		"^\\{\"v\":1,\"k\":\"ack\",\"ids\":\\[(\"[0-9a-f]{32}\"(,\"[0-9a-f]{32}\")*)?\\]\\}$");
	private static final Pattern END = Pattern.compile("^\\{\"v\":1,\"k\":\"end\",\"n\":(\\d{1,9})\\}$");
	private static final Pattern ID_IN = Pattern.compile("\"([0-9a-f]{32})\"");
	private static final Pattern SHARD_NAME = Pattern.compile("^shard-([0-9a-f]{16})\\.(spl|spl\\.next|lock|corrupt)$");
	private static final Pattern INDEX_BODY = Pattern.compile(
		"^\\{\"v\":2,\"identities\":\\[(\\{\"identity\":\"[0-9a-f]{32}\",\"updated_ms\":\\d{1,19}\\}"
			+ "(,\\{\"identity\":\"[0-9a-f]{32}\",\"updated_ms\":\\d{1,19}\\}){0,15})\\]\\}$");
	private static final Pattern INDEX_ENTRY = Pattern.compile(
		"\\{\"identity\":\"([0-9a-f]{32})\",\"updated_ms\":(\\d{1,19})\\}");
	static final String INDEX_LOCK = "index.lock";

	/** The compaction rename. Production is ATOMIC_MOVE only; there is no in-place fallback. */
	interface Mover
	{
		void move(Path from, Path to) throws IOException;
	}

	static final Mover ATOMIC = (from, to) -> Files.move(from, to, StandardCopyOption.ATOMIC_MOVE);

	static final class Limits
	{
		static final Limits DEFAULT = new Limits(5L * 1024 * 1024, 5000, MAX_AGE_MS);
		final long maxBytes;
		final int maxRecords;
		final long maxAgeMs;

		Limits(long maxBytes, int maxRecords, long maxAgeMs)
		{
			this.maxBytes = maxBytes;
			this.maxRecords = maxRecords;
			this.maxAgeMs = maxAgeMs;
		}
	}

	/** Cumulative, content-free counters. Shared by every spool instance of one plugin process. */
	static final class Counters
	{
		final AtomicLong corrupt = new AtomicLong();
		final AtomicLong dropped = new AtomicLong();
		final AtomicLong compactionFailed = new AtomicLong();
		final AtomicLong purged = new AtomicLong();
		final AtomicLong quarantined = new AtomicLong();
		final AtomicLong filtered = new AtomicLong();
		final AtomicLong acked = new AtomicLong();
		final AtomicLong replayed = new AtomicLong();
		final AtomicLong unacked2xx = new AtomicLong();
		final AtomicLong appendFailed = new AtomicLong();
		final AtomicLong reopenFailed = new AtomicLong();
		final AtomicLong gateTimeout = new AtomicLong();
		final AtomicLong replayAgedAtDispatch = new AtomicLong();
		final AtomicLong lastAckMs = new AtomicLong();
	}

	static final class Record
	{
		final String eventId;
		final String type;
		final String eventJson;
		final long createdMs;
		final boolean recovered;
		final int payloadBytes;

		Record(String eventId, String type, String eventJson, long createdMs, boolean recovered)
		{
			this.eventId = eventId;
			this.type = type;
			this.eventJson = eventJson;
			this.createdMs = createdMs;
			this.recovered = recovered;
			this.payloadBytes = eventJson.getBytes(StandardCharsets.UTF_8).length;
		}
	}

	enum ScanStatus
	{
		CLEAN, TORN_TAIL, CORRUPT
	}

	static final class Scan
	{
		ScanStatus status;
		long validEnd;
		final List<String> payloads = new ArrayList<>();
	}

	/** One shard generation after its tombstones are applied. */
	static final class Gen
	{
		boolean corrupt;
		final LinkedHashMap<String, Record> live = new LinkedHashMap<>();
		long newestCreated = -1L;
	}

	private final Path pluginData;
	private final Path dir;
	private final LongSupplier clock;
	private final Mover mover;
	private final Limits limits;
	private final Counters counters;
	private final String shardId;

	private FileChannel ch;
	private Locked ownLock;
	private boolean closed;
	private long fileBytes;
	private long overheadBytes;
	private long liveFrameBytes;
	private long payloadBytes;
	private long noCompactBeforeMs;
	private LinkedHashMap<String, Record> pending = new LinkedHashMap<>();

	/** Creates nothing on disk. The directory and the shard appear only at the first durable write. */
	EventSpool(Path pluginData, Path dir, LongSupplier clock, Mover mover, Limits limits, Counters counters)
	{
		this.pluginData = pluginData;
		this.dir = dir;
		this.clock = clock;
		this.mover = mover;
		this.limits = limits;
		this.counters = counters;
		byte[] b = new byte[8];
		RANDOM.nextBytes(b);
		this.shardId = hex(b);
	}

	// ------------------------------------------------------------------ identity

	static String identityKey(String token, String accountHash)
	{
		return sha256Hex("spool-identity:" + token + ":" + accountHash).substring(0, 32);
	}

	static String newEventId()
	{
		byte[] b = new byte[16];
		RANDOM.nextBytes(b);
		return hex(b);
	}

	// ------------------------------------------------------------------ accessors

	Path shardFile()
	{
		return dir.resolve("shard-" + shardId + ".spl");
	}

	String shardId()
	{
		return shardId;
	}

	Path dir()
	{
		return dir;
	}

	Counters counters()
	{
		return counters;
	}

	boolean isOpen()
	{
		return ch != null;
	}

	boolean purgeRequested()
	{
		return Files.exists(dir.resolve(MARKER));
	}

	List<Record> pending()
	{
		return new ArrayList<>(pending.values());
	}

	int pendingCount()
	{
		return pending.size();
	}

	long pendingPayloadBytes()
	{
		return payloadBytes;
	}

	long oldestCreatedMs()
	{
		long oldest = -1L;
		for (Record r : pending.values())
		{
			if (oldest < 0 || r.createdMs < oldest)
			{
				oldest = r.createdMs;
			}
		}
		return oldest;
	}

	Record get(String eventId)
	{
		return pending.get(eventId);
	}

	// ------------------------------------------------------------------ write path

	/**
	 * Append one event durably. True only once the record is forced to disk. False when this spool is
	 * closed or its directory carries a purge marker; nothing is written then.
	 */
	boolean append(String eventId, String type, long createdMs, String eventJson) throws IOException
	{
		if (closed || failed || purgeRequested())
		{
			return false;
		}
		if (eventId == null || !HEX32.matcher(eventId).matches() || type == null || !TYPE.matcher(type).matches()
			|| eventJson == null || !isJsonObject(eventJson))
		{
			return false;
		}
		if (pending.containsKey(eventId))
		{
			return true;
		}
		Record r = new Record(eventId, type, eventJson, createdMs, false);
		ensureOpen();
		writeFrames(java.util.Collections.singletonList(evPayload(r)));
		put(pending, r);
		enforceBounds();
		return true;
	}

	/** Tombstone the listed ids that are still pending. Returns how many were removed. */
	int ack(Collection<String> eventIds) throws IOException
	{
		List<String> hit = new ArrayList<>();
		for (String id : eventIds)
		{
			if (id != null && pending.containsKey(id) && !hit.contains(id))
			{
				hit.add(id);
			}
		}
		tombstone(hit);
		return hit.size();
	}

	/**
	 * Terminal quarantine: keep non-sensitive metadata only, then tombstone the rows. Bounded by the
	 * same record and byte caps as the spool, oldest lines dropped first.
	 */
	int quarantine(Collection<String> eventIds, int statusCode) throws IOException
	{
		List<String> hit = new ArrayList<>();
		StringBuilder lines = new StringBuilder();
		for (String id : eventIds)
		{
			Record r = id == null ? null : pending.get(id);
			if (r == null || hit.contains(id))
			{
				continue;
			}
			hit.add(id);
			lines.append("{\"event_id\":\"").append(r.eventId).append("\",\"type\":\"").append(r.type)
				.append("\",\"created_ms\":").append(r.createdMs).append(",\"status\":").append(statusCode).append("}\n");
		}
		if (hit.isEmpty())
		{
			return 0;
		}
		Path q = dir.resolve(QUARANTINE);
		try (FileChannel qc = open(q, StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND))
		{
			writeFully(qc, ByteBuffer.wrap(lines.toString().getBytes(StandardCharsets.UTF_8)), -1L);
			qc.force(false);
		}
		boundQuarantine(q);
		tombstone(hit);
		counters.quarantined.addAndGet(hit.size());
		return hit.size();
	}

	private void boundQuarantine(Path q) throws IOException
	{
		List<String> all = Files.readAllLines(q, StandardCharsets.UTF_8);
		long bytes = Files.size(q);
		if (all.size() <= limits.maxRecords && bytes <= limits.maxBytes)
		{
			return;
		}
		int from = Math.max(0, all.size() - limits.maxRecords);
		long kept = 0;
		for (int i = all.size() - 1; i >= from; i--)
		{
			kept += all.get(i).getBytes(StandardCharsets.UTF_8).length + 1;
			if (kept > limits.maxBytes)
			{
				from = i + 1;
				break;
			}
		}
		StringBuilder sb = new StringBuilder();
		for (String l : all.subList(from, all.size()))
		{
			sb.append(l).append('\n');
		}
		Path tmp = dir.resolve(QUARANTINE + ".next");
		try (FileChannel t = open(tmp, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
		{
			writeFully(t, ByteBuffer.wrap(sb.toString().getBytes(StandardCharsets.UTF_8)), 0L);
			t.force(true);
		}
		try
		{
			mover.move(tmp, q);
		}
		catch (IOException e)
		{
			Files.deleteIfExists(tmp);	// fail closed: the old, longer file stays
		}
	}

	/** Compact when acked bytes exceed a quarter of the file or 1 MiB. Called by the owner's tick. */
	void maybeCompact() throws IOException
	{
		if (ch == null || closed)
		{
			return;
		}
		long dead = fileBytes - overheadBytes - liveFrameBytes;
		if (dead <= 0 || clock.getAsLong() < noCompactBeforeMs)
		{
			return;
		}
		if (dead * 4 > fileBytes || dead > COMPACT_DEAD_BYTES)
		{
			if (!compactNow())
			{
				noCompactBeforeMs = clock.getAsLong() + COMPACT_RETRY_MS;
			}
		}
	}

	/**
	 * Rewrite the live rows to .next, force it, ATOMIC_MOVE it over the shard and force the directory.
	 * If the move is refused the old shard is kept exactly as it was (fail closed) and false is returned.
	 */
	boolean compactNow() throws IOException
	{
		if (ch == null || closed)
		{
			return true;
		}
		Path next = dir.resolve("shard-" + shardId + ".spl.next");
		List<String> payloads = new ArrayList<>();
		for (Record r : pending.values())
		{
			payloads.add(evPayload(r));
		}
		String end = "{\"v\":1,\"k\":\"end\",\"n\":" + payloads.size() + "}";
		try (FileChannel n = open(next, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
		{
			long pos = 0;
			pos += writeFully(n, ByteBuffer.wrap(header()), pos);
			for (String p : payloads)
			{
				pos += writeFully(n, ByteBuffer.wrap(frame(p)), pos);
			}
			writeFully(n, ByteBuffer.wrap(frame(end)), pos);
			n.force(true);
		}
		catch (IOException e)
		{
			Files.deleteIfExists(next);
			counters.compactionFailed.incrementAndGet();
			return false;
		}
		// Close OUR handle on the shard before it is replaced: Windows refuses to rename over a file that
		// is open. The shard lock file stays held the whole time, so no other process can take the shard
		// while no handle is open, and only this writer thread ever touches it.
		ch.close();
		ch = null;
		boolean moved;
		try
		{
			mover.move(next, shardFile());
			moved = true;
		}
		catch (IOException e)
		{
			Files.deleteIfExists(next);
			counters.compactionFailed.incrementAndGet();
			moved = false;	// fail closed: the old generation stays exactly as it was
		}
		if (moved)
		{
			forceDir(dir);
		}
		try
		{
			ch = reopener.reopen(shardFile());
		}
		catch (IOException | RuntimeException e)
		{
			// The data is safe on disk (old or new generation), but this writer can no longer append.
			// Fail closed: stop taking rows; the next process recovers the shard once our lock is gone.
			failed = true;
			counters.reopenFailed.incrementAndGet();
			throw e instanceof IOException ? (IOException) e : new IOException(e);
		}
		if (!moved)
		{
			return false;
		}
		fileBytes = ch.size();
		overheadBytes = HEADER + frame(end).length;
		liveFrameBytes = fileBytes - overheadBytes;
		return true;
	}

	/** How the shard is reopened after a compaction. Production opens it read/write. */
	interface Reopener
	{
		FileChannel reopen(Path shard) throws IOException;
	}

	private Reopener reopener = p -> FileChannel.open(p, StandardOpenOption.READ, StandardOpenOption.WRITE);
	private boolean failed;

	void setReopenerForTest(Reopener r)
	{
		reopener = r;
	}

	/** True once this writer can no longer append (a reopen failed). It takes no rows after that. */
	boolean isFailed()
	{
		return failed;
	}

	// ------------------------------------------------------------------ recovery

	/**
	 * Merge abandoned shards of THIS identity directory into this process. A shard whose lock is held
	 * belongs to a live writer and is never read. A marked directory is never replayed from. Recovered
	 * rows are re-written into this process's own shard (forced) before their source file is deleted,
	 * and they go ahead of rows this process generated itself. Returns the number of rows merged.
	 */
	int recover() throws IOException
	{
		if (closed || !Files.isDirectory(dir) || purgeRequested())
		{
			return 0;
		}
		Locked rl = lock(dir.resolve(RECOVERY_LOCK));
		if (rl == null)
		{
			return 0;
		}
		LinkedHashMap<String, Record> merged = new LinkedHashMap<>();
		try
		{
			long cutoff = clock.getAsLong() - limits.maxAgeMs;
			for (String sid : shardIds(dir))
			{
				if (sid.equals(shardId))
				{
					continue;
				}
				Locked sl = lockOther(dir, sid);
				if (sl == null)
				{
					continue;	// a live writer: never touch it
				}
				try
				{
					Gen g = load(dir, sid);
					if (g.corrupt)
					{
						quarantineCorrupt(dir, sid, counters);
						continue;
					}
					List<Record> add = new ArrayList<>();
					for (Record r : g.live.values())
					{
						if (r.createdMs < cutoff)
						{
							counters.dropped.incrementAndGet();
						}
						else if (!pending.containsKey(r.eventId) && !merged.containsKey(r.eventId))
						{
							add.add(new Record(r.eventId, r.type, r.eventJson, r.createdMs, true));
						}
					}
					if (!add.isEmpty())
					{
						ensureOpen();
						List<String> payloads = new ArrayList<>();
						for (Record r : add)
						{
							payloads.add(evPayload(r));
						}
						writeFrames(payloads);
						for (Record r : add)
						{
							merged.put(r.eventId, r);
						}
					}
					Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl"));
					Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl.next"));
					forceDir(dir);
				}
				finally
				{
					sl.releaseAndDelete();
				}
			}
		}
		finally
		{
			rl.close();
		}
		if (!merged.isEmpty())
		{
			LinkedHashMap<String, Record> reordered = new LinkedHashMap<>();
			for (Record r : merged.values())
			{
				reordered.put(r.eventId, r);
			}
			for (Record r : pending.values())
			{
				reordered.put(r.eventId, r);
			}
			pending = reordered;
			for (Record r : merged.values())
			{
				payloadBytes += r.payloadBytes;
				liveFrameBytes += frame(evPayload(r)).length;
			}
			enforceBounds();
		}
		return merged.size();
	}

	// ------------------------------------------------------------------ shutdown + purge

	/**
	 * Graceful close: rows stay on disk for the next process. EXCEPT in a marked directory: the identity
	 * was purged while we held the shard, so our shard is deleted too and, when no other live shard is
	 * left, the purge is finished (marker and directory gone). Nothing of a purged identity survives a close.
	 */
	void close()
	{
		if (!closed && purgeRequested())
		{
			closeAndDeleteOwn();
			try
			{
				purgeIfIdle(dir);
			}
			catch (IOException ignored)
			{
				// the sweep finishes it later
			}
			return;
		}
		closed = true;
		closeQuietly();
	}

	/** Process death: drop channels and the lock, write nothing else. */
	void crashForTest()
	{
		closed = true;
		closeQuietly();
	}

	/** Stop, and delete this process's own shard and lock. Other shards are not touched. */
	void closeAndDeleteOwn()
	{
		closed = true;
		closeQuietly();
		try
		{
			Files.deleteIfExists(shardFile());
			Files.deleteIfExists(dir.resolve("shard-" + shardId + ".spl.next"));
			Files.deleteIfExists(lockPath(dir, shardId));
		}
		catch (IOException ignored)
		{
			// best effort; the age-out sweep removes anything left behind
		}
		pending.clear();
		payloadBytes = 0;
	}

	private void closeQuietly()
	{
		try
		{
			if (ch != null)
			{
				ch.close();
			}
		}
		catch (IOException ignored)
		{
			// closing
		}
		ch = null;
		if (ownLock != null)
		{
			ownLock.close();
			ownLock = null;
		}
	}

	/**
	 * Purge one identity directory. Takes the recovery lock, deletes every shard whose lock can be
	 * acquired, and NEVER deletes a shard another live process holds: for those it leaves a purge
	 * marker, which makes that writer stop and delete its own shard. True when the directory is gone.
	 * Creates nothing when the directory does not exist.
	 */
	static boolean purgeIdentityDir(Path dir, LongSupplier clock) throws IOException
	{
		if (!Files.isDirectory(dir))
		{
			return true;
		}
		Locked rl = lock(dir.resolve(RECOVERY_LOCK));
		if (rl == null)
		{
			writeMarker(dir, clock.getAsLong());
			return false;
		}
		boolean live = false;
		try
		{
			for (String sid : shardIds(dir))
			{
				Locked sl = lockOther(dir, sid);
				if (sl == null)
				{
					live = true;
					continue;
				}
				try
				{
					Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl"));
					Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl.next"));
					Files.deleteIfExists(dir.resolve("shard-" + sid + ".corrupt"));
				}
				finally
				{
					sl.releaseAndDelete();
				}
			}
			Files.deleteIfExists(dir.resolve(QUARANTINE));
			Files.deleteIfExists(dir.resolve(QUARANTINE + ".next"));
			if (live)
			{
				writeMarker(dir, clock.getAsLong());
				return false;
			}
			Files.deleteIfExists(dir.resolve(MARKER));
		}
		finally
		{
			rl.releaseAndDelete();
		}
		try
		{
			Files.deleteIfExists(dir);
			return true;
		}
		catch (java.nio.file.DirectoryNotEmptyException e)
		{
			return false;
		}
	}

	/**
	 * Purge an identity ONLY when no live writer holds any of its shards: all or nothing, and never a marker.
	 * This is the purge used when ANOTHER identity becomes active (two clients on one OS user may each hold a
	 * different identity, and neither may cost the other its rows). A live identity is left untouched and is
	 * retried at the next grant or sweep. True when the directory is gone (or never existed).
	 */
	static boolean purgeIfIdle(Path dir) throws IOException
	{
		if (!Files.isDirectory(dir))
		{
			return true;
		}
		Locked rl = lock(dir.resolve(RECOVERY_LOCK));
		if (rl == null)
		{
			return false;
		}
		List<Locked> held = new ArrayList<>();
		boolean live = false;
		try
		{
			for (String sid : shardIds(dir))
			{
				Locked sl = lockOther(dir, sid);
				if (sl == null)
				{
					live = true;
					break;
				}
				held.add(sl);
			}
			if (live)
			{
				for (Locked sl : held)
				{
					sl.close();
				}
				held.clear();
				return false;
			}
			for (String sid : shardIds(dir))
			{
				Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl"));
				Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl.next"));
				Files.deleteIfExists(dir.resolve("shard-" + sid + ".corrupt"));
			}
			Files.deleteIfExists(dir.resolve(QUARANTINE));
			Files.deleteIfExists(dir.resolve(QUARANTINE + ".next"));
			Files.deleteIfExists(dir.resolve(MARKER));
		}
		finally
		{
			for (Locked sl : held)
			{
				sl.releaseAndDelete();
			}
			rl.releaseAndDelete();
		}
		try
		{
			Files.deleteIfExists(dir);
			return true;
		}
		catch (java.nio.file.DirectoryNotEmptyException e)
		{
			return false;
		}
	}

	private static void writeMarker(Path dir, long nowMs) throws IOException
	{
		Path m = dir.resolve(MARKER);
		try (FileChannel c = open(m, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
		{
			writeFully(c, ByteBuffer.wrap(("{\"v\":1,\"requested_ms\":" + nowMs + "}").getBytes(StandardCharsets.UTF_8)), 0L);
			c.force(true);
		}
	}

	/**
	 * Age out abandoned shards in every identity directory under the spool root. Age is the created
	 * time of the newest valid durable record, never the file time. A shard whose lock is held is
	 * skipped; middle corruption is quarantined exactly as recovery does; a torn shard is aged by its
	 * valid prefix. A directory left with no shard is removed.
	 */
	static void sweepAged(Path root, LongSupplier clock, long maxAgeMs) throws IOException
	{
		sweepAged(root, clock, maxAgeMs, new Counters());
	}

	static void sweepAged(Path root, LongSupplier clock, long maxAgeMs, Counters counters) throws IOException
	{
		if (!Files.isDirectory(root))
		{
			return;
		}
		long cutoff = clock.getAsLong() - maxAgeMs;
		List<Path> dirs = new ArrayList<>();
		try (DirectoryStream<Path> ds = Files.newDirectoryStream(root))
		{
			for (Path d : ds)
			{
				if (Files.isDirectory(d) && HEX32.matcher(d.getFileName().toString()).matches())
				{
					dirs.add(d);
				}
			}
		}
		for (Path d : dirs)
		{
			// A marked directory is a purge someone could not finish because a shard was live. Finish it
			// now if every shard is free; if one is still live, leave it to its writer.
			if (Files.exists(d.resolve(MARKER)))
			{
				purgeIfIdle(d);
				continue;
			}
			Locked rl = lock(d.resolve(RECOVERY_LOCK));
			if (rl == null)
			{
				continue;
			}
			boolean empty;
			try
			{
				for (String sid : shardIds(d))
				{
					Locked sl = lockOther(d, sid);
					if (sl == null)
					{
						continue;
					}
					try
					{
						Path spl = d.resolve("shard-" + sid + ".spl");
						Path next = d.resolve("shard-" + sid + ".spl.next");
						if (Files.exists(spl) || Files.exists(next))
						{
							Gen g = load(d, sid);
							if (g.corrupt)
							{
								quarantineCorrupt(d, sid, counters);
							}
							else if (g.live.isEmpty() || g.newestCreated < cutoff)
							{
								Files.deleteIfExists(spl);
								Files.deleteIfExists(next);
							}
						}
						Path corrupt = d.resolve("shard-" + sid + ".corrupt");
						if (Files.exists(corrupt) && newestCreatedAnyValid(Files.readAllBytes(corrupt)) < cutoff)
						{
							Files.deleteIfExists(corrupt);
						}
					}
					finally
					{
						boolean keep = Files.exists(d.resolve("shard-" + sid + ".spl"))
							|| Files.exists(d.resolve("shard-" + sid + ".spl.next"))
							|| Files.exists(d.resolve("shard-" + sid + ".corrupt"));
						if (keep)
						{
							sl.close();
						}
						else
						{
							sl.releaseAndDelete();
						}
					}
				}
				empty = shardIds(d).isEmpty();
				if (empty)
				{
					Files.deleteIfExists(d.resolve(QUARANTINE));
					Files.deleteIfExists(d.resolve(QUARANTINE + ".next"));
					Files.deleteIfExists(d.resolve(MARKER));
				}
			}
			finally
			{
				rl.releaseAndDelete();
			}
			if (empty)
			{
				try
				{
					Files.deleteIfExists(d);
				}
				catch (java.nio.file.DirectoryNotEmptyException ignored)
				{
					// another process created something meanwhile
				}
			}
		}
	}

	// ------------------------------------------------------------------ pointer

	/**
	 * THE INDEX (active.json, format v2): {"v":2,"identities":[{"identity":"<key>","updated_ms":N},...]}, the
	 * identity keys this install has used, newest last, at most MAX_INDEX entries (oldest dropped). Only keys
	 * and times: never a token, never an account hash in clear. Staff only: it is written only while a spool
	 * grant is active. It lets a grant for one identity purge OTHER identities whose token is no longer known,
	 * without ever forgetting an older one because a newer one was recorded (two live clients may each hold a
	 * different identity). Read-modify-write happens under index.lock, because two processes may both write it.
	 */
	static final int MAX_INDEX = 16;

	/** Record identity as the newest entry of the index; written + forced (file and directory). */
	static void writePointer(Path pluginData, Path root, String identity, long nowMs) throws IOException
	{
		if (identity == null || !HEX32.matcher(identity).matches())
		{
			return;
		}
		createOwnerOnlyDirs(pluginData, root);
		updateIndex(root, idx ->
		{
			idx.remove(identity);
			idx.put(identity, nowMs);
			while (idx.size() > MAX_INDEX)
			{
				idx.remove(idx.keySet().iterator().next());
			}
		});
	}

	/** The most recently recorded identity, or null. */
	static String readPointer(Path root)
	{
		List<String> idx = readIndex(root);
		return idx.isEmpty() ? null : idx.get(idx.size() - 1);
	}

	/** Every indexed identity, oldest first. Empty when absent or unreadable. */
	static List<String> readIndex(Path root)
	{
		return new ArrayList<>(parseIndex(root).keySet());
	}

	/** Drop identity from the index; an index left empty is deleted. */
	static void deletePointerIf(Path root, String identity) throws IOException
	{
		if (identity == null || !Files.isRegularFile(root.resolve(POINTER)) || !readIndex(root).contains(identity))
		{
			return;
		}
		updateIndex(root, idx -> idx.remove(identity));
	}

	private static LinkedHashMap<String, Long> parseIndex(Path root)
	{
		LinkedHashMap<String, Long> out = new LinkedHashMap<>();
		Path p = root.resolve(POINTER);
		if (!Files.isRegularFile(p))
		{
			return out;
		}
		try
		{
			String s = new String(Files.readAllBytes(p), StandardCharsets.UTF_8).trim();
			if (!INDEX_BODY.matcher(s).matches())
			{
				return out;
			}
			Matcher m = INDEX_ENTRY.matcher(s);
			while (m.find())
			{
				out.put(m.group(1), Long.parseLong(m.group(2)));
			}
		}
		catch (IOException | RuntimeException e)
		{
			out.clear();
		}
		return out;
	}

	private static void updateIndex(Path root, java.util.function.Consumer<LinkedHashMap<String, Long>> change) throws IOException
	{
		// Never sleep or interrupt a RuneLite/plugin thread while waiting for another process. The
		// spool is best-effort and the memory delivery path remains authoritative, so transient
		// cross-process contention simply fails this spool operation and a later operation retries.
		Locked il = lock(root.resolve(INDEX_LOCK));
		if (il == null)
		{
			throw new IOException("index lock unavailable");
		}
		try
		{
			LinkedHashMap<String, Long> idx = parseIndex(root);
			change.accept(idx);
			if (idx.isEmpty())
			{
				Files.deleteIfExists(root.resolve(POINTER));
				forceDir(root);
				return;
			}
			StringBuilder body = new StringBuilder("{\"v\":2,\"identities\":[");
			boolean first = true;
			for (Map.Entry<String, Long> e : idx.entrySet())
			{
				if (!first)
				{
					body.append(',');
				}
				first = false;
				body.append("{\"identity\":\"").append(e.getKey()).append("\",\"updated_ms\":").append(e.getValue()).append('}');
			}
			body.append("]}");
			Path tmp = root.resolve(POINTER + ".next");
			try (FileChannel c = open(tmp, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE))
			{
				writeFully(c, ByteBuffer.wrap(body.toString().getBytes(StandardCharsets.UTF_8)), 0L);
				c.force(true);
			}
			try
			{
				Files.move(tmp, root.resolve(POINTER), StandardCopyOption.ATOMIC_MOVE);
			}
			catch (IOException e)
			{
				Files.deleteIfExists(tmp);
				throw e;
			}
			forceDir(root);	// the rename itself is durable before any row it covers is written
		}
		finally
		{
			// Keep a stable inode: unlinking after unlock lets a concurrent waiter acquire
			// the old file while a third process locks a newly created replacement.
			il.close();
		}
	}

	// ------------------------------------------------------------------ codec

	static byte[] header()
	{
		return new byte[]{MAGIC[0], MAGIC[1], MAGIC[2], MAGIC[3], (byte) (FORMAT >>> 8), (byte) FORMAT};
	}

	static byte[] frame(String payload)
	{
		byte[] p = payload.getBytes(StandardCharsets.UTF_8);
		CRC32 crc = new CRC32();
		crc.update(p, 0, p.length);
		ByteBuffer b = ByteBuffer.allocate(8 + p.length);
		b.putInt(p.length);
		b.putInt((int) crc.getValue());
		b.put(p);
		return b.array();
	}

	static Scan scan(Path file) throws IOException
	{
		return scan(Files.readAllBytes(file));
	}

	static Scan scan(byte[] b)
	{
		Scan s = new Scan();
		if (b.length < HEADER)
		{
			boolean prefix = true;
			byte[] h = header();
			for (int i = 0; i < b.length; i++)
			{
				prefix &= b[i] == h[i];
			}
			s.status = prefix ? ScanStatus.TORN_TAIL : ScanStatus.CORRUPT;
			s.validEnd = 0;
			return s;
		}
		byte[] h = header();
		for (int i = 0; i < HEADER; i++)
		{
			if (b[i] != h[i])
			{
				s.status = ScanStatus.CORRUPT;
				s.validEnd = 0;
				return s;
			}
		}
		int pos = HEADER;
		while (true)
		{
			if (pos == b.length)
			{
				s.status = ScanStatus.CLEAN;
				s.validEnd = pos;
				return s;
			}
			String p = frameAt(b, pos);
			if (p == null)
			{
				s.status = anyValidFrameAfter(b, pos + 1) ? ScanStatus.CORRUPT : ScanStatus.TORN_TAIL;
				s.validEnd = pos;
				return s;
			}
			s.payloads.add(p);
			pos += 8 + p.getBytes(StandardCharsets.UTF_8).length;
		}
	}

	/** The payload of a well-formed frame at pos, or null. */
	private static String frameAt(byte[] b, int pos)
	{
		if (b.length - pos < 8)
		{
			return null;
		}
		long len = ByteBuffer.wrap(b, pos, 4).getInt() & 0xffffffffL;
		if (len < 2 || len > MAX_FRAME_PAYLOAD || len > b.length - pos - 8L)
		{
			return null;
		}
		int n = (int) len;
		int start = pos + 8;
		if (b[start] != '{' || b[start + n - 1] != '}')
		{
			return null;
		}
		CRC32 crc = new CRC32();
		crc.update(b, start, n);
		int stored = ByteBuffer.wrap(b, pos + 4, 4).getInt();
		if ((int) crc.getValue() != stored)
		{
			return null;
		}
		try
		{
			CharBuffer cb = StandardCharsets.UTF_8.newDecoder()
				.onMalformedInput(CodingErrorAction.REPORT)
				.onUnmappableCharacter(CodingErrorAction.REPORT)
				.decode(ByteBuffer.wrap(b, start, n));
			return cb.toString();
		}
		catch (CharacterCodingException e)
		{
			return null;
		}
	}

	/** Is there any well-formed frame starting after a bad one? Then the damage is in the middle. */
	private static boolean anyValidFrameAfter(byte[] b, int from)
	{
		for (int q = from; q <= b.length - 10; q++)
		{
			if (frameAt(b, q) != null)
			{
				return true;
			}
		}
		return false;
	}

	/** Load one shard id: the newest COMPLETE generation, tombstones applied. Never merges two files. */
	static Gen load(Path dir, String sid) throws IOException
	{
		Path spl = dir.resolve("shard-" + sid + ".spl");
		Path next = dir.resolve("shard-" + sid + ".spl.next");
		if (Files.exists(next))
		{
			Scan sn = scan(next);
			Gen gn = sn.status == ScanStatus.CLEAN ? apply(sn.payloads, true) : null;
			if (gn != null)
			{
				Files.deleteIfExists(spl);
				Files.move(next, spl, StandardCopyOption.ATOMIC_MOVE);
				return gn;
			}
			Files.deleteIfExists(next);	// incomplete compaction output: the older generation stands
		}
		Gen g = new Gen();
		if (!Files.exists(spl))
		{
			return g;
		}
		Scan s = scan(spl);
		if (s.status == ScanStatus.CORRUPT)
		{
			g.corrupt = true;
			return g;
		}
		Gen applied = apply(s.payloads, false);
		return applied == null ? corruptGen() : applied;
	}

	private static Gen corruptGen()
	{
		Gen g = new Gen();
		g.corrupt = true;
		return g;
	}

	/**
	 * Apply records in order. requireEnd: a compaction output is complete only when its last record is
	 * an end record counting exactly its rows, and it holds no tombstone. Returns null when a record
	 * that passed the CRC is still not one of ours, or when a required end record is missing.
	 */
	private static Gen apply(List<String> payloads, boolean requireEnd)
	{
		Gen g = new Gen();
		int evs = 0;
		boolean ended = false;
		for (String p : payloads)
		{
			if (ended)
			{
				return requireEnd ? null : g;
			}
			Matcher m = EV_HEAD.matcher(p);
			if (m.find())
			{
				String json = p.substring(m.end(), p.length() - 1);
				if (!isJsonObject(json))
				{
					return null;
				}
				Record r = new Record(m.group(1), m.group(3), json, Long.parseLong(m.group(2)), false);
				g.live.put(r.eventId, r);
				g.newestCreated = Math.max(g.newestCreated, r.createdMs);
				evs++;
				continue;
			}
			if (ACK.matcher(p).matches())
			{
				if (requireEnd)
				{
					return null;
				}
				Matcher ids = ID_IN.matcher(p);
				while (ids.find())
				{
					g.live.remove(ids.group(1));
				}
				continue;
			}
			Matcher e = END.matcher(p);
			if (e.matches())
			{
				if (requireEnd)
				{
					if (Integer.parseInt(e.group(1)) != evs)
					{
						return null;
					}
					ended = true;
				}
				continue;
			}
			return null;
		}
		return requireEnd && !ended ? null : g;
	}

	/** Newest created_ms among frames that pass their own CRC, walking past bad ones where possible. */
	private static long newestCreatedAnyValid(byte[] b)
	{
		long newest = -1L;
		int pos = HEADER;
		while (pos <= b.length - 8)
		{
			String p = frameAt(b, pos);
			if (p != null)
			{
				Matcher m = EV_HEAD.matcher(p);
				if (m.find())
				{
					newest = Math.max(newest, Long.parseLong(m.group(2)));
				}
				pos += 8 + p.getBytes(StandardCharsets.UTF_8).length;
				continue;
			}
			long len = ByteBuffer.wrap(b, pos, 4).getInt() & 0xffffffffL;
			if (len < 2 || len > b.length - pos - 8L)
			{
				break;
			}
			pos += 8 + (int) len;
		}
		return newest;
	}

	private static void quarantineCorrupt(Path dir, String sid, Counters counters) throws IOException
	{
		Path spl = dir.resolve("shard-" + sid + ".spl");
		Path to = dir.resolve("shard-" + sid + ".corrupt");
		try
		{
			Files.move(spl, to, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException e)
		{
			Files.move(spl, to, StandardCopyOption.REPLACE_EXISTING);
		}
		Files.deleteIfExists(dir.resolve("shard-" + sid + ".spl.next"));
		counters.corrupt.incrementAndGet();
	}

	// ------------------------------------------------------------------ internals

	private void ensureOpen() throws IOException
	{
		if (ch != null)
		{
			return;
		}
		if (closed)
		{
			throw new IOException("spool closed");
		}
		createOwnerOnlyDirs(pluginData, dir);
		if (ownLock == null)
		{
			ownLock = lock(lockPath(dir, shardId));
			// A purge in another process may have deleted the lock file between our open and our tryLock.
			// Then we hold a lock on an unlinked file: refuse to write rather than create an unlocked shard.
			if (ownLock == null || !Files.exists(lockPath(dir, shardId)) || purgeRequested())
			{
				if (ownLock != null)
				{
					ownLock.close();
					ownLock = null;
				}
				throw new IOException("shard lock unavailable");
			}
		}
		ch = open(shardFile(), StandardOpenOption.CREATE_NEW, StandardOpenOption.READ, StandardOpenOption.WRITE);
		writeFully(ch, ByteBuffer.wrap(header()), 0L);
		ch.force(true);
		forceDir(dir);
		fileBytes = HEADER;
		overheadBytes = HEADER;
		liveFrameBytes = 0;
	}

	private void writeFrames(List<String> payloads) throws IOException
	{
		if (payloads.isEmpty())
		{
			return;
		}
		ByteArrayBuilder all = new ByteArrayBuilder();
		for (String p : payloads)
		{
			all.add(frame(p));
		}
		byte[] bytes = all.toArray();
		writeFully(ch, ByteBuffer.wrap(bytes), fileBytes);
		ch.force(false);
		fileBytes += bytes.length;
	}

	private void put(Map<String, Record> into, Record r)
	{
		into.put(r.eventId, r);
		payloadBytes += r.payloadBytes;
		liveFrameBytes += frame(evPayload(r)).length;
	}

	private void tombstone(List<String> ids) throws IOException
	{
		if (ids.isEmpty())
		{
			return;
		}
		List<String> payloads = new ArrayList<>();
		for (int i = 0; i < ids.size(); i += 500)
		{
			StringBuilder sb = new StringBuilder("{\"v\":1,\"k\":\"ack\",\"ids\":[");
			for (int j = i; j < Math.min(ids.size(), i + 500); j++)
			{
				if (j > i)
				{
					sb.append(',');
				}
				sb.append('"').append(ids.get(j)).append('"');
			}
			payloads.add(sb.append("]}").toString());
		}
		writeFrames(payloads);
		for (String id : ids)
		{
			Record r = pending.remove(id);
			if (r != null)
			{
				payloadBytes -= r.payloadBytes;
				liveFrameBytes -= frame(evPayload(r)).length;
			}
		}
	}

	/** Enforce the age, record and byte bounds now (durable tombstones, counted). The replay calls it first. */
	void enforceBoundsNow() throws IOException
	{
		if (ch != null && !closed && !failed && !pending.isEmpty())
		{
			enforceBounds();
		}
	}

	/** Age, record-count and byte bounds. Drops the OLDEST undelivered rows, durably. */
	private void enforceBounds() throws IOException
	{
		long cutoff = clock.getAsLong() - limits.maxAgeMs;
		List<String> drop = new ArrayList<>();
		Set<String> dropSet = new HashSet<>();
		long bytes = payloadBytes;
		int count = pending.size();
		for (Record r : pending.values())
		{
			if (r.createdMs < cutoff)
			{
				drop.add(r.eventId);
				dropSet.add(r.eventId);
				bytes -= r.payloadBytes;
				count--;
			}
		}
		for (Record r : pending.values())
		{
			if (count <= limits.maxRecords && bytes <= limits.maxBytes)
			{
				break;
			}
			if (dropSet.contains(r.eventId))
			{
				continue;
			}
			drop.add(r.eventId);
			dropSet.add(r.eventId);
			bytes -= r.payloadBytes;
			count--;
		}
		if (!drop.isEmpty())
		{
			tombstone(drop);
			counters.dropped.addAndGet(drop.size());
		}
	}

	static String evPayload(Record r)
	{
		return "{\"v\":1,\"k\":\"ev\",\"id\":\"" + r.eventId + "\",\"c\":" + r.createdMs + ",\"t\":\"" + r.type
			+ "\",\"e\":" + r.eventJson + "}";
	}

	private static boolean isJsonObject(String json)
	{
		try (com.google.gson.stream.JsonReader r = new com.google.gson.stream.JsonReader(new StringReader(json)))
		{
			if (r.peek() != com.google.gson.stream.JsonToken.BEGIN_OBJECT)
			{
				return false;
			}
			r.skipValue();
			return r.peek() == com.google.gson.stream.JsonToken.END_DOCUMENT;
		}
		catch (IOException | RuntimeException e)
		{
			return false;
		}
	}

	private static Set<String> shardIds(Path dir) throws IOException
	{
		Set<String> ids = new TreeSet<>();
		try (DirectoryStream<Path> ds = Files.newDirectoryStream(dir))
		{
			for (Path p : ds)
			{
				Matcher m = SHARD_NAME.matcher(p.getFileName().toString());
				if (m.matches())
				{
					ids.add(m.group(1));
				}
			}
		}
		return ids;
	}

	private static Path lockPath(Path dir, String sid)
	{
		return dir.resolve("shard-" + sid + ".lock");
	}

	/**
	 * Lock another process's shard. A writer takes its lock BEFORE it creates its .spl, so when a .spl (or
	 * .next / .corrupt) exists its owner either holds the lock or is dead, and creating the lock file is
	 * safe. A lock-only entry may belong to a writer between open and tryLock: never create it then.
	 */
	private static Locked lockOther(Path dir, String sid) throws IOException
	{
		boolean hasData = Files.exists(dir.resolve("shard-" + sid + ".spl"))
			|| Files.exists(dir.resolve("shard-" + sid + ".spl.next"))
			|| Files.exists(dir.resolve("shard-" + sid + ".corrupt"));
		return lock(lockPath(dir, sid), hasData);
	}

	/** An exclusive lock, or null when another holder (this JVM or another process) has it. */
	static Locked lock(Path file) throws IOException
	{
		return lock(file, true);
	}

	/**
	 * create=false is how a process locks ANOTHER process's shard lock: it never re-creates a lock file that
	 * its owner may be about to take, so an owner that finds its lock file gone after tryLock knows it lost
	 * that race and refuses to write. Returns null when the file is absent or held.
	 */
	static Locked lock(Path file, boolean create) throws IOException
	{
		FileChannel c;
		try
		{
			c = create ? open(file, StandardOpenOption.CREATE, StandardOpenOption.WRITE)
				: FileChannel.open(file, StandardOpenOption.WRITE);
		}
		catch (java.nio.file.NoSuchFileException e)
		{
			return null;
		}
		try
		{
			FileLock l = c.tryLock();
			if (l == null)
			{
				c.close();
				return null;
			}
			return new Locked(file, c, l);
		}
		catch (OverlappingFileLockException e)
		{
			c.close();
			return null;
		}
		catch (IOException | RuntimeException e)
		{
			c.close();
			throw e;
		}
	}

	static final class Locked
	{
		private final Path file;
		private final FileChannel channel;
		private final FileLock lock;

		Locked(Path file, FileChannel channel, FileLock lock)
		{
			this.file = file;
			this.channel = channel;
			this.lock = lock;
		}

		void close()
		{
			try
			{
				lock.release();
			}
			catch (IOException ignored)
			{
				// closing the channel releases it too
			}
			try
			{
				channel.close();
			}
			catch (IOException ignored)
			{
				// closing
			}
		}

		void releaseAndDelete()
		{
			close();
			try
			{
				Files.deleteIfExists(file);
			}
			catch (IOException ignored)
			{
				// Windows may refuse while another handle is open; harmless, re-used next time
			}
		}
	}

	private static FileAttribute<?>[] fileAttrs()
	{
		return POSIX
			? new FileAttribute<?>[]{PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rw-------"))}
			: new FileAttribute<?>[0];
	}

	private static FileChannel open(Path p, OpenOption... options) throws IOException
	{
		Set<OpenOption> set = new HashSet<>(java.util.Arrays.asList(options));
		return FileChannel.open(p, set, fileAttrs());
	}

	/** Create every directory from pluginData down to target, owner-only where POSIX applies. */
	static void createOwnerOnlyDirs(Path pluginData, Path target) throws IOException
	{
		Files.createDirectories(pluginData);
		Path rel = pluginData.relativize(target);
		Path cur = pluginData;
		for (Path part : rel)
		{
			cur = cur.resolve(part);
			if (Files.isDirectory(cur))
			{
				continue;
			}
			try
			{
				if (POSIX)
				{
					Files.createDirectory(cur, PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));
				}
				else
				{
					Files.createDirectory(cur);
				}
			}
			catch (FileAlreadyExistsException ignored)
			{
				// another process created it
			}
		}
	}

	private static void forceDir(Path dir)
	{
		try (FileChannel d = FileChannel.open(dir, StandardOpenOption.READ))
		{
			d.force(true);
		}
		catch (IOException | RuntimeException ignored)
		{
			// not supported on every platform (Windows); the file forces already ran
		}
	}

	private static long writeFully(FileChannel c, ByteBuffer b, long pos) throws IOException
	{
		long written = 0;
		while (b.hasRemaining())
		{
			int n = pos < 0 ? c.write(b) : c.write(b, pos + written);
			written += n;
		}
		return written;
	}

	private static final class ByteArrayBuilder
	{
		private final java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();

		void add(byte[] b)
		{
			out.write(b, 0, b.length);
		}

		byte[] toArray()
		{
			return out.toByteArray();
		}
	}

	static String sha256Hex(String s)
	{
		try
		{
			return hex(java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));
		}
		catch (java.security.NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 unavailable", e);
		}
	}

	private static String hex(byte[] b)
	{
		StringBuilder sb = new StringBuilder(b.length * 2);
		for (byte x : b)
		{
			sb.append(Character.forDigit((x >> 4) & 0xf, 16)).append(Character.forDigit(x & 0xf, 16));
		}
		return sb.toString();
	}
}

/*
 * OSRS Best in Slot — the player's own game variables, as raw values.
 *
 * WHY RAW. Every account-state source the audited Plugin Hub plugins read (quests, diaries, combat
 * achievement tasks, Slayer task/boss/area/size, prayer unlocks, Sailing charting, farming patches,
 * minigame points, unlocks, kill counters kept in varps) is a VARP or a VARBIT, and every varbit is a bit
 * range of a varp. So the full varp array decodes to all of them on the server, with no per-feature
 * client code and no plugin release when a new game update adds a variable. The registry in the lane
 * (`registry/registry_aggregate.tsv`) maps each decoded field to its source id and the plugins that use it.
 *
 * WHAT IS SENT. Only the LOCAL player's own variables, which the game server sends to this client for this
 * account. Nothing about other players is in this array. The encoding is sparse (non-zero entries only),
 * because a fresh account has almost every varp at 0: {"n": length, "nz": {"<index>": value, ...},
 * "sha": sha256 of the encoded map}. Absent index = 0 in the game, which is the game's own default for a
 * varp, so this does not turn an unknown into zero: the whole block is absent until the client has
 * finished loading the player's variables (the caller checks that).
 *
 * A pure helper: no RuneLite types, so it is unit-testable without a client.
 */
package com.osrsbestinslot.export;

import java.util.LinkedHashMap;
import java.util.Map;

final class GameVarsCapture
{
	private GameVarsCapture()
	{
	}

	/** Sparse encoding of a varp array, or null when the array is missing. */
	static Map<String, Object> encode(int[] varps)
	{
		if (varps == null)
		{
			return null;
		}
		Map<String, Object> nz = new LinkedHashMap<>();
		StringBuilder canon = new StringBuilder();
		for (int i = 0; i < varps.length; i++)
		{
			if (varps[i] != 0)
			{
				nz.put(Integer.toString(i), varps[i]);
				canon.append(i).append('=').append(varps[i]).append(';');
			}
		}
		Map<String, Object> out = new LinkedHashMap<>();
		out.put("n", varps.length);
		out.put("nz", nz);
		out.put("sha", AccountConnectPlugin.sha256Hex(canon.toString()));
		return out;
	}

	/** Decode one varbit from a varp value, given the varbit's bit range (inclusive). Used by tests and docs. */
	static int varbit(int varpValue, int lsb, int msb)
	{
		int width = msb - lsb + 1;
		int mask = width >= 32 ? -1 : (1 << width) - 1;
		return (varpValue >>> lsb) & mask;
	}
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/** Bounded UI evidence, never a trade ledger or a source of execution timestamps. */
final class GeHistoryCapture
{
    private static final String NUMBER = "([0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)";
    private static final Pattern TOTAL = Pattern.compile("^" + NUMBER + " coins?(?:\\s|$)");
    // 0.7.42 actual client renders "= 11,203 each"; the historic format was ">= N each".
    private static final Pattern EACH = Pattern.compile("(?:^|\\s)>?= " + NUMBER + " each(?:\\s|$)");
    private static final String STRICT_NUMBER = "(0|[1-9][0-9]{0,2}(?:,[0-9]{3})+|[1-9][0-9]*)";
    private static final Pattern DEDUCTION = Pattern.compile(STRICT_NUMBER + " coins?(?:<br>| )\\("
        + STRICT_NUMBER + " - " + STRICT_NUMBER + "(?: tax)?\\)");
    private static final Pattern NET_SEGMENT = Pattern.compile(STRICT_NUMBER + " coins?");
    private static final Pattern DEDUCTION_SEGMENT = Pattern.compile("\\(" + STRICT_NUMBER + " - " + STRICT_NUMBER
        + "(?: tax)?\\)");
    private static final Pattern EACH_SEGMENT = Pattern.compile("= " + STRICT_NUMBER + " each");
    private static final Pattern COLOUR_WRAPPER = Pattern.compile("<col=[0-9a-fA-F]{3}(?:[0-9a-fA-F]{3})?>(.*)</col>");
    private final List<Map<String, Object>> observations = new ArrayList<>();
    private List<Map<String, Object>> previous;
    private List<Map<String, Object>> candidate;
    private long candidateAt;
    private int nextTick;
    private int nextObservationTick;
    private long sequence;
    private long evicted;
    private String collectorSession = java.util.UUID.randomUUID().toString();

    void reset()
    {
        collectorSession = java.util.UUID.randomUUID().toString();
        observations.clear();
        previous = candidate = null;
        nextTick = nextObservationTick = 0;
        sequence = evicted = 0;
    }

    void poll(Client client, long now)
    {
        int tick = client.getTickCount();
        if (tick < nextTick) return;
        nextTick = tick + 1;
        Widget list = client.getWidget(383, 3);
        if (list == null || list.isHidden())
        {
            candidate = null;
            return;
        }
        List<Map<String, Object>> rows = read(list.getDynamicChildren());
        if (rows == null || rows.isEmpty())
        {
            candidate = null;
            return;
        }
        // Require two equal reads: WidgetLoaded can precede layout and item population.
        if (!rows.equals(candidate))
        {
            candidate = rows;
            candidateAt = now;
            return;
        }
        if (rows.equals(previous)) return; // opening the same history is not another execution
        if (tick < nextObservationTick) return;
        nextObservationTick = tick + 5;
        previous = rows;
        Map<String, Object> observation = new LinkedHashMap<>();
        observation.put("sequence", ++sequence);
        observation.put("observed_at_ms", candidateAt);
        observation.put("confirmed_at_ms", now);
        observation.put("rows", rows);
        observations.add(observation);
        if (observations.size() > 8)
        {
            observations.remove(0);
            evicted++;
        }
    }

    static List<Map<String, Object>> read(Widget[] children)
    {
        if (children == null || children.length == 0 || children.length % 6 != 0 || children.length > 240)
            return null;
        List<Map<String, Object>> rows = new ArrayList<>();
        for (int offset = 0; offset < children.length; offset += 6)
        {
            Widget state = children[offset + 2], item = children[offset + 4], price = children[offset + 5];
            if (state == null || item == null || price == null) return null;
            String rawState = state.getText(), rawPrice = price.getText();
            if (rawState == null || rawPrice == null || rawState.length() > 128 || rawPrice.length() > 512)
                return null;
            if (rawState.isEmpty() && item.getItemId() <= 0) continue; // empty history row
            if (item.getItemId() <= 0 || item.getItemQuantity() <= 0) return null;
            // The 0.7.43 actual client shows "Bought:" / "Sold:".
            String side = Text.removeTags(rawState).trim().replaceFirst(":$", "");
            Map<String, Object> row = new LinkedHashMap<>();
            row.put("row_index", offset / 6);
            row.put("item_id", item.getItemId());
            row.put("quantity", item.getItemQuantity());
            row.put("side", "Bought".equals(side) ? "buy" : "Sold".equals(side) ? "sell" : "unknown");
            row.put("state_text", rawState);
            row.put("price_text", rawPrice);
            String plain = Text.removeTags(rawPrice.replace("<br>", " ")).replace('\u00a0', ' ').trim();
            row.put("displayed_total_gp", number(TOTAL, plain));
            row.put("displayed_each_gp", number(EACH, plain));
            row.put("execution_time", "unknown");
            row.put("price_semantics", "displayed_values_tax_and_rounding_unresolved");
            captureDeduction(row, rawState, rawPrice);
            rows.add(row);
        }
        return rows;
    }

    /**
     * Historic format reference: Flipping Utilities GeHistoryTabExtractor.getPrice ("(gross - tax tax)").
     * The 0.7.43 actual client (field-read 2026-10-19) renders each line in its own colour wrapper:
     * "<col=ffb83f>2,646 coins</col><br><col=9f9f9f>(2,700 - 54)</col>", optionally followed by
     * "<br>= 1,323 each", with no "tax" word. Both forms are accepted.
     * Unlike that extractor, retain offer totals: division cannot recover exact fills, and
     * displayed net must never have tax deducted again. Missing tax is not evidence of zero tax.
     */
    private static void captureDeduction(Map<String, Object> row, String rawState, String rawPrice)
    {
        row.put("original_gross_gp", null);
        row.put("explicit_tax_gp", null);
        row.put("displayed_net_gp", null);
        row.put("tax_gross_source", "ge_history_widget_383_3_price_text");
        row.put("tax_gross_provenance", "historic_flipping_utilities_ge_history_format");
        row.put("tax_gross_semantics", "unknown");
        row.put("verified_with_actual_client", false);

        // Only a complete plain string or one balanced colour wrapper is accepted. Never
        // strip arbitrary markup: doing so can join split digits or hide truncated text.
        String state = unwrapColour(rawState);
        if (state.endsWith(":")) state = state.substring(0, state.length() - 1);
        boolean buy = "Bought".equals(state);
        if (!buy && !"Sold".equals(state)) return;
        String[] parts = deduction(rawPrice);
        if (parts == null) return;
        try
        {
            long net = Long.parseLong(parts[0].replace(",", ""));
            long gross = Long.parseLong(parts[1].replace(",", ""));
            long tax = Long.parseLong(parts[2].replace(",", ""));
            // Nonnegative longs and tax <= gross make subtraction overflow-safe.
            if (tax > gross || gross - tax != net || (buy && tax != 0)) return;
            row.put("original_gross_gp", gross);
            row.put("explicit_tax_gp", tax);
            row.put("displayed_net_gp", net);
            row.put("tax_gross_semantics", "explicit_ui_offer_totals_not_exact_fills");
        }
        catch (NumberFormatException ex)
        {
            // All three fields remain unknown on overflow, even if a prefix was parseable.
        }
    }

    /**
     * {net, gross, tax} text, or null. Either the historic single string, or lines split on "<br>"
     * where each line is plain or exactly one balanced colour wrapper: net coins, (gross - tax),
     * then an optional "= N each". Any other markup or extra line rejects the whole row.
     */
    private static String[] deduction(String rawPrice)
    {
        Matcher whole = DEDUCTION.matcher(unwrapColour(rawPrice));
        if (whole.matches()) return new String[]{whole.group(1), whole.group(2), whole.group(3)};
        String[] lines = rawPrice.split("<br>", -1);
        if (lines.length < 2 || lines.length > 3) return null;
        for (int i = 0; i < lines.length; i++)
        {
            lines[i] = unwrapColour(lines[i]);
            if (lines[i].indexOf('<') >= 0 || lines[i].indexOf('>') >= 0) return null;
        }
        Matcher net = NET_SEGMENT.matcher(lines[0]), split = DEDUCTION_SEGMENT.matcher(lines[1]);
        if (!net.matches() || !split.matches()) return null;
        if (lines.length == 3 && !EACH_SEGMENT.matcher(lines[2]).matches()) return null;
        return new String[]{net.group(1), split.group(1), split.group(2)};
    }

    private static String unwrapColour(String raw)
    {
        Matcher wrapper = COLOUR_WRAPPER.matcher(raw);
        return wrapper.matches() ? wrapper.group(1) : raw;
    }

    private static Long number(Pattern pattern, String text)
    {
        Matcher match = pattern.matcher(text);
        if (!match.find()) return null;
        try { return Long.parseLong(match.group(1).replace(",", "")); }
        catch (NumberFormatException ex) { return null; }
    }

    Map<String, Object> snapshot()
    {
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("source", "ge_history_widget_383_3");
        out.put("collector_session", collectorSession);
        out.put("identity_scope", "account_profile_collector_session");
        out.put("observations", new ArrayList<>(observations));
        out.put("observations_evicted", evicted);
        out.put("complete", false); // UI is a limited recent history, not all trades
        return out;
    }
}

package com.osrsbestinslot.export;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;

/** Own-account, session-local observations. No game order ID or execution timestamp is exposed. */
final class GeObservationTracker
{
    private final Map<Integer, Slot> slots = new HashMap<>();
    private final Map<Integer, Long> emptySlots = new HashMap<>();

    private static final class Slot
    {
        String key = EventSpool.newEventId();
        String seen;
        GrandExchangeOfferState state;
        long[] value;
        long emittedQty;
        long emittedGp;
        long emittedAt;
        long observedAt;
        int lastProgressTick;
        boolean uncertain;
        boolean gap;
        long sequence;
        /** Restored from disk after a restart: the offer_key outlived the collector session. */
        boolean restored;
    }

    void clear()
    {
        slots.clear();
        emptySlots.clear();
    }

    void gap()
    {
        for (Slot s : slots.values())
        {
            s.gap = true;
        }
    }

    boolean isEmpty()
    {
        return slots.isEmpty();
    }

    /** The slots as plain values, for the restart file. Empty-slot times are not kept: they only date a new offer. */
    java.util.List<Map<String, Object>> export()
    {
        java.util.List<Map<String, Object>> out = new java.util.ArrayList<>();
        for (Map.Entry<Integer, Slot> e : new java.util.TreeMap<>(slots).entrySet())
        {
            Slot s = e.getValue();
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("slot", e.getKey());
            m.put("key", s.key);
            m.put("seen", s.seen);
            m.put("state", s.state.name());
            m.put("value", java.util.Arrays.stream(s.value).boxed().collect(java.util.stream.Collectors.toList()));
            m.put("emitted_qty", s.emittedQty);
            m.put("emitted_gp", s.emittedGp);
            m.put("emitted_at", s.emittedAt);
            m.put("observed_at", s.observedAt);
            m.put("uncertain", s.uncertain);
            m.put("sequence", s.sequence);
            out.add(m);
        }
        return out;
    }

    /**
     * Take back the slots of the same account, profile and token after a restart. Every restored slot is marked
     * as crossing a gap: the next observation reports the counter difference since the last row sent, with the
     * interval from that row to now and no fill time. A malformed entry is skipped, never guessed.
     */
    void restore(java.util.List<?> saved)
    {
        slots.clear();
        emptySlots.clear();
        if (saved == null)
        {
            return;
        }
        for (Object o : saved)
        {
            try
            {
                Map<?, ?> m = (Map<?, ?>) o;
                java.util.List<?> v = (java.util.List<?>) m.get("value");
                String key = (String) m.get("key");
                if (v == null || v.size() != 5 || key == null || !key.matches("^[0-9a-f]{32}$"))
                {
                    continue;
                }
                int slot = ((Number) m.get("slot")).intValue();
                if (slot < 0 || slot >= AccountConnectPlugin.GE_SLOT_COUNT)
                {
                    continue;
                }
                Slot s = new Slot();
                s.key = key;
                s.seen = (String) m.get("seen");
                s.state = GrandExchangeOfferState.valueOf((String) m.get("state"));
                s.value = new long[5];
                for (int i = 0; i < 5; i++)
                {
                    s.value[i] = ((Number) v.get(i)).longValue();
                }
                s.emittedQty = ((Number) m.get("emitted_qty")).longValue();
                s.emittedGp = ((Number) m.get("emitted_gp")).longValue();
                s.emittedAt = ((Number) m.get("emitted_at")).longValue();
                s.observedAt = ((Number) m.get("observed_at")).longValue();
                s.uncertain = Boolean.TRUE.equals(m.get("uncertain"));
                s.sequence = ((Number) m.get("sequence")).longValue();
                s.lastProgressTick = Integer.MIN_VALUE / 2;	// the tick count restarted with the client
                s.gap = true;
                s.restored = true;
                if (s.state == GrandExchangeOfferState.EMPTY || s.seen == null)
                {
                    continue;
                }
                slots.put(slot, s);
            }
            catch (RuntimeException e)
            {
                // skip this entry
            }
        }
    }

    static boolean active(GrandExchangeOfferState s)
    {
        return s == GrandExchangeOfferState.BUYING || s == GrandExchangeOfferState.SELLING;
    }

    private static boolean same(Slot s, GrandExchangeOfferState state, long[] v)
    {
        return s.value[0] == v[0] && s.value[2] == v[2] && s.value[3] == v[3]
            && java.util.Objects.equals(AccountConnectPlugin.geSide(s.state), AccountConnectPlugin.geSide(state));
    }

    /** v = item, cumulative quantity, total quantity, listing price, cumulative RuneLite spent. */
    Map<String, Object> observe(int slot, GrandExchangeOfferState state, long[] v,
        boolean replay, int tick, long observedAt)
    {
        if (slot < 0 || slot >= 8 || state == null || v == null || v.length != 5)
        {
            return null;
        }
        Slot s = slots.get(slot);
        if (state == GrandExchangeOfferState.EMPTY)
        {
            slots.remove(slot);
            emptySlots.put(slot, observedAt);
            return s == null || replay ? null : row(slot, s, "ge_collect", observedAt, false);
        }
        if (v[0] <= 0 || v[1] < 0 || v[2] <= 0 || v[1] > v[2] || v[3] < 0 || v[4] < 0)
        {
            // Do not bridge a malformed counter into an apparently trustworthy delta.
            if (s != null)
            {
                s.uncertain = true;
            }
            return null;
        }
        Long emptyAt = emptySlots.remove(slot);
        boolean afterEmpty = emptyAt != null;
        boolean ambiguousReuse = s != null && same(s, state, v) && !active(s.state) && active(state);
        boolean fresh = s == null || !same(s, state, v) || (!active(s.state) && active(state));
        if (fresh)
        {
            s = new Slot();
            s.uncertain = ambiguousReuse;
            s.state = state;
            s.value = v.clone();
            s.seen = replay ? "midway" : active(state) && (afterEmpty || v[1] == 0) ? "placed" : "midway";
            // Only an observed empty slot supplies a zero baseline for an instant fill.
            // Otherwise first sight cannot credit historical fills, including restart/login.
            boolean fromEmpty = afterEmpty && !replay;
            s.emittedQty = fromEmpty ? 0 : v[1];
            s.emittedGp = fromEmpty ? 0 : v[4];
            s.emittedAt = fromEmpty ? emptyAt : observedAt;
            s.observedAt = observedAt;
            s.lastProgressTick = replay ? tick - AccountConnectPlugin.GE_PROGRESS_MIN_TICKS : tick;
            slots.put(slot, s);
            if (replay)
            {
                return null;
            }
            return row(slot, s, active(state) ? (afterEmpty || v[1] == 0 ? "ge_offer" : "ge_progress")
                : terminalType(state), observedAt, !fromEmpty);
        }
        if (v[1] < s.value[1] || v[4] < s.value[4])
        {
            // Could be a stale packet, collection-counter reset or unseen identical relist. No oracle
            // distinguishes these. Keep the high-water tuple and quarantine deltas until a new offer.
            s.uncertain = true;
            return null;
        }
        GrandExchangeOfferState previousState = s.state;
        boolean changed = v[1] != s.value[1] || v[4] != s.value[4];
        s.value = v.clone();
        s.state = state;
        s.observedAt = observedAt;
        s.gap |= replay;
        if (replay && !changed && state == previousState)
        {
            return null;
        }
        String type = null;
        if (!active(state) && (state != previousState || changed))
        {
            type = terminalType(state);
        }
        else if (active(state) && (s.value[1] != s.emittedQty || s.value[4] != s.emittedGp)
            && (replay || tick < s.lastProgressTick || tick - s.lastProgressTick >= AccountConnectPlugin.GE_PROGRESS_MIN_TICKS))
        {
            type = "ge_progress";
        }
        if (type == null)
        {
            return null;
        }
        s.lastProgressTick = tick;
        return row(slot, s, type, observedAt, false);
    }

    private static String terminalType(GrandExchangeOfferState state)
    {
        if (state == GrandExchangeOfferState.BOUGHT)
        {
            return "ge_buy";
        }
        if (state == GrandExchangeOfferState.SOLD)
        {
            return "ge_sell";
        }
        return "ge_cancel";
    }

    private static Map<String, Object> row(int slot, Slot s, String type, long at, boolean baseline)
    {
        Map<String, Object> f = new LinkedHashMap<>();
        f.put("type", type);
        f.put("item", (int) s.value[0]);
        f.put("qty", (int) s.value[1]);
        f.put("qty_total", (int) s.value[2]);
        f.put("price", s.value[3]);
        f.put("gp", s.value[4]);
        f.put("slot", slot);
        f.put("state", s.state.name());
        f.put("side", AccountConnectPlugin.geSide(s.state));
        f.put("offer_key", s.key);
        f.put("offer_seen", s.seen);
        Map<String, Object> o = new LinkedHashMap<>();
        o.put("schema_v", 1);
        o.put("sequence", ++s.sequence);
        o.put("cumulative_qty", s.value[1]);
        o.put("cumulative_gp", s.value[4]);
        o.put("delta_from_qty", s.emittedQty);
        o.put("delta_from_gp", s.emittedGp);
        o.put("source", "runelite_grand_exchange_offer");
        o.put("observed_at_ms", at);
        o.put("counter_observed_at_ms", s.observedAt);
        o.put("listing_price", s.value[3]);
        o.put("gp_semantics", "runelite_spent_tax_unknown");
        o.put("execution_price", null);
        o.put("tax_gp", null);
        o.put("identity", s.uncertain ? "ambiguous_counter_regression" : s.gap ? "inferred_across_gap" : "inferred_session_slot");
        o.put("offer_key_scope", s.restored ? "account_profile" : "collector_session");
        boolean clockOk = at >= s.emittedAt;
        o.put("delta_status", s.uncertain ? "unknown" : baseline ? "baseline_only" : "observed_counter_difference");
        o.put("delta_qty", s.uncertain ? null : s.value[1] - s.emittedQty);
        o.put("delta_gp", s.uncertain ? null : s.value[4] - s.emittedGp);
        // Bounds are observation bounds, conditional on the inferred identity; never exact fill times.
        o.put("interval_start_ms", !s.uncertain && clockOk ? s.emittedAt : null);
        o.put("interval_end_ms", !s.uncertain && clockOk ? s.observedAt : null);
        o.put("fill_time", "unknown");
        f.put("ge_observation", o);
        s.emittedQty = s.value[1];
        s.emittedGp = s.value[4];
        s.emittedAt = at;
        return f;
    }
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Pure, deterministic reducer from ge_* event rows (as emitted by GeObservationTracker and kept by
 * PublicTransport) to one derived record per offer episode. Raw rows are never changed.
 *
 * Contract: offer_key is a session-slot episode, not a game order ID. Only counter differences
 * after an observed baseline are credited. Fill times are observation intervals, never execution
 * times. RuneLite "spent" has unverified tax semantics: tax is a rule-based range or an exact
 * value only when a unique GE history row corroborates the same counters. The result does not
 * depend on input order.
 */
final class GeOfferLifecycle
{
    static final int RECORD_SCHEMA_V = 1;
    static final String DERIVATION = "c1_ge_offer_lifecycle_v2";
    static final long TAX_EXEMPT_BELOW_UNIT_GP = 50;
    static final long TAX_CAP_PER_ITEM_GP = 5_000_000;
    private static final Set<String> TYPES = new LinkedHashSet<>(java.util.Arrays.asList(
        "ge_offer", "ge_progress", "ge_buy", "ge_sell", "ge_cancel", "ge_collect"));
    private static final List<String> IDENTITY_RANK = java.util.Arrays.asList(
        "inferred_session_slot", "inferred_across_gap", "ambiguous_counter_regression");

    private GeOfferLifecycle() {}

    private static final class Episode
    {
        final String key;
        final List<Map<String, Object>> rows = new ArrayList<>();
        final Set<String> quarantine = new LinkedHashSet<>();
        Episode(String key) { this.key = key; }
    }

    /**
     * @param events ge_* rows for ONE account (other types are counted and ignored)
     * @param history GeHistoryCapture rows for the same account, or null; corroboration only
     * @param generation caller-supplied account/mode identity; there is no shared public epoch yet
     */
    static Map<String, Object> reduce(List<Map<String, Object>> events, List<Map<String, Object>> history,
        String generation)
    {
        Map<String, Object> diagnostics = new TreeMap<>();
        // Pass 1: keep usable rows and find event IDs that carry more than one content.
        Map<String, Map<Long, List<Map<String, Object>>>> grouped = new TreeMap<>();
        Map<String, Set<String>> contentsById = new TreeMap<>();
        Map<String, Set<String>> keysById = new TreeMap<>();
        for (Object raw : events == null ? Collections.emptyList() : (List<?>) events)
        {
            Map<String, Object> e = stringKeyed(raw);
            if (e == null || !TYPES.contains(String.valueOf(e.get("type"))))
            {
                count(diagnostics, "non_ge_rows_ignored");
                continue;
            }
            Map<?, ?> o = e.get("ge_observation") instanceof Map ? (Map<?, ?>) e.get("ge_observation") : null;
            Object key = e.get("offer_key");
            Long sequence = o == null ? null : num(o.get("sequence"));
            if (e.get("event_id") instanceof String)
            {
                // Before any row is dropped: an unusable copy under a used ID is still a conflict.
                String id = (String) e.get("event_id");
                contentsById.computeIfAbsent(id, k -> new TreeSet<>()).add(canonical(e));
                Set<String> named = keysById.computeIfAbsent(id, k -> new TreeSet<>());
                if (key instanceof String) named.add((String) key);
            }
            if (!(key instanceof String) || o == null || sequence == null)
            {
                count(diagnostics, "rows_without_versioned_observation");
                continue;
            }
            grouped.computeIfAbsent((String) key, k -> new TreeMap<>())
                .computeIfAbsent(sequence, k -> new ArrayList<>()).add(e);
        }
        Set<String> conflictKeys = new TreeSet<>();
        for (Map.Entry<String, Set<String>> c : contentsById.entrySet())
        {
            if (c.getValue().size() > 1)
            {
                // Every offer any variant names is suspect, whichever variant arrived first.
                count(diagnostics, "conflicting_event_id");
                conflictKeys.addAll(keysById.get(c.getKey()));
            }
        }
        // Pass 2: one row per (offer_key, sequence), chosen without regard to arrival order.
        List<Map<String, Object>> offers = new ArrayList<>();
        for (Map.Entry<String, Map<Long, List<Map<String, Object>>>> g : grouped.entrySet())
        {
            Episode ep = new Episode(g.getKey());
            if (conflictKeys.contains(ep.key))
            {
                ep.quarantine.add("conflicting_event_id");
            }
            for (List<Map<String, Object>> rows : g.getValue().values())
            {
                Set<String> contents = new TreeSet<>();
                Set<String> ids = new TreeSet<>();
                int unnamed = 0;
                for (Map<String, Object> r : rows)
                {
                    contents.add(canonical(r));
                    if (r.get("event_id") instanceof String) ids.add((String) r.get("event_id"));
                    else unnamed++;
                }
                if (contents.size() > 1)
                {
                    count(diagnostics, "conflicting_sequence");
                    ep.quarantine.add("conflicting_sequence");
                }
                // A replay with a new event_id but the same observation is not another fill.
                add(diagnostics, "duplicate_event_id_dropped", rows.size() - ids.size() - unnamed);
                add(diagnostics, "duplicate_sequence_dropped", ids.size() + unnamed - 1);
                rows.sort((a, b) ->
                {
                    String ia = a.get("event_id") instanceof String ? (String) a.get("event_id") : "￿";
                    String ib = b.get("event_id") instanceof String ? (String) b.get("event_id") : "￿";
                    int c = ia.compareTo(ib);
                    return c != 0 ? c : canonical(a).compareTo(canonical(b));
                });
                ep.rows.add(rows.get(0));
            }
            offers.add(record(ep));
        }
        offers.sort((a, b) ->
        {
            Long fa = num(a.get("first_seen_at_ms")), fb = num(b.get("first_seen_at_ms"));
            int c = Long.compare(fa == null ? Long.MAX_VALUE : fa, fb == null ? Long.MAX_VALUE : fb);
            return c != 0 ? c : String.valueOf(a.get("offer_key")).compareTo(String.valueOf(b.get("offer_key")));
        });
        supersede(offers, diagnostics);
        List<Map<String, Object>> unmatched = joinHistory(offers, history, diagnostics);
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("record_schema_v", RECORD_SCHEMA_V);
        out.put("derivation", DERIVATION);
        out.put("generation", generation);
        out.put("generation_source", "caller_supplied");
        out.put("offers", offers);
        out.put("history_only", unmatched);
        out.put("diagnostics", new LinkedHashMap<>(diagnostics));
        return out;
    }

    static Map<String, Object> reduce(List<Map<String, Object>> events, List<Map<String, Object>> history)
    {
        return reduce(events, history, null);
    }

    private static Map<String, Object> record(Episode ep)
    {
        Map<String, Object> first = ep.rows.get(0);
        Map<?, ?> firstObs = (Map<?, ?>) first.get("ge_observation");
        Set<String> gaps = new LinkedHashSet<>();
        Set<String> quarantine = new LinkedHashSet<>(ep.quarantine);
        String identity = "inferred_session_slot";
        List<Map<String, Object>> fills = new ArrayList<>();
        Long placedAt = null, completedAt = null, cancelledAt = null, collectedAt = null, lastCounterAt = null;
        long[] firstFill = null, completion = null, cancel = null;
        boolean firstFillSeen = false, collected = false;
        String phase = "open";
        long previousSeq = 0, previousQty = -1, previousGp = -1;
        long creditedQty = 0, creditedGp = 0;
        boolean placementObserved = false;
        long baselineQty = 0, baselineGp = 0;

        Long item = num(first.get("item")), totalQty = num(first.get("qty_total")), price = num(first.get("price"));
        String side = first.get("side") instanceof String ? (String) first.get("side") : null;
        Long slot = num(first.get("slot"));
        if (item == null || item <= 0 || totalQty == null || totalQty <= 0 || price == null || price < 0
            || !("buy".equals(side) || "sell".equals(side)) || slot == null || slot < 0 || slot > 7)
        {
            quarantine.add("missing_offer_terms");
        }

        // The tracker's first row decides the baseline. Only a ge_offer the tracker saw being placed
        // proves placement: a terminal first row can follow an unseen zero-counter replay seed.
        String firstStatus = firstObs.get("delta_status") instanceof String ? (String) firstObs.get("delta_status") : null;
        Long firstFromQty = num(firstObs.get("delta_from_qty")), firstFromGp = num(firstObs.get("delta_from_gp"));
        if ("baseline_only".equals(firstStatus))
        {
            Long cq = num(firstObs.get("cumulative_qty")), cg = num(firstObs.get("cumulative_gp"));
            baselineQty = cq == null ? 0 : cq;
            baselineGp = cg == null ? 0 : cg;
            if (cq == null || cg == null) quarantine.add("missing_baseline_fields");
        }
        else if (firstFromQty != null && firstFromGp != null && firstStatus != null)
        {
            baselineQty = firstFromQty;
            baselineGp = firstFromGp;
        }
        else
        {
            quarantine.add("missing_baseline_fields");
        }
        placementObserved = "ge_offer".equals(first.get("type")) && "placed".equals(first.get("offer_seen"))
            && seq(first) == 1 && baselineQty == 0 && baselineGp == 0;
        if (placementObserved)
        {
            placedAt = num(firstObs.get("observed_at_ms"));
        }
        else if (baselineQty == 0 && baselineGp == 0)
        {
            gaps.add("placement_unconfirmed_zero_baseline");
        }
        else
        {
            gaps.add("placement_not_observed_earlier_fills_uncredited");
        }
        if (seq(first) != 1)
        {
            gaps.add("earlier_rows_missing");
        }

        for (int i = 0; i < ep.rows.size(); i++)
        {
            Map<String, Object> r = ep.rows.get(i);
            Map<?, ?> o = (Map<?, ?>) r.get("ge_observation");
            String type = String.valueOf(r.get("type"));
            long sequence = seq(r);
            Long at = num(o.get("observed_at_ms"));
            if (!sameSignature(first, r))
            {
                quarantine.add("signature_changed_within_offer_key");
            }
            identity = worse(identity, o.get("identity"));
            if (i > 0 && sequence != previousSeq + 1)
            {
                gaps.add("missing_rows_between_observations");
            }
            if ("unknown".equals(o.get("delta_status")))
            {
                quarantine.add("tracker_delta_unknown");
            }
            Long cq = num(o.get("cumulative_qty")), cg = num(o.get("cumulative_gp"));
            Long fromQty = num(o.get("delta_from_qty")), fromGp = num(o.get("delta_from_gp"));
            if (cq == null || cg == null || cq < 0 || cg < 0 || (totalQty != null && cq > totalQty))
            {
                quarantine.add("missing_counter");
                continue;
            }
            if (previousQty >= 0 && (cq < previousQty || cg < previousGp))
            {
                quarantine.add("counter_regression");
            }
            if (previousQty >= 0 && fromQty != null && fromGp != null && (fromQty != previousQty || fromGp != previousGp))
            {
                // A row was lost: the counter difference is still recoverable, its timing is not.
                gaps.add("missing_rows_between_observations");
            }
            Long dq = num(o.get("delta_qty")), dg = num(o.get("delta_gp"));
            if ("observed_counter_difference".equals(o.get("delta_status")))
            {
                if (dq == null || dg == null || fromQty == null || fromGp == null
                    || cq - fromQty != dq || cg - fromGp != dg || dq < 0 || dg < 0
                    || (dq == 0) != (dg == 0))
                {
                    quarantine.add("inconsistent_counter_pair");
                }
                else if (dq > 0)
                {
                    Map<String, Object> fill = new LinkedHashMap<>();
                    fill.put("sequence", sequence);
                    fill.put("qty", dq);
                    fill.put("gp", dg);
                    fill.put("interval_start_ms", num(o.get("interval_start_ms")));
                    fill.put("interval_end_ms", num(o.get("interval_end_ms")));
                    fill.put("fill_time", "unknown_within_interval");
                    fill.put("avg_gp_per_unit_proxy", ratio(dg, dq));
                    fills.add(fill);
                    creditedQty += dq;
                    creditedGp += dg;
                    if (!firstFillSeen)
                    {
                        firstFillSeen = true;
                        firstFill = interval(o);
                    }
                }
            }
            previousQty = cq;
            previousGp = cg;
            previousSeq = sequence;
            lastCounterAt = at;
            if ("ge_buy".equals(type) || "ge_sell".equals(type))
            {
                phase = "completed";
                completedAt = at;
                completion = interval(o);
            }
            else if ("ge_cancel".equals(type))
            {
                phase = "cancelled";
                cancelledAt = at;
                cancel = interval(o);
            }
            else if ("ge_collect".equals(type))
            {
                collected = true;
                collectedAt = at;
                if ("open".equals(phase))
                {
                    // The collect row carries the slot's last state; a terminal row may have been lost.
                    String state = String.valueOf(r.get("state"));
                    phase = state.startsWith("CANCELLED") ? "cancelled" : "BOUGHT".equals(state) || "SOLD".equals(state)
                        ? "completed" : "unknown";
                    gaps.add("terminal_row_not_observed");
                }
            }
        }
        if ("ambiguous_counter_regression".equals(identity))
        {
            quarantine.add("ambiguous_identity");
        }
        if ("inferred_across_gap".equals(identity))
        {
            gaps.add("observation_gap_logout_or_hop");
        }
        if (previousQty < 0)
        {
            quarantine.add("missing_counter");
        }
        if (previousQty >= 0 && (previousQty < baselineQty || previousGp < baselineGp))
        {
            quarantine.add("counter_regression");
        }
        boolean quarantined = !quarantine.isEmpty();
        long finalQty = Math.max(previousQty, 0), finalGp = Math.max(previousGp, 0);
        Long observedQty = quarantined ? null : finalQty - baselineQty;
        Long observedGp = quarantined ? null : finalGp - baselineGp;
        if (!collected)
        {
            gaps.add("not_collected_yet_or_collect_not_observed");
        }

        Map<String, Object> rec = new LinkedHashMap<>();
        rec.put("record_schema_v", RECORD_SCHEMA_V);
        rec.put("derivation", DERIVATION);
        rec.put("offer_key", ep.key);
        rec.put("offer_key_scope", "collector_session");
        rec.put("account_hash", first.get("account_hash"));
        rec.put("profile_type", first.get("profile_type"));
        rec.put("slot", num(first.get("slot")));
        rec.put("item_id", item);
        rec.put("side", side);
        rec.put("listing_price", price);
        rec.put("total_qty", totalQty);
        rec.put("placement", placementObserved ? "observed" : "not_observed");
        rec.put("placed_observed_at_ms", placedAt);
        rec.put("first_seen_at_ms", num(firstObs.get("observed_at_ms")));
        rec.put("phase", phase);
        rec.put("completed_at_observed_ms", completedAt);
        rec.put("cancelled_at_observed_ms", cancelledAt);
        rec.put("collected", collected);
        rec.put("collected_at_observed_ms", collectedAt);
        rec.put("superseded_by", null);
        rec.put("counter_qty", previousQty < 0 ? null : finalQty);
        rec.put("counter_gp", previousGp < 0 ? null : finalGp);
        rec.put("baseline_qty_uncredited", baselineQty);
        rec.put("baseline_gp_uncredited", baselineGp);
        rec.put("filled_qty_observed", observedQty);
        rec.put("filled_gp_observed", observedGp);
        rec.put("fills", quarantined ? Collections.emptyList() : fills);
        rec.put("untimed_fill_qty", quarantined ? null : observedQty - creditedQty);
        rec.put("first_fill_interval_ms", quarantined ? null : list(firstFill));
        rec.put("completion_interval_ms", quarantined || !placementObserved ? null : list(completion));
        rec.put("cancel_interval_ms", quarantined ? null : list(cancel));
        rec.put("fill_time", "unknown_within_intervals");
        rec.put("identity", identity);
        rec.put("quarantined", quarantined);
        rec.put("quarantine_reasons", new ArrayList<>(quarantine));
        rec.put("gaps", new ArrayList<>(gaps));
        rec.put("completeness", completeness(quarantined, placementObserved, collected, gaps));
        rec.put("cashflow", quarantined ? quarantinedCashflow()
            : cashflow(side, price, finalQty, finalGp, observedQty, observedGp));
        rec.put("escrow", quarantined || "unknown".equals(phase)
            ? unknownEscrow(lastCounterAt, identity, quarantined ? "quarantined" : "phase_unknown")
            : escrow(side, price, totalQty, finalQty, finalGp, phase, collected, collectedAt, lastCounterAt, identity));
        rec.put("history_corroboration", null);
        List<Object> ids = new ArrayList<>();
        for (Map<String, Object> r : ep.rows)
        {
            ids.add(r.get("event_id"));
        }
        rec.put("contributing_event_ids", ids);
        rec.put("as_of_observed_ms", lastCounterAt);
        return rec;
    }

    private static String completeness(boolean quarantined, boolean placement, boolean collected, Set<String> gaps)
    {
        if (quarantined) return "quarantined";
        return placement && collected && !gaps.contains("missing_rows_between_observations")
            && !gaps.contains("terminal_row_not_observed") && !gaps.contains("superseded_by_later_offer_key_same_slot")
            ? "complete_observed_lifecycle" : "partial";
    }

    /**
     * The tracker starts a new offer_key after a restart, account/profile/token change or a
     * re-baseline, even for the same live offer. An uncollected key keeps its escrow only when it
     * started strictly after every other key in its slot was last seen. Otherwise it ended
     * unobserved, continues under a later key, or the clocks cannot order them: escrow unknown.
     */
    @SuppressWarnings("unchecked")
    private static void supersede(List<Map<String, Object>> offers, Map<String, Object> diagnostics)
    {
        Map<String, List<Map<String, Object>>> fences = new TreeMap<>();
        for (Map<String, Object> offer : offers)
        {
            String fence = offer.get("account_hash") + "|" + offer.get("profile_type") + "|" + offer.get("slot");
            fences.computeIfAbsent(fence, k -> new ArrayList<>()).add(offer);
        }
        for (List<Map<String, Object>> fence : fences.values())
        {
            if (fence.size() < 2)
            {
                continue;
            }
            for (Map<String, Object> u : fence)
            {
                if (Boolean.TRUE.equals(u.get("collected")))
                {
                    continue;
                }
                Long start = num(u.get("first_seen_at_ms")), end = num(u.get("as_of_observed_ms"));
                // A key whose own clock ran backwards cannot be ordered against anything.
                boolean latest = start != null && end != null && end >= start;
                Map<String, Object> next = null;
                boolean nextTied = false, contradicted = false;
                for (Map<String, Object> o : fence)
                {
                    if (o == u) continue;
                    Long otherEnd = num(o.get("as_of_observed_ms")), otherStart = num(o.get("first_seen_at_ms"));
                    if (start == null || otherEnd == null || otherEnd >= start)
                    {
                        latest = false;
                    }
                    if (!Boolean.TRUE.equals(o.get("collected")) && sameTerms(u, o) && !countersAgreeWithClocks(u, o))
                    {
                        // Same offer terms: the key the clocks call later must re-baseline at or above
                        // the earlier key's counter. Otherwise the clocks are wrong (e.g. a step back).
                        latest = false;
                        contradicted = true;
                    }
                    if (end != null && otherStart != null && otherStart > end)
                    {
                        Long best = next == null ? null : num(next.get("first_seen_at_ms"));
                        if (best == null || otherStart < best)
                        {
                            next = o;
                            nextTied = false;
                        }
                        else if (otherStart.equals(best))
                        {
                            nextTied = true;
                        }
                    }
                }
                if (latest)
                {
                    continue;
                }
                boolean ordered = next != null && !nextTied && !contradicted;
                String reason = ordered ? "superseded_by_later_offer_key_same_slot" : "slot_order_ambiguous";
                u.put("superseded_by", ordered ? next.get("offer_key") : null);
                if ("open".equals(u.get("phase")))
                {
                    u.put("phase", "unknown");
                }
                ((List<String>) u.get("gaps")).add(reason);
                if (!Boolean.TRUE.equals(u.get("quarantined")))
                {
                    u.put("completeness", "partial");
                }
                u.put("escrow", unknownEscrow(end, String.valueOf(u.get("identity")), reason));
                count(diagnostics, ordered ? "superseded_offer_keys" : "slot_order_ambiguous_offer_keys");
            }
        }
    }

    private static Map<String, Object> quarantinedCashflow()
    {
        Map<String, Object> c = new LinkedHashMap<>();
        c.put("gp_counter_semantics", "runelite_spent_tax_unknown");
        c.put("status", "unknown_quarantined");
        return c;
    }

    /** Realized GP from credited counter differences. A buy refund and sell tax are qualified. */
    private static Map<String, Object> cashflow(String side, long price, long finalQty, long finalGp, long qty, long gp)
    {
        Map<String, Object> c = new LinkedHashMap<>();
        c.put("gp_counter_semantics", "runelite_spent_tax_unknown");
        c.put("status", "credited_counter_difference");
        if ("buy".equals(side))
        {
            c.put("coins_paid_gp", gp);
            c.put("items_bought", qty);
            // Coins put up at the listing price minus coins spent return at collection.
            c.put("overpay_refund_gp_whole_offer", price * finalQty - finalGp);
            c.put("tax_gp", 0L);
            c.put("tax_status", "no_tax_on_buys");
            return c;
        }
        c.put("items_sold", qty);
        c.put("gp_counter", gp);
        c.put("tax_gp", null);
        putTaxRule(c, qty, gp, "spent_is_gross_field_observed_once_0742; item_exemptions_not_checked");
        return c;
    }

    /**
     * Per-item tax is floor(2% of that item's price), items under 50 gp exempt, capped per item.
     * Mixed prices inside one counter change are unknown, so the sum lies in
     * [floor(2% of gross) - qty + 1, floor(2% of gross)].
     */
    private static void putTaxRule(Map<String, Object> c, long qty, long gross, String assumption)
    {
        Long low = null, high = null;
        String status;
        if (qty == 0)
        {
            status = "no_sale";
            low = high = 0L;
        }
        else if (gross > TAX_CAP_PER_ITEM_GP * 50)
        {
            // Some item may be above the 250M price where the per-item cap binds.
            status = "unknown_cap_may_apply";
        }
        else
        {
            high = gross * 2 / 100;
            low = Math.max(0, high - qty + 1);
            if (gross < TAX_EXEMPT_BELOW_UNIT_GP * qty)
            {
                low = 0L;
            }
            status = low.equals(high) ? "rule_exact_if_gp_is_gross_and_item_not_exempt"
                : "rule_range_if_gp_is_gross_and_item_not_exempt";
        }
        c.put("tax_status", status);
        c.put("tax_rule_low_gp", low);
        c.put("tax_rule_high_gp", high);
        c.put("net_gp_rule_low", high == null ? null : gross - high);
        c.put("net_gp_rule_high", low == null ? null : gross - low);
        c.put("tax_assumption", assumption);
    }

    private static Map<String, Object> unknownEscrow(Long asOf, String identity, String basis)
    {
        Map<String, Object> e = new LinkedHashMap<>();
        e.put("as_of_observed_ms", asOf);
        e.put("basis", basis);
        e.put("escrow_state", "unknown");
        e.put("gap_or_reset_seen", !"inferred_session_slot".equals(identity));
        return e;
    }

    /** Escrow for a wealth ledger from the last observed absolute counters. Partial collection is unobservable. */
    private static Map<String, Object> escrow(String side, long price, long total, long qty, long gp, String phase,
        boolean collected, Long collectedAt, Long asOf, String identity)
    {
        Map<String, Object> e = new LinkedHashMap<>();
        boolean open = "open".equals(phase);
        boolean cancelled = "cancelled".equals(phase);
        e.put("as_of_observed_ms", collected ? collectedAt : asOf);
        e.put("basis", collected ? "slot_emptied_while_logged_in" : "last_observed_counter");
        e.put("escrow_state", "observed");
        e.put("gap_or_reset_seen", !"inferred_session_slot".equals(identity));
        e.put("filled_qty", qty);
        if (collected)
        {
            e.put("locked_coins", 0L);
            e.put("locked_items", 0L);
            e.put("uncollected_items_max", 0L);
            e.put("uncollected_coins_max", 0L);
            e.put("collection_note", "collect_is_not_proof_of_arrival_match_container_change");
            return e;
        }
        long lockedCoins, lockedItems, items, coins;
        if ("buy".equals(side))
        {
            lockedCoins = open ? price * (total - qty) : 0L;
            lockedItems = 0L;
            items = qty;
            coins = price * qty - gp + (cancelled ? price * (total - qty) : 0L);
        }
        else
        {
            lockedCoins = 0L;
            lockedItems = open ? total - qty : 0L;
            items = cancelled ? total - qty : 0L;
            coins = gp;
            e.put("coins_semantics", "gp_counter_tax_unknown");
        }
        if (lockedCoins < 0 || lockedItems < 0 || items < 0 || coins < 0)
        {
            // A buy can never spend more than its listing price allows; counters disagree with terms.
            return unknownEscrow(asOf, identity, "counters_inconsistent_with_offer_terms");
        }
        e.put("locked_coins", lockedCoins);
        e.put("locked_items", lockedItems);
        e.put("uncollected_items_max", items);
        e.put("uncollected_coins_max", coins);
        e.put("uncollected_semantics", "upper_bound_partial_collection_unobserved");
        return e;
    }

    /**
     * GE history rows have no time and no order ID. Join only a one-to-one match on item, side,
     * offer quantity and counters. A match corroborates the counters and, for a sell, gives the
     * displayed tax. Never adds a fill.
     */
    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> joinHistory(List<Map<String, Object>> offers,
        List<Map<String, Object>> history, Map<String, Object> diagnostics)
    {
        List<Map<String, Object>> unmatched = new ArrayList<>();
        if (history == null)
        {
            return unmatched;
        }
        List<Map<String, Object>> rows = new ArrayList<>();
        for (Object raw : (List<?>) history)
        {
            Map<String, Object> row = stringKeyed(raw);
            if (row == null) count(diagnostics, "history_row_invalid");
            else rows.add(row);
        }
        List<List<Integer>> rowMatches = new ArrayList<>();
        int[] offerMatchCount = new int[offers.size()];
        for (Map<String, Object> row : rows)
        {
            List<Integer> found = new ArrayList<>();
            for (int i = 0; i < offers.size(); i++)
            {
                Map<String, Object> offer = offers.get(i);
                if (Boolean.TRUE.equals(offer.get("quarantined")) || "open".equals(offer.get("phase"))
                    || "unknown".equals(offer.get("phase")))
                {
                    continue;
                }
                if (Objects.equals(num(row.get("item_id")), num(offer.get("item_id")))
                    && Objects.equals(row.get("side"), offer.get("side"))
                    && Objects.equals(num(row.get("quantity")), num(offer.get("counter_qty")))
                    && counterMatch(row, offer) != null)
                {
                    found.add(i);
                    offerMatchCount[i]++;
                }
            }
            rowMatches.add(found);
        }
        for (int r = 0; r < rows.size(); r++)
        {
            List<Integer> found = rowMatches.get(r);
            Map<String, Object> row = rows.get(r);
            if (found.isEmpty())
            {
                unmatched.add(historyOnly(row));
                continue;
            }
            if (found.size() != 1)
            {
                count(diagnostics, "history_row_ambiguous");
                continue;
            }
            if (offerMatchCount[found.get(0)] != 1)
            {
                count(diagnostics, "history_offer_ambiguous");
                continue;
            }
            Map<String, Object> offer = offers.get(found.get(0));
            String basis = counterMatch(row, offer);
            Map<String, Object> h = new LinkedHashMap<>();
            h.put("match", "unique_item_side_qty_counter");
            h.put("counter_equals", basis);
            h.put("history_gross_gp", num(row.get("original_gross_gp")));
            h.put("history_tax_gp", num(row.get("explicit_tax_gp")));
            h.put("history_net_gp", num(row.get("displayed_net_gp")));
            h.put("history_execution_time", "unknown");
            h.put("history_verified_with_actual_client", row.get("verified_with_actual_client"));
            offer.put("history_corroboration", h);
            Map<String, Object> c = (Map<String, Object>) offer.get("cashflow");
            Long tax = num(row.get("explicit_tax_gp")), gross = num(row.get("original_gross_gp")),
                net = num(row.get("displayed_net_gp"));
            if ("sell".equals(offer.get("side")) && tax != null && gross != null && net != null
                && Objects.equals(num(c.get("gp_counter")), num(offer.get("counter_gp"))))
            {
                // Exact only when the whole offer was credited; the history total is the whole offer.
                boolean counterIsGross = "history_gross".equals(basis);
                c.put("gp_counter_semantics", counterIsGross ? "matches_history_gross_one_offer"
                    : "matches_history_net_one_offer");
                // The rule range is always computed on the gross value, never on a net that is already taxed.
                putTaxRule(c, num(offer.get("counter_qty")), gross, "history_gross; item_exemptions_not_checked");
                c.put("tax_gp", tax);
                c.put("net_gp", net);
                Long low = num(c.get("tax_rule_low_gp")), high = num(c.get("tax_rule_high_gp"));
                c.put("tax_status", "history_explicit_offer_total");
                if (low != null && high != null && (tax < low || tax > high))
                {
                    // Exemption, cap or a rule change: keep the displayed value and flag the disagreement.
                    c.put("tax_rule_disagrees_with_history", true);
                }
            }
            count(diagnostics, "history_joined");
        }
        unmatched.sort((a, b) -> canonical(a).compareTo(canonical(b)));
        return unmatched;
    }

    /**
     * A finished offer seen only in the GE history UI, e.g. made on mobile or with the plugin off.
     * It proves an offer total existed in the recent list. It has no time, no slot, no fills and no
     * order ID, and two equal rows cannot be told apart from one repeated snapshot row.
     */
    private static Map<String, Object> historyOnly(Map<String, Object> row)
    {
        Map<String, Object> h = new LinkedHashMap<>();
        h.put("item_id", num(row.get("item_id")));
        h.put("side", row.get("side") instanceof String ? row.get("side") : null);
        h.put("quantity", num(row.get("quantity")));
        h.put("gross_gp", num(row.get("original_gross_gp")));
        h.put("tax_gp", num(row.get("explicit_tax_gp")));
        h.put("net_gp", num(row.get("displayed_net_gp")));
        h.put("displayed_total_gp", num(row.get("displayed_total_gp")));
        h.put("recoverable", "offer_total_only");
        h.put("execution_time", "unknown");
        h.put("placement_and_fills", "unknown");
        h.put("may_overlap_unobserved_or_earlier_session_offers", true);
        return h;
    }

    private static String counterMatch(Map<String, Object> row, Map<String, Object> offer)
    {
        Long gp = num(offer.get("counter_gp"));
        if (gp == null) return null;
        if (gp.equals(num(row.get("original_gross_gp")))) return "history_gross";
        if (gp.equals(num(row.get("displayed_net_gp")))) return "history_net";
        if (num(row.get("original_gross_gp")) == null && gp.equals(num(row.get("displayed_total_gp"))))
            return "history_displayed_total";
        return null;
    }

    private static boolean countersAgreeWithClocks(Map<String, Object> a, Map<String, Object> b)
    {
        Long aStart = num(a.get("first_seen_at_ms")), aEnd = num(a.get("as_of_observed_ms"));
        Long bStart = num(b.get("first_seen_at_ms")), bEnd = num(b.get("as_of_observed_ms"));
        Map<String, Object> earlier, later;
        if (aEnd != null && bStart != null && aEnd < bStart) { earlier = a; later = b; }
        else if (bEnd != null && aStart != null && bEnd < aStart) { earlier = b; later = a; }
        else return false;
        if ("observed".equals(later.get("placement"))
            && ("completed".equals(earlier.get("phase")) || "cancelled".equals(earlier.get("phase"))))
        {
            // A finished offer never becomes active again: an observed placement after it is a new
            // identical offer (a relist), so its zero baseline is expected.
            return true;
        }
        Long base = num(later.get("baseline_qty_uncredited")), counter = num(earlier.get("counter_qty"));
        return base != null && counter != null && base >= counter;
    }

    private static boolean sameTerms(Map<String, Object> a, Map<String, Object> b)
    {
        return Objects.equals(a.get("item_id"), b.get("item_id")) && Objects.equals(a.get("side"), b.get("side"))
            && Objects.equals(a.get("total_qty"), b.get("total_qty"))
            && Objects.equals(a.get("listing_price"), b.get("listing_price"));
    }

    private static boolean sameSignature(Map<String, Object> a, Map<String, Object> b)
    {
        return Objects.equals(num(a.get("item")), num(b.get("item"))) && Objects.equals(a.get("side"), b.get("side"))
            && Objects.equals(num(a.get("qty_total")), num(b.get("qty_total")))
            && Objects.equals(num(a.get("price")), num(b.get("price")))
            && Objects.equals(num(a.get("slot")), num(b.get("slot")))
            && Objects.equals(a.get("account_hash"), b.get("account_hash"));
    }

    private static String worse(String a, Object b)
    {
        int ia = IDENTITY_RANK.indexOf(a), ib = IDENTITY_RANK.indexOf(b);
        if (ib < 0) return "ambiguous_counter_regression"; // an unknown label is never trusted
        return ib > ia ? (String) b : a;
    }

    private static long[] interval(Map<?, ?> o)
    {
        Long s = num(o.get("interval_start_ms")), e = num(o.get("interval_end_ms"));
        return s == null || e == null ? null : new long[]{s, e};
    }

    private static List<Long> list(long[] v)
    {
        return v == null ? null : java.util.Arrays.asList(v[0], v[1]);
    }

    private static String ratio(long gp, long qty)
    {
        return new java.math.BigDecimal(gp).divide(new java.math.BigDecimal(qty), 4, java.math.RoundingMode.HALF_EVEN)
            .stripTrailingZeros().toPlainString();
    }

    private static long seq(Map<String, Object> e)
    {
        Long v = num(((Map<?, ?>) e.get("ge_observation")).get("sequence"));
        return v == null ? 0 : v;
    }

    /** Content identity without transport-only envelope fields. Numbers compare by value, not type. */
    private static String canonical(Map<String, Object> e)
    {
        Map<String, Object> copy = new TreeMap<>();
        for (Map.Entry<?, ?> x : ((Map<?, ?>) e).entrySet())
        {
            String k = String.valueOf(x.getKey());
            // Gson omits nulls by default, so an absent field and a null field are the same content.
            if (x.getValue() != null && !"event_id".equals(k) && !"ts".equals(k) && !"received_at".equals(k)
                && !"token_fp".equals(k) && !k.startsWith("_"))
            {
                copy.put(k, normal(x.getValue()));
            }
        }
        return copy.toString();
    }

    /** A row with only String keys, or null; raw or polluted input is skipped, never fatal. */
    @SuppressWarnings("unchecked")
    private static Map<String, Object> stringKeyed(Object raw)
    {
        if (!(raw instanceof Map)) return null;
        for (Object k : ((Map<?, ?>) raw).keySet())
        {
            if (!(k instanceof String)) return null;
        }
        return (Map<String, Object>) raw;
    }

    private static Object normal(Object v)
    {
        if (v instanceof Number)
        {
            Long n = num(v);
            return n != null ? "n" + n : "d" + ((Number) v).doubleValue();
        }
        if (v instanceof Map)
        {
            Map<String, Object> m = new TreeMap<>();
            for (Map.Entry<?, ?> x : ((Map<?, ?>) v).entrySet())
            {
                if (x.getValue() != null) m.put(String.valueOf(x.getKey()), normal(x.getValue()));
            }
            return m;
        }
        if (v instanceof List)
        {
            List<Object> l = new ArrayList<>();
            for (Object x : (List<?>) v) l.add(normal(x));
            return l;
        }
        return v;
    }

    private static Long num(Object o)
    {
        if (o instanceof Long || o instanceof Integer || o instanceof Short) return ((Number) o).longValue();
        if (o instanceof Number)
        {
            double d = ((Number) o).doubleValue();
            return d == Math.rint(d) && Math.abs(d) < 9.0e15 ? (long) d : null;
        }
        return null;
    }

    private static void count(Map<String, Object> d, String key)
    {
        add(d, key, 1);
    }

    private static void add(Map<String, Object> d, String key, long n)
    {
        if (n <= 0) return;
        Long v = num(d.get(key));
        d.put(key, (v == null ? 0 : v) + n);
    }
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * loadout.revision.v1: ordered worn-equipment revisions for ONE caller-supplied generation (account/profile/mode
 * session). Pure and deterministic. The caller (shared adapter) owns the generation key; this class never joins
 * two independently generated session IDs. Agreed with C2 on 2026-10-19.
 *
 * Rules:
 * - No observation yet = no revision. Unknown equipment is never an empty loadout.
 * - The first observation of a generation, and the first after a gap, is a "baseline", never a change.
 * - Only a different slot -> item id map makes a new revision. Quantity changes (ammo, darts) do not.
 * - content_id = sha256 of the canonical slot map, so the same gear joins across generations.
 * - Inventory Setups are not an input: they are global RuneLite config with no account binding.
 */
final class LoadoutRevision
{
    static final String SCHEMA = "loadout.revision.v1";
    /** EquipmentInventorySlot indices 0..13; 8 (HAIR) and 11 (JAW) are body kit, never worn items. */
    private static final String[] SLOT_NAMES = {"head", "cape", "amulet", "weapon", "body", "shield", null, "legs",
        null, "gloves", "boots", null, "ring", "ammo"};
    static final int MAX_REVISIONS = 256;
    /** C4 WealthLedger.owns location lists that qualify a "no" answer. */
    static final String[] HOLDINGS_GAPS = {"unknown_locations", "stale_locations", "bounded_locations", "unsupported_locations",
        "undated_locations", "carried_locations"};

    private final String generation;
    private final List<Map<String, Object>> revisions = new ArrayList<>();
    private Map<Integer, Integer> current;
    private boolean gap = true;
    private int evicted;
    /** {revision_seq the gap followed, gap tick}: the gap ends that revision's validity. */
    private final List<int[]> gaps = new ArrayList<>();

    LoadoutRevision(String generation)
    {
        if (generation == null || generation.isEmpty()) throw new IllegalArgumentException("generation required");
        this.generation = generation;
    }

    /** The client lost sight of the equipment (logout, hop, region gap): the next observation is a baseline. */
    void gap(int tick)
    {
        if (!gap) gaps.add(new int[]{revisions.size() + evicted, tick});
        gap = true;
        if (gaps.size() > MAX_REVISIONS) gaps.remove(0);
    }

    /**
     * Records one observed worn-equipment state. slotItemIds: equipment slot index -> item id, only occupied slots.
     * Returns the new revision, or null when the item-id map did not change.
     */
    Map<String, Object> observe(Map<Integer, Integer> slotItemIds, int tick, long observedAtMs)
    {
        if (slotItemIds == null) return null; // container unavailable is unknown, not empty
        Map<Integer, Integer> slots = new TreeMap<>();
        for (Map.Entry<Integer, Integer> e : slotItemIds.entrySet())
        {
            Integer slot = e.getKey(), item = e.getValue();
            if (slot == null || slot < 0 || slot >= SLOT_NAMES.length || SLOT_NAMES[slot] == null) continue;
            if (item != null && item > 0) slots.put(slot, item);
        }
        boolean baseline = gap || current == null;
        if (!baseline && slots.equals(current)) return null;
        // A baseline that matches the last known map still records a revision: it proves the gear at that time.
        Map<String, Object> rev = new LinkedHashMap<>();
        rev.put("schema", SCHEMA);
        rev.put("generation", generation);
        rev.put("revision_seq", revisions.size() + evicted + 1);
        rev.put("tick", tick);
        rev.put("observed_at_ms", observedAtMs);
        rev.put("provenance", baseline ? "baseline" : "observed_change");
        rev.put("content_id", contentId(slots));
        rev.put("slots", named(slots));
        rev.put("previous_content_id", baseline ? null : contentId(current));
        current = slots;
        gap = false;
        Map<String, Object> frozen = Collections.unmodifiableMap(rev);
        revisions.add(frozen);
        if (revisions.size() > MAX_REVISIONS)
        {
            revisions.remove(0);
            evicted++;
        }
        return frozen;
    }

    /**
     * Revision active at tick (max revision_seq with tick <= at), or null when the gear is unknown at that tick:
     * before the first retained revision, or inside a gap that no later baseline has closed yet.
     */
    Map<String, Object> activeAt(int tick)
    {
        Map<String, Object> best = null;
        for (Map<String, Object> rev : revisions)
        {
            if ((Integer) rev.get("tick") <= tick) best = rev;
        }
        if (best == null) return null;
        int seq = (Integer) best.get("revision_seq");
        for (int[] g : gaps)
        {
            if (g[0] == seq && g[1] <= tick) return null;
        }
        return best;
    }

    List<Map<String, Object>> revisions()
    {
        return Collections.unmodifiableList(revisions);
    }

    int evicted()
    {
        return evicted;
    }

    String generation()
    {
        return generation;
    }

    /**
     * Adapter helper: worn container items (index = EquipmentInventorySlot index) to the observe() input.
     * Returns null for a missing container, so "unavailable" never becomes an empty loadout.
     */
    static Map<Integer, Integer> slotsOf(net.runelite.api.Item[] worn)
    {
        if (worn == null) return null;
        Map<Integer, Integer> out = new TreeMap<>();
        for (int i = 0; i < worn.length && i < SLOT_NAMES.length; i++)
        {
            if (worn[i] != null && worn[i].getId() > 0 && worn[i].getQuantity() > 0) out.put(i, worn[i].getId());
        }
        return out;
    }

    /** Canonical "slot=item;" string over named slots in index order, hashed. Stable across generations. */
    static String contentId(Map<Integer, Integer> slots)
    {
        StringBuilder canon = new StringBuilder("loadout.v1;");
        for (Map.Entry<Integer, Integer> e : new TreeMap<>(slots).entrySet())
        {
            canon.append(SLOT_NAMES[e.getKey()]).append('=').append(e.getValue()).append(';');
        }
        return AccountConnectPlugin.sha256Hex(canon.toString());
    }

    private static Map<String, Object> named(Map<Integer, Integer> slots)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        for (Map.Entry<Integer, Integer> e : slots.entrySet()) out.put(SLOT_NAMES[e.getKey()], e.getValue());
        return Collections.unmodifiableMap(out);
    }

    /**
     * Ownership context for one revision from C4 holdings. owns is C4 WealthLedger.owns (item id -> answer map
     * with "answer" yes|no_in_observed_locations|unknown and location lists). Worn at the revision is observed;
     * current holdings come only from C4. A null holdings source or a missing answer stays unknown.
     */
    static Map<String, Object> ownership(Map<String, Object> revision, java.util.function.IntFunction<? extends Map<?, ?>> owns)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        Map<?, ?> slots = (Map<?, ?>) revision.get("slots");
        for (Map.Entry<?, ?> e : slots.entrySet())
        {
            int item = ((Number) e.getValue()).intValue();
            Map<?, ?> answer = owns == null ? null : owns.apply(item);
            Object a = answer == null ? null : answer.get("answer");
            // "yes" from only stale, undated or carried readings is ownership that may be out of date.
            String state = "yes".equals(a) ? (seenFresh(answer.get("seen")) ? "owned_observed" : "owned_possibly_outdated")
                : "no_in_observed_locations".equals(a) ? "not_seen_in_observed" : "unknown";
            Map<String, Object> slot = new LinkedHashMap<>();
            slot.put("item_id", item);
            slot.put("worn_at_revision", true);
            slot.put("current_holdings", state);
            // not_seen_in_observed can hold while a store is stale, bounded (GE collect box) or unsupported, so
            // every C4 gap list is carried. A null list means no C4 answer, not "nothing missing".
            for (String gap : HOLDINGS_GAPS) slot.put(gap, answer == null ? null : answer.get(gap));
            out.put((String) e.getKey(), slot);
        }
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("content_id", revision.get("content_id"));
        result.put("revision_seq", revision.get("revision_seq"));
        result.put("slots", out);
        result.put("holdings_source", owns == null ? "unavailable" : "c4_wealth_ledger_owns");
        return result;
    }

    /** True when at least one C4 seen row was read in the current snapshot (state "observed" or "bounded"). */
    private static boolean seenFresh(Object seen)
    {
        if (!(seen instanceof List)) return false;
        for (Object row : (List<?>) seen)
        {
            Object state = row instanceof Map ? ((Map<?, ?>) row).get("state") : null;
            if ("observed".equals(state) || "bounded".equals(state)) return true;
        }
        return false;
    }
}

package com.osrsbestinslot.export;

import java.util.*;
import java.util.regex.*;
import net.runelite.api.*;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/** Narrow own-account acquisition. Values remain absolute observations, never rewards or deltas. */
final class OwnActivityCapture
{
    private final OwnGameplayCapture out;
    private int messageTick = -1, deathTick = -1;
    private final Set<String> messages = new HashSet<>();
    private static final Pattern CONTRACT_TOTAL = Pattern.compile("You have completed ([0-9,]+) contracts with a total of ([0-9,]+) points?\\.");
    private static final Pattern CHOMPY_TOTAL = Pattern.compile("You've scratched up a total of ([0-9,]+) chompy bird kills?\\.");
    private static final Pattern COAL = Pattern.compile("The coal bag (?:still )?contains (one|[0-9]+) pieces? of coal\\.");
    private static final Pattern COMPOST = Pattern.compile("You treat the [A-Za-z -]{1,80} with (ultra|super|)compost\\.");
    // Pinned rumour-reminder 38a5b7ae message prefix and public game creature names.
    // The trailing instruction is checked for shape, then discarded; it is never telemetry.
    private static final Pattern RUMOUR_TARGET = Pattern.compile("Your current rumour target is (?:a|an) ([A-Za-z -]{1,40})\\. You'll [A-Za-z ,'-]{1,160}[.!]?");
    private static final Set<String> RUMOUR_TARGETS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        "tropical wagtail", "wild kebbit", "sapphire glacialis", "swamp lizard", "spined larupia",
        "barb-tailed kebbit", "snowy knight", "prickly kebbit", "embertailed jerboa", "horned graahk",
        "spotted kebbit", "black warlock", "orange salamander", "razor-backed kebbit", "sabre-toothed kebbit",
        "red chinchompa", "chinchompa", "sabre-toothed kyatt", "dark kebbit", "pyre fox", "red salamander",
        "sunlight moth", "sunlight antelope", "dashing kebbit", "moonlight moth", "tecu salamander",
        "herbiboar", "moonlight antelope")));
    static boolean rumourTargetCode(Object code)
    {
        if(!(code instanceof String))return false;
        for(String name:RUMOUR_TARGETS)if(name.replace(' ','_').replace('-','_').equals(code))return true;
        return false;
    }
    private static final String[] ROOMS = {"The Maiden of Sugadinti", "Pestilent Bloat", "Nylocas Prinkipas", "Nylocas Vasilias", "Sotetseg", "Xarpus", "Verzik Vitur"};

    static boolean raidRoom(Object value) { return value instanceof String && Arrays.asList(ROOMS).contains(value); }

    OwnActivityCapture(OwnGameplayCapture out) { this.out = out; }
    void reset() { messageTick = deathTick = -1; messages.clear(); }

    private void bits(Client c, int[] vars, String family, String[] keys, int[] ids, long at)
    {
        Map<String,Object> value = new LinkedHashMap<>();
        for (int i=0; i<ids.length; i++) value.put(keys[i], AccountProgressCapture.bit(c,vars,ids[i]));
        out.state(family, "varbits:"+Arrays.toString(ids), value, c.getTickCount(), at);
    }

    void poll(Client c, int[] vars, long at)
    {
        Map<String,Object> potions = new LinkedHashMap<>();
        potions.put("storage_values_raw", OwnPotionStorageCapture.raw(vars));
        potions.put("unlocked_raw", AccountProgressCapture.bit(c,vars,11295));
        potions.put("units", "unverified_not_doses_or_bottles");
        out.state("storage.potion_store", "RuneLite1.13.1:113_named_varps;varbit:11295", potions,c.getTickCount(),at);

        // Read fixed own progress fields; task identity and reward decoding remain unverified.
        Map<String,Object> port = new LinkedHashMap<>();
        int[] taskVars = {VarPlayerID.PORT_TASKS_0,VarPlayerID.PORT_TASKS_1,VarPlayerID.PORT_TASKS_2,
            VarPlayerID.PORT_TASKS_3,VarPlayerID.PORT_TASKS_4,VarPlayerID.PORT_TASKS_GENERAL};
        Map<String,Object> slots = new LinkedHashMap<>();
        for (int id : taskVars) slots.put(String.valueOf(id),AccountProgressCapture.varp(vars,id));
        port.put("packed_slots_raw",slots);
        port.put("completed_total_raw",AccountProgressCapture.varp(vars,VarPlayerID.PORT_TASKS_COMPLETED));
        port.put("bounty_item_counter_raw",AccountProgressCapture.varp(vars,VarPlayerID.PORT_TASKS_BOUNTY_ITEM_COUNTER));
        port.put("extra_slots_raw",AccountProgressCapture.bit(c,vars,VarbitID.PORT_TASK_EXTRA_SLOTS_UNLOCKED));
        port.put("completed_today_raw",AccountProgressCapture.bit(c,vars,VarbitID.PORT_TASKS_COMPLETED_TODAY));
        port.put("interpretation","task_identity_and_reward_unverified");
        out.state("sailing.port_tasks", "RuneLite1.13.1:8_named_varps;varbits:19589,19591", port,c.getTickCount(),at);

        bits(c,vars,"minigame.tears",new String[]{"countdown_raw","tears_raw","collecting_raw"},new int[]{5099,455,453},at);
        // Only the local player's contribution, never team bottles or other players' scoreboards.
        bits(c,vars,"minigame.brewing",new String[]{"own_contribution_raw"},new int[]{2290},at);
        bits(c,vars,"minigame.restaurant_order",new String[]{"started_raw","customer_id_raw","order_id_raw","refused_hard_raw"},new int[]{2478,2484,2483,2485},at);
        bits(c,vars,"minigame.plunder_state",new String[]{"timer_raw","room_raw"},new int[]{2375,2377},at);
        bits(c,vars,"sailing.trial_progress",new String[]{"tempor_tantrum_raw","jubbly_jive_raw","gwenith_glide_raw"},new int[]{18427,18432,18437},at);
        bits(c,vars,"storage.bank_tabs",new String[]{"tab_1_slots","tab_2_slots","tab_3_slots","tab_4_slots","tab_5_slots","tab_6_slots","tab_7_slots","tab_8_slots","tab_9_slots"},new int[]{4171,4172,4173,4174,4175,4176,4177,4178,4179},at);

        Map<String,Object> totems = new LinkedHashMap<>();
        totems.put("research_points_raw", AccountProgressCapture.varp(vars,4764));
        for (int site=0; site<OwnActivityMappings.TOTEMS.length; site++)
        {
            Map<String,Object> fields = new LinkedHashMap<>();
            for (int f=0; f<OwnActivityMappings.TOTEM_FIELDS.length; f++)
                fields.put(OwnActivityMappings.TOTEM_FIELDS[f], AccountProgressCapture.bit(c,vars,OwnActivityMappings.TOTEMS[site][f]));
            totems.put("site_"+(site+1),fields);
        }
        out.state("minigame.totem_state","varp:4764;varbits:17611-17748 audited site projection",totems,c.getTickCount(),at);
        Map<String,Object> chart = new LinkedHashMap<>();
        for(int id:OwnActivityMappings.CHARTING) chart.put(String.valueOf(id),AccountProgressCapture.bit(c,vars,id));
        out.state("sailing.charting","358 pinned completion varbits; keys are varbit IDs",chart,c.getTickCount(),at);

        Map<String,Object> special = new LinkedHashMap<>();
        special.put("energy_raw",AccountProgressCapture.varp(vars,300));
        // A decrease is not evidence of a particular hit, target defence or a teammate action.
        out.state("combat.special_attack","varp:300",special,c.getTickCount(),at);
        raid(c,vars,at);
    }

    private Map<String,Object> raid(Client c, int[] vars, long at)
    {
        Integer status=AccountProgressCapture.bit(c,vars,6440);
        Map<String,Object> value=new LinkedHashMap<>(); value.put("party_status_raw",status);
        String room=null;
        if (Integer.valueOf(2).equals(status))
        {
            Widget parent=c.getWidget(28,1);
            Widget child=parent==null || parent.isHidden() ? null : parent.getChild(2);
            String label=child==null || child.isHidden() ? "" : clean(child.getText());
            for(String known:ROOMS) if(known.equals(label)) room=known;
        }
        value.put("room_observed",room); // HUD disappearance clears context instead of retaining stale text.
        out.state("combat.raid_context","varbit:6440;visible widget:28.1 child:2 allowlist",value,c.getTickCount(),at);
        return value;
    }

    void death(Client c, Actor actor, long at)
    {
        if(actor==null || actor!=c.getLocalPlayer() || c.getTickCount()==deathTick) return;
        deathTick=c.getTickCount();
        Map<String,Object> context=raid(c,c.getVarps(),at);
        if(!Integer.valueOf(2).equals(context.get("party_status_raw"))) return;
        Map<String,Object> value=new LinkedHashMap<>(context);
        value.put("actor","self"); value.put("classification","observed_own_death_not_team_wipe");
        out.append("combat.tob_room_death","ActorDeath:self",c.getTickCount(),at,value);
    }

    static String clean(String text)
    {
        if(text==null || text.length()>512) return "";
        return Text.removeTags(text.replace("<br>"," ")).trim();
    }

    static Long number(String text)
    {
        if(text==null || !text.matches("(?:0|[1-9][0-9]{0,9}|[1-9][0-9]{0,2}(?:,[0-9]{3}){1,3})")) return null;
        try { return Long.parseLong(text.replace(",","")); } catch(NumberFormatException e) { return null; }
    }

    void chat(Client c, ChatMessage event, long at)
    {
        ChatMessageType type=event.getType();
        if(type!=ChatMessageType.GAMEMESSAGE && type!=ChatMessageType.SPAM) return;
        String text=clean(event.getMessage());
        if(text.isEmpty()) return;
        if(type==ChatMessageType.GAMEMESSAGE && text.startsWith("Your party failed to complete the challenge"))
            out.scene.reset(); // discard hazard continuity; do not upload party text or infer team deaths
        // Bound duplicate callback suppression to a tick; never infer a lifetime/session count.
        if(messageTick!=c.getTickCount()) { messages.clear(); messageTick=c.getTickCount(); }
        Map<String,Object> value=new LinkedHashMap<>();
        String family=null;
        Matcher m=CONTRACT_TOTAL.matcher(text);
        if(type==ChatMessageType.GAMEMESSAGE && m.matches())
        {
            Long contracts=number(m.group(1)), points=number(m.group(2));
            if(contracts==null || points==null) return;
            value.put("contracts_absolute",contracts); value.put("points_absolute",points);
            family="minigame.construction_contract";
        }
        else if(type==ChatMessageType.SPAM && text.equals("You scratch a notch on your bow for the chompy bird kill."))
        {
            value.put("signal","notch_observed"); value.put("total_kills",null); family="combat.chompy_kc";
        }
        else if(type==ChatMessageType.GAMEMESSAGE && (m=CHOMPY_TOTAL.matcher(text)).matches())
        {
            Long total=number(m.group(1)); if(total==null) return;
            value.put("signal","absolute_check"); value.put("total_kills",total); family="combat.chompy_kc";
        }
        else if(type==ChatMessageType.GAMEMESSAGE && (m=Pattern.compile("Your quetzal whistle has ([0-9]+) charges remaining\\.").matcher(text)).matches())
        {
            Long charges=number(m.group(1)); if(charges==null) return;
            value.put("whistle_charges_observed",charges); family="hunter.rumour";
        }
        else if(type==ChatMessageType.GAMEMESSAGE && (m=RUMOUR_TARGET.matcher(text)).matches())
        {
            String target=m.group(1).toLowerCase(Locale.ROOT);
            if(!RUMOUR_TARGETS.contains(target)) return;
            value.put("signal","whistle_target");
            value.put("target_observed",target.replace(' ','_').replace('-','_'));
            value.put("turn_in_verified",false); family="hunter.rumour";
        }
        else if(type==ChatMessageType.GAMEMESSAGE && text.equals("You do not have an active rumour right now."))
        {
            // Absence observed now is not proof of a turn-in or of what happened during a gap.
            value.put("signal","whistle_no_active"); value.put("target_observed",null);
            value.put("turn_in_verified",false); family="hunter.rumour";
        }
        else if((m=COAL.matcher(text)).matches())
        {
            Long count="one".equals(m.group(1))?1L:number(m.group(1)); if(count==null || count>54) return;
            value.put("count_observed",count); family="storage.coal_bag";
        }
        else if(text.equals("The coal bag is empty.") || text.equals("The coal bag is now empty."))
        {
            value.put("count_observed",0L); family="storage.coal_bag";
        }
        else if(text.matches("(?:Your grape barrel is (?:now|already) full|The grape barrel is (?:empty|partially full))\\."))
        {
            value.put("fill_observed",text.contains("partially")?"partial":text.contains("empty")?"empty":"full"); family="storage.grape_barrel";
        }
        else if((m=COMPOST.matcher(text)).matches())
        {
            value.put("compost_type",m.group(1).isEmpty()?"normal":m.group(1)); value.put("patch_identity","unknown");
            family="farming.compost"; // Never attach a stale menu target/patch or emit the raw patch text.
        }
        if(family!=null && messages.size()<64 && messages.add(family+":"+value))
            out.append(family,"ChatMessage:"+type+":exact_english_projection",c.getTickCount(),at,value);
    }
}

package com.osrsbestinslot.export;

import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/** Passive, own-bank cache interpretation. No widget items, inventory sum, prices or game actions. */
final class OwnBankTabsCapture
{
    static final int MAX_SLOTS = 4096;
    private final OwnGameplayCapture out;
    private int[][] observed;
    private int packetTick;
    private long packetAt;
    OwnBankTabsCapture(OwnGameplayCapture out) { this.out = out; }
    void reset() { observed = null; packetTick = -1; packetAt = 0; }

    void container(int id, ItemContainer container, int tick, long at)
    {
        if (id != InventoryID.BANK) return;
        observed = copy(container); packetTick = tick; packetAt = at;
    }

    private static int[][] copy(ItemContainer container)
    {
        Item[] items = container == null ? null : container.getItems();
        if (items == null || items.length > MAX_SLOTS) return null;
        int[][] result = new int[items.length][2];
        for (int i = 0; i < items.length; i++)
        {
            Item item = items[i];
            if (item == null || item.getQuantity() < 0 || item.getId() < -1
                || item.getId() <= 0 && item.getQuantity() > 0) return null;
            result[i][0] = item.getId(); result[i][1] = item.getQuantity();
        }
        return result;
    }

    void built(Client client, long at)
    {
        Map<String,Object> value = new LinkedHashMap<>();
        value.put("basis", "inferred_raw_tab_ranges_same_session_cached_bank");
        value.put("complete", false);
        value.put("container_observed_at_ms", observed == null ? null : packetAt);
        value.put("tabs", null); value.put("untabbed", null);
        String status = "own_bank_packet_unavailable";
        if (observed != null)
        {
            int[] vars = client.getVarps();
            Integer tab = AccountProgressCapture.bit(client, vars, VarbitID.BANK_CURRENTTAB);
            Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
            if (at < packetAt || client.getTickCount() < packetTick) status = "clock_or_tick_gap";
            else if (bank == null || bank.isHidden() || tab == null || tab < 0 || tab > 9)
                status = "ordinary_bank_ui_unavailable"; // excludes potion storage's synthetic tab15
            else if (!Arrays.deepEquals(observed, copy(client.getItemContainer(InventoryID.BANK))))
                status = "bank_cache_changed_without_packet";
            else
            {
                Integer[] counts = new Integer[9]; long total = 0; boolean valid = true;
                for (int i = 0; i < counts.length; i++)
                {
                    counts[i] = AccountProgressCapture.bit(client, vars, 4171 + i);
                    if (counts[i] == null || counts[i] < 0) valid = false;
                    else total += counts[i];
                }
                if (!valid) status = "tab_counts_unknown";
                else if (total > observed.length) status = "tab_counts_exceed_container";
                else
                {
                    List<Map<String,Object>> tabs = new ArrayList<>(); int start = 0;
                    for (int i = 0; i < counts.length; i++)
                    {
                        Map<String,Object> range = range(start, counts[i]); range.put("tab", i + 1);
                        tabs.add(range); start += counts[i];
                    }
                    value.put("tabs", tabs);
                    // Tab0 in the UI displays all items, not just this remainder.
                    value.put("untabbed", range(start, observed.length - start));
                    status = "observed_cache_ranges";
                }
            }
        }
        value.put("status", status);
        out.state("storage.bank_tab_currency", "own_bank_packet+bankmain_build+tab_counts:4171-4179",
            value, client.getTickCount(), at, false);
    }

    private Map<String,Object> range(int start, int count)
    {
        long coins = 0, platinum = 0;
        for (int i = start; i < start + count; i++)
        {
            if (observed[i][0] == ItemID.COINS) coins += observed[i][1];
            if (observed[i][0] == ItemID.PLATINUM) platinum += observed[i][1];
        }
        Map<String,Object> row = new LinkedHashMap<>();
        row.put("start_slot", start); row.put("slot_count", count);
        row.put("coins", coins); row.put("platinum_tokens", platinum);
        row.put("currency_gp_equivalent", coins + platinum * 1000L);
        return row;
    }
}

package com.osrsbestinslot.export;

import java.util.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.cluescrolls.clues.MapClue;
import net.runelite.client.plugins.cluescrolls.clues.CoordinateClue;

/** Own clue observations plus fixed public library facts. No drop owner, actual route or completed timer. */
final class OwnClueProjection
{
    static final Set<String> SIGNALS=Set.of("clues.owned_ground","clues.ground_gap","world.scene_gap");
    static boolean supports(Object kind) { return kind instanceof String&&SIGNALS.contains(kind); }
    static String source(String kind)
    {return kind.equals("clues.owned_ground")?"own_client_ground":"own_client_capacity";}
    static boolean sourceMatches(String kind,Object source,Map<?,?> raw)
    {
        switch(kind) {
            case "clues.owned_ground":return "appeared".equals(raw.get("observation"))
                ?"RuneLite1.13.1:TileItem_ownership_and_server_ticks".equals(source)
                :"left_scene".equals(raw.get("observation"))&&"RuneLite1.13.1:tracked_self_ItemDespawned".equals(source);
            case "clues.ground_gap":return "bounded_self_ground_clue_capacity".equals(source);
            case "world.scene_gap":return "bounded object observation capacity".equals(source);
            default:return false;
        }
    }
    static Map<String,Object> inventory(Map<?,?> p)
    {
        Object raw=p.get("inventory_map_coordinate_clues");Map<String,Object> clues=null;
        if(raw!=null)
        {
            Map<?,?> entries=map(raw);if(entries.size()>28)throw new IllegalArgumentException();clues=new TreeMap<>();
            for(Map.Entry<?,?> entry:entries.entrySet())
            {
                if(!(entry.getKey() instanceof String)||!((String)entry.getKey()).matches("[1-9][0-9]{0,5}"))throw new IllegalArgumentException();
                int id=Integer.parseInt((String)entry.getKey());MapClue mc=MapClue.forItemId(id);CoordinateClue cc=mc==null?CoordinateClue.forItemId(id):null;
                if(mc==null&&cc==null)throw new IllegalArgumentException();WorldPoint point=mc!=null?mc.getLocation(null):cc.getLocation(null);
                Map<?,?> v=map(entry.getValue());String kind=mc!=null?"map":"coordinate";
                if(!kind.equals(v.get("kind"))||!"library_base_location_not_resolved_quest_alternative".equals(v.get("qualification"))
                    ||num(v.get("x"),0,16383)!=point.getX()||num(v.get("y"),0,16383)!=point.getY()||num(v.get("plane"),0,3)!=point.getPlane())throw new IllegalArgumentException();
                clues.put((String)entry.getKey(),Map.of("kind",kind,"x",(long)point.getX(),"y",(long)point.getY(),"plane",(long)point.getPlane(),
                    "qualification","library_base_location_not_resolved_quest_alternative"));
            }
        }
        Map<String,Object> out=new LinkedHashMap<>();out.put("inventory_map_coordinate_clues",clues);out.put("complete",false);
        out.put("source_table","runelite_1_13_1_primary");return out;
    }
    static Map<String,Object> signal(String kind,Map<?,?> p)
    {
        if(!kind.equals("clues.owned_ground"))
        {
            String gap=kind.equals("clues.ground_gap")?"observation_capacity":"object_capacity";
            if(!gap.equals(p.get("gap")))throw new IllegalArgumentException();return Map.of("gap",gap);
        }
        Object id=p.get("observation_id");if(!(id instanceof String))throw new IllegalArgumentException();String observationId=((String)id).replace("-","");
        if(!((String)id).matches("[a-f0-9]{32}|[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"))throw new IllegalArgumentException();
        int item=(int)num(p.get("item_id"),1,Integer.MAX_VALUE);
        if(item!=ItemID.TRAIL_CLUE_BEGINNER&&item!=ItemID.TRAIL_CLUE_MASTER&&MapClue.forItemId(item)==null&&CoordinateClue.forItemId(item)==null)throw new IllegalArgumentException();
