package com.osrsbestinslot.export;

import com.google.gson.*;
import java.util.*;

/** Legacy D1 bank receipts, negotiated separately from Queue and the staff spool. */
final class PublicBankProtocol
{
    static final String SCOPE = "bank-visit-v1";
    private static final Set<String> TYPES = new HashSet<>(Arrays.asList(
        "bank_visit_open", "bank_visit_manifest_chunk", "bank_visit_close"));
    private PublicBankProtocol() {}

    static boolean allows(Map<String,Object> event)
    {
        Object id = event.get("event_id");
        return TYPES.contains(event.get("type")) && id instanceof String && ((String)id).matches("[a-f0-9]{32}");
    }

    static EventQueueProtocol.ReceiptSet receipts(int code, String body, List<Map<String,Object>> batch)
    {
        EventQueueProtocol.ReceiptSet out = new EventQueueProtocol.ReceiptSet(batch.size());
        if (code < 200 || code >= 300) return out;
        try
        {
            JsonObject root = new JsonParser().parse(body).getAsJsonObject();
            JsonElement ok = root.get("ok");
            if (ok == null || !ok.isJsonPrimitive() || !ok.getAsJsonPrimitive().isBoolean() || !ok.getAsBoolean()) return out;
            Map<String,Integer> indices = new HashMap<>();
            for (int i=0;i<batch.size();i++)
            {
                if (!allows(batch.get(i)) || indices.put((String)batch.get(i).get("event_id"),i) != null) return out;
            }
            Set<String> seen = new HashSet<>();
            for (JsonElement element : root.getAsJsonArray("results"))
            {
                JsonObject row = element.getAsJsonObject();
                JsonElement id = row.get("event_id"), status = row.get("status");
                if (id == null || !id.isJsonPrimitive() || !id.getAsJsonPrimitive().isString()
                    || status == null || !status.isJsonPrimitive() || !status.getAsJsonPrimitive().isString())
                    return new EventQueueProtocol.ReceiptSet(batch.size());
                if (!seen.add(id.getAsString())) return new EventQueueProtocol.ReceiptSet(batch.size());
                Integer i = indices.get(id.getAsString());
                if (i == null) continue;
                String value = status.getAsString();
                if ("stored".equals(value) || "duplicate".equals(value))
                    out.outcomes.set(i,EventQueueProtocol.Outcome.DURABLE);
                else if ("filtered".equals(value)) out.outcomes.set(i,EventQueueProtocol.Outcome.REJECTED);
                // A D1 receipt is not an archive or Queue broker receipt: stages remain NONE.
            }
        }
        catch (RuntimeException invalid) { return new EventQueueProtocol.ReceiptSet(batch.size()); }
        return out;
    }
}

package com.osrsbestinslot.export;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.function.LongSupplier;

/**
 * Bounded public queue-v1 journal. All methods run on the plugin's disk executor.
 * Uses the existing forced journal and tombstones, in a root separate from staff.
 * It owns projected event rows only, never snapshots, credentials or gameplay actions.
 */
final class PublicEventOutbox
{
    static final class Context
    {
        final String identity;
        final String account;
        final String mode;
        Context(String token, String account, String mode, String profile)
        {
            if (token == null || !token.matches("[a-f0-9]{32}") || account == null || account.isEmpty()
                || "-1".equals(account) || mode == null || "UNKNOWN".equals(mode)
                || !mode.matches("[A-Z_]{1,64}") || profile == null || profile.isEmpty())
                throw new IllegalArgumentException("public outbox requires a settled identity");
            this.account = account;
            this.mode = mode;
            // Length-delimited identity components; raw token/profile never reach disk.
            identity = EventSpool.identityKey(token, "public-v1:" + account.length() + ":" + account
                + ":" + mode.length() + ":" + mode + ":" + profile.length() + ":" + profile);
        }
        boolean owns(Map<String, Object> event)
        {
            return account.equals(event.get("account_hash"))
                && mode.equals(event.getOrDefault("profile_type", "STANDARD"));
        }
    }

    private final Path data;
    private final Path root;
    private final Gson gson;
    private final LongSupplier clock;
    private final EventSpool.Limits limits;
    private final boolean bankOnly;
    final EventSpool.Counters counters = new EventSpool.Counters();
    private EventSpool journal;
    private Context context;

    PublicEventOutbox(Path data, Gson gson, LongSupplier clock)
    {
        this(data, gson, clock, EventSpool.Limits.DEFAULT);
    }

    PublicEventOutbox(Path data, Gson gson, LongSupplier clock, EventSpool.Limits limits)
    {
        this(data,gson,clock,limits,false);
    }

    PublicEventOutbox(Path data, Gson gson, LongSupplier clock, EventSpool.Limits limits, boolean bankOnly)
    {
        this.data = data;
        this.root = data.resolve("osrsbis").resolve(bankOnly ? "public-bank-events-v1" : "public-events-v1");
        this.bankOnly = bankOnly;
        this.gson = gson;
        this.clock = clock;
        this.limits = limits;
    }

    /** No grant or no settled account means no open, recovery or replay. */
    boolean activate(Context next) throws IOException
    {
        if (next == null) return false;
        if (context != null && context.identity.equals(next.identity) && journal != null)
        {
            if (journal.purgeRequested())
            {
                // Remove this writer's sensitive payload now. Keep the marker/closed handle so
                // the same stale grant cannot reopen it on the following tick.
                journal.closeAndDeleteOwn();
                return false;
            }
            if (!journal.isFailed()) return true;
            // A compaction reopen failure leaves recoverable rows on disk. Retire the failed
            // writer and recover under the same still-valid context, as the staff adapter does.
        }
        close();
        // A normal account/profile change is not an erasure or ACK. Retain recent
        // identities for a later matching grant; age and append-time index bounds still apply.
        EventSpool.sweepAged(root, clock, limits.maxAgeMs, counters);
        Path dir = root.resolve(next.identity);
        if (Files.exists(dir.resolve(EventSpool.MARKER))) return false;
        EventSpool opened = new EventSpool(data, dir, clock, EventSpool.ATOMIC, limits, counters);
        if (Files.isDirectory(dir)) opened.recover();
        journal = opened;
        context = next;
        return true;
    }

    /** Returns true only for a row still present after a forced append and bound enforcement. */
    boolean append(Context owner, String scope, Map<String, Object> input) throws IOException
    {
        Map<String, Object> event = PublicTransport.event(input);
        if (owner == null || event == null || !owner.owns(event) || !knownType(event) || !allows(scope, event))
            return false;
        event.remove("rsn"); // account_hash and the token-bound context suffice for public Queue routing
        Object timestamp = event.get("ts");
        if (!(timestamp instanceof Number) || ((Number) timestamp).longValue() <= 0) return false;
        String json = gson.toJson(event);
        if (json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length >= AccountConnectPlugin.EVENT_BATCH_MAX_BYTES)
        {
            counters.dropped.incrementAndGet();
            return false;
        }
        if (!activate(owner)) return false;
        // Persist the hashed recovery/purge pointer before the first sensitive row.
        EventSpool.writePointer(data, root, owner.identity, clock.getAsLong());
        String id = (String) event.get("event_id");
        long created = Math.min(((Number) timestamp).longValue(), clock.getAsLong());
        boolean appended = journal.append(id, String.valueOf(event.get("type")), created, json);
        journal.maybeCompact();
        boolean retained = appended && journal.get(id) != null;
        if (retained) retireOutsideIndex(owner.identity);
        return retained;
    }

    private void retireOutsideIndex(String active) throws IOException
    {
        // writePointer has already forced this identity into the existing newest16 index.
        // Do not evict for an empty pending() probe, or if index integrity is unavailable.
        EventSpool.Locked index = EventSpool.lock(root.resolve(EventSpool.INDEX_LOCK));
        if (index == null) return; // retry cleanup on a later append; this row is already durable
        try
        {
            Set<String> retained = new HashSet<>(EventSpool.readIndex(root));
            // A missing/short index is not evidence that unknown older directories exceeded
            // the bound. Keep them until a complete recent index or explicit withdrawal.
            if (retained.size() != EventSpool.MAX_INDEX || !retained.contains(active)) return;
            for (String old : knownIdentities())
                if (!retained.contains(old)
                    && Files.isDirectory(root.resolve(old), java.nio.file.LinkOption.NOFOLLOW_LINKS)
                    && EventSpool.purgeIfIdle(root.resolve(old)))
                    counters.purged.incrementAndGet();
        }
        finally { index.close(); }
        // Live sibling locks are never overridden; they may temporarily exceed the index bound.
    }

    /** Re-project recovered rows and re-check ownership before exposing any payload. */
    List<Map<String, Object>> pending(Context owner, String scope, int maximum) throws IOException
    {
        List<Map<String, Object>> result = new ArrayList<>();
        if (maximum <= 0 || !activate(owner)) return result;
        journal.enforceBoundsNow();
        List<String> rejected = new ArrayList<>();
        for (EventSpool.Record row : journal.pending())
        {
            Map<String, Object> event;
            try { event = PublicTransport.event(gson.fromJson(row.eventJson, Map.class)); }
            catch (RuntimeException invalid) { event = null; }
            if (event == null || !owner.owns(event) || !row.eventId.equals(event.get("event_id"))
                || !knownType(event))
            {
                rejected.add(row.eventId);
                continue;
            }
            // A narrower grant pauses retained broader rows; it does not acknowledge them.
            if (allows(scope, event) && result.size() < maximum) result.add(event);
        }
        journal.quarantine(rejected, -1);
        return result;
    }

    static boolean allows(String scope, Map<String,Object> event)
    {
        return PublicBankProtocol.SCOPE.equals(scope) ? PublicBankProtocol.allows(event) : EventQueueProtocol.allows(scope,event);
    }

    private boolean knownType(Map<String,Object> event)
    {
        return bankOnly ? PublicBankProtocol.allows(event) : EventQueueProtocol.allows("own-signals-v1",event);
    }

    /** Only validated per-ID queue outcomes settle rows, including partial non-2xx receipts. */
    void settle(Context sentOwner, List<Map<String, Object>> sent, List<EventQueueProtocol.Outcome> outcomes)
        throws IOException
    {
        if (context == null || sentOwner == null || !context.identity.equals(sentOwner.identity)
            || journal == null || outcomes.size() != sent.size()) return;
        List<String> accepted = new ArrayList<>(), rejected = new ArrayList<>();
        for (int i = 0; i < sent.size(); i++)
        {
            String id = String.valueOf(sent.get(i).get("event_id"));
            if (!sentOwner.owns(sent.get(i)) || journal.get(id) == null) continue;
            switch (outcomes.get(i))
            {
                case ERASED:
                    purge();
                    return;
                case DURABLE: accepted.add(id); break;
                case REJECTED: rejected.add(id); break;
                default: break;
            }
        }
        counters.acked.addAndGet(journal.ack(accepted));
        journal.quarantine(rejected, -2);
        journal.maybeCompact();
    }

    /** Explicit withdrawal: mark known live siblings and retire idle retry payloads. */
    void purge() throws IOException
    {
        String active = context == null ? null : context.identity;
        if (journal != null) journal.closeAndDeleteOwn();
        journal = null;
        context = null;
        if (active != null)
        {
            EventSpool.purgeIdentityDir(root.resolve(active), clock);
            EventSpool.deletePointerIf(root, active);
        }
        // A cold client can receive revocation or clear its token before any grant/recovery.
        // Use only hashed pointers; never open payloads or mark an unrelated live writer.
        for (String old : knownIdentities())
            if (EventSpool.purgeIfIdle(root.resolve(old)))
                EventSpool.deletePointerIf(root, old);
        counters.purged.incrementAndGet();
    }

    /** The bounded index is a hint, not proof that no older local identity exists. */
    private Set<String> knownIdentities() throws IOException
    {
        Set<String> identities = new LinkedHashSet<>(EventSpool.readIndex(root));
        if (Files.isDirectory(root, java.nio.file.LinkOption.NOFOLLOW_LINKS))
            try (java.nio.file.DirectoryStream<Path> dirs = Files.newDirectoryStream(root))
            {
                for (Path dir : dirs)
                    if (dir.getFileName().toString().matches("[a-f0-9]{32}")
                        && Files.isDirectory(dir, java.nio.file.LinkOption.NOFOLLOW_LINKS))
                        identities.add(dir.getFileName().toString());
            }
        return identities;
    }

    /** A late account-erased receipt may only retire the identity that was sent. */
    void erase(Context erased) throws IOException
    {
        if (erased == null) return;
        if (context != null && context.identity.equals(erased.identity))
        {
            if (journal != null) journal.closeAndDeleteOwn();
            journal = null;
            context = null;
        }
        EventSpool.purgeIdentityDir(root.resolve(erased.identity), clock);
        EventSpool.deletePointerIf(root, erased.identity);
        counters.purged.incrementAndGet();
    }

    /** Logout/normal close retains retry rows; a future matching grant is required to recover. */
    void close()
    {
        if (journal != null) journal.close();
        journal = null;
        context = null;
    }

    int size() { return journal == null ? 0 : journal.pendingCount(); }
    long bytes() { return journal == null ? 0 : journal.pendingPayloadBytes(); }
    void crashForTest() { if (journal != null) journal.crashForTest(); journal = null; context = null; }
}

package com.osrsbestinslot.export;

import java.util.*;

/**
 * Public Hub wire contract. Remote grants, tokens and JVM properties cannot widen it for a player.
 * The one exception is staff capture, which the server grants only to an approved staff token and account.
 */
final class PublicTransport
{
    private PublicTransport() {}
    static boolean firehoseAllowed() { return false; }

    private static final Map<String, Set<String>> FIELDS = new HashMap<>();
    private static final Set<String> ENVELOPE = keys("type ts event_id account_hash rsn profile_type world world_members");
    private static final Set<String> ITEMS = keys("given received equipped unequipped items items_lost deposited withdrawn");
    static
    {
        allow("trade", "given received world world_members");
        allow("ge_offer ge_progress ge_buy ge_sell ge_cancel ge_collect",
            "item qty price gp qty_total slot state side offer_key offer_seen ge_observation world world_members");
        allow("store_buy store_sell", "item qty gp_total coins_unchanged qty_merged qty_executed qty_partial unit_price_gp world loc");
        allow("drop", "item qty location wilderness tile drop_session_id drop_seq");
        allow("ground_removed", "item qty location ticks_on_ground cause recipient drop_session_id drop_seq attribution_uncertain tile");
        allow("pickup alch", "item qty spell gp location");
        allow("login", "wealth world world_members");
        allow("logout", "wealth session_ms reason world world_members");
        allow("world_hop", "from to");
        allow("region", "from to x y");
        allow("death", "location death_kind items_lost");
        allow("equip_change", "equipped unequipped");
        allow("loot", "source_name source_type items value");
        allow("kill_count", "source kind count");
        allow("pet", ""); // the event is useful; unstructured chat text is not sent
        allow("level_up", "skill level xp");
        allow("xp_gain", "gains total");
        allow("bank_session", "deposited withdrawn complete truncated");
        allow("combat_hit combat_npc_end", "combat_schema gameplay_session source_sequence source_tick observed_at_ms source direction amount hitsplat_type npc_id target_key first_own_hit_tick end kill_credit");
        allow("own_vars", "");
        allow("own_signal", "");
        allow("own_state", ""); // the nested body uses the closed OwnStateEvent projection below
        allow("bank_visit_open", "visit_id opened_at_ms read_at_ms bank_state item_stacks manifest_sha256 plugin_version manifest_in_snapshot");
        allow("bank_visit_close", "visit_id closed_at_ms close_reason manifest_complete moves_complete deposited_sha256 withdrawn_sha256 end_manifest_sha256 end_chunks end_item_stacks manifest_in_snapshot deposited withdrawn deposited_chunks withdrawn_chunks moves_chunks");
        allow("bank_visit_manifest_chunk", "visit_id phase chunk chunks manifest_sha256 items");
        // No fh_batch, store_taken or media manifests: these are observations of others / Ops proof.
    }
    private static Set<String> keys(String s) { return new HashSet<>(Arrays.asList(s.split(" "))); }
    private static void allow(String types, String fields)
    {
        for (String type : types.split(" ")) FIELDS.put(type, keys(fields));
    }
    static boolean allowsEvent(String type) { return FIELDS.containsKey(type); }
    private static final Set<String> STAFF_EVENT_TYPES = keys("store_taken drop_trade_clip drop_trade_clip_final");
    static boolean allowsEvent(String type, boolean verifiedStaff)
    {
        return allowsEvent(type) || (verifiedStaff && STAFF_EVENT_TYPES.contains(type));
    }

    /**
     * The public projection, unless the server has granted staff capture to this exact token and account.
     * A staff row keeps every field the plugin wrote, as staff clients sent before the public boundary
     * (other players' names, counterparty, recipient, media manifests). Local delivery keys ("__...") never leave.
     */
    static Map<String, Object> event(Map<String, Object> input, boolean verifiedStaff)
    {
        Map<String, Object> standard = event(input);
        if (!verifiedStaff || input == null) return standard;
        String type = String.valueOf(input.get("type"));
        if (!allowsEvent(type, true)) return null;
        // A row the public projection refuses stays refused, unless it is one of the staff-only types.
        if (standard == null && !STAFF_EVENT_TYPES.contains(type)) return null;
        Map<String, Object> out = standard == null ? new LinkedHashMap<>() : standard;
        for (Map.Entry<String, Object> e : input.entrySet())
        {
            String key = e.getKey();
            Object value = e.getValue();
            if (key == null || key.startsWith("__")) continue;
            if ("observation_context".equals(key)) { out.put(key, EventObservationContext.project(value)); continue; }
            if (value == null || value instanceof String || value instanceof Number || value instanceof Boolean
                || value instanceof Map || value instanceof List)
                out.put(key, value);
        }
        return out;
    }

    /** null means local privacy rejection, never an acknowledged server delivery. */
    static Map<String, Object> event(Map<String, Object> input)
    {
        if (input == null) return null;
        String type = String.valueOf(input.get("type"));
        Set<String> fields = FIELDS.get(type);
        if (fields == null) return null;
        Map<String,Object> out = new LinkedHashMap<>();
        for (Map.Entry<String,Object> e : input.entrySet())
        {
            String k = e.getKey(); Object v = e.getValue();
            if ("observation_context".equals(k)) out.put(k, EventObservationContext.project(v));
            else if (ENVELOPE.contains(k))
            {
                if (v instanceof String || v instanceof Number || v instanceof Boolean) out.put(k,v);
            }
            else if (fields.contains(k))
            {
                if ("ge_observation".equals(k)) out.put(k, geObservation(v));
                else if (ITEMS.contains(k)) out.put(k, itemRows(v));
                else if ("location".equals(k) || "tile".equals(k))
                    out.put(k, numericMap(v, keys("x y plane region_id")));
                else if ("gains".equals(k) && v instanceof List)
                {
                    List<Map<String,Object>> gains = new ArrayList<>();
                    for (Object entry : (List<?>) v) if (entry instanceof Map)
                    {
                        Map<?,?> g = (Map<?,?>) entry;
                        if (g.get("skill") instanceof String && g.get("xp") instanceof Number)
                        {
                            Map<String,Object> gain = new LinkedHashMap<>();
                            gain.put("skill", g.get("skill")); gain.put("xp", g.get("xp")); gains.add(gain);
                        }
                    }
                    out.put(k, gains);
                }
                else if ("loc".equals(k) && v instanceof List)
                {
                    List<?> loc = (List<?>) v;
                    if (loc.size() == 3 && loc.stream().allMatch(n -> n instanceof Number))
                        out.put(k, new ArrayList<>(loc));
                }
                else if (v == null || v instanceof Number || v instanceof Boolean || v instanceof String)
                    out.put(k,v);
            }
        }
        // Legacy PvP loot must never bring the victim's name back through disk replay.
        if ("loot".equals(type) && !"npc".equals(input.get("source_type")) && !"event".equals(input.get("source_type")))
            out.remove("source_name");
        if ("ground_removed".equals(type)) out.put("recipient", "UNKNOWN");
        if ("own_signal".equals(type))
        {
            Map<String,Object> signal=OwnSignalEvent.wire(input);if(signal==null)return null;out.putAll(signal);
        }
        if ("own_vars".equals(type))
        {
            Map<String,Object> vars = OwnVarsEvent.wire(input);
            if (vars == null) return null;
            out.putAll(vars);
        }
        if ("own_state".equals(type))
        {
            Map<String,Object> state = OwnStateEvent.wire(input);
            if (state == null) return null;
            out.putAll(state);
        }
        return out;
    }
    private static Map<String,Object> geObservation(Object input)
    {
        Set<String> numbers = keys("schema_v sequence cumulative_qty cumulative_gp delta_from_qty delta_from_gp observed_at_ms counter_observed_at_ms listing_price execution_price tax_gp delta_qty delta_gp interval_start_ms interval_end_ms");
        Set<String> values = keys("runelite_grand_exchange_offer runelite_spent_tax_unknown ambiguous_counter_regression inferred_across_gap inferred_session_slot collector_session account_profile unknown baseline_only observed_counter_difference");
        Set<String> labels = keys("source gp_semantics identity offer_key_scope delta_status fill_time");
        Map<String,Object> out = new LinkedHashMap<>();
        if (input instanceof Map) for (Map.Entry<?,?> e : ((Map<?,?>) input).entrySet())
        {
            Object key = e.getKey(), value = e.getValue();
            if (numbers.contains(key) && (value == null || value instanceof Number)
                || labels.contains(key) && value instanceof String && values.contains(value))
                out.put((String) key, value);
        }
        return out;
    }
    private static Map<String,Object> numericMap(Object input, Set<String> allowed)
    {
        Map<String,Object> out = new LinkedHashMap<>();
        if (input instanceof Map) for (Map.Entry<?,?> e : ((Map<?,?>) input).entrySet())
            if (e.getKey() instanceof String && (allowed == null || allowed.contains(e.getKey())) && e.getValue() instanceof Number)
                out.put((String)e.getKey(), e.getValue());
        return out;
    }
    private static List<Object> itemRows(Object input)
    {
        List<Object> out = new ArrayList<>();
        if (input instanceof List) for (Object item : (List<?>) input)
        {
            // Bank manifests use integer pairs, both in-memory long[] and JSON replay Lists.
            if (item instanceof long[] && ((long[])item).length == 2)
            {
                out.add(((long[])item).clone()); continue;
            }
            if (item instanceof List)
            {
                List<?> pair = (List<?>)item;
                if (pair.size() == 2 && pair.get(0) instanceof Number && pair.get(1) instanceof Number)
                    out.add(Arrays.asList(((Number)pair.get(0)).longValue(), ((Number)pair.get(1)).longValue()));
                continue;
            }
            Map<String,Object> row = numericMap(item, keys("id qty slot"));
            if (row.containsKey("id") && row.containsKey("qty")) out.add(row);
        }
        return out;
    }
}

package com.osrsbestinslot.export;

import java.util.*;

/** Bounded process-local observations; no identities or payloads and no unique/completeness claim. */
final class QueueDeliveryHealth
{
    private static final Set<String> TYPES = new HashSet<>(Arrays.asList("ge_offer", "ge_progress", "ge_buy",
        "ge_sell", "ge_cancel", "ge_collect", "bank_session", "equip_change", "loot", "kill_count",
        "level_up", "xp_gain", "alch", "pickup", "combat_hit", "combat_npc_end"));
    private static final String[] COUNTERS = {"capture_handoffs", "forced_appends", "fallback_or_refused_handoffs",
        "broker_receipts", "archive_receipts", "retry_response_rows", "rejected_response_rows", "erased_response_rows"};
    private final Map<String,long[]> families = new TreeMap<>();

    private String family(Map<String,Object> event)
    {
        Object type = event.get("type");
        if (TYPES.contains(type)) return (String)type;
        Object kind = event.get("state_kind");
        if("own_signal".equals(type)&&OwnSignalEvent.supports(event.get("signal_kind")))return "own_signal_"+event.get("signal_kind");
        if ("own_vars".equals(type) && OwnVarsEvent.supports(event.get("var_family")))
            return "own_vars_" + event.get("var_family");
        if ("own_state".equals(type) && OwnStateEvent.supportsWireKind(kind))
            return "own_state_" + kind;
        return null;
    }
    private void count(Map<String,Object> event, int counter)
    {
        String family = family(event); if (family == null) return;
        long[] values = families.computeIfAbsent(family, ignored -> new long[COUNTERS.length]);
        if (values[counter] < Long.MAX_VALUE) values[counter]++;
    }
    synchronized void handoff(Map<String,Object> event) { count(event, 0); }
    synchronized void forced(Map<String,Object> event) { count(event, 1); }
    synchronized void undurable(Map<String,Object> event) { count(event, 2); }
    synchronized void response(List<Map<String,Object>> batch, EventQueueProtocol.ReceiptSet receipts)
    {
        if (receipts.outcomes.size() != batch.size() || receipts.stages.size() != batch.size()) return;
        for (int i=0;i<batch.size();i++)
        {
            switch (receipts.outcomes.get(i))
            {
                case DURABLE:
                    if (receipts.stages.get(i) == EventQueueProtocol.Stage.BROKER) count(batch.get(i),3);
                    else if (receipts.stages.get(i) == EventQueueProtocol.Stage.ARCHIVE) count(batch.get(i),4);
                    break;
                case RETRY: count(batch.get(i),5); break;
                case REJECTED: count(batch.get(i),6); break;
                case ERASED: count(batch.get(i),7); break;
                default: break;
            }
        }
    }
    synchronized Map<String,Object> snapshot()
    {
        Map<String,Object> out = new LinkedHashMap<>(), byFamily = new LinkedHashMap<>();
        families.forEach((family,values) -> {
            Map<String,Long> counters = new LinkedHashMap<>();
            for(int i=0;i<COUNTERS.length;i++)counters.put(COUNTERS[i],values[i]);
            byFamily.put(family,counters);
        });
        out.put("schema_v",1);out.put("scope","process_queue_operations");out.put("by_family",byFamily);
        out.put("unique_events",null);out.put("complete_capture",null);out.put("archival_after_broker_receipt","unknown");
        out.put("counts_are_not_a_partition",true);out.put("recovery_may_predate_process",true);
        out.put("network_failures_not_response_rows",true);
        return out;
    }
}

package com.osrsbestinslot.export;

import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.RuneScapeProfileType;

/** Bounded evidence, never a writer to legacy bank state. All calls use the progress grant/identity gate. */
final class StorageRecoveryCapture
{
    static final int BANK = 95, INVENTORY = 93, BANK_WIDGET = 786433, DEPOSIT_ITEMS = 12582936;
    private Map<Integer, Long> bank, inventory;
    private Long bankSeen, inventorySeen;
    private boolean gap = true, inventoryUncertain = true;
    private String session = UUID.randomUUID().toString();
    private long sequence, evicted, inventoryVersion;
    private final Deque<Map<String, Object>> observations = new ArrayDeque<>();
    private Pending pending;
    private Map<String, Object> plankSack;
    private int nextStorageTick;

    private static final class Pending
    {
        int item, tick, op;
        long quantity, at, inventoryVersion;
        Map<Integer, Long> before;
    }

    void reset()
    {
        bank = inventory = null;
        plankSack = null;
        nextStorageTick = 0;
        bankSeen = inventorySeen = null;
        gap = inventoryUncertain = true;
        pending = null;
        observations.clear();
        sequence = evicted = inventoryVersion = 0;
        session = UUID.randomUUID().toString();
    }

    static boolean bankVisible(Client client)
    {
        Widget widget = client.getWidget(BANK_WIDGET);
        return widget != null && !widget.isHidden();
    }

    void gap()
    {
        gap = inventoryUncertain = true;
        pending = null;
    }

    void container(Client client, int id, ItemContainer container, long now)
    {
        if (id != BANK && id != INVENTORY) return;
        Map<Integer, Long> counts = counts(client, container);
        if (counts == null) { gap(); return; }
        if (id == INVENTORY)
        {
            inventoryUncertain = false;
            inventoryVersion++;
            inventory = counts;
            inventorySeen = now;
            return;
        }
        // Cached bank containers outside the interface are not a fresh authoritative bank read.
        if (!bankVisible(client)) { gap = true; return; }
        // Empty bank transmissions can be clears during teardown; never fabricate a full withdrawal.
        if (counts.isEmpty()) { gap = true; return; }
        if (!gap && counts.equals(bank)) { bankSeen = now; return; }
        Map<String, Object> row = row(client, now, "item_container_changed_95");
        row.put("kind", bank == null ? "bank_baseline" : "bank_observed_delta");
        row.put("delta_status", bank == null ? "baseline_only" : "authoritative_container_difference");
        row.put("transfer_attribution", "unknown");
        row.put("across_gap", gap);
        row.put("from_observed_at_ms", bankSeen);
        if (bank != null) row.put("delta", difference(bank, counts));
        append(row);
        bank = counts;
        bankSeen = now;
        gap = false;
    }

    void menu(Client client, MenuOptionClicked event, long now)
    {
        // Competing actions invalidate attribution, including a second deposit before settlement.
        if (pending != null)
        {
            unresolved(client, now, "competing_menu_action");
            return;
        }
        if (event == null || event.isConsumed() || event.getParam1() != DEPOSIT_ITEMS
            || (event.getMenuAction() != MenuAction.CC_OP && event.getMenuAction() != MenuAction.CC_OP_LOW_PRIORITY)
            || bankVisible(client)) return;
        Widget widget = client.getWidget(DEPOSIT_ITEMS);
        if (widget == null || widget.isHidden()) return;
        int op = event.getId();
        // Only fixed 1/5/10 and All. Default and X need additional modal/settings evidence.
        if (op != 2 && op != 3 && op != 4 && op != 6) return;
        Map<Integer, Long> before = counts(client.getItemContainer(INVENTORY));
        if (before == null || event.getItemId() <= 0) return;
        long available = before.getOrDefault(event.getItemId(), 0L);
        if (available <= 0) return;
        pending = new Pending();
        pending.item = event.getItemId();
        pending.op = op;
        pending.tick = client.getTickCount();
        pending.at = now;
        pending.before = before;
        pending.inventoryVersion = inventoryVersion;
        pending.quantity = Math.min(available, op == 2 ? 1 : op == 3 ? 5 : op == 4 ? 10 : available);
    }

    void poll(Client client, long now)
    {
        if (plankSack == null || client.getTickCount() >= nextStorageTick)
        {
            samplePlanks(client, now);
            nextStorageTick = client.getTickCount() + 100;
        }
        if (!bankVisible(client)) gap = true;
        if (pending == null || client.getTickCount() - pending.tick < 2) return;
        Map<Integer, Long> delta = inventory == null ? null : difference(pending.before, inventory);
        boolean matched = inventoryVersion > pending.inventoryVersion && inventorySeen != null && inventorySeen >= pending.at && delta != null
            && delta.size() == 1 && Objects.equals(delta.get(pending.item), -pending.quantity)
            && !bankVisible(client) && client.getTickCount() - pending.tick <= 3;
        Map<String, Object> row = row(client, now, "deposit_box_menu_and_inventory_callback");
        row.put("kind", "deposit_box_recovery");
        row.put("delta_status", matched ? "inferred" : "uncertain");
        row.put("reason", matched ? "single_item_loss_matches_fixed_action" : "no_unambiguous_inventory_match");
        row.put("clicked_at_ms", pending.at);
        row.put("menu_op", pending.op);
        row.put("raw_item_id", pending.item);
        row.put("requested_quantity", pending.quantity);
        row.put("inventory_observed_at_ms", inventorySeen);
        if (matched) row.put("inventory_delta", delta);
        // Notes, item transformations and concurrent unseen actions prevent a bank-item/quantity assertion.
        row.put("bank_delta_status", "unknown");
        row.put("authoritative_baseline_mutated", false);
        append(row);
        pending = null;
    }

    private void unresolved(Client client, long now, String reason)
    {
        Map<String, Object> row = row(client, now, "deposit_box_menu");
        row.put("kind", "deposit_box_recovery");
        row.put("delta_status", "uncertain");
        row.put("reason", reason);
        row.put("clicked_at_ms", pending.at);
        append(row);
        pending = null;
    }

    private Map<String, Object> row(Client client, long now, String source)
    {
        Map<String, Object> row = new LinkedHashMap<>();
        row.put("sequence", ++sequence);
        row.put("observed_at_ms", now);
        row.put("source", source);
        row.put("account_hash", Long.toString(client.getAccountHash()));
        row.put("profile_type", RuneScapeProfileType.getCurrent(client).name());
        row.put("world", client.getWorld());
        return row;
    }

    private void append(Map<String, Object> row)
    {
        if (observations.size() == 64) { observations.removeFirst(); evicted++; }
        observations.addLast(Collections.unmodifiableMap(row));
    }

    Map<String, Object> snapshot(Client client)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("schema_v", 1);
        out.put("plank_sack", plankSack == null ? null : new LinkedHashMap<>(plankSack));
        out.put("collector_session", session);
        out.put("complete", false);
        out.put("observations_evicted", evicted);
        out.put("observations", new ArrayList<>(observations));
        out.put("bank", containerBlock(bank, bankSeen, gap || !bankVisible(client)));
        out.put("inventory", containerBlock(inventory, inventorySeen, inventoryUncertain));
        return out;
    }

    private void samplePlanks(Client client, long now)
    {
        int[] live = client.getVarps();
        int[] vars = live == null ? null : live.clone();
        Map<String, Object> values = new LinkedHashMap<>();
        String[] names = {"plain", "oak", "teak", "mahogany", "camphor", "ironwood", "rosewood"};
        // RuneLite gameval 1.13.1 PLANK_SACK_*; no runtime linkage to newer constants.
        for (int i = 0; i < names.length; i++)
            values.put(names[i], AccountProgressCapture.bit(client, vars, 18171 + i));
        plankSack = new LinkedHashMap<>();
        plankSack.put("quantities", values);
        plankSack.put("source", "sampled_varbits_18171_18177");
        plankSack.put("last_seen_ms", now);
        plankSack.put("full_or_partial", "partial");
        plankSack.put("authority", "client_varbit_values");
        plankSack.put("server_freshness", "unknown");
        plankSack.put("ownership", "unknown"); // zero counts do not prove possession of a sack
    }

    private static Map<String, Object> containerBlock(Map<Integer, Long> items, Long seen, boolean uncertain)
    {
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("items", items == null ? null : new TreeMap<>(items));
        out.put("last_seen_ms", seen);
        out.put("full_or_partial", "partial"); // all observed slots, no protocol completeness proof
        out.put("source", "item_container_changed");
        out.put("uncertain", uncertain);
        return out;
    }

    static Map<Integer, Long> counts(ItemContainer container)
    {
        return counts(null, container);
    }

    /** As counts, without bank placeholders: a placeholder is its own id at quantity 1 and is never held. */
    static Map<Integer, Long> counts(Client client, ItemContainer container)
    {
        if (container == null || container.getItems() == null || container.getItems().length > 1500) return null;
        Map<Integer, Long> out = new TreeMap<>();
        for (Item item : container.getItems())
        {
            if (item == null || item.getQuantity() < 0) return null;
            if (item.getId() > 0 && item.getQuantity() > 0 && !placeholder(client, item.getId()))
                out.merge(item.getId(), (long) item.getQuantity(), Long::sum);
        }
        return out;
    }

    private static boolean placeholder(Client client, int id)
    {
        net.runelite.api.ItemComposition c = client == null ? null : client.getItemDefinition(id);
        return c != null && c.getPlaceholderTemplateId() != -1;
    }

    private static Map<Integer, Long> difference(Map<Integer, Long> before, Map<Integer, Long> after)
    {
        Map<Integer, Long> delta = new TreeMap<>(after);
        before.forEach((id, quantity) -> delta.merge(id, -quantity, Long::sum));
        delta.values().removeIf(value -> value == 0);
        return delta;
    }
}

package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Who is standing next to you while a shop is open, nearest first.
 *
 * Rows are read only for this display while the staff store-tools gate is open. They are
 * neither retained nor passed to the public capture readers or upload paths.
 *
 * The reset countdown used to live here and was SPLIT OUT on 2026-09-03: this list changes length
 * as players walk past, and a growing panel dragged the countdown around with it. See
 * StoreResetOverlay.
 *
 * Shows ONLY while a shop interface is open. Movable, so placement is the user's choice.
 */
class StoreNearbyOverlay extends OverlayPanel
{
	/** Rows to draw. The event payload caps at 24; a panel that tall would cover the shop. */
	static final int DISPLAY_CAP = 6;

	/**
	 * An OSRS display name is at most 12 characters, so EVERY real RSN must fit — truncating one
	 * would name the wrong player. The panel is sized for 12 plus the right column instead.
	 * The guard stays for anything longer than a real name could be.
	 */
	static final int RSN_MAX_CHARS = 12;

	/** Fixed width: 12-char RSN plus the right column. Also what the anchor subtracts to right-align. */
	static final int PANEL_WIDTH = 196;

	/** Beyond this many tiles a player cannot be the counterparty of a store hand-off. */
	static final int DISPLAY_RANGE_TILES = 15;

	/**
	 * A deliberately QUIET palette. The countdown is the thing the user acts on and it owns the loud
	 * colours (StoreResetOverlay); if this list shouted too, neither would read at a glance. Only
	 * the adjacent player — the plausible counterparty — gets an accent.
	 */
	private static final Color GOLD = new Color(255, 193, 71);
	private static final Color NAME = new Color(225, 225, 225);
	private static final Color NEAR = new Color(190, 190, 190);
	private static final Color DIM = new Color(140, 140, 140);

	/** Matches StoreResetOverlay: one plate colour across both overlays. */
	private static final Color PLATE = new Color(26, 26, 26, 235);

	private final AccountConnectPlugin plugin;

	StoreNearbyOverlay(AccountConnectPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		// Option D: sits under the reset timer on the right. Both stay draggable.
		// DYNAMIC: the plugin supplies a live location each frame (under the shop's item grid) —
		// see anchorUnderItems below. A fixed corner cannot follow a window that moves with the
		// client size, and "below the items" is what was asked for.
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// Let the user drag it where they want in overlay edit mode. Placement is taste, not policy.
		setMovable(true);
		setSnappable(true);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));	// 12-char RSN + "12 tiles  126"
		// Same plate as the countdown so the two read as one design, not two accidents.
		panelComponent.setBackgroundColor(PLATE);
		panelComponent.setBorder(new java.awt.Rectangle(6, 4, 6, 4));
		panelComponent.setGap(new java.awt.Point(0, 2));	// default 0 makes rows collide
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		anchorUnderItems();
		// Two gates, both required: a shop is open, and the backend granted store tools to this
		// token. The second is what keeps these overlays off every ordinary player's screen.
		if (!plugin.isShopOpen() || !plugin.storeToolsEnabled())
		{
			return null;
		}

		// No "Store" title any more: the countdown left for its own overlay, and "Nearby (N)"
		// already names this panel. One less line covering the shop.
		List<String[]> rows = visibleRows(plugin.nearbyPlayersForOverlay(DISPLAY_CAP));

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(rows.isEmpty() ? "Nobody nearby" : "Nearby (" + rows.size() + ")")
			.color(rows.isEmpty() ? DIM : NAME)
			.build());

		for (String[] row : rows)
		{
			int dist = Integer.parseInt(row[2]);
			panelComponent.getChildren().add(LineComponent.builder()
				.left(row[0])
				.right(row[1])
				.leftColor(dist <= 1 ? GOLD : NAME)
				.rightColor(distanceColor(dist))
				.build());
		}

		builtRows = panelComponent.getChildren().size();
		return super.render(graphics);
	}

	/**
	 * Park this list under the reset timer, which itself sits under the shop's item grid, unless
	 * the user has dragged it. setPreferredLocation is what RuneLite persists on a drag, so writing
	 * it every frame would pin the overlay and silently undo their placement — hence once per visit.
	 */
	private void anchorUnderItems()
	{
		if (anchored)
		{
			return;
		}
		java.awt.Point p = plugin.shopItemsBottomLeft();
		if (p == null)
		{
			return;		// widget not laid out yet — try again next frame
		}
		if (getPreferredLocation() == null)
		{
			// Right-aligned to the same grid edge as the countdown (p.x is that edge), and pushed
			// down by the countdown's own height so the two stack without touching.
			setPreferredLocation(new java.awt.Point(p.x - PANEL_WIDTH, p.y + 32));
		}
		anchored = true;
	}

	/** One anchor per visit; cleared when the shop closes so the next visit re-places it. */
	private boolean anchored;

	void resetAnchorForVisit()
	{
		anchored = false;
	}

	/** Gold for the tile next to you — the plausible counterparty — fading out with distance. */
	static Color distanceColor(int dist)
	{
		if (dist <= 1)
		{
			return GOLD;
		}
		return dist <= 5 ? NEAR : DIM;
	}

	/** How many lines the last render BUILT, before OverlayPanel cleared them. Test seam only. */
	private int builtRows;

	int builtRowCountForTest()
	{
		return builtRows;
	}

	/**
	 * Trim an RSN that would wrap. A wrapped name pushes its own right column onto the next line and
	 * every row below it reads against the wrong player — worse than a truncated name.
	 */
	static String shortenRsn(String rsn)
	{
		if (rsn == null)
		{
			return "";
		}
		if (rsn.length() <= RSN_MAX_CHARS)
		{
			return rsn;
		}
		return rsn.substring(0, RSN_MAX_CHARS - 1) + "\u2026";
	}

	/**
	 * Turn the plugin's nearby[] maps into display rows: {left, right, distance}.
	 *
	 * Pure and static so the filtering and formatting are testable without a game client or a
	 * Graphics2D. Skips any entry missing the two fields it needs rather than drawing a broken row.
	 */
	static List<String[]> visibleRows(List<Map<String, Object>> nearby)
	{
		List<String[]> out = new ArrayList<>();
		if (nearby == null)
		{
			return out;
		}
		for (Map<String, Object> p : nearby)
		{
			Object rsnValue = p.get("rsn");
			Object distValue = p.get("dist");
			if (!(rsnValue instanceof String) || !(distValue instanceof Integer))
			{
				continue;
			}
			int dist = (Integer) distValue;
			if (dist > DISPLAY_RANGE_TILES)
			{
				continue;
			}
			String right = dist <= 1 ? "beside you" : dist + " tiles";
			Object cb = p.get("cb");
			if (cb instanceof Integer)
			{
				right = right + "  lvl " + cb;
			}
			out.add(new String[]{shortenRsn((String) rsnValue), right, String.valueOf(dist)});
			if (out.size() >= DISPLAY_CAP)
			{
				break;
			}
		}
		return out;
	}
}

package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * The store reset countdown, ON ITS OWN so it never moves.
 *
 * Split out of the combined panel on 2026-09-03 for one measured reason: the nearby list changes
 * length every few ticks as players walk past, and a panel anchored by its bottom edge grows and
 * shrinks upward — so the countdown jittered between positions and was hard to read at a glance.
 * A separate overlay drawing exactly ONE row can never change height, so it sits still.
 *
 * The number is the thing the user acts on, so it gets its own fixed spot and the strongest colour.
 */
class StoreResetOverlay extends OverlayPanel
{
	/** Under this many seconds, do not start a hand-off — the window is closing. */
	static final int URGENT_SECONDS = 12;

	/** Above this many seconds there is comfortable room to work. */
	static final int SAFE_SECONDS = 25;

	static final Color GREEN = new Color(106, 214, 106);
	static final Color AMBER = new Color(245, 184, 56);
	static final Color RED = new Color(232, 88, 88);
	static final Color DIM = new Color(140, 140, 140);
	private static final Color LABEL = new Color(215, 215, 215);

	/** The mockup's plate: near-opaque so text never fights the game scene behind it. */
	private static final Color PLATE = new Color(26, 26, 26, 235);

	/**
	 * ONE fixed width, always. A width that tracks its content is the other half of the jitter:
	 * "8s" and "sell junk" are very different lengths, so the panel edge would jump on every
	 * rollover. Sized for the longest string this overlay can ever draw.
	 */
	private static final int PANEL_WIDTH = 112;

	private final AccountConnectPlugin plugin;

	StoreResetOverlay(AccountConnectPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		// Option D (operator choice, 2026-09-03): both overlays on the RIGHT, clear of the item grid.
		// DYNAMIC: the plugin supplies a live location each frame (under the shop's item grid) —
		// see anchorUnderItems below. A fixed corner cannot follow a window that moves with the
		// client size, and "below the items" is what was asked for.
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(true);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
		// STYLE, to match the signed-off mockup: a solid dark plate rather than RuneLite's default
		// translucent grey, which let the game scene bleed through and made the text hard to read
		// against a bright shop. Tighter border and row gap than the default so the plate reads as
		// one deliberate object instead of a loose stack.
		panelComponent.setBackgroundColor(PLATE);
		panelComponent.setBorder(new java.awt.Rectangle(6, 4, 6, 4));
		panelComponent.setGap(new java.awt.Point(0, 2));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		anchorUnderItems();
		if (!plugin.isShopOpen() || !plugin.storeToolsEnabled())
		{
			return null;
		}

		long remainMs = plugin.msUntilNextResetForDisplay();
		lastText = resetText(remainMs);
		lastColor = remainMs <= 0 ? DIM : countdownColor((int) ((remainMs + 999) / 1000));

		// EXACTLY ONE ROW, on every path. This is what keeps the overlay still.
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Reset")
			.leftColor(LABEL)
			.right(lastText)
			.rightColor(lastColor)
			.build());

		builtRows = panelComponent.getChildren().size();
		return super.render(graphics);
	}

	/**
	 * Park this overlay under the shop's item grid, unless the user has dragged it somewhere.
	 *
	 * setPreferredLocation is what RuneLite persists when a user moves an overlay in edit mode, so
	 * writing it every frame would pin the overlay and silently undo their drag. The default is
	 * therefore applied ONCE per shop visit; after that the position is theirs.
	 */
	private void anchorUnderItems()
	{
		if (anchored)
		{
			return;
		}
		java.awt.Point p = plugin.shopItemsBottomLeft();
		if (p == null)
		{
			return;		// widget not laid out yet — try again next frame
		}
		if (getPreferredLocation() == null)
		{
			// p.x is the grid's RIGHT edge, so subtract our own width to end flush with it. Both
			// overlays do this, so their right edges line up whatever each one's width is.
			setPreferredLocation(new java.awt.Point(p.x - PANEL_WIDTH, p.y));
		}
		anchored = true;
	}

	/** One anchor per visit; cleared when the shop closes so the next visit re-places it. */
	private boolean anchored;

	void resetAnchorForVisit()
	{
		anchored = false;
	}

	/** Green with room to work, amber as it tightens, red when a hand-off should not be started. */
	static Color countdownColor(int secs)
	{
		if (secs <= URGENT_SECONDS)
		{
			return RED;
		}
		return secs >= SAFE_SECONDS ? GREEN : AMBER;
	}

	/**
	 * The countdown, or what it is waiting for.
	 *
	 * Never blank: a silent overlay is indistinguishable from a broken one, and that is exactly how
	 * the first live test read ("store reset not appearing anywhere"). Whole seconds, rounded UP so
	 * it never shows 0s — the last second reads 1s and then rolls to 60s.
	 */
	static String resetText(long remainMs)
	{
		if (remainMs <= 0)
		{
			return "sell junk";
		}
		return ((int) ((remainMs + 999) / 1000)) + "s";
	}

	/* Test seams: OverlayPanel clears its children after render, so the drawn values are
	 * otherwise unobservable. */
	private String lastText = "";
	private Color lastColor;
	private int builtRows;

	/** Rows the last render BUILT — OverlayPanel clears them afterwards, so this is the only view. */
	int builtRowCountForTest()
	{
		return builtRows;
	}

	String lastTextForTest()
	{
		return lastText;
	}

	Color lastColorForTest()
	{
		return lastColor;
	}
}

/*
 * Which frames of a general-store visit are uploaded: the visit start, every buy / sell / taken
 * moment, and a low-rate baseline between them, inside one fixed per-visit frame budget.
 *
 * WHY, measured. The store path used to keep only the NEWEST 12 seconds (360 frames at 30fps) in a
 * ring. A delivery visit is longer than that. Arengees, 2026-09-25: sells from 16:37:59 to 16:39:51,
 * uploaded frames 16:39:55 to 16:40:06, every frame static. The clip was intact and showed no sale.
 * The sales are the evidence, so the budget now follows the sales instead of the clock.
 *
 * WHAT IS KEPT
 *   * the first START_MILLIS of the visit at the full sample rate;
 *   * for every moment (a buy/sell click, a store_taken): PRE_ROLL_MILLIS before it and
 *     POST_ROLL_MILLIS after it at the full sample rate. The frames before a click cannot be chosen
 *     after it, so frames that are not kept are HELD in a short pre-roll until they expire;
 *   * one frame every BASELINE_PERIOD_MILLIS in between, so the gaps are not blank.
 *
 * THE BUDGET. maxFrames (360) and maxBytes (16 MiB since PIO-014; the ring had 12MB) for the WHOLE
 * visit. That keeps a visit at the same number of 40-frame chunks, so it spends the same share of
 * the server's per-token burst rate limit as before. When a new frame would exceed the budget, one
 * frame is evicted from the LARGEST group (start, each moment, baseline). Groups therefore shrink
 * toward equal size, and no moment can be pushed out by later ones. Inside a group the frame
 * farthest from its moment goes first, until only the core span around the moment is left; after
 * that the core is thinned evenly. So a visit with many sales still shows every click and the
 * inventory change after it, at a lower rate, rather than losing whole sales.
 *
 * Why not DropCaptureRate: it drops the capture time of pre-roll frames (the upload needs it for
 * each chunk's captured_at) and it has no whole-visit budget, because a drop session streams its
 * segments. Changing it would touch the drop-proof path, which is reviewed separately.
 *
 * Pure: JDK only, the clock is a parameter, thread-safe (encode thread offers, client thread marks
 * moments, the uploader snapshots).
 */
package com.osrsbestinslot.export;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class StoreVisitClip
{
	/** Full-rate footage at the start of the visit: the approach to the shop. */
	public static final long START_MILLIS = 2_000L;
	/** Full-rate footage kept BEFORE a moment. */
	public static final long PRE_ROLL_MILLIS = 2_000L;
	/** Full-rate footage kept AFTER a moment. A click resolves on the next game tick (0.6s). */
	public static final long POST_ROLL_MILLIS = 3_000L;
	/** One baseline frame per this many milliseconds between moments. */
	public static final long BASELINE_PERIOD_MILLIS = 1_000L;
	/**
	 * The core span of a moment: from just before the click to two game ticks after it, which is
	 * where the item leaves the inventory. Edges outside it are evicted first; the core is only
	 * ever thinned, never cut away.
	 */
	public static final long CORE_BEFORE_MILLIS = 500L;
	public static final long CORE_AFTER_MILLIS = 1_200L;

	/** Group id of baseline frames. The start is group 0; moments are 1, 2, 3 ... */
	static final int BASELINE = -1;
	static final int START = 0;

	private static final class Frame
	{
		final byte[] jpeg;
		final long at;
		final int group;

		Frame(byte[] jpeg, long at, int group)
		{
			this.jpeg = jpeg;
			this.at = at;
			this.group = group;
		}
	}

	/** A snapshot for the uploader: frames and their capture times, oldest first. */
	public static final class Snapshot
	{
		public final List<byte[]> frames;
		public final List<Long> capturedAtMillis;

		Snapshot(List<byte[]> frames, List<Long> capturedAtMillis)
		{
			this.frames = frames;
			this.capturedAtMillis = capturedAtMillis;
		}
	}

	private final int maxFrames;
	private final long maxBytes;
	private final int maxFrameBytes;

	private final List<Frame> kept = new ArrayList<>();
	private final Deque<Frame> preRoll = new ArrayDeque<>();
	/** Anchor time per group id: index 0 is the visit start, then one entry per moment. */
	private final List<Long> anchors = new ArrayList<>();
	private long keptBytes;
	private long lastBaselineMillis = Long.MIN_VALUE;

	public StoreVisitClip(int maxFrames, long maxBytes, int maxFrameBytes)
	{
		if (maxFrames < 1 || maxBytes < 1 || maxFrameBytes < 1)
		{
			throw new IllegalArgumentException("budget must be positive");
		}
		this.maxFrames = maxFrames;
		this.maxBytes = maxBytes;
		this.maxFrameBytes = maxFrameBytes;
	}

	/** One sampled, encoded frame. The visit starts at the first frame offered. */
	public synchronized void offer(byte[] jpeg, long atMillis)
	{
		if (jpeg == null || jpeg.length == 0 || jpeg.length > maxFrameBytes)
		{
			return;
		}
		if (anchors.isEmpty())
		{
			anchors.add(atMillis);
		}
		expirePreRoll(atMillis);
		int latest = anchors.size() - 1;
		long latestAt = anchors.get(latest);
		int group;
		if (latest > START && atMillis >= latestAt - PRE_ROLL_MILLIS && atMillis <= latestAt + POST_ROLL_MILLIS)
		{
			group = latest;
		}
		else if (atMillis - anchors.get(START) < START_MILLIS)
		{
			group = START;
		}
		else if (lastBaselineMillis == Long.MIN_VALUE || atMillis - lastBaselineMillis >= BASELINE_PERIOD_MILLIS)
		{
			group = BASELINE;
			lastBaselineMillis = atMillis;
		}
		else
		{
			preRoll.addLast(new Frame(jpeg, atMillis, BASELINE));
			return;
		}
		keep(new Frame(jpeg, atMillis, group));
	}

	/**
	 * A buy, sell or taken moment happened now. Claims the held pre-roll and opens a full-rate window.
	 * A moment before the first frame is anchored at its own time and still gets its window.
	 */
	public synchronized void onMoment(long atMillis)
	{
		if (anchors.isEmpty())
		{
			anchors.add(atMillis);
		}
		anchors.add(atMillis);
		int group = anchors.size() - 1;
		expirePreRoll(atMillis);
		List<Frame> held = new ArrayList<>(preRoll);
		preRoll.clear();
		for (Frame f : held)
		{
			if (f.at >= atMillis - PRE_ROLL_MILLIS)
			{
				keep(new Frame(f.jpeg, f.at, group));
			}
		}
	}

	/** Kept frames and their capture times, oldest first. */
	public synchronized Snapshot snapshot()
	{
		List<Frame> sorted = new ArrayList<>(kept);
		sorted.sort((a, b) -> Long.compare(a.at, b.at));
		List<byte[]> frames = new ArrayList<>(sorted.size());
		List<Long> times = new ArrayList<>(sorted.size());
		for (Frame f : sorted)
		{
			frames.add(f.jpeg);
			times.add(f.at);
		}
		return new Snapshot(frames, times);
	}

	public synchronized int size()
	{
		return kept.size();
	}

	public synchronized long byteSize()
	{
		return keptBytes;
	}

	/** Frames held for the lookbehind. Bounded by PRE_ROLL_MILLIS at the sample rate. */
	public synchronized int preRollSize()
	{
		return preRoll.size();
	}

	/** Number of buy / sell / taken moments marked this visit. */
	public synchronized int momentCount()
	{
		return Math.max(0, anchors.size() - 1);
	}

	public synchronized void clear()
	{
		kept.clear();
		preRoll.clear();
		anchors.clear();
		keptBytes = 0;
		lastBaselineMillis = Long.MIN_VALUE;
	}

	private void expirePreRoll(long nowMillis)
	{
		while (!preRoll.isEmpty() && nowMillis - preRoll.peekFirst().at > PRE_ROLL_MILLIS)
		{
			preRoll.pollFirst();
		}
	}

	private void keep(Frame f)
	{
		kept.add(f);
		keptBytes += f.jpeg.length;
		while (!kept.isEmpty() && (kept.size() > maxFrames || keptBytes > maxBytes))
		{
			Frame victim = kept.remove(victimIndex());
			keptBytes -= victim.jpeg.length;
		}
	}

	/** The frame to evict: from the largest group, its farthest edge, else its densest spot. */
	private int victimIndex()
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (Frame f : kept)
		{
			counts.merge(f.group, 1, Integer::sum);
		}
		int group = BASELINE;
		int best = -1;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			int g = e.getKey();
			int n = e.getValue();
			// Ties go to the baseline, then to the OLDEST moment: a moment still filling keeps its frames.
			if (n > best || (n == best && group != BASELINE && (g == BASELINE || g < group)))
			{
				best = n;
				group = g;
			}
		}
		if (group != BASELINE)
		{
			long anchor = anchors.get(group);
			int far = -1;
			long farDist = -1;
			for (int i = 0; i < kept.size(); i++)
			{
				Frame f = kept.get(i);
				if (f.group != group)
				{
					continue;
				}
				// Before the anchor counts double: the outcome after a click matters more than the approach.
				long dist = f.at < anchor ? 2 * (anchor - f.at) : f.at - anchor;
				boolean inCore = f.at >= anchor - CORE_BEFORE_MILLIS && f.at <= anchor + CORE_AFTER_MILLIS;
				if (!inCore && dist > farDist)
				{
					farDist = dist;
					far = i;
				}
			}
			if (far >= 0)
			{
				return far;
			}
		}
		return densestIndex(group);
	}

	/** The frame of this group closest in time to the previous one: removing it thins evenly. */
	private int densestIndex(int group)
	{
		int prev = -1;
		int pick = -1;
		long pickGap = Long.MAX_VALUE;
		List<Integer> idx = new ArrayList<>();
		for (int i = 0; i < kept.size(); i++)
		{
			if (kept.get(i).group == group)
			{
				idx.add(i);
			}
		}
		idx.sort((a, b) -> Long.compare(kept.get(a).at, kept.get(b).at));
		for (int i : idx)
		{
			if (prev >= 0)
			{
				long gap = kept.get(i).at - kept.get(prev).at;
				if (gap < pickGap)
				{
					pickGap = gap;
					pick = i;
				}
			}
			prev = i;
		}
		return pick >= 0 ? pick : idx.get(0);
	}
}

package com.osrsbestinslot.export;

import java.util.*;
import java.util.function.IntUnaryOperator;

/**
 * Own-account holdings read model (C4 wealth lane, contract v1). Pure derivation over one built snapshot map
 * (the same map buildSnapshot uploads). No client calls, no prices from the network, no writes.
 *
 * Rules:
 * - A location the snapshot did not observe is UNKNOWN, never empty. A location the plugin cannot read is
 *   UNSUPPORTED. Neither is ever counted as zero.
 * - GE escrow counts only what is provably still inside the GE. Bought items, sale proceeds and refunds that the
 *   player may already have collected are kept as an upper bound, outside the known subtotal, so a collected
 *   item is never counted twice (once in the inventory/bank and once in the offer).
 * - No complete account total is claimed. The result carries a known subtotal and the list of locations that
 *   are unknown, stale, unsupported or only bounded.
 */
final class WealthLedger
{
	static final String CONTRACT = "c4-wealth-holdings-v1";
	static final int COINS = 995;
	static final int PLATINUM_TOKEN = 13204;
	static final long PLATINUM_TOKEN_COINS = 1000L;
	/** Display policy only: a storage reading older than this is reported stale. Not a correctness claim. */
	static final long DEFAULT_STALE_AFTER_MS = 60L * 60L * 1000L;

	static final String OBSERVED = "observed";
	static final String STALE = "stale";
	static final String UNKNOWN = "unknown";
	static final String UNSUPPORTED = "unsupported";
	static final String BOUNDED = "bounded";
	/** Container present at capture but the plugin recorded no send time (seen on a real 0.7.39 first bank open). */
	static final String UNDATED = "undated";
	/** Not present in this snapshot; the reading is carried from an earlier snapshot of the same account. */
	static final String CARRIED = "carried";

	/** The four core locations. The account view is "core complete" only when all four are observed and exact. */
	static final List<String> CORE = List.of("inventory", "equipment", "bank", "ge_escrow");
	/** Own storages the snapshot carries only after the game sent them this session (opened or checked). */
	static final List<String> OPTIONAL_STORAGE = List.of("looting_bag", "seed_vault", "bonds_pouch", "bonds_escrow", "quiver_ammo",
		"seed_box", "tackle_box", "forestry_kit", "huntsmans_kit", "barbarian_knapsack", "death_storage",
		"gravestone", "poh_costume_room", "poh_menagerie", "potion_storage_device");
	/**
	 * Own wealth the plugin does not read as items today. rune_pouch is raw type indexes, not item ids. Group
	 * storage is out of the own-player contract. The others have no container read in the plugin.
	 */
	static final List<String> UNSUPPORTED_STORAGE = List.of("rune_pouch", "poh_storage", "stash_units",
		"herb_sack_gem_bag_coal_bag", "item_charges", "group_storage", "boat_storage");

	private WealthLedger()
	{
	}

	/** One location's reading. items is null unless the location is observed (or stale). */
	static final class Location
	{
		final String name;
		final String state;
		final Long observedAtMs;
		final SortedMap<Integer, Long> items;
		final String note;

		Location(String name, String state, Long observedAtMs, SortedMap<Integer, Long> items, String note)
		{
			this.name = name;
			this.state = state;
			this.observedAtMs = observedAtMs;
			this.items = items;
			this.note = note;
		}

		/** Items are present. For BOUNDED escrow they are the provably locked part; more may sit in the collect box. */
		boolean readable()
		{
			return OBSERVED.equals(state) || STALE.equals(state) || BOUNDED.equals(state) || UNDATED.equals(state)
				|| CARRIED.equals(state);
		}
	}

	/** One active GE slot, split into the provably locked part and the possibly-uncollected part. */
	static final class Escrow
	{
		final int slot;
		final String side;
		final int itemId;
		final String offerState;
		final long lockedCoins;
		final long lockedItems;
		final long maxUncollectedCoins;
		final long maxUncollectedItems;
		final String escrowState;
		/** Raw slot counters, kept so two snapshots can tell the same offer from a replaced one. */
		long total, done, price, spent;

		Escrow(int slot, String side, int itemId, String offerState, long lockedCoins, long lockedItems,
			long maxUncollectedCoins, long maxUncollectedItems)
		{
			this.slot = slot;
			this.side = side;
			this.itemId = itemId;
			this.offerState = offerState;
			this.lockedCoins = lockedCoins;
			this.lockedItems = lockedItems;
			this.maxUncollectedCoins = maxUncollectedCoins;
			this.maxUncollectedItems = maxUncollectedItems;
			this.escrowState = maxUncollectedCoins == 0 && maxUncollectedItems == 0 ? OBSERVED : BOUNDED;
		}
	}

	static final class Holdings
	{
		final String accountKey;
		final String accountKeySource;
		final long asOfMs;
		final Map<String, Location> locations;
		final List<Escrow> escrow;
		/** The id map the snapshot was read with; reconcile applies the same map to flows and trade facts. */
		final IntUnaryOperator canonical;

		Holdings(String accountKey, String accountKeySource, long asOfMs, Map<String, Location> locations, List<Escrow> escrow)
		{
			this(accountKey, accountKeySource, asOfMs, locations, escrow, IntUnaryOperator.identity());
		}

		Holdings(String accountKey, String accountKeySource, long asOfMs, Map<String, Location> locations, List<Escrow> escrow,
			IntUnaryOperator canonical)
		{
			this.canonical = canonical;
			this.accountKey = accountKey;
			this.accountKeySource = accountKeySource;
			this.asOfMs = asOfMs;
			this.locations = locations;
			this.escrow = escrow;
		}

		/** Names of locations in the given state, in fixed order. */
		List<String> inState(String state)
		{
			List<String> out = new ArrayList<>();
			for (Location l : locations.values())
			{
				if (l.state.equals(state))
				{
					out.add(l.name);
				}
			}
			return out;
		}

		boolean coreComplete()
		{
			for (String name : CORE)
			{
				if (!OBSERVED.equals(locations.get(name).state))
				{
					return false;
				}
			}
			return true;
		}

		/**
		 * Known item totals over locations read in THIS snapshot (observed, stale, undated, bounded escrow). Carried
		 * readings are left out: the real 0.7.39 run withdrew a coin after the bank closed, so adding the carried bank
		 * would count that coin twice.
		 */
		SortedMap<Integer, Long> knownItems()
		{
			return itemsWhere(false);
		}

		/** Items in carried locations only: last readings from earlier snapshots, possibly out of date. */
		SortedMap<Integer, Long> carriedItems()
		{
			return itemsWhere(true);
		}

		private SortedMap<Integer, Long> itemsWhere(boolean carried)
		{
			SortedMap<Integer, Long> out = new TreeMap<>();
			for (Location l : locations.values())
			{
				if (l.readable() && CARRIED.equals(l.state) == carried)
				{
					l.items.forEach((id, qty) -> out.merge(id, qty, Math::addExact));
				}
			}
			return out;
		}

		/** Coins plus platinum tokens at 1000 each, over locations read in this snapshot only. */
		long knownCoins()
		{
			return coins(knownItems());
		}

		static long coins(SortedMap<Integer, Long> items)
		{
			return Math.addExact(items.getOrDefault(COINS, 0L),
				Math.multiplyExact(items.getOrDefault(PLATINUM_TOKEN, 0L), PLATINUM_TOKEN_COINS));
		}

		/**
		 * Ownership answer for C5. "yes" lists where the item was seen. "no_in_observed_locations" never means
		 * "not owned" while any location is unknown, stale, bounded or unsupported. "unknown" when nothing was read.
		 */
		Map<String, Object> owns(int itemId)
		{
			Map<String, Object> out = new LinkedHashMap<>();
			List<Map<String, Object>> seen = new ArrayList<>();
			boolean anyRead = false;
			for (Location l : locations.values())
			{
				if (!l.readable())
				{
					continue;
				}
				anyRead = true;
				Long qty = l.items.get(itemId);
				if (qty != null && qty > 0)
				{
					Map<String, Object> row = new LinkedHashMap<>();
					row.put("location", l.name);
					row.put("qty", qty);
					row.put("as_of_ms", l.observedAtMs);
					row.put("state", l.state);
					seen.add(row);
				}
			}
			out.put("item_id", itemId);
			out.put("answer", !seen.isEmpty() ? "yes" : anyRead ? "no_in_observed_locations" : UNKNOWN);
			out.put("seen", seen);
			out.put("unknown_locations", inState(UNKNOWN));
			out.put("stale_locations", inState(STALE));
			out.put("bounded_locations", inState(BOUNDED));
			out.put("unsupported_locations", inState(UNSUPPORTED));
			out.put("undated_locations", inState(UNDATED));
			out.put("carried_locations", inState(CARRIED));
			return out;
		}

		/**
		 * Fill locations this snapshot did not read (bank closed, storage not opened) with the earlier reading of
		 * the same account, marked CARRIED with its original time. A carried reading can be out of date: the game
		 * does not resend a closed bank, and play on another client or on mobile between the two snapshots is not
		 * visible. It is never OBSERVED, so it never makes a view core-complete.
		 */
		Holdings carryForward(Holdings earlier)
		{
			if (earlier == null || accountKey == null || !accountKey.equals(earlier.accountKey) || earlier.asOfMs >= asOfMs)
			{
				return this;
			}
			Map<String, Location> locs = new LinkedHashMap<>(locations);
			for (Location now : locations.values())
			{
				Location before = earlier.locations.get(now.name);
				if (UNKNOWN.equals(now.state) && before != null && before.readable() && !now.name.equals("ge_escrow")
					&& !now.name.equals("inventory") && !now.name.equals("equipment"))
				{
					locs.put(now.name, new Location(now.name, CARRIED, before.observedAtMs, before.items,
						"carried from snapshot at " + earlier.asOfMs + " (" + before.state + "); may be out of date"));
				}
			}
			return new Holdings(accountKey, accountKeySource, asOfMs, Collections.unmodifiableMap(locs), escrow, canonical);
		}

		/** Compact JSON-ready view: the derived result other lanes and the site read. */
		Map<String, Object> toMap()
		{
			Map<String, Object> out = new LinkedHashMap<>();
			out.put("contract", CONTRACT);
			out.put("account_key", accountKey);
			out.put("account_key_source", accountKeySource);
			out.put("as_of_ms", asOfMs);
			Map<String, Object> locs = new LinkedHashMap<>();
			for (Location l : locations.values())
			{
				Map<String, Object> m = new LinkedHashMap<>();
				m.put("state", l.state);
				m.put("observed_at_ms", l.observedAtMs);
				m.put("stacks", l.items == null ? null : l.items.size());
				m.put("coins", l.items == null ? null
					: l.items.getOrDefault(COINS, 0L) + l.items.getOrDefault(PLATINUM_TOKEN, 0L) * PLATINUM_TOKEN_COINS);
				if (l.note != null)
				{
					m.put("note", l.note);
				}
				locs.put(l.name, m);
			}
			out.put("locations", locs);
			List<Map<String, Object>> esc = new ArrayList<>();
			long maxCoins = 0;
			for (Escrow e : escrow)
			{
				Map<String, Object> m = new LinkedHashMap<>();
				m.put("slot", e.slot);
				m.put("side", e.side);
				m.put("item_id", e.itemId);
				m.put("offer_state", e.offerState);
				m.put("locked_coins", e.lockedCoins);
				m.put("locked_items", e.lockedItems);
				m.put("max_uncollected_coins", e.maxUncollectedCoins);
				m.put("max_uncollected_items", e.maxUncollectedItems);
				m.put("escrow_state", e.escrowState);
				esc.add(m);
				maxCoins += e.maxUncollectedCoins;
			}
			out.put("ge_escrow", esc);
			out.put("known_coins", knownCoins());
			out.put("carried_coins_last_read", coins(carriedItems()));
			out.put("ge_possibly_uncollected_coins_max", maxCoins);
			out.put("core_complete", coreComplete());
			out.put("account_total_claimed", false);
			out.put("unknown_locations", inState(UNKNOWN));
			out.put("stale_locations", inState(STALE));
			out.put("bounded_locations", inState(BOUNDED));
			out.put("unsupported_locations", inState(UNSUPPORTED));
			out.put("undated_locations", inState(UNDATED));
			out.put("carried_locations", inState(CARRIED));
			return out;
		}
	}

	static Holdings fromSnapshot(Map<?, ?> snap)
	{
		return fromSnapshot(snap, DEFAULT_STALE_AFTER_MS, null, null);
	}

	/**
	 * Project a built snapshot. asOf is the snapshot's captured_at. Inventory, equipment and GE slots are live
	 * reads at that moment. Bank and other storages carry their own observed_at (last time the game sent them in
	 * this login session; the plugin clears these on login, so a previous account never leaks in).
	 * There is no shared public account/mode epoch yet (integrator contract 2026-10-19). A caller that has one passes
	 * callerIdentity; otherwise the key comes from the snapshot's own account block.
	 *
	 * canonical maps a noted or placeholder item id to its base id (in the plugin: ItemManager::canonicalize). The
	 * snapshot keeps raw ids, so without it a noted withdraw shows as -N of one id and +N of another. null = no mapping,
	 * and then noted moves stay unexplained (visible, never hidden).
	 */
	static Holdings fromSnapshot(Map<?, ?> snap, long staleAfterMs, String callerIdentity, IntUnaryOperator canonical)
	{
		IntUnaryOperator canon = canonical == null ? IntUnaryOperator.identity() : canonical;
		Long capturedS = asLong(snap.get("captured_at"));
		if (capturedS == null || capturedS <= 0)
		{
			throw new IllegalArgumentException("snapshot without captured_at");
		}
		long asOf = capturedS * 1000L;
		Map<?, ?> flags = asMap(snap.get("capture_flags"));
		Map<String, Location> locs = new LinkedHashMap<>();

		locs.put("inventory", flag(flags, "inventory_synced")
			? new Location("inventory", OBSERVED, asOf, list(snap.get("inventory"), canon), null)
			: new Location("inventory", UNKNOWN, null, null, "inventory container not sent"));
		locs.put("equipment", flag(flags, "equipment_synced")
			? new Location("equipment", OBSERVED, asOf, equipment(snap.get("equipment"), canon), null)
			: new Location("equipment", UNKNOWN, null, null, "equipment container not sent"));
		locs.put("bank", storage("bank", flag(flags, "bank_synced") ? asMap(snap.get("bank")) : null, asOf, staleAfterMs,
			"bank not opened this login session", canon));

		List<Escrow> escrow = new ArrayList<>();
		Object offers = snap.get("ge_offers");
		if (offers instanceof List)
		{
			SortedMap<Integer, Long> locked = new TreeMap<>();
			boolean bounded = false;
			Set<Integer> slots = new HashSet<>();
			for (Object o : (List<?>) offers)
			{
				Escrow e = escrow(asMap(o), canon);
				if (!slots.add(e.slot))
				{
					throw new IllegalArgumentException("two ge_offers rows for slot " + e.slot);
				}
				escrow.add(e);
				bounded |= BOUNDED.equals(e.escrowState);
				if (e.lockedCoins > 0)
				{
					locked.merge(COINS, e.lockedCoins, Math::addExact);
				}
				if (e.lockedItems > 0)
				{
					locked.merge(e.itemId, e.lockedItems, Math::addExact);
				}
			}
			locs.put("ge_escrow", new Location("ge_escrow", bounded ? BOUNDED : OBSERVED, asOf, locked,
				bounded ? "filled part may already be collected; counted as an upper bound only" : null));
		}
		else
		{
			locs.put("ge_escrow", new Location("ge_escrow", UNKNOWN, null, null, "no GE slot read in snapshot"));
		}

		for (String name : OPTIONAL_STORAGE)
		{
			locs.put(name, storage(name, asMap(snap.get(name)), asOf, staleAfterMs, "not opened or checked this login session",
				canon));
		}
		for (String name : UNSUPPORTED_STORAGE)
		{
			locs.put(name, new Location(name, UNSUPPORTED, null, null, null));
		}
		String key = callerIdentity != null ? callerIdentity : accountKey(asMap(snap.get("account")));
		return new Holdings(key, callerIdentity != null ? "caller" : "snapshot_account_block", asOf,
			Collections.unmodifiableMap(locs),
			Collections.unmodifiableList(escrow), canon);
	}

	/**
	 * Account key = account hash + game profile (STANDARD/LEAGUE/...) + iron mode. Bank Memory keys the same way so
	 * a League or Deadman bank never merges into the main game. null when the hash is missing or -1.
	 */
	static String accountKey(Map<?, ?> account)
	{
		if (account == null)
		{
			return null;
		}
		Object hash = account.get("account_hash");
		if (hash == null || "-1".equals(String.valueOf(hash)) || String.valueOf(hash).isEmpty())
		{
			return null;
		}
		return hash + "|" + account.get("profile_type") + "|" + account.get("account_type");
	}

	/**
	 * GE slot escrow. The collect box holds bought items/sale coins/refunds; the player may collect them while the
	 * offer is still open, and RuneLite's counters stay cumulative, so that part is only an upper bound.
	 */
	static Escrow escrow(Map<?, ?> o)
	{
		return escrow(o, IntUnaryOperator.identity());
	}

	static Escrow escrow(Map<?, ?> o, IntUnaryOperator canon)
	{
		if (o == null)
		{
			throw new IllegalArgumentException("ge offer row");
		}
		int slot = (int) req(o, "slot");
		int itemId = canon.applyAsInt((int) req(o, "item_id"));
		String state = String.valueOf(o.get("state"));
		long total = req(o, "total_qty");
		long done = req(o, "transferred_qty");
		long price = req(o, "price_per_item");
		long spent = req(o, "spent");
		if (total < 0 || done < 0 || done > total || price < 0 || spent < 0)
		{
			throw new IllegalArgumentException("ge offer counters");
		}
		boolean buy = state.equals("BUYING") || state.equals("BOUGHT") || state.equals("CANCELLED_BUY");
		boolean open = state.equals("BUYING") || state.equals("SELLING");
		Escrow e = escrowOf(slot, itemId, state, buy, open, total, done, price, spent);
		e.total = total;
		e.done = done;
		e.price = price;
		e.spent = spent;
		return e;
	}

	private static Escrow escrowOf(int slot, int itemId, String state, boolean buy, boolean open, long total, long done,
		long price, long spent)
	{
		if (buy)
		{
			// Unfilled coins stay locked while the offer is open. Bought items and the overpay refund may be collected.
			long unfilledCoins = Math.multiplyExact(total - done, price);
			long refund = Math.max(0L, Math.multiplyExact(done, price) - spent);
			if (open)
			{
				return new Escrow(slot, "buy", itemId, state, unfilledCoins, 0, refund, done);
			}
			// Finished or cancelled: everything left sits in the collect box, which the player may have emptied in part.
			return new Escrow(slot, "buy", itemId, state, 0, 0, unfilledCoins + refund, done);
		}
		long unsold = total - done;
		if (open)
		{
			return new Escrow(slot, "sell", itemId, state, 0, unsold, spent, 0);
		}
		return new Escrow(slot, "sell", itemId, state, 0, 0, spent, unsold);
	}

	private static Location storage(String name, Map<?, ?> block, long asOf, long staleAfterMs, String missing,
		IntUnaryOperator canon)
	{
		if (block == null)
		{
			return new Location(name, UNKNOWN, null, null, missing);
		}
		Long observedS = asLong(block.get("observed_at"));
		if (observedS == null)
		{
			// The container was present when the snapshot was built, so its items are the client's copy at that moment,
			// but the plugin has no send time for it. Real 0.7.39 run: first bank open after login had no observed_at.
			return new Location(name, UNDATED, asOf, list(block.get("items"), canon),
				"present at capture, game send time not recorded");
		}
		long at = observedS * 1000L;
		String state = asOf - at > staleAfterMs ? STALE : OBSERVED;
		return new Location(name, state, at, list(block.get("items"), canon), null);
	}

	private static SortedMap<Integer, Long> list(Object raw, IntUnaryOperator canon)
	{
		SortedMap<Integer, Long> out = new TreeMap<>();
		if (raw == null)
		{
			return out;
		}
		if (!(raw instanceof List))
		{
			throw new IllegalArgumentException("item list");
		}
		for (Object row : (List<?>) raw)
		{
			add(out, asMap(row), canon);
		}
		return out;
	}

	private static SortedMap<Integer, Long> equipment(Object raw, IntUnaryOperator canon)
	{
		SortedMap<Integer, Long> out = new TreeMap<>();
		Map<?, ?> slots = asMap(raw);
		if (slots != null)
		{
			for (Object row : slots.values())
			{
				add(out, asMap(row), canon);
			}
		}
		return out;
	}

	private static void add(SortedMap<Integer, Long> out, Map<?, ?> row, IntUnaryOperator canon)
	{
		if (row == null)
		{
			throw new IllegalArgumentException("item row");
		}
		long id = req(row, "id");
		long qty = req(row, "qty");
		if (id <= 0 || id > Integer.MAX_VALUE || qty < 0)
		{
			throw new IllegalArgumentException("item id/qty");
		}
		if (qty > 0)
		{
			int base = canon.applyAsInt((int) id);
			if (base <= 0)
			{
				throw new IllegalArgumentException("canonical item id");
			}
			out.merge(base, qty, Math::addExact);
		}
	}

	private static boolean flag(Map<?, ?> flags, String key)
	{
		return flags != null && Boolean.TRUE.equals(flags.get(key));
	}

	private static long req(Map<?, ?> m, String key)
	{
		Long v = asLong(m.get(key));
		if (v == null)
		{
			throw new IllegalArgumentException(key);
		}
		return v;
	}

	static Long asLong(Object x)
	{
		if (!(x instanceof Number))
		{
			return null;
		}
		Number n = (Number) x;
		long v = n.longValue();
		return n.doubleValue() == v ? v : null;
	}

	static Map<?, ?> asMap(Object x)
	{
		return x instanceof Map ? (Map<?, ?>) x : null;
	}
}

package com.osrsbestinslot.export;

import java.util.*;
import java.util.function.IntUnaryOperator;

/**
 * Item ledger between two holdings of the same account (C4 wealth lane, contract v1). Pure derivation.
 *
 * Per item, over locations readable in BOTH holdings only:
 *   net change = transfer between own locations (matched opposite moves, always net zero)
 *              + trade (GE fills; C1 records when given, else slot counter differences)
 *              + C3 flows (consumption/loss, reward, transform, transfer out of view) taken as facts
 *              + GE collect-box movement (bounded by what the box can hold)
 *              + unexplained (the residual; never silently given a class)
 * Value change = quantity effect at the FROM prices + revaluation (TO price minus FROM price on TO quantities), so
 * a price move is never reported as earned GP. Platinum tokens fold into coins at 1000 each.
 */
final class WealthReconciliation
{
	static final String CONTRACT = "c4-wealth-ledger-v1";
	static final String TRANSFER = "transfer";
	static final String TRADE = "trade";
	static final String GE_SETTLEMENT_INFERRED = "ge_settlement_inferred";
	static final String GE_COLLECT_BOX = "ge_collect_box";
	static final String CONSUMPTION_LOSS = "consumption_loss";
	static final String REWARD = "reward";
	static final String TRANSFORM = "transform";
	static final String TRANSFER_OUT_OF_VIEW = "transfer_out_of_view";
	static final String TRANSFER_INFERRED_CARRIED = "transfer_inferred_carried";
	/** C3 bank_session flow whose bank side was not read in this window: own move, recorded by an event, value 0. */
	static final String TRANSFER_OWN_UNREAD = "transfer_own_unread";
	/** Snapshot times are whole seconds; a flow or fill in the same second as either snapshot cannot be placed. */
	static final long SNAPSHOT_TIME_RESOLUTION_MS = 1000L;
	static final String UNEXPLAINED = "unexplained";

	private WealthReconciliation()
	{
	}

	/** A trade fill as C1 publishes it: delta to the account (item in/out, coins out/in). */
	static final class TradeFact
	{
		final int itemId;
		final long qtyDelta;
		final Long coinsDelta;
		final String source;

		TradeFact(int itemId, long qtyDelta, Long coinsDelta, String source)
		{
			this.itemId = itemId;
			this.qtyDelta = qtyDelta;
			this.coinsDelta = coinsDelta;
			this.source = source;
		}
	}

	/** A C3 item flow, taken as a fact. flowClass uses C3's names. */
	static final class Flow
	{
		final String flowId;
		final int itemId;
		final long qtyDelta;
		final String flowClass;
		final String provenance;
		final String origin;

		Flow(String flowId, int itemId, long qtyDelta, String flowClass, String provenance)
		{
			this(flowId, itemId, qtyDelta, flowClass, provenance, null);
		}

		Flow(String flowId, int itemId, long qtyDelta, String flowClass, String provenance, String origin)
		{
			this.flowId = Objects.requireNonNull(flowId, "flow_id");
			this.itemId = itemId;
			this.qtyDelta = qtyDelta;
			this.flowClass = Objects.requireNonNull(flowClass, "flow_class");
			this.provenance = provenance;
			this.origin = origin;
		}

		/** NPC/chest loot (C3 origin server_loot_*) lands on the ground or in a reward interface, not in a read location. */
		boolean groundLoot()
		{
			return origin != null && origin.startsWith("server_loot");
		}

		/** C3 marks bank deposits/withdrawals as transferred with origin bank_deposit / bank_withdraw. */
		boolean ownBankMove()
		{
			return "bank_deposit".equals(origin) || "bank_withdraw".equals(origin);
		}
	}

	/**
	 * Trade facts from C1's derived offer records (GeOfferLifecycle.reduce output, record_schema_v 1). Only fills
	 * whose observation interval lies inside (fromMs, toMs] count. A fill interval that crosses either end cannot be
	 * placed in this window, so it is excluded and listed; the snapshot residual then stays visible. Fill quantity with
	 * no interval (untimed_fill_qty, after a lost row) is listed too, never spread over a guessed time. Quarantined
	 * offers and offers of another account/profile are excluded too. Sell gp is RuneLite's counter, tax unknown.
	 */
	static List<TradeFact> tradeFactsFromC1(Map<?, ?> reduced, String accountHash, String profileType, long fromMs,
		long toMs, List<String> excluded)
	{
		List<TradeFact> out = new ArrayList<>();
		Object offers = reduced == null ? null : reduced.get("offers");
		if (!(offers instanceof List))
		{
			return out;
		}
		for (Object o : (List<?>) offers)
		{
			Map<?, ?> offer = WealthLedger.asMap(o);
			if (offer == null)
			{
				continue;
			}
			String key = String.valueOf(offer.get("offer_key"));
			if (!String.valueOf(offer.get("account_hash")).equals(accountHash)
				|| !String.valueOf(offer.get("profile_type")).equals(profileType))
			{
				excluded.add(key + ":other_account");
				continue;
			}
			if (Boolean.TRUE.equals(offer.get("quarantined")))
			{
				excluded.add(key + ":quarantined");
				continue;
			}
			Long item = WealthLedger.asLong(offer.get("item_id"));
			boolean buy = "buy".equals(offer.get("side"));
			Object fills = offer.get("fills");
			if (item == null || !(fills instanceof List))
			{
				excluded.add(key + ":malformed");
				continue;
			}
			for (Object f : (List<?>) fills)
			{
				Map<?, ?> fill = WealthLedger.asMap(f);
				Long qty = fill == null ? null : WealthLedger.asLong(fill.get("qty"));
				Long gp = fill == null ? null : WealthLedger.asLong(fill.get("gp"));
				Long start = fill == null ? null : WealthLedger.asLong(fill.get("interval_start_ms"));
				Long end = fill == null ? null : WealthLedger.asLong(fill.get("interval_end_ms"));
				if (qty == null || start == null || end == null)
				{
					excluded.add(key + ":fill_unknown");
					continue;
				}
				if (end <= fromMs || start >= toMs + SNAPSHOT_TIME_RESOLUTION_MS)
				{
					continue;	// outside the window
				}
				// Snapshot times are whole seconds: a fill touching the second of either snapshot may already be in it.
				if (start < fromMs + SNAPSHOT_TIME_RESOLUTION_MS || end > toMs)
				{
					excluded.add(key + ":fill_straddles_window");
					continue;
				}
				out.add(new TradeFact(item.intValue(), buy ? qty : -qty, gp == null ? null : buy ? -gp : gp,
					"c1_offer_lifecycle"));
			}
			// A lost middle row: the offer total is right but part of it has no interval (C1 untimed_fill_qty). That part
			// cannot be placed in any window, so it is listed and the snapshot residual for it stays unexplained.
			Long untimed = WealthLedger.asLong(offer.get("untimed_fill_qty"));
			Long first = WealthLedger.asLong(offer.get("first_seen_at_ms"));
			Long last = WealthLedger.asLong(offer.get("as_of_observed_ms"));
			boolean overlaps = (first == null || first <= toMs) && (last == null || last > fromMs);
			if (untimed != null && untimed > 0 && overlaps)
			{
				excluded.add(key + ":untimed_fill_qty=" + untimed);
			}
		}
		return out;
	}

	/**
	 * Flows from C3 ActivityFlows.classify output (c3-activity-flows-v1). Only flows observed inside (fromMs, toMs]
	 * count. A flow with no item or quantity (a death without a trusted items_lost diff) becomes an unknown flow:
	 * it is kept with itemId 0 so the ledger reports it and never calls the window explained.
	 */
	static List<Flow> flowsFromC3(List<? extends Map<?, ?>> c3Flows, long fromMs, long toMs, List<String> excluded)
	{
		List<Flow> out = new ArrayList<>();
		if (c3Flows == null)
		{
			return out;
		}
		for (Map<?, ?> f : c3Flows)
		{
			if (f.get("flow_id") == null || f.get("flow_class") == null)
			{
				excluded.add("row" + out.size() + ":missing_flow_id_or_class");
				continue;
			}
			String id = String.valueOf(f.get("flow_id"));
			Long at = WealthLedger.asLong(f.get("observed_at_ms"));
			if (at == null)
			{
				excluded.add(id + ":no_time");
				continue;
			}
			if (at < fromMs || at >= toMs + SNAPSHOT_TIME_RESOLUTION_MS)
			{
				continue;
			}
			if (at < fromMs + SNAPSHOT_TIME_RESOLUTION_MS || at >= toMs)
			{
				excluded.add(id + ":same_second_as_snapshot");	// may already be inside the FROM or TO snapshot
				continue;
			}
			Long item = WealthLedger.asLong(f.get("item_id")), qty = WealthLedger.asLong(f.get("qty_delta"));
			String cls = String.valueOf(f.get("flow_class"));
			Object origin = f.get("origin");
			out.add(item == null || qty == null || item <= 0
				? new Flow(id, 0, 0, cls, "unknown", origin == null ? null : origin.toString())
				: new Flow(id, item.intValue(), qty, cls, String.valueOf(f.get("provenance")),
					origin == null ? null : origin.toString()));
		}
		return out;
	}

	static String ledgerClass(String c3FlowClass)
	{
		switch (c3FlowClass)
		{
			case "consumed_observed":
			case "consumed_inferred":
			case "lost_death":
				return CONSUMPTION_LOSS;
			case "output_reward":
				return REWARD;
			case "transformed":
				return TRANSFORM;
			case "transferred":
				return TRANSFER_OUT_OF_VIEW;
			default:
				return UNEXPLAINED;
		}
	}

	/**
	 * Reconcile. tradeFacts null means "derive GE fills from the two snapshots' slot counters"; pass C1's records
	 * instead when they exist, never both. Prices may be null (then no GP figures). Missing prices are listed.
	 */
	static Map<String, Object> reconcile(WealthLedger.Holdings from, WealthLedger.Holdings to,
		List<TradeFact> tradeFacts, List<Flow> flows, Map<Integer, Long> priceFrom, Map<Integer, Long> priceTo)
	{
		Map<String, Object> out = new LinkedHashMap<>();
		out.put("contract", CONTRACT);
		out.put("account_key", to.accountKey);
		out.put("from_ms", from.asOfMs);
		out.put("to_ms", to.asOfMs);
		if (from.accountKey == null || !from.accountKey.equals(to.accountKey))
		{
			// An account, game profile or iron-mode switch starts a new ledger. Never diff two accounts.
			out.put("status", "not_comparable_account");
			return out;
		}
		if (to.asOfMs <= from.asOfMs)
		{
			out.put("status", "not_comparable_order");
			return out;
		}

		List<String> comparable = new ArrayList<>(), carried = new ArrayList<>(), stale = new ArrayList<>();
		Map<String, String> notComparable = new LinkedHashMap<>();
		for (String name : to.locations.keySet())
		{
			WealthLedger.Location a = from.locations.get(name), b = to.locations.get(name);
			if (a == null || !a.readable() || !b.readable())
			{
				if (!WealthLedger.UNSUPPORTED.equals(b.state))
				{
					notComparable.put(name, "from=" + (a == null ? "absent" : a.state) + " to=" + b.state);
				}
				continue;
			}
			if (WealthLedger.CARRIED.equals(a.state) && !WealthLedger.CARRIED.equals(b.state))
			{
				// A carried reading replaced by a new one (real 0.7.43 run: bank reopened, new reading dated before FROM).
				// The difference spans earlier windows whose moves were already counted from flows or left unexplained
				// there, so it is not a change of this window.
				notComparable.put(name, "from=carried to=" + b.state + " (carried reading refreshed)");
				continue;
			}
			comparable.add(name);
			if ((WealthLedger.CARRIED.equals(a.state) || WealthLedger.CARRIED.equals(b.state)
				|| b.observedAtMs != null && b.observedAtMs <= from.asOfMs) && !name.equals("ge_escrow")
				&& !name.equals("inventory") && !name.equals("equipment"))
			{
				// The TO reading was taken at or before the FROM snapshot: nothing in this window was read there, so
				// changes made out of view (for example items sent straight to the bank) are unseen.
				carried.add(name);
			}
			if (WealthLedger.STALE.equals(a.state) || WealthLedger.STALE.equals(b.state)
				|| WealthLedger.UNDATED.equals(a.state) || WealthLedger.UNDATED.equals(b.state))
			{
				stale.add(name);	// readable but not freshly dated at one end
			}
		}

		// Per item: sum of positive and negative location deltas over comparable locations.
		SortedMap<Integer, long[]> moves = new TreeMap<>();	// [pos, neg]
		for (String name : comparable)
		{
			SortedMap<Integer, Long> a = fold(from.locations.get(name).items), b = fold(to.locations.get(name).items);
			Set<Integer> ids = new TreeSet<>(a.keySet());
			ids.addAll(b.keySet());
			for (int id : ids)
			{
				long d = b.getOrDefault(id, 0L) - a.getOrDefault(id, 0L);
				if (d != 0)
				{
					long[] pn = moves.computeIfAbsent(id, k -> new long[2]);
					pn[d > 0 ? 0 : 1] += d;
				}
			}
		}

		// Facts by item and class.
		Map<Integer, Map<String, Long>> facts = new TreeMap<>();
		List<String> tradeSources = new ArrayList<>();
		boolean geComparable = comparable.contains("ge_escrow");
		Map<Integer, long[]> settleBounds = new HashMap<>();	// item -> [min, max] for vanished/replaced offers
		Map<Integer, long[]> boxBounds = new HashMap<>();		// item -> [max collected out, max collected in]
		List<String> inferredTrades = new ArrayList<>();
		Map<Integer, long[]> settlePrice = new HashMap<>();	// item -> [max buy price, max ask] of vanished open offers
		IntUnaryOperator canon = to.canonical;
		if (geComparable)
		{
			geFacts(from, to, tradeFacts == null, facts, settleBounds, boxBounds, tradeSources, inferredTrades, settlePrice);
		}
		if (tradeFacts != null)
		{
			for (TradeFact t : tradeFacts)
			{
				add(facts, canon.applyAsInt(t.itemId), TRADE, t.qtyDelta);
				if (t.coinsDelta != null)
				{
					add(facts, WealthLedger.COINS, TRADE, t.coinsDelta);
				}
				if (!tradeSources.contains(t.source))
				{
					tradeSources.add(t.source);
				}
			}
		}
		Map<Integer, Long> outOfView = new HashMap<>(), outOfViewFull = new HashMap<>(), ownUnread = new HashMap<>(),
			groundLoot = new HashMap<>();
		boolean bankFresh = comparable.contains("bank") && !carried.contains("bank")
			&& WealthLedger.OBSERVED.equals(from.locations.get("bank").state)
			&& WealthLedger.OBSERVED.equals(to.locations.get("bank").state);
		List<String> unknownFlows = new ArrayList<>();
		Set<String> seenFlows = new HashSet<>();
		int duplicateFlows = 0;
		List<String> conflictingFlows = new ArrayList<>();
		if (flows != null)
		{
			// Group by flow_id first. Identical copies (a replayed upload) count once. Copies that disagree (one
			// event_id with different contents) are all dropped and listed, so first-wins can never hide a conflict.
			Map<String, Flow> byId = new LinkedHashMap<>();
			Set<String> conflicted = new LinkedHashSet<>();
			for (Flow f : flows)
			{
				Flow first = byId.putIfAbsent(f.flowId, f);
				if (first != null)
				{
					duplicateFlows++;
					if (first.itemId != f.itemId || first.qtyDelta != f.qtyDelta || !first.flowClass.equals(f.flowClass)
						|| !Objects.equals(first.origin, f.origin))
					{
						conflicted.add(f.flowId);
					}
				}
			}
			conflictingFlows.addAll(conflicted);
			for (Flow f : byId.values())
			{
				seenFlows.add(f.flowId);
				if (conflicted.contains(f.flowId))
				{
					continue;
				}
				if (f.itemId <= 0)
				{
					unknownFlows.add(f.flowId + ":" + f.flowClass);	// e.g. a death with no trusted item diff
					continue;
				}
				int base = canon.applyAsInt(f.itemId);
				int id = base == WealthLedger.PLATINUM_TOKEN ? WealthLedger.COINS : base;
				long q = base == WealthLedger.PLATINUM_TOKEN ? f.qtyDelta * WealthLedger.PLATINUM_TOKEN_COINS : f.qtyDelta;
				String cls = ledgerClass(f.flowClass);
				if (cls.equals(TRANSFER_OUT_OF_VIEW))
				{
					if (f.ownBankMove())
					{
						// A bank read freshly at both ends shows this move in view already; the flow adds nothing and
						// must not absorb an unrelated residual. Only an unread or carried bank needs it.
						if (!bankFresh)
						{
							ownUnread.merge(id, q, Long::sum);
						}
					}
					else if (f.origin != null)
					{
						// Trade, drop and pickup never land in a read own location: apply in full.
						outOfViewFull.merge(id, q, Long::sum);
					}
					else
					{
						outOfView.merge(id, q, Long::sum);	// origin unknown: only the part not seen in view
					}
				}
				else if (cls.equals(REWARD) && f.groundLoot())
				{
					// Real 0.7.46 run: rat loot dropped to the ground; only the part picked up in this window reaches the
					// inventory. Use the loot only for an inventory gain it can explain; loot left on the ground is not wealth.
					groundLoot.merge(id, q, Long::sum);
				}
				else
				{
					add(facts, id, cls, q);
				}
			}
		}
		// Carried locations: an item can move into or out of them while they are out of view.
		Map<Integer, Long> carriedHeld = new HashMap<>();
		boolean anyCarried = false;
		for (String name : comparable)
		{
			if (WealthLedger.CARRIED.equals(to.locations.get(name).state))
			{
				anyCarried = true;
				to.locations.get(name).items.forEach((id, q) -> carriedHeld.merge(id, q, Long::sum));
			}
		}
		Long tokens = carriedHeld.remove(WealthLedger.PLATINUM_TOKEN);
		if (tokens != null)
		{
			carriedHeld.merge(WealthLedger.COINS, tokens * WealthLedger.PLATINUM_TOKEN_COINS, Long::sum);
		}

		Set<Integer> items = new TreeSet<>(moves.keySet());
		items.addAll(facts.keySet());
		items.addAll(outOfView.keySet());
		items.addAll(ownUnread.keySet());
		items.addAll(outOfViewFull.keySet());
		items.addAll(groundLoot.keySet());
		// Items first, coins last: a coin settlement must follow the items its vanished offers actually settled.
		List<Integer> order = new ArrayList<>(items);
		if (order.remove(Integer.valueOf(WealthLedger.COINS)))
		{
			order.add(WealthLedger.COINS);
		}
		long[] coinSettle = new long[2];
		List<Map<String, Object>> rows = new ArrayList<>();
		Map<String, Long> classValue = new LinkedHashMap<>();
		Map<String, Long> classQtyItems = new LinkedHashMap<>();
		List<Integer> unpriced = new ArrayList<>();
		long revaluation = 0, atRisk = 0;
		boolean priced = priceFrom != null && priceTo != null;
		for (int id : order)
		{
			long[] pn = moves.getOrDefault(id, new long[2]);
			long net = pn[0] + pn[1];
			Map<String, Long> cls = new LinkedHashMap<>();
			long transfer = Math.min(pn[0], -pn[1]);
			if (transfer > 0)
			{
				cls.put(TRANSFER, transfer);
			}
			long remaining = net;
			Map<String, Long> f = facts.getOrDefault(id, Collections.emptyMap());
			for (Map.Entry<String, Long> e : f.entrySet())
			{
				if (e.getValue() != 0)
				{
					cls.merge(e.getKey(), e.getValue(), Long::sum);
					remaining -= e.getValue();
				}
			}
			// Out-of-view flows first. A transferred flow whose other side is already seen in view was used up as the
			// in-view transfer, so only the part beyond the in-view moves on that side can explain a residual.
			remaining = applyFull(cls, remaining, ownUnread.get(id), TRANSFER_OWN_UNREAD);
			remaining = applyFull(cls, remaining, groundLoot.get(id), REWARD);
			remaining = applyFull(cls, remaining, outOfViewFull.get(id), TRANSFER_OUT_OF_VIEW);
			remaining = applyOutOfView(cls, remaining, outOfView.get(id), pn, TRANSFER_OUT_OF_VIEW);
			long[] box = boxBounds.get(id);
			if (remaining != 0 && box != null)
			{
				// remaining > 0: items left the collect box into view. remaining < 0: items entered the box (unseen).
				long take = remaining > 0 ? Math.min(remaining, box[0]) : Math.max(remaining, -box[1]);
				if (take != 0)
				{
					cls.merge(GE_COLLECT_BOX, take, Long::sum);
					remaining -= take;
				}
			}
			long[] settle = id == WealthLedger.COINS ? coinSettle : settleBounds.get(id);
			if (remaining != 0 && settle != null)
			{
				// Only the part the vanished offer's terms can justify; any excess stays unexplained.
				long take = Math.max(settle[0], Math.min(settle[1], remaining));
				if (take != 0)
				{
					cls.merge(GE_SETTLEMENT_INFERRED, take, Long::sum);
					remaining -= take;
					long[] pr = settlePrice.get(id);
					if (pr != null && id != WealthLedger.COINS)
					{
						// Bought items cost at most the bid; sold items bring at least the ask (counted up to the ask).
						if (take > 0)
						{
							coinSettle[0] -= Math.multiplyExact(take, pr[0]);
						}
						else
						{
							coinSettle[1] += Math.multiplyExact(-take, pr[1]);
						}
					}
				}
			}
			if (remaining != 0 && anyCarried)
			{
				// Withdrawn from (remaining > 0, at most what the carried reading held) or deposited into (remaining < 0)
				// a location that was not resent. Inferred, never proof.
				long take = remaining > 0 ? Math.min(remaining, carriedHeld.getOrDefault(id, 0L)) : remaining;
				if (take != 0)
				{
					cls.merge(TRANSFER_INFERRED_CARRIED, take, Long::sum);
					remaining -= take;
				}
			}
			if (remaining != 0)
			{
				cls.merge(UNEXPLAINED, remaining, Long::sum);
			}
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("item_id", id);
			row.put("net_change", net);
			row.put("classes", cls);
			Long pa = priced ? priceOf(priceFrom, id) : null, pb = priced ? priceOf(priceTo, id) : null;
			if (priced && (pa == null || pb == null))
			{
				unpriced.add(id);
			}
			if (pa != null && pb != null)
			{
				for (Map.Entry<String, Long> e : cls.entrySet())
				{
					// Transfers and collect-box moves stay inside the account: they move value, they never create it.
					if (e.getKey().equals(GE_SETTLEMENT_INFERRED))
					{
						// The item and coin sides of an out-of-view settlement cannot be paired, so no GP value is claimed.
						atRisk = Math.addExact(atRisk, Math.multiplyExact(Math.abs(e.getValue()), pa));
						continue;
					}
					boolean inferredInternal = e.getKey().equals(GE_COLLECT_BOX) || e.getKey().equals(TRANSFER_INFERRED_CARRIED)
						|| e.getKey().equals(TRANSFER_OWN_UNREAD);
					boolean internal = e.getKey().equals(TRANSFER) || inferredInternal;
					if (inferredInternal)
					{
						// Valued 0 as an own move, but it is inferred: report how much value it could be hiding.
						atRisk = Math.addExact(atRisk, Math.multiplyExact(Math.abs(e.getValue()), pa));
					}
					long v = internal ? 0 : Math.multiplyExact(e.getValue(), pa);
					classValue.merge(e.getKey(), v, Math::addExact);
				}
			}
			rows.add(row);
		}
		if (priced)
		{
			// Revaluation over every comparable holding, including items whose quantity did not change.
			SortedMap<Integer, Long> held = new TreeMap<>();
			for (String name : comparable)
			{
				fold(to.locations.get(name).items).forEach((id, q) -> held.merge(id, q, Long::sum));
			}
			for (Map.Entry<Integer, Long> e : held.entrySet())
			{
				Long pa = priceOf(priceFrom, e.getKey()), pb = priceOf(priceTo, e.getKey());
				if (pa == null || pb == null)
				{
					if (!unpriced.contains(e.getKey()))
					{
						unpriced.add(e.getKey());
					}
					continue;
				}
				revaluation = Math.addExact(revaluation, Math.multiplyExact(e.getValue(), pb - pa));
			}
		}

		out.put("status", "reconciled");
		out.put("comparable_locations", comparable);
		out.put("not_comparable_locations", notComparable);
		out.put("carried_forward_locations", carried);
		out.put("stale_locations", stale);
		out.put("trade_sources", tradeSources);
		out.put("trade_gp_semantics", "runelite_spent_tax_unknown");
		out.put("duplicate_flows_ignored", duplicateFlows);
		out.put("contributing_flow_ids", new ArrayList<>(new TreeSet<>(seenFlows)));
		out.put("items", rows);
		if (priced)
		{
			out.put("value_by_class_gp_at_from_prices", classValue);
			out.put("unvalued_classes", Collections.singletonList(GE_SETTLEMENT_INFERRED));
			out.put("inferred_value_at_risk_gp", atRisk);
			out.put("revaluation_gp", revaluation);
			out.put("unpriced_item_ids", unpriced);
		}
		boolean conserved = true;
		for (Map<String, Object> row : rows)
		{
			@SuppressWarnings("unchecked") Map<String, Long> cls = (Map<String, Long>) row.get("classes");
			long sum = 0;
			for (Map.Entry<String, Long> e : cls.entrySet())
			{
				if (!e.getKey().equals(TRANSFER))
				{
					sum += e.getValue();
				}
			}
			conserved &= sum == (long) row.get("net_change");
		}
		out.put("conservation_holds", conserved);
		out.put("unknown_flows", unknownFlows);
		out.put("conflicting_flow_ids", conflictingFlows);
		out.put("inferred_trade_slots", inferredTrades);
		// The collect box is never read: its use is inferred from slot counters, so it never counts as explained.
		boolean explained = rowsHave(rows, UNEXPLAINED) == 0 && rowsHave(rows, GE_SETTLEMENT_INFERRED) == 0
			&& rowsHave(rows, TRANSFER_INFERRED_CARRIED) == 0 && rowsHave(rows, GE_COLLECT_BOX) == 0
			&& rowsHave(rows, TRANSFER_OWN_UNREAD) == 0
			&& unknownFlows.isEmpty() && conflictingFlows.isEmpty() && inferredTrades.isEmpty();
		boolean core = true;
		for (String name : WealthLedger.CORE)
		{
			core &= comparable.contains(name) && !carried.contains(name) && !stale.contains(name)
				&& WealthLedger.OBSERVED.equals(from.locations.get(name).state)
				&& WealthLedger.OBSERVED.equals(to.locations.get(name).state);
		}
		out.put("explained", explained);
		out.put("core_comparable", core);
		// core_complete = bank, inventory, equipment and GE read freshly at both ends and every change classified
		// from evidence. It is NOT an account total: optional storages stay listed in not_comparable_locations.
		out.put("core_complete", explained && core);
		return out;
	}

	/**
	 * GE slot evidence between two snapshots. The same offer persists when slot, item, side, total and price match
	 * and no counter went down; then the counter difference is an observed fill. An offer first seen at TO with fills
	 * is a placement that was not observed: its fills may predate the window (for example a read taken before the
	 * login GE replay), so they are derived but listed in inferredTrades. A vanished or replaced offer was collected
	 * out of view.
	 *
	 * Collect-box room (box[0] = most that can have left the box into view, box[1] = most that can have entered it):
	 * FROM box contents plus fills, released locked coins/items on a cancel. A vanished offer's FROM box contents are
	 * box room; only fills after FROM (at most the unfilled remainder) can be settlement.
	 */
	private static void geFacts(WealthLedger.Holdings from, WealthLedger.Holdings to, boolean deriveFills,
		Map<Integer, Map<String, Long>> facts, Map<Integer, long[]> settle, Map<Integer, long[]> box, List<String> sources,
		List<String> inferredTrades, Map<Integer, long[]> settlePrice)
	{
		Map<Integer, WealthLedger.Escrow> fromSlot = new HashMap<>(), toSlot = new HashMap<>();
		for (WealthLedger.Escrow a : from.escrow)
		{
			fromSlot.put(a.slot, a);
		}
		for (WealthLedger.Escrow b : to.escrow)
		{
			toSlot.put(b.slot, b);
			WealthLedger.Escrow a = fromSlot.get(b.slot);
			boolean same = same(a, b);
			long q = b.done - (same ? a.done : 0), s = b.spent - (same ? a.spent : 0);
			boolean buy = b.side.equals("buy");
			if (same)
			{
				// A cancel moves the still-locked coins (buy) or items (sell) into the collect box.
				long releasedCoins = a.lockedCoins - b.lockedCoins - (buy ? Math.multiplyExact(q, b.price) : 0);
				long releasedItems = a.lockedItems - b.lockedItems - (buy ? 0 : q);
				bound(box, WealthLedger.COINS, 0, releasedCoins);
				bound(box, b.itemId, 0, releasedItems);
			}
			else
			{
				// Placed inside the window (real 0.7.42 run: a buy placed and cancelled between two snapshots). All of
				// its collect-box contents entered the box inside the window, fills and released escrow alike.
				bound(box, WealthLedger.COINS, 0, b.maxUncollectedCoins);
				bound(box, b.itemId, 0, b.maxUncollectedItems);
			}
			if (q <= 0 && s <= 0)
			{
				continue;
			}
			if (deriveFills && !same && a == null && b.done > 0)
			{
				inferredTrades.add("slot" + b.slot + ":placement_not_observed");
			}
			if (deriveFills)
			{
				add(facts, b.itemId, TRADE, buy ? q : -q);
				add(facts, WealthLedger.COINS, TRADE, buy ? -s : s);
				if (!sources.contains("snapshot_slot_counter"))
				{
					sources.add("snapshot_slot_counter");
				}
			}
			if (!same)
			{
				continue;	// box room for a new offer is its whole collect box, counted above
			}
			if (buy)
			{
				bound(box, b.itemId, 0, q);
				bound(box, WealthLedger.COINS, 0, Math.multiplyExact(q, b.price) - s);	// overpay refund
			}
			else
			{
				bound(box, WealthLedger.COINS, 0, s);
			}
		}
		for (WealthLedger.Escrow a : from.escrow)
		{
			bound(box, a.itemId, a.maxUncollectedItems, 0);
			bound(box, WealthLedger.COINS, a.maxUncollectedCoins, 0);
			if (same(a, toSlot.get(a.slot)))
			{
				continue;
			}
			long remaining = a.total - a.done;
			boolean open = a.offerState.equals("BUYING") || a.offerState.equals("SELLING");
			if (!open || remaining <= 0)
			{
				continue;	// a finished or cancelled offer has nothing left to fill; its box contents are box room above
			}
			// Item side only. The coin side is derived per item from what actually settled (see reconcile).
			long[] pr = settlePrice.computeIfAbsent(a.itemId, k -> new long[2]);
			if (a.side.equals("buy"))
			{
				range(settle, a.itemId, 0, remaining);
				pr[0] = Math.max(pr[0], a.price);
			}
			else
			{
				range(settle, a.itemId, -remaining, 0);
				pr[1] = Math.max(pr[1], a.price);
			}
		}
	}

	private static boolean same(WealthLedger.Escrow a, WealthLedger.Escrow b)
	{
		return a != null && b != null && a.itemId == b.itemId && a.side.equals(b.side) && a.total == b.total
			&& a.price == b.price && b.done >= a.done && b.spent >= a.spent;
	}

	/**
	 * Use a transferred flow for the residual. A negative flow (left a read location) whose arrival is seen in view
	 * was already counted as an in-view transfer; only the part beyond the in-view arrivals (pn[0]) is out of view.
	 * The same holds for a positive flow and the in-view departures (pn[1]).
	 */
	private static long applyOutOfView(Map<String, Long> cls, long remaining, Long flow, long[] pn, String name)
	{
		if (remaining == 0 || flow == null || flow == 0)
		{
			return remaining;
		}
		long away = flow < 0 ? Math.min(0, flow + pn[0]) : Math.max(0, flow + pn[1]);
		if (away == 0 || Long.signum(away) != Long.signum(remaining))
		{
			return remaining;
		}
		long take = remaining > 0 ? Math.min(remaining, away) : Math.max(remaining, away);
		cls.merge(name, take, Long::sum);
		return remaining - take;
	}

	/** Use a flow that never lands in a read location for the residual, in full, when the signs agree. */
	private static long applyFull(Map<String, Long> cls, long remaining, Long flow, String name)
	{
		if (remaining == 0 || flow == null || flow == 0 || Long.signum(flow) != Long.signum(remaining))
		{
			return remaining;
		}
		long take = remaining > 0 ? Math.min(remaining, flow) : Math.max(remaining, flow);
		cls.merge(name, take, Long::sum);
		return remaining - take;
	}

	private static void bound(Map<Integer, long[]> box, int id, long out, long in)
	{
		long[] b = box.computeIfAbsent(id, k -> new long[2]);
		b[0] += Math.max(0, out);
		b[1] += Math.max(0, in);
	}

	private static void range(Map<Integer, long[]> settle, int id, long min, long max)
	{
		long[] r = settle.computeIfAbsent(id, k -> new long[2]);
		r[0] += min;
		r[1] += max;
	}

	private static void add(Map<Integer, Map<String, Long>> facts, int id, String cls, long q)
	{
		if (q != 0)
		{
			facts.computeIfAbsent(id, k -> new LinkedHashMap<>()).merge(cls, q, Long::sum);
		}
	}

	private static SortedMap<Integer, Long> fold(SortedMap<Integer, Long> items)
	{
		SortedMap<Integer, Long> out = new TreeMap<>(items);
		Long tokens = out.remove(WealthLedger.PLATINUM_TOKEN);
		if (tokens != null)
		{
			out.merge(WealthLedger.COINS, tokens * WealthLedger.PLATINUM_TOKEN_COINS, Long::sum);
		}
		return out;
	}

	private static Long priceOf(Map<Integer, Long> prices, int id)
	{
		return id == WealthLedger.COINS ? Long.valueOf(1L) : prices.get(id);
	}

	private static int rowsHave(List<Map<String, Object>> rows, String cls)
	{
		int n = 0;
		for (Map<String, Object> row : rows)
		{
			if (((Map<?, ?>) row.get("classes")).containsKey(cls))
			{
				n++;
			}
		}
		return n;
	}
}

