        tick += 5;
        when(client.getRealSkillLevel(Skill.HITPOINTS)).thenReturn(10);
        assertFalse(capture.ready(client, TOKEN));
        tick++;
        assertFalse(capture.ready(client, TOKEN));
        tick++;
        assertTrue(capture.ready(client, TOKEN));
        when(client.getAccountHash()).thenReturn(-1L);
        assertFalse(capture.ready(client, TOKEN));
    }

