        bit(16097, 4655, 0, 0); bit(16098, 4655, 1, 1); bit(3909, 1050, 1, 4);
        bit(5186, 1353, 8, 8); bit(5187, 1353, 9, 9);
        bit(14815, 3791, 0, 15);
        vars[1429] = 10; vars[4655] = 2; vars[1050] = 16; vars[1353] = 256; vars[3791] = 1234;
        Map<?, ?> p = block("prayer_unlocks");
