		r.open(bank(new int[]{995, 10}));
		r.close();
		assertTrue(r.of("bank_visit_open").isEmpty());
		assertTrue(r.of("bank_visit_manifest_chunk").isEmpty());
		assertTrue(r.of("bank_visit_close").isEmpty());
	}

