		r.open(bank(new int[]{995, 10}));
		r.close();
		assertTrue(r.of("bank_visit_open").isEmpty());
		r.grant("on");
		r.grant("off");
		r.open(bank(new int[]{995, 10}));
		r.close();
		assertTrue(r.of("bank_visit_open").isEmpty());
	}

