	public void shopCloseClearsStorePending() throws Exception
	{
		// (e) closing the shop widget drops any armed-but-unresolved pending.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		arm(plugin, new AccountConnectPlugin.StorePending("store_buy", 4151, 1, 1000L, 5, false));
		WidgetClosed wc = new WidgetClosed(300, 0, false); // SHOPMAIN — final class, use the real event
		plugin.onWidgetClosed(wc);
		assertNull("closing the shop must drop any armed pending", storePending(plugin));
	}

	@Test
	public void wrongSignDeltaOmitsPriceButKeepsItemQty() throws Exception
	{
		// A buy paired with a POSITIVE delta (coins rose) is a mispairing — degrade to {item,qty} (option D),
		// never emit a wrong-sign price.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		arm(plugin, new AccountConnectPlugin.StorePending("store_buy", 4151, 1, 1000L, 5, false));
		plugin.resolveStorePendingOnInventoryChange(1200L, 6); // wrong sign for a buy
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals(4151, e.get("item"));
		assertEquals(1, e.get("qty"));
		assertFalse("must not emit a wrong-sign price", e.containsKey("gp_total"));
	}

	@Test
	public void ambiguousBatchedClicksOmitPrice() throws Exception
	{
		// Same-tick batched clicks merge two transactions into one delta — omit gp_total even when the
		// sign is right, rather than attribute both to one click's qty.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		arm(plugin, new AccountConnectPlugin.StorePending("store_buy", 4151, 1, 1000L, 5, true));
		plugin.resolveStorePendingOnInventoryChange(700L, 5); // sign ok but batch-ambiguous
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertFalse("same-tick batched clicks must omit gp_total", e.containsKey("gp_total"));
	}

	/** The one armed pending, or null. These tests arm at most one item. */
	private static AccountConnectPlugin.StorePending storePending(AccountConnectPlugin plugin)
	{
		assertTrue(plugin.storePendings.size() <= 1);
		return plugin.storePendings.isEmpty() ? null : plugin.storePendings.values().iterator().next();
	}

	private static void arm(AccountConnectPlugin plugin, AccountConnectPlugin.StorePending p)
	{
		plugin.storePendings.put(p.item, p);
	}

	@Test
	public void tradeCounterpartyExcludedRegardlessOfGrant() throws Exception
	{
		// default (public) backend: counterparty now forwarded for ALL users (gate removed, product decision 2026-07-14)
		AccountConnectPlugin pub = new AccountConnectPlugin();
		inject(pub, "config", onConfig()); // apiBaseUrl == default public
		injectPendingTrade(pub, "Bob");
		pub.emitTradeEvent();
		Map<String, Object> pe = pub.pendingEvents.get(0);
		assertEquals("trade", pe.get("type"));
		assertTrue("given items present", pe.containsKey("given"));
		assertNull("public artifact excludes the partner", pe.get("counterparty"));

		// staff backend: counterparty included
		AccountConnectPlugin staff = new AccountConnectPlugin();
		inject(staff, "config", new AccountConnectConfig()
		{
			@Override public String linkToken() { return TEST_TOKEN; }
			@Override public String apiBaseUrl() { return "https://staff.internal/api"; }
		});
		injectPendingTrade(staff, "Bob");
		staff.emitTradeEvent();
		assertNull("a staff grant cannot widen this artifact", staff.pendingEvents.get(0).get("counterparty"));
	}

	private static void injectPendingTrade(AccountConnectPlugin plugin, String counterparty) throws Exception
	{
		java.util.List<Map<String, Object>> given = new ArrayList<>();
		Map<String, Object> item = new LinkedHashMap<>();
		item.put("id", 20997);
		item.put("qty", 1);
		given.add(item);
		inject(plugin, "pendingTradeGiven", given);
		inject(plugin, "pendingCounterparty", counterparty);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class EventObservationContextTest
{
    @Test public void missingAndStaleContextNeverBecomeNormalMode()
    {
        EventObservationContext c = new EventObservationContext();
        assertNull(c.event(null,"0.7.17",1000));
        Map<String,Object> unknown=c.event("private-owner","0.7.17",1000);
        assertNull(unknown.get("account_mode"));
        c.observe("private-owner",null,4,1000);
        assertNull(c.event("private-owner","0.7.17",1100).get("account_mode"));
        c.observe("private-owner","NORMAL",5,2000);
        assertEquals("NORMAL",c.event("private-owner","0.7.17",2001).get("account_mode"));
        assertNull(c.event("private-owner","0.7.17",1999).get("account_mode"));
        assertNull(c.event("private-owner","0.7.17",12001).get("account_mode"));
    }
    @Test public void identityChangesAndResetRotateSessionAndDoNotCarryMode()
    {
        EventObservationContext c=new EventObservationContext();c.observe("a","IRONMAN",2,1000);
        Map<String,Object> first=c.event("a","0.7.17",1000),next=c.event("a","0.7.17",1001);
        assertEquals(first.get("collector_session"),next.get("collector_session"));
        assertEquals(2L,next.get("sequence"));
        Map<String,Object> changed=c.event("b","0.7.17",1002);
        assertNotEquals(first.get("collector_session"),changed.get("collector_session"));
        assertEquals(1L,changed.get("sequence"));assertNull(changed.get("account_mode"));
        c.clear();assertNotEquals(changed.get("collector_session"),c.event("b","0.7.17",1003).get("collector_session"));
    }
    @Test public void nestedProjectionDropsNamesCredentialsAndUnknownLabels()
    {
        Map<String,Object> input=new LinkedHashMap<>();input.put("other_player","PRIVATE_CANARY");
        input.put("collector_session","PRIVATE_CANARY");input.put("account_mode","PRIVATE_CANARY");
        input.put("plugin_version","PRIVATE_CANARY");input.put("source","PRIVATE_CANARY");
        input.put("context_status","PRIVATE_CANARY");input.put("sequence",Double.NaN);
        input.put("context_tick",-1);input.put("schema_v",1);input.put("account_mode_source","PRIVATE_CANARY");
        Map<String,Object> clean=EventObservationContext.project(input);
        assertFalse(clean.toString().contains("PRIVATE_CANARY"));assertFalse(clean.containsKey("sequence"));
        assertFalse(clean.containsKey("context_tick"));assertEquals(1,clean.get("schema_v"));
    }
}

