		int before = bodies.size();
		replayAndWait(p, before + 1);
		assertEquals("only the fresh row replays", Collections.singletonList(fresh), idsIn(bodies.get(before)));
		assertFalse("a row older than 48 h is never POSTed by replay", postedIds().subList(before, postedIds().size()).contains(old));
		assertEquals(droppedBefore + 1, p.captureHealthSnapshot().get("spool_dropped_total"));
		p.crashSpoolForTest();
		AccountConnectPlugin q = plugin(TOKEN_A, "12345");
		q.wallClock = () -> System.currentTimeMillis() - 1_000L;	// even a clock that is back inside the window
		q.startUp();
		grant(q);
		assertFalse("the age-out is durable (tombstoned)", pendingIds(q).contains(old));
	}

	@Test
	public void aReplayBatchThatCrossesTheAgeBoundBeforeDispatchIsNeverSent() throws Exception
	{
		AccountConnectPlugin p = plugin(TOKEN_A, "12345");
		final long[] offset = {-(EventSpool.MAX_AGE_MS - 2_000L)};
		p.wallClock = () -> System.currentTimeMillis() + offset[0];
		grant(p);
		emit(p, "trade");
		releaseToReplay(p);
		String old = pendingIds(p).get(0);
		int before = bodies.size();
		// The batch is built inside the window; the clock then passes 48 h before OkHttp dispatches it.
		p.spoolReplayBeforeDispatchHookForTest = () -> offset[0] = 3_000L;
		p.spoolReplayNotBeforeMs = 0L;
		p.spoolReplayBackoffUntilMs = 0L;
		p.replaySpoolTick();
		waitFor(() -> !p.spoolReplayInFlight, "replay attempt settled");
		p.awaitSpoolIdleForTest();
		Thread.sleep(200);
		assertEquals("a row past 48 h at dispatch is never on the wire", before, bodies.size());
		assertEquals(1L, p.captureHealthSnapshot().get("spool_replay_aged_at_dispatch_total"));
		p.spoolReplayBeforeDispatchHookForTest = null;
		replayAndWaitNoRequest(p, before);
		assertFalse("and the next tick ages it out durably", pendingIds(p).contains(old));
	}

	@Test
	public void healthCarriesTheSpoolCounters() throws Exception
	{
		AccountConnectPlugin p = plugin(TOKEN_A, "12345");
		grant(p);
		emit(p, "trade");
		Map<String, Object> h = p.captureHealthSnapshot();
		for (String k : Arrays.asList("spool_active", "spool_records_pending", "spool_bytes", "spool_oldest_age_s",
			"spool_replayed_total", "spool_acked_total", "spool_dropped_total", "spool_corrupt_total",
			"spool_quarantined_total", "spool_filtered_total", "spool_unacked_2xx_total", "spool_purged_total",
			"spool_append_failed_total", "spool_gate_timeout_total"))
		{
			assertTrue(k, h.containsKey(k));
		}
		assertEquals(true, h.get("spool_active"));
		assertEquals(1, h.get("spool_records_pending"));
	}

	// ------------------------------------------------------------------ helpers

	private static JsonObject result(String id, String status)
	{
		JsonObject r = new JsonObject();
		r.addProperty("event_id", id);
		r.addProperty("status", status);
		return r;
	}

	private void replayAndWaitNoRequest(AccountConnectPlugin p, int before) throws Exception
	{
		p.spoolReplayNotBeforeMs = 0L;
		p.spoolReplayBackoffUntilMs = 0L;
		p.replaySpoolTick();
		Thread.sleep(300);
		p.awaitSpoolIdleForTest();
		assertEquals("no replay request expected", before, bodies.size());
	}

	private String treeDigest() throws Exception
	{
		StringBuilder sb = new StringBuilder();
		List<Path> paths = allPaths();
		Collections.sort(paths);
		for (Path x : paths)
		{
			sb.append(x).append('=').append(Files.isRegularFile(x) ? EventSpoolCodecTest.sha(x) : "dir").append('\n');
		}
		return sb.toString();
	}

	static void waitFor(java.util.function.BooleanSupplier cond, String what) throws Exception
	{
		long deadline = System.currentTimeMillis() + 4_000L;
		while (System.currentTimeMillis() < deadline)
		{
			if (cond.getAsBoolean())
			{
				return;
			}
			Thread.sleep(10);
		}
		throw new AssertionError("timed out waiting for: " + what);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import net.runelite.client.events.ClientShutdown;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Events queued in memory when the client closes while the server answers 429 (the global event hour is
 * full) were lost: 11 events of one session were never sent (2026-10-11). The close now writes what the
 * final batch could not deliver, and the next start sends it.
 */
public class ExitPendingEventsTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final String OTHER = "fedcba9876543210fedcba9876543210";

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private MockWebServer server;
	private Path data;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
		data = tmp.newFolder("plugin-data").toPath();
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	private AccountConnectPlugin plugin(String token) throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "gson", new Gson());
		inject(p, "okHttpClient", new OkHttpClient.Builder().readTimeout(2, TimeUnit.SECONDS).build());
		String base = server.url("/api").toString().replaceAll("/+$", "");
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return token;
			}

			@Override
			public String apiBaseUrl()
			{
				return base;
			}
		});
		p.setSpoolDataRootForTest(data);
		return p;
	}

	private static void inject(AccountConnectPlugin p, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(p, value);
	}

	private static void emit(AccountConnectPlugin p, String skill)
	{
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("skill", skill);
		fields.put("level", 50);
		p.emitEvent("level_up", fields);
	}

	private static List<Object> skills(RecordedRequest r)
	{
		Map<?, ?> body = new Gson().fromJson(r.getBody().readUtf8(), Map.class);
		return ((List<?>) body.get("events")).stream().map(e -> ((Map<?, ?>) e).get("skill")).collect(Collectors.toList());
	}

	private void closeClient(AccountConnectPlugin p) throws Exception
	{
		ClientShutdown close = new ClientShutdown();
		p.onClientShutdown(close);
		close.waitForAllConsumers(java.time.Duration.ofSeconds(10));
	}

	private Path file()
	{
		return data.resolve("osrsbis").resolve(AccountConnectPlugin.EXIT_PENDING_FILE);
	}

	@Test
	public void eventsRefusedAtCloseAreSentByTheNextStart() throws Exception
	{
		AccountConnectPlugin first = plugin(TOKEN);
		emit(first, "Attack");
		emit(first, "Mining");
		server.enqueue(new MockResponse().setResponseCode(429).setBody("{\"error\":\"Event capacity reached\"}"));
		closeClient(first);
		assertEquals(List.of("Attack", "Mining"), skills(server.takeRequest(5, TimeUnit.SECONDS)));
		assertTrue("the refused rows are on disk", Files.exists(file()));
		assertFalse("the token itself is never written", new String(Files.readAllBytes(file())).contains(TOKEN));

		AccountConnectPlugin next = plugin(TOKEN);
		next.startUp();
		assertFalse("the file is consumed at start", Files.exists(file()));
		emit(next, "Fishing");
		server.enqueue(new MockResponse().setResponseCode(200).setBody("{\"ok\":true,\"stored\":3}"));
		next.flushEvents();
		RecordedRequest replay = server.takeRequest(5, TimeUnit.SECONDS);
		assertEquals("the old rows go first, in order, then the new one",
			List.of("Attack", "Mining", "Fishing"), skills(replay));
	}

	@Test
	public void restoredRowsKeepTheirEventIdAndWholeNumbers() throws Exception
	{
		AccountConnectPlugin first = plugin(TOKEN);
		emit(first, "Attack");
		Object id = first.pendingEvents.get(0).get("event_id");
		Object ts = first.pendingEvents.get(0).get("ts");
		first.persistPendingEvents();

		AccountConnectPlugin next = plugin(TOKEN);
		next.restorePendingEvents();
		Map<String, Object> back = next.pendingEvents.get(0);
		assertEquals("a retry carries the same id, so the server can drop a duplicate", id, back.get("event_id"));
		assertEquals(ts, back.get("ts"));
		assertEquals(50L, back.get("level"));
	}

	@Test
	public void anotherTokenNeverSendsTheRows() throws Exception
	{
		AccountConnectPlugin first = plugin(TOKEN);
		emit(first, "Attack");
		first.persistPendingEvents();
		assertTrue(Files.exists(file()));

		AccountConnectPlugin other = plugin(OTHER);
		other.restorePendingEvents();
		assertTrue(other.pendingEvents.isEmpty());
		assertFalse("rows of a token no longer configured are deleted", Files.exists(file()));
	}

	@Test
	public void aPluginStopKeepsTheRowsToo() throws Exception
	{
		AccountConnectPlugin first = plugin(TOKEN);
		emit(first, "Attack");
		first.shutDown();
		assertTrue(first.pendingEvents.isEmpty());

		AccountConnectPlugin next = plugin(TOKEN);
		next.startUp();
		assertEquals(1, next.pendingEvents.size());
		assertEquals("Attack", next.pendingEvents.get(0).get("skill"));
	}

	@Test
	public void aDeliveredCloseLeavesNoFile() throws Exception
	{
		AccountConnectPlugin first = plugin(TOKEN);
		emit(first, "Attack");
		server.enqueue(new MockResponse().setResponseCode(200).setBody("{\"ok\":true,\"stored\":1}"));
		closeClient(first);
		server.takeRequest(5, TimeUnit.SECONDS);
		assertFalse(Files.exists(file()));
	}
}

package com.osrsbestinslot.export;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.GZIPInputStream;

/** Private, read-only archive audit. Test classpath only; never included in the public plugin JAR. */
public final class GeArchiveAudit
{
    private static final Set<String> TYPES = new HashSet<>(Arrays.asList(
        "ge_offer", "ge_progress", "ge_buy", "ge_sell", "ge_cancel", "ge_collect"));
    private static final Gson JSON = new Gson();

    private GeArchiveAudit() {}

    /** Only aggregate quality counts leave this function; account, token, offer and item IDs do not. */
    static Map<String, Object> audit(List<Map<String, Object>> rows, long ack)
    {
        if (ack <= 0 || rows.size() > 80_000) throw new IllegalArgumentException("audit bound");
        Map<List<String>, List<Map<String, Object>>> groups = new LinkedHashMap<>();
        Map<String, Integer> reasons = new TreeMap<>();
        int geRows = 0, eligible = 0;
        for (Map<String, Object> row : rows)
        {
            if (!TYPES.contains(row.get("type"))) continue;
            geRows++;
            Long id = integer(row.get("id"));
            if (id == null || id < 1 || id > ack) throw new IllegalArgumentException("row outside durable ACK");
            Map<?, ?> fields = fields(row.get("fields"));
            if (fields == null) { count(reasons, "malformed_fields"); continue; }
            String account = nonempty(row.get("account_hash"));
            String token = nonempty(row.get("link_token"));
            String profile = nonempty(fields.get("profile_type"));
            boolean versioned = fields.get("ge_observation") instanceof Map
                && nonempty(fields.get("offer_key")) != null;
            if (!versioned) count(reasons, "missing_versioned_observation");
            if (profile == null) count(reasons, "missing_mode");
            if (account == null || token == null) count(reasons, "missing_owner_binding");
            if (!versioned || profile == null || account == null || token == null) continue;
            if (fields.containsKey("account_hash") && !account.equals(fields.get("account_hash")))
            { count(reasons, "conflicting_account"); continue; }
            Map<String, Object> event = new LinkedHashMap<>();
            for (Map.Entry<?, ?> e : fields.entrySet())
                if (e.getKey() instanceof String) event.put((String) e.getKey(), e.getValue());
            // Archived routing identity wins over untrusted payload fields.
            event.put("account_hash", account);
            event.put("type", row.get("type"));
            event.put("ts", row.get("ts"));
            if (nonempty(event.get("event_id")) == null && nonempty(row.get("event_id")) != null)
                event.put("event_id", row.get("event_id"));
            if (nonempty(event.get("event_id")) == null)
            { count(reasons, "missing_event_id"); continue; }
            // Never join a re-bound token or a different explicit profile. Missing account_type is not STANDARD.
            List<String> binding = Arrays.asList(token, account, profile, nonempty(fields.get("account_type")));
            groups.computeIfAbsent(binding, k -> new ArrayList<>()).add(event);
            eligible++;
        }
        int offers = 0, quarantined = 0, qualified = 0, fillIntervals = 0;
        Map<String, Long> diagnostics = new TreeMap<>();
        for (List<Map<String, Object>> events : groups.values())
        {
            Map<String, Object> result = GeOfferLifecycle.reduce(events, null, "private_archive_partition");
            for (Object value : (List<?>) result.get("offers"))
            {
                Map<?, ?> offer = (Map<?, ?>) value;
                offers++;
                if (Boolean.TRUE.equals(offer.get("quarantined"))) quarantined++;
                else
                {
                    qualified++;
                    fillIntervals += ((List<?>) offer.get("fills")).size();
                }
            }
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) result.get("diagnostics")).entrySet())
                diagnostics.merge((String) entry.getKey(), ((Number) entry.getValue()).longValue(), Long::sum);
        }
        Map<String, Object> report = new LinkedHashMap<>();
        report.put("schema", "private-ge-archive-quality-v1");
        report.put("rows_scanned", rows.size());
        report.put("ge_rows", geRows);
        report.put("eligible_versioned_rows", eligible);
        report.put("excluded_rows", geRows - eligible);
        report.put("exclusion_reasons", reasons);
        report.put("offers", offers);
        report.put("quarantined_offers", quarantined);
        report.put("qualified_offers", qualified);
        report.put("observed_fill_intervals", fillIntervals);
        report.put("reducer_diagnostics", diagnostics);
        report.put("durable_ack", ack);
        report.put("scope", "bounded archive observations; exclusion reasons overlap and are not summed; "
            + "not independent-player coverage, actual execution times or GP/tax proof");
        return report;
    }

    private static void count(Map<String, Integer> map, String reason) { map.merge(reason, 1, Integer::sum); }
    private static String nonempty(Object value)
    { return value instanceof String && !((String) value).trim().isEmpty() ? (String) value : null; }
    private static Long integer(Object value)
    {
        if (!(value instanceof Number)) return null;
        double n = ((Number) value).doubleValue();
        return Double.isFinite(n) && n == Math.rint(n) && Math.abs(n) <= 9_007_199_254_740_991L
            ? ((Number) value).longValue() : null;
    }
    private static Map<?, ?> fields(Object value)
    {
        if (value instanceof String)
        {
            if (((String) value).length() > 200_000) return null;
            try { value = JSON.fromJson((String) value, Object.class); }
            catch (RuntimeException ignored) { return null; }
        }
        return value instanceof Map ? (Map<?, ?>) value : null;
    }

    /** Usage: GeArchiveAudit ARCHIVE_ROOT ACK ARCHIVE.jsonl.gz [up to four exact existing archive files]. */
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception
    {
        if (args.length < 3 || args.length > 6) throw new IllegalArgumentException("root, ACK and 1..4 archives required");
        Path root = Paths.get(args[0]).toRealPath();
        long ack = Long.parseLong(args[1]);
        Set<Path> seen = new HashSet<>();
        List<Map<String, Object>> rows = new ArrayList<>();
        List<Map<String, Object>> sources = new ArrayList<>();
        long readCharacters = 0;
        for (int i = 2; i < args.length; i++)
        {
            Path path = Paths.get(args[i]);
            Path real = path.toRealPath();
            if (Files.isSymbolicLink(path) || !real.startsWith(root) || !seen.add(real)
                || Files.size(real) > 50_000_000) throw new IllegalArgumentException("archive outside audit bound");
            int count = 0;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                new GZIPInputStream(Files.newInputStream(real)), StandardCharsets.UTF_8)))
            {
                String line;
                while ((line = reader.readLine()) != null)
                {
                    readCharacters += line.length();
                    if (++count > 20_000 || line.length() > 200_000 || readCharacters > 50_000_000)
                        throw new IllegalArgumentException("archive row bound");
                    Map<String, Object> row = JSON.fromJson(line, Map.class);
                    if (row == null) throw new IllegalArgumentException("invalid archive row");
                    rows.add(row);
                }
            }
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(Files.readAllBytes(real));
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) hex.append(String.format("%02x", b & 255));
            Map<String, Object> source = new LinkedHashMap<>();
            source.put("file", real.getFileName().toString());
            source.put("sha256", hex.toString());
            source.put("rows", count);
            sources.add(source);
        }
        Map<String, Object> report = audit(rows, ack);
        report.put("sources", sources);
        System.out.println(new GsonBuilder().setPrettyPrinting().create().toJson(report));
    }
}

package com.osrsbestinslot.export;

import com.google.gson.Gson;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static net.runelite.api.GrandExchangeOfferState.*;

public class GeArchiveAuditTest
{
    private List<Map<String, Object>> sequence()
    {
        GeObservationTracker tracker = new GeObservationTracker();
        tracker.observe(0, EMPTY, new long[]{0,0,0,0,0}, false, 1, 1000L);
        List<Map<String, Object>> rows = new ArrayList<>();
        for (int n = 0; n < 2; n++)
        {
            Map<String, Object> event = tracker.observe(0, n == 0 ? BUYING : BOUGHT,
                new long[]{560,n == 0 ? 0 : 10,10,250,n == 0 ? 0 : 2400}, false, 2+n, 2000L+n*1000);
            event.put("event_id", "private-event-"+n);
            event.put("profile_type", "STANDARD");
            event.put("account_hash", "private-account");
            Map<String, Object> wire = PublicTransport.event(event);
            Map<String, Object> row = new LinkedHashMap<>();
            row.put("type", wire.remove("type"));
            row.put("id", n+1L);
            row.put("account_hash", "private-account");
            row.put("link_token", "private-token");
            row.put("fields", wire);
            rows.add(row);
        }
        return rows;
    }

    @Test public void actualTrackerProjectionProducesQualifiedCountsWithoutIdentifiers()
    {
        Map<String, Object> result = GeArchiveAudit.audit(sequence(), 2);
        assertEquals(2, result.get("eligible_versioned_rows"));
        assertEquals(1, result.get("qualified_offers"));
        assertEquals(1, result.get("observed_fill_intervals"));
        for (String identifier : Arrays.asList("private-account", "private-token", "private-event"))
            assertFalse(new Gson().toJson(result).contains(identifier));
        assertFalse(new Gson().toJson(result).contains("560"));
    }

    @Test public void legacyRowsAreExcludedWithoutInventingModeOrFill()
    {
        List<Map<String, Object>> rows = sequence();
        rows.get(0).put("fields", "{\"item\":560,\"qty\":10,\"gp\":2400}");
        rows.get(1).put("fields", "[]");
        Map<String, Object> result = GeArchiveAudit.audit(rows, 2);
        assertEquals(0, result.get("eligible_versioned_rows"));
        assertEquals(0, result.get("offers"));
        assertEquals(2, result.get("excluded_rows"));
    }

    @Test public void differentOwnerBindingsNeverMergeTheSameOfferKey()
    {
        List<Map<String, Object>> rows = sequence();
        rows.get(1).put("link_token", "another-private-token");
        Map<String, Object> result = GeArchiveAudit.audit(rows, 2);
        assertEquals(2, result.get("offers"));
        assertEquals(0, result.get("quarantined_offers"));
        // The terminal row carries its own measured delta interval; it does not need an archive-side join.
        assertEquals(1, result.get("observed_fill_intervals"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void aboveAckFailsInsteadOfClaimingPreservation() { GeArchiveAudit.audit(sequence(), 1); }

    @Test public void conflictingPayloadAccountIsExcluded()
    {
        List<Map<String, Object>> rows = sequence();
        ((Map<String, Object>) rows.get(1).get("fields")).put("account_hash", "other-account");
        Map<String, Object> result = GeArchiveAudit.audit(rows, 2);
        assertEquals(1, result.get("eligible_versioned_rows"));
        assertEquals(1, ((Map<?, ?>) result.get("exclusion_reasons")).get("conflicting_account"));
    }
}

package com.osrsbestinslot.export;

import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class GeHistoryCaptureTest
{
    private Widget[] row(String side, int quantity, String price)
    {
        Widget[] row = new Widget[6];
        row[2] = mock(Widget.class); row[4] = mock(Widget.class); row[5] = mock(Widget.class);
        when(row[2].getText()).thenReturn(side);
        when(row[4].getItemId()).thenReturn(4151);
        when(row[4].getItemQuantity()).thenReturn(quantity);
        when(row[5].getText()).thenReturn(price);
        return row;
    }

    @Test public void preservesRawTaxTextAndDisplayedLongValuesWithoutInventingUnitPrice()
    {
        String raw = "<col=ffffff>3,000,000,000 coins<br>(3,060,000,000 - 60,000,000 tax)</col>";
        Map<String, Object> r = GeHistoryCapture.read(row("Sold", 3, raw)).get(0);
        assertEquals("sell", r.get("side"));
        assertEquals(3000000000L, r.get("displayed_total_gp"));
        assertNull(r.get("displayed_each_gp"));
        assertEquals(raw, r.get("price_text"));
        assertEquals("unknown", r.get("execution_time"));
        assertDeduction(r, 3060000000L, 60000000L, 3000000000L);
        assertEquals("displayed_values_tax_and_rounding_unresolved", r.get("price_semantics"));
    }

    @Test public void currentClientDeductionWithoutTheTaxWordIsRead()
    {
        // 0.7.42 actual client, Varrock GE 2026-10-19: "Sold: Mithril platebody 2,646 coins (2,700 - 54)".
        assertDeduction(GeHistoryCapture.read(row("Sold", 1, "2,646 coins<br>(2,700 - 54)")).get(0), 2700, 54, 2646);
        assertDeduction(GeHistoryCapture.read(row("Sold", 1, "11,939 coins<br>(12,182 - 243)")).get(0), 12182, 243, 11939);
        Map<String, Object> bought = GeHistoryCapture.read(row("Bought", 57, "638,571 coins<br>= 11,203 each")).get(0);
        assertEquals(638571L, bought.get("displayed_total_gp"));
        assertEquals(11203L, bought.get("displayed_each_gp"));
        assertNull(bought.get("explicit_tax_gp"));
        // Arithmetic still binds: a mismatched triple stays unknown.
        assertNull(GeHistoryCapture.read(row("Sold", 1, "2,600 coins (2,700 - 54)")).get(0).get("explicit_tax_gp"));
    }

    @Test public void fieldReadMarkupFromTheActual0743ClientIsParsed()
    {
        // Exact widget strings captured by the plugin on 0.7.43 at the Varrock GE, 2026-10-19.
        Map<String, Object> sold = GeHistoryCapture.read(row("Sold:", 1,
            "<col=ffb83f>2,646 coins</col><br><col=9f9f9f>(2,700 - 54)</col>")).get(0);
        assertEquals("sell", sold.get("side"));
        assertDeduction(sold, 2700, 54, 2646);
        Map<String, Object> each = GeHistoryCapture.read(row("Sold:", 2,
            "<col=ffb83f>23,952 coins</col><br><col=9f9f9f>(24,440 - 488)</col><br>= 11,976 each")).get(0);
        assertDeduction(each, 24440, 488, 23952);
        assertEquals(11976L, each.get("displayed_each_gp"));
        Map<String, Object> bought = GeHistoryCapture.read(row("Bought:", 57,
            "<col=ffb83f>638,571 coins</col><br>= 11,203 each")).get(0);
        assertEquals("buy", bought.get("side"));
        assertEquals(638571L, bought.get("displayed_total_gp"));
        assertEquals(11203L, bought.get("displayed_each_gp"));
        assertNull(bought.get("explicit_tax_gp"));
        for (String bad : new String[]{
            "<col=ffb83f>2,646 coins</col><br><col=9f9f9f>(2,700 - 55)</col>",
            "<col=ffb83f>2,646 coins</col><br><col=9f9f9f>(2,700 - 54)</col><br>>= 1 each",
            "<col=ffb83f>2,646 coins</col><br><col=9f9f9f>(2,700 - 54)</col><br>= 1 each<br>= 1 each",
            "<col=ffb83f>2,646 coins<br><col=9f9f9f>(2,700 - 54)</col>",
            "<col=ffb83f>2,646 coins</col><br><col=9f9f9f>(2,<b>700</b> - 54)</col>"})
        {
            assertNull(bad, GeHistoryCapture.read(row("Sold:", 1, bad)).get(0).get("explicit_tax_gp"));
        }
    }

    @Test public void explicitDeductionIsAnOfferTotalRegardlessOfQuantity()
    {
        for (int quantity : new int[] {1, 3, Integer.MAX_VALUE})
        {
            Map<String, Object> r = GeHistoryCapture.read(row("Sold", quantity,
                "1,001 coins<br>(1,021 - 20 tax)")).get(0);
            assertDeduction(r, 1021L, 20L, 1001L);
            assertEquals(quantity, r.get("quantity"));
            assertNull(r.get("displayed_each_gp")); // no aggregate division or rounding
        }
    }

    @Test public void explicitZeroTaxAndZeroTotalsAreNotMissingValues()
    {
        for (String side : new String[] {"Bought", "Sold", "<col=fff>Sold</col>"})
        {
            assertDeduction(GeHistoryCapture.read(row(side, 1, "1 coin (1 - 0 tax)")).get(0), 1, 0, 1);
            assertDeduction(GeHistoryCapture.read(row(side, 2, "0 coins<br>(0 - 0 tax)")).get(0), 0, 0, 0);
            // Ordinary untaxed UI text does not explicitly supply gross and tax.
            assertUnknown(GeHistoryCapture.read(row(side, 2, "100 coins<br>>= 50 each")).get(0));
            assertUnknown(GeHistoryCapture.read(row(side, 1, "0 coins")).get(0));
        }
    }

    @Test public void acceptsLongBoundariesWithoutAddingTaxOrMultiplyingQuantity()
    {
        assertDeduction(GeHistoryCapture.read(row("Sold", Integer.MAX_VALUE,
            "9,223,372,036,854,775,806 coins<br>(9,223,372,036,854,775,807 - 1 tax)")).get(0),
            Long.MAX_VALUE, 1, Long.MAX_VALUE - 1);
        assertDeduction(GeHistoryCapture.read(row("Sold", 1,
            "0 coins (9223372036854775807 - 9223372036854775807 tax)")).get(0),
            Long.MAX_VALUE, Long.MAX_VALUE, 0);
        assertDeduction(GeHistoryCapture.read(row("Bought", 1,
            "9223372036854775807 coins (9223372036854775807 - 0 tax)")).get(0),
            Long.MAX_VALUE, 0, Long.MAX_VALUE);
    }

    @Test public void rejectsAmbiguousMalformedInconsistentAndOverflowDeductionAtomically()
    {
        String[] invalid = {
            "unknown", "", "98 coins", "98 coins (100 - 2", "98 coins (100 - 2 tax", "98 coins (100 - 2 tx)",
            "98 coins (100 - 3 tax)", "0 coins (1 - 2 tax)", "-1 coins (1 - 2 tax)",
            "98 coins (100 - -2 tax)", "98 coins (0100 - 2 tax)", "98 coins (1,00 - 2 tax)",
            "98 coins (100 - 2 tax) extra", "98 coins (100 - 2 tax) (100 - 2 tax)",
            "98 coins (100 - 2 tax)<br>>= 49 each", // additional units remain unverified
            "<col=fff>98 coins<br>(100 - 2 tax)", "98 coins<br>(100 - 2 tax)</col>",
            "<col=fff>98 coins<br>(100 - 2 tax)</col></col>",
            "98 coins<br>(1<col=fff>00</col> - 2 tax)",
            "98 coins<br/>(100 - 2 tax)", "98 coins<unknown>(100 - 2 tax)",
            "98 coins<br>(100 - 2 tax)\n", "98 coins<br>(100 - 2 tax)...",
            "9223372036854775808 coins (9223372036854775807 - 0 tax)",
            "9223372036854775807 coins (9223372036854775808 - 1 tax)",
            "0 coins (9223372036854775807 - 9223372036854775808 tax)",
            "1 coins (0 - 18446744073709551615 tax)"
        };
        for (String raw : invalid)
        {
            Map<String, Object> r = GeHistoryCapture.read(row("Sold", 2, raw)).get(0);
            assertEquals(raw, r.get("price_text"));
            assertUnknown(r);
        }
        for (String side : new String[] {"Bought", "Cancelled", "", "Unknown", "So<bad>ld", "Sold</col>"})
            assertUnknown(GeHistoryCapture.read(row(side, 2, "98 coins (100 - 2 tax)")).get(0));
    }

    private void assertDeduction(Map<String, Object> r, long gross, long tax, long net)
    {
        assertEquals(gross, r.get("original_gross_gp"));
        assertEquals(tax, r.get("explicit_tax_gp"));
        assertEquals(net, r.get("displayed_net_gp"));
        assertEquals(net, r.get("displayed_total_gp"));
        assertEquals("explicit_ui_offer_totals_not_exact_fills", r.get("tax_gross_semantics"));
        assertEvidence(r);
    }

    private void assertUnknown(Map<String, Object> r)
    {
        for (String field : new String[] {"original_gross_gp", "explicit_tax_gp", "displayed_net_gp"})
        {
            assertTrue(r.containsKey(field));
            assertNull(r.get("price_text").toString(), r.get(field));
        }
        assertEquals("unknown", r.get("tax_gross_semantics"));
        assertEvidence(r);
    }

    private void assertEvidence(Map<String, Object> r)
    {
        assertEquals("ge_history_widget_383_3_price_text", r.get("tax_gross_source"));
        assertEquals("historic_flipping_utilities_ge_history_format", r.get("tax_gross_provenance"));
        assertEquals(false, r.get("verified_with_actual_client"));
        assertEquals("unknown", r.get("execution_time"));
    }

    @Test public void eachIsObservedNotMultipliedAndUnknownIsNotZeroOrSell()
    {
        Map<String, Object> r = GeHistoryCapture.read(row("Bought", 3, "<col=fff>1,001 coins<br>>= 333 each</col>")).get(0);
        assertEquals(1001L, r.get("displayed_total_gp"));
        assertEquals(333L, r.get("displayed_each_gp"));
        r = GeHistoryCapture.read(row("Cancelled", 3, "unknown")).get(0);
        assertEquals("unknown", r.get("side"));
        assertNull(r.get("displayed_total_gp"));
        assertNull(r.get("displayed_each_gp"));
        assertNull(GeHistoryCapture.read(row("Bought", 1, "999999999999999999999999 coins")).get(0).get("displayed_total_gp"));
    }

    @Test public void rejectsPartialAndOversizedLayoutsButRetainsIdenticalRows()
    {
        assertNull(GeHistoryCapture.read(new Widget[7]));
        assertNull(GeHistoryCapture.read(new Widget[246]));
        assertNull(GeHistoryCapture.read(new Widget[6]));
        assertNull(GeHistoryCapture.read(row("Bought", 0, "1 coin")));
        Widget[] one = row("Bought", 1, "1 coin"), two = new Widget[12];
        System.arraycopy(one, 0, two, 0, 6); System.arraycopy(one, 0, two, 6, 6);
        List<Map<String, Object>> rows = GeHistoryCapture.read(two);
        assertEquals(2, rows.size());
        assertEquals(1, rows.get(1).get("row_index"));
    }

    @Test public void delayedPopulationReopenRateBoundAndReset()
    {
        GeHistoryCapture capture = new GeHistoryCapture();
        Client client = mock(Client.class); Widget list = mock(Widget.class);
        when(client.getWidget(383, 3)).thenReturn(list);
        when(list.getDynamicChildren()).thenReturn(new Widget[6]);
        poll(capture, client, 0);
        Widget[] populated = row("Bought", 3, "30 coins<br>>= 10 each");
        when(list.getDynamicChildren()).thenReturn(populated);
        poll(capture, client, 5);
        assertTrue(observations(capture).isEmpty());
        poll(capture, client, 5); // same tick is throttled
        assertTrue(observations(capture).isEmpty());
        poll(capture, client, 10);
        assertEquals(1, observations(capture).size());
        assertEquals(5000L, observations(capture).get(0).get("observed_at_ms"));
        when(list.isHidden()).thenReturn(true); poll(capture, client, 15);
        when(list.isHidden()).thenReturn(false); poll(capture, client, 20); poll(capture, client, 25);
        assertEquals(1, observations(capture).size());
        String session = (String) capture.snapshot().get("collector_session");
        capture.reset();
        assertNotEquals(session, capture.snapshot().get("collector_session"));
        assertTrue(observations(capture).isEmpty());
    }

    @Test public void boundedRecoveryReportsEvictionsAndRetainsLatestRawRows()
    {
        GeHistoryCapture capture = new GeHistoryCapture();
        Client client = mock(Client.class); Widget list = mock(Widget.class);
        when(client.getWidget(383, 3)).thenReturn(list);
        for (int n = 0; n < 12; n++)
        {
            Widget[] populated = row("Bought", n + 1, "100 coins");
            when(list.getDynamicChildren()).thenReturn(populated);
            poll(capture, client, n * 10); poll(capture, client, n * 10 + 5);
        }
        assertEquals(8, observations(capture).size());
        assertEquals(4L, capture.snapshot().get("observations_evicted"));
        assertEquals(12L, observations(capture).get(7).get("sequence"));
    }

    private void poll(GeHistoryCapture c, Client client, int tick)
    {
        when(client.getTickCount()).thenReturn(tick); c.poll(client, tick * 1000L);
    }

    private List<Map<String, Object>> observations(GeHistoryCapture c)
    {
        return (List<Map<String, Object>>) c.snapshot().get("observations");
    }
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * GE offer lifecycle (owner defaults PIO-014 item 6, GE/product): placed, partly filled, finished,
 * cancelled, collected. One row per real step, the login replay is a baseline, and a big offer that
 * fills in hundreds of steps stays bounded.
 */
public class GeLifecycleTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private AccountConnectPlugin p;
	private Client client;
	private int tick = 1000;
	private GameState gameState = GameState.LOGGED_IN;

	private void setUp() throws Exception
	{
		p = new AccountConnectPlugin();
		inject("config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		});
		client = mock(Client.class);
		when(client.getTickCount()).thenAnswer(i -> tick);
		when(client.getGameState()).thenAnswer(i -> gameState);
		inject("client", client);
	}

	private void inject(String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(p, value);
	}

	private void offer(int slot, GrandExchangeOfferState s, int item, int sold, int total, int price, int spent)
	{
		GrandExchangeOffer o = mock(GrandExchangeOffer.class);
		when(o.getState()).thenReturn(s);
		when(o.getItemId()).thenReturn(item);
		when(o.getQuantitySold()).thenReturn(sold);
		when(o.getTotalQuantity()).thenReturn(total);
		when(o.getPrice()).thenReturn((long) price);
		when(o.getSpent()).thenReturn((long) spent);
		GrandExchangeOfferChanged ev = mock(GrandExchangeOfferChanged.class);
		when(ev.getOffer()).thenReturn(o);
		when(ev.getSlot()).thenReturn(slot);
		p.onGrandExchangeOfferChanged(ev);
	}

	private List<Map<String, Object>> ge()
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : p.pendingEvents)
		{
			if (String.valueOf(e.get("type")).startsWith("ge_"))
			{
				out.add(e);
			}
		}
		return out;
	}

	private List<String> types()
	{
		List<String> out = new ArrayList<>();
		for (Map<String, Object> e : ge())
		{
			out.add((String) e.get("type"));
		}
		return out;
	}

	@Test
	public void aFullBuyEmitsPlacedPartialBoughtCollected() throws Exception
	{
		setUp();
		offer(3, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		tick++;
		offer(3, GrandExchangeOfferState.BUYING, 560, 0, 1000, 250, 0);
		tick += 5;
		offer(3, GrandExchangeOfferState.BUYING, 560, 400, 1000, 250, 100_000);	// within a minute of the placement
		tick += 200;
		offer(3, GrandExchangeOfferState.BUYING, 560, 600, 1000, 250, 150_000);
		tick += 3;
		offer(3, GrandExchangeOfferState.BOUGHT, 560, 1000, 1000, 250, 250_000);
		tick += 50;
		offer(3, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);

		assertEquals(java.util.Arrays.asList("ge_offer", "ge_progress", "ge_buy", "ge_collect"), types());
		Map<String, Object> placed = ge().get(0);
		assertEquals(560, placed.get("item"));
		assertEquals(0, placed.get("qty"));
		assertEquals(1000, placed.get("qty_total"));
		assertEquals(250L, placed.get("price"));
		assertEquals("BUYING", placed.get("state"));
		assertEquals("buy", placed.get("side"));
		assertEquals(3, placed.get("slot"));
		Map<String, Object> part = ge().get(1);
		assertEquals("the rate-limited step is folded into the next row", 600, part.get("qty"));
		assertEquals(150_000L, part.get("gp"));
		Map<String, Object> bought = ge().get(2);
		assertEquals(1000, bought.get("qty"));
		assertEquals(250_000L, bought.get("gp"));
		Map<String, Object> collected = ge().get(3);
		assertEquals("a collect names what the slot held", 560, collected.get("item"));
		assertEquals(1000, collected.get("qty"));
		assertEquals("BOUGHT", collected.get("state"));
		assertEquals("buy", collected.get("side"));
	}

	@Test
	public void aCancelledSellEmitsCancelWithSideAndCollect() throws Exception
	{
		setUp();
		offer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(0, GrandExchangeOfferState.SELLING, 4151, 0, 2, 1_500_000, 0);
		offer(0, GrandExchangeOfferState.CANCELLED_SELL, 4151, 0, 2, 1_500_000, 0);
		offer(0, GrandExchangeOfferState.CANCELLED_SELL, 4151, 0, 2, 1_500_000, 0);	// repeat: no second row
		offer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		assertEquals(java.util.Arrays.asList("ge_offer", "ge_cancel", "ge_collect"), types());
		assertEquals("sell", ge().get(1).get("side"));
		assertEquals("CANCELLED_SELL", ge().get(2).get("state"));
	}

	@Test
	public void theLoginReplayIsABaselineNotActivity() throws Exception
	{
		setUp();
		GameStateChanged gs = new GameStateChanged();
		gs.setGameState(GameState.LOGGED_IN);
		p.onGameStateChanged(gs);
		// the client replays every slot in the first ticks after login
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
		offer(2, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
		offer(4, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		tick += 2;
		offer(5, GrandExchangeOfferState.BUYING, 1511, 3, 100, 5, 15);
		assertTrue("an old finished offer is not reported again at login: " + types(), types().isEmpty());

		// real activity after the replay window
		tick += 10;
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(2, GrandExchangeOfferState.SOLD, 4151, 1, 1, 1_500_000, 1_500_000);
		assertEquals(java.util.Arrays.asList("ge_collect", "ge_sell"), types());
		assertEquals(560, ge().get(0).get("item"));
	}

	private void gameState(GameState s)
	{
		gameState = s;
		GameStateChanged gs = new GameStateChanged();
		gs.setGameState(s);
		p.onGameStateChanged(gs);
	}

	@Test
	public void anOfferThatFinishedDuringAHopIsStillReported() throws Exception
	{
		setUp();
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		gameState(GameState.HOPPING);
		tick += 5;
		gameState(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// in the replay window
		assertEquals(java.util.Arrays.asList("ge_offer", "ge_buy"), types());
	}

	@Test
	public void aSceneLoadIsNotALoginReplay() throws Exception
	{
		setUp();
		gameState(GameState.LOGGED_IN);
		tick += 50;
		offer(2, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(2, GrandExchangeOfferState.SELLING, 4151, 0, 5, 1_500_000, 0);
		tick += 150;
		gameState(GameState.LOADING);
		gameState(GameState.LOGGED_IN);		// region change, not a login
		offer(2, GrandExchangeOfferState.SELLING, 4151, 2, 5, 1_500_000, 3_000_000);	// a fill right after it
		assertEquals(java.util.Arrays.asList("ge_offer", "ge_progress"), types());
	}

	@Test
	public void anotherAccountsSlotNeverMakesAReplayLookFinished() throws Exception
	{
		setUp();
		when(client.getAccountHash()).thenReturn(111L);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		gameState(GameState.LOGIN_SCREEN);
		when(client.getAccountHash()).thenReturn(222L);
		tick += 100;
		gameState(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// the other account's own old offer
		assertEquals(java.util.Arrays.asList("ge_offer"), types());
	}

	/**
	 * Review HIGH-1: the client clears every slot to EMPTY while hopping / logging in / at the login
	 * screen. That clear is not a collect, and it must not erase the slot so the replay still sees
	 * that the offer finished while away.
	 */
	@Test
	public void theHopClearIsNotACollectAndAFinishWhileAwayIsKept() throws Exception
	{
		setUp();
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		gameState(GameState.HOPPING);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);		// the client's own clear
		tick += 5;
		gameState(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
		assertEquals(java.util.Arrays.asList("ge_offer", "ge_buy"), types());
	}

	@Test
	public void theLogoutClearIsNotACollect() throws Exception
	{
		setUp();
		offer(2, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(2, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
		gameState(GameState.LOGIN_SCREEN);
		for (int s = 0; s < 8; s++)
		{
			offer(s, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		}
		assertEquals(java.util.Arrays.asList("ge_offer"), types());
	}

	/** Review LOW-2: a finished slot that turns active again (its collect unseen) is a new offer. */
	@Test
	public void aFinishedSlotReusedIsANewOffer() throws Exception
	{
		setUp();
		offer(4, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
		tick += 50;
		offer(4, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
		assertEquals(java.util.Arrays.asList("ge_buy", "ge_offer"), types());
	}

	/** Review MED-2: started while already logged in, a region load is not a login replay. */
	@Test
	public void startedMidSessionTheFirstRegionLoadIsNotAReplay() throws Exception
	{
		setUp();
		p.startUp();
		offer(2, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(2, GrandExchangeOfferState.SELLING, 4151, 0, 5, 1_500_000, 0);
		tick += 150;
		gameState(GameState.LOADING);
		gameState(GameState.LOGGED_IN);
		offer(2, GrandExchangeOfferState.SELLING, 4151, 2, 5, 1_500_000, 3_000_000);
		assertEquals(java.util.Arrays.asList("ge_offer", "ge_progress"), types());
	}

	@Test
	public void anOfferFirstSeenPartFilledIsProgressNotANewOffer() throws Exception
	{
		setUp();
		offer(6, GrandExchangeOfferState.BUYING, 1511, 40, 100, 5, 200);
		assertEquals(java.util.Arrays.asList("ge_progress"), types());
	}

	@Test
	public void aTerminalRepeatStillEmitsOnce() throws Exception
	{
		setUp();
		offer(2, GrandExchangeOfferState.BOUGHT, 20997, 3, 3, 100, 300);
		offer(2, GrandExchangeOfferState.BOUGHT, 20997, 3, 3, 100, 300);
		assertEquals(java.util.Arrays.asList("ge_buy"), types());
	}

	/**
	 * Volume: eight slots, each a 10 000-unit offer filling one unit per tick for an hour. Rows are bounded
	 * by the one-per-minute-per-slot rule: at most 8 x 60 progress rows plus the placements, far under the
	 * server's 6000 rows per token per hour.
	 */
	@Test
	public void eightSlotsFillingEveryTickForAnHourStayBounded() throws Exception
	{
		setUp();
		for (int s = 0; s < 8; s++)
		{
			offer(s, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
			offer(s, GrandExchangeOfferState.BUYING, 560, 0, 10_000, 250, 0);
		}
		for (int t = 1; t <= 6000; t++)
		{
			tick++;
			for (int s = 0; s < 8; s++)
			{
				offer(s, GrandExchangeOfferState.BUYING, 560, t, 10_000, 250, t * 250);
			}
		}
		int rows = ge().size();
		assertTrue("rows/hour " + rows, rows <= 8 + 8 * 61);
		assertTrue("fills are still reported: " + rows, rows >= 8 + 8 * 59);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * GE login / replay window, aligned with the RuneLite GE plugin: the client replays every slot from
 * LOGGING_IN / HOPPING until shortly after LOGGED_IN, the account hash is -1 before login, and a plugin
 * enabled while in the world gets no replay at all. Each arm drives the real game state sequence.
 */
public class GeLoginWindowTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final long A = 111L;
	private static final long B = 222L;

	private AccountConnectPlugin p;
	private Client client;
	private int tick = 1000;
	private GameState gameState = GameState.LOGGED_IN;
	private long hash = A;
	private GrandExchangeOffer[] slots = new GrandExchangeOffer[8];

	private void setUp(GameState start) throws Exception
	{
		gameState = start;
		p = new AccountConnectPlugin();
		inject("config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		});
		client = mock(Client.class);
		when(client.getTickCount()).thenAnswer(i -> tick);
		when(client.getGameState()).thenAnswer(i -> gameState);
		when(client.getAccountHash()).thenAnswer(i -> hash);
		when(client.getGrandExchangeOffers()).thenAnswer(i -> slots);
		inject("client", client);
		p.startUp();
	}

	private void inject(String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(p, value);
	}

	private static GrandExchangeOffer o(GrandExchangeOfferState s, int item, int sold, int total, int price, int spent)
	{
		GrandExchangeOffer o = mock(GrandExchangeOffer.class);
		when(o.getState()).thenReturn(s);
		when(o.getItemId()).thenReturn(item);
		when(o.getQuantitySold()).thenReturn(sold);
		when(o.getTotalQuantity()).thenReturn(total);
		when(o.getPrice()).thenReturn((long) price);
		when(o.getSpent()).thenReturn((long) spent);
		return o;
	}

	private void offer(int slot, GrandExchangeOfferState s, int item, int sold, int total, int price, int spent)
	{
		GrandExchangeOffer offer = o(s, item, sold, total, price, spent);
		GrandExchangeOfferChanged ev = mock(GrandExchangeOfferChanged.class);
		when(ev.getOffer()).thenReturn(offer);
		when(ev.getSlot()).thenReturn(slot);
		p.onGrandExchangeOfferChanged(ev);
	}

	private void state(GameState s)
	{
		gameState = s;
		GameStateChanged gs = new GameStateChanged();
		gs.setGameState(s);
		p.onGameStateChanged(gs);
	}

	private List<Map<String, Object>> ge()
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : p.pendingEvents)
		{
			if (String.valueOf(e.get("type")).startsWith("ge_"))
			{
				out.add(e);
			}
		}
		return out;
	}

	private List<String> types()
	{
		List<String> out = new ArrayList<>();
		for (Map<String, Object> e : ge())
		{
			out.add((String) e.get("type"));
		}
		return out;
	}

	// ---- (a) fresh client first login ----

	/**
	 * A fresh client knows no slot. The replay arrives while LOGGING_IN / LOADING, before LOGGED_IN. It is a
	 * baseline, so an old finished offer is never reported as a new buy.
	 */
	@Test
	public void aFreshClientLoginReplayBeforeLoggedInEmitsNothing() throws Exception
	{
		for (boolean knownHash : new boolean[]{false, true})
		{
			hash = -1L;
			setUp(GameState.LOGIN_SCREEN);
			state(GameState.LOGIN_SCREEN);
			state(GameState.LOGGING_IN);
			hash = knownHash ? A : -1L;
			offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
			offer(2, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
			tick += 3;
			state(GameState.LOADING);
			offer(3, GrandExchangeOfferState.BUYING, 1511, 3, 100, 5, 15);
			tick += 2;
			hash = A;
			state(GameState.LOGGED_IN);
			tick += 1;
			offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// the in-world replay
			assertTrue("hash known=" + knownHash + ": the login replay is a baseline: " + types(), types().isEmpty());

			tick += 20;
			offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);	// real activity afterwards still counts
			assertEquals("hash known=" + knownHash, Arrays.asList("ge_collect"), types());
			assertEquals(560, ge().get(0).get("item"));
		}
	}

	// ---- (b) identical replay after a hop ----

	@Test
	public void anIdenticalReplayAfterAHopEmitsNothing() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(0, GrandExchangeOfferState.BUYING, 560, 4, 10, 250, 1000);
		state(GameState.HOPPING);
		offer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);		// the client's own clear
		state(GameState.LOADING);
		tick += 4;
		state(GameState.LOGGED_IN);
		tick += 3;							// outside the 2-tick burst
		offer(0, GrandExchangeOfferState.BUYING, 560, 4, 10, 250, 1000);
		assertEquals(Arrays.asList("ge_offer"), types());
	}

	// ---- (c) finished while away, replayed before LOGGED_IN ----

	@Test
	public void anOfferFinishedDuringAHopAndReplayedWhileLoggingInIsOneBuy() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.HOPPING);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		state(GameState.LOGGING_IN);
		tick += 2;
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// replay before LOGGED_IN
		state(GameState.LOADING);
		tick += 3;
		state(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// replayed again in the burst
		tick += 10;
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// and re-sent later
		assertEquals(Arrays.asList("ge_offer", "ge_buy"), types());
		assertEquals(10, ge().get(1).get("qty"));
	}

	// ---- (d) hash -1 in the middle ----

	@Test
	public void anEventWithNoAccountHashDoesNotClearTheSlots() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.LOGIN_SCREEN);
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);		// replay, account not known yet
		offer(2, GrandExchangeOfferState.SOLD, 4151, 1, 1, 1_500_000, 1_500_000);
		hash = A;
		tick += 5;
		state(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// finished while away
		assertEquals(Arrays.asList("ge_offer", "ge_buy"), types());
	}

	private void gameTick()
	{
		p.onGameTick(new net.runelite.api.events.GameTick());
	}

	/**
	 * Review r1 MEDIUM-1: a real client replays each slot ONCE. If that single replay carries hash -1 it is
	 * the only report of an offer that finished while away. It is held, then judged as a replay of the same
	 * account once the hash is known: exactly one ge_buy, and the later collect names what was bought.
	 */
	@Test
	public void aSingleReplayWithNoAccountHashStillReportsTheFinishOnce() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.HOPPING);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);		// the client's own clear
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// the only replay, hash -1
		tick += 3;
		state(GameState.LOADING);
		hash = A;
		tick += 2;
		state(GameState.LOGGED_IN);
		gameTick();
		tick += 1;
		gameTick();
		assertEquals(Arrays.asList("ge_offer", "ge_buy"), types());
		assertEquals(10, ge().get(1).get("qty"));
		assertEquals(2500L, ge().get(1).get("gp"));

		tick += 20;
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		assertEquals(Arrays.asList("ge_offer", "ge_buy", "ge_collect"), types());
		Map<String, Object> c = ge().get(2);
		assertEquals("BOUGHT", c.get("state"));
		assertEquals(10, c.get("qty"));
		assertEquals(2500L, c.get("gp"));
	}

	/** The held event is also settled by the next GE event that carries the real hash (before any tick). */
	@Test
	public void theNextKnownHashEventSettlesTheHeldReplayFirst() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		offer(2, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(2, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
		state(GameState.HOPPING);
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
		hash = A;
		offer(2, GrandExchangeOfferState.SOLD, 4151, 1, 1, 1_500_000, 1_500_000);
		assertEquals(Arrays.asList("ge_offer", "ge_offer", "ge_buy", "ge_sell"), types());
	}

	/** A -> logout -> B, with B's replay at hash -1: B's slots are the new baseline and A's offer is never reported. */
	@Test
	public void anotherAccountsReplayAtNoHashIsABaselineAndNeverReportsTheOldOffer() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.LOGIN_SCREEN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// B's own old offer, same item
		offer(3, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
		hash = B;
		tick += 5;
		state(GameState.LOGGED_IN);
		gameTick();
		assertEquals("B's held replay is a baseline", Arrays.asList("ge_offer"), types());

		tick += 20;
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);		// B collects its own old buy
		offer(3, GrandExchangeOfferState.SOLD, 4151, 1, 1, 1_500_000, 1_500_000);
		assertEquals(Arrays.asList("ge_offer", "ge_collect", "ge_sell"), types());
		assertEquals("the collect names B's slot, from B's baseline", "BOUGHT", ge().get(1).get("state"));
	}

	/**
	 * Review r2 LOW-1: a held -1 event of account A must not survive a plugin disable. Disabled during a hop
	 * with slot 5 held, enabled again at the login screen (no LOGIN_SCREEN event is seen), then B logs in:
	 * B's slot 5 has no baseline from A, so B's new offer there is a ge_offer.
	 */
	@Test
	public void aHeldEventDoesNotSurviveAPluginDisable() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(5, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(5, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.HOPPING);
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(5, GrandExchangeOfferState.BUYING, 560, 3, 10, 250, 750);	// held at -1
		p.shutDown();
		gameState = GameState.LOGIN_SCREEN;
		p.startUp();							// re-enabled at the login screen
		hash = B;
		tick += 5;
		state(GameState.LOGGING_IN);
		state(GameState.LOGGED_IN);
		gameTick();
		tick += 20;
		offer(5, GrandExchangeOfferState.BUYING, 1511, 0, 100, 5, 0);	// B places a new offer in slot 5
		assertEquals("A's held slot never becomes B's baseline",
			Arrays.asList("ge_offer", "ge_offer"), types());
		assertEquals(1511, ge().get(1).get("item"));
	}

	/** Held events never outlive the login that produced them. */
	@Test
	public void theLoginScreenDropsHeldEvents() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.HOPPING);
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
		state(GameState.LOGIN_SCREEN);		// the login failed or was cancelled
		hash = A;
		tick += 5;
		state(GameState.LOGGING_IN);
		state(GameState.LOGGED_IN);
		gameTick();
		assertEquals(Arrays.asList("ge_offer"), types());
	}

	// ---- (e) enabled while logged in ----

	@Test
	public void enabledWhileLoggedInSeedsTheSlotsAndEmitsNothingForTheSeed() throws Exception
	{
		slots[0] = o(GrandExchangeOfferState.BUYING, 560, 0, 1000, 250, 0);
		slots[1] = o(GrandExchangeOfferState.SELLING, 4151, 1, 5, 1_500_000, 1_500_000);
		slots[2] = o(GrandExchangeOfferState.BOUGHT, 1511, 100, 100, 5, 500);
		for (int s = 3; s < 8; s++)
		{
			slots[s] = o(GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		}
		setUp(GameState.LOGGED_IN);
		assertTrue("the seed itself is not activity: " + types(), types().isEmpty());

		tick += 5;
		offer(0, GrandExchangeOfferState.BUYING, 560, 0, 1000, 250, 0);	// re-sent unchanged: not a new offer
		assertTrue("an unchanged slot is not a placement: " + types(), types().isEmpty());

		tick += 5;
		offer(0, GrandExchangeOfferState.BUYING, 560, 300, 1000, 250, 75_000);
		assertEquals(Arrays.asList("ge_progress"), types());
		assertEquals(300, ge().get(0).get("qty"));

		tick += 5;
		offer(2, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);		// collect the offer that was done at enable
		assertEquals(Arrays.asList("ge_progress", "ge_collect"), types());
		Map<String, Object> c = ge().get(1);
		assertEquals("the collect names what the seeded slot held", 1511, c.get("item"));
		assertEquals("BOUGHT", c.get("state"));
		assertEquals(100, c.get("qty"));
	}

	/** Enabled at the login screen: no seed, the replay window handles the baseline. */
	@Test
	public void enabledOutsideTheWorldDoesNotSeed() throws Exception
	{
		slots[2] = o(GrandExchangeOfferState.BOUGHT, 1511, 100, 100, 5, 500);
		hash = -1L;
		setUp(GameState.LOGIN_SCREEN);
		hash = A;
		tick += 5;
		state(GameState.LOGGED_IN);
		tick += 10;
		offer(2, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		assertTrue("nothing seeded, nothing replayed, so no collect can be named: " + types(), types().isEmpty());
	}

	// ---- (f) a real account switch ----

	@Test
	public void aRealAccountSwitchClearsTheOldSlotsAndTheNewReplayEmitsNothing() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.LOGIN_SCREEN);
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		hash = -1L;
		state(GameState.LOGGING_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// B's own old offer, hash not known
		hash = B;
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);	// B's own old offer, hash known
		tick += 5;
		state(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2500);
		assertEquals("A's open offer never makes B's replay look finished", Arrays.asList("ge_offer"), types());

		tick += 20;
		offer(1, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0, 0);
		assertEquals(Arrays.asList("ge_offer", "ge_collect"), types());
		assertEquals(560, ge().get(1).get("item"));
	}

	/** Another account's replay of the same item in the same slot is never our sale. */
	@Test
	public void anotherAccountsReplayOfTheSameItemIsNotOurSale() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(3, GrandExchangeOfferState.SELLING, 4151, 0, 1, 1_500_000, 0);
		state(GameState.LOGIN_SCREEN);
		hash = B;
		state(GameState.LOGGING_IN);
		offer(3, GrandExchangeOfferState.SOLD, 4151, 1, 1, 1_500_000, 1_500_000);
		assertEquals("another account's replay of the same item is not our sale",
			Arrays.asList("ge_offer"), types());
	}
	@Test
	public void heldReplayKeepsCallbackTimeInsteadOfResolutionTime() throws Exception
	{
		setUp(GameState.LOGGED_IN);
		offer(1, GrandExchangeOfferState.BUYING, 560, 0, 10, 250, 0);
		state(GameState.HOPPING);
		hash = -1L;
		offer(1, GrandExchangeOfferState.BOUGHT, 560, 10, 10, 250, 2400);
		Field f = AccountConnectPlugin.class.getDeclaredField("geUnkeyed");
		f.setAccessible(true);
		Map<Integer, Object[]> held = (Map<Integer, Object[]>) f.get(p);
		long captured = (Long) held.get(1)[2];
		hash = A;
		p.resolveUnkeyedGe(A);
		Map<?, ?> observation = (Map<?, ?>) ge().get(1).get("ge_observation");
		assertEquals(captured, observation.get("observed_at_ms"));
		assertEquals(captured, observation.get("counter_observed_at_ms"));
		assertEquals(10L, observation.get("delta_qty"));
		p.resolveUnkeyedGe(A);
		assertEquals(2, ge().size());
	}

}

package com.osrsbestinslot.export;

import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import static net.runelite.api.GrandExchangeOfferState.*;
import static org.junit.Assert.*;

public class GeObservationTrackerTest
{
    private final GeObservationTracker tracker = new GeObservationTracker();

    private Map<String, Object> at(GrandExchangeOfferState state, long qty, long gp, int tick)
    {
        return tracker.observe(0, state, new long[]{560, qty, 100, 300, gp}, false, tick, 100000L + tick);
    }

    private Map<?, ?> meta(Map<String, Object> row)
    {
        assertNotNull(row);
        return (Map<?, ?>) row.get("ge_observation");
    }

    @Test
    public void coalescedDeltasTerminalAndCollectNeverDoubleCredit()
    {
        Map<String, Object> start = at(BUYING, 0, 0, 1);
        assertNull(at(BUYING, 10, 2400, 2));
        Map<String, Object> progress = at(BUYING, 40, 9000, 101);
        assertEquals(40L, meta(progress).get("delta_qty"));
        assertEquals(9000L, meta(progress).get("delta_gp"));
        assertEquals(100001L, meta(progress).get("interval_start_ms"));
        assertEquals(100101L, meta(progress).get("interval_end_ms"));
        assertEquals(300L, meta(progress).get("listing_price"));
        assertNull(meta(progress).get("execution_price"));
        assertNull(meta(progress).get("tax_gp"));
        Map<String, Object> end = at(BOUGHT, 100, 21000, 102);
        assertEquals(60L, meta(end).get("delta_qty"));
        assertEquals(12000L, meta(end).get("delta_gp"));
        assertNull(at(BOUGHT, 100, 21000, 103));
        Map<String, Object> collect = at(EMPTY, 0, 0, 104);
        assertEquals(0L, meta(collect).get("delta_qty"));
        assertEquals(0L, meta(collect).get("delta_gp"));
        assertEquals(start.get("offer_key"), collect.get("offer_key"));
        assertNotEquals(start.get("offer_key"), at(BUYING, 0, 0, 105).get("offer_key"));
    }

    @Test
    public void regressionQuarantinesEvenWhenCountersRecover()
    {
        at(BUYING, 0, 0, 1);
        assertEquals(50L, meta(at(BUYING, 50, 10000, 101)).get("delta_qty"));
        assertNull(at(BUYING, 20, 4000, 102));
        Map<?, ?> end = meta(at(BOUGHT, 100, 20000, 201));
        assertNull(end.get("delta_qty"));
        assertNull(end.get("delta_gp"));
        assertNull(end.get("interval_start_ms"));
        assertEquals("ambiguous_counter_regression", end.get("identity"));
    }

    @Test
    public void gpOnlyRegressionAndMalformedCountsCannotBeCredited()
    {
        at(BUYING, 10, 2000, 1);
        assertNull(at(BUYING, 20, 1000, 101));
        assertNull(meta(at(BOUGHT, 100, 20000, 201)).get("delta_gp"));
        tracker.clear();
        at(BUYING, 0, 0, 1);
        assertNull(at(BUYING, 101, 1000, 101));
        assertNull(meta(at(BOUGHT, 100, 20000, 201)).get("delta_qty"));
    }

    @Test
    public void identicalUnseenRelistOrStaleActiveAfterTerminalIsAmbiguous()
    {
        at(BUYING, 0, 0, 1);
        at(BOUGHT, 100, 20000, 101);
        at(BUYING, 0, 0, 102);
        assertNull(meta(at(BOUGHT, 100, 20000, 103)).get("delta_qty"));
    }

    @Test
    public void pendingThrottledFillIsCarriedByCollect()
    {
        at(BUYING, 0, 0, 1);
        assertNull(at(BUYING, 20, 4000, 2));
        Map<?, ?> collect = meta(at(EMPTY, 0, 0, 3));
        assertEquals(20L, collect.get("delta_qty"));
        assertEquals(100002L, collect.get("interval_end_ms"));
        assertEquals(100003L, collect.get("observed_at_ms"));
    }

    @Test
    public void partialReplayPreservesKeyAndOnlyCreditsTheDifference()
    {
        Map<String, Object> first = at(BUYING, 20, 4000, 1);
        tracker.gap();
        Map<String, Object> replay = tracker.observe(0, BUYING, new long[]{560, 40, 100, 300, 8000}, true, 2, 100002L);
        assertEquals(first.get("offer_key"), replay.get("offer_key"));
        assertEquals(20L, meta(replay).get("delta_qty"));
        assertEquals("inferred_across_gap", meta(replay).get("identity"));
        assertNull(tracker.observe(0, BUYING, new long[]{560, 40, 100, 300, 8000}, true, 3, 100003L));
        assertEquals(60L, meta(at(BOUGHT, 100, 20000, 4)).get("delta_qty"));
    }

    @Test
    public void restartAndOtherCollectorDoNotCreditHistoricalCumulativeTotals()
    {
        Map<String, Object> old = at(BUYING, 50, 10000, 1);
        tracker.clear();
        assertNull(tracker.observe(0, BUYING, new long[]{560, 80, 100, 300, 16000}, true, 2, 100002L));
        Map<String, Object> end = at(BOUGHT, 100, 20000, 3);
        assertNotEquals(old.get("offer_key"), end.get("offer_key"));
        assertEquals(20L, meta(end).get("delta_qty"));
        GeObservationTracker other = new GeObservationTracker();
        Map<String, Object> otherEnd = other.observe(0, BOUGHT, new long[]{560, 100, 100, 300, 20000}, false, 4, 100004L);
        assertEquals(0L, meta(otherEnd).get("delta_qty"));
        assertNotEquals(end.get("offer_key"), otherEnd.get("offer_key"));
    }

    @Test
    public void changedSignatureRotatesEvenWithoutQuantityIncrease()
    {
        Map<String, Object> first = at(BUYING, 40, 8000, 1);
        Map<String, Object> replaced = tracker.observe(0, SELLING, new long[]{560, 10, 100, 301, 3000}, false, 2, 100002L);
        assertNotEquals(first.get("offer_key"), replaced.get("offer_key"));
