	/**
	 * FINDING 2. A deferred removal must be classified at the tick it was REMOVED, not the tick we
	 * got around to concluding. Settling at `currentTick` let up to REMOVAL_RESOLVE_MAX_TICKS of
	 * drift cross the despawn deadline, silently upgrading a genuine `removed_early` to
	 * `despawn_timer` — a STRONGER claim than the evidence supports.
	 */
	@Test
	public void aDeferredEarlyRemovalStaysEarly() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);

		tick(plugin, 396);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 397);						// genuinely BEFORE the deadline
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		tick(plugin, 403);						// the Take never lands; window closes past 400
		plugin.onGameTick(new net.runelite.api.events.GameTick());

		Map<String, Object> ev = onlyEvent(plugin, "ground_removed");
		// NARROW CANDIDATE: a Take named this pile, so the cause is `unknown` rather than
		// `removed_early`. What this test actually pins is the STORED REMOVAL TICK, and that is
		// unchanged: the removal is classified at 397, not at the 403 settlement, so the deferral
		// can never drift a verdict across the 400 deadline into a stronger `despawn_timer`.
		assertEquals("a pile our own Take named cannot be blamed on a stranger",
			"unknown", ev.get("cause"));
		assertEquals("ticks_on_ground must measure the removal, not the settlement",
			Integer.valueOf(297), ev.get("ticks_on_ground"));
	}

	/** BOUNDARY. One tick before the deadline is early; at the deadline it is the timer. */
	@Test
	public void theDeadlineBoundaryIsNotBlurredByTheDeferral() throws Exception
	{
		AccountConnectPlugin early = newPlugin(POT, 1);
		dropItemAt(early, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(early, 396);
		early.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(early, 397);
		early.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		tick(early, 500);
		early.onGameTick(new net.runelite.api.events.GameTick());
		// NARROW CANDIDATE: a Take named the pile, so both arms read `unknown` on the CAUSE. The
		// boundary property is pinned on ticks_on_ground instead, which is what the deferral could
		// blur: 297 for the early arm, 298 for the on-time one, both measured at the removal tick.
		assertEquals("unknown", onlyEvent(early, "ground_removed").get("cause"));
		assertEquals("classified at the removal tick 397, not the 500 settlement",
			Integer.valueOf(297), onlyEvent(early, "ground_removed").get("ticks_on_ground"));

		AccountConnectPlugin onTime = newPlugin(POT, 1);
		dropItemAt(onTime, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(onTime, 396);
		onTime.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(onTime, 398);	// inside GROUND_EARLY_MARGIN_TICKS of the 400 deadline
		onTime.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		tick(onTime, 500);
		onTime.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals("unknown", onlyEvent(onTime, "ground_removed").get("cause"));
		assertEquals("classified at the removal tick 398, not the 500 settlement",
			Integer.valueOf(298), onlyEvent(onTime, "ground_removed").get("ticks_on_ground"));
	}

	/**
	 * FINDING 5. A tick counter that moves BACKWARDS must not strand a parked removal forever.
	 * `currentTick - stored` goes negative and never reaches the window, so the event is lost.
	 * A late verdict beats a missing one.
	 */
	@Test
	public void aBackwardsTickCounterStillFinalizesTheRemoval() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 5000, 5300, TILE_X, TILE_Y);
		tick(plugin, 5001);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));

		tick(plugin, 3);	// the counter jumped backwards; no state change fired
		plugin.onGameTick(new net.runelite.api.events.GameTick());

		assertEquals("a parked removal must never be stranded by a backwards tick",
			1, eventsOfType(plugin, "ground_removed").size());
	}

	private static void dropItem(AccountConnectPlugin plugin, int item, int qty, int atTick, int despawnTick,
		int... remaining) throws Exception
	{
		tick(plugin, atTick);
		plugin.onMenuOptionClicked(menu("Drop", "", item));
		setInventory(plugin, remaining);
		spawn(plugin, item, qty, despawnTick);
	}

	private static void spawn(AccountConnectPlugin plugin, int item, int qty, int despawnTick)
		throws Exception
	{
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(TILE_X, TILE_Y, 0), tileItem(item, qty, despawnTick)));
	}

	/** Move the local player, so a drop on a different tile is close enough to be confirmed. */
	private static void standAt(AccountConnectPlugin plugin, int x, int y) throws Exception
	{
		when(client(plugin).getLocalPlayer().getWorldLocation()).thenReturn(new WorldPoint(x, y, 0));
	}

	/** Drop one item on an EXPLICIT tile: walk there first, then drop and confirm the spawn. */
	private static void dropItemAt(AccountConnectPlugin plugin, int item, int qty, int atTick,
		int despawnTick, int x, int y, int... remaining) throws Exception
	{
		standAt(plugin, x, y);
		tick(plugin, atTick);
		plugin.onMenuOptionClicked(menu("Drop", "", item));
		setInventory(plugin, remaining);
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(x, y, 0), tileItem(item, qty, despawnTick)));
	}

	private static net.runelite.api.events.ItemDespawned despawn(int item, int qty, int x, int y, int plane)
	{
		return new net.runelite.api.events.ItemDespawned(tile(x, y, plane), tileItem(item, qty, 0));
	}

	private static net.runelite.api.Tile tile(int x, int y, int plane)
	{
		net.runelite.api.Tile t = mock(net.runelite.api.Tile.class);
		when(t.getWorldLocation()).thenReturn(new WorldPoint(x, y, plane));
		return t;
	}

	private static net.runelite.api.TileItem tileItem(int id, int qty, int despawnTick)
	{
		net.runelite.api.TileItem it = mock(net.runelite.api.TileItem.class);
		when(it.getId()).thenReturn(id);
		when(it.getQuantity()).thenReturn(qty);
		when(it.getDespawnTime()).thenReturn(despawnTick);
		when(it.getOwnership()).thenReturn(net.runelite.api.TileItem.OWNERSHIP_SELF);
		return it;
	}

	private static net.runelite.api.events.GameStateChanged gameState(GameState st)
	{
		net.runelite.api.events.GameStateChanged ev = new net.runelite.api.events.GameStateChanged();
		ev.setGameState(st);
		return ev;
	}

	private static AccountConnectPlugin newPlugin(int... idQtyPairs) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv0 = container(idQtyPairs);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv0);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(0);
		when(client.getTickCount()).thenReturn(100);
		// WorldPoint.fromScene() reads the world view's base coordinates. Base 0 makes the scene
		// coordinates in a Take menu entry equal to world coordinates, which keeps the tile
		// assertions readable. Without this the conversion returns null and every tile check
		// silently degrades to item-id-only matching — i.e. passes for the wrong reason.
		net.runelite.api.WorldView wv = mock(net.runelite.api.WorldView.class);
		when(wv.getBaseX()).thenReturn(0);
		when(wv.getBaseY()).thenReturn(0);
		when(client.getTopLevelWorldView()).thenReturn(wv);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(TILE_X, TILE_Y, 0));
		inject(plugin, "client", client);
		return plugin;
	}

	private static void setInventory(AccountConnectPlugin plugin, int... idQtyPairs) throws Exception
	{
		ItemContainer next = container(idQtyPairs);
		when(client(plugin).getItemContainer(InventoryID.INVENTORY)).thenReturn(next);
	}

	private static net.runelite.api.events.ItemContainerChanged invChanged(AccountConnectPlugin plugin)
		throws Exception
	{
		ItemContainer inv = client(plugin).getItemContainer(InventoryID.INVENTORY);
		return new net.runelite.api.events.ItemContainerChanged(InventoryID.INVENTORY.getId(), inv);
	}

	private static Client client(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		return (Client) f.get(plugin);
	}

	private static void setUnreliable(AccountConnectPlugin plugin, boolean v) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("groundObservationUnreliable");
		f.setAccessible(true);
		f.setBoolean(plugin, v);
	}

	private static void tick(AccountConnectPlugin plugin, int t) throws Exception
	{
		when(client(plugin).getTickCount()).thenReturn(t);
	}

	private static List<Map<String, Object>> eventsOfType(AccountConnectPlugin plugin, String type)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				out.add(e);
			}
		}
		return out;
	}

	private static Map<String, Object> firstEvent(AccountConnectPlugin plugin, String type)
	{
		List<Map<String, Object>> all = eventsOfType(plugin, type);
		return all.isEmpty() ? null : all.get(0);
	}

	private static Map<String, Object> onlyEvent(AccountConnectPlugin plugin, String type)
	{
		List<Map<String, Object>> all = eventsOfType(plugin, type);
		assertEquals("expected exactly one " + type + " event, got " + all, 1, all.size());
		return all.get(0);
	}

	/** The REAL ground-item Take entry: itemId is -1, the item id sits in the identifier. */
	private static MenuOptionClicked groundTake(String name, int itemId)
	{
		return groundTakeAt(name, itemId, TILE_X, TILE_Y);
	}

	/**
	 * The REAL ground-item Take entry, aimed at one specific tile.
	 *
	 * itemId is -1, the item id sits in the identifier, the opcode is GROUND_ITEM_THIRD_OPTION and
	 * param0/param1 carry the pile's SCENE coordinates. The test client mock reports base 0, so the
	 * scene coordinates ARE the world coordinates here.
	 */
	/** A Take the client gave us no usable tile for: the opcode is right, the scene coords are not. */
	private static MenuOptionClicked takeWithNoTile(String name, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(itemId);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION);
		when(m.getParam0()).thenThrow(new IllegalStateException("no scene coords"));
		return m;
	}

	private static MenuOptionClicked groundTakeAt(String name, int itemId, int x, int y)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(itemId);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION);
		when(m.getParam0()).thenReturn(x);
		when(m.getParam1()).thenReturn(y);
		return m;
	}

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class) { return Boolean.TRUE; }
				if (rt == String.class) { return "0123456789abcdef0123456789abcdef"; }
				if (rt == int.class || rt == Integer.class) { return 0; }
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static net.runelite.api.GrandExchangeOfferState.*;

/** Exercise current domain implementations together, rather than a historical JSON handoff fixture. */
public class HistoryDomainIntegrationTest
{
    @Test public void currentWireReducerAndWealthAdapterPreserveFillAndOwnerBoundary()
    {
        GeObservationTracker tracker = new GeObservationTracker();
        tracker.observe(0, EMPTY, new long[]{0,0,0,0,0}, false, 1, 1_001_000L);
        List<Map<String, Object>> wire = new ArrayList<>();
        for (int n = 0; n < 2; n++)
        {
            Map<String, Object> event = tracker.observe(0, n == 0 ? BUYING : BOUGHT,
                new long[]{560,n == 0 ? 0 : 10,10,250,n == 0 ? 0 : 2400}, false, n+2, 1_002_000L+n*1000);
            event.put("account_hash", "42");
            event.put("profile_type", "STANDARD");
            event.put("event_id", String.format("%032x", n+1));
            wire.add(PublicTransport.event(event));
        }
        Map<String, Object> reduced = GeOfferLifecycle.reduce(wire, null, "same-owned-generation");
        List<String> excluded = new ArrayList<>();
        List<WealthReconciliation.TradeFact> facts = WealthReconciliation.tradeFactsFromC1(
            reduced, "42", "STANDARD", 1_000_000L, 1_020_000L, excluded);
        assertEquals(1, facts.size());
        assertEquals(560, facts.get(0).itemId);
        assertEquals(10L, facts.get(0).qtyDelta);
        assertEquals(Long.valueOf(-2400L), facts.get(0).coinsDelta);
        assertTrue(excluded.isEmpty());
        assertTrue(WealthReconciliation.tradeFactsFromC1(reduced, "other", "STANDARD",
            1_000_000L, 1_020_000L, new ArrayList<>()).isEmpty());
        assertTrue(WealthReconciliation.tradeFactsFromC1(reduced, "42", "LEAGUE",
            1_000_000L, 1_020_000L, new ArrayList<>()).isEmpty());
        excluded.clear();
        assertTrue(WealthReconciliation.tradeFactsFromC1(reduced, "42", "STANDARD",
            1_002_000L, 1_020_000L, excluded).isEmpty());
        assertTrue(excluded.get(0).endsWith(":fill_straddles_window"));
    }

    @Test public void currentLoadoutConsumerKeepsRealWealthUnknownLocations()
    {
        LoadoutRevision revisions = new LoadoutRevision("same-owned-generation");
        Map<String, Object> revision = revisions.observe(Collections.singletonMap(3, 4151), 10, 10_000L);
        WealthLedger.Holdings unreadBank = new WealthLedgerTest.Snap(WealthLedgerTest.T0).h();
        Map<?, ?> slots = (Map<?, ?>) LoadoutRevision.ownership(revision, unreadBank::owns).get("slots");
        Map<?, ?> weapon = (Map<?, ?>) slots.get("weapon");
        assertEquals("not_seen_in_observed", weapon.get("current_holdings"));
        assertTrue(((List<?>) weapon.get("unknown_locations")).contains("bank"));
        WealthLedger.Holdings worn = new WealthLedgerTest.Snap(WealthLedgerTest.T0).worn("weapon", 4151, 1).h();
        slots = (Map<?, ?>) LoadoutRevision.ownership(revision, worn::owns).get("slots");
        assertEquals("owned_observed", ((Map<?, ?>) slots.get("weapon")).get("current_holdings"));
    }
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.game.ItemManager;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * 0.7.62, agreed with the server on 2026-10-28: the server keeps only the newest complete bank of a player, from
 * the snapshot. So a player's bank visit sends no open or close item list when a snapshot queued for upload holds
 * that same bank, and says so with manifest_in_snapshot. Without such a snapshot the list goes as chunks, as
 * before. A staff visit always sends its lists.
 */
public class LatestBankSnapshotTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int BANK_GROUP = 12;
	private static final int BANK = net.runelite.api.gameval.InventoryID.BANK;

	private MockWebServer server;
	private AccountConnectPlugin plugin;
	private Client client;
	private ItemContainer bank;
	private boolean staff;
	private int tick = 1000;
	private int failNext;		// refuse this many uploads with a 503
	private int dropNext;		// fail this many uploads on the network
	private final DirectExecutor executor = new DirectExecutor();

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.setDispatcher(new Dispatcher()
		{
			@Override
			public MockResponse dispatch(RecordedRequest request)
			{
				if (failNext > 0)
				{
					failNext--;	// a refused upload that still carries the token's grants
					return grant(new MockResponse().setResponseCode(503));
				}
				return grant(new MockResponse().setResponseCode(200));
			}
		});
		server.start();
		plugin = new AccountConnectPlugin();
		client = mock(Client.class);
		Player player = mock(Player.class);
		when(player.getName()).thenReturn("Fixture Main");
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getAccountHash()).thenReturn(42L);
		when(client.getTickCount()).thenAnswer(i -> tick);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(client.getRealSkillLevel(Skill.HITPOINTS)).thenReturn(10);
		when(client.getSkillExperience(any(Skill.class))).thenReturn(0);
		when(client.getVarps()).thenReturn(new int[5000]);
		when(client.getItemContainer(InventoryID.BANK)).thenAnswer(i -> bank);
		String baseUrl = server.url("/").toString();
		inject("config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl;
			}
		});
		inject("client", client);
		inject("gson", new Gson());
		// Calls run on the calling thread, so a response (which clears a 429 backoff) lands before the next step.
		inject("okHttpClient", new OkHttpClient.Builder().dispatcher(new okhttp3.Dispatcher(executor))
			.addInterceptor(chain ->
			{
				if (dropNext > 0)
				{
					dropNext--;
					throw new java.io.IOException("connection lost");	// the plugin's onFailure path
				}
				return chain.proceed(chain.request());
			}).build());
		inject("itemManager", mock(ItemManager.class));
		inject("activeHash", "42");
	}

	private static final class DirectExecutor extends java.util.concurrent.AbstractExecutorService
	{
		private boolean shutdown;

		boolean hold;
		final List<Runnable> held = new ArrayList<>();

		@Override
		public void execute(Runnable command)
		{
			if (hold)
			{
				held.add(command);
				return;
			}
			command.run();
		}

		void release()
		{
			hold = false;
			for (Runnable r : new ArrayList<>(held))
			{
				r.run();
			}
			held.clear();
		}

		@Override
		public void shutdown()
		{
			shutdown = true;
		}

		@Override
		public List<Runnable> shutdownNow()
		{
			shutdown = true;
			return new ArrayList<>();
		}

		@Override
		public boolean isShutdown()
		{
			return shutdown;
		}

		@Override
		public boolean isTerminated()
		{
			return shutdown;
		}

		@Override
		public boolean awaitTermination(long timeout, TimeUnit unit)
		{
			return true;
		}
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	/** A player gets the bank receipt; staff gets the spool instead, never both. */
	private MockResponse grant(MockResponse r)
	{
		r.addHeader("X-Bank-Evidence", "on");
		return staff ? r.addHeader("X-Event-Spool", "on") : r.addHeader("X-Bank-Receipt", "event-id-v1");
	}

	private void policy() throws Exception
	{
		okhttp3.Response.Builder b = new okhttp3.Response.Builder()
			.request(new okhttp3.Request.Builder().url("http://localhost/").build())
			.protocol(okhttp3.Protocol.HTTP_1_1).code(200).message("OK").header("X-Bank-Evidence", "on");
		if (staff)
		{
			b.header("X-Event-Spool", "on");
		}
		else
		{
			b.header("X-Bank-Receipt", "event-id-v1");
		}
		plugin.applyServerPolicy(b.build(), TOKEN);
	}

	private void inject(String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static ItemContainer container(int[]... rows)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] arr = new Item[rows.length];
		for (int i = 0; i < rows.length; i++)
		{
			arr[i] = new Item(rows[i][0], rows[i][1]);
		}
		when(c.getItems()).thenReturn(arr);
		when(c.getId()).thenReturn(BANK);
		return c;
	}

	/** The bank's contents arrive in the tick it opens, so the open snapshot's read has a known time. */
	private void open(ItemContainer b)
	{
		bank = b;
		plugin.onItemContainerChanged(new ItemContainerChanged(BANK, b));
		plugin.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);
	}

	private void change(ItemContainer b)
	{
		bank = b;
		plugin.onItemContainerChanged(new ItemContainerChanged(BANK, b));
	}

	/**
	 * The close, the next regular snapshot (the 120 s upload interval has passed), and game ticks until the close
	 * goes out: at once when an accepted snapshot holds its bank, otherwise after the wait.
	 */
	private void close()
	{
		plugin.handleBankWidgetClosed(BANK_GROUP);
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		regularUpload();
		tick++;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		tick += AccountConnectPlugin.PUBLIC_CLOSE_WAIT_TICKS;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
	}

	private void regularUpload()
	{
		plugin.lastSendMillis = 0L;
		plugin.syncTask();
	}

	private List<Map<String, Object>> of(String type)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				out.add(e);
			}
		}
		return out;
	}

	private List<Map<String, Object>> chunks(String phase)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : of("bank_visit_manifest_chunk"))
		{
			if (phase.equals(e.get("phase")))
			{
				out.add(e);
			}
		}
		return out;
	}

	/** Bank blocks of every snapshot the server received, in order. */
	private List<Map<?, ?>> sentBanks() throws Exception
	{
		List<Map<?, ?>> out = new ArrayList<>();
		RecordedRequest req;
		while ((req = server.takeRequest(200, TimeUnit.MILLISECONDS)) != null)
		{
			Map<?, ?> body = new Gson().fromJson(req.getBody().readUtf8(), Map.class);
			Object snap = body.get("snapshot");
			if (snap instanceof Map)
			{
				out.add((Map<?, ?>) ((Map<?, ?>) snap).get("bank"));
			}
		}
		return out;
	}

	@Test
	public void theSnapshotBankCarriesTheVisitHashAndItsStackCount() throws Exception
	{
		policy();
		bank = container(new int[]{4151, 1}, new int[]{995, 1000}, new int[]{995, 5});
		plugin.forceSendSnapshot();
		Map<?, ?> sent = sentBanks().get(0);
		assertNull("one item in two slots does not match its items list, so no hash", sent.get("manifest_sha256"));

		bank = container(new int[]{4151, 1}, new int[]{995, 1000});
		plugin.forceSendSnapshot();
		sent = sentBanks().get(0);
		Map<Integer, Long> counts = new LinkedHashMap<>();
		counts.put(4151, 1L);
		counts.put(995, 1000L);
		assertEquals(BankVisitManifest.sha256(BankVisitManifest.canonical(counts)), sent.get("manifest_sha256"));
		assertEquals(2.0, sent.get("item_stacks"));
		assertEquals("item_stacks counts the items list of the same block", 2, ((List<?>) sent.get("items")).size());
	}

	@Test
	public void anUnreadBankHasNoHash() throws Exception
	{
		policy();
		plugin.forceSendSnapshot();
		Map<?, ?> sent = sentBanks().get(0);
		assertTrue(((List<?>) sent.get("items")).isEmpty());
		assertFalse(sent.containsKey("manifest_sha256"));
		assertFalse(sent.containsKey("item_stacks"));
	}

	@Test
	public void aPlayersVisitSendsNoItemListWhenAQueuedSnapshotHoldsIt() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));			// the whip leaves
		close();

		Map<String, Object> open = of("bank_visit_open").get(0);
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertEquals(true, open.get("manifest_in_snapshot"));
		assertEquals(2, open.get("item_stacks"));
		assertNotNull(open.get("manifest_sha256"));
		assertEquals(true, close.get("manifest_in_snapshot"));
		assertEquals(1, close.get("end_item_stacks"));
		assertFalse(close.containsKey("end_chunks"));
		assertTrue("no open or close list", chunks("open").isEmpty() && chunks("close").isEmpty());
		assertEquals(true, close.get("moves_complete"));
		assertEquals("the moves still go inline", 1, ((List<?>) close.get("withdrawn")).size());

		List<Map<?, ?>> banks = sentBanks();
		assertEquals("the open hash was queued", open.get("manifest_sha256"), banks.get(0).get("manifest_sha256"));
		Map<?, ?> last = banks.get(banks.size() - 1);
		assertEquals("the end bank was queued", close.get("end_manifest_sha256"), last.get("manifest_sha256"));
		assertNotNull("with a known read time", last.get("observed_at"));
	}

	@Test
	public void withNoSnapshotQueuedTheListsGoAsChunks() throws Exception
	{
		policy();
		plugin.backoffUntilMillis = Long.MAX_VALUE;		// a 429 backoff: no snapshot can be queued
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));
		close();

		Map<String, Object> open = of("bank_visit_open").get(0);
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertFalse(open.containsKey("manifest_in_snapshot"));
		assertFalse(close.containsKey("manifest_in_snapshot"));
		assertFalse(close.containsKey("end_item_stacks"));
		assertEquals(1, chunks("open").size());
		assertEquals(1, chunks("close").size());
		assertEquals(1, close.get("end_chunks"));
		assertTrue(sentBanks().isEmpty());
	}

	@Test
	public void aSnapshotQueuedForAnotherAccountDoesNotCount() throws Exception
	{
		policy();
		bank = container(new int[]{995, 1000});
		plugin.forceSendSnapshot();						// queued under account 42
		when(client.getAccountHash()).thenReturn(43L);		// a relog to another account
		inject("activeHash", "43");
		plugin.backoffUntilMillis = Long.MAX_VALUE;
		open(container(new int[]{995, 1000}));
		close();
		assertFalse(of("bank_visit_open").get(0).containsKey("manifest_in_snapshot"));
		assertEquals(1, chunks("open").size());
		assertEquals(1, chunks("close").size());
	}

	@Test
	public void aQueuedSnapshotOfAnOlderBankDoesNotCount() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));	// the open snapshot is queued
		plugin.backoffUntilMillis = Long.MAX_VALUE;
		change(container(new int[]{995, 1000}));
		close();
		assertEquals(true, of("bank_visit_open").get(0).get("manifest_in_snapshot"));
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertFalse("the queued bank still holds the whip", close.containsKey("manifest_in_snapshot"));
		assertEquals(1, chunks("close").size());
	}

	@Test
	public void theOpenCountsAnUntimedOpenSnapshotButTheCloseNeedsATimedOne() throws Exception
	{
		policy();
		bank = container(new int[]{995, 1000});
		plugin.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);			// contents not confirmed in this tick
		plugin.backoffUntilMillis = Long.MAX_VALUE;
		Map<?, ?> queued = sentBanks().get(0);
		assertNull(queued.get("observed_at"));
		assertNotNull(queued.get("manifest_sha256"));
		close();
		assertEquals("the bank-open snapshot is never timed", true,
			of("bank_visit_open").get(0).get("manifest_in_snapshot"));
		assertTrue(chunks("open").isEmpty());
		assertFalse("only a timed bank stands for the close", of("bank_visit_close").get(0).containsKey("manifest_in_snapshot"));
		assertEquals(1, chunks("close").size());
	}

	@Test
	public void theCloseForcesNoUploadAndWaitsForAnAcceptedRegularOne() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));
		int before = server.getRequestCount();
		plugin.handleBankWidgetClosed(BANK_GROUP);			// the close script's WidgetClosed
		tick++;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals("no extra upload for a visit", before, server.getRequestCount());
		assertTrue("waits for a snapshot holding the end bank", of("bank_visit_close").isEmpty());
		regularUpload();
		assertEquals(before + 1, server.getRequestCount());
		tick++;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals(true, of("bank_visit_close").get(0).get("manifest_in_snapshot"));
		assertTrue(chunks("close").isEmpty());
	}

	@Test
	public void anUploadStillInFlightDoesNotStandForTheClose() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));
		plugin.handleBankWidgetClosed(BANK_GROUP);
		executor.hold = true;
		regularUpload();									// sent, no answer yet
		tick++;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		assertTrue("not before the server accepted it", of("bank_visit_close").isEmpty());
		executor.release();
		tick++;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals(true, of("bank_visit_close").get(0).get("manifest_in_snapshot"));
	}

	@Test
	public void aLostUploadIsNeverClaimed() throws Exception
	{
		policy();
		dropNext = 1;										// the bank-open snapshot is lost on the network
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		assertFalse(of("bank_visit_open").get(0).containsKey("manifest_in_snapshot"));
		assertEquals(1, chunks("open").size());
		plugin.handleBankWidgetClosed(BANK_GROUP);
		assertTrue("a backoff after the loss", plugin.backoffUntilMillis > System.currentTimeMillis());
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));	// a reopen during the backoff
		Map<String, Object> second = of("bank_visit_open").get(1);
		assertFalse("no claim from the refused upload", second.containsKey("manifest_in_snapshot"));
		assertEquals(2, chunks("open").size());
	}

	@Test
	public void anUploadThatFailsAfterTheCloseLeavesTheListAsChunks() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));
		plugin.handleBankWidgetClosed(BANK_GROUP);
		failNext = 1;
		regularUpload();									// fails: nothing on the server holds the end bank
		tick += AccountConnectPlugin.PUBLIC_CLOSE_WAIT_TICKS;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertFalse(close.containsKey("manifest_in_snapshot"));
		assertEquals(1, chunks("close").size());
	}

	@Test
	public void aShopCloseWithAPendingBuyBuildsOnTheNextTick() throws Exception
	{
		policy();
		plugin.storePendings.put(560, new AccountConnectPlugin.StorePending("store_buy", 560, 10, 100L, 5L, tick, false, false));
		int before = server.getRequestCount();
		plugin.onWidgetClosed(new net.runelite.api.events.WidgetClosed(net.runelite.api.gameval.InterfaceID.SHOPMAIN, 0, false));
		assertEquals(1, of("store_buy").size());
		assertEquals("no build inside the shop close script", before, server.getRequestCount());
		tick++;
		plugin.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals(before + 1, server.getRequestCount());
	}

	@Test
	public void aLogoutBeforeTheNextTickSendsTheCloseWithItsList() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));
		plugin.handleBankWidgetClosed(BANK_GROUP);
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		net.runelite.api.events.GameStateChanged e = new net.runelite.api.events.GameStateChanged();
		e.setGameState(GameState.LOGIN_SCREEN);
		plugin.onGameStateChanged(e);
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertFalse(close.containsKey("manifest_in_snapshot"));
		assertEquals(1, close.get("end_chunks"));
		assertEquals(1, chunks("close").size());
	}

	@Test
	public void aStaffVisitAlwaysSendsItsLists() throws Exception
	{
		staff = true;
		policy();
		open(container(new int[]{995, 1000}, new int[]{4151, 1}));
		change(container(new int[]{995, 1000}));
		close();

		Map<String, Object> open = of("bank_visit_open").get(0);
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertFalse(open.containsKey("manifest_in_snapshot"));
		assertFalse(close.containsKey("manifest_in_snapshot"));
		assertEquals(1, chunks("open").size());
		assertEquals(1, chunks("close").size());
		assertEquals(1, close.get("end_chunks"));
	}

	@Test
	public void aTeardownCloseIsUnchanged() throws Exception
	{
		policy();
		open(container(new int[]{995, 1000}));
		plugin.handleBankWidgetClosed(BANK_GROUP, true);	// unload: hop, logout, disconnect
		Map<String, Object> close = of("bank_visit_close").get(0);
		assertFalse(close.containsKey("manifest_in_snapshot"));
		assertFalse(close.containsKey("end_manifest_sha256"));
		assertTrue(chunks("close").isEmpty());
	}

	@Test
	public void thePublicProjectionKeepsTheNewFields()
	{
		Map<String, Object> close = new LinkedHashMap<>();
		close.put("type", "bank_visit_close");
		close.put("event_id", "0123456789abcdef0123456789abcdef");
		close.put("visit_id", "0123456789abcdef0123456789abcdef");
		close.put("end_item_stacks", 3);
		close.put("manifest_in_snapshot", true);
		Map<String, Object> out = PublicTransport.event(close, false);
		assertEquals(3, out.get("end_item_stacks"));
		assertEquals(true, out.get("manifest_in_snapshot"));

		Map<String, Object> open = new LinkedHashMap<>();
		open.put("type", "bank_visit_open");
		open.put("event_id", "0123456789abcdef0123456789abcdef");
		open.put("manifest_in_snapshot", true);
		assertEquals(true, PublicTransport.event(open, false).get("manifest_in_snapshot"));
	}
}

package com.osrsbestinslot.export;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.LinkedHashMap;
import net.runelite.api.Item;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.*;

public class LoadoutRevisionTest
{
    private static final int HEAD = 0, WEAPON = 3, BODY = 4, HAIR = 8, AMMO = 13;

    private static Map<Integer, Integer> gear(int... slotItem)
    {
        Map<Integer, Integer> m = new TreeMap<>();
        for (int i = 0; i < slotItem.length; i += 2) m.put(slotItem[i], slotItem[i + 1]);
        return m;
    }

    /** Shape of C4 WealthLedger.owns at da11975: answer plus location lists. Absent item = unknown answer. */
    private static java.util.function.IntFunction<Map<String, Object>> c4(Map<Integer, String> answers)
    {
        return id -> {
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("item_id", id);
            String answer = answers.getOrDefault(id, "unknown");
            m.put("answer", answer.startsWith("yes") ? "yes" : answer);
            if (answer.startsWith("yes"))
            {
                Map<String, Object> row = new LinkedHashMap<>();
                row.put("location", "bank");
                row.put("state", answer.equals("yes:carried") ? "carried" : "observed");
                m.put("seen", new java.util.ArrayList<>(java.util.Arrays.asList(row)));
            }
            m.put("unknown_locations", new java.util.ArrayList<>(java.util.Arrays.asList("bank")));
            m.put("stale_locations", new java.util.ArrayList<String>());
            m.put("bounded_locations", new java.util.ArrayList<>(java.util.Arrays.asList("ge_collect")));
            m.put("unsupported_locations", new java.util.ArrayList<>(java.util.Arrays.asList("rune_pouch", "poh_storage")));
            m.put("undated_locations", new java.util.ArrayList<String>());
            m.put("carried_locations", new java.util.ArrayList<String>());
            return m;
        };
    }

    @Test
    public void firstObservationIsBaselineAndUnknownIsNotEmpty()
    {
        LoadoutRevision l = new LoadoutRevision("gen-a");
        assertNull(l.activeAt(100));
        assertNull(l.observe(null, 100, 1L)); // container unavailable: no revision, still unknown
        assertNull(l.activeAt(100));
        Map<String, Object> r = l.observe(gear(WEAPON, 4151, BODY, 10551), 101, 2L);
        assertEquals("baseline", r.get("provenance"));
        assertEquals(1, r.get("revision_seq"));
        assertEquals("loadout.revision.v1", r.get("schema"));
        assertEquals(4151, ((Map<?, ?>) r.get("slots")).get("weapon"));
        assertNull(r.get("previous_content_id"));
    }

    @Test
    public void onlyItemIdChangesMakeRevisionsAndOrderIsMonotonic()
    {
        LoadoutRevision l = new LoadoutRevision("gen-a");
        Map<String, Object> a = l.observe(gear(WEAPON, 4151), 10, 1L);
        assertNull(l.observe(gear(WEAPON, 4151), 11, 2L)); // same map, quantity-only change is invisible here
        Map<String, Object> b = l.observe(gear(WEAPON, 12006), 20, 3L);
        assertEquals("observed_change", b.get("provenance"));
        assertEquals(2, b.get("revision_seq"));
        assertEquals(a.get("content_id"), b.get("previous_content_id"));
        assertSame(a, l.activeAt(15));
        assertSame(b, l.activeAt(20));
        assertNull(l.activeAt(9));
    }

    @Test
    public void contentIdIsStableAcrossGenerationsAndIgnoresBodyKitAndEmpties()
    {
        Map<String, Object> a = new LoadoutRevision("gen-a").observe(gear(HEAD, 10828, WEAPON, 4151), 1, 1L);
        Map<String, Object> b = new LoadoutRevision("gen-b").observe(gear(WEAPON, 4151, HEAD, 10828, HAIR, 3, AMMO, -1), 99, 9L);
        assertEquals(a.get("content_id"), b.get("content_id"));
        assertNotEquals(a.get("generation"), b.get("generation"));
        Map<String, Object> c = new LoadoutRevision("gen-c").observe(gear(HEAD, 4151, WEAPON, 10828), 1, 1L);
        assertNotEquals(a.get("content_id"), c.get("content_id")); // same items in other slots is other gear
    }

    @Test
    public void gapMakesGearUnknownUntilTheNextBaseline()
    {
        LoadoutRevision l = new LoadoutRevision("gen-a");
        Map<String, Object> a = l.observe(gear(WEAPON, 4151), 10, 1L);
        l.gap(30);
        assertSame(a, l.activeAt(29));
        assertNull(l.activeAt(31)); // gear during a gap is not assumed unchanged
        Map<String, Object> b = l.observe(gear(WEAPON, 4151), 40, 2L);
        assertEquals("baseline", b.get("provenance")); // same gear after a gap is re-proved, not a change
        assertEquals(a.get("content_id"), b.get("content_id"));
        assertNull(l.activeAt(35));
        assertSame(b, l.activeAt(41));
    }

    @Test
    public void evictionKeepsSequenceAndOldTicksBecomeUnknown()
    {
        LoadoutRevision l = new LoadoutRevision("gen-a");
        for (int i = 0; i < LoadoutRevision.MAX_REVISIONS + 5; i++) l.observe(gear(WEAPON, 1000 + i), i, i);
        assertEquals(LoadoutRevision.MAX_REVISIONS, l.revisions().size());
        assertEquals(5, l.evicted());
        assertEquals(6, l.revisions().get(0).get("revision_seq"));
        assertNull(l.activeAt(2));
    }

    @Test
    public void ownershipUsesC4AnswersAndNeverTurnsUnknownIntoNotOwned()
    {
        Map<String, Object> r = new LoadoutRevision("gen-a").observe(gear(WEAPON, 4151, BODY, 10551, HEAD, 10828), 1, 1L);
        Map<Integer, String> answers = new HashMap<>();
        answers.put(4151, "yes");
        answers.put(10551, "no_in_observed_locations");
        Map<String, Object> o = LoadoutRevision.ownership(r, c4(answers));
        Map<?, ?> slots = (Map<?, ?>) o.get("slots");
        assertEquals("owned_observed", ((Map<?, ?>) slots.get("weapon")).get("current_holdings"));
        assertEquals("not_seen_in_observed", ((Map<?, ?>) slots.get("body")).get("current_holdings"));
        assertEquals("unknown", ((Map<?, ?>) slots.get("head")).get("current_holdings"));
        answers.put(10828, "yes:carried"); // seen only in a reading carried from an earlier snapshot
        Map<?, ?> carried = (Map<?, ?>) ((Map<?, ?>) LoadoutRevision.ownership(r, c4(answers)).get("slots")).get("head");
        assertEquals("owned_possibly_outdated", carried.get("current_holdings"));
        assertEquals(java.util.Arrays.asList("rune_pouch", "poh_storage"),
            ((Map<?, ?>) slots.get("body")).get("unsupported_locations"));
        assertEquals(java.util.Collections.singletonList("ge_collect"), ((Map<?, ?>) slots.get("body")).get("bounded_locations"));
        Map<?, ?> none = (Map<?, ?>) ((Map<?, ?>) LoadoutRevision.ownership(r, null).get("slots")).get("body");
        assertEquals("unknown", none.get("current_holdings"));
        assertNull(none.get("stale_locations"));
        assertEquals("unavailable", LoadoutRevision.ownership(r, null).get("holdings_source"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void generationIsRequired()
    {
        new LoadoutRevision("");
    }

    @Test
    public void slotsOfKeepsUnavailableDistinctFromEmpty()
    {
        assertNull(LoadoutRevision.slotsOf(null));
        assertTrue(LoadoutRevision.slotsOf(new Item[14]).isEmpty());
        Item[] worn = new Item[14];
        worn[WEAPON] = new Item(4151, 1);
        worn[AMMO] = new Item(11212, 0); // zero quantity is not worn
        worn[HAIR] = new Item(-1, 0);
        assertEquals(gear(WEAPON, 4151), LoadoutRevision.slotsOf(worn));
    }

    /**
     * C2 fixture: baseline -> weapon swap -> logout gap -> same gear re-proved by baseline. Encounter queries
     * at ticks before, inside and after the gap show known versus unknown equipment.
     */
    @Test
    public void representativeSessionMatchesCommittedFixture() throws Exception
    {
        LoadoutRevision l = new LoadoutRevision("caller-generation-1");
        l.observe(gear(HEAD, 10828, BODY, 10551, WEAPON, 4151, AMMO, 11212), 1000, 1760880000000L);
        l.observe(gear(HEAD, 10828, BODY, 10551, WEAPON, 12006, AMMO, 11212), 1010, 1760880006000L);
        l.gap(1100);
        l.observe(gear(HEAD, 10828, BODY, 10551, WEAPON, 12006, AMMO, 11212), 1300, 1760880180000L);
        Map<String, Object> example = new LinkedHashMap<>();
        example.put("revisions", l.revisions());
        Map<String, Object> queries = new LinkedHashMap<>();
        for (int t : new int[]{999, 1005, 1050, 1200, 1300})
        {
            Map<String, Object> rev = l.activeAt(t);
            queries.put("tick_" + t, rev == null ? "unknown" : rev.get("revision_seq"));
        }
        example.put("active_at", queries);
        Map<Integer, String> answers = new HashMap<>();
        answers.put(12006, "yes");
        answers.put(10551, "no_in_observed_locations");
        example.put("ownership_of_latest", LoadoutRevision.ownership(l.revisions().get(2), c4(answers)));
        Gson gson = new GsonBuilder().setPrettyPrinting().serializeNulls().create();
        String actual = gson.toJson(example) + "\n";
        Path fixture = Paths.get("src/test/resources/progress/loadout-revisions-example.json");
        if ("1".equals(System.getenv("C5_WRITE_FIXTURES")))
        {
            Files.createDirectories(fixture.getParent());
            Files.write(fixture, actual.getBytes(StandardCharsets.UTF_8));
        }
        assertEquals(new String(Files.readAllBytes(fixture), StandardCharsets.UTF_8), actual);
    }
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The W4 adversarial probes, re-aimed at the NARROW attribution rule.
 *
 * Every probe below found a real defect in the wide 54d5a0a candidate. The narrow rule answers each
 * of them the same way: `unknown`, and no fabricated pickup row. The expectations are rewritten to
 * that answer, so this class is the standing proof that the narrow rule closes the class rather than
 * a record of what the wide one did.
 *
 * F1 / F1b  a single Take plus a larger unrelated gain must never claim a customer collection.
 * F2 / F2b  a slow or interrupted walk must never publish our own recovery as somebody else's.
 * F3 / F3b  a stale Take must never claim a pile and must never fabricate a pickup row.
 * F5        a stale merged-stack record must never label a later customer collection.
 * F6        two piles on one tile must never get swapped labels.
 */
public class NarrowRuleProbeTest
{
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int TILE_X = 3210;
	private static final int TILE_Y = 3420;

	/** F1: ONE Take, customer collects the 1,200 pile, an unrelated 1,500 gain lands 2 ticks later. */
	@Test
	public void f1_singleTakeLargerUnrelatedGainReportsUnknown() throws Exception
	{
		assertEquals("F1: a 1,500-coin sale is not a 1,200-coin pile (single click)",
			"unknown", singleTakeThenGain(1500));
	}

	/** F1b: an exact double of the pile with a single click. */
	@Test
	public void f1b_singleTakeExactDoubleGainReportsUnknown() throws Exception
	{
		assertEquals("F1b: 2,400 is not one 1,200-coin pile", "unknown", singleTakeThenGain(2400));
	}

	/** F1 control: a SMALLER unrelated gain is refused too. */
	@Test
	public void f1_control_smallerUnrelatedGainReportsUnknown() throws Exception
	{
		assertEquals("control: 700 is refused", "unknown", singleTakeThenGain(700));
	}

	/** And the EXACT pile size still attributes, so the rule is not simply refusing everything. */
	@Test
	public void f1_control_theExactPileSizeStillAttributes() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1200);
		dropItemAt(plugin, COINS, 1200, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));
		tick(plugin, 151);
		plugin.onItemDespawned(despawn(COINS, 1200, TILE_X, TILE_Y, 0));
		tick(plugin, 153);
		setInventory(plugin, COINS, 1200);		// exactly the pile
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 165);
		plugin.onGameTick(null);
		assertEquals("an exact-size recovery on a lone Take is still ours",
			"self_pickup", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	private static String singleTakeThenGain(int gain) throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1200);
		dropItemAt(plugin, COINS, 1200, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));
		tick(plugin, 151);
		plugin.onItemDespawned(despawn(COINS, 1200, TILE_X, TILE_Y, 0));	// CUSTOMER collects
		tick(plugin, 153);
		setInventory(plugin, COINS, gain);					// unrelated gain
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 165);
		plugin.onGameTick(null);
		return String.valueOf(onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/**
	 * F2: a lone Take served after a 6-tick walk loses its label and reports `unknown`.
	 *
	 * The pickup pending lives 5 ticks, so a longer walk expires it. The narrow rule does not try to
	 * revive a stale Take, because every attempt at that in the wide candidate (defects 22 and 23)
	 * produced its own regression. The pile is never mislabelled, only unlabelled.
	 */
	@Test
	public void f2_sixTickWalkReportsUnknown() throws Exception
	{
		assertEquals("walk 6", "unknown", walkAndRecover(6));
	}

	/** F2 control: a 5-tick walk is inside the window and still attributes. */
	@Test
	public void f2_control_fiveTickWalkIsSelfPickup() throws Exception
	{
		assertEquals("walk 5", "self_pickup", walkAndRecover(5));
	}

	private static String walkAndRecover(int walk) throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 150 + walk);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 150 + walk + 10);
		plugin.onGameTick(null);
		return String.valueOf(onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F2b: an unrelated container change 6 ticks into the walk prunes the Take; our recovery then reads removed_early. */
	@Test
	public void f2b_containerChangeDuringWalkMustNotPublishOwnRecoveryAsRemovedEarly() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 156);
		setInventory(plugin, COINS, 5);						// unrelated change, no pot
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 158);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));	// we pick it up
		setInventory(plugin, COINS, 5, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 170);
		plugin.onGameTick(null);

		// The unrelated container change at 156 prunes the Take, so at 158 no Take is armed and the
		// pile is not deferred. It is NOT mislabelled either: `takeArmed` was set when the Take was
		// clicked and never clears, so the pile reports `unknown` and names nobody.
		assertEquals("F2b: our own recovery is never `somebody else took it`",
			"unknown", onlyEvent(plugin, "ground_removed").get("cause"));
		assertEquals("F2b: no pickup row may be fabricated from an expired Take",
			0, eventsOfType(plugin, "pickup").size());
	}

	/** F3: a stale unserved Take on the SAME tile sits ahead of the fresh one and eats its evidence. */
	@Test
	public void f3_staleSameTileTakeReportsUnknown() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));	// never served
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));	// served
		tick(plugin, 203);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 215);
		plugin.onGameTick(null);

		// Two armed Takes of one item: the client cannot say which click the server ran, so nothing
		// is claimed. The stale one at the queue head no longer STEALS the evidence either - it is
		// discarded on sight for being past its own window - but two Takes is still two Takes.
		assertEquals("F3: two armed Takes cannot prove which one landed",
			"unknown", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F3 control: without the stale Take the same recovery is self_pickup. */
	@Test
	public void f3_control_freshTakeAloneIsSelfPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 203);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 215);
		plugin.onGameTick(null);

		assertEquals("control", "self_pickup", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F3b: stale Take at the head, then a stale-Take resolution fabricates a pickup row off an unrelated gain much later. */
	@Test
	public void f3b_staleTakeFabricatesNoPickupRowFromALaterUnrelatedGain() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1000);
		dropItemAt(plugin, COINS, 1000, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));	// never served
		tick(plugin, 405);
		plugin.onItemDespawned(despawn(COINS, 1000, TILE_X, TILE_Y, 0));	// timer expiry
		tick(plugin, 420);
		plugin.onGameTick(null);
		tick(plugin, 900);
		setInventory(plugin, COINS, 250);					// unrelated store sale, 750 ticks later
		plugin.onItemContainerChanged(invChanged(plugin));

		assertEquals("F3b: no pickup happened, so no pickup row may exist",
			0, eventsOfType(plugin, "pickup").size());
		assertEquals("F3b: a Take of ours named this pile, so its timer expiry is not assertable",
			"unknown", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F5: merged-stack double record. After a clean self_pickup the stale second record survives and labels a later customer collection on the same tile. */
	@Test
	public void f5_staleMergedRecordNeverLabelsALaterCustomerCollection() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1200);
		standAt(plugin, TILE_X, TILE_Y);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		setInventory(plugin, COINS, 200);
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(TILE_X, TILE_Y, 0), tileItem(COINS, 1000, 400)));
		tick(plugin, 101);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		setInventory(plugin);
		plugin.onItemQuantityChanged(new net.runelite.api.events.ItemQuantityChanged(
			tileItem(COINS, 1200, 401), tile(TILE_X, TILE_Y, 0), 1000, 1200));
		assertEquals("one real stack is tracked twice", 2, plugin.groundDropCount());

		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));
		tick(plugin, 152);
		plugin.onItemDespawned(despawn(COINS, 1200, TILE_X, TILE_Y, 0));	// we recover it
		setInventory(plugin, COINS, 1200);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 160);
		plugin.onGameTick(null);
		// Two tracked records describe one real 1,200-coin stack, so the Take has two candidates and
		// claims neither. `unknown`, never a fabricated attribution.
		assertEquals("first removal is unattributable", "unknown",
			onlyEvent(plugin, "ground_removed").get("cause"));

		// Next delivery on the same tile 400 ticks later: drop 800, the customer collects at once.
		tick(plugin, 550);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		setInventory(plugin, COINS, 400);
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(TILE_X, TILE_Y, 0), tileItem(COINS, 800, 850)));
		tick(plugin, 560);
		plugin.onItemDespawned(despawn(COINS, 800, TILE_X, TILE_Y, 0));	// CUSTOMER collects
		tick(plugin, 570);
		plugin.onGameTick(null);

		List<Map<String, Object>> all = eventsOfType(plugin, "ground_removed");
		Map<String, Object> second = all.get(all.size() - 1);
		assertNotEquals("F5: a customer collection 10 ticks after the drop is not a timer expiry",
			"despawn_timer", second.get("cause"));
		assertEquals("F5: nor is it ours", "unknown", second.get("cause"));
	}

	/** F6: two own unstackable piles on ONE tile. Customer takes first, we take second. */
	@Test
	public void f6_sameTileCustomerFirstThenOurs_bothUnknown() throws Exception
	{
