	// ---------- helpers ----------

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]); // Item is final — construct, don't mock
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	/**
	 * The oldest armed pending. `invDeltaPending` became the bounded FIFO `invDeltaPendings` when a single
	 * slot was proven to silently lose rapid drops (RapidDropTest): four real drops emitted one event. Every
	 * assertion in this file is about ONE pending, so peeking the head keeps them all meaningful and unchanged.
	 */
	private static AccountConnectPlugin.InvDeltaPending invDeltaPending(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("invDeltaPendings");
		f.setAccessible(true);
		java.util.Deque<?> d = (java.util.Deque<?>) f.get(plugin);
		return d.isEmpty() ? null : (AccountConnectPlugin.InvDeltaPending) d.peekFirst();
	}

	/** Arm exactly one pending, replacing anything already armed — the old inject("invDeltaPending", p). */
	private static void armPending(AccountConnectPlugin plugin, AccountConnectPlugin.InvDeltaPending p)
		throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("invDeltaPendings");
		f.setAccessible(true);
		@SuppressWarnings("unchecked")
		java.util.Deque<AccountConnectPlugin.InvDeltaPending> d =
			(java.util.Deque<AccountConnectPlugin.InvDeltaPending>) f.get(plugin);
		d.clear();
		if (p != null)
		{
			d.addLast(p);
		}
	}

	private static AccountConnectPlugin.DeathPending deathPending(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("deathPending");
		f.setAccessible(true);
		return (AccountConnectPlugin.DeathPending) f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * The orphaned {@code uploadTradeScreenshots} key.
 *
 * Its config item was deleted when delivery-proof screenshots became part of core sync, but RuneLite
 * keeps a stored value whose item is gone, so the key is still in every upgraded profile. It was read
 * out of a live profile on 2026-09-15. Nothing reads it, so the risk is not behaviour: it is that a
 * profile file advertises a toggle the code does not have.
 */
public class OrphanConfigKeyTest
{
	@Test
	public void startUpUnsetsTheOrphanedKey() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		ConfigManager cm = mock(ConfigManager.class);
		inject(plugin, "configManager", cm);

		Method startUp = AccountConnectPlugin.class.getDeclaredMethod("startUp");
		startUp.setAccessible(true);
		startUp.invoke(plugin);

		verify(cm, times(1)).unsetConfiguration(
			AccountConnectPlugin.CONFIG_GROUP, AccountConnectPlugin.ORPHAN_SCREENSHOT_KEY);
	}

	/** A missing ConfigManager must not throw — startUp runs before injection in some test paths. */
	@Test
	public void aMissingConfigManagerIsASafeNoOp() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "configManager", null);
		plugin.removeOrphanedKeys();
	}

	/** And the key must genuinely be orphaned — if an item ever declares it again, this unset is a bug. */
	@Test
	public void theKeyIsNotDeclaredByAnyConfigItem()
	{
		for (Method m : AccountConnectConfig.class.getDeclaredMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			assertFalse("no live config item may own the orphaned key",
				AccountConnectPlugin.ORPHAN_SCREENSHOT_KEY.equals(item.keyName()));
		}
	}

	private static void inject(AccountConnectPlugin p, String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(p, value);
	}
}

