/**
 * WAVE 2 — real-time sync. Every tracked event flushes live (coalesced into a ~1s window so a burst is ONE
 * POST, not one per line), and a state-changing event (trade/ge/store/death) forces an immediate snapshot.
 */
public class RealtimeFlushTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private MockWebServer server;
	private AccountConnectPlugin plugin;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field field = AccountConnectPlugin.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private AccountConnectConfig cfg()
	{
		final String base = server.url("/").toString();
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

			@Override
			public String apiBaseUrl()
			{
				return base;
			}
		};
	}

	private static Map<String, Object> field(String k, Object v)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put(k, v);
		return m;
	}

	/** A burst of events schedules exactly one coalesced flush (not one per event). */
	@Test
	public void burstOfEventsSchedulesFlushOnce() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("config", cfg());
		ScheduledExecutorService exec = mock(ScheduledExecutorService.class);
		inject("executor", exec);

		plugin.emitEvent("level_up", field("skill", "line one"));
		plugin.emitEvent("level_up", field("skill", "line two"));
		plugin.emitEvent("level_up", field("skill", "line three"));

		verify(exec, times(1)).schedule(any(Runnable.class), anyLong(), eq(TimeUnit.MILLISECONDS));
		assertEquals("all three buffered for a single coalesced flush", 3, plugin.pendingEvents.size());
	}

	/** A rapid burst becomes exactly ONE /event-ingest POST carrying every event; a later event opens a new window. */
	@Test
	public void burstBecomesSinglePost() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("config", cfg());
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
		ScheduledExecutorService exec = Executors.newSingleThreadScheduledExecutor();
		inject("executor", exec);
		plugin.eventCoalesceMillis = 120L;
		server.enqueue(new MockResponse().setResponseCode(200));
		server.enqueue(new MockResponse().setResponseCode(200));

		plugin.emitEvent("level_up", field("skill", "a"));
		plugin.emitEvent("level_up", field("skill", "b"));
		plugin.emitEvent("level_up", field("skill", "c"));

		RecordedRequest r1 = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull("the burst must flush", r1);
		assertTrue("chat flushes to /event-ingest (not a forced snapshot)", r1.getPath().contains("/event-ingest"));
		Map<?, ?> body = new Gson().fromJson(r1.getBody().readUtf8(), Map.class);
		assertEquals("three events coalesced into one POST", 3, ((List<?>) body.get("events")).size());
		assertNull("no second POST for the same burst", server.takeRequest(300, TimeUnit.MILLISECONDS));

		plugin.emitEvent("level_up", field("skill", "d"));
		RecordedRequest r2 = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull("a later event opens a fresh window -> a second POST", r2);
		exec.shutdownNow();
	}

	/** A state-changing event forces an immediate snapshot AND flushes the event; chat only flushes the event. */
	@Test
	public void stateChangingEventForcesImmediateSnapshot() throws Exception
	{
		plugin = new AccountConnectPlugin();
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(player.getName()).thenReturn("TestPlayer");
		when(player.getCombatLevel()).thenReturn(100);
		ItemManager itemManager = mock(ItemManager.class);

		inject("client", client);
		inject("itemManager", itemManager);
		inject("config", cfg());
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
		inject("executor", Executors.newSingleThreadScheduledExecutor());
		plugin.eventCoalesceMillis = 60L;
		server.enqueue(new MockResponse().setResponseCode(200));
		server.enqueue(new MockResponse().setResponseCode(200));

		plugin.emitEvent("ge_buy", field("item", 4151));

		boolean sawSnapshot = false;
		boolean sawEvent = false;
		for (int i = 0; i < 2; i++)
		{
			RecordedRequest r = server.takeRequest(5, TimeUnit.SECONDS);
			assertNotNull("expected both a snapshot and an event POST", r);
			if (r.getPath().contains("/account-ingest"))
			{
				sawSnapshot = true;
			}
			if (r.getPath().contains("/event-ingest"))
			{
				sawEvent = true;
			}
		}
		assertTrue("a state-changing event must force an immediate snapshot", sawSnapshot);
		assertTrue("a state-changing event must also flush the event", sawEvent);
	}
}

package com.osrsbestinslot.export;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The release branch must not still declare the SHIPPED version.
 *
 * WHY THIS EXISTS, and it is not hypothetical. This branch sat at `version = '0.7.13'` through two
 * commits whose messages both said the version had been bumped. The bump was written, the write was
 * in a command a commit hook rejected, and the retry committed nothing — so the claim survived in
 * prose while the file never changed. A privacy review caught it, at which point the branch would
 * have shipped to the Plugin Hub declaring the version already pinned there, making a Hub build and
 * a local build indistinguishable by version.
 *
 * No build step reads this number for correctness, which is exactly why nothing else catches it.
 * The one number a human is guaranteed to quote in a release report is the one number nothing
 * verified.
 *
 * 0.7.16 is the SHIPPED version: GitHub osrsbis/account-connect release/0.7.16 = 896cc62, which
 * declares 0.7.16 (Hub fork branch osrs-best-in-slot-0.7.16). So the rule is
 * stated as a DIFFERENCE from the shipped version rather than as an equality with a literal: this file
 * only has to be edited when the shipped baseline moves.
 */
public class ReleaseVersionTest
{
	/** The version declared by 896cc62, the shipped 0.7.16 commit. */
	private static final String SHIPPED_VERSION = "0.7.16";

	private static String declaredVersion() throws IOException
	{
		// Walk up to the module root rather than assuming the working directory: gradle and an IDE
		// start tests from different places, and a test that cannot find its own build file would
		// otherwise pass vacuously.
		Path dir = Paths.get("").toAbsolutePath();
		while (dir != null && !Files.exists(dir.resolve("build.gradle")))
		{
			dir = dir.getParent();
		}
		assertTrue("build.gradle must be findable, or this test proves nothing", dir != null);

		List<String> lines = Files.readAllLines(dir.resolve("build.gradle"));
		Pattern p = Pattern.compile("^version\\s*=\\s*'([^']+)'\\s*$");
		String found = null;
		int hits = 0;
		for (String line : lines)
		{
			Matcher m = p.matcher(line);
			if (m.matches())
			{
				found = m.group(1);
				hits++;
			}
		}
		// EXACTLY ONE, because two assignments would mean the build uses the last and a reader the
		// first. An ambiguous build file is a refusal, not a best guess.
		assertEquals("build.gradle must declare exactly one version", 1, hits);
		return found;
	}

	@Test
	public void theReleaseBranchDoesNotDeclareTheShippedVersion() throws IOException
	{
		assertNotEquals(
			"this branch still declares the SHIPPED version, so a Hub build and this build would be "
				+ "indistinguishable by version — bump build.gradle",
			SHIPPED_VERSION, declaredVersion());
	}

	@Test
	public void theDeclaredVersionIsAPlausibleRelease() throws IOException
	{
		// A guard against "fixing" the test above by deleting the number or writing something that
		// is not a version at all.
		assertTrue("the version must look like x.y.z", declaredVersion().matches("\\d+\\.\\d+\\.\\d+"));
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * CONTROLLED DROP -> SELF-PICKUP. Reproduces the live 2026-09-11 grokerini test: three items dropped in
 * rapid succession, one left on the ground, two picked back up by the same account.
 */
public class SelfPickupTest
{
	private static final int CHAPS = 2495;
	private static final int DIAMOND = 1617;
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int TILE_X = 3210;
	private static final int TILE_Y = 3420;

	@Test
	public void dropThreeThenPickTwoBackUp() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1, DIAMOND, 1, COINS, 10);

		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));
		tick(plugin, 105);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		tick(plugin, 108);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));

		setInventory(plugin);	// inventory now empty of all three
		plugin.resolveDropPendingOnGroundSpawn(CHAPS, 0, 0L, 100);
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 105);
		plugin.resolveDropPendingOnGroundSpawn(COINS, 0, 0L, 108);

		assertEquals("all three drops must emit", 3, eventsOfType(plugin, "drop").size());

		// --- pick the diamond back up ---
		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));

		// --- pick the 10 coins back up ---
		tick(plugin, 150);
		plugin.onMenuOptionClicked(menu("Take", "Coins", COINS));
		setInventory(plugin, DIAMOND, 1, COINS, 10);
		plugin.onItemContainerChanged(containerChanged(plugin));

		List<Integer> picked = eventsOfType(plugin, "pickup");
		assertEquals("both self-pickups must emit exactly once: " + picked, 2, picked.size());
		assertTrue("diamond self-pickup lost", picked.contains(DIAMOND));
		assertTrue("coin self-pickup lost", picked.contains(COINS));
	}


	/** Isolates the PICKUP stage: one drop only, so the single-slot drop defect cannot confound it. */
	@Test
	public void oneDropThenPickItBackUp() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(DIAMOND, 1);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		setInventory(plugin);
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 100);
		assertEquals("the single drop must emit", 1, eventsOfType(plugin, "drop").size());

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("self-pickup after own drop must emit", 1, eventsOfType(plugin, "pickup").size());
	}

	/** Bare pickup, no preceding drop — the general mechanism the corpus already shows working. */
	@Test
	public void barePickupWithNoPrecedingDrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("bare pickup must emit", 1, eventsOfType(plugin, "pickup").size());
	}

	/**
	 * THE REAL GROUND-TAKE SHAPE, captured from a live client on 2026-09-12.
	 *
	 * Dropping a Pot and taking it back on world 308 produced exactly this MenuOptionClicked:
	 *   option=Take target=<col=ff9040>Pot id=1931 itemId=-1 param0=49 param1=54
	 *   type=GROUND_ITEM_THIRD_OPTION
	 *
	 * This test previously asserted that NO pickup is emitted here, which encoded the defect as
	 * correct behaviour and is why a green suite missed a live failure on two real staff accounts.
	 */
	@Test
	public void aRealGroundTakeEmitsItsPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTake("Pot", POT));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("a ground Take carries its item id in the entry identifier, not getItemId()",
			1, eventsOfType(plugin, "pickup").size());
		assertEquals(Integer.valueOf(POT), eventsOfType(plugin, "pickup").get(0));
	}

	/** An entry with NEITHER source populated must still be skipped, not guessed at. */
	@Test
	public void aTakeWithNoUsableIdAnywhereStillEmitsNothing() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTake("Pot", -1));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals(0, eventsOfType(plugin, "pickup").size());
	}

	/** The fallback is pickup-ONLY: an inventory entry's identifier is an option index, not an item. */
	@Test
	public void theIdentifierFallbackDoesNotApplyToOtherOpcodes() throws Exception
	{
		MenuOptionClicked drop = mock(MenuOptionClicked.class);
		when(drop.getMenuOption()).thenReturn("Drop");
		when(drop.getItemId()).thenReturn(-1);
		when(drop.getId()).thenReturn(7);          // the real Drop entry's identifier: option index
		assertEquals("a Drop must never adopt the option index as an item id",
			-1, AccountConnectPlugin.offBookItemId(drop, "drop"));
	}

	/**
	 * The identifier is only an item id on a GROUND_ITEM_* opcode.
	 *
	 * Matching the option word "Take" alone would adopt the identifier of any other entry that
	 * happens to be labelled Take — a widget button, a future interface — where the identifier is
	 * an option index or a widget id, not an item. The opcode is what makes the field meaningful.
	 */
	@Test
	public void aTakeOnANonGroundOpcodeNeverAdoptsItsIdentifier()
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(9764864);	// a widget id, not an item
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.CC_OP_LOW_PRIORITY);
		assertEquals("only a ground-item opcode puts an item id in the identifier",
			-1, AccountConnectPlugin.offBookItemId(m, "pickup"));
	}

	/** Every ground-item option index is a valid source, not just the third. */
	@Test
	public void everyGroundItemOpcodeCarriesItsItemIdInTheIdentifier()
	{
		for (net.runelite.api.MenuAction a : new net.runelite.api.MenuAction[]{
			net.runelite.api.MenuAction.GROUND_ITEM_FIRST_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_SECOND_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_FOURTH_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_FIFTH_OPTION})
		{
			MenuOptionClicked m = mock(MenuOptionClicked.class);
			when(m.getItemId()).thenReturn(-1);
			when(m.getId()).thenReturn(POT);
			when(m.getMenuAction()).thenReturn(a);
			assertEquals(a.toString(), POT, AccountConnectPlugin.offBookItemId(m, "pickup"));
		}
	}

	/** An inventory action with a good getItemId() keeps using it, identifier ignored. */
	@Test
	public void aNormalInventoryActionStillUsesGetItemId()
	{
		MenuOptionClicked drop = mock(MenuOptionClicked.class);
		when(drop.getItemId()).thenReturn(1931);
		when(drop.getId()).thenReturn(7);
		assertEquals(1931, AccountConnectPlugin.offBookItemId(drop, "drop"));
	}


	/** EXACT live shape: three drops each confirmed by its own ground spawn, then a Take. */
	@Test
	public void liveShapeThreeConfirmedDropsThenTake() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1, DIAMOND, 1, COINS, 10);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));
		plugin.resolveDropPendingOnGroundSpawn(CHAPS, 0, 0L, 100);
		tick(plugin, 105);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 105);
		tick(plugin, 108);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		plugin.resolveDropPendingOnGroundSpawn(COINS, 0, 0L, 108);
		setInventory(plugin);
		assertEquals("live shape: all three drops emitted", 3, eventsOfType(plugin, "drop").size());

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("the self-pickup after the live drop shape must emit",
			1, eventsOfType(plugin, "pickup").size());
	}

	/** A Drop click that never gets a ground spawn leaves a pending. Does it swallow a later Take? */
	@Test
	public void staleUnconfirmedDropDoesNotSwallowALaterPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));	// no ground spawn ever arrives

		tick(plugin, 102);					// 2 ticks later, well inside DROP_PENDING_MAX_TICKS
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, CHAPS, 1, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("a stale drop pending must not swallow a real pickup",
			1, eventsOfType(plugin, "pickup").size());
	}

	// ---------------------------------------------------------------- harness

	private static AccountConnectPlugin newPlugin(int... idQtyPairs) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv0 = container(idQtyPairs);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv0);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(0);
		when(client.getTickCount()).thenReturn(100);
		// WorldPoint.fromScene() reads the world view's base coordinates. Base 0 makes the scene
		// coordinates in a Take menu entry equal to world coordinates, which keeps the tile
		// assertions readable. Without this the conversion returns null and every tile check
		// silently degrades to item-id-only matching — i.e. passes for the wrong reason.
		net.runelite.api.WorldView wv = mock(net.runelite.api.WorldView.class);
		when(wv.getBaseX()).thenReturn(0);
		when(wv.getBaseY()).thenReturn(0);
		when(client.getTopLevelWorldView()).thenReturn(wv);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(TILE_X, TILE_Y, 0));
		inject(plugin, "client", client);
		return plugin;
	}

	private static void setInventory(AccountConnectPlugin plugin, int... idQtyPairs) throws Exception
	{
		ItemContainer next = container(idQtyPairs);
		when(client(plugin).getItemContainer(InventoryID.INVENTORY)).thenReturn(next);
	}

	/** The real client hands the changed INVENTORY container to onItemContainerChanged. */
	private static net.runelite.api.events.ItemContainerChanged containerChanged(AccountConnectPlugin plugin)
		throws Exception
	{
		ItemContainer inv = client(plugin).getItemContainer(InventoryID.INVENTORY);
		return new net.runelite.api.events.ItemContainerChanged(InventoryID.INVENTORY.getId(), inv);
	}

	private static Client client(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		return (Client) f.get(plugin);
	}

	private static void tick(AccountConnectPlugin plugin, int t) throws Exception
	{
		when(client(plugin).getTickCount()).thenReturn(t);
	}

	private static List<Integer> eventsOfType(AccountConnectPlugin plugin, String type)
	{
		List<Integer> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				out.add((Integer) e.get("item"));
			}
		}
		return out;
	}

	/** The REAL ground-item Take entry: itemId is -1, the item id sits in the identifier. */
	private static MenuOptionClicked groundTake(String name, int itemId)
	{
		return groundTakeAt(name, itemId, TILE_X, TILE_Y);
	}

	/**
	 * The REAL ground-item Take entry, aimed at one specific tile.
	 *
	 * itemId is -1, the item id sits in the identifier, the opcode is GROUND_ITEM_THIRD_OPTION and
	 * param0/param1 carry the pile's SCENE coordinates. The test client mock reports base 0, so the
	 * scene coordinates ARE the world coordinates here.
	 */
	private static MenuOptionClicked groundTakeAt(String name, int itemId, int x, int y)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(itemId);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION);
		when(m.getParam0()).thenReturn(x);
		when(m.getParam1()).thenReturn(y);
		return m;
	}

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class) { return Boolean.TRUE; }
				if (rt == String.class) { return "0123456789abcdef0123456789abcdef"; }
				if (rt == int.class || rt == Integer.class) { return 0; }
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The shop-stock diagnostic. It is about to be quoted as evidence for what a reset actually is, so
 * it gets one known-bad run first: a trace that silently writes nothing, or writes the wrong delta,
 * would send the next fix in the wrong direction.
 */
public class ShopTraceTest
{
	/**
	 * A NORMAL BUILD WRITES NOTHING.
	 *
	 * The arm is written as an A/B on ONE file rather than as "some temp path stays absent", which
	 * proves nothing: the plugin was never pointed at that path, so the assertion held whatever the
	 * code did. Here the property is set, a change is traced, the file's size is recorded, then the
	 * property is cleared and the same changes are replayed. The file must not grow by one byte.
	 *
	 * KNOWN LIMIT, stated because it is real: this kills a stale-or-removed guard, which is the
	 * regression that can actually happen. It cannot kill a trace rewritten to a hard-coded constant
	 * path, because a black-box test cannot enumerate every path the process might write.
	 */
	@Test
	public void writesNothingUnlessExplicitlyEnabled() throws Exception
	{
		Path out = Files.createTempFile("shoptrace-ab", ".log");
		Files.delete(out);
		try
		{
			System.setProperty("osrsbis.shoptrace", out.toString());
			AccountConnectPlugin on = configured();
			on.handleShopStockChanged(container(new int[][]{{561, 1}}));
			on.handleShopStockChanged(container(new int[][]{{561, 0}}));
			assertTrue("the control arm must prove the trace CAN write", Files.exists(out));
			long enabledSize = Files.size(out);
			assertTrue("the enabled trace must have content", enabledSize > 0);

			System.clearProperty("osrsbis.shoptrace");
			AccountConnectPlugin off = configured();
			off.handleShopStockChanged(container(new int[][]{{561, 1}}));
			off.handleShopStockChanged(container(new int[][]{{561, 0}}));

			assertEquals("a normal build must write no trace at all",
				enabledSize, Files.size(out));
		}
		finally
		{
			System.clearProperty("osrsbis.shoptrace");
			Files.deleteIfExists(out);
		}
	}

	@Test
	public void recordsTheItemsThatActuallyChanged() throws Exception
	{
		Path out = Files.createTempFile("shoptrace", ".log");
		Files.delete(out);
		System.setProperty("osrsbis.shoptrace", out.toString());
		try
		{
			AccountConnectPlugin p = configured();
			p.handleShopStockChanged(container(new int[][]{{561, 1}, {995, 10}}));	// baseline
			p.handleShopStockChanged(container(new int[][]{{561, 0}, {995, 11}}));	// a reset shape

			String text = new String(Files.readAllBytes(out), "UTF-8");
			String[] lines = text.split("\n");
			// The fixture is deliberately a real tick shape (one fall + one rise), so the plugin
			// also writes its ANCHOR line. Assert on CONTENT rather than a line count, which would
			// break every time a new diagnostic line is added.
			String delta = null;
			for (String l : lines)
			{
				if (l.contains("delta=") && l.contains("561:1->0"))
				{
					delta = l;
				}
			}
			assertTrue("the fall must be recorded", delta != null);
			assertTrue("the restock must be recorded too", delta.contains("995:10->11"));
			// KNOWN-BAD CONTROL: an unchanged container must NOT look like a change.
			p.handleShopStockChanged(container(new int[][]{{561, 0}, {995, 11}}));
			String all = new String(Files.readAllBytes(out), "UTF-8");
			assertTrue("an unchanged read must say so", all.contains("(none)"));
		}
		finally
		{
			System.clearProperty("osrsbis.shoptrace");
			Files.deleteIfExists(out);
		}
	}

	private static AccountConnectPlugin configured() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	private static net.runelite.api.ItemContainer container(int[][] items)
	{
		net.runelite.api.ItemContainer c = org.mockito.Mockito.mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] arr = new net.runelite.api.Item[items.length];
		for (int i = 0; i < items.length; i++)
		{
			arr[i] = new net.runelite.api.Item(items[i][0], items[i][1]);
		}
		org.mockito.Mockito.when(c.getItems()).thenReturn(arr);
		return c;
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.game.ItemManager;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Agreed with the server and the readers on 2026-10-24, after the live 0.7.55 logs:
 * - snapshot.captured_at_ms orders a snapshot against an event in the same second; captured_at is its second.
 * - bank.open_at_capture marks bank items read from the live container of an open bank, so a reader can tell
 *   them from a read retained after the close.
 * - login/logout carry wealth only when this login has read the bank: without it the same field held
 *   inventory + gear only, a second meaning (11.38M with the bank, 5.05M without on one account).
 * Neither new snapshot field may make an unchanged account look changed.
 */
public class SnapshotFreshnessTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int BANK_GROUP = 12;
	private static final int COINS = 995;
	private static final int BONES = 530;

	private MockWebServer server;
	private AccountConnectPlugin plugin;
	private Client client;
	private ItemContainer bank;
	private int tick = 1000;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
		plugin = new AccountConnectPlugin();
		client = mock(Client.class);
		Player player = mock(Player.class);
		when(player.getName()).thenReturn("Fixture Main");
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getAccountHash()).thenReturn(42L);
		when(client.getTickCount()).thenAnswer(i -> tick);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(client.getRealSkillLevel(Skill.HITPOINTS)).thenReturn(10);
		when(client.getSkillExperience(any(Skill.class))).thenReturn(0);
		when(client.getVarps()).thenReturn(new int[5000]);
		when(client.getItemContainer(InventoryID.BANK)).thenAnswer(i -> bank);
		String baseUrl = server.url("/").toString();
		inject("config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl;
			}
		});
		inject("client", client);
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
		inject("itemManager", mock(ItemManager.class));
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	private void inject(String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static ItemContainer container(Item... items)
	{
		ItemContainer c = mock(ItemContainer.class);
		when(c.getItems()).thenReturn(items);
		when(c.getId()).thenReturn(net.runelite.api.gameval.InventoryID.BANK);
		return c;
	}

	private void change(ItemContainer b)
	{
		bank = b;
		plugin.onItemContainerChanged(new ItemContainerChanged(net.runelite.api.gameval.InventoryID.BANK, b));
	}

	/** The bank interface loads: the snapshot sent for the open is returned. */
	@SuppressWarnings("unchecked")
	private Map<String, Object> open(ItemContainer b) throws Exception
	{
		bank = b;
		server.enqueue(new MockResponse().setResponseCode(200));
		plugin.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);
		RecordedRequest req = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull("the open sends a snapshot", req);
		return (Map<String, Object>) new Gson().fromJson(req.getBody().readUtf8(), Map.class).get("snapshot");
	}

	private void close()
	{
		plugin.handleBankWidgetClosed(BANK_GROUP);
		bank = null;
	}

	@SuppressWarnings("unchecked")
	private Map<String, Object> snapshot() throws Exception
	{
		Method build = AccountConnectPlugin.class.getDeclaredMethod("buildSnapshot");
		build.setAccessible(true);
		return (Map<String, Object>) build.invoke(plugin);
	}

	private static Object openAtCapture(Map<String, Object> snap)
	{
		return ((Map<?, ?>) snap.get("bank")).get("open_at_capture");
	}

	@Test
	public void capturedAtMsIsTheSameClockReadAsCapturedAt() throws Exception
	{
		Map<String, Object> snap = snapshot();
		Object ms = snap.get("captured_at_ms");
		assertTrue("an integer of milliseconds", ms instanceof Long);
		assertEquals(snap.get("captured_at"), (Long) ms / 1000L);

		String json = new Gson().toJson(snap);
		assertTrue("an integer on the wire, never 1.7E12", json.contains("\"captured_at_ms\":" + ms + ","));
	}

	@Test
	public void theNewFieldsNeverMakeAnUnchangedAccountLookChanged() throws Exception
	{
		Map<String, Object> a = snapshot();
		Map<String, Object> b = new LinkedHashMap<>(a);
		b.put("captured_at_ms", (Long) a.get("captured_at_ms") + 1234L);
		Map<String, Object> bankBlock = new LinkedHashMap<>((Map<String, Object>) a.get("bank"));
		bankBlock.put("open_at_capture", true);
		b.put("bank", bankBlock);
		assertEquals(plugin.canonicalHash(a), plugin.canonicalHash(b));

		Map<String, Object> moved = new LinkedHashMap<>(bankBlock);
		moved.put("value_gp", 1L);
		b.put("bank", moved);
		assertFalse("a real bank change still counts", plugin.canonicalHash(a).equals(plugin.canonicalHash(b)));
	}

	@Test
	public void anOpenBankIsMarkedAndARetainedReadIsNot() throws Exception
	{
		assertNull("no bank this login", openAtCapture(snapshot()));

		ItemContainer b = container(new Item(COINS, 100), new Item(BONES, 1));
		change(b);										// this open's contents arrive in the open's own tick
		assertEquals("the snapshot sent for the open", true, openAtCapture(open(b)));
		tick++;
		assertEquals("still open", true, openAtCapture(snapshot()));
		change(container(new Item(COINS, 100)));
		assertEquals("a change while open", true, openAtCapture(snapshot()));

		close();
		Map<String, Object> after = snapshot();
		assertEquals("the read is kept after the close", true, ((Map<?, ?>) after.get("capture_flags")).get("bank_synced"));
		assertNull("but it is not an open bank", openAtCapture(after));
	}

	/**
	 * Live 0.7.57 QA (2026-10-24): the snapshot sent at the open read a populated container before the open's
	 * ItemContainerChanged. Nothing proves that read is this visit's contents and not the last visit's copy.
	 */
	@Test
	public void anOpenWhoseContentsNoChangeConfirmedIsNotMarked() throws Exception
	{
		change(container(new Item(COINS, 100), new Item(BONES, 1)));	// the last visit
		close();
		tick += 50;
		ItemContainer stale = container(new Item(COINS, 100), new Item(BONES, 1));
		assertNull("the open read only a container no change has confirmed", openAtCapture(open(stale)));
		tick++;
		assertNull("still unconfirmed a tick later", openAtCapture(snapshot()));
		change(container(new Item(COINS, 100)));			// this visit's contents arrive
		assertEquals(true, openAtCapture(snapshot()));
	}

	@Test
	public void aChangeOfTheLastVisitNeverConfirmsAReopenInTheSameTick() throws Exception
	{
		change(container(new Item(COINS, 100), new Item(BONES, 1)));	// the last visit's change in tick T
		close();
		ItemContainer stale = container(new Item(COINS, 100), new Item(BONES, 1));
		assertNull("reopened in the same tick T, no change of this open yet", openAtCapture(open(stale)));
		tick++;
		assertNull(openAtCapture(snapshot()));
	}

	private static Object observedAt(Map<String, Object> snap)
	{
		return ((Map<?, ?>) snap.get("bank")).get("observed_at");
	}

	/**
	 * Live 0.7.58 QA (2026-10-24, G4): an item was deposited at a deposit box while the bank was closed. The
	 * upload sent at the reopen held it with the observed_at of the read before the deposit.
	 */
	@Test
	public void anUnconfirmedOpenReadHasNoTimeAndAConfirmedOrRetainedReadKeepsIts() throws Exception
	{
		change(container(new Item(COINS, 100)));				// the last visit's read
		Object lastRead = observedAt(snapshot());
		assertNotNull(lastRead);
		close();
		assertEquals("a retained read after the close keeps its time", lastRead, observedAt(snapshot()));

		tick += 50;
		ItemContainer deposited = container(new Item(COINS, 100), new Item(BONES, 1));	// changed while closed
		assertNull("the open read: no change of this open yet", observedAt(open(deposited)));
		tick++;
		assertNull("still unconfirmed a tick later", observedAt(snapshot()));

		change(deposited);										// this open's change
		Map<String, Object> confirmed = snapshot();
		assertNotNull(observedAt(confirmed));
		assertEquals(true, openAtCapture(confirmed));

		close();
		assertEquals("after the close the confirmed read keeps its time", observedAt(confirmed), observedAt(snapshot()));
	}

	@Test
	public void anOpenWhoseChangeArrivesInItsOwnTickKeepsItsTime() throws Exception
	{
		ItemContainer b = container(new Item(COINS, 100));
		change(b);
		assertNotNull(observedAt(open(b)));
	}

	@Test
	public void anUnreadableCloseIsNotAnOpenBank() throws Exception
	{
		open(container(new Item(COINS, 100)));
		bank = container();								// the close reads an empty container: the close waits
		plugin.handleBankWidgetClosed(BANK_GROUP);
		bank = container(new Item(COINS, 100));			// a read arriving after the close
		assertNull(openAtCapture(snapshot()));
	}

	@Test
	public void anOpenThatHasNotLoadedIsNotMarkedUntilItLoads() throws Exception
	{
		assertNull("an empty open is no read", openAtCapture(open(container())));
		change(container(new Item(COINS, 100)));			// the first populated read
		assertEquals(true, openAtCapture(snapshot()));
	}

	@Test
	public void loginAndLogoutCarryWealthOnlyOnceTheBankIsRead() throws Exception
	{
		plugin.syncTask();
		server.takeRequest(5, TimeUnit.SECONDS);
		Map<String, Object> login = plugin.pendingEvents.get(0);
		assertEquals("login", login.get("type"));
		assertFalse("no bank read yet: no wealth at all", login.containsKey("wealth"));
		assertNull(plugin.lastKnownNetWorth());

		open(container(new Item(COINS, 100)));
		close();
		plugin.pendingEvents.clear();
		plugin.trackLogout("manual");
		Map<String, Object> logout = plugin.pendingEvents.get(0);
		assertEquals("logout", logout.get("type"));
		assertNotNull("the bank was read this login", logout.get("wealth"));
	}
}

package com.osrsbestinslot.export;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StorageRecoveryCaptureTest
{
    private Client client;
    private StorageRecoveryCapture capture;
    private int tick;

    @Before public void setup()
    {
        client = mock(Client.class);
        capture = new StorageRecoveryCapture();
        when(client.getAccountHash()).thenReturn(42L);
        when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
        when(client.getTickCount()).thenAnswer(i -> tick);
        when(client.getWidget(StorageRecoveryCapture.DEPOSIT_ITEMS)).thenReturn(mock(Widget.class));
    }

    private ItemContainer items(int... pairs)
    {
        ItemContainer c = mock(ItemContainer.class);
        Item[] items = new Item[pairs.length / 2];
        for (int i = 0; i < pairs.length; i += 2) items[i / 2] = new Item(pairs[i], pairs[i + 1]);
        when(c.getItems()).thenReturn(items);
        return c;
    }

    private void bank(int... pairs)
    {
        when(client.getWidget(StorageRecoveryCapture.BANK_WIDGET)).thenReturn(mock(Widget.class));
        capture.container(client, 95, items(pairs), 10 + tick);
    }

    private MenuOptionClicked click(int op, int item)
    {
        MenuOptionClicked event = mock(MenuOptionClicked.class);
        when(event.getMenuAction()).thenReturn(MenuAction.CC_OP);
        when(event.getParam1()).thenReturn(StorageRecoveryCapture.DEPOSIT_ITEMS);
        when(event.getId()).thenReturn(op);
        when(event.getItemId()).thenReturn(item);
        return event;
    }

    private List<Map<String, Object>> rows()
    {
        return (List<Map<String, Object>>) capture.snapshot(client).get("observations");
    }

    private Map<?, ?> block(String key) { return (Map<?, ?>) capture.snapshot(client).get(key); }

    @Test public void bankBaselineAndSignedDifferenceRetainGapAndIdentity()
    {
        bank(100, 10, 101, 5);
        assertEquals("baseline_only", rows().get(0).get("delta_status"));
        assertEquals("42", rows().get(0).get("account_hash"));
        assertEquals("STANDARD", rows().get(0).get("profile_type"));
        tick++;
        bank(100, 7, 102, 2);
        assertEquals(Map.of(100, -3L, 101, -5L, 102, 2L), rows().get(1).get("delta"));
        assertEquals(false, rows().get(1).get("across_gap"));
        capture.gap();
        bank(100, 8);
        assertEquals(true, rows().get(2).get("across_gap"));
        assertEquals("unknown", rows().get(2).get("transfer_attribution"));
    }

    @Test public void closedAndEmptyReadsNeverOverwriteBaseline()
    {
        bank(100, 10);
        when(client.getWidget(StorageRecoveryCapture.BANK_WIDGET)).thenReturn(null);
        capture.container(client, 95, items(100, 999), 20);
        assertEquals(Map.of(100, 10L), block("bank").get("items"));
        assertEquals(true, block("bank").get("uncertain"));
        bank();
        assertEquals(Map.of(100, 10L), block("bank").get("items"));
        assertEquals(1, rows().size());
    }

    @Test public void fixedDepositNeedsCallbackAndNeverMutatesBank()
    {
        bank(100, 10);
        when(client.getWidget(StorageRecoveryCapture.BANK_WIDGET)).thenReturn(null);
        doReturn(items(100, 8)).when(client).getItemContainer(93);
        capture.menu(client, click(3, 100), 20);
        assertEquals(1, rows().size());
        capture.container(client, 93, items(100, 3), 21);
        tick = 2;
        capture.poll(client, 22);
        assertEquals("inferred", rows().get(1).get("delta_status"));
        assertEquals(Map.of(100, -5L), rows().get(1).get("inventory_delta"));
        assertEquals("unknown", rows().get(1).get("bank_delta_status"));
        assertEquals(Map.of(100, 10L), block("bank").get("items"));
        capture.poll(client, 23);
        assertEquals(2, rows().size());
    }

    @Test public void missedCallbackAndClickOnlyStayUncertain()
    {
        doReturn(items(100, 8)).when(client).getItemContainer(93);
        capture.menu(client, click(3, 100), 20);
        tick = 2;
        capture.poll(client, 22);
        assertEquals("uncertain", rows().get(0).get("delta_status"));
        assertNull(rows().get(0).get("inventory_delta"));
        assertNull(block("bank").get("items"));
    }

    @Test public void multipleChangesOrDelayedCallbacksDoNotInfer()
    {
        doReturn(items(100, 8, 200, 1)).when(client).getItemContainer(93);
        capture.menu(client, click(3, 100), 20);
        capture.container(client, 93, items(100, 3), 21);
        tick = 2;
        capture.poll(client, 22);
        assertEquals("uncertain", rows().get(0).get("delta_status"));
        capture.menu(client, click(3, 100), 25);
        capture.container(client, 93, items(100, 3, 200, 1), 26);
        tick = 6;
        capture.poll(client, 27);
        assertEquals("uncertain", rows().get(1).get("delta_status"));
    }

    @Test public void competingClicksCancelAndUnsupportedActionsDoNotArm()
    {
        doReturn(items(100, 8)).when(client).getItemContainer(93);
        capture.menu(client, click(3, 100), 20);
        capture.menu(client, click(3, 100), 21);
        assertEquals("competing_menu_action", rows().get(0).get("reason"));
        for (int op : new int[]{1, 5, 7, 9}) capture.menu(client, click(op, 100), 22);
        MenuOptionClicked consumed = click(3, 100);
        when(consumed.isConsumed()).thenReturn(true);
        capture.menu(client, consumed, 22);
        tick = 3;
        capture.poll(client, 23);
        assertEquals(1, rows().size());
    }

    @Test public void notesRemainRawWithoutInventedBankNormalization()
    {
        doReturn(items(101, 8)).when(client).getItemContainer(93);
        capture.menu(client, click(6, 101), 20);
        capture.container(client, 93, items(), 21);
        tick = 2;
        capture.poll(client, 22);
        assertEquals("inferred", rows().get(0).get("delta_status"));
        assertEquals(101, rows().get(0).get("raw_item_id"));
        assertEquals("unknown", rows().get(0).get("bank_delta_status"));
    }

    @Test public void boundedRingAndResetAreExplicit()
    {
        for (int i = 1; i <= 70; i++) bank(100, i);
        assertEquals(64, rows().size());
        assertEquals(6L, capture.snapshot(client).get("observations_evicted"));
        Object session = capture.snapshot(client).get("collector_session");
        capture.reset();
        assertTrue(rows().isEmpty());
        assertNull(block("bank").get("last_seen_ms"));
        assertNotEquals(session, capture.snapshot(client).get("collector_session"));
    }

    @Test public void missingPlankDefinitionsStayUnknownAndKnownZeroSurvives()
    {
        VarbitComposition def = mock(VarbitComposition.class);
        when(def.getIndex()).thenReturn(1);
        when(def.getLeastSignificantBit()).thenReturn(1);
        when(def.getMostSignificantBit()).thenReturn(8);
        when(client.getVarbit(18171)).thenReturn(def);
        when(client.getVarps()).thenReturn(new int[5]);
        capture.poll(client, 20);
        Map<?, ?> quantities = (Map<?, ?>) block("plank_sack").get("quantities");
        assertEquals(0, quantities.get("plain"));
        assertNull(quantities.get("oak"));
        assertEquals("unknown", block("plank_sack").get("ownership"));
        assertEquals("partial", block("plank_sack").get("full_or_partial"));
    }

    @Test public void identityAndLoadingInvalidatePendingEvidence()
    {
        AccountProgressCapture progress = new AccountProgressCapture();
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getLocalPlayer()).thenReturn(mock(Player.class));
        when(client.getRealSkillLevel(Skill.HITPOINTS)).thenReturn(10);
        assertFalse(progress.ready(client, "token"));
        tick = 2;
        assertTrue(progress.ready(client, "token"));
        when(client.getWidget(StorageRecoveryCapture.BANK_WIDGET)).thenReturn(mock(Widget.class));
        progress.storageRecovery.container(client, 95, items(100, 8), 10);
        when(client.getGameState()).thenReturn(GameState.LOADING);
        assertFalse(progress.ready(client, "token"));
        assertEquals(true, ((Map<?, ?>) progress.storageRecovery.snapshot(client).get("bank")).get("uncertain"));
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getAccountHash()).thenReturn(43L);
        assertFalse(progress.ready(client, "token"));
        assertNull(((Map<?, ?>) progress.storageRecovery.snapshot(client).get("bank")).get("items"));
        tick = 4;
        assertTrue(progress.ready(client, "token"));
        progress.storageRecovery.container(client, 95, items(100, 8), 20);
        assertFalse(progress.ready(client, "new-token"));
        assertTrue(((List<?>) progress.storageRecovery.snapshot(client).get("observations")).isEmpty());
    }

    @Test public void countsUseLongAndRejectMalformedOrOversizedArrays()
    {
        assertEquals(Long.valueOf(4294967294L), StorageRecoveryCapture.counts(items(100, Integer.MAX_VALUE, 100, Integer.MAX_VALUE)).get(100));
        assertNull(StorageRecoveryCapture.counts(items(100, -1)));
        ItemContainer oversized = mock(ItemContainer.class);
        when(oversized.getItems()).thenReturn(new Item[1501]);
        assertNull(StorageRecoveryCapture.counts(oversized));
    }
}

package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the store delivery-proof burst capture path (Task B2) — no live client needed.
 * Covers: the opt-in default (off), the server force-disable gate, wall-clock 1-in-time decimation,
 * and the RGB (no-alpha) frame conversion the JDK JPEG writer requires. The listener wiring, real
 * shop-widget event delivery, and the multipart upload (B3) need a live client / are covered elsewhere.
 */
public class StoreClipCaptureTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	/** Config with a linked token — the ONLY local condition for capture since the toggle was removed. */
	private static AccountConnectConfig linked()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	// (a) no link token -> no capture. The separate opt-in toggle was removed 2026-09-02; capture is now
	// part of core sync, so the token IS the gate. An unlinked client must still capture nothing.
	@Test
	public void storeClipsDisabledWithoutLinkToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
});
		assertFalse("store-clip capture must be off with no link token",
			plugin.storeClipsEnabled());
	}

	// (a2) a malformed token is not a link — same refusal as none at all.
	@Test
	public void storeClipsDisabledOnMalformedToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "not-a-token";
			}
		});
		assertFalse("a malformed token must not enable capture", plugin.storeClipsEnabled());
	}

	// (b) server force-disable wins even when the client IS linked.
	@Test
	public void serverForceDisableOverridesLinkedToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", linked());
		// linked, server not disabling -> enabled.
		assertFalse("the public artifact never enables media capture",
			plugin.storeClipsEnabled());
		// server flips it off -> gate closes despite the link.
		plugin.serverClipsDisabled = true;
		assertFalse("server X-Clips=off must force capture off",
			plugin.storeClipsEnabled());
	}

	// (c) wall-clock decimation: 50 render frames across one simulated second -> exactly CLIP_FPS samples.
	//
	// The expectation is DERIVED from CLIP_FPS, not hardcoded. It used to assert a literal 1, so raising
	// the sample rate to 2 on 2026-09-02 turned this red for the rate change rather than for a defect —
	// a test that fails when the thing it measures is deliberately changed is testing the constant, not
	// the decimation. What must hold at ANY rate is: exactly CLIP_FPS samples per second, and the same
	// again in the following second (a rate, never a one-shot).
	@Test
	public void wallClockDecimationYieldsOneSamplePerSecond()
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		// nextClipSampleAt defaults to 0; walk 50 evenly-spaced nanoTime ticks over exactly one second
		// (~50fps render). Only every (1/CLIP_FPS)s boundary should cross the gate.
		long oneSecond = 1_000_000_000L;
		int trues = 0;
		for (int i = 0; i < 50; i++)
		{
			long now = i * (oneSecond / 50);	// 0ms, 20ms, ... 980ms
			if (plugin.shouldSampleClipFrame(now))
			{
				trues++;
			}
		}
		// Exact equality is the WRONG assertion above 1fps and asserting it hid a real property. The gate
		// advances by exactly 1/CLIP_FPS seconds, but render ticks land on a 20ms grid, so each sample
		// fires at the first tick AT OR AFTER its boundary and the remainder carries into the next
		// second: at 8fps a 50-tick second yields 8 then 7, alternating, averaging 8. That is correct
		// decimation, not drift — the gate never loses time, it only rounds each sample forward. So the
		// per-second count is asserted within +/-1 and the TWO-second total is asserted exactly, which
		// is what actually proves the rate.
		assertTrue("expected ~CLIP_FPS samples across one simulated second, got " + trues,
			Math.abs(trues - AccountConnectPlugin.CLIP_FPS) <= 1);
		// MOUSE VISIBILITY is the floor, not "enough to catch the transaction". A cursor crossing a shop
		// interface reads as movement only when consecutive frames are ~125ms apart; 3fps (333ms) was
		// rejected on review as too laggy to see the mouse at all. Asserted independently of whatever
		// CLIP_FPS currently is, so lowering the rate for a byte saving turns this RED.
		assertTrue("a delivery clip must sample at the client's own render rate (30fps) to read as motion",
			AccountConnectPlugin.CLIP_FPS >= 30);
		// The burst must fit the SERVER's frame-count cap. This is 240 only because the ingest cap was
		// raised to 360 in the same change (osrsbis-web-integrator backend.js FRAMES_COUNT_MAX); with the
		// old 120 the server 400s the whole burst — it does not trim it — so this number and the server's
		// must move together, and this assertion is what catches them drifting apart.
		// The visit's frames no longer have to fit ONE request: the upload is chunked. What must hold is
		// that a CHUNK fits the smallest server frame cap ever deployed (120), with margin. This is the
		// assertion that lets clip length grow without a server deploy — and that turns red if someone
		// raises the chunk size back up to the current cap and re-couples the two.
		assertTrue("a chunk must fit the smallest deployed server frame cap (120) with margin",
			AccountConnectPlugin.CLIP_CHUNK_FRAMES <= 100);
		assertTrue("chunking must actually chunk a full visit",
			AccountConnectPlugin.MAX_CLIP_FRAMES > AccountConnectPlugin.CLIP_CHUNK_FRAMES);
		// And it must fit the BYTE cap at the measured mean frame size (56KB over 68 real frames), or the
		// newest-suffix trim silently discards the opening of the visit.
		// 30KB is the MEASURED mean at the current MAX_FRAME_WIDTH/quality (704px, q0.55). If either is
		// raised, this arm goes red — which is the point: the frame size and the frame count are one
		// budget, and changing one without the other silently truncates the start of every visit.
		// This is the VISIT budget (memory + total upload), not a per-request limit.
		assertTrue("fps x seconds at ~30KB/frame (704px q0.55) must fit the 16 MiB visit budget",
			(long) AccountConnectPlugin.MAX_CLIP_FRAMES * 30 * 1024
				<= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("frame width must stay at the legibility floor that the byte budget assumes",
			704, AccountConnectPlugin.MAX_FRAME_WIDTH);

		// A second simulated second must yield the next sample — proves it is a rate, not a one-shot.
		int trues2 = 0;
		for (int i = 50; i < 100; i++)
		{
			long now = i * (oneSecond / 50);	// 1000ms .. 1980ms
			if (plugin.shouldSampleClipFrame(now))
			{
				trues2++;
			}
		}
		assertTrue("expected ~CLIP_FPS more samples across the next simulated second, got " + trues2,
			Math.abs(trues2 - AccountConnectPlugin.CLIP_FPS) <= 1);
		// The two-second total is exact: rounding each sample forward must not COST a sample.
		assertEquals("two simulated seconds must yield exactly 2x CLIP_FPS samples",
			2 * AccountConnectPlugin.CLIP_FPS, trues + trues2);

		// Over a LONG span the rate must not drift. This is the arm that caught the real defect: the
		// gate used to advance from the observed tick, so each sample's rounding error compounded and
		// 8fps delivered ~7.5. Ten simulated seconds at a 50fps render must yield 10x CLIP_FPS.
		AccountConnectPlugin p2 = new AccountConnectPlugin();
		int over10s = 0;
		for (int i = 0; i < 500; i++)
		{
			if (p2.shouldSampleClipFrame(i * (oneSecond / 50)))
			{
				over10s++;
			}
		}
		assertEquals("ten simulated seconds must yield exactly 10x CLIP_FPS samples — no cumulative drift",
			10 * AccountConnectPlugin.CLIP_FPS, over10s);

		// A long stall must NOT produce a catch-up burst on consecutive frames: duplicating one instant
		// is not evidence. After a 5-second gap the next tick samples once, and the tick right after it
		// (20ms later, well inside the 125ms period) must not.
		AccountConnectPlugin p3 = new AccountConnectPlugin();
		assertTrue("first call always samples", p3.shouldSampleClipFrame(0L));
		assertTrue("the tick after a long stall samples once", p3.shouldSampleClipFrame(5 * oneSecond));
		assertFalse("...and does not fire again 20ms later",
			p3.shouldSampleClipFrame(5 * oneSecond + oneSecond / 50));
	}

	// (d) RGB conversion: an ARGB frame becomes TYPE_INT_RGB (the JDK JPEG writer corrupts ARGB rasters).
	@Test
	public void toRgbFrameProducesNonAlphaRgb()
	{
		BufferedImage argb = new BufferedImage(32, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = argb.createGraphics();
		g.setColor(Color.ORANGE);
		g.fillRect(0, 0, 32, 24);
		g.dispose();

		BufferedImage rgb = AccountConnectPlugin.toRgbFrame(argb);
		assertNotNull("toRgbFrame returned null for a valid image", rgb);
		assertEquals("frame must be TYPE_INT_RGB (no alpha) for the JPEG writer",
			BufferedImage.TYPE_INT_RGB, rgb.getType());
		assertEquals("width must be preserved", 32, rgb.getWidth());
		assertEquals("height must be preserved", 24, rgb.getHeight());
	}

	/**
	 * WEDGE ARM (added 2026-09-02 after mutation testing): clipFramePending is a one-in-flight latch, so
	 * ANY path out of the frame callback must clear it. A DrawManager that hands back a null image — the
	 * documented shape when the GPU plugin owns the surface — must not leave the latch set, or capture
	 * silently stops for the rest of the visit after one bad frame and the clip is short or empty.
	 *
	 * Falsified: removing the `clipFramePending = false` from the null branch of onClipFrameTick makes
	 * this arm fail. Without it that mutation survived the whole suite.
	 */
	@Test
	public void nullFrameDoesNotWedgeCapture() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", linked());
		// A DrawManager whose listener is invoked immediately with a null image.
		inject(plugin, "drawManager", new net.runelite.client.ui.DrawManager()
		{
			@Override
			public void requestNextFrameListener(java.util.function.Consumer<java.awt.Image> consumer)
			{
				consumer.accept(null);
			}
		});
		inject(plugin, "clipCapturing", true);
		inject(plugin, "clipVisit", new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES));

		plugin.onClipFrameTick();		// first sample: null frame comes back
		assertFalse("a null frame must release the in-flight latch", pending(plugin));

		plugin.onClipFrameTick();		// a wedged latch would make this a no-op forever
		assertFalse("capture must still be able to request further frames", pending(plugin));
	}

	private static boolean pending(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("clipFramePending");
		f.setAccessible(true);
		return f.getBoolean(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import com.sun.net.httpserver.HttpServer;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import net.runelite.client.ui.DrawManager;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okio.Buffer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the store delivery-proof burst UPLOAD path (Task B3) — no live client needed.
 * Covers: JPEG encode (SOI + ImageIO round-trip), the multipart burst builder (frame_count field
 * exactly equals the attached frames[] parts), the per-frame cap filter, the newest-suffix (tail)
 * truncation at the 16 MiB burst cap, the mandatory no-transaction privacy discard (US-08), and one
 * happy-path POST through a local JDK HttpServer stub proving submitStoreClipUpload targets the real
 * /store-frames-ingest route with the real constants. Live-client wiring is covered by the manual plan.
 */
public class StoreClipUploadTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";
	private static final byte[] JPEG_SOI = {(byte) 0xFF, (byte) 0xD8};

	// (a) encodeJpeg emits a real JPEG: SOI marker 0xFFD8 and round-trips via ImageIO at the same dims.
	@Test
	public void encodeJpegProducesSoiAndRoundTrips() throws Exception
	{
		byte[] bytes = AccountConnectPlugin.encodeJpeg(rgbFrame(48, 36));
		assertNotNull("encodeJpeg returned null", bytes);
		assertTrue("JPEG too short", bytes.length > 2);
		assertEquals("SOI byte 0", JPEG_SOI[0], bytes[0]);
		assertEquals("SOI byte 1", JPEG_SOI[1], bytes[1]);

		BufferedImage back = javax.imageio.ImageIO.read(new ByteArrayInputStream(bytes));
		assertNotNull("JPEG did not decode", back);
		assertEquals("width not preserved", 48, back.getWidth());
		assertEquals("height not preserved", 36, back.getHeight());
	}

	// (b) burst builder: frame_count field must EXACTLY equal the number of frames[] parts attached
	// (the server 400s on a mismatch), and the token/captured_at/fps fields must be present.
	@Test
	public void buildStoreClipBodyFrameCountMatchesAttachedParts() throws Exception
	{
		List<byte[]> kept = new ArrayList<>();
		kept.add(new byte[]{1, 2, 3});
		kept.add(new byte[]{4, 5, 6});
		kept.add(new byte[]{7, 8, 9});

		MultipartBody mb = AccountConnectPlugin.buildStoreClipBody(kept, TEST_TOKEN, 1700000000L, AccountConnectPlugin.CLIP_FPS);

		int frameParts = 0;
		int declaredCount = -1;
		boolean hasToken = false;
		boolean hasCapturedAt = false;
		boolean hasFps = false;
		for (int i = 0; i < mb.size(); i++)
		{
			MultipartBody.Part p = mb.part(i);
			String cd = p.headers().get("Content-Disposition");
			assertNotNull("part missing Content-Disposition", cd);
			if (cd.contains("name=\"frames[]\""))
			{
				frameParts++;
			}
			else if (cd.contains("name=\"frame_count\""))
			{
				declaredCount = Integer.parseInt(readPartUtf8(p).trim());
			}
			else if (cd.contains("name=\"token\""))
			{
				hasToken = TEST_TOKEN.equals(readPartUtf8(p).trim());
			}
			else if (cd.contains("name=\"captured_at\""))
			{
				hasCapturedAt = true;
			}
			else if (cd.contains("name=\"fps\""))
			{
				hasFps = true;
			}
		}
		assertEquals("expected 3 frames[] parts", 3, frameParts);
		assertEquals("frame_count must equal attached parts", 3, declaredCount);
		assertTrue("token field missing/mismatched", hasToken);
		assertTrue("captured_at field missing", hasCapturedAt);
		assertTrue("fps field missing", hasFps);
	}

	// (c) any frame over the per-frame cap is dropped, and frame_count still matches what is attached.
	@Test
	public void overPerFrameCapFramesDroppedAndCountMatches() throws Exception
	{
		List<byte[]> encoded = new ArrayList<>();
		encoded.add(sized(500_000, 0));					// ok
		encoded.add(sized(AccountConnectPlugin.MAX_CLIP_FRAME_BYTES + 1, 1));	// over per-frame cap -> dropped
		encoded.add(sized(500_000, 2));					// ok

		List<byte[]> kept = AccountConnectPlugin.selectStoreClipFrames(
			encoded, AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_FRAME_BYTES, AccountConnectPlugin.MAX_CLIP_BURST_BYTES);

		assertEquals("oversized frame not dropped", 2, kept.size());
		assertEquals("wrong survivor 0", 0, kept.get(0)[0]);
		assertEquals("wrong survivor 1", 2, kept.get(1)[0]);

		MultipartBody mb = AccountConnectPlugin.buildStoreClipBody(kept, TEST_TOKEN, 1700000000L, AccountConnectPlugin.CLIP_FPS);
		int frameParts = 0;
		int declaredCount = -1;
		for (int i = 0; i < mb.size(); i++)
		{
			String cd = mb.part(i).headers().get("Content-Disposition");
			if (cd != null && cd.contains("name=\"frames[]\""))
			{
				frameParts++;
			}
			else if (cd != null && cd.contains("name=\"frame_count\""))
			{
				declaredCount = Integer.parseInt(readPartUtf8(mb.part(i)).trim());
			}
		}
		assertEquals("attached parts wrong after drop", 2, frameParts);
		assertEquals("frame_count must match attached after drop", 2, declaredCount);
	}

	// (d) truncation keeps the NEWEST suffix (the chronological tail) — the shop-close / sale frames are
	// the actual evidence; walking oldest-first would drop them. 20 frames of 1MB each exceed the 16 MiB
	// burst cap; exactly the last 16 (indices 4..19) must survive, in order.
	@Test
	public void truncationKeepsNewestSuffix() throws Exception
	{
		List<byte[]> encoded = new ArrayList<>();
		for (int i = 0; i < 20; i++)
		{
			encoded.add(sized(1_000_000, i));			// each == per-frame cap, allowed
		}
		List<byte[]> kept = AccountConnectPlugin.selectStoreClipFrames(
			encoded, AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_FRAME_BYTES, AccountConnectPlugin.MAX_CLIP_BURST_BYTES);

		assertEquals("16 MiB cap must keep exactly 16 x 1MB frames", 16, kept.size());
		assertEquals("kept set must start at the tail (index 4)", 4, kept.get(0)[0]);
		assertEquals("kept set must end at the newest (index 19)", 19, kept.get(15)[0]);
		// prove strict chronological order across the kept suffix
		for (int i = 0; i < kept.size(); i++)
		{
			assertEquals("kept order broken at " + i, 4 + i, kept.get(i)[0]);
		}
	}

	// (e) MANDATORY PRIVACY (US-08): a shop visit with NO buy/sell uploads NOTHING. Drive the real
	// stopStoreClipCapture(true) with storeTxThisVisit=false and prove submitStoreClipUpload is never
	// reached (subclass-override seam) and the ring is cleared. Positive control: tx=true DOES upload.
	@Test
	public void noStoreTransactionUploadsNothing() throws Exception
	{
		final boolean[] uploaded = {false};
		AccountConnectPlugin plugin = new AccountConnectPlugin()
		{
			@Override
			void submitStoreClipUpload(List<byte[]> frames, List<Long> capturedAtMillis)
			{
				uploaded[0] = true;
			}
		};
		inject(plugin, "config", enabledConfig(null));
		inject(plugin, "drawManager", new DrawManager());
		StoreVisitClip ring = newVisit();
		ring.offer(jpeg(16, 12), 1_000L);
		ring.offer(jpeg(16, 12), 1_033L);
		inject(plugin, "clipVisit", ring);
		inject(plugin, "clipCapturing", true);
		plugin.storeTxThisVisit = false;			// the visit had NO buy/sell

		plugin.stopStoreClipCapture(true);			// upload requested, but tx flag is false

		assertFalse("no-transaction visit must NEVER upload", uploaded[0]);
		assertEquals("frames must be discarded", 0, ring.size());

		// positive control: an identical visit WITH a transaction does upload.
		final boolean[] uploaded2 = {false};
		AccountConnectPlugin plugin2 = new AccountConnectPlugin()
		{
			@Override
			void submitStoreClipUpload(List<byte[]> frames, List<Long> capturedAtMillis)
			{
				uploaded2[0] = true;
			}
		};
		inject(plugin2, "config", enabledConfig(null));
		inject(plugin2, "drawManager", new DrawManager());
		StoreVisitClip ring2 = newVisit();
		ring2.offer(jpeg(16, 12), 1_000L);
		inject(plugin2, "clipVisit", ring2);
		inject(plugin2, "clipCapturing", true);
		plugin2.storeTxThisVisit = true;			// a buy/sell happened

		plugin2.stopStoreClipCapture(true);

		assertTrue("a visit with a transaction must upload", uploaded2[0]);
	}

	// (glue) happy path: submitStoreClipUpload actually POSTs the burst to the real /store-frames-ingest
	// route with the real constants — the pure-seam tests above prove the logic but not the wiring.
	@Test
	public void publicStoreClipUploadRefusesEncodedBurst() throws Exception
	{
		BlockingQueue<Capture> received = new LinkedBlockingQueue<>();
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			byte[] reqBody = readAll(exchange.getRequestBody());
			byte[] resp = "{\"ok\":true}".getBytes(StandardCharsets.UTF_8);
			exchange.sendResponseHeaders(200, resp.length);
			exchange.getResponseBody().write(resp);
			exchange.close();
			received.add(new Capture(exchange.getRequestURI().getPath(),
				exchange.getRequestHeaders().getFirst("Content-Type"), reqBody));
		});
		server.start();
		try
		{
			String base = "http://127.0.0.1:" + server.getAddress().getPort() + "/wp-json/osrsbis/v1";
			AccountConnectPlugin plugin = new AccountConnectPlugin();
			inject(plugin, "config", enabledConfig(base));
			inject(plugin, "executor", Executors.newSingleThreadScheduledExecutor());
			inject(plugin, "okHttpClient", new OkHttpClient());

			List<byte[]> frames = new ArrayList<>();
			frames.add(jpeg(40, 30));
			frames.add(jpeg(40, 30));
			frames.add(jpeg(40, 30));
			plugin.submitStoreClipUpload(frames, java.util.Arrays.asList(1_700_000_000_000L,
				1_700_000_000_033L, 1_700_000_000_066L));

			assertNull("encoded frames must not leave the public artifact", received.poll(300, TimeUnit.MILLISECONDS));
		}
		finally
		{
			server.stop(0);
		}
	}

	// ---- helpers ----

	private static StoreVisitClip newVisit()
	{
		return new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES);
	}

	private static byte[] sized(int len, int tag)
	{
		byte[] b = new byte[len];
		b[0] = (byte) tag;
		return b;
	}

	private static BufferedImage rgbFrame(int w, int h)
	{
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.BLUE);
		g.fillRect(0, 0, w, h);
		g.setColor(Color.YELLOW);
		g.fillRect(0, 0, w / 2, h / 2);
		g.dispose();
		return img;
	}

	/**
	 * THE UPLOAD TIMEOUT (added 2026-09-03) — the defect that destroyed every chunked clip.
	 *
	 * RuneLite's injected OkHttpClient keeps OkHttp's default 10s timeouts. A real frame chunk does
	 * not upload in 10s, so the client abandoned the request mid-body. Because that is a CANCEL and
	 * not a failure, the server's cleanup never ran either: orphaned frames in storage, no manifest,
	 * no database row, nothing logged above debug.
	 *
	 * Reproduced on production with identical bytes: a 10s cap left 49 objects and no manifest (the
	 * exact signature seen in six real staff bursts); a 60s cap stored all 101 and returned 200.
	 *
	 * This asserts the constant is sized for the payload rather than left at the shared default.
	 */
	@Test
	public void clipUploadTimeoutIsSizedForTheChunkNotThePageFetchDefault()
	{
		final int okhttpDefaultSeconds = 10;
		assertTrue("CLIP_UPLOAD_TIMEOUT_SECONDS=" + AccountConnectPlugin.CLIP_UPLOAD_TIMEOUT_SECONDS
				+ " is at or under OkHttp's " + okhttpDefaultSeconds
				+ "s default; a real chunk cannot upload that fast and the burst is destroyed mid-body",
			AccountConnectPlugin.CLIP_UPLOAD_TIMEOUT_SECONDS > okhttpDefaultSeconds);

		// Sized against the measured worst case: ~37KB/frame, and a 100-frame chunk took up to 16.6s
		// on a fast host. A 40-frame chunk on a slow domestic uplink must still fit.
		final int worstCaseSecondsForAChunk = 45;
		assertTrue("timeout must cover a slow uplink's worst case (" + worstCaseSecondsForAChunk + "s)",
			AccountConnectPlugin.CLIP_UPLOAD_TIMEOUT_SECONDS >= worstCaseSecondsForAChunk);

		// But not unbounded: a hung socket must not pin an executor thread for the whole session.
		assertTrue("an effectively-infinite timeout would hang the upload executor on a dead socket",
			AccountConnectPlugin.CLIP_UPLOAD_TIMEOUT_SECONDS <= 300);
	}

	/**
	 * SERVER SUBREQUEST CONTRACT (added 2026-09-03). The server writes one R2 object per frame inside a
	 * single Worker invocation, which has a hard subrequest ceiling. A chunk larger than the server's
	 * MEDIA.FRAMES_PER_REQUEST_MAX kills that worker MID-LOOP: orphaned frames in storage, no manifest,
	 * no database row, no cleanup — and the plugin cannot tell, because it only sees a dead socket.
	 * Every delivery clip between the chunked-upload release and 2026-09-03 was lost exactly this way.
	 *
	 * This arm is the plugin's half of a two-repo contract. If it is ever raised past what the server
	 * grants, clips go silently missing again, so the number is asserted rather than trusted.
	 */
	@Test
	public void chunkSizeStaysInsideTheServerSubrequestBudget()
	{
		final int serverPerRequestMax = 40;	// osrsbis-web MEDIA.FRAMES_PER_REQUEST_MAX
		assertTrue("CLIP_CHUNK_FRAMES=" + AccountConnectPlugin.CLIP_CHUNK_FRAMES
				+ " exceeds the server's " + serverPerRequestMax
				+ "-frame per-request budget; the worker dies mid-write and the clip is lost silently",
			AccountConnectPlugin.CLIP_CHUNK_FRAMES <= serverPerRequestMax);
		assertTrue("a zero/negative chunk size would loop forever or upload nothing",
			AccountConnectPlugin.CLIP_CHUNK_FRAMES >= 1);
	}

	/** A full-length visit must still be delivered — in more chunks, not fewer frames. */
	@Test
	public void aFullBurstIsSplitIntoWholeChunksWithNoFrameLost()
	{
		int total = AccountConnectPlugin.MAX_CLIP_FRAMES;
		int chunk = AccountConnectPlugin.CLIP_CHUNK_FRAMES;
		// Guard the loop bound FIRST. A zero or negative chunk makes `off += chunk` non-advancing, so
		// this test would hang forever rather than fail — found by mutation on 2026-09-03, where the
		// chunk=0 mutant produced a 120s timeout instead of a red assertion. A test that hangs on a
		// defect is not a test.
		assertTrue("CLIP_CHUNK_FRAMES must be >= 1; " + chunk + " would never advance the upload loop",
			chunk >= 1);
		int sent = 0, chunks = 0;
		for (int off = 0; off < total; off += chunk)
		{
			sent += Math.min(chunk, total - off);
			chunks++;
		}
		assertEquals("chunking must cover every captured frame exactly once", total, sent);
		assertTrue("a full visit should split into more than one chunk at this size", chunks > 1);
	}

	/** An ENCODED frame — what the ring holds since the heap fix (2026-09-02). */
	private static byte[] jpeg(int w, int h)
	{
		return AccountConnectPlugin.encodeJpeg(rgbFrame(w, h));
	}

	private static AccountConnectConfig enabledConfig(String baseUrl)
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;	// the token IS the gate now (the opt-in toggle was removed 2026-09-02)
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl != null ? baseUrl : AccountConnectConfig.super.apiBaseUrl();
			}
		};
	}

	private static String readPartUtf8(MultipartBody.Part part) throws java.io.IOException
	{
		Buffer buffer = new Buffer();
		part.body().writeTo(buffer);
		return buffer.readUtf8();
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static byte[] readAll(InputStream in) throws java.io.IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] chunk = new byte[8192];
		int n;
		while ((n = in.read(chunk)) != -1)
		{
			out.write(chunk, 0, n);
		}
		return out.toByteArray();
	}

	private static int indexOf(byte[] haystack, byte[] needle)
	{
		outer:
		for (int i = 0; i <= haystack.length - needle.length; i++)
		{
			for (int j = 0; j < needle.length; j++)
			{
				if (haystack[i + j] != needle[j])
				{
					continue outer;
				}
			}
			return i;
		}
		return -1;
	}

	private static final class Capture
	{
		final String path;
		final String contentType;
		final byte[] body;

		Capture(String path, String contentType, byte[] body)
		{
			this.path = path;
			this.contentType = contentType;
			this.body = body;
		}
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Before;
import org.junit.Test;

/**
 * A sell click the shop refused (live run 2026-10-19: Pot still held, shop stock unchanged) still sent a
 * store_sell, because one armed click resolved on any inventory change inside its window. The retry that
 * really sold sent a second row, so one sale showed as two. A click now resolves only on a change that moved
 * its own item, driven here through the real click and inventory events.
 */
public class StoreFailedSellTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int LOBSTER = 379;
	private static final int NATURE = 561;
	private static final int DEATH = 560;

	private AccountConnectPlugin plugin;
	private Client client;
	private int tick = 100;
	private Item[] inventory;

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		});
		client = mock(Client.class);
		when(client.getTickCount()).thenAnswer(i -> tick);
		ItemContainer inv = mock(ItemContainer.class);
		when(inv.getItems()).thenAnswer(i -> inventory);
		when(client.getItemContainer(any(InventoryID.class))).thenReturn(inv);
		inject("client", client);
		inject("shopOpen", true);
		inventoryIs(735_512L, POT, LOBSTER);
	}

	private void inject(String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private void sell(int item)
	{
		MenuOptionClicked click = mock(MenuOptionClicked.class);
		when(click.getMenuOption()).thenReturn("Sell 1<col=ff9040>");
		when(click.getItemId()).thenReturn(item);
		plugin.onMenuOptionClicked(click);
	}

	private void inventoryIs(long coins, int... items)
	{
		List<Item> rows = new ArrayList<>();
		rows.add(new Item(COINS, (int) coins));
		for (int item : items) rows.add(new Item(item, 1));
		inventory = rows.toArray(new Item[0]);
	}

	/** The server's inventory update: these items and this coin count. */
	private void inventoryNow(long coins, int... items)
	{
		inventoryIs(coins, items);
		ItemContainer changed = client.getItemContainer(InventoryID.INVENTORY);
		plugin.onItemContainerChanged(new ItemContainerChanged(net.runelite.api.gameval.InventoryID.INV, changed));
	}

	private List<Map<String, Object>> storeSells()
	{
		return plugin.pendingEvents.stream().filter(e -> "store_sell".equals(e.get("type"))).collect(Collectors.toList());
	}

	@Test
	public void aRefusedSellThenARealRetryGiveOneRow()
	{
		sell(POT);
		tick++;
		inventoryNow(735_512L, POT, LOBSTER);			// some inventory update, the Pot is still held
		assertEquals("a sale that moved no item is not a sale", 0, storeSells().size());

		tick += AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1;
		sell(POT);										// the retry
		tick++;
		inventoryNow(735_512L, LOBSTER);				// sold, the shop paid 0 gp

		List<Map<String, Object>> sells = storeSells();
		assertEquals("one real sale, one row", 1, sells.size());
		assertEquals(POT, sells.get(0).get("item"));
		assertEquals(0, plugin.storePendings.size());
		assertEquals("a measured 0 gp sale says so", 0L, sells.get(0).get("gp_total"));
		assertEquals(true, sells.get(0).get("coins_unchanged"));
	}

	/**
	 * Live 0.7.61 player run (2026-10-28): Sell 1 Vial, the shop paid 0 gp, and the row had no gp_total, the
	 * same as a sale whose coins were never read. A measured 0 now says gp_total 0 with coins_unchanged.
	 */
	@Test
	public void aZeroGpSaleIsMeasuredAndEveryUnmeasuredCaseIsNot()
	{
		sell(POT);
		tick++;
		inventoryNow(735_512L, LOBSTER);
		Map<String, Object> zero = storeSells().get(0);
		assertEquals(0L, zero.get("gp_total"));
		assertEquals(true, zero.get("coins_unchanged"));
		assertEquals(1L, zero.get("qty_executed"));
		assertFalse("no price from a 0", zero.containsKey("unit_price_gp"));
		assertEquals("it survives the public projection", true, PublicTransport.event(zero).get("coins_unchanged"));
		plugin.pendingEvents.clear();

		sell(LOBSTER);
		plugin.flushStorePendingOnShopClose();		// closed before any change: nothing was measured
		assertFalse(storeSells().get(0).containsKey("gp_total"));
		assertFalse(storeSells().get(0).containsKey("coins_unchanged"));
	}

	@Test
	public void aSaleThatPaysIsNotMarked()
	{
		sell(LOBSTER);
		tick++;
		inventoryNow(735_512L + 28L, POT);
		assertEquals(28L, storeSells().get(0).get("gp_total"));
		assertFalse(storeSells().get(0).containsKey("coins_unchanged"));
	}

	@Test
	public void theBuilderMarksOnlyAMeasuredUnambiguousSell()
	{
		assertEquals(true, AccountConnectPlugin.buildStoreTxFields("store_sell", POT, 1, 100L, 100L, false, false, 1L)
			.get("coins_unchanged"));
		assertFalse("two sales in one change", AccountConnectPlugin.buildStoreTxFields("store_sell", POT, 1, 100L, 100L,
			true, false, 1L).containsKey("gp_total"));
		assertFalse("merged clicks", AccountConnectPlugin.buildStoreTxFields("store_sell", POT, 2, 100L, 100L,
			false, true, 1L).containsKey("gp_total"));
		assertFalse("nothing moved", AccountConnectPlugin.buildStoreTxFields("store_sell", POT, 1, 100L, 100L,
			false, false, 0L).containsKey("gp_total"));
		assertFalse("item count unknown", AccountConnectPlugin.buildStoreTxFields("store_sell", POT, 1, 100L, 100L,
			false, false, AccountConnectPlugin.UNKNOWN_ITEM_COUNT).containsKey("gp_total"));
		assertFalse("coins fell on a sell", AccountConnectPlugin.buildStoreTxFields("store_sell", POT, 1, 100L, 90L,
			false, false, 1L).containsKey("gp_total"));
		assertFalse("a buy for 0 is not a shop case", AccountConnectPlugin.buildStoreTxFields("store_buy", POT, 1, 100L,
			100L, false, false, 1L).containsKey("gp_total"));
	}

	@Test
	public void anUnrelatedCoinChangeIsNotTheSalePrice()
	{
		sell(LOBSTER);
		tick++;
		inventoryNow(735_512L + 100L, POT, LOBSTER);	// coins moved for another reason, Lobster still held
		inventoryNow(735_512L + 100L + 28L, POT);		// the sale itself

		List<Map<String, Object>> sells = storeSells();
		assertEquals(1, sells.size());
		assertEquals("only the sale's own coins", 28L, sells.get(0).get("gp_total"));
	}

	@Test
	public void aRealSaleStillResolvesOnItsOwnChange()
	{
		sell(LOBSTER);
		tick++;
		inventoryNow(735_512L + 28L, POT);

		List<Map<String, Object>> sells = storeSells();
		assertEquals(1, sells.size());
		assertEquals(LOBSTER, sells.get(0).get("item"));
		assertEquals(28L, sells.get(0).get("gp_total"));
	}

	@Test
	public void aRefusedSellLeavesNoRowAtShopClose()
	{
		sell(POT);
		tick++;
		inventoryNow(735_512L, POT, LOBSTER);
		tick += AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1;
		plugin.flushStorePendingOnShopClose();
		assertEquals(0, storeSells().size());
		assertFalse(plugin.storePendings.containsKey(POT));
	}

	/**
	 * Live 0.7.55 (2026-10-24): a player buying two runes per world got both in one inventory change. The coins
	 * cannot be split between them, but each rune's own count measured what moved, so each row keeps it.
	 */
	@Test
	public void twoBuysInOneChangeKeepTheirMeasuredQuantity() throws Exception
	{
		inventoryIs(735_512L, POT, LOBSTER);
		buy(NATURE, 50);
		buy(DEATH, 50);
		tick++;
		inventory = new Item[]{new Item(COINS, 735_512 - 7_000), new Item(POT, 1), new Item(LOBSTER, 1),
			new Item(NATURE, 30), new Item(DEATH, 30)};
		ItemContainer changed = client.getItemContainer(InventoryID.INVENTORY);
		plugin.onItemContainerChanged(new ItemContainerChanged(net.runelite.api.gameval.InventoryID.INV, changed));

		List<Map<String, Object>> buys = plugin.pendingEvents.stream().filter(e -> "store_buy".equals(e.get("type")))
			.collect(Collectors.toList());
		assertEquals(2, buys.size());
		for (Map<String, Object> b : buys)
		{
			assertFalse("the coins of two buys are never split by a guess", b.containsKey("gp_total"));
			assertEquals(30L, b.get("qty_executed"));
			assertEquals(true, b.get("qty_partial"));
			assertFalse(b.containsKey("unit_price_gp"));
		}
	}

	private void buy(int item, int qty)
	{
		MenuOptionClicked click = mock(MenuOptionClicked.class);
		when(click.getMenuOption()).thenReturn("Buy " + qty + "<col=ff9040>");
		when(click.getItemId()).thenReturn(item);
		plugin.onMenuOptionClicked(click);
	}

	@Test
	public void sellThenCloseInsideTheWindowStillReportsTheSale()
	{
		sell(LOBSTER);
		plugin.flushStorePendingOnShopClose();		// buy- or sell-then-close: the change has not arrived yet
		assertEquals(1, storeSells().size());
		assertFalse("no coins could be measured", storeSells().get(0).containsKey("gp_total"));
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;

/**
 * 0.7.4 item 3 — STORE gp_total INTEGRITY FOR MULTI-QUANTITY TRANSACTIONS.
 *
 * <p>Production evidence (2026-08-15 audit, newest clients only): {@code gp_total} was missing from
 * <b>140 of 377 (37.1%)</b> multi-quantity {@code store_buy} events against <b>14 of 176 (8.0%)</b> at
 * qty=1. The miss concentrates on qty&gt;1 because a player spam-clicking "Buy 10" lands two clicks on
 * one tick, which the old code flagged {@code ambiguous} and then dropped the gold for.
 *
 * <p>General-store selling is how gold is delivered, so those four weeks of events showed the item
 * leaving and never the coins arriving.
 *
 * <p>The fix folds same-tick clicks on the SAME item and direction into ONE pending with a summed
 * quantity and the ORIGINAL coinsBefore — sound because a pending is only consumed by an inventory
 * change, so an un-resolved pending proves no inventory change has happened and its coinsBefore still
 * predates both transactions. Genuinely un-splittable cases (different item, opposite direction) stay
 * ambiguous and still degrade to {item, qty} rather than emitting a guess.
 */
public class StoreMultiQtyGpTest
{
	private static final int TICK = 4242;
	private static final int COAL = 453;
	private static final int ORE = 440;

	// ------------------------------------------------------------------ the defect, directly

	@Test
	public void sameTickRepeatBuyOnOneItemNowCarriesExactGpInsteadOfDroppingIt()
	{
		// Two "Buy 10" clicks on the same tick, coins 1,000,000 before either.
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK);

		assertFalse("a same-item same-tick repeat is NOT ambiguous — one delta covers both",
			merged.ambiguous);
		assertEquals("quantities must sum", 20, merged.qty);
		assertEquals("coinsBefore must stay the ORIGINAL pre-transaction reading",
			1_000_000L, merged.coinsBefore);

		// 20 coal cost 2,000 total; coins end at 998,000. Both clicks executed here.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_000L, merged.ambiguous, merged.qtyMerged);

		assertEquals("the exact transacted gold must be present", 2_000L, fields.get("gp_total"));
		assertEquals(20, fields.get("qty"));
		assertNull("merged qty is click intent, so no unit price may be derived from it",
			fields.get("unit_price_gp"));
	}

	@Test
	public void beforeTheFixThisExactCaseEmittedNoGold()
	{
		// The old behaviour, reproduced by passing ambiguous=true: item and qty survive, gold does not.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", COAL, 20, 1_000_000L, 998_000L, true);

		assertNull("this is the production defect: 37.1% of multi-qty buys looked like this",
			fields.get("gp_total"));
		assertEquals("only item and qty survived", 2, fields.size());
	}

	// ------------------------------------------------------------------ the half-price regression

	/**
	 * REGRESSION GUARD for the defect the conservative fix exists to prevent.
	 *
	 * <p>A merged qty is the sum of click INTENT. A click can fail — shop out of stock, inventory full,
	 * not enough coins — while still having been counted into that sum. So when two "Buy 10" clicks merge
	 * but only the first executes, the truth is: 10 items moved for 1,000 gp (100 gp each).
	 *
	 * <p>gp_total is still EXACT, because it is the measured coin delta and the coins only moved for the
	 * click that actually happened. But qty reads 20, so a derived unit price would be 1000/20 = 50 —
	 * <b>half the real unit price</b>, and plausible enough that nothing downstream would ever question it.
	 *
	 * <p>That is strictly worse than the bug this release fixes: an absent field is recoverable, a
	 * confidently wrong number is not. unit_price_gp must therefore be ABSENT on any merged pending.
	 */
	@Test
	public void mergedQuantityNeverProducesAHalfPriceUnitCost()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK);

		assertTrue("a merged pending must be marked as such", merged.qtyMerged);

		// Only the FIRST click executed: 10 coal at 100 gp = 1,000 gp. Coins 1,000,000 -> 999,000.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 999_000L, merged.ambiguous, merged.qtyMerged);

		assertEquals("the coin delta is ground truth and stays exact", 1_000L, fields.get("gp_total"));
		assertNull("unit_price_gp MUST be omitted — 1000/20 = 50 would be half the real 100 gp price",
			fields.get("unit_price_gp"));
	}

	/**
	 * Rewritten 2026-08-17. The old title — "unmerged multi-quantity STILL carries a unit price BECAUSE
	 * its denominator is confirmed" — encoded the assumption the field disproved: one menu option does not
	 * confirm anything, because the shop's stock, the inventory's free space and the player's coins all cap
	 * what executes. Confirmation now means MEASURED: the item-count delta equals the clicked quantity.
	 */
	@Test
	public void unmergedMultiQuantityCarriesAUnitPriceOnlyWhenTheExecutedQuantityMatchesTheClick()
	{
		AccountConnectPlugin.StorePending p =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 20, 1_000_000L, 0L, TICK);
		assertFalse("a single click is not merged", p.qtyMerged);

		Map<String, Object> confirmed = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 998_000L, p.ambiguous, p.qtyMerged, 20L);
		assertEquals(2_000L, confirmed.get("gp_total"));
		assertEquals("a MEASURED denominator yields a unit price", 100L, confirmed.get("unit_price_gp"));

		// Same click, but the shop only had 5 — the field-observed shape.
		Map<String, Object> partial = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 999_500L, p.ambiguous, p.qtyMerged, 5L);
		assertEquals("the coin delta is still exact", 500L, partial.get("gp_total"));
		assertEquals(Boolean.TRUE, partial.get("qty_partial"));
		assertEquals(5L, partial.get("qty_executed"));
		assertNull("25 gp/item would be 4x low against the real 100", partial.get("unit_price_gp"));
	}

	/**
	 * The field-observed numbers themselves, both directions, as the fixed code must now report them.
	 */
	@Test
	public void theFieldObservedPartialFillsAreLabelledRatherThanPriced()
	{
		// BUY 50 on a shop holding 5: 26,207,203 -> 26,203,278 coins, 0 -> 5 packs.
		Map<String, Object> buy = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", 22660, 50, 26_207_203L, 26_203_278L, false, false, 5L);
		assertEquals(3_925L, buy.get("gp_total"));
		assertEquals(Boolean.TRUE, buy.get("qty_partial"));
		assertEquals(5L, buy.get("qty_executed"));
		assertNull("78 gp/item against a true ~785", buy.get("unit_price_gp"));

		// SELL 50 holding 27: coins +2,175, 27 -> 0 packs.
		Map<String, Object> sell = AccountConnectPlugin.buildStoreTxFields(
			"store_sell", 22660, 50, 26_201_103L, 26_203_278L, false, false, 27L);
		assertEquals(2_175L, sell.get("gp_total"));
		assertEquals(Boolean.TRUE, sell.get("qty_partial"));
		assertEquals(27L, sell.get("qty_executed"));
		assertNull("43 gp/item against a true ~80", sell.get("unit_price_gp"));
	}

	/**
	 * A merged row now also publishes what actually moved when it can be measured. The merged qty stays an
	 * upper bound and still gets no unit price — the label is unchanged — but a consumer gains a real
	 * denominator instead of only "trust nothing here".
	 */
	@Test
	public void aMergedRowPublishesTheMeasuredQuantityAlongsideItsUpperBound()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, 0L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, 0L, TICK + 1);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_500L,
			merged.ambiguous, merged.qtyMerged, 15L);	// the shop ran short: 15 of 20 arrived

		assertEquals(Boolean.TRUE, fields.get("qty_merged"));
		assertEquals("the click-intent upper bound", 20, fields.get("qty"));
		assertEquals("what actually moved", 15L, fields.get("qty_executed"));
		assertNull("still never a derived price on a merged row", fields.get("unit_price_gp"));
	}

	/** A delta pointing the wrong way is not this transaction's, so nothing is measured from it. */
	@Test
	public void anImpossibleItemDeltaIsTreatedAsUnmeasuredRatherThanAsAQuantity()
	{
		AccountConnectPlugin.StorePending buy = new AccountConnectPlugin.StorePending(
			"store_buy", COAL, 10, 1_000_000L, 40L, TICK, false, false);
		assertEquals("a buy whose item count FELL measures nothing",
			AccountConnectPlugin.UNKNOWN_ITEM_COUNT, AccountConnectPlugin.executedQty(buy, 30L));

		AccountConnectPlugin.StorePending sell = new AccountConnectPlugin.StorePending(
			"store_sell", COAL, 10, 1_000_000L, 30L, TICK, false, false);
		assertEquals("a sell whose item count ROSE measures nothing",
			AccountConnectPlugin.UNKNOWN_ITEM_COUNT, AccountConnectPlugin.executedQty(sell, 40L));

		AccountConnectPlugin.StorePending noBase = new AccountConnectPlugin.StorePending(
			"store_buy", COAL, 10, 1_000_000L, TICK, false);
		assertEquals("no baseline, no measurement",
			AccountConnectPlugin.UNKNOWN_ITEM_COUNT, AccountConnectPlugin.executedQty(noBase, 10L));
	}

	/**
	 * A merged row must SAY it is merged, so nothing downstream pairs gp_total against an unconfirmed
	 * qty. Two things can make the merged qty overstate what those coins bought: a failed click, or the
	 * server settling the two clicks on different ticks (the first inventory update then carries only
	 * the first transaction's delta). Neither is detectable client-side, so the row is labelled rather
	 * than guessed at.
	 */
	@Test
	public void aMergedRowIsLabelledSoConsumersTreatQtyAsAnUpperBound()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_000L, merged.ambiguous, merged.qtyMerged);

		assertEquals("coins that really moved", 2_000L, fields.get("gp_total"));
		assertEquals("the row must carry the merged marker", Boolean.TRUE, fields.get("qty_merged"));
		assertNull("and never a derived unit price", fields.get("unit_price_gp"));
	}

	@Test
	public void anUnmergedRowCarriesNoMergedMarker()
	{
		AccountConnectPlugin.StorePending p =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 20, 1_000_000L, 0L, TICK);
		// all 20 arrived, so the denominator is confirmed
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 998_000L, p.ambiguous, p.qtyMerged, 20L);

		assertNull("a single click needs no caveat", fields.get("qty_merged"));
		assertNull("nor a partial-fill caveat", fields.get("qty_partial"));
		assertEquals("and keeps its unit price", 100L, fields.get("unit_price_gp"));
	}

	@Test
	public void sameTickRepeatSellOnOneItemAlsoResolves()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_sell", COAL, 5, 500_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_sell", COAL, 5, 500_100L, TICK);

		assertFalse(merged.ambiguous);
		assertEquals(10, merged.qty);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 500_800L, merged.ambiguous, merged.qtyMerged);
		assertEquals("sell proceeds must be captured", 800L, fields.get("gp_total"));
		assertNull("merged sell qty is intent too — no unit price", fields.get("unit_price_gp"));
	}

	// ------------------------------------------------------------------ genuine ambiguity is PRESERVED

	@Test
	public void sameTickClicksOnDifferentItemsStayAmbiguousBecauseOneDeltaCannotBeSplit()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", ORE, 10, 999_000L, TICK);

		assertTrue("two different items in one delta cannot be attributed", merged.ambiguous);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 990_000L, merged.ambiguous);
		assertNull("we must still refuse to emit a guessed number", fields.get("gp_total"));
	}

	@Test
	public void sameTickBuyThenSellStaysAmbiguous()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_sell", COAL, 10, 999_000L, TICK);

		assertTrue("opposite directions net against each other in one delta", merged.ambiguous);
	}

	@Test
	public void anAlreadyAmbiguousPendingStaysAmbiguousWhenAThirdClickLands()
	{
		AccountConnectPlugin.StorePending a =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending b =
			AccountConnectPlugin.mergeStorePending(a, "store_buy", ORE, 10, 999_000L, TICK);
		AccountConnectPlugin.StorePending c =
			AccountConnectPlugin.mergeStorePending(b, "store_buy", COAL, 10, 998_000L, TICK);

		assertTrue("ambiguity must not be laundered away by a later same-item click", c.ambiguous);
	}

	// ------------------------------------------------------------------ unaffected paths

	/**
	 * SUPERSEDED BY FIELD EVIDENCE (2026-08-17). This test previously asserted that a click one tick
	 * later "is its own transaction — quantities must NOT sum", and it passed. The live client then
	 * showed that assertion describes a defect: two "Buy 10" clicks a tick apart emitted one click's
	 * qty against both clicks' gold plus a fabricated {@code unit_price_gp} of 1,132 (true ~755). The
	 * premise was wrong — a pending is only consumed by an inventory change, so an unresolved pending a
	 * tick later still has a {@code coinsBefore} that predates both transactions.
	 *
	 * <p>Kept, rewritten to assert the corrected contract at the boundary that actually matters: inside
	 * the resolution window the pending merges and is LABELLED; outside it the clicks stay independent.
	 * See {@code adjacentTickRepeatBuyMergesInsteadOfPairingOneQtyWithTwoClicksOfGold} and
	 * {@code aPendingOlderThanTheMergeWindowDoesNotMerge}.
	 */
	@Test
	public void clicksMergeInsideTheResolutionWindowAndAreIndependentOutsideIt()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);

		AccountConnectPlugin.StorePending inside = AccountConnectPlugin.mergeStorePending(
			first, "store_buy", COAL, 10, 999_000L, TICK + AccountConnectPlugin.STORE_PENDING_MAX_TICKS);
		assertTrue("still unresolved, so still one delta", inside.qtyMerged);
		assertEquals(20, inside.qty);
		assertEquals("the original pre-transaction reading", 1_000_000L, inside.coinsBefore);

		AccountConnectPlugin.StorePending outside = AccountConnectPlugin.mergeStorePending(
			first, "store_buy", COAL, 10, 999_000L,
			TICK + AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1);
		assertFalse("past the window the resolver would drop it anyway", outside.qtyMerged);
		assertFalse(outside.ambiguous);
		assertEquals("its own transaction — quantities must NOT sum", 10, outside.qty);
		assertEquals("and it uses its OWN coinsBefore", 999_000L, outside.coinsBefore);
	}

	/**
	 * A colour tag's own hex digits must never be read as a quantity. "Sell 10&lt;col=ff9040&gt;" scanned
	 * naively for a trailing digit run yields 9040 — a plausible-looking number, which is the failure
	 * shape this whole release is about. Tags are stripped before the quantity is read.
	 */
	@Test
	public void colourTagHexDigitsAreNeverMistakenForAQuantity()
	{
		assertEquals(10, AccountConnectPlugin.parseTrailingQty("Sell 10<col=ff9040>"));
		assertEquals("a tag containing digits, with no quantity at all", 1,
			AccountConnectPlugin.parseTrailingQty("Sell<col=ff9040>"));
		assertEquals("leading tag too", 10,
			AccountConnectPlugin.parseTrailingQty("<col=00ff00>Sell 10<col=ff9040>"));
	}

	@Test
	public void singleQuantityBuyIsUnchanged()
	{
		AccountConnectPlugin.StorePending p =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 1, 1_000_000L, TICK);
		assertFalse(p.ambiguous);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 999_900L, p.ambiguous);
		assertEquals(100L, fields.get("gp_total"));
		assertNull("no average unit price for a single item", fields.get("unit_price_gp"));
	}

	@Test
	public void wrongSignDeltaStillDegradesRatherThanEmittingNonsense()
	{
		// A buy whose coin count went UP cannot be that buy's delta — refuse it.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", COAL, 20, 1_000_000L, 1_005_000L, false);
		assertNull(fields.get("gp_total"));
	}

	// ------------------------------------------------------------------ FIELD-OBSERVED defects (2026-08-17)

	/**
	 * FIELD DEFECT 1 — every general-store SELL was logging qty 1.
	 *
	 * <p>Observed live on 2026-08-17 at the Varrock General Store: one "Sell 10" click moved ten items
	 * out of the inventory and 1,325 gp in, and the event reached production D1 as
	 * {@code {"item":22660,"qty":1,"gp_total":1325}} — a consumer dividing those gets 1,325 gp per item
	 * against a true 132.5, ten times over. Reproduced twice.
	 *
	 * <p>Cause: the client's SELL option string carries a colour tag the BUY string does not, so the
	 * trailing token is "10&lt;col=ff9040&gt;", which {@code Integer.parseInt} rejects and the catch
	 * silently defaults to 1. The pre-existing test asserted on the clean string "Sell 10", which the
	 * live client never sends — the assertion was true and the behaviour was still wrong.
	 *
	 * <p>The strings below are verbatim from the client's own MenuOptionClicked trace.
	 */
	@Test
	public void sellQuantityIsParsedFromTheColourTaggedOptionTheClientActuallySends()
	{
		assertEquals("verbatim from the live client trace", 10,
			AccountConnectPlugin.parseTrailingQty("Sell 10<col=ff9040>"));
		assertEquals(50, AccountConnectPlugin.parseTrailingQty("Sell 50<col=ff9040>"));
		assertEquals(5, AccountConnectPlugin.parseTrailingQty("Sell 5<col=ff9040>"));
		assertEquals(1, AccountConnectPlugin.parseTrailingQty("Sell 1<col=ff9040>"));
		// the buy strings are untagged and must keep working exactly as before
		assertEquals(10, AccountConnectPlugin.parseTrailingQty("Buy 10"));
		assertEquals(50, AccountConnectPlugin.parseTrailingQty("Buy 50"));
		assertEquals("no trailing number still means one", 1,
			AccountConnectPlugin.parseTrailingQty("Buy"));
		assertEquals("a tag with no number is still one", 1,
			AccountConnectPlugin.parseTrailingQty("Sell<col=ff9040>"));
	}

	/**
	 * FIELD DEFECT 2 — two clicks on ADJACENT ticks emitted one click's qty against both clicks' gold,
	 * and then derived a unit price from the mismatch.
	 *
	 * <p>Observed live on 2026-08-17: two rapid "Buy 10" clicks, fifteen packs received (the shop ran
	 * short), 11,325 gp spent. D1 got {@code qty:10, gp_total:11325, unit_price_gp:1132} with NO
	 * {@code qty_merged} flag — an exact-looking unit price against a true ~755, indistinguishable
	 * downstream from a genuinely correct single-click row. Reproduced twice.
	 *
	 * <p>Cause: the merge only fired on {@code prev.tick == tick}. One tick apart, {@code prev} was
	 * dropped and the new pending kept its own {@code coinsBefore} — but no inventory change had
	 * resolved yet, so that reading STILL predates both transactions. The same argument that justifies
	 * the same-tick merge applies to any unresolved pending: what makes {@code coinsBefore} usable is
	 * that nothing has been consumed, not that the clock agrees.
	 */
	@Test
	public void adjacentTickRepeatBuyMergesInsteadOfPairingOneQtyWithTwoClicksOfGold()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK + 1);

		assertTrue("an unresolved pending one tick back must still merge", merged.qtyMerged);
		assertEquals("quantities sum", 20, merged.qty);
		assertEquals("the ORIGINAL pre-transaction coin reading survives",
			1_000_000L, merged.coinsBefore);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_000L,
			merged.ambiguous, merged.qtyMerged);
		assertEquals("both clicks' gold", 2_000L, fields.get("gp_total"));
		assertNull("a merged qty may never produce a unit price", fields.get("unit_price_gp"));
	}

	/**
	 * The field defect's exact numbers, as the fixed code must now report them: two "Buy 10" clicks a
	 * tick apart that delivered fifteen items for 11,325 gp. The row must be LABELLED and must not
	 * carry the fabricated 1,132 unit price.
	 */
	@Test
	public void theFieldObservedAdjacentTickBuyNoLongerFabricatesAUnitPrice()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", 22660, 10, 26_233_393L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", 22660, 10, 26_227_000L, TICK + 1);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 26_222_068L,
			merged.ambiguous, merged.qtyMerged);

		assertEquals("the measured coin delta, unchanged", 11_325L, fields.get("gp_total"));
		assertEquals(Boolean.TRUE, fields.get("qty_merged"));
		assertNull("1132 gp/item was the fabrication this test exists to prevent",
			fields.get("unit_price_gp"));
	}

	/**
	 * The merge window must stay BOUNDED. Two clicks far apart are two separate transactions and the
	 * later one owns its own coin reading — merging them would attribute the first purchase's gold to
	 * the second.
	 */
	@Test
	public void aPendingOlderThanTheMergeWindowDoesNotMerge()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending second = AccountConnectPlugin.mergeStorePending(
			first, "store_buy", COAL, 10, 999_000L, TICK + AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1);

		assertFalse("too far apart to share one delta", second.qtyMerged);
		assertEquals("qty is this click's alone", 10, second.qty);
		assertEquals("and it uses its OWN coinsBefore", 999_000L, second.coinsBefore);
	}
}

package com.osrsbestinslot.export;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The visibility gate, exercised through the REAL RuneLite OverlayPanel render path against a real
 * Graphics2D. A unit test of the row builder cannot catch an overlay that draws in the wrong state,
 * and drawing over the game outside a shop is this feature's worst failure.
 */
public class StoreNearbyOverlayRenderTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final String ACCOUNT = "0";	// a mocked Client reports account 0

	/**
	 * A plugin with a linked token. storeToolsEnabled() requires BOTH the server grant and a linked
	 * token, so a config-less plugin cannot represent either state honestly.
	 */
	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		});
		return p;
	}

	/** The server's staff-capture grant for the logged-in account: the nearby panel reads players only under it. */
	private static void staff(AccountConnectPlugin p) throws Exception
	{
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("activeHash");
		f.setAccessible(true);
		f.set(p, ACCOUNT);
		p.setStaffCaptureForTest(TOKEN, ACCOUNT);
	}

	private static Graphics2D graphics()
	{
		BufferedImage img = new BufferedImage(400, 300, BufferedImage.TYPE_INT_ARGB);
		return img.createGraphics();
	}

	@Test
	public void drawsNothingWhileNoShopIsOpen() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(false);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		assertNull("overlay must not render outside a shop", overlay.render(graphics()));
	}

	@Test
	public void drawsWhileAShopIsOpen() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		// No client is injected, so the display reader returns empty — the panel must still draw
		// its title and the explicit "nobody nearby" line rather than vanishing.
		Dimension d = overlay.render(graphics());
		assertNotNull("overlay must render while a shop is open", d);
		// OverlayPanel clears its children at the END of render, so inspect what it BUILT. A panel
		// with only a title is indistinguishable from one whose data source silently broke — the
		// explicit empty-state line is what tells those apart, so assert it is actually produced.
		java.util.List<String[]> rows = StoreNearbyOverlay.visibleRows(plugin.nearbyPlayersForOverlay(6));
		org.junit.Assert.assertTrue("no client injected, so the row list must be empty", rows.isEmpty());
		// One line: the "Nobody nearby" heading. The reset countdown is its own overlay now.
		org.junit.Assert.assertEquals("empty-state heading only",
			1, overlay.builtRowCountForTest());
	}



	/**
	 * THE GATE. These overlays render other players' names, and they are granted only by the
	 * backend to an allowlisted token. A regular player must see nothing even inside a shop.
	 */
	@Test
	public void drawsNothingWhenTheServerHasNotGrantedStoreTools() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		// store tools deliberately NOT granted — this is every ordinary player's state
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		assertNull("ungranted tokens must see no overlay", overlay.render(graphics()));
	}

	/**
	 * THE DEV OVERRIDE IS OFF UNLESS A JVM FLAG SETS IT, and only the exact grant words count.
	 * A Hub build launched normally has no such property, so this can never leak to a player.
	 */
	@Test
	public void theDevOverrideIsOffWithoutTheFlagAndRefusesJunkValues() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		org.junit.Assert.assertFalse("no flag = no override",
			AccountConnectPlugin.storeToolsDevOverride());
		try
		{
			for (String bad : new String[]{"", " ", "off", "false", "0", "yes", "ON"})
			{
				System.setProperty("osrsbis.storetools", bad);
				org.junit.Assert.assertFalse("'" + bad + "' must not grant",
					AccountConnectPlugin.storeToolsDevOverride());
			}
			for (String good : new String[]{"on", "true", "1"})
			{
				System.setProperty("osrsbis.storetools", good);
				org.junit.Assert.assertTrue("'" + good + "' must grant",
					AccountConnectPlugin.storeToolsDevOverride());
			}
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	/** The override still requires a linked token — it bypasses the server, not the account. */
	@Test
	public void theDevOverrideStillRequiresALinkedToken() throws Exception
	{
		System.setProperty("osrsbis.storetools", "on");
		try
		{
			AccountConnectPlugin unlinked = new AccountConnectPlugin();
			java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
			f.setAccessible(true);
			f.set(unlinked, new AccountConnectConfig()
			{
				@Override
				public String linkToken()
				{
					return "";
				}
			});
			org.junit.Assert.assertFalse("no token = no overlays even with the flag",
				unlinked.storeToolsEnabled());
			org.junit.Assert.assertTrue("linked token + flag = granted", plugin().storeToolsEnabled());
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	@Test
	public void theGateDefaultsToOff() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		org.junit.Assert.assertFalse("store tools must default OFF", plugin.storeToolsEnabled());
	}

	@Test
	public void repeatedRendersDoNotAccumulateRows() throws Exception
	{
		// OverlayPanel clears its children between frames only when clearChildren is on. If it is
		// not, the panel grows one row per frame and covers the screen within seconds.
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		overlay.render(graphics());
		int afterFirst = overlay.getPanelComponent().getChildren().size();
		for (int i = 0; i < 20; i++)
		{
			overlay.render(graphics());
		}
		int afterMany = overlay.getPanelComponent().getChildren().size();
		org.junit.Assert.assertEquals("panel children grew across frames", afterFirst, afterMany);
	}
	@Test
	public void drawsNearbyPlayerFromClientInsteadOfAnAlwaysEmptyCaptureReader() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		staff(plugin);
		net.runelite.api.Client client = org.mockito.Mockito.mock(net.runelite.api.Client.class);
		net.runelite.api.Player self = org.mockito.Mockito.mock(net.runelite.api.Player.class);
		net.runelite.api.Player nearby = org.mockito.Mockito.mock(net.runelite.api.Player.class);
		org.mockito.Mockito.when(client.getLocalPlayer()).thenReturn(self);
		org.mockito.Mockito.when(self.getWorldLocation())
			.thenReturn(new net.runelite.api.coords.WorldPoint(3210, 3210, 0));
		org.mockito.Mockito.when(nearby.getName()).thenReturn("Near Player");
		org.mockito.Mockito.when(nearby.getWorldLocation())
			.thenReturn(new net.runelite.api.coords.WorldPoint(3211, 3210, 0));
		org.mockito.Mockito.when(nearby.getCombatLevel()).thenReturn(80);
		org.mockito.Mockito.when(client.getPlayers()).thenReturn(java.util.Arrays.asList(self, nearby));
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		f.set(plugin, client);

		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		Graphics2D g = graphics();
		try
		{
			assertNotNull(overlay.render(g));
			org.junit.Assert.assertEquals("heading plus the nearby player's row",
				2, overlay.builtRowCountForTest());
			plugin.setStaffCaptureForTest(null, null);
			assertNotNull(overlay.render(g));
			org.junit.Assert.assertEquals("store tools without the staff-capture grant show nobody",
				1, overlay.builtRowCountForTest());
			org.junit.Assert.assertTrue("and read no player for an upload",
				plugin.nearbyPlayersSnapshot(6).isEmpty());
		}
		finally
		{
			g.dispose();
		}
	}

	private static net.runelite.api.Player visiblePlayer(String name, int x, int y)
	{
		net.runelite.api.Player p = org.mockito.Mockito.mock(net.runelite.api.Player.class);
		org.mockito.Mockito.when(p.getName()).thenReturn(name);
		org.mockito.Mockito.when(p.getWorldLocation())
			.thenReturn(new net.runelite.api.coords.WorldPoint(x, y, 0));
		org.mockito.Mockito.when(p.getCombatLevel()).thenReturn(80);
		return p;
	}

	@Test
	public void displayReadsOnlyCurrentNearbyRowsAndKeepsCaptureReadersEmpty() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		staff(plugin);
		net.runelite.api.Client client = org.mockito.Mockito.mock(net.runelite.api.Client.class);
		net.runelite.api.Player self = visiblePlayer("Self", 3210, 3210);
		net.runelite.api.Player near = visiblePlayer("<col=ff0000>Near</col>", 3211, 3210);
		net.runelite.api.Player farther = visiblePlayer("Farther", 3214, 3210);
		net.runelite.api.Player far = visiblePlayer("Out of range", 3240, 3210);
		net.runelite.api.Player unnamed = visiblePlayer("", 3210, 3210);
		org.mockito.Mockito.when(client.getLocalPlayer()).thenReturn(self);
		org.mockito.Mockito.when(client.getPlayers()).thenReturn(
			java.util.Arrays.asList(far, farther, self, null, near, unnamed));
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		f.set(plugin, client);

		java.util.List<java.util.Map<String, Object>> rows = plugin.nearbyPlayersForOverlay(6);
		org.junit.Assert.assertEquals(2, rows.size());
		org.junit.Assert.assertEquals("Near", rows.get(0).get("rsn"));
		org.junit.Assert.assertEquals(1, rows.get(0).get("dist"));
		org.junit.Assert.assertEquals(80, rows.get(0).get("cb"));
		org.junit.Assert.assertEquals("Farther", rows.get(1).get("rsn"));
		org.junit.Assert.assertEquals(1, plugin.nearbyPlayersForOverlay(1).size());
		// The display reader itself never asks for animation or target: those belong to the staff upload readers.
		org.mockito.Mockito.verify(near, org.mockito.Mockito.never()).getAnimation();
		org.mockito.Mockito.verify(near, org.mockito.Mockito.never()).getInteracting();

		// Store tools without the staff-capture grant: the upload readers stay empty and read nothing.
		plugin.setStaffCaptureForTest(null, null);
		org.junit.Assert.assertTrue(plugin.nearbyPlayersForOverlay(6).isEmpty());
		org.junit.Assert.assertTrue(plugin.nearbyPlayersSnapshot(6, true).isEmpty());
		plugin.accumulateShopNearby();
		f = AccountConnectPlugin.class.getDeclaredField("shopVisitNearby");
		f.setAccessible(true);
		org.junit.Assert.assertTrue(((java.util.Map<?, ?>) f.get(plugin)).isEmpty());
		org.mockito.Mockito.verify(near, org.mockito.Mockito.never()).getAnimation();
		org.mockito.Mockito.verify(near, org.mockito.Mockito.never()).getInteracting();

		staff(plugin);
		org.mockito.Mockito.when(client.getPlayers()).thenReturn(java.util.Collections.singletonList(self));
		org.junit.Assert.assertTrue("leaving players must not remain in a display cache",
			plugin.nearbyPlayersForOverlay(6).isEmpty());
		org.mockito.Mockito.clearInvocations(client);
		plugin.setStoreToolsForTest(false);
		org.junit.Assert.assertTrue(plugin.nearbyPlayersForOverlay(6).isEmpty());
		plugin.setStoreToolsForTest(true);
		plugin.setShopOpenForTest(false);
		org.junit.Assert.assertTrue(plugin.nearbyPlayersForOverlay(6).isEmpty());
		org.mockito.Mockito.verify(client, org.mockito.Mockito.never()).getPlayers();
	}

}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The nearby panel's row selection. Covers what a wrong overlay would actually get wrong:
 * showing a player across the map, drawing a row with no name, or growing without bound.
 */
public class StoreNearbyOverlayTest
{
	private static Map<String, Object> player(String rsn, int dist, Integer cb)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("rsn", rsn);
		m.put("dist", dist);
		if (cb != null)
		{
			m.put("cb", cb);
		}
		return m;
	}

	@Test
	public void formatsNameDistanceAndCombat()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("Light Work G", 1, 114));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals(1, rows.size());
		assertEquals("Light Work G", rows.get(0)[0]);
		assertEquals("beside you  lvl 114", rows.get(0)[1]);
		assertEquals("1", rows.get(0)[2]);		// adjacent => highlighted gold
	}

	@Test
	public void pluralisesBeyondOneTile()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("Zezima", 4, 126));
		assertEquals("4 tiles  lvl 126", StoreNearbyOverlay.visibleRows(in).get(0)[1]);
		assertEquals("4", StoreNearbyOverlay.visibleRows(in).get(0)[2]);
	}

	@Test
	public void dropsPlayersBeyondDisplayRange()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("Close", StoreNearbyOverlay.DISPLAY_RANGE_TILES, 3));
		in.add(player("Far", StoreNearbyOverlay.DISPLAY_RANGE_TILES + 1, 3));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals(1, rows.size());
		assertEquals("Close", rows.get(0)[0]);
	}

	@Test
	public void skipsEntriesMissingNameOrDistance()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		Map<String, Object> noName = new LinkedHashMap<>();
		noName.put("dist", 2);
		in.add(noName);
		Map<String, Object> noDist = new LinkedHashMap<>();
		noDist.put("rsn", "Ghost");
		in.add(noDist);
		in.add(player("Real", 2, 50));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals(1, rows.size());
		assertEquals("Real", rows.get(0)[0]);
	}

	@Test
	public void omitsCombatLevelWhenAbsent()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("NoCb", 3, null));
		assertEquals("3 tiles", StoreNearbyOverlay.visibleRows(in).get(0)[1]);
	}

	@Test
	public void neverDrawsMoreRowsThanTheDisplayCap()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		for (int i = 0; i < StoreNearbyOverlay.DISPLAY_CAP + 10; i++)
		{
			in.add(player("P" + i, 2, 3));
		}
		assertEquals(StoreNearbyOverlay.DISPLAY_CAP, StoreNearbyOverlay.visibleRows(in).size());
	}



	@Test
	public void theAdjacentPlayerIsColouredDifferentlyFromTheRest()
	{
		java.awt.Color adjacent = StoreNearbyOverlay.distanceColor(1);
		java.awt.Color near = StoreNearbyOverlay.distanceColor(3);
		java.awt.Color far = StoreNearbyOverlay.distanceColor(12);
		org.junit.Assert.assertNotEquals("the adjacent player must stand out", adjacent, near);
		org.junit.Assert.assertNotEquals("far players must be dimmer", near, far);
	}

	/**
	 * A LONG RSN MUST NOT WRAP. Seen on the rig: `96pure2382` wrapped and its "9 tiles lvl 22" landed
	 * on the next line, so every row below it read against the wrong player. A truncated name is
	 * recoverable; a misaligned list is actively misleading about who is standing next to you.
	 */
	@Test
	public void longNamesAreTruncatedRatherThanAllowedToWrap()
	{
		String longest = "AAAAAAAAAAAAA";		// 13 chars — longer than any real RSN
		assertTrue(longest.length() > StoreNearbyOverlay.RSN_MAX_CHARS);
		String out = StoreNearbyOverlay.shortenRsn(longest);
		assertEquals(StoreNearbyOverlay.RSN_MAX_CHARS, out.length());
		assertTrue("truncation must be visible", out.endsWith("\u2026"));
	}

	/** Every REAL RSN fits: OSRS caps display names at 12 characters. */
	@Test
	public void everyRealRsnLengthSurvivesUntouched()
	{
		assertTrue("the cap must cover a full-length OSRS name",
			StoreNearbyOverlay.RSN_MAX_CHARS >= 12);
		assertEquals("Light Work G", StoreNearbyOverlay.shortenRsn("Light Work G"));
		assertEquals("96pure2382", StoreNearbyOverlay.shortenRsn("96pure2382"));
	}

	@Test
	public void namesThatFitAreLeftExactlyAsTheyAre()
	{
		// An RSN is an identity. Trimming one that fits would name the wrong player.
		String exact = "AAAAAAAAAAAA";		// exactly RSN_MAX_CHARS, and a real 12-char RSN
		assertEquals(StoreNearbyOverlay.RSN_MAX_CHARS, exact.length());
		assertEquals(exact, StoreNearbyOverlay.shortenRsn(exact));
		assertEquals("Zezima", StoreNearbyOverlay.shortenRsn("Zezima"));
		assertEquals("", StoreNearbyOverlay.shortenRsn(null));
	}

	@Test
	public void theRowBuilderAppliesTheTruncation()
	{
		java.util.List<java.util.Map<String, Object>> in = new ArrayList<>();
		in.add(player("ThisNameIsWayTooLong", 3, 50));
		String shown = StoreNearbyOverlay.visibleRows(in).get(0)[0];
		assertTrue("rows must carry the shortened name", shown.length() <= StoreNearbyOverlay.RSN_MAX_CHARS);
	}

	@Test
	public void emptyAndNullInputProduceNoRows()
	{
		assertTrue(StoreNearbyOverlay.visibleRows(new ArrayList<>()).isEmpty());
		assertTrue(StoreNearbyOverlay.visibleRows(null).isEmpty());
	}

	@Test
	public void preservesTheOrderItIsGiven()
	{
		// nearbyPlayersSnapshot sorts nearest-first; the panel must not reshuffle that.
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("A", 1, 3));
		in.add(player("B", 5, 3));
		in.add(player("C", 9, 3));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals("A", rows.get(0)[0]);
		assertEquals("B", rows.get(1)[0]);
		assertEquals("C", rows.get(2)[0]);
	}
}

package com.osrsbestinslot.export;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The standalone reset countdown. Split from the nearby panel because a list that changes height
 * moved the number around the screen — so the arms here are mostly about STAYING STILL.
 */
public class StoreResetOverlayTest
{
	private static Graphics2D graphics()
	{
		return new BufferedImage(400, 300, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	/**
	 * THE JITTER FIX. The overlay must draw exactly one row in every state, so its height can never
	 * change. This is the whole reason it is a separate overlay.
	 */
	@Test
	public void alwaysDrawsExactlyOneRowWhateverTheState() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);

		// phase unknown
		o.render(graphics());
		assertEquals("waiting state must be one row", 1, o.builtRowCountForTest());

		// phase known — drive the anchor through the real field
		java.lang.reflect.Field a = AccountConnectPlugin.class.getDeclaredField("storeResetAnchorMs");
		a.setAccessible(true);
		a.setLong(p, System.currentTimeMillis() - 30_000L);
		o.render(graphics());
		assertEquals("counting state must also be one row", 1, o.builtRowCountForTest());
	}

	@Test
	public void repeatedRendersDoNotAccumulateRows() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);
		for (int i = 0; i < 25; i++)
		{
			o.render(graphics());
		}
		assertEquals("the panel must not grow across frames", 1, o.builtRowCountForTest());
	}

	@Test
	public void drawsNothingOutsideAShopOrWithoutTheGrant() throws Exception
	{
		AccountConnectPlugin outside = plugin();
		outside.setStoreToolsForTest(true);
		assertNull("no shop, no overlay", new StoreResetOverlay(outside).render(graphics()));

		AccountConnectPlugin ungranted = plugin();
		ungranted.setShopOpenForTest(true);
		assertNull("no grant, no overlay", new StoreResetOverlay(ungranted).render(graphics()));
	}

	@Test
	public void drawsWhileAShopIsOpenAndGranted() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		Dimension d = new StoreResetOverlay(p).render(graphics());
		assertNotNull(d);
	}

	@Test
	public void theWaitingStateIsNamedAndNeutral() throws Exception
	{
		// A blank or red waiting state is the failure: blank looks broken, red is a standing
		// "do not hand off" warning on a shop that has never reset.
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);
		o.render(graphics());
		assertEquals("sell junk", o.lastTextForTest());
		org.junit.Assert.assertNotEquals("waiting must not look urgent",
			StoreResetOverlay.countdownColor(1), o.lastColorForTest());
	}

	@Test
	public void theCountdownRoundsUpAndNeverShowsZero()
	{
		assertEquals("sell junk", StoreResetOverlay.resetText(0));
		assertEquals("sell junk", StoreResetOverlay.resetText(-5));
		assertEquals("1s", StoreResetOverlay.resetText(1));
		assertEquals("rounds up", "1s", StoreResetOverlay.resetText(999));
		assertEquals("13s", StoreResetOverlay.resetText(12_500));
		assertEquals("60s", StoreResetOverlay.resetText(60_000));
	}

	@Test
	public void theColourBandsAreDistinctAndOrdered()
	{
		java.awt.Color safe = StoreResetOverlay.countdownColor(StoreResetOverlay.SAFE_SECONDS);
		java.awt.Color mid = StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS + 1);
		java.awt.Color urgent = StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS);
		org.junit.Assert.assertNotEquals(safe, mid);
		org.junit.Assert.assertNotEquals(mid, urgent);
		org.junit.Assert.assertNotEquals(safe, urgent);
		assertTrue("urgent reads red", urgent.getRed() > urgent.getGreen());
		assertTrue("safe reads green", safe.getGreen() > safe.getRed());
	}

	@Test
	public void theUrgentBandIsInclusiveOfItsBoundary()
	{
		assertEquals(StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS),
			StoreResetOverlay.countdownColor(1));
		org.junit.Assert.assertNotEquals(
			StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS),
			StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS + 1));
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The store reset clock (0.7.8).
 *
 * A general store cycles its stock on a fixed 60s clock. An item put into the shop vanishes at the
 * next tick of that clock, NOT 60s after it was sold — so an item sold 1s after a reset is gone in
 * 59s, and one sold at 58s is gone in 2. A seller currently feels this out by selling a junk item and
 * watching it disappear, which is a guess repeated by eye on every visit; measured over 56 real
 * sessions the gap between that probe and the first real item ran 5s to 146s.
 *
 * One observed reset fixes the PHASE, and every later reset follows from it while the shop stays
 * open (operator report, 2026-09-03). These arms hold the two properties that make the countdown safe to
 * trust: the arithmetic is a phase, not a per-item duration, and an UNKNOWN phase shows nothing
 * rather than a guess.
 */
public class StoreResetTimerTest
{
	private static final long P = 60_000L;

	// ---- phase arithmetic ----

	/**
	 * THE PROPERTY THE WHOLE FEATURE RESTS ON. Time remaining depends on where we are in the cycle,
	 * never on when an item was sold. A naive "60s from the sell" would pass a test that only ever
	 * measured from the anchor, so measure from three different offsets instead.
	 */
	@Test
	public void countdownIsAPhaseNotAPerItemDuration()
	{
		long anchor = 1_000_000L;
		assertEquals("1s after a reset -> 59s left", 59_000L, AccountConnectPlugin.msUntilNextReset(anchor, anchor + 1_000L));
		assertEquals("30s in -> 30s left", 30_000L, AccountConnectPlugin.msUntilNextReset(anchor, anchor + 30_000L));
		assertEquals("58s in -> 2s left", 2_000L, AccountConnectPlugin.msUntilNextReset(anchor, anchor + 58_000L));
	}

	/** The anchor keeps working across later cycles — one probe pins the phase for the whole visit. */
	@Test
	public void oneAnchorSurvivesManyCycles()
	{
		long anchor = 5_000_000L;
		assertEquals("into the 5th cycle, 40s elapsed", 20_000L,
			AccountConnectPlugin.msUntilNextReset(anchor, anchor + (4 * P) + 40_000L));
		assertEquals("an hour later the phase still holds", 45_000L,
			AccountConnectPlugin.msUntilNextReset(anchor, anchor + (60 * P) + 15_000L));
	}

	/** Landing exactly on a tick means a FULL period remains — never 0, which means "unknown". */
	@Test
	public void exactTickYieldsAFullPeriodNotZero()
	{
		long anchor = 2_000_000L;
		assertEquals(P, AccountConnectPlugin.msUntilNextReset(anchor, anchor));
		assertEquals(P, AccountConnectPlugin.msUntilNextReset(anchor, anchor + P));
		assertEquals(P, AccountConnectPlugin.msUntilNextReset(anchor, anchor + (7 * P)));
	}

	/**
	 * DEGENERATE ARMS. An unknown phase must return the "show nothing" sentinel rather than a plausible
	 * number — a confidently wrong countdown is worse than no countdown, because the user would push a
	 * high-value item into a window that has already closed.
	 */
	@Test
	public void unknownPhaseShowsNothing()
	{
		assertEquals("no anchor yet", 0L, AccountConnectPlugin.msUntilNextReset(0L, 9_999_999L));
		assertEquals("negative anchor is not an anchor", 0L, AccountConnectPlugin.msUntilNextReset(-1L, 9_999_999L));
		assertEquals("clock went backwards", 0L, AccountConnectPlugin.msUntilNextReset(5_000L, 4_000L));
		assertFalse(AccountConnectPlugin.resetPhaseKnown(0L));
		assertTrue(AccountConnectPlugin.resetPhaseKnown(1L));
	}

	// ---- anchor detection ----




	/**
	 * THE PROBE IS FIXED AT THE FIRST SELL AND NEVER RE-ARMED.
	 *
	 * If each sell overwrote the probe, the high-value merchandise would become the probe and the
	 * customer's purchase would anchor the clock — precisely the defect this model exists to avoid.
	 * Drives the REAL sell path rather than injecting the field, because the bug lives in that branch.
	 * (Mutation-found 2026-09-03: relaxing the `storeProbeItem == 0` guard survived every other arm.)
	 */
	@Test
	public void theProbeIsFixedAtTheFirstSellAndNotReArmed() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		inject(plugin, "shopOpen", true);
		net.runelite.api.Client client = org.mockito.Mockito.mock(net.runelite.api.Client.class);
		inject(plugin, "client", client);

		plugin.onMenuOptionClicked(sellClick(111));	// junk probe first
		plugin.onMenuOptionClicked(sellClick(999));	// then the merchandise

		assertEquals("the probe must remain the FIRST item sold", 111, probeItem(plugin));
	}




	/**
	 * THE COUNTDOWN MUST COME BACK FOR THE NEXT CYCLE WITHOUT A NEW OBSERVATION.
	 *
	 * RuneLite's Timer infobox removes ITSELF at zero, so one observed reset buys exactly one 60s
	 * countdown. The phase is still known, so the tick handler re-arms it. Without this the timer
	 * shows once and disappears — half of the live "not working" report on 2026-09-03.
	 *
	 * This asserts the re-arm CONDITION on the real fields, not a mock InfoBoxManager: showResetTimer
	 * needs an injected manager, and the decision being tested is the guard, not the drawing.
	 */
	@Test
	public void theTickReArmsTheCountdownWhenThePhaseIsKnownAndNoTimerIsUp() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		inject(plugin, "shopOpen", true);
		inject(plugin, "storeResetAnchorMs", System.currentTimeMillis());
		inject(plugin, "infoBoxManager", null);		// no manager: showResetTimer is a safe no-op
		inject(plugin, "resetTimer", null);		// the state after a Timer removed itself

		plugin.onGameTick(new net.runelite.api.events.GameTick());

		// The guard ran and reached showResetTimer, which returned early with no manager. What this
		// arm pins is that the tick path is REACHED at all — deleting the re-arm block, or negating
		// any of its three conditions, changes the reachability asserted below.
		assertTrue("phase must still be known after the tick", plugin.resetPhaseKnownForTest());
		assertTrue("the tick must have attempted a re-arm", plugin.reArmAttemptsForTest() > 0);
	}

	/** No re-arm while a countdown is already showing — that would restart it every tick. */
	@Test
	public void theTickDoesNotReArmWhileACountdownIsAlreadyUp() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		inject(plugin, "shopOpen", true);
		inject(plugin, "storeResetAnchorMs", System.currentTimeMillis());
		inject(plugin, "resetTimer", org.mockito.Mockito.mock(
			net.runelite.client.ui.overlay.infobox.Timer.class));

		plugin.onGameTick(new net.runelite.api.events.GameTick());

		assertEquals("must not re-arm over a live countdown", 0, plugin.reArmAttemptsForTest());
	}

	/** No re-arm outside a shop, and none while the phase is unknown. */
	@Test
	public void theTickDoesNotReArmOutsideAShopOrWithAnUnknownPhase() throws Exception
	{
		AccountConnectPlugin outside = plugin();
		inject(outside, "shopOpen", false);
		inject(outside, "storeResetAnchorMs", System.currentTimeMillis());
		outside.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals("no re-arm outside a shop", 0, outside.reArmAttemptsForTest());

		AccountConnectPlugin unknown = plugin();
		inject(unknown, "shopOpen", true);
		inject(unknown, "storeResetAnchorMs", 0L);
		unknown.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals("no re-arm with an unknown phase", 0, unknown.reArmAttemptsForTest());
	}

	// ---- anchor 1: THE ITEM WE SOLD VANISHING (measured live 2026-09-03) ----
	//
	// This is the event the user watches. A junk item the shop does NOT natively stock is sold in, and
	// for it to disappear. Measured: player-added item 1191 decayed 5->4->3->...->0, every step
	// exactly 60.0s apart, and left the shop at zero. Selling a Pot into Varrock GS — where a Pot IS
	// default stock — raised it 5->6 and the shop normalised it back to 5 in 1.2-5.4 SECONDS, which
	// is not the cycle at all. ZERO is the discriminator between those two.

	@Test
	public void theItemWeSoldReachingZeroAnchorsTheClock() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		// The probe is seeded because the REAL sell path sets it: 1191 is the first item sold this
		// visit, so it IS the probe. The old fixture left storeProbeItem at 0, which no live visit
		// ever does. The assertion below is unchanged.
		seedVisitWithProbe(plugin, 1191, new int[][]{{1191, 1}});	// our junk, one left
		long before = System.currentTimeMillis();

		plugin.handleShopStockChanged(shop(new int[][]{{550, 5}}));	// 1191 gone entirely

		assertTrue("the sold item vanishing must anchor", anchor(plugin) >= before);
	}

	/**
	 * A FALL TO A NON-ZERO NUMBER IS NOT THE TICK. This is the exact shape that produced 72-second
	 * "cycles" drifting 36s/24s/12s from the truth: the shop absorbing its own default stock a few
	 * seconds after a sell. If this arm goes green with a naive "stock fell" rule, the countdown is
	 * confidently wrong again.
	 */
	@Test
	public void theShopAbsorbingItsOwnDefaultStockDoesNotAnchor() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1931, 6}});		// a Pot sold in, above the default of 5

		plugin.handleShopStockChanged(shop(new int[][]{{1931, 5}}));	// normalised, NOT gone

		assertEquals("6->5 is the shop normalising, not a tick", 0L, anchor(plugin));
	}

	/**
	 * A MULTI-ITEM DELIVERY MUST NOT RE-ANCHOR ON THE MERCHANDISE.
	 *
	 * Reported from the field by Snaauz, 2026-09-19: "if we're delivering more than 1 item, the timer
	 * messes up, it resets as soon as the first item is bought from the store."
	 *
	 * The visit sells a junk probe first, then the merchandise. A customer buying the merchandise out
	 * takes its stock to zero, which is NOT a store tick — it is a purchase, and it happens at an
	 * arbitrary moment in the cycle. Anchoring there throws the phase away and restarts the countdown
	 * from the wrong place, so every later number is wrong for the rest of the visit.
	 *
	 * Only the PROBE reaching zero is the tick. storeProbeItem already records which item that is.
	 */
	@Test
	public void aCustomerBuyingOutTheMerchandiseDoesNotAnchor() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisitWithProbe(plugin, 111, new int[][]{{111, 1}, {999, 3}});	// probe + merchandise

		plugin.handleShopStockChanged(shop(new int[][]{{111, 1}}));	// 999 bought out, probe still there

		assertEquals("a customer clearing the merchandise is not a store tick", 0L, anchor(plugin));
	}

	/** The probe reaching zero still anchors while merchandise sits in the shop beside it. */
	@Test
	public void theProbeReachingZeroStillAnchorsInAMultiItemVisit() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisitWithProbe(plugin, 111, new int[][]{{111, 1}, {999, 3}});
		long before = System.currentTimeMillis();

		plugin.handleShopStockChanged(shop(new int[][]{{999, 3}}));	// probe gone, merchandise untouched

		assertTrue("the probe vanishing is still the tick", anchor(plugin) >= before);
	}

	/**
	 * A visit with NO probe recorded must not anchor off any sold item at all.
	 *
	 * The degenerate arm: storeProbeItem is 0 until the first sell lands.
	 *
	 * ⚠ THIS ARM IS WEAK AND SAYS SO. Mutation-checked 2026-09-20: replacing the
	 * `storeProbeItem != 0` guard with `true` leaves it GREEN, because handleShopStockChanged only
	 * ever records ids above zero, so a lookup of id 0 returns 0 and the `had > 0` test fails anyway.
	 * The guard is therefore belt-and-braces rather than load-bearing. It is kept because it states
	 * the intent at the branch, and this arm is kept because it pins the degenerate state, but
	 * neither should be read as proof that the guard is what stops the anchor.
	 */
	@Test
	public void noProbeRecordedMeansNoAnchorFromAVanishingItem() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisitWithProbe(plugin, 0, new int[][]{{999, 3}});		// stock present, probe never set

		plugin.handleShopStockChanged(shop(new int[][]{{550, 5}}));	// 999 gone

		assertEquals("no probe means no tick can be read from a vanishing item", 0L, anchor(plugin));
	}

	@Test
	public void anItemWeDidNotSellVanishingDoesNotAnchor() throws Exception
	{
		// Another player's stock reaching zero is a real tick, but we cannot tell it from a customer
		// clearing the last of a stack. Only OUR OWN sold item is unambiguous.
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1191, 1}});
		Field f = AccountConnectPlugin.class.getDeclaredField("shopStock");
		f.setAccessible(true);
		@SuppressWarnings("unchecked")
		Map<Integer, Integer> st = (Map<Integer, Integer>) f.get(plugin);
		st.put(9999, 1);			// present in stock, never sold by us

		plugin.handleShopStockChanged(shop(new int[][]{{1191, 1}}));	// 9999 vanished, ours did not

		assertEquals("only our own sold item may anchor", 0L, anchor(plugin));
	}

	@Test
	public void anItemThatWasNeverInStockCannotVanish() throws Exception
	{
		// had == 0 must not read as a fall to zero. Otherwise every item we ever sold anchors the
		// clock on every single container change, forever.
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1191, 0}});

		plugin.handleShopStockChanged(shop(new int[][]{{550, 5}}));

		assertEquals("0->0 is not a disappearance", 0L, anchor(plugin));
	}

	// ---- anchor detection: PERIODICITY (measured live 2026-09-03) ----
	//
	// Two models were refuted by live measurement before this one. Anchoring on "the junk item we
	// sold vanished" gave 72s cycles drifting 36s/24s/12s from the truth, because a shop's default
	// stock normalises 0.6-2.4s after a sell on its own schedule. Anchoring on "a rise and a fall
	// together" refused all five ticks in a five-minute observation, because a full shop has
	// nothing to restock and every tick was fall-only. The PERIOD held at 60.0s every time.

	@Test
	public void twoChangesOnePeriodApartAnchorTheClock()
	{
		long t = 1_000_000L;
		assertTrue(AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L));
	}

	@Test
	public void theToleranceCoversRealJitterAndNoMore()
	{
		long t = 1_000_000L;
		long tol = AccountConnectPlugin.PERIOD_TOLERANCE_MS;
		assertTrue("at the edge, inside", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L + tol));
		assertTrue("at the edge, early", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L - tol));
		assertFalse("one ms past the edge", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L + tol + 1));
		assertFalse("one ms early past the edge", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L - tol - 1));
	}

	@Test
	public void ordinaryShopTrafficDoesNotAnchor()
	{
		// Real gaps measured between non-tick changes: a buy 9s after the last change, a sell 15s,
		// an absorption 2s. None may lock the clock.
		long t = 1_000_000L;
		for (long gap : new long[]{600L, 1_800L, 2_400L, 9_000L, 15_000L, 30_000L, 45_000L, 120_000L})
		{
			assertFalse("a " + gap + "ms gap must not anchor",
				AccountConnectPlugin.isPeriodAgreement(t, t + gap));
		}
	}

	/**
	 * DEGENERATE ARMS. Each passes a naive check while proving nothing, and each would anchor the
	 * clock on a non-event.
	 */
	@Test
	public void theFirstChangeOfAVisitCannotAnchor()
	{
		// With no previous change there is nothing to be periodic WITH. Opening a shop, or the very
		// first stock reading, must leave the clock unknown rather than anchoring to that instant.
		assertFalse(AccountConnectPlugin.isPeriodAgreement(0L, 1_000_000L));
		assertFalse(AccountConnectPlugin.isPeriodAgreement(-1L, 1_000_000L));
	}

	@Test
	public void aClockGoingBackwardsNeverAnchors()
	{
		assertFalse(AccountConnectPlugin.isPeriodAgreement(2_000_000L, 1_000_000L));
		assertFalse("identical timestamps are not a period",
			AccountConnectPlugin.isPeriodAgreement(1_000_000L, 1_000_000L));
	}

	@Test
	public void twoPeriodsIsNotOnePeriod()
	{
		// A tick MISSED (the shop unchanged for a whole cycle) lands 120s later. Treating that as
		// agreement would be right by luck here and wrong whenever the gap is any other multiple.
		long t = 1_000_000L;
		assertFalse(AccountConnectPlugin.isPeriodAgreement(t, t + 120_000L));
		assertFalse(AccountConnectPlugin.isPeriodAgreement(t, t + 180_000L));
	}

	/** The real container path: two changes one period apart anchor; nothing else does. */
	@Test
	public void theContainerPathAnchorsOnlyOnPeriodAgreement() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		inject(plugin, "shopOpen", true);
		inject(plugin, "shopStock", new java.util.LinkedHashMap<Integer, Integer>());
		inject(plugin, "soldThisVisit", new java.util.LinkedHashSet<Integer>());

		// First reading of the visit — establishes the baseline, must not anchor.
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 10}, {1191, 2}}));
		assertEquals("the first reading must not anchor", 0L, anchor(plugin));

		// A change — records the time, still nothing to be periodic with.
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 9}, {1191, 1}}));
		assertEquals("one change is not a period", 0L, anchor(plugin));

		// A change one period later. Drive the clock through the field rather than sleeping 60s.
		inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 8}, {1191, 1}}));
		assertTrue("two changes one period apart must anchor", anchor(plugin) > 0);
	}

	@Test
	public void anUnchangedContainerIsNotAChangeAtAll() throws Exception
	{
		// The shop container fires on events that leave the stock identical. Counting those as
		// changes would reset the periodicity chain constantly and stop the clock ever locking.
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		inject(plugin, "shopOpen", true);
		inject(plugin, "shopStock", new java.util.LinkedHashMap<Integer, Integer>());
		inject(plugin, "soldThisVisit", new java.util.LinkedHashSet<Integer>());
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 10}}));

		long marker = System.currentTimeMillis() - 60_000L;
		inject(plugin, "lastStockChangeMs", marker);
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 10}}));	// identical
		Field f = AccountConnectPlugin.class.getDeclaredField("lastStockChangeMs");
		f.setAccessible(true);
		assertEquals("an unchanged read must not touch the chain", marker, f.getLong(plugin));
		assertEquals("and must not anchor", 0L, anchor(plugin));
	}

	private static net.runelite.api.events.MenuOptionClicked sellClick(int itemId)
	{
		net.runelite.api.events.MenuOptionClicked e =
			org.mockito.Mockito.mock(net.runelite.api.events.MenuOptionClicked.class);
		org.mockito.Mockito.when(e.getMenuOption()).thenReturn("Sell 1");
		org.mockito.Mockito.when(e.getItemId()).thenReturn(itemId);
		return e;
	}

	private static int probeItem(AccountConnectPlugin p) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("storeProbeItem");
		f.setAccessible(true);
		return f.getInt(p);
	}


	// ---- infobox lifecycle: a countdown left on screen is the obvious failure of this feature ----

	/**
	 * Every exit path must remove the box. RuneLite does NOT clear a plugin's infoboxes for it, so a
	 * missed teardown leaves a stale countdown ticking against a shop that is no longer open — exactly
	 * the "confidently wrong number" this feature exists to replace.
	 */
	@Test
	public void everyExitPathRemovesTheTimer() throws Exception
	{
		for (String path : new String[]{"shutdown", "hop", "logout", "connection-lost"})
		{
			AccountConnectPlugin plugin = plugin();
			java.util.List<Object> boxes = new java.util.ArrayList<>();
			installInfoBoxManager(plugin, boxes);
			plugin.setStoreToolsForTest(true);	// the countdown is gated
			seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
			inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
			plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));	// period -> box
			assertEquals(path + ": a reset should show the countdown", 1, boxes.size());

			switch (path)
			{
				case "shutdown":
					plugin.shutDown();
					break;
				default:
					net.runelite.api.events.GameStateChanged ev = new net.runelite.api.events.GameStateChanged();
					ev.setGameState("hop".equals(path) ? net.runelite.api.GameState.HOPPING
						: "logout".equals(path) ? net.runelite.api.GameState.LOGIN_SCREEN
						: net.runelite.api.GameState.CONNECTION_LOST);
					plugin.onGameStateChanged(ev);
					break;
			}
			assertEquals(path + ": the countdown must be removed", 0, boxes.size());
			assertEquals(path + ": the phase must be dropped too", 0L, anchor(plugin));
		}
	}

	/** Repeated resets replace the box rather than stacking a new one every minute. */
	@Test
	public void repeatedResetsDoNotAccumulateBoxes() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		java.util.List<Object> boxes = new java.util.ArrayList<>();
		installInfoBoxManager(plugin, boxes);
		plugin.setStoreToolsForTest(true);	// the countdown is gated
		for (int i = 0; i < 4; i++)
		{
			seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
			inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
			plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));
		}
		assertEquals("four resets must leave exactly one box", 1, boxes.size());
	}

	/**
	 * THE COUNTDOWN IS GATED TOO, not only the panel. Both surfaces render from the same
	 * gated feature, so an ungranted token must get neither.
	 */
	@Test
	public void anUngrantedTokenGetsNoCountdown() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		java.util.List<Object> boxes = new java.util.ArrayList<>();
		installInfoBoxManager(plugin, boxes);
		// store tools deliberately NOT granted
		seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
		inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);

		plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));	// a real tick

		assertEquals("an ungranted token must see no countdown", 0, boxes.size());
		assertTrue("but the phase is still tracked for when it IS granted", anchor(plugin) > 0);
	}

	/** Revoking the grant mid-session must clear a countdown that is already on screen. */
	@Test
	public void revokingTheGrantRemovesALiveCountdown() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		java.util.List<Object> boxes = new java.util.ArrayList<>();
		installInfoBoxManager(plugin, boxes);
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
		inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
		plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));
		assertEquals("granted: countdown shows", 1, boxes.size());

		plugin.applyServerPolicy(policyResponse("off"));

		assertEquals("revoked: countdown must be cleared", 0, boxes.size());
	}

	/** A 200 with the grant header present turns the feature on for this token. */
	@Test
	public void theServerHeaderGrantsAndRevokesTheFeature() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		assertFalse("default is OFF", plugin.storeToolsEnabled());
		plugin.applyServerPolicy(policyResponse("on"));
		assertTrue("header on grants the feature", plugin.storeToolsEnabled());
		plugin.applyServerPolicy(policyResponse("off"));
		assertFalse("header off revokes it", plugin.storeToolsEnabled());
	}

	/** Anything that is not an explicit grant word must leave the feature OFF. */
	@Test
	public void unrecognisedHeaderValuesDoNotGrantTheFeature() throws Exception
	{
		for (String v : new String[]{"", " ", "maybe", "allow", "yes", "2", "OFF"})
		{
			AccountConnectPlugin plugin = plugin();
			plugin.applyServerPolicy(policyResponse(v));
			assertFalse("'" + v + "' must not grant store tools", plugin.storeToolsEnabled());
		}
	}

	/** A response with NO header must not change a grant that is already in force. */
	@Test
	public void anAbsentHeaderLeavesTheCurrentGrantAlone() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.applyServerPolicy(policyResponse("on"));
		assertTrue(plugin.storeToolsEnabled());
		plugin.applyServerPolicy(policyResponse(null));		// header omitted entirely
		assertTrue("an absent header must not silently revoke", plugin.storeToolsEnabled());
	}

	/** Build a 200 carrying (or omitting) the X-Store-Tools header. */
	private static okhttp3.Response policyResponse(String storeTools)
	{
		okhttp3.Response.Builder b = new okhttp3.Response.Builder()
			.request(new okhttp3.Request.Builder().url("https://example.invalid/x").build())
			.protocol(okhttp3.Protocol.HTTP_1_1)
			.code(200)
			.message("OK");
		if (storeTools != null)
		{
			b.header("X-Store-Tools", storeTools);
		}
		return b.build();
	}

	/** A real InfoBoxManager whose add/remove we can observe. */
	private static void installInfoBoxManager(AccountConnectPlugin plugin, java.util.List<Object> boxes) throws Exception
	{
		net.runelite.client.ui.overlay.infobox.InfoBoxManager m =
			org.mockito.Mockito.mock(net.runelite.client.ui.overlay.infobox.InfoBoxManager.class);
		org.mockito.Mockito.doAnswer(inv -> { boxes.add(inv.getArgument(0)); return null; })
			.when(m).addInfoBox(org.mockito.Mockito.any());
		org.mockito.Mockito.doAnswer(inv -> { boxes.remove(inv.getArgument(0)); return null; })
			.when(m).removeInfoBox(org.mockito.Mockito.any());
		inject(plugin, "infoBoxManager", m);
	}

	// ---- helpers ----

	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	/** Seed a visit AND pin which item was the junk probe (the first thing sold). */
	private static void seedVisitWithProbe(AccountConnectPlugin p, int probe, int[][] stock) throws Exception
	{
		seedVisit(p, stock);
		inject(p, "storeProbeItem", probe);
	}

	/** Put the plugin in a shop visit that has sold the given {item, qty} pairs into the shop. */
	private static void seedVisit(AccountConnectPlugin p, int[][] stock) throws Exception
	{
		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		java.util.Map<Integer, Integer> base = new java.util.LinkedHashMap<>();
		for (int[] pair : stock)
		{
			sold.add(pair[0]);
			base.put(pair[0], pair[1]);
		}
		inject(p, "soldThisVisit", sold);
		inject(p, "shopStock", base);
	}

	/** net.runelite.api.Item is FINAL and cannot be mocked — build real ones. */
	private static net.runelite.api.ItemContainer shop(int[][] pairs)
	{
		net.runelite.api.ItemContainer c = org.mockito.Mockito.mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] items = new net.runelite.api.Item[pairs.length];
		for (int i = 0; i < pairs.length; i++)
		{
			items[i] = new net.runelite.api.Item(pairs[i][0], pairs[i][1]);
		}
		org.mockito.Mockito.when(c.getItems()).thenReturn(items);
		return c;
	}

	private static long anchor(AccountConnectPlugin p) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("storeResetAnchorMs");
		f.setAccessible(true);
		return f.getLong(p);
	}

	private static void inject(AccountConnectPlugin plugin, String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Before;
import org.junit.Test;

/**
 * Two different items bought in one tick (2026-09-26, Torva full helm + amulet of fury). The single store
 * pending slot kept only the last click, so the fury got one store_buy without gp_total and the helm got no
 * event at all. Each item now has its own pending, driven here through the real click and inventory events.
 */
public class StoreSameTickItemsTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int COINS = 995;
	private static final int HELM = 26382;
	private static final int FURY = 6585;

	private AccountConnectPlugin plugin;
	private Client client;
	private int tick = 100;
	private Item[] inventory;

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		});
		client = mock(Client.class);
		when(client.getTickCount()).thenAnswer(i -> tick);
		ItemContainer inv = mock(ItemContainer.class);
		when(inv.getItems()).thenAnswer(i -> inventory);
		when(client.getItemContainer(any(InventoryID.class))).thenReturn(inv);
		inject("client", client);
		inject("shopOpen", true);
		inventory = new Item[]{new Item(COINS, 300_000_000)};
	}

	private void inject(String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private void buy(int item)
	{
		MenuOptionClicked click = mock(MenuOptionClicked.class);
		when(click.getMenuOption()).thenReturn("Buy 1");
		when(click.getItemId()).thenReturn(item);
		plugin.onMenuOptionClicked(click);
	}

	/** The server's inventory update: these items and this coin count. */
	private void inventoryNow(long coins, int... items)
	{
		List<Item> rows = new ArrayList<>();
		rows.add(new Item(COINS, (int) coins));
		for (int item : items) rows.add(new Item(item, 1));
		inventory = rows.toArray(new Item[0]);
		ItemContainer changed = client.getItemContainer(InventoryID.INVENTORY);
		plugin.onItemContainerChanged(new ItemContainerChanged(net.runelite.api.gameval.InventoryID.INV, changed));
	}

	private List<Map<String, Object>> storeBuys()
	{
		return plugin.pendingEvents.stream().filter(e -> "store_buy".equals(e.get("type"))).collect(Collectors.toList());
	}

	@Test
	public void twoItemsInOneInventoryUpdateGiveTwoEventsAndNoGuessedPrice()
	{
		buy(HELM);
		buy(FURY);					// same tick
		tick++;
		inventoryNow(300_000_000L - 216_042_420L - 2_846_161L, HELM, FURY);

		List<Map<String, Object>> buys = storeBuys();
		assertEquals("one store_buy per item", 2, buys.size());
		assertEquals(HELM, buys.get(0).get("item"));
		assertEquals(FURY, buys.get(1).get("item"));
		for (Map<String, Object> e : buys)
		{
			assertEquals(1, e.get("qty"));
			assertFalse("one coin change cannot be split between two items", e.containsKey("gp_total"));
		}
		assertEquals(0, plugin.storePendings.size());
	}

	@Test
	public void twoItemsInSeparateInventoryUpdatesEachGetTheirOwnGpTotal()
	{
		buy(HELM);
		buy(FURY);					// same tick
		tick++;
		inventoryNow(300_000_000L - 216_042_420L, HELM);
		inventoryNow(300_000_000L - 216_042_420L - 2_846_161L, HELM, FURY);

		List<Map<String, Object>> buys = storeBuys();
		assertEquals(2, buys.size());
		assertEquals(HELM, buys.get(0).get("item"));
		assertEquals(216_042_420L, buys.get(0).get("gp_total"));
		assertEquals(FURY, buys.get(1).get("item"));
		assertEquals("the fury's own coins, not the helm's as well", 2_846_161L, buys.get(1).get("gp_total"));
	}

	@Test
	public void aClickThatNeverExecutesExpiresWithoutBlockingTheOtherItem()
	{
		buy(HELM);
		buy(FURY);					// the fury buy fails: out of stock
		tick++;
		inventoryNow(300_000_000L - 216_042_420L, HELM);
		tick += AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1;
		inventoryNow(300_000_000L - 216_042_420L - 10L, HELM);	// an unrelated later change

		List<Map<String, Object>> buys = storeBuys();
		assertEquals(1, buys.size());
		assertEquals(216_042_420L, buys.get(0).get("gp_total"));
		assertEquals(0, plugin.storePendings.size());
	}

	@Test
	public void shopCloseReportsEveryArmedItem() throws Exception
	{
		buy(HELM);
		buy(FURY);
		plugin.flushStorePendingOnShopClose();
		assertEquals(2, storeBuys().size());
	}
}

package com.osrsbestinslot.export;

import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * THE GATE, as one place. These overlays render other players' names on screen, so the
 * question "could an ordinary player ever see this?" must have exactly one answer: no.
 *
 * Three independent conditions, ALL required: a linked token, the backend grant, and an open shop.
 * The grant itself is server-derived from the RSN allowlist and cannot be self-issued —
 * tests/e3a/store-tools-gate.test.mjs holds that half.
 */
public class StoreToolsGateTest
{
	private static java.awt.Graphics2D g()
	{
		return new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	private static AccountConnectPlugin withToken(String token) throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return token;
			}
		});
		return p;
	}

	@Test
	public void aFreshPluginGrantsNothing() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		assertFalse("default must be closed", withToken("0123456789abcdef0123456789abcdef").storeToolsEnabled());
	}

	/** No token means no account is linked at all — the grant cannot apply to anybody. */
	@Test
	public void noLinkedTokenMeansNoOverlaysEvenWithTheGrant() throws Exception
	{
		for (String bad : new String[]{"", "   ", "not-a-token", "0123456789abcdef"})
		{
			AccountConnectPlugin p = withToken(bad);
			p.setStoreToolsForTest(true);
			assertFalse("token '" + bad + "' must not enable store tools", p.storeToolsEnabled());
		}
	}

	/** BOTH overlays must obey the gate. One of them leaking is the whole failure. */
	@Test
	public void neitherOverlayDrawsWithoutTheGrant() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setShopOpenForTest(true);		// shop open, grant withheld
		assertNull("reset overlay must stay hidden", new StoreResetOverlay(p).render(g()));
		assertNull("nearby overlay must stay hidden", new StoreNearbyOverlay(p).render(g()));
	}

	/** And with the grant, both draw — otherwise the gate is just "always off". */
	@Test
	public void bothOverlaysDrawWhenGrantedInsideAShop() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		org.junit.Assert.assertNotNull(new StoreResetOverlay(p).render(g()));
		org.junit.Assert.assertNotNull(new StoreNearbyOverlay(p).render(g()));
	}

	/** Outside a shop, a granted account still sees nothing. */
	@Test
	public void theGrantDoesNotFollowTheUserOutOfTheShop() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setStoreToolsForTest(true);		// granted, but no shop open
		assertNull(new StoreResetOverlay(p).render(g()));
		assertNull(new StoreNearbyOverlay(p).render(g()));
	}

	/**
	 * THE SHIPPED BUILD HAS NO LOCAL WAY IN. The dev override is a JVM system property, which the
	 * Plugin Hub launcher never sets — but a config item or an env read WOULD be reachable by a
	 * player, so assert the override's shape rather than trusting the comment above it.
	 */
	@Test
	public void theOverrideIsAJvmPropertyAndNothingElse() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		assertFalse(AccountConnectPlugin.storeToolsDevOverride());
		try
		{
			System.setProperty("osrsbis.storetools", "on");
			assertTrue(AccountConnectPlugin.storeToolsDevOverride());
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
		// A player-reachable surface would be a config key. There must be none.
		for (java.lang.reflect.Method m : AccountConnectConfig.class.getMethods())
		{
			assertFalse("config must expose no store-tools switch: " + m.getName(),
				m.getName().toLowerCase().contains("storetool"));
		}
	}

	/** A server revoke mid-session closes the gate immediately. */
	@Test
	public void aRevokeClosesTheGate() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setStoreToolsForTest(true);
		p.setShopOpenForTest(true);
		assertTrue(p.storeToolsEnabled());
		p.setStoreToolsForTest(false);
		assertFalse("revoke must take effect at once", p.storeToolsEnabled());
		assertNull(new StoreNearbyOverlay(p).render(g()));
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The store visit clip keeps every sale, not the last 12 seconds.
 *
 * Field defect, Arengees 2026-09-25: sells 16:37:59-16:39:51, uploaded frames 16:39:55-16:40:06, every
 * frame static. The old ring kept the NEWEST 360 frames (12s at 30fps), so any visit that ran more
 * than 12 seconds past its last sale uploaded no sale at all.
 *
 * Known-bad control: replacing StoreVisitClip's keep policy with "keep every frame, evict the oldest"
 * (the old ring) turns everySaleOfALongVisitIsInTheUpload RED.
 */
public class StoreVisitClipTest
{
	/** Measured mean frame size at 704px / q0.55 (StoreClipCaptureTest pins the width). */
	private static final int FRAME_BYTES = 30 * 1024;
	private static final long FRAME_MS = 1000L / AccountConnectPlugin.CLIP_FPS;

	private static StoreVisitClip visit()
	{
		return new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES);
	}

	/** Drive a visit: a frame every 1/30s from 0 to closeMs, a moment at each sale time. */
	private static StoreVisitClip.Snapshot run(StoreVisitClip v, long closeMs, long... sales)
	{
		int next = 0;
		for (long t = 0; t <= closeMs; t += FRAME_MS)
		{
			while (next < sales.length && sales[next] <= t)
			{
				v.onMoment(sales[next]);
				next++;
			}
			v.offer(new byte[FRAME_BYTES], t);
		}
		return v.snapshot();
	}

	private static int framesBetween(StoreVisitClip.Snapshot s, long from, long to)
	{
		int n = 0;
		for (long t : s.capturedAtMillis)
		{
			if (t >= from && t <= to)
			{
				n++;
			}
		}
		return n;
	}

	private static void assertWithinBudget(StoreVisitClip v, StoreVisitClip.Snapshot s)
	{
		assertTrue("frame budget exceeded: " + s.frames.size(),
			s.frames.size() <= AccountConnectPlugin.MAX_CLIP_FRAMES);
		long bytes = 0;
		for (byte[] f : s.frames)
		{
			bytes += f.length;
		}
		assertTrue("byte budget exceeded: " + bytes, bytes <= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("byteSize must match the snapshot", bytes, v.byteSize());
		for (int i = 1; i < s.capturedAtMillis.size(); i++)
		{
			assertTrue("frames must be in capture order",
				s.capturedAtMillis.get(i - 1) <= s.capturedAtMillis.get(i));
		}
	}

	/** Every sale shows the click and the change after it: frames before and after the click. */
	private static void assertSaleVisible(StoreVisitClip.Snapshot s, long sale, int minAfter)
	{
		int after = framesBetween(s, sale, sale + StoreVisitClip.CORE_AFTER_MILLIS);
		assertTrue("sale at " + sale + "ms has only " + after + " frames in the 1.2s after the click",
			after >= minAfter);
		if (sale > 0)
		{
			assertTrue("sale at " + sale + "ms has no frame in the 0.5s before the click",
				framesBetween(s, sale - StoreVisitClip.CORE_BEFORE_MILLIS, sale - 1) >= 1);
		}
	}

	/** The brief's case: sales at 0s, 60s and 110s, shop closed at 125s. */
	@Test
	public void everySaleOfALongVisitIsInTheUpload()
	{
		StoreVisitClip v = visit();
		long[] sales = {0L, 60_000L, 110_000L};
		StoreVisitClip.Snapshot s = run(v, 125_000L, sales);

		assertWithinBudget(v, s);
		for (long sale : sales)
		{
			// 1.2s at 30fps is 36 frames; at least half must survive the budget.
			assertSaleVisible(s, sale, 18);
		}
		// The gaps between sales are not blank: the baseline shows the tile in between.
		assertTrue("the middle of the visit must have baseline frames",
			framesBetween(s, 20_000L, 50_000L) >= 10);
		// The visit start is in the clip.
		assertTrue("the visit start must be in the clip", s.capturedAtMillis.get(0) <= 1_000L);
		// And the old failure is gone: the clip does not start in the last 12 seconds.
		assertTrue("the clip must not be just the last 12 seconds",
			s.capturedAtMillis.get(0) < 125_000L - 12_000L);
	}

	/** A 2-minute visit with nothing sold: start plus 1fps baseline, well inside the budget. */
	@Test
	public void aTwoMinuteIdleVisitStaysWithinBudget()
	{
		StoreVisitClip v = visit();
		StoreVisitClip.Snapshot s = run(v, 120_000L);

		assertWithinBudget(v, s);
		assertEquals("no moments were marked", 0, v.momentCount());
		// 2s start at 30fps (60) + one baseline frame a second for the other ~118s.
		assertTrue("idle visit should be about 180 frames, got " + s.frames.size(),
			s.frames.size() >= 170 && s.frames.size() <= 185);
		assertTrue("the pre-roll held for lookbehind stays bounded to 2s at 30fps",
			v.preRollSize() <= 61);
	}

	/** Twenty sales spaced out over a long visit: the cap holds and every sale is still shown. */
	@Test
	public void twentySpacedSalesStayInsideTheCapAndAllAreShown()
	{
		StoreVisitClip v = visit();
		long[] sales = new long[20];
		for (int i = 0; i < 20; i++)
		{
			sales[i] = 5_000L + i * 7_000L;
		}
		StoreVisitClip.Snapshot s = run(v, 150_000L, sales);

		assertWithinBudget(v, s);
		assertEquals("the frame cap must be reached, not exceeded",
			AccountConnectPlugin.MAX_CLIP_FRAMES, s.frames.size());
		for (long sale : sales)
		{
			assertSaleVisible(s, sale, 3);
		}
	}

	/** Twenty rapid sells one second apart (a multi-item delivery): every click is still covered. */
	@Test
	public void twentyRapidSalesAreAllShown()
	{
		StoreVisitClip v = visit();
		long[] sales = new long[20];
		for (int i = 0; i < 20; i++)
		{
			sales[i] = 10_000L + i * 1_000L;
		}
		StoreVisitClip.Snapshot s = run(v, 90_000L, sales);

		assertWithinBudget(v, s);
		for (long sale : sales)
		{
			assertSaleVisible(s, sale, 3);
		}
		assertTrue("the visit start survives many sales", s.capturedAtMillis.get(0) <= 2_000L);
	}

	/** The byte cap binds too: frames larger than the measured mean still keep every sale. */
	/**
	 * PIO-014: the GS video budget is 16 MiB. A full 360-frame visit at 44 KB/frame (~15.8 MB, the
	 * current quality at a busy scene) keeps every frame, both in the visit selector and in the final
	 * upload selection. Under the old 12MB budget about a quarter of these frames were cut.
	 */
	@Test
	public void aFullVisitAt44KbPerFrameKeepsAll360Frames()
	{
		StoreVisitClip v = visit();
		long[] sales = {2_000L, 5_000L, 8_000L, 11_000L};	// windows cover the whole 12 s
		int next = 0;
		int offered = 0;
		for (long t = 0; offered < AccountConnectPlugin.MAX_CLIP_FRAMES; t += FRAME_MS)
		{
			while (next < sales.length && sales[next] <= t)
			{
				v.onMoment(sales[next++]);
			}
			v.offer(new byte[44_000], t);
			offered++;
		}
		StoreVisitClip.Snapshot s = v.snapshot();
		assertEquals("every frame of a 360-frame visit at 44 KB is kept", 360, s.frames.size());
		assertWithinBudget(v, s);
		assertEquals(360, AccountConnectPlugin.selectStoreClipFrames(s.frames, AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_FRAME_BYTES, AccountConnectPlugin.MAX_CLIP_BURST_BYTES).size());
		assertEquals("the retry budget is two visits (32 MiB)", 32L * 1024 * 1024, AccountConnectPlugin.CLIP_RETRY_BYTE_BUDGET);
	}

	@Test
	public void theByteCapIsRespectedWithLargeFrames()
	{
		StoreVisitClip v = new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES);
		long[] sales = {3_000L, 40_000L, 80_000L};
		int next = 0;
		for (long t = 0; t <= 100_000L; t += FRAME_MS)
		{
			while (next < sales.length && sales[next] <= t)
			{
				v.onMoment(sales[next++]);
			}
			v.offer(new byte[100_000], t);	// 100KB: the byte cap (16 MiB = 167 frames) binds first
		}
		StoreVisitClip.Snapshot s = v.snapshot();
		assertTrue("16 MiB cap", v.byteSize() <= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertTrue("bytes cap bound the frame count", s.frames.size() <= 167);
		for (long sale : sales)
		{
			assertSaleVisible(s, sale, 3);
		}
	}

	/** Frames that fail to encode or exceed the per-frame cap are never kept. */
	@Test
	public void emptyAndOversizedFramesAreIgnored()
	{
		StoreVisitClip v = visit();
		v.offer(null, 0L);
		v.offer(new byte[0], 10L);
		v.offer(new byte[AccountConnectPlugin.MAX_CLIP_FRAME_BYTES + 1], 20L);
		assertEquals(0, v.size());
		v.offer(new byte[10], 30L);
		assertEquals(1, v.size());
	}

	/**
	 * WIRING: a real Sell click during a capturing visit marks a moment on the visit clip. Without
	 * this call the clip falls back to start + baseline and the sale is only seen by chance.
	 */
	@Test
	public void aSellClickMarksAMomentOnTheVisitClip() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() { });
		inject(plugin, "client", org.mockito.Mockito.mock(net.runelite.api.Client.class));
		StoreVisitClip v = visit();
		inject(plugin, "clipVisit", v);
		inject(plugin, "clipCapturing", true);
		inject(plugin, "shopOpen", true);

		net.runelite.api.events.MenuOptionClicked sell =
			org.mockito.Mockito.mock(net.runelite.api.events.MenuOptionClicked.class);
		org.mockito.Mockito.when(sell.getMenuOption()).thenReturn("Sell 1");
		org.mockito.Mockito.when(sell.getItemId()).thenReturn(1511);
		plugin.onMenuOptionClicked(sell);

		assertEquals("the sell click must mark one moment", 1, v.momentCount());
		assertTrue("and still flag the visit for upload", plugin.storeTxThisVisit);

		// Outside a capturing visit nothing is marked.
		inject(plugin, "clipCapturing", false);
		plugin.onMenuOptionClicked(sell);
		assertEquals(1, v.momentCount());
	}

	/** The uploader stamps each chunk with its OWN first frame's capture time, not a derived one. */
	@Test
	public void chunksAreStampedWithTheirFirstFramesRealCaptureTime()
	{
		StoreVisitClip v = visit();
		StoreVisitClip.Snapshot s = run(v, 125_000L, 0L, 60_000L, 110_000L);
		List<Integer> idx = AccountConnectPlugin.selectStoreClipFrameIndexes(s.frames,
			AccountConnectPlugin.MAX_CLIP_FRAMES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("the visit clip is already inside the budget, so nothing is trimmed",
			s.frames.size(), idx.size());
		int chunks = (idx.size() + AccountConnectPlugin.CLIP_CHUNK_FRAMES - 1) / AccountConnectPlugin.CLIP_CHUNK_FRAMES;
		assertTrue("a full visit is still at most 9 chunks of 40", chunks <= 9);
		long prev = -1;
		for (int off = 0; off < idx.size(); off += AccountConnectPlugin.CLIP_CHUNK_FRAMES)
		{
			// captured_at goes on the wire in whole SECONDS and the collector orders chunks on it, so
			// two chunks sharing a second would be ordered by a random burst id. 40 frames at 30fps
			// span at least 1.3s, so the seconds must strictly increase.
			long atSec = s.capturedAtMillis.get(idx.get(off)) / 1000L;
			assertTrue("chunk captured_at seconds must strictly increase", atSec > prev);
			prev = atSec;
		}
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/** Staff-visible outcomes driven through RuneLite's real registration and event dispatch. */
public class StoreWorkflowRegressionTest
{
    private static final String TOKEN = "0123456789abcdef0123456789abcdef";
    private static final String ACCOUNT = "12345";
    @Rule public TemporaryFolder temp = new TemporaryFolder();
    private final AccountConnectPlugin plugin = new AccountConnectPlugin();
    private final Client client = mock(Client.class);
    private final OverlayManager manager = mock(OverlayManager.class);
    private final List<Overlay> registered = new ArrayList<>();
    private final List<Throwable> failures = new ArrayList<>();
    private final EventBus bus = new EventBus(failures::add);
    private String token = TOKEN;
    private String oldHome;
    private Graphics2D graphics;
    private StoreNearbyOverlay nearby;
    private StoreResetOverlay reset;
    private Player self;

    private static void inject(Object target, String field, Object value) throws Exception
    {
        Field f = AccountConnectPlugin.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    @Before public void start() throws Exception
    {
        oldHome = System.getProperty("user.home");
        System.setProperty("user.home", temp.getRoot().getAbsolutePath());
        graphics = new BufferedImage(600, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
        inject(plugin, "config", new AccountConnectConfig()
        {
            @Override public String linkToken() { return token; }
            @Override public String apiBaseUrl() { return "http://localhost/never-networked"; }
        });
        inject(plugin, "client", client);
        inject(plugin, "gson", new Gson());
        inject(plugin, "overlayManager", manager);
        inject(plugin, "drawManager", mock(net.runelite.client.ui.DrawManager.class));
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getTickCount()).thenReturn(100);
        when(client.getWorld()).thenReturn(301);
        when(client.getWorldType()).thenReturn(java.util.EnumSet.noneOf(net.runelite.api.WorldType.class));
        inject(plugin, "itemManager", mock(net.runelite.client.game.ItemManager.class));
        // Keep network outside this UI workflow; production handlers and snapshot construction still run.
        okhttp3.OkHttpClient http = mock(okhttp3.OkHttpClient.class);
        okhttp3.Call httpCall = mock(okhttp3.Call.class);
        when(http.newCall(any(Request.class))).thenReturn(httpCall);
        inject(plugin, "okHttpClient", http);
        self = player("Self", 3210);
        when(client.getLocalPlayer()).thenReturn(self);
        when(client.getPlayers()).thenReturn(Collections.singletonList(self));
        ItemContainer inventory = mock(ItemContainer.class);
        when(inventory.getItems()).thenReturn(new Item[]{new Item(995, 1000), new Item(1191, 2), new Item(999, 1)});
        when(client.getItemContainer(net.runelite.api.InventoryID.INVENTORY)).thenReturn(inventory);
        doAnswer(call -> { registered.add(call.getArgument(0)); return true; }).when(manager).add(any(Overlay.class));
        doAnswer(call -> { registered.remove(call.getArgument(0)); return true; }).when(manager).remove(any(Overlay.class));
        inject(plugin, "activeHash", ACCOUNT);
        when(client.getAccountHash()).thenReturn(Long.parseLong(ACCOUNT));
        plugin.staffApiBase = "http://localhost/never-networked";	// this rig's stand-in for osrsbestinslot.com
        bus.register(plugin);
        plugin.startUp();
        captureRegisteredOverlays();
    }

    private void captureRegisteredOverlays()
    {
        assertEquals("startup must register both visible staff tools", 2, registered.size());
        nearby = (StoreNearbyOverlay) registered.stream().filter(o -> o instanceof StoreNearbyOverlay).findFirst().orElse(null);
        reset = (StoreResetOverlay) registered.stream().filter(o -> o instanceof StoreResetOverlay).findFirst().orElse(null);
        assertNotNull("nearby overlay missing from OverlayManager", nearby);
        assertNotNull("countdown missing from OverlayManager", reset);
    }

    @After public void stop()
    {
        try
        {
            bus.unregister(plugin);
            plugin.pendingEvents.clear();
            plugin.shutDown();
            assertTrue("shutdown left staff overlays registered", registered.isEmpty());
            if (!failures.isEmpty()) throw new AssertionError("RuneLite subscriber threw", failures.get(0));
        }
        finally
        {
            if (graphics != null) graphics.dispose();
            if (oldHome != null) System.setProperty("user.home", oldHome);
        }
    }

    private static Player player(String name, int x)
    {
        Player p = mock(Player.class);
        when(p.getName()).thenReturn(name);
        when(p.getWorldLocation()).thenReturn(new WorldPoint(x, 3210, 0));
        when(p.getCombatLevel()).thenReturn(80);
        return p;
    }

    private void post(Object event)
    {
        bus.post(event);
        if (!failures.isEmpty()) throw new AssertionError("RuneLite subscriber threw", failures.get(0));
    }

    private void policy(String value, String sentToken)
    {
        Response response = new Response.Builder().request(new Request.Builder().url("http://localhost/never-networked/account-ingest").build())
            .protocol(Protocol.HTTP_1_1).code(200).message("OK").header("X-Store-Tools", value)
            // The server names a staff account only for an approved staff token; "off" withdraws both.
            .header("X-Staff-Capture", value).header("X-Staff-Account", "on".equals(value) ? ACCOUNT : "").build();
        plugin.applyServerPolicy(response, sentToken);
    }

    private void open()
    {
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        WidgetLoaded event = new WidgetLoaded();
        event.setGroupId(InterfaceID.SHOPMAIN);
        post(event);
    }

    private void sell(int itemId)
    {
        net.runelite.api.MenuEntry entry = mock(net.runelite.api.MenuEntry.class);
        when(entry.getOption()).thenReturn("Sell 1<col=ff9040>");
        when(entry.getItemId()).thenReturn(itemId);
        // EventBus dispatches by exact class: post a real event, not a Mockito subclass.
        post(new MenuOptionClicked(entry));
    }

    private void stock(Item... items)
    {
        ItemContainer container = mock(ItemContainer.class);
        when(container.getItems()).thenReturn(items);
        post(new ItemContainerChanged(InventoryID.GENERALSHOP1, container));
    }

    private void assertHidden()
    {
        assertNull("nearby panel visible outside an active granted visit", nearby.render(graphics));
        assertNull("countdown visible outside an active granted visit", reset.render(graphics));
    }

    private void assertUnknown()
    {
        assertNotNull(reset.render(graphics));
        assertEquals("new visit must require a fresh probe", "sell junk", reset.lastTextForTest());
    }

    private void observeProbeReset()
    {
        sell(1191);
        stock(new Item(1191, 1));
        stock();
        assertNotNull("observed stock reset must render a countdown", reset.render(graphics));
        String text = reset.lastTextForTest();
        assertTrue("actual sell/container events never reached the visible timer: " + text, text.matches("[0-9]+s"));
        int seconds = Integer.parseInt(text.substring(0, text.length() - 1));
        assertTrue("countdown outside the store's 60-second cycle", seconds >= 1 && seconds <= 60);
    }

    @Test public void startupPolicyAndShopEventsReachLiveNearbyRowsAndCloseBothPanels()
    {
        assertHidden();
        open();
        assertHidden();
        policy("on", token);
        Player visitor = player("Visitor", 3211);
        when(client.getPlayers()).thenReturn(Arrays.asList(self, visitor));
        assertNotNull(nearby.render(graphics));
        assertEquals("registered overlay must read actual Client players", 2, nearby.builtRowCountForTest());
        assertUnknown();
        when(client.getPlayers()).thenReturn(Collections.singletonList(self));
        assertNotNull(nearby.render(graphics));
        assertEquals("departed players must disappear on the next frame", 1, nearby.builtRowCountForTest());
        post(new WidgetClosed(InterfaceID.SHOPMAIN, 0, true));
        assertHidden();
    }

    @Test public void realSellAndStockEventsDriveCountdownWithoutReanchoringOnMerchandise() throws Exception
    {
        policy("on", token);
        open();
        assertUnknown();
        observeProbeReset();
        Field anchor = AccountConnectPlugin.class.getDeclaredField("storeResetAnchorMs");
        anchor.setAccessible(true);
        long observed = anchor.getLong(plugin);
        sell(999);
        stock(new Item(999, 1));
        stock();
        assertEquals("a customer's merchandise purchase must not reset the clock", observed, anchor.getLong(plugin));
        post(new WidgetClosed(InterfaceID.SHOPMAIN, 0, true));
        assertHidden();
        open();
        assertUnknown();
    }

    @Test public void sessionLossHidesPanelsEvenWhenRuneLiteNeverSendsWidgetClosed()
    {
        policy("on", token);
        for (GameState state : new GameState[]{GameState.HOPPING, GameState.LOGIN_SCREEN,
            GameState.CONNECTION_LOST, GameState.LOGGING_IN})
        {
            open();
            observeProbeReset();
            GameStateChanged event = new GameStateChanged();
            event.setGameState(state);
            when(client.getGameState()).thenReturn(state);
            post(event);
            assertHidden();
            open();
            assertUnknown();
        }
    }

    @Test public void revokedUnlinkedAndStalePolicyResponsesCannotShowPanels()
    {
        open();
        policy("on", token);
        assertNotNull(nearby.render(graphics));
        policy("off", token);
        assertHidden();
        token = "abcdef0123456789abcdef0123456789";
        policy("on", TOKEN);
        assertHidden();
        policy("on", token);
        assertNotNull(nearby.render(graphics));
        token = "";
        assertHidden();
    }

    @Test public void disableAndReenableRequiresANewShopVisit()
    {
        policy("on", token);
        open();
        observeProbeReset();
        plugin.pendingEvents.clear();
        plugin.shutDown();
        assertTrue("disable must remove both registered overlays", registered.isEmpty());
        plugin.startUp();
        captureRegisteredOverlays();
        assertHidden();
        open();
        assertUnknown();
    }
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

/**
 * Regression guards for the two HIGH defects found by the 0.7.4 adversarial review. Both were
 * introduced BY 0.7.4 and neither was covered by the release's own tests — the suite was green while
 * both were live, which is why these exist.
 */
public class TradeLeakAndFlushWedgeTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int TRADE_MAIN_GROUP_ID = 335;

	private AccountConnectPlugin plugin;

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
	}

	private void inject(String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private Object get(String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private void configWith(String apiBaseUrl) throws Exception
	{
		AccountConnectConfig config = mock(AccountConnectConfig.class);
		when(config.linkToken()).thenReturn(TOKEN);
		when(config.apiBaseUrl()).thenReturn(apiBaseUrl);
		inject("config", config);
	}

	// ============================================================ FINDING 1 — cross-trade leak

	/**
	 * A trade that ends WITHOUT acceptance must not leak its counterparty or received items into the
	 * next trade's event.
	 *
	 * <p>The leak path: a decline routes through handleTradeChat, which early-returns when trade
	 * screenshots are off — the DEFAULT — so resetTradeState() never runs. handleTradeWidgetClosed only
	 * resets when tradeArmed, which is set at confirm-load with screenshots ON, so a trade abandoned at
	 * the first screen never arms either. 0.7.4's last-non-empty-wins poll then PRESERVES the stale
	 * items past a next partner who offers nothing — the classic gold-delivery shape — producing
	 * {@code counterparty=Alice, received=[Bob's item]}.
	 *
	 * <p>0.7.3 could not do this: it assigned the pendings unconditionally at confirm, so every trade
	 * overwrote the last. The fix clears them at 335-load, the one point guaranteed to run per trade.
	 */
	@Test
	public void a335LoadClearsStalePendingsFromAnAbandonedTrade() throws Exception
	{
		configWith("https://example.invalid/api");

		// Trade 1 with Bob ended without acceptance — pendings survive in the real leak scenario.
		List<Map<String, Object>> bobsOffer = new ArrayList<>();
		Map<String, Object> bandos = new LinkedHashMap<>();
		bandos.put("id", 11832);
		bandos.put("qty", 1);
		bobsOffer.add(bandos);
		inject("pendingCounterparty", "Bob");
		inject("pendingTradeReceived", bobsOffer);
		inject("pendingReceivedText", "Bandos chestplate x 1");

		// Trade 2 opens. The 335-load must wipe Bob's residue before any polling happens.
		plugin.handleActivityWidgetLoaded(TRADE_MAIN_GROUP_ID);

		assertNull("counterparty from the abandoned trade must not survive", get("pendingCounterparty"));
		assertNull("received items must not survive — this is the field the release exists to fix",
			get("pendingTradeReceived"));
		assertNull("the text fallback must not survive either", get("pendingReceivedText"));
		assertTrue("polling must still be armed for the new trade", plugin.tradeMainOpen);
	}

	@Test
	public void repeatedAbandonedTradesNeverAccumulateResidue() throws Exception
	{
		configWith("https://example.invalid/api");
		for (int i = 0; i < 3; i++)
		{
			inject("pendingCounterparty", "Ghost" + i);
			List<Map<String, Object>> junk = new ArrayList<>();
			Map<String, Object> it = new LinkedHashMap<>();
			it.put("id", 4151 + i);
			it.put("qty", 1);
			junk.add(it);
			inject("pendingTradeReceived", junk);

			plugin.handleActivityWidgetLoaded(TRADE_MAIN_GROUP_ID);

			assertNull("each new trade starts clean", get("pendingCounterparty"));
			assertNull(get("pendingTradeReceived"));
		}
	}

	// ============================================================ FINDING 2 — permanent flush wedge

	/**
	 * A throw between draining the buffer and enqueueing the request must not lose the batch, and must
	 * NEVER leave delivery permanently wedged.
	 *
	 * <p>{@code apiBaseUrl} is user-editable and {@code Request.Builder.url()} throws
	 * IllegalArgumentException on a malformed value — a pasted non-URL is enough. Before the guard, that
	 * threw AFTER the buffer was cleared and {@code eventPostInFlight} set, so the batch was lost and
	 * every later flush early-returned forever, silently, with no further log lines. 0.7.3 recovered as
	 * soon as the user fixed the typo; unguarded 0.7.4 would stay dead until a plugin restart.
	 */
	@Test
	public void aMalformedApiUrlRequeuesTheBatchAndDoesNotWedgeDelivery() throws Exception
	{
		configWith("not a url at all");

		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", "trade");
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}

		plugin.flushEvents();	// must not propagate

		synchronized (plugin.pendingEvents)
		{
			assertEquals("the batch must be preserved, not destroyed by the throw",
				1, plugin.pendingEvents.size());
		}
		assertFalse("the in-flight flag MUST be cleared, or every later flush early-returns forever",
			plugin.eventPostInFlight);
		assertTrue("the failure must arm the backoff like any other", plugin.eventRetryBackoffUntilMs > 0);
	}

	/**
	 * The recovery half: after the user CORRECTS the URL, delivery must resume. This is the difference
	 * between a transient config typo and a session-long silent outage.
	 */
	@Test
	public void deliveryResumesOnceTheUrlIsCorrected() throws Exception
	{
		configWith("not a url at all");
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", "trade");
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}
		plugin.flushEvents();
		assertFalse(plugin.eventPostInFlight);

		// User fixes the config; the next tick must actually attempt a send rather than early-return.
		configWith("http://127.0.0.1:1/api");	// refused connection, but a VALID url
		plugin.eventRetryBackoffUntilMs = 0L;
		plugin.flushEvents();

		// The batch left the buffer (a real attempt happened) or came back via onFailure — either way
		// the flag must not be stuck true, which is what "wedged" means.
		Thread.sleep(500);
		assertFalse("delivery must not be permanently wedged after a corrected config",
			plugin.eventPostInFlight);
	}
}

package com.osrsbestinslot.export;

