	@Test
	public void deathDefersThenCarriesLocationAndKind() throws Exception
	{
		// Deferred model: ActorDeath arms a pending (reads pre-death inv+equip live) and emits NOTHING; the
		// death event with location + death_kind is emitted once the containers settle (syncTask) or on logout.
		// This mock is a SAFE death (no wilderness varbit / pvp world), so it carries NO items_lost — a safe death
		// is a gp-sink reclaim, not an inter-account transfer, and its diff would be polluted by post-death eating.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		WorldPoint wp = new WorldPoint(3200, 3200, 0);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(wp);
		inject(plugin, "client", client);

		// ActorDeath is a final class -> construct directly with the (mockable) player as the dead actor.
		plugin.onActorDeath(new ActorDeath((Actor) player));
		assertTrue("death emit is deferred to the settle/logout resolve", plugin.pendingEvents.isEmpty());

		plugin.resolveDeathPending(new LinkedHashMap<>(), true); // settle-window path
		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("death", e.get("type"));
		assertEquals("safe", e.get("death_kind")); // no wilderness varbit / pvp world in the mock
		assertFalse("safe death carries no items_lost (not a transfer)", e.containsKey("items_lost"));
		@SuppressWarnings("unchecked")
		Map<String, Object> loc = (Map<String, Object>) e.get("location");
		assertEquals(wp.getRegionID(), loc.get("region_id"));
		assertEquals(0, loc.get("plane"));
	}

	private static boolean getBool(AccountConnectPlugin plugin, String fieldName) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		return f.getBoolean(plugin);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Wave 3 firehose: high-frequency rows buffered and emitted as ONE fh_batch event.
 *
 * THE GRANT IS SERVER-SIDE AND THERE IS NO CONFIG ITEM. The original commit gated this on a
 * `maximumCapture` toggle in the plugin's own settings. The operator default (2026-09-19) is that this
 * plugin carries no user-facing settings, so the gate moved onto the X-Max-Capture response header,
 * exactly like the existing X-Store-Tools grant. These tests pin that an ungranted client captures
 * nothing at all, which is the property that keeps other players' names off every ordinary client.
 */
public class Wave3FirehoseTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	// 0.7.14 removed the enableUpload switch: uploadAllowed() is the link token alone, so the config
	// here only carries a token.
	private static AccountConnectConfig config(final String token)
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return token;
			}
		};
	}

	/** A plugin with a linked token. The firehose grant is still OFF until the server sets it. */
	private static AccountConnectPlugin plug() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", config(TOKEN));
		return p;
	}

	private static Map<String, Object> row(String k, Object v)
	{
		Map<String, Object> d = new LinkedHashMap<>();
		d.put(k, v);
		return d;
	}

	@Test
	public void ungrantedClientBuffersNothing() throws Exception
	{
		AccountConnectPlugin p = plug();
		assertTrue("no grant = not capturing", !p.maxCapture());
		p.firehose("pos", row("x", 3200));
		p.firehose("nearby", row("rsn", "Someone Else"));
		p.flushFirehose();
		assertTrue("an ungranted client emits nothing at all", p.pendingEvents.isEmpty());
	}

	@Test
	public void grantedPublicClientStillEmitsNothing() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.serverMaxCaptureEnabled = true;
		p.firehose("pos", row("x", 3200));
		p.firehose("pos", row("x", 3201));
		p.firehose("anim", row("id", 829));
		assertTrue("buffered, not emitted per row", p.pendingEvents.isEmpty());
		p.flushFirehose();
		assertTrue("public grants cannot emit firehose rows", p.pendingEvents.isEmpty());
	}

	@Test
	public void publicFirehoseDoesNotAccumulateRows() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.serverMaxCaptureEnabled = true;
		for (int i = 0; i < 600; i++)
		{
			p.firehose("pos", row("x", i));
		}
		p.flushFirehose();
		assertTrue("no firehose rows enter the public buffer", p.pendingEvents.isEmpty());
	}

	@Test
	public void flushOnAnEmptyBufferEmitsNothing() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.serverMaxCaptureEnabled = true;
		p.flushFirehose();
		assertTrue("an empty flush is not an empty batch event", p.pendingEvents.isEmpty());
	}

	@Test
	public void grantAloneIsNotEnoughWithAMalformedToken() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", config("not-a-token"));	// uploadAllowed() is false
		p.serverMaxCaptureEnabled = true;		// server granted anyway
		assertTrue("a malformed token beats a server grant", !p.maxCapture());
		p.firehose("pos", row("x", 3200));
		p.flushFirehose();
		assertTrue(p.pendingEvents.isEmpty());
	}

	@Test
	public void grantAloneIsNotEnoughWithoutALinkedToken() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", config(""));
		p.serverMaxCaptureEnabled = true;
		assertTrue("no token beats a server grant", !p.maxCapture());
		p.firehose("pos", row("x", 3200));
		p.flushFirehose();
		assertTrue(p.pendingEvents.isEmpty());
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * WAVE 4 — structured loot events. All four loot classes were javap-verified present in client 1.12.32;
 * we consume ServerNpcLoot (NPC) + PlayerLootReceived (PvP), mirroring RuneLite's own LootTrackerPlugin
 * to avoid the ServerNpcLoot/NpcLootReceived double-fire. These tests exercise the emit + adapter logic
 * with real ItemStacks and mocked NPCComposition/Player; the events are fired by LootManager (a core
 * service) at runtime, which no unit test can stand in for.
 */
public class Wave4LootTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	@Test
	public void emitLootBuffersItemsAndSource() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		plugin.emitLoot("Goblin", "npc", Arrays.asList(new ItemStack(995, 40), new ItemStack(526, 1)));

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("loot", ev.get("type"));
		assertEquals("Goblin", ev.get("source_name"));
		assertEquals("npc", ev.get("source_type"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) ev.get("items");
		assertEquals("one kill's drops coalesce into one event", 2, items.size());
		assertEquals(995, items.get(0).get("id"));
		assertEquals(40, items.get(0).get("qty"));
		assertEquals(0L, ev.get("value")); // no ItemManager injected → value 0, still present
	}

	@Test
	public void emitLootValuesViaItemManager() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		ItemManager im = mock(ItemManager.class);
		when(im.getItemPrice(995)).thenReturn(1L);
		when(im.getItemPrice(560)).thenReturn(200L);
		inject(plugin, "itemManager", im);

		plugin.emitLoot("Vorkath", "npc", Arrays.asList(new ItemStack(995, 5000), new ItemStack(560, 100)));

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals(5000L + 200L * 100L, ev.get("value")); // 5000 + 20000 = 25000
	}

	@Test
	public void emitLootSkipsBlankStacksAndEmptyDrops() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());

		plugin.emitLoot("Goblin", "npc", Collections.emptyList());
		assertTrue("empty drop → no event", plugin.pendingEvents.isEmpty());

		plugin.emitLoot("Goblin", "npc", Arrays.asList(new ItemStack(-1, 5), new ItemStack(995, 0)));
		assertTrue("all-blank drop → no event", plugin.pendingEvents.isEmpty());

		plugin.emitLoot("Goblin", "npc", Arrays.asList(new ItemStack(-1, 5), new ItemStack(526, 3)));
		assertEquals(1, plugin.pendingEvents.size());
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) plugin.pendingEvents.get(0).get("items");
		assertEquals("only the real item survives", 1, items.size());
		assertEquals(526, items.get(0).get("id"));
	}

	@Test
	public void onServerNpcLootEmitsNpcLoot() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		NPCComposition comp = mock(NPCComposition.class);
		when(comp.getName()).thenReturn("Zulrah");
		ServerNpcLoot event = new ServerNpcLoot(comp, Collections.singletonList(new ItemStack(12934, 250)));

		plugin.onServerNpcLoot(event);

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("loot", ev.get("type"));
		assertEquals("npc", ev.get("source_type"));
		assertEquals("Zulrah", ev.get("source_name"));
	}

	@Test
	public void onPlayerLootWithholdsVictimName() throws Exception
	{
		// Compliance: capture the PvP loot ITEMS but never the killed player's name (product decision, TODO).
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Player victim = mock(Player.class);
		PlayerLootReceived event = new PlayerLootReceived(victim, Collections.singletonList(new ItemStack(11832, 1)));

		plugin.onPlayerLootReceived(event);

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("loot", ev.get("type"));
		assertEquals("player", ev.get("source_type"));
		assertFalse("victim name must NOT be sent", ev.containsKey("source_name"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) ev.get("items");
		assertEquals(11832, items.get(0).get("id"));
	}

	@Test
	public void lootGatedOnToken() throws Exception
	{
		// No token → activity log inactive → loot buffers nothing (same gate as every event).
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
});
		plugin.emitLoot("Goblin", "npc", Collections.singletonList(new ItemStack(995, 10)));
		assertTrue(plugin.pendingEvents.isEmpty());
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

